-- ---------------------------------------------------------------------
-- FUNCTION: alertas.check_partidas_vencidas()
-- ---------------------------------------------------------------------
CREATE FUNCTION alertas.check_partidas_vencidas() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'doc', 'iam', 'notification'
    AS $$
BEGIN
    -- OPEN: partidas past due and not yet closed
    INSERT INTO notification.notifications (
        user_id, title, body, tipo, categoria,
        objeto_tipo, objeto_id, payload
    )
    SELECT
        ur.user_id,
        'Partida vencida',
        'La partida #' || p.numero || ' (' || c.nombre || ') venció el '
            || TO_CHAR(p.fecha_acordada, 'DD/MM/YYYY') || ' sin ser despachada.',
        'alert',
        'partida_vencida',
        'partida',
        p.id,
        jsonb_build_object('partida_id', p.id, 'numero', p.numero, 'cliente', c.nombre, 'fecha_acordada', p.fecha_acordada)
    FROM mes.partida p
    JOIN tercero c ON c.id = p.tercero_id
    CROSS JOIN (
        SELECT ur.user_id
        FROM iam.user_rol ur
        JOIN iam.rol r ON r.id = ur.rol_id
        WHERE r.code = ANY(ARRAY['jefe_planta', 'compras'])
    ) ur
    WHERE p.fecha_acordada < now()
      AND p.estado_produccion NOT IN ('CERRADA', 'CANCELADA')
      AND p.fyh_elm IS NULL
      AND NOT EXISTS (
          SELECT 1 FROM notification.notifications n
          WHERE n.user_id     = ur.user_id
            AND n.categoria   = 'partida_vencida'
            AND n.objeto_tipo = 'partida'
            AND n.objeto_id   = p.id
            AND n.fyh_resuelta IS NULL
      )
    ON CONFLICT DO NOTHING;

    -- CLOSE: partidas that are now terminal or no longer overdue
    UPDATE notification.notifications
    SET fyh_resuelta = now()
    WHERE categoria   = 'partida_vencida'
      AND objeto_tipo = 'partida'
      AND fyh_resuelta IS NULL
      AND objeto_id IN (
          SELECT id FROM mes.partida
          WHERE estado_produccion IN ('CERRADA', 'CANCELADA')
             OR fecha_acordada >= now()
      );
END;
$$;


ALTER FUNCTION alertas.check_partidas_vencidas() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: alertas.check_rollos_sin_programar()
-- ---------------------------------------------------------------------
CREATE FUNCTION alertas.check_rollos_sin_programar() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'doc', 'mes', 'inventario', 'iam', 'notification'
    AS $$
BEGIN
    -- OPEN: entregas older than 5 days with at least one in-stock unassigned roll
    INSERT INTO notification.notifications (
        user_id, title, body, tipo, categoria,
        objeto_tipo, objeto_id, payload
    )
    SELECT
        ur.user_id,
        'Rollos sin programar',
        'La guía ' || gr.serie || '-' || gr.correlativo || ' de ' || t.nombre
            || ' lleva ' || (CURRENT_DATE - gr.fecha_emision::DATE)
            || ' días con rollos sin asignar a una orden de producción.',
        'alert',
        'rollo_sin_programar',
        'entrega',
        gr.id,
        jsonb_build_object(
            'entrega_id',  gr.id,
            'entrega_numero',       gr.serie || '-' || gr.correlativo,
            'tercero',           t.nombre,
            'dias_espera',       (CURRENT_DATE - gr.fecha_emision::DATE),
            'fecha_emision',     gr.fecha_emision
        )
    FROM doc.entrega gr
    JOIN doc.entrega_tipo grt ON grt.id = gr.entrega_tipo_id
    JOIN tercero t ON t.id = gr.tercero_id
    CROSS JOIN (
        SELECT ur.user_id
        FROM iam.user_rol ur
        JOIN iam.rol r ON r.id = ur.rol_id
        WHERE r.code = ANY(ARRAY['jefe_planta', 'supervisor_produccion'])
    ) ur
    WHERE grt.codigo = 'CLIENTE_ENVIO_PROCESO'
      AND gr.fecha_emision < CURRENT_DATE - 5
      AND EXISTS (
          -- at least one in-stock roll with no partida assigned
          SELECT 1
          FROM inventario.lote_rollo_detalle lrd
          JOIN inventario.lote l              ON l.id = lrd.lote_id AND l.fyh_elm IS NULL
          JOIN inventario.vw_stock_lotes sl   ON sl.lote_id = l.id
          LEFT JOIN mes.partida_componente pc ON pc.lote_id = l.id
          WHERE lrd.entrega_id = gr.id
            AND pc.lote_id IS NULL
      )
      AND NOT EXISTS (
          SELECT 1 FROM notification.notifications n
          WHERE n.user_id     = ur.user_id
            AND n.categoria   = 'rollo_sin_programar'
            AND n.objeto_tipo = 'entrega'
            AND n.objeto_id   = gr.id
            AND n.fyh_resuelta IS NULL
      )
    ON CONFLICT DO NOTHING;

    -- CLOSE: entregas that no longer have any in-stock unassigned rolls
    UPDATE notification.notifications n
    SET fyh_resuelta = now()
    WHERE n.categoria   = 'rollo_sin_programar'
      AND n.objeto_tipo = 'entrega'
      AND n.fyh_resuelta IS NULL
      AND NOT EXISTS (
          SELECT 1
          FROM inventario.lote_rollo_detalle lrd
          JOIN inventario.lote l              ON l.id = lrd.lote_id AND l.fyh_elm IS NULL
          JOIN inventario.vw_stock_lotes sl   ON sl.lote_id = l.id
          LEFT JOIN mes.partida_componente pc ON pc.lote_id = l.id
          WHERE lrd.entrega_id = n.objeto_id
            AND pc.lote_id IS NULL
      );
END;
$$;


ALTER FUNCTION alertas.check_rollos_sin_programar() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: alertas.check_stock_bajo()
-- ---------------------------------------------------------------------
CREATE FUNCTION alertas.check_stock_bajo() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'inventario', 'iam', 'notification'
    AS $$
BEGIN
    -- OPEN: items below their reorder point
    INSERT INTO notification.notifications (
        user_id, title, body, tipo, categoria,
        objeto_tipo, objeto_id, payload
    )
    WITH consumo_60d AS (
        SELECT
            im.item_id,
            SUM(im.cantidad) / 60.0 AS avg_daily
        FROM inventario.item_movimientos im
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE im.origen_ubicacion_id IS NOT NULL
          AND imt.categoria NOT IN ('PRODUCCION', 'TRANSFERENCIA')
          AND im.fecha_hora >= now() - interval '60 days'
        GROUP BY im.item_id
    ),
    actividad_90d AS (
        SELECT DISTINCT im.item_id
        FROM inventario.item_movimientos im
        WHERE im.fecha_hora >= now() - interval '90 days'
    ),
    stock_actual AS (
        SELECT item_id, COALESCE(cantidad_total, 0) AS cantidad
        -- vw_stock_items (quantity fact, no attribute/valuation joins): this
        -- flow only needs item_id + cantidad_total, and self-scopes to INSUMO.
        FROM inventario.vw_stock_items
    ),
    items_bajo AS (
        SELECT
            i.id                                                        AS item_id,
            i.nombre                                                    AS item_nombre,
            COALESCE(sa.cantidad, 0)                                    AS stock_actual,
            COALESCE(i.stock_minimo, COALESCE(c.avg_daily, 0) * 7)     AS reorder_point,
            un.codigo                                                   AS unidad
        FROM item i
        JOIN item_tipo it  ON it.id = i.item_tipo_id AND it.codigo = 'INSUMO'
        JOIN unidad un     ON un.id = i.unidad_id
        LEFT JOIN stock_actual  sa ON sa.item_id = i.id
        LEFT JOIN consumo_60d   c  ON c.item_id  = i.id
        LEFT JOIN actividad_90d a  ON a.item_id  = i.id
        WHERE i.fyh_elm IS NULL
          AND (i.stock_minimo IS NOT NULL OR a.item_id IS NOT NULL)
          AND COALESCE(sa.cantidad, 0) < COALESCE(i.stock_minimo, COALESCE(c.avg_daily, 0) * 7)
          AND COALESCE(i.stock_minimo, COALESCE(c.avg_daily, 0) * 7) > 0
    )
    SELECT
        ur.user_id,
        'Stock bajo: ' || ib.item_nombre,
        'El stock de ' || ib.item_nombre || ' (' || ib.stock_actual || ' ' || ib.unidad
            || ') está por debajo del punto de reorden (' || ROUND(ib.reorder_point, 2) || ' ' || ib.unidad || ').',
        'alert',
        'stock_bajo',
        'item',
        ib.item_id,
        jsonb_build_object(
            'item_id',       ib.item_id,
            'item_nombre',   ib.item_nombre,
            'stock_actual',  ib.stock_actual,
            'reorder_point', ROUND(ib.reorder_point, 2),
            'unidad',        ib.unidad
        )
    FROM items_bajo ib
    CROSS JOIN (
        SELECT ur.user_id
        FROM iam.user_rol ur
        JOIN iam.rol r ON r.id = ur.rol_id
        WHERE r.code = ANY(ARRAY['inventario', 'compras'])
    ) ur
    WHERE NOT EXISTS (
        SELECT 1 FROM notification.notifications n
        WHERE n.user_id     = ur.user_id
          AND n.categoria   = 'stock_bajo'
          AND n.objeto_tipo = 'item'
          AND n.objeto_id   = ib.item_id
          AND n.fyh_resuelta IS NULL
    )
    ON CONFLICT DO NOTHING;

    -- CLOSE: items that have recovered above their reorder point
    UPDATE notification.notifications n
    SET fyh_resuelta = now()
    WHERE n.categoria   = 'stock_bajo'
      AND n.objeto_tipo = 'item'
      AND n.fyh_resuelta IS NULL
      AND NOT EXISTS (
          WITH consumo_60d AS (
              SELECT im.item_id, SUM(im.cantidad) / 60.0 AS avg_daily
              FROM inventario.item_movimientos im
              JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
              WHERE im.origen_ubicacion_id IS NOT NULL
          AND imt.categoria NOT IN ('PRODUCCION', 'TRANSFERENCIA')
                AND im.fecha_hora >= now() - interval '60 days'
              GROUP BY im.item_id
          ),
          stock_actual AS (
              SELECT item_id, COALESCE(cantidad_total, 0) AS cantidad
              -- vw_stock_items (quantity fact, no attribute/valuation joins): this
              -- flow only needs item_id + cantidad_total, and self-scopes to INSUMO.
              FROM inventario.vw_stock_items
          )
          SELECT 1
          FROM item i
          LEFT JOIN stock_actual sa ON sa.item_id = i.id
          LEFT JOIN consumo_60d  c  ON c.item_id  = i.id
          WHERE i.id = n.objeto_id
            AND COALESCE(sa.cantidad, 0) < COALESCE(i.stock_minimo, COALESCE(c.avg_daily, 0) * 7)
      );
END;
$$;


ALTER FUNCTION alertas.check_stock_bajo() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: alertas.check_stock_pasos()
-- ---------------------------------------------------------------------
CREATE FUNCTION alertas.check_stock_pasos() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'inventario', 'mes', 'receta', 'iam', 'notification'
    AS $$
BEGIN
    -- OPEN: pasos whose recipe insumo demand exceeds available stock
    INSERT INTO notification.notifications (
        user_id, title, body, tipo, categoria,
        objeto_tipo, objeto_id, payload
    )
    WITH paso_demanda AS (
        SELECT
            pp.id                                                           AS paso_id,
            tpi.item_id,
            SUM(
                tpi.cantidad * pc.cantidad_reservada
                / CASE WHEN tpi.medida = 'pct' THEN 100.0 ELSE 1000.0 END
            )                                                               AS kg_demandado
        FROM mes.partida_paso pp
        JOIN mes.operacion op          ON op.id = pp.operacion_id AND op.requiere_receta = true
        JOIN mes.partida_componente pc ON pc.partida_id = pp.partida_id AND pc.lote_id IS NOT NULL
        JOIN receta.tenido rt          ON rt.id = pp.receta_id AND rt.flg_produccion = true
        JOIN receta.tenido_paso rtp    ON rtp.receta_id = rt.id
        JOIN receta.tenido_paso_insumo tpi ON tpi.paso_id = rtp.id
        WHERE NOT EXISTS (
            SELECT 1 FROM mes.partida_paso_ejecucion pe
            WHERE pe.partida_paso_id = pp.id AND pe.estado = 'COMPLETADO'
        )
        GROUP BY pp.id, tpi.item_id
    ),
    stock_disponible AS (
        SELECT item_id, COALESCE(cantidad_total, 0) AS cantidad
        -- vw_stock_items (quantity fact, no attribute/valuation joins): this
        -- flow only needs item_id + cantidad_total, and self-scopes to INSUMO.
        FROM inventario.vw_stock_items
    ),
    deficit AS (
        SELECT
            pd.paso_id,
            pd.item_id,
            i.nombre                         AS item_nombre,
            pd.kg_demandado,
            COALESCE(sd.cantidad, 0)         AS stock_actual,
            un.codigo                        AS unidad
        FROM paso_demanda pd
        JOIN item i           ON i.id  = pd.item_id
        JOIN unidad un        ON un.id = i.unidad_id
        LEFT JOIN stock_disponible sd ON sd.item_id = pd.item_id
        WHERE COALESCE(sd.cantidad, 0) < pd.kg_demandado
    )
    SELECT
        ur.user_id,
        'Stock insuficiente para paso',
        'El paso #' || d.paso_id || ' requiere ' || ROUND(d.kg_demandado, 2)
            || ' ' || d.unidad || ' de ' || d.item_nombre
            || ' pero solo hay ' || ROUND(d.stock_actual, 2) || ' ' || d.unidad || ' disponibles.',
        'alert',
        'stock_paso',
        'partida_paso',
        d.paso_id,
        jsonb_build_object(
            'paso_id',      d.paso_id,
            'item_id',      d.item_id,
            'item_nombre',  d.item_nombre,
            'kg_demandado', ROUND(d.kg_demandado, 2),
            'stock_actual', ROUND(d.stock_actual, 2),
            'unidad',       d.unidad
        )
    FROM deficit d
    CROSS JOIN (
        SELECT ur.user_id
        FROM iam.user_rol ur
        JOIN iam.rol r ON r.id = ur.rol_id
        WHERE r.code = ANY(ARRAY['jefe_planta', 'supervisor_produccion', 'inventario', 'compras'])
    ) ur
    WHERE NOT EXISTS (
        SELECT 1 FROM notification.notifications n
        WHERE n.user_id     = ur.user_id
          AND n.categoria   = 'stock_paso'
          AND n.objeto_tipo = 'partida_paso'
          AND n.objeto_id   = d.paso_id
          AND n.fyh_resuelta IS NULL
    )
    ON CONFLICT DO NOTHING;

    -- CLOSE: deficit cleared (stock recovered or paso completed)
    UPDATE notification.notifications n
    SET fyh_resuelta = now()
    WHERE n.categoria   = 'stock_paso'
      AND n.objeto_tipo = 'partida_paso'
      AND n.fyh_resuelta IS NULL
      AND NOT EXISTS (
          WITH paso_demanda AS (
              SELECT
                  pp.id                                            AS paso_id,
                  tpi.item_id,
                  SUM(
                      tpi.cantidad * pc.cantidad_reservada
                      / CASE WHEN tpi.medida = 'pct' THEN 100.0 ELSE 1000.0 END
                  )                                                AS kg_demandado
              FROM mes.partida_paso pp
              JOIN mes.operacion op          ON op.id = pp.operacion_id AND op.requiere_receta = true
              JOIN mes.partida_componente pc ON pc.partida_id = pp.partida_id AND pc.lote_id IS NOT NULL
              JOIN receta.tenido rt          ON rt.id = pp.receta_id AND rt.flg_produccion = true
              JOIN receta.tenido_paso rtp    ON rtp.receta_id = rt.id
              JOIN receta.tenido_paso_insumo tpi ON tpi.paso_id = rtp.id
              WHERE pp.id = n.objeto_id
                AND NOT EXISTS (
                    SELECT 1 FROM mes.partida_paso_ejecucion pe
                    WHERE pe.partida_paso_id = pp.id AND pe.estado = 'COMPLETADO'
                )
              GROUP BY pp.id, tpi.item_id
          ),
          stock_disponible AS (
              SELECT item_id, COALESCE(cantidad_total, 0) AS cantidad
              -- vw_stock_items (quantity fact, no attribute/valuation joins): this
              -- flow only needs item_id + cantidad_total, and self-scopes to INSUMO.
              FROM inventario.vw_stock_items
          )
          SELECT 1
          FROM paso_demanda pd
          LEFT JOIN stock_disponible sd ON sd.item_id = pd.item_id
          WHERE COALESCE(sd.cantidad, 0) < pd.kg_demandado
      );
END;
$$;


ALTER FUNCTION alertas.check_stock_pasos() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: audit.fn_audit_row()
-- ---------------------------------------------------------------------
CREATE FUNCTION audit.fn_audit_row() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'audit', 'public'
    AS $$
DECLARE
    v_id bigint;
BEGIN
    IF TG_TABLE_SCHEMA = 'audit' THEN
        RETURN COALESCE(NEW, OLD);
    END IF;
    v_id := COALESCE(NEW.id, OLD.id);
    INSERT INTO audit.data_audit (
        schema_name, table_name, row_id, operacion, old_data, new_data, usr_id
    )
    VALUES (
        TG_TABLE_SCHEMA,
        TG_TABLE_NAME,
        v_id,
        TG_OP,
        CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN to_jsonb(OLD) END,
        CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN to_jsonb(NEW) END,
        get_user_id()
    );
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION audit.fn_audit_row() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: calidad.anular_inspeccion(bigint, text)
-- ---------------------------------------------------------------------
CREATE FUNCTION calidad.anular_inspeccion(p_inspeccion_id bigint, p_motivo text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'calidad', 'inventario', 'mes'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id        int  := get_user_id();
    v_lote_id       int;
    v_resultado     calidad_estado_enum;
    v_nuevo_estado  calidad_estado_enum;
BEGIN
    IF NOT jwt_has_permission('calidad.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere calidad.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_motivo IS NULL OR trim(p_motivo) = '' THEN
        RAISE EXCEPTION 'Se requiere motivo para anular la inspección.';
    END IF;

    SELECT ci.lote_id, ci.resultado
    INTO   v_lote_id, v_resultado
    FROM   calidad.inspeccion ci
    WHERE  ci.id = p_inspeccion_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Inspección #% no encontrada.', p_inspeccion_id;
    END IF;

    -- Lote must still be alive, UNLESS it was soft-deleted by mes.anular_produccion
    -- reversing the very step that created it (PROD_ING_REV, no PROD_SCRAP). That case
    -- predates the guard added to anular_produccion that now blocks it going forward —
    -- this branch exists only to unblock inspections already orphaned that way. There is
    -- nothing to restore (the roll legitimately no longer exists); just drop the record.
    IF EXISTS (SELECT 1 FROM inventario.lote WHERE id = v_lote_id AND fyh_elm IS NOT NULL) THEN
        IF EXISTS (
            SELECT 1 FROM inventario.item_movimientos im
            JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
            WHERE im.lote_id = v_lote_id AND imt.codigo = 'PROD_SCRAP'
        ) THEN
            RAISE EXCEPTION
                'El lote #% ya fue dado de baja. Use calidad.revertir_baja_lote primero.', v_lote_id;
        END IF;
        -- else: lote was reversed via mes.anular_produccion — fall through and delete
        -- the orphaned inspection below.
    END IF;

    -- Guard: no dispatch or scrap movements
    IF EXISTS (
        SELECT 1 FROM inventario.item_movimientos im
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE im.lote_id = v_lote_id
          AND imt.codigo IN ('VENTA_EGR', 'SERV_EGR', 'PROD_SCRAP')
    ) THEN
        RAISE EXCEPTION
            'El lote #% ya fue despachado o dado de baja. No se puede anular la inspección.',
            v_lote_id;
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_inspeccion', v_usr_id,
            jsonb_build_object('inspeccion_id', p_inspeccion_id, 'lote_id', v_lote_id,
                               'resultado_original', v_resultado, 'motivo', p_motivo));

    -- Hard-delete in FK order: foto → defecto → inspeccion
    DELETE FROM calidad.inspeccion_foto
    WHERE inspeccion_defecto_id IN (
        SELECT id FROM calidad.inspeccion_defecto WHERE inspeccion_id = p_inspeccion_id
    );
    DELETE FROM calidad.inspeccion_defecto WHERE inspeccion_id = p_inspeccion_id;
    DELETE FROM calidad.inspeccion           WHERE id          = p_inspeccion_id;

    -- Reset estado_calidad to the latest remaining inspection or PENDIENTE
    SELECT ci2.resultado INTO v_nuevo_estado
    FROM   calidad.inspeccion ci2
    WHERE  ci2.lote_id = v_lote_id
    ORDER  BY ci2.fyh_cre DESC
    LIMIT  1;

    UPDATE inventario.lote
    SET estado_calidad = COALESCE(v_nuevo_estado, 'PENDIENTE')
    WHERE id = v_lote_id;

    RETURN format('Inspección #%s (resultado: %s) del lote #%s anulada. Estado_calidad restaurado a %s.',
                  p_inspeccion_id, v_resultado, v_lote_id,
                  COALESCE(v_nuevo_estado::text, 'PENDIENTE'));

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_inspeccion - User: %, Inspeccion: %, Error: %, Detail: %',
              v_usr_id, p_inspeccion_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION calidad.anular_inspeccion(p_inspeccion_id bigint, p_motivo text) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: calidad.bulk_anular_decision_calidad(integer[], text)
-- ---------------------------------------------------------------------
CREATE FUNCTION calidad.bulk_anular_decision_calidad(p_lote_ids integer[], p_motivo text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'calidad', 'inventario'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id        int     := get_user_id();
    v_lote_id       int;
    v_inspeccion_id bigint;
    v_success       jsonb   := '[]'::jsonb;
    v_failed        jsonb   := '[]'::jsonb;
    v_result_msg    text;
BEGIN
    IF NOT jwt_has_permission('calidad.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere calidad.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_motivo IS NULL OR trim(p_motivo) = '' THEN
        RAISE EXCEPTION 'Se requiere motivo para la anulación masiva.';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('bulk_anular_decision_calidad', v_usr_id,
            jsonb_build_object('lote_ids', p_lote_ids, 'motivo', p_motivo));

    FOREACH v_lote_id IN ARRAY p_lote_ids LOOP
        -- Most recent inspection for this lote
        SELECT ci.id INTO v_inspeccion_id
        FROM   calidad.inspeccion ci
        WHERE  ci.lote_id = v_lote_id
        ORDER  BY ci.fyh_cre DESC
        LIMIT  1;

        IF v_inspeccion_id IS NULL THEN
            v_failed := v_failed || jsonb_build_object(
                'lote_id', v_lote_id,
                'error', 'Sin inspección activa para este lote'
            );
            CONTINUE;
        END IF;

        BEGIN
            SELECT calidad.anular_inspeccion(v_inspeccion_id, p_motivo) INTO v_result_msg;
            v_success := v_success || jsonb_build_object(
                'lote_id',       v_lote_id,
                'inspeccion_id', v_inspeccion_id,
                'message',       v_result_msg
            );
        EXCEPTION WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT;
            v_failed := v_failed || jsonb_build_object(
                'lote_id',       v_lote_id,
                'inspeccion_id', v_inspeccion_id,
                'error',         v_message
            );
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'anulados', jsonb_array_length(v_success),
        'fallidos', jsonb_array_length(v_failed),
        'total',    jsonb_array_length(v_success) + jsonb_array_length(v_failed),
        'success',  v_success,
        'failed',   v_failed
    );

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in bulk_anular_decision_calidad - User: %, Lotes: %, Error: %, Detail: %',
              v_usr_id, p_lote_ids, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION calidad.bulk_anular_decision_calidad(p_lote_ids integer[], p_motivo text) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: calidad.bulk_aprobar_lotes(integer[], integer, text)
-- ---------------------------------------------------------------------
CREATE FUNCTION calidad.bulk_aprobar_lotes(p_lote_ids integer[], p_empleado_id integer DEFAULT NULL::integer, p_observacion text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'calidad', 'inventario', 'mes'
    AS $$
DECLARE
    v_message   text;
    v_detail    text;
    v_hint      text;
    v_context   text;
    v_sqlstate  text;
    v_usr_id    int := get_user_id();
    v_approved  int;
    v_results   jsonb;
BEGIN
    IF NOT jwt_has_permission('calidad.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere calidad.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('bulk_aprobar_lotes', v_usr_id,
            jsonb_build_object('lote_ids', p_lote_ids, 'empleado_id', p_empleado_id));

    WITH lotes_resueltos AS (
        -- Resolve ejecucion_id via the view — handles both output rolls
        -- (documento_tipo = 'partida_paso_ejecucion') and input rolls
        -- (ejecucion resolved via the active lateral join in the view).
        SELECT v.lote_id, v.partida_paso_ejecucion_id
        FROM calidad.vw_lotes_pendientes_inspeccion v
        WHERE v.lote_id = ANY(p_lote_ids)
    ),
    ins AS (
        INSERT INTO calidad.inspeccion (lote_id, partida_paso_ejecucion_id, resultado, observacion, empleado_id)
        SELECT lr.lote_id, lr.partida_paso_ejecucion_id, 'APROBADO', p_observacion, p_empleado_id
        FROM lotes_resueltos lr
        WHERE NOT EXISTS (
            SELECT 1 FROM calidad.inspeccion ci
            WHERE ci.lote_id                   = lr.lote_id
              AND ci.partida_paso_ejecucion_id = lr.partida_paso_ejecucion_id
        )
        RETURNING id AS inspeccion_id, lote_id
    ),
    upd AS (
        UPDATE inventario.lote
        SET estado_calidad = 'APROBADO'
        WHERE id IN (SELECT lote_id FROM ins)
    )
    SELECT COUNT(*)::int,
           jsonb_agg(jsonb_build_object('lote_id', lote_id, 'inspeccion_id', inspeccion_id))
    INTO v_approved, v_results
    FROM ins;

    IF v_approved > 0 THEN
        INSERT INTO notification.notifications(user_id, title, body, tipo, payload)
        SELECT ur.user_id,
               'Aprobación Masiva de Calidad',
               COALESCE(
                   (SELECT COALESCE(nombre, 'Usuario desconocido') || ' ' || apellido
                    FROM usuario WHERE id = v_usr_id),
                   'sistema'
               ) || ' aprobó ' || v_approved || ' rollo(s) en bloque',
               'info',
               jsonb_build_object('objeto_tipo', 'bulk_aprobacion', 'lote_ids', p_lote_ids)
        FROM iam.user_rol ur
        LEFT JOIN iam.rol r ON ur.rol_id = r.id
        WHERE r.code IN ('jefe_planta', 'calidad')
          AND v_usr_id <> ur.user_id;
    END IF;

    RETURN jsonb_build_object(
        'aprobados',  v_approved,
        'resultados', COALESCE(v_results, '[]'::jsonb)
    );

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;
        RAISE LOG 'Error in bulk_aprobar_lotes - User: %, Lotes: %, Error: %, Detail: %',
                  v_usr_id, p_lote_ids, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION calidad.bulk_aprobar_lotes(p_lote_ids integer[], p_empleado_id integer, p_observacion text) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: calidad.bulk_rechazar_lotes(integer[], public.calidad_estado_enum, text, integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION calidad.bulk_rechazar_lotes(p_lote_ids integer[], p_resultado public.calidad_estado_enum, p_observacion text, p_empleado_id integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'calidad', 'inventario', 'mes'
    AS $$
DECLARE
    v_message      text;
    v_detail       text;
    v_hint         text;
    v_context      text;
    v_sqlstate     text;
    v_usr_id       int := get_user_id();
    v_rechazados   int;
    v_results      jsonb;
    v_ineligibles  int[];
BEGIN
    IF NOT jwt_has_permission('calidad.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere calidad.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- Strict eligibility gate: raise if ANY supplied lote is not pending QC.
    SELECT ARRAY_AGG(u) INTO v_ineligibles
    FROM UNNEST(p_lote_ids) u
    WHERE NOT EXISTS (
        SELECT 1 FROM calidad.vw_lotes_pendientes_inspeccion v WHERE v.lote_id = u
    );

    IF v_ineligibles IS NOT NULL THEN
        RAISE EXCEPTION 'Lotes no elegibles para inspección: %. Deben estar pendientes de QC.',
            v_ineligibles;
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('bulk_rechazar_lotes', v_usr_id,
            jsonb_build_object('lote_ids', p_lote_ids, 'resultado', p_resultado, 'empleado_id', p_empleado_id));

    WITH lotes_resueltos AS (
        SELECT v.lote_id, v.partida_paso_ejecucion_id
        FROM calidad.vw_lotes_pendientes_inspeccion v
        WHERE v.lote_id = ANY(p_lote_ids)
    ),
    ins AS (
        INSERT INTO calidad.inspeccion (lote_id, partida_paso_ejecucion_id, resultado, observacion, empleado_id)
        SELECT lr.lote_id, lr.partida_paso_ejecucion_id, p_resultado, p_observacion, p_empleado_id
        FROM lotes_resueltos lr
        WHERE NOT EXISTS (
            SELECT 1 FROM calidad.inspeccion ci
            WHERE ci.lote_id                   = lr.lote_id
              AND ci.partida_paso_ejecucion_id = lr.partida_paso_ejecucion_id
        )
        RETURNING id AS inspeccion_id, lote_id
    ),
    upd AS (
        UPDATE inventario.lote
        SET estado_calidad = p_resultado
        WHERE id IN (SELECT lote_id FROM ins)
    )
    SELECT COUNT(*)::int,
           jsonb_agg(jsonb_build_object('lote_id', lote_id, 'inspeccion_id', inspeccion_id))
    INTO v_rechazados, v_results
    FROM ins;

    IF v_rechazados > 0 THEN
        INSERT INTO notification.notifications(user_id, title, body, tipo, payload)
        SELECT ur.user_id,
               'Rechazo Masivo de Calidad',
               COALESCE(
                   (SELECT COALESCE(nombre, 'Usuario desconocido') || ' ' || apellido
                    FROM usuario WHERE id = v_usr_id),
                   'sistema'
               ) || ' rechazó ' || v_rechazados || ' rollo(s) como ' || p_resultado,
               'warning',
               jsonb_build_object('objeto_tipo', 'bulk_rechazo', 'lote_ids', p_lote_ids, 'resultado', p_resultado)
        FROM iam.user_rol ur
        LEFT JOIN iam.rol r ON ur.rol_id = r.id
        WHERE r.code IN ('jefe_planta', 'calidad')
          AND v_usr_id <> ur.user_id;
    END IF;

    RETURN jsonb_build_object(
        'rechazados', v_rechazados,
        'resultados', COALESCE(v_results, '[]'::jsonb)
    );

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;
        RAISE LOG 'Error in bulk_rechazar_lotes - User: %, Lotes: %, Resultado: %, Error: %, Detail: %',
                  v_usr_id, p_lote_ids, p_resultado, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION calidad.bulk_rechazar_lotes(p_lote_ids integer[], p_resultado public.calidad_estado_enum, p_observacion text, p_empleado_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: calidad.crear_inspeccion(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION calidad.crear_inspeccion(p_inspeccion jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'calidad', 'inventario', 'mes'
    AS $$
DECLARE
    v_message   text;
    v_detail    text;
    v_hint      text;
    v_context   text;
    v_sqlstate  text;
    v_inspeccion_id BIGINT;
    v_usr_id        int  := get_user_id();
    v_lote_id       int  := (p_inspeccion->>'lote_id')::INT;
    v_ejecucion_id  BIGINT;
    v_es_output     BOOLEAN;
BEGIN
    IF NOT jwt_has_permission('calidad.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere calidad.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- Resolve lote type and ejecucion_id.
    -- Output rolls: auto-populate from lote.documento_id so the per-ejecucion
    -- view filter can detect this inspection even if the caller omits the field.
    -- Input rolls: caller must supply partida_paso_ejecucion_id explicitly.
    SELECT l.documento_tipo = 'partida_paso_ejecucion',
           COALESCE(
               (p_inspeccion->>'partida_paso_ejecucion_id')::BIGINT,
               CASE WHEN l.documento_tipo = 'partida_paso_ejecucion'
                    THEN l.documento_id::BIGINT END
           )
    INTO v_es_output, v_ejecucion_id
    FROM inventario.lote l
    WHERE l.id = v_lote_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Lote % no encontrado.', v_lote_id
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    -- Eligibility: output roll or input roll in a running partida
    IF NOT (
        v_es_output
        OR EXISTS (
            SELECT 1 FROM mes.partida_componente pc
            JOIN mes.partida p ON p.id = pc.partida_id
            WHERE pc.lote_id = v_lote_id AND p.estado_produccion = 'EN_PRODUCCION'
        )
    ) THEN
        RAISE EXCEPTION 'Lote % no está asociado a una partida activa.', v_lote_id
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    -- Input rolls must link to an active paso so the view filter works correctly
    IF NOT v_es_output AND v_ejecucion_id IS NULL THEN
        RAISE EXCEPTION 'Se requiere partida_paso_ejecucion_id para inspección de rollo de entrada.'
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    -- Input rolls: verify the lote is actually a component of the partida owning this ejecucion
    IF NOT v_es_output THEN
        IF NOT EXISTS (
            SELECT 1
            FROM mes.partida_componente pc2
            JOIN mes.partida_paso pp2        ON pp2.partida_id = pc2.partida_id
            JOIN mes.partida_paso_ejecucion ppe ON ppe.partida_paso_id = pp2.id
            WHERE pc2.lote_id = v_lote_id AND ppe.id = v_ejecucion_id
        ) THEN
            RAISE EXCEPTION 'Lote % no es componente de la partida en ejecución %.', v_lote_id, v_ejecucion_id
                USING ERRCODE = 'invalid_parameter_value';
        END IF;
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('crear_inspeccion', v_usr_id, p_inspeccion);

    -- Parent: inspeccion
    INSERT INTO calidad.inspeccion (lote_id, partida_paso_ejecucion_id, resultado, observacion, empleado_id)
    VALUES (
        v_lote_id,
        v_ejecucion_id,
        (p_inspeccion->>'resultado')::calidad_estado_enum,
        p_inspeccion->>'observacion',
        (p_inspeccion->>'empleado_id')::INT
    )
    RETURNING id INTO v_inspeccion_id;  
     
    -- Children: defectos + fotos (fotos nested inside each defecto in the JSON)
    WITH defectos_inserted AS (
        INSERT INTO calidad.inspeccion_defecto (inspeccion_id, tipo_defecto_id, cantidad, observacion)
        SELECT v_inspeccion_id,
               (d.value->>'tipo_defecto_id')::SMALLINT,
               COALESCE((d.value->>'cantidad')::SMALLINT, 1),
               d.value->>'observacion'
        FROM jsonb_array_elements(p_inspeccion->'defectos') WITH ORDINALITY AS d(value, ordinality)
        ORDER BY d.ordinality
        RETURNING id
    ),
    defectos_mapped AS (
        SELECT id, ROW_NUMBER() OVER (ORDER BY id) AS idx
        FROM defectos_inserted
    )
    INSERT INTO calidad.inspeccion_foto (inspeccion_defecto_id, ruta_archivo, etiqueta, observacion)
    SELECT dm.id,
           f->>'ruta_archivo',
           f->>'etiqueta',
           f->>'observacion'
    FROM jsonb_array_elements(p_inspeccion->'defectos') WITH ORDINALITY AS d(value, ordinality)
    JOIN defectos_mapped dm ON dm.idx = d.ordinality
    CROSS JOIN LATERAL jsonb_array_elements(d.value->'fotos') AS f;

    -- Update lote quality status
    UPDATE inventario.lote
    SET estado_calidad = (p_inspeccion->>'resultado')::calidad_estado_enum
    WHERE id = (p_inspeccion->>'lote_id')::INT;

    -- Notification
    INSERT INTO notification.notifications(user_id, title, body, tipo, payload)
    SELECT ur.user_id,
           'Nueva Inspección de Calidad',
           COALESCE((SELECT COALESCE(nombre,'Usuario desconocido') || ' ' || apellido
                     FROM usuario WHERE id = v_usr_id), 'sistema')
             || ' registró una inspección con resultado '
             || (p_inspeccion->>'resultado'),
           'info',
           jsonb_build_object('objeto_tipo','inspeccion','inspeccion_id', v_inspeccion_id)
    FROM iam.user_rol ur
    LEFT JOIN iam.rol r ON ur.rol_id = r.id
    WHERE r.code IN ('jefe_planta','calidad') AND v_usr_id <> ur.user_id;

       RETURN jsonb_build_object(
        'inspeccion_id', v_inspeccion_id,
        'defecto_ids', (
            SELECT jsonb_agg(id ORDER BY id)
            FROM calidad.inspeccion_defecto
            WHERE inspeccion_id = v_inspeccion_id
        ),
        'message', format('Inspección %s creada', v_inspeccion_id)
    );

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;
        RAISE LOG 'Error in crear_inspeccion - User: %, Params: %, Error: %, Detail: %',
                  v_usr_id, p_inspeccion::TEXT, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION calidad.crear_inspeccion(p_inspeccion jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: calidad.dar_de_baja_lote(integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION calidad.dar_de_baja_lote(p_lote_id integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'calidad', 'inventario', 'mes'
    AS $$
DECLARE
    v_message        text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id         int  := get_user_id();
    v_estado_calidad calidad_estado_enum;
    v_documento_tipo text;
    v_partida_id     bigint;
    v_scrap_tipo_id  smallint;
    v_doc_mov_id     bigint;
    v_ubicacion_id   int;
    v_item_id        int;
    v_cantidad       numeric;
BEGIN
    IF NOT jwt_has_permission('calidad.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere calidad.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- 1. Resolve lote
    SELECT l.estado_calidad, l.documento_tipo, l.item_id, l.cantidad
    INTO v_estado_calidad, v_documento_tipo, v_item_id, v_cantidad
    FROM inventario.lote l
    WHERE l.id = p_lote_id AND l.fyh_elm IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Lote % no encontrado o ya anulado.', p_lote_id;
    END IF;

    IF v_estado_calidad <> 'BAJA' THEN
        RAISE EXCEPTION
            'Lote % debe tener estado_calidad = BAJA para dar de baja. Estado actual: %.',
            p_lote_id, v_estado_calidad;
    END IF;

    IF v_documento_tipo <> 'partida_paso_ejecucion' THEN
        RAISE EXCEPTION
            'dar_de_baja_lote solo aplica a lotes de salida de producción (documento_tipo = partida_paso_ejecucion). Tipo actual: %.',
            v_documento_tipo;
    END IF;

    -- 2. Guard: no downstream movements beyond the original PROD_ING
    IF EXISTS (
        SELECT 1
        FROM inventario.item_movimientos im
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE im.lote_id   = p_lote_id
          AND imt.codigo NOT IN ('PROD_ING', 'PROD_ING_REV')
    ) THEN
        RAISE EXCEPTION
            'Lote % tiene movimientos posteriores (despacho, ajuste, etc.). Anule esos documentos antes de dar de baja.',
            p_lote_id;
    END IF;

    -- 3. Resolve partida for cantidad_producida recount
    SELECT pp.partida_id
    INTO v_partida_id
    FROM mes.partida_paso_ejecucion pe
    JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
    JOIN inventario.lote l   ON l.documento_id = pe.id AND l.documento_tipo = 'partida_paso_ejecucion'
    WHERE l.id = p_lote_id;

    -- 4. Lock
    PERFORM 1 FROM inventario.lote WHERE id = p_lote_id FOR UPDATE;

    -- 5. Post PROD_SCRAP movement
    SELECT id INTO v_scrap_tipo_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PROD_SCRAP';
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

    SELECT sa.ubicacion_id INTO v_ubicacion_id
    FROM inventario.vw_stock_lotes_ubicacion sa
    WHERE sa.lote_id = p_lote_id
    LIMIT 1;

    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        origen_ubicacion_id, cantidad, documento_tipo, documento_id
    )
    VALUES (
        v_doc_mov_id, v_item_id, p_lote_id, v_scrap_tipo_id,
        v_ubicacion_id, v_cantidad, 'calidad_baja', p_lote_id
    );

    -- 6. Soft-delete lote (lote_rollo_detalle kept for traceability)
    UPDATE inventario.lote
    SET fyh_elm = NOW(), usr_elm = v_usr_id
    WHERE id = p_lote_id;

    -- 7. Recount cantidad_producida (same pattern as registrar_produccion / anular_produccion)
    UPDATE mes.partida_detalle pd
    SET cantidad_producida = (
        SELECT COUNT(*)
        FROM inventario.lote l
        JOIN mes.partida_paso_ejecucion pe
            ON pe.id = l.documento_id AND l.documento_tipo = 'partida_paso_ejecucion'
        JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
        WHERE pp.partida_id = v_partida_id
          AND l.item_id     = pd.item_id
          AND l.fyh_elm     IS NULL
    ),
    usr_mod = v_usr_id,
    fyh_mod = NOW()
    WHERE pd.partida_id = v_partida_id;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('dar_de_baja_lote', v_usr_id, jsonb_build_object('lote_id', p_lote_id));

    RETURN format('Lote #%s dado de baja. Movimiento PROD_SCRAP registrado.', p_lote_id);

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;
        RAISE LOG 'Error in dar_de_baja_lote - User: %, Lote: %, Error: %, Detail: %',
                  v_usr_id, p_lote_id, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION calidad.dar_de_baja_lote(p_lote_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: calidad.get_inspeccion(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION calidad.get_inspeccion(p_inspeccion_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'calidad', 'inventario', 'mes'
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    SELECT jsonb_build_object(
        'id', i.id,
        'lote_id', i.lote_id,
        'partida_paso_ejecucion_id', i.partida_paso_ejecucion_id,
        'resultado', i.resultado,
        'observacion', i.observacion,
        'empleado_id', i.empleado_id,
        'empleado', e.nombre,
        'fyh_inspeccion', i.fyh_inspeccion,
        'fyh_cre', i.fyh_cre,

        'defectos', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', id2.id,
                'tipo_defecto_id', id2.tipo_defecto_id,
                'tipo_defecto_codigo', td.codigo,
                'tipo_defecto_nombre', td.nombre,
                'severidad', td.severidad,
                'cantidad', id2.cantidad,
                'observacion', id2.observacion,
                'fotos', COALESCE((
                    SELECT jsonb_agg(jsonb_build_object(
                        'id', f.id,
                        'ruta_archivo', f.ruta_archivo,
                        'etiqueta', f.etiqueta,
                        'observacion', f.observacion
                    ) ORDER BY f.id)
                    FROM calidad.inspeccion_foto f
                    WHERE f.inspeccion_defecto_id = id2.id
                ), '[]'::jsonb)
            ) ORDER BY td.severidad DESC, id2.id)
            FROM calidad.inspeccion_defecto id2
            JOIN calidad.tipo_defecto td ON td.id = id2.tipo_defecto_id
            WHERE id2.inspeccion_id = i.id
        ), '[]'::jsonb)
    )
    INTO v_result
    FROM calidad.inspeccion i
    LEFT JOIN mes.empleado e ON e.id = i.empleado_id
    WHERE i.id = p_inspeccion_id;

    RETURN v_result;
END;
$$;


ALTER FUNCTION calidad.get_inspeccion(p_inspeccion_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: calidad.get_lotes_pendientes_partida(bigint, boolean)
-- ---------------------------------------------------------------------
CREATE FUNCTION calidad.get_lotes_pendientes_partida(p_partida_id bigint, p_solo_output boolean DEFAULT false) RETURNS TABLE(lote_id integer, lote_codigo text, item_id integer, item_nombre text, item_codigo text, partida_paso_ejecucion_id bigint, operacion_id smallint, operacion_codigo text, maquina_id integer, maquina_codigo text, ancho text, peso numeric, fecha_creacion_lote timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'calidad', 'inventario', 'mes'
    AS $$
    -- p_solo_output: when true, restricts to finished output rolls (es_output) —
    -- for the "final QC" flow, so mid-process componente/input rolls from earlier
    -- pasos don't bleed into a screen meant to show only closure-step output.
    SELECT
        v.lote_id,
        v.lote_codigo,
        v.item_id,
        v.item_nombre,
        v.item_codigo,
        v.partida_paso_ejecucion_id,
        v.operacion_id,
        v.operacion_codigo,
        v.maquina_id,
        v.maquina_codigo,
        v.ancho,
        l.cantidad  AS peso,
        v.fecha_creacion_lote
    FROM calidad.vw_lotes_pendientes_inspeccion v
    JOIN inventario.lote l ON l.id = v.lote_id
    WHERE v.partida_id = p_partida_id
      AND (NOT p_solo_output OR v.es_output)
    ORDER BY v.partida_paso_ejecucion_id, v.fecha_creacion_lote;
$$;


ALTER FUNCTION calidad.get_lotes_pendientes_partida(p_partida_id bigint, p_solo_output boolean) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: calidad.revertir_baja_lote(integer, text)
-- ---------------------------------------------------------------------
CREATE FUNCTION calidad.revertir_baja_lote(p_lote_id integer, p_motivo text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'calidad', 'inventario', 'mes'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int     := get_user_id();
    v_item_id           int;
    v_cantidad          numeric;
    v_partida_id        bigint;
    v_ubicacion_id      int;
    v_scrap_rev_tipo_id smallint;
    v_doc_mov_id        bigint;
BEGIN
    IF NOT jwt_has_permission('calidad.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere calidad.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_motivo IS NULL OR trim(p_motivo) = '' THEN
        RAISE EXCEPTION 'Se requiere motivo para revertir la baja.';
    END IF;

    -- Lote must be soft-deleted
    SELECT l.item_id, l.cantidad
    INTO   v_item_id, v_cantidad
    FROM   inventario.lote l
    WHERE  l.id = p_lote_id AND l.fyh_elm IS NOT NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Lote % no encontrado o no está dado de baja (fyh_elm IS NULL).', p_lote_id;
    END IF;

    -- PROD_SCRAP must exist
    IF NOT EXISTS (
        SELECT 1 FROM inventario.item_movimientos im
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE im.lote_id = p_lote_id AND imt.codigo = 'PROD_SCRAP'
    ) THEN
        RAISE EXCEPTION 'Lote % no tiene movimiento PROD_SCRAP. No puede revertirse con esta función.', p_lote_id;
    END IF;

    -- Guard: no movements beyond PROD_ING / PROD_ING_REV / PROD_SCRAP
    IF EXISTS (
        SELECT 1 FROM inventario.item_movimientos im
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE im.lote_id = p_lote_id
          AND imt.codigo NOT IN ('PROD_ING', 'PROD_ING_REV', 'PROD_SCRAP')
    ) THEN
        RAISE EXCEPTION
            'Lote % tiene movimientos posteriores a la baja. Anule esos documentos primero.',
            p_lote_id;
    END IF;

    -- Resolve partida for cantidad_producida recount
    SELECT pp.partida_id INTO v_partida_id
    FROM   mes.partida_paso_ejecucion pe
    JOIN   mes.partida_paso pp ON pp.id = pe.partida_paso_id
    JOIN   inventario.lote l   ON l.documento_id = pe.id AND l.documento_tipo = 'partida_paso_ejecucion'
    WHERE  l.id = p_lote_id;

    -- Restore to the same location the PROD_SCRAP movement took from
    SELECT im.origen_ubicacion_id INTO v_ubicacion_id
    FROM   inventario.item_movimientos im
    JOIN   inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
    WHERE  im.lote_id = p_lote_id AND imt.codigo = 'PROD_SCRAP'
    LIMIT  1;

    SELECT id INTO v_scrap_rev_tipo_id
    FROM   inventario.item_movimiento_tipo WHERE codigo = 'PROD_SCRAP_REV';

    IF v_scrap_rev_tipo_id IS NULL THEN
        RAISE EXCEPTION 'Tipo PROD_SCRAP_REV no encontrado. Aplique migration/23_reversal_movement_types.sql primero.';
    END IF;

    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

    -- PROD_SCRAP_REV: ingress — restores roll to stock at its original location
    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        destino_ubicacion_id, cantidad, documento_tipo, documento_id
    )
    VALUES (
        v_doc_mov_id, v_item_id, p_lote_id, v_scrap_rev_tipo_id,
        v_ubicacion_id, v_cantidad, 'calidad_baja', p_lote_id
    );

    -- Un-delete lote
    UPDATE inventario.lote
    SET fyh_elm = NULL, usr_elm = NULL
    WHERE id = p_lote_id;

    -- Reset estado_calidad: inspection that condemned it still exists, so stay at BAJA
    UPDATE inventario.lote SET estado_calidad = 'BAJA' WHERE id = p_lote_id;

    -- Recount cantidad_producida (same pattern as registrar_produccion / anular_produccion)
    UPDATE mes.partida_detalle pd
    SET cantidad_producida = (
        SELECT COUNT(*)
        FROM   inventario.lote l2
        JOIN   mes.partida_paso_ejecucion pe2
                   ON pe2.id = l2.documento_id AND l2.documento_tipo = 'partida_paso_ejecucion'
        JOIN   mes.partida_paso pp2 ON pp2.id = pe2.partida_paso_id
        WHERE  pp2.partida_id = v_partida_id
          AND  l2.item_id     = pd.item_id
          AND  l2.fyh_elm     IS NULL
    ),
    usr_mod = v_usr_id,
    fyh_mod = NOW()
    WHERE pd.partida_id = v_partida_id;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('revertir_baja_lote', v_usr_id,
            jsonb_build_object('lote_id', p_lote_id, 'motivo', p_motivo));

    RETURN format('Baja del lote #%s revertida. Lote restaurado al inventario con estado_calidad BAJA.',
                  p_lote_id);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in revertir_baja_lote - User: %, Lote: %, Error: %, Detail: %',
              v_usr_id, p_lote_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION calidad.revertir_baja_lote(p_lote_id integer, p_motivo text) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.actualizar_compra(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.actualizar_compra(p_compra_id bigint, p_datos jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message   text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id    int := get_user_id();
    v_fyh_elm   timestamptz;
    v_tercero_id int;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('actualizar_compra', v_usr_id,
            jsonb_build_object('compra_id', p_compra_id) || p_datos);

    SELECT fyh_elm, tercero_id INTO v_fyh_elm, v_tercero_id
    FROM doc.compra WHERE id = p_compra_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Compra #% no encontrada.', p_compra_id;
    END IF;
    IF v_fyh_elm IS NOT NULL THEN
        RAISE EXCEPTION 'Compra #% ya está anulada.', p_compra_id;
    END IF;

    UPDATE doc.compra
    SET fecha       = COALESCE((p_datos->>'fecha')::DATE, fecha),
        observacion = p_datos->>'observacion',
        usr_mod     = v_usr_id,
        fyh_mod     = NOW()
    WHERE id = p_compra_id;

    -- Replace line items only when 'detalle' key is explicitly present.
    -- Diffed by item_id (frontend sends the full grid, no line ids) so that
    -- lines which persist keep their compra_detalle.id — and therefore keep
    -- entrega_detalle.compra_detalle_id (LIPS→EKPO) intact — instead of being
    -- dropped and recreated.
    IF p_datos ? 'detalle' THEN
        -- A line can only be removed if no *active* entrega is linked to it.
        -- entrega_detalle rows are never deleted (audit trail), so an
        -- anulada entrega must not keep blocking the line forever.
        IF EXISTS (
            SELECT 1
            FROM doc.compra_detalle cd
            WHERE cd.compra_id = p_compra_id
              AND NOT EXISTS (
                  SELECT 1 FROM jsonb_array_elements(p_datos->'detalle') d
                  WHERE (d->>'item_id')::INT = cd.item_id
              )
              AND EXISTS (
                  SELECT 1
                  FROM doc.entrega_detalle ed
                  JOIN doc.entrega e ON e.id = ed.entrega_id
                  WHERE ed.compra_detalle_id = cd.id
                    AND e.fyh_elm IS NULL
              )
        ) THEN
            RAISE EXCEPTION 'No se puede eliminar una línea con entregas ya vinculadas. Desvincule la entrega correspondiente primero.';
        END IF;

        -- Update lines that persist (same item_id) in place.
        UPDATE doc.compra_detalle cd
        SET cantidad        = (d->>'cantidad')::NUMERIC,
            precio_unitario = (d->>'precio_unitario')::NUMERIC
        FROM jsonb_array_elements(p_datos->'detalle') d
        WHERE cd.compra_id = p_compra_id
          AND cd.item_id = (d->>'item_id')::INT;

        -- Insert lines for newly added items.
        INSERT INTO doc.compra_detalle (compra_id, item_id, cantidad, precio_unitario, usr_cre)
        SELECT p_compra_id,
               (d->>'item_id')::INT,
               (d->>'cantidad')::NUMERIC,
               (d->>'precio_unitario')::NUMERIC,
               v_usr_id
        FROM jsonb_array_elements(p_datos->'detalle') d
        WHERE NOT EXISTS (
            SELECT 1 FROM doc.compra_detalle cd
            WHERE cd.compra_id = p_compra_id AND cd.item_id = (d->>'item_id')::INT
        );

        -- Clear stale EKPO links from anulada entregas before deleting — the guard
        -- above only allows the delete through when no *active* entrega remains,
        -- but the FK itself has no ON DELETE clause and would otherwise RESTRICT.
        UPDATE doc.entrega_detalle ed
        SET compra_detalle_id = NULL
        FROM doc.compra_detalle cd, doc.entrega e
        WHERE e.id = ed.entrega_id
          AND ed.compra_detalle_id = cd.id
          AND cd.compra_id = p_compra_id
          AND e.fyh_elm IS NOT NULL
          AND NOT EXISTS (
              SELECT 1 FROM jsonb_array_elements(p_datos->'detalle') d
              WHERE (d->>'item_id')::INT = cd.item_id
          );

        -- Delete lines the user removed (already confirmed above to be unlinked).
        DELETE FROM doc.compra_detalle cd
        WHERE cd.compra_id = p_compra_id
          AND NOT EXISTS (
              SELECT 1 FROM jsonb_array_elements(p_datos->'detalle') d
              WHERE (d->>'item_id')::INT = cd.item_id
          );
    END IF;

    -- Replace entrega links only when 'entrega_ids' key is explicitly present
    IF p_datos ? 'entrega_ids' THEN
        IF jsonb_array_length(p_datos->'entrega_ids') > 0 THEN
            IF EXISTS (
                SELECT 1 FROM doc.entrega
                WHERE id IN (SELECT jsonb_array_elements_text(p_datos->'entrega_ids')::bigint)
                  AND tercero_id IS DISTINCT FROM v_tercero_id
            ) THEN
                RAISE EXCEPTION 'Una o más guías no pertenecen al proveedor de la compra #%.', p_compra_id;
            END IF;
        END IF;

        DELETE FROM doc.compra_entrega WHERE compra_id = p_compra_id;

        IF jsonb_array_length(p_datos->'entrega_ids') > 0 THEN
            INSERT INTO doc.compra_entrega(compra_id, entrega_id)
            SELECT p_compra_id, jsonb_array_elements_text(p_datos->'entrega_ids')::bigint
            ON CONFLICT DO NOTHING;
        END IF;
    END IF;

    -- Replace factura links only when 'factura_ids' key is explicitly present
    IF p_datos ? 'factura_ids' THEN
        IF jsonb_array_length(p_datos->'factura_ids') > 0 THEN
            IF EXISTS (
                SELECT 1 FROM doc.factura_proveedor
                WHERE id IN (SELECT jsonb_array_elements_text(p_datos->'factura_ids')::bigint)
                  AND tercero_id IS DISTINCT FROM v_tercero_id
            ) THEN
                RAISE EXCEPTION 'Una o más facturas no pertenecen al proveedor de la compra #%.', p_compra_id;
            END IF;
        END IF;

        DELETE FROM doc.compra_factura_proveedor WHERE compra_id = p_compra_id;

        IF jsonb_array_length(p_datos->'factura_ids') > 0 THEN
            INSERT INTO doc.compra_factura_proveedor(compra_id, factura_proveedor_id, usr_cre)
            SELECT p_compra_id, jsonb_array_elements_text(p_datos->'factura_ids')::bigint, v_usr_id
            ON CONFLICT DO NOTHING;
        END IF;
    END IF;

    RETURN format('Compra #%s actualizada.', p_compra_id);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in actualizar_compra - User: %, compra: %, Error: %', v_usr_id, p_compra_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.actualizar_compra(p_compra_id bigint, p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.actualizar_entrega(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.actualizar_entrega(p_entrega_id bigint, p_datos jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_usr_id        INT  := get_user_id();
    v_entrega       RECORD;
    v_reversal_tipo SMALLINT;
    v_doc_mov_id    BIGINT;
    v_fecha_mov     TIMESTAMPTZ;
    v_linea_rec     RECORD;
    v_detalle_id    BIGINT;
    v_compra_id     BIGINT;
    v_compra_det_id BIGINT;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('actualizar_entrega', v_usr_id,
            jsonb_build_object('entrega_id', p_entrega_id, 'datos', p_datos));

    SELECT gr.id, gr.fyh_elm, gr.tercero_id,
           grt.flg_emitida, grt.codigo AS tipo_codigo,
           grt.item_movimiento_tipo_id
    INTO v_entrega
    FROM doc.entrega gr
    JOIN doc.entrega_tipo grt ON grt.id = gr.entrega_tipo_id
    WHERE gr.id = p_entrega_id
    FOR UPDATE OF gr;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Guía #% no encontrada.', p_entrega_id;
    END IF;
    IF v_entrega.fyh_elm IS NOT NULL THEN
        RAISE EXCEPTION 'Guía #% ya está anulada; no se puede editar.', p_entrega_id;
    END IF;
    IF v_entrega.flg_emitida THEN
        RAISE EXCEPTION
            'Guía #% es una guía de salida; use anular + crear para corregirla.',
            p_entrega_id
            USING HINT = 'actualizar_entrega sólo admite guías de entrada (flg_emitida = false).';
    END IF;

    -- Devolution tipos have dedicated anulación RPCs (funciones/devoluciones.sql)
    -- and no edit path — anular + re-registrar with the correct data instead.
    IF v_entrega.tipo_codigo IN ('DEVOLUCION_CLIENTE_SERVICIO', 'DEVOLUCION_CLIENTE_VENTA') THEN
        RAISE EXCEPTION 'Use doc.anular_devolucion_cliente para corregir esta devolución (%).', v_entrega.tipo_codigo;
    END IF;

    -- Block if any lote born from this entrega has downstream movements
    IF EXISTS (
        SELECT 1
        FROM inventario.lote l
        JOIN inventario.item_movimientos im ON im.lote_id = l.id
        WHERE l.documento_tipo = 'entrega'
          AND l.documento_id   = p_entrega_id
          AND l.fyh_elm        IS NULL
          AND NOT (im.documento_tipo = 'entrega' AND im.documento_id = p_entrega_id)
    ) THEN
        RAISE EXCEPTION
            'No se puede editar la guía #%: uno o más lotes ya tienen movimientos posteriores (producción, pesaje, redespacho).',
            p_entrega_id;
    END IF;

    -- ── Header update (only fields present in p_datos are touched) ──────────
    UPDATE doc.entrega SET
        serie           = CASE WHEN p_datos ? 'serie'
                               THEN p_datos->>'serie'
                               ELSE serie           END,
        correlativo     = CASE WHEN p_datos ? 'correlativo'
                               THEN p_datos->>'correlativo'
                               ELSE correlativo     END,
        fecha_emision   = CASE WHEN p_datos ? 'fecha_emision'
                               THEN (p_datos->>'fecha_emision')::TIMESTAMPTZ
                               ELSE fecha_emision   END,
        fecha_recepcion = CASE WHEN p_datos ? 'fecha_recepcion'
                               THEN (p_datos->>'fecha_recepcion')::TIMESTAMPTZ
                               ELSE fecha_recepcion END,
        tercero_id      = CASE WHEN p_datos ? 'tercero_id'
                               THEN (p_datos->>'tercero_id')::INT
                               ELSE tercero_id      END,
        usr_mod         = v_usr_id,
        fyh_mod         = NOW()
    WHERE id = p_entrega_id;

    -- ── Line replacement (only when "items" key is supplied) ────────────────
    IF p_datos ? 'items' THEN

        -- Resolve the PO this entrega is linked to (if any), so replacement
        -- lines can keep the EKPO link and cantidad_recibida can be resynced.
        SELECT ce.compra_id INTO v_compra_id
        FROM doc.compra_entrega ce WHERE ce.entrega_id = p_entrega_id LIMIT 1;

        -- Resolve the paired reversal movement tipo (same table as anular_entrega)
        SELECT imt2.id INTO v_reversal_tipo
        FROM inventario.item_movimiento_tipo imt1
        JOIN inventario.item_movimiento_tipo imt2
          ON imt2.codigo = CASE imt1.codigo
              WHEN 'COMPRA_ING' THEN 'DEV_PROV_EGR'
              WHEN 'SERV_ING'   THEN 'DEV_CLI_EGR'
              WHEN 'SERV_EGR'   THEN 'SERV_DEV_ING'
              WHEN 'VENTA_EGR'  THEN 'DEV_CLI_ING'
              ELSE NULL END
        WHERE imt1.id = v_entrega.item_movimiento_tipo_id;

        IF v_reversal_tipo IS NULL THEN
            RAISE EXCEPTION
                'Guía #%: no existe tipo de movimiento de reversal para "%". Contactar administrador.',
                p_entrega_id, v_entrega.tipo_codigo;
        END IF;

        -- Post counter-movements for all original movements
        SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id,
            item_movimiento_tipo_id,
            origen_ubicacion_id, destino_ubicacion_id,
            cantidad, fecha_hora,
            documento_tipo, documento_id, observacion
        )
        SELECT
            v_doc_mov_id, im.item_id, im.lote_id,
            v_reversal_tipo,
            im.destino_ubicacion_id,  -- swap: was destination, now origin
            im.origen_ubicacion_id,   -- swap: was origin, now destination
            im.cantidad, NOW(),
            'entrega', p_entrega_id,
            'EDICION guía #' || p_entrega_id
        FROM inventario.item_movimientos im
        WHERE im.documento_tipo = 'entrega'
          AND im.documento_id   = p_entrega_id;

        -- Soft-delete lotes that were created by this entrega
        UPDATE inventario.lote
        SET usr_elm = v_usr_id, fyh_elm = NOW()
        WHERE documento_tipo = 'entrega'
          AND documento_id   = p_entrega_id
          AND fyh_elm        IS NULL;

        -- Drop old detalle lines
        DELETE FROM doc.entrega_detalle WHERE entrega_id = p_entrega_id;

        -- New doc_mov_id for the incoming replacement movements
        SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

        v_fecha_mov := COALESCE(
            (p_datos->>'fecha_recepcion')::TIMESTAMPTZ,
            NOW()
        );

        -- (a) New-roll lines (lote_id absent): create lotes + lrd + movements
        FOR v_linea_rec IN
            SELECT
                COALESCE((item->>'linea')::SMALLINT, idx::SMALLINT) AS linea,
                (item->>'item_id')::INT                             AS item_id,
                (item->>'ubicacion_id')::INT                        AS ubicacion_id,
                (item->>'cantidad')::NUMERIC                        AS cantidad,
                COALESCE((item->>'cantidad_rollos')::INT, 1)        AS cantidad_rollos,
                (item->>'compra_detalle_id')::BIGINT                AS compra_detalle_id_explicit
            FROM jsonb_array_elements(p_datos->'items') WITH ORDINALITY AS t(item, idx)
            WHERE item->>'lote_id' IS NULL
        LOOP
            -- Resolve EKPO link: explicit from payload, or auto-match by item_id
            -- (mirrors doc.registrar_entrega_compra) so the corrected line keeps
            -- counting toward the PO instead of going silently unlinked.
            v_compra_det_id := v_linea_rec.compra_detalle_id_explicit;
            IF v_compra_det_id IS NULL AND v_compra_id IS NOT NULL THEN
                SELECT id INTO v_compra_det_id
                FROM doc.compra_detalle
                WHERE compra_id = v_compra_id AND item_id = v_linea_rec.item_id
                ORDER BY id LIMIT 1;
            END IF;

            INSERT INTO doc.entrega_detalle (entrega_id, linea, item_id, cantidad, n_rollos, compra_detalle_id)
            VALUES (p_entrega_id, v_linea_rec.linea, v_linea_rec.item_id,
                    v_linea_rec.cantidad, v_linea_rec.cantidad_rollos, v_compra_det_id)
            RETURNING id INTO v_detalle_id;

            WITH nuevos_lotes AS (
                INSERT INTO inventario.lote (
                    item_id, documento_tipo, documento_id,
                    cantidad, propietario_id, usr_cre
                )
                SELECT
                    v_linea_rec.item_id, 'entrega', p_entrega_id,
                    COALESCE(
                        v_linea_rec.cantidad / NULLIF(v_linea_rec.cantidad_rollos, 0),
                        v_linea_rec.cantidad
                    ),
                    (p_datos->>'propietario_id')::INT,
                    v_usr_id
                FROM generate_series(1, v_linea_rec.cantidad_rollos)
                RETURNING id, item_id, cantidad
            ),
            lrd_rows AS (
                INSERT INTO inventario.lote_rollo_detalle (lote_id, entrega_id, flg_tenido)
                SELECT nl.id, p_entrega_id, false
                FROM nuevos_lotes nl
                JOIN item      i  ON i.id  = nl.item_id
                JOIN item_tipo it ON it.id = i.item_tipo_id AND it.codigo = 'ROLLO'
            )
            INSERT INTO inventario.item_movimientos (
                doc_movimiento_id, item_id, lote_id,
                item_movimiento_tipo_id,
                origen_ubicacion_id, destino_ubicacion_id,
                cantidad, fecha_hora,
                documento_tipo, documento_id, documento_linea_id, usr_cre
            )
            SELECT
                v_doc_mov_id, nl.item_id, nl.id,
                v_entrega.item_movimiento_tipo_id,
                NULL,
                COALESCE((p_datos->>'destino_ubicacion_id')::INT, v_linea_rec.ubicacion_id),
                nl.cantidad, v_fecha_mov,
                'entrega', p_entrega_id, v_detalle_id, v_usr_id
            FROM nuevos_lotes nl;
        END LOOP;

        -- (b) Devolution lines (lote_id present): move existing lotes back in
        WITH items AS (
            SELECT
                COALESCE((item->>'linea')::SMALLINT, idx::SMALLINT) AS linea,
                (item->>'item_id')::INT                             AS item_id,
                (item->>'cantidad')::NUMERIC(12,4)                  AS cantidad,
                (item->>'lote_id')::INT                             AS lote_id,
                (item->>'ubicacion_id')::INT                        AS ubicacion_id,
                COALESCE(
                    (item->>'compra_detalle_id')::BIGINT,
                    (SELECT cd.id FROM doc.compra_detalle cd
                     WHERE cd.compra_id = v_compra_id AND cd.item_id = (item->>'item_id')::INT
                     ORDER BY cd.id LIMIT 1)
                ) AS compra_detalle_id
            FROM jsonb_array_elements(p_datos->'items') WITH ORDINALITY AS t(item, idx)
            WHERE item->>'lote_id' IS NOT NULL
        ),
        det AS (
            INSERT INTO doc.entrega_detalle
                (entrega_id, linea, item_id, cantidad, lote_id, ubicacion_id, compra_detalle_id)
            SELECT p_entrega_id, linea, item_id, cantidad, lote_id, ubicacion_id, compra_detalle_id
            FROM items
            RETURNING id, linea
        )
        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id,
            item_movimiento_tipo_id,
            destino_ubicacion_id,
            cantidad, fecha_hora,
            documento_tipo, documento_id, documento_linea_id
        )
        SELECT
            v_doc_mov_id, i.item_id, i.lote_id,
            v_entrega.item_movimiento_tipo_id,
            i.ubicacion_id,
            i.cantidad, v_fecha_mov,
            'entrega', p_entrega_id, d.id
        FROM items i
        JOIN det d ON d.linea = i.linea;

        -- Resync compra_detalle.cantidad_recibida against the movements just posted
        IF v_compra_id IS NOT NULL THEN
            PERFORM doc.fn_refresh_compra_detalle_qtys(v_compra_id);
        END IF;

    END IF; -- items replacement

    RETURN format('Guía #%s actualizada correctamente.', p_entrega_id);
EXCEPTION WHEN OTHERS THEN
    RAISE LOG 'Error in actualizar_entrega - User: %, entrega: %, Error: %',
        v_usr_id, p_entrega_id, SQLERRM;
    RAISE;
END;
$$;


ALTER FUNCTION doc.actualizar_entrega(p_entrega_id bigint, p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.actualizar_factura_proveedor(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.actualizar_factura_proveedor(p_factura_id bigint, p_datos jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id      int := get_user_id();
    v_estado_pago estado_pago_enum;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('actualizar_factura_proveedor', v_usr_id,
            jsonb_build_object('factura_id', p_factura_id) || p_datos);

    SELECT estado_pago INTO v_estado_pago
    FROM doc.factura_proveedor WHERE id = p_factura_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Factura #% no encontrada.', p_factura_id;
    END IF;
    IF v_estado_pago = 'anulado' THEN
        RAISE EXCEPTION 'Factura #% ya está anulada.', p_factura_id;
    END IF;
    IF v_estado_pago = 'total' THEN
        RAISE EXCEPTION 'Factura #% ya está completamente pagada y no puede modificarse.', p_factura_id;
    END IF;

    -- Validate subtotal + igv ≈ total
    IF ABS(
        (p_datos->>'total')::NUMERIC -
        (COALESCE((p_datos->>'subtotal')::NUMERIC, 0) +
         COALESCE((p_datos->>'igv')::NUMERIC, 0))
    ) > 0.01 THEN
        RAISE EXCEPTION 'Total (%) no coincide con subtotal + IGV (% + % = %)',
            p_datos->>'total',
            p_datos->>'subtotal',
            p_datos->>'igv',
            COALESCE((p_datos->>'subtotal')::NUMERIC, 0) +
            COALESCE((p_datos->>'igv')::NUMERIC, 0);
    END IF;

    -- tipo_cambio required for USD
    IF COALESCE(p_datos->>'moneda', 'USD') = 'USD'
       AND (p_datos->>'tipo_cambio') IS NULL THEN
        RAISE EXCEPTION 'Se requiere tipo_cambio para facturas en USD.';
    END IF;

    UPDATE doc.factura_proveedor
    SET
        serie             = p_datos->>'serie',
        numero            = (p_datos->>'numero')::INT,
        fecha_emision     = (p_datos->>'fecha_emision')::DATE,
        fecha_vencimiento = (p_datos->>'fecha_vencimiento')::DATE,
        tipo_pago         = COALESCE((p_datos->>'tipo_pago')::tipo_pago_enum, tipo_pago),
        moneda            = COALESCE(p_datos->>'moneda', moneda),
        tipo_cambio       = (p_datos->>'tipo_cambio')::NUMERIC,
        subtotal          = (p_datos->>'subtotal')::NUMERIC,
        igv               = COALESCE((p_datos->>'igv')::NUMERIC, 0),
        total             = (p_datos->>'total')::NUMERIC,
        observacion       = p_datos->>'observacion',
        usr_mod           = v_usr_id,
        fyh_mod           = NOW()
    WHERE id = p_factura_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Factura #% no encontrada.', p_factura_id;
    END IF;

    -- Replace line items only when 'lineas' key is explicitly present
    IF p_datos ? 'lineas' THEN
        -- Block if any letra is already paid (covers parcial estado_pago)
        IF EXISTS (
            SELECT 1 FROM doc.letra_factura lf
            JOIN doc.letra l ON l.id = lf.letra_id
            WHERE lf.factura_proveedor_id = p_factura_id
              AND l.estado = 'pagada'
        ) THEN
            RAISE EXCEPTION 'No se pueden modificar las líneas de la factura #%: tiene letras pagadas vinculadas.', p_factura_id;
        END IF;

        DELETE FROM doc.factura_proveedor_detalle
        WHERE factura_proveedor_id = p_factura_id;

        IF jsonb_array_length(p_datos->'lineas') > 0 THEN
            INSERT INTO doc.factura_proveedor_detalle(
                factura_proveedor_id, item_id, cantidad,
                precio_unitario, igv_porcentaje, usr_cre
            )
            SELECT
                p_factura_id,
                (l->>'item_id')::INT,
                (l->>'cantidad')::NUMERIC,
                (l->>'precio_unitario')::NUMERIC,
                COALESCE((l->>'igv_porcentaje')::NUMERIC, 18),
                v_usr_id
            FROM jsonb_array_elements(p_datos->'lineas') l;
        END IF;
    END IF;

    RETURN format('Factura #%s actualizada.', p_factura_id);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in actualizar_factura_proveedor - User: %, factura: %, Error: %',
        v_usr_id, p_factura_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.actualizar_factura_proveedor(p_factura_id bigint, p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.actualizar_orden_servicio(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.actualizar_orden_servicio(p_os_id bigint, p_orden jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_usr_id     INT := get_user_id();
    v_existing   RECORD;
    v_linea      jsonb;
    v_recibida   INT;
    v_cur_item   INT;
    v_cur_color  INT;
    v_cur_tenido INT;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('actualizar_orden_servicio', v_usr_id,
            jsonb_build_object('os_id', p_os_id, 'orden', p_orden));

    IF NOT EXISTS (SELECT 1 FROM doc.orden_servicio WHERE id = p_os_id AND flg_elm = false) THEN
        RAISE EXCEPTION 'orden_servicio % no existe o fue eliminada.', p_os_id;
    END IF;

    -- ── Header ───────────────────────────────────────────────────
    UPDATE doc.orden_servicio SET
        tercero_id      = COALESCE((p_orden->>'tercero_id')::INT, tercero_id),
        serie           = COALESCE(p_orden->>'serie', serie),
        correlativo     = COALESCE((p_orden->>'correlativo')::INT, correlativo),
        flg_antipilling = COALESCE((p_orden->>'flg_antipilling')::BOOLEAN, flg_antipilling),
        flg_urgente     = COALESCE((p_orden->>'flg_urgente')::BOOLEAN, flg_urgente),
        fecha_entrega   = CASE WHEN p_orden ? 'fecha_entrega' THEN (p_orden->>'fecha_entrega')::DATE ELSE fecha_entrega END,
        rendimiento     = CASE WHEN p_orden ? 'rendimiento'   THEN p_orden->>'rendimiento'           ELSE rendimiento   END,
        ancho           = CASE WHEN p_orden ? 'ancho'         THEN p_orden->>'ancho'                 ELSE ancho         END,
        observacion     = CASE WHEN p_orden ? 'observacion'   THEN p_orden->>'observacion'           ELSE observacion   END,
        referencia_hilo = CASE WHEN p_orden ? 'referencia_hilo' THEN p_orden->>'referencia_hilo'     ELSE referencia_hilo END
    WHERE id = p_os_id;

    -- ── Lines (optional reconcile) ───────────────────────────────
    IF p_orden ? 'lineas' THEN
        -- Deletions: existing lines absent from the payload.
        FOR v_existing IN
            SELECT id, cantidad_recibida
            FROM doc.orden_servicio_detalle
            WHERE orden_servicio_id = p_os_id
        LOOP
            IF NOT EXISTS (
                SELECT 1 FROM jsonb_array_elements(p_orden->'lineas') l
                WHERE (l->>'id')::BIGINT = v_existing.id
            ) THEN
                IF v_existing.cantidad_recibida > 0 THEN
                    RAISE EXCEPTION 'No se puede eliminar la línea %: tiene % rollos recibidos. Revierta la recepción primero.',
                        v_existing.id, v_existing.cantidad_recibida;
                END IF;
                DELETE FROM doc.orden_servicio_detalle WHERE id = v_existing.id;
            END IF;
        END LOOP;

        -- Upserts
        FOR v_linea IN SELECT jsonb_array_elements(p_orden->'lineas')
        LOOP
            IF (v_linea ? 'id') AND (v_linea->>'id') IS NOT NULL THEN
                SELECT cantidad_recibida, item_id, color_x_cliente_id, tenido_id
                INTO v_recibida, v_cur_item, v_cur_color, v_cur_tenido
                FROM doc.orden_servicio_detalle
                WHERE id = (v_linea->>'id')::BIGINT AND orden_servicio_id = p_os_id;
                IF NOT FOUND THEN
                    RAISE EXCEPTION 'La línea % no pertenece a la orden_servicio %.', (v_linea->>'id'), p_os_id;
                END IF;

                IF (v_linea->>'cantidad')::INT < v_recibida THEN
                    RAISE EXCEPTION 'Línea %: la cantidad ordenada (%) no puede ser menor a la recibida (%).',
                        (v_linea->>'id'), (v_linea->>'cantidad')::INT, v_recibida;
                END IF;

                IF v_recibida > 0 AND (
                       (v_linea->>'item_id')::INT            IS DISTINCT FROM v_cur_item
                    OR (v_linea->>'color_x_cliente_id')::INT IS DISTINCT FROM v_cur_color
                    OR (v_linea->>'tenido_id')::INT          IS DISTINCT FROM v_cur_tenido
                ) THEN
                    RAISE EXCEPTION 'Línea %: no se puede cambiar item/color/teñido con rollos ya recibidos.', (v_linea->>'id');
                END IF;

                UPDATE doc.orden_servicio_detalle SET
                    linea              = COALESCE((v_linea->>'linea')::SMALLINT, linea),
                    item_id            = (v_linea->>'item_id')::INT,
                    malla              = v_linea->>'malla',
                    cantidad           = (v_linea->>'cantidad')::INT,
                    color_x_cliente_id = (v_linea->>'color_x_cliente_id')::INT,
                    tenido_id          = (v_linea->>'tenido_id')::INT,
                    flg_doble_bolsa    = COALESCE((v_linea->>'flg_doble_bolsa')::BOOLEAN, false)
                WHERE id = (v_linea->>'id')::BIGINT;
            ELSE
                INSERT INTO doc.orden_servicio_detalle (
                    orden_servicio_id, linea, item_id, malla,
                    cantidad, color_x_cliente_id, tenido_id, flg_doble_bolsa
                ) VALUES (
                    p_os_id,
                    COALESCE((v_linea->>'linea')::SMALLINT, 1),
                    (v_linea->>'item_id')::INT,
                    v_linea->>'malla',
                    (v_linea->>'cantidad')::INT,
                    (v_linea->>'color_x_cliente_id')::INT,
                    (v_linea->>'tenido_id')::INT,
                    COALESCE((v_linea->>'flg_doble_bolsa')::BOOLEAN, false)
                );
            END IF;
        END LOOP;
    END IF;

    RETURN format('Orden de servicio %s actualizada.', p_os_id);
EXCEPTION
    WHEN OTHERS THEN
        RAISE LOG 'Error in actualizar_orden_servicio - User: %, os: %, Error: %',
                  v_usr_id, p_os_id, SQLERRM;
        RAISE;
END;
$$;


ALTER FUNCTION doc.actualizar_orden_servicio(p_os_id bigint, p_orden jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.actualizar_referencia_entrega(bigint, text, text, date)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.actualizar_referencia_entrega(p_entrega_id bigint, p_serie text, p_correlativo text, p_fecha date DEFAULT NULL::date) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id   int := get_user_id();
    v_tipo     text;
    v_existing text;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('actualizar_referencia_entrega', v_usr_id,
            jsonb_build_object('entrega_id', p_entrega_id,
                               'serie', p_serie, 'correlativo', p_correlativo));

    SELECT et.codigo, e.correlativo
    INTO v_tipo, v_existing
    FROM doc.entrega e
    JOIN doc.entrega_tipo et ON et.id = e.entrega_tipo_id
    WHERE e.id = p_entrega_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Entrega #% no encontrada.', p_entrega_id;
    END IF;
    IF v_tipo <> 'COMPRA_INGRESO' THEN
        RAISE EXCEPTION 'Entrega #% no es de tipo COMPRA_INGRESO (es %).', p_entrega_id, v_tipo;
    END IF;
    IF v_existing IS NOT NULL THEN
        RAISE EXCEPTION 'Entrega #% ya tiene referencia (%). Use otra función para correcciones contables.', p_entrega_id, v_existing;
    END IF;
    IF p_correlativo IS NULL OR p_correlativo = '' THEN
        RAISE EXCEPTION 'correlativo es requerido.';
    END IF;

    UPDATE doc.entrega
    SET serie          = NULLIF(p_serie, ''),
        correlativo    = p_correlativo,
        fecha_emision  = COALESCE(p_fecha::timestamptz, fecha_emision)
    WHERE id = p_entrega_id;

    RETURN format('Entrega #%s actualizada con referencia %s-%s.',
                  p_entrega_id, p_serie, p_correlativo);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in actualizar_referencia_entrega - User: %, entrega: %, Error: %',
        v_usr_id, p_entrega_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.actualizar_referencia_entrega(p_entrega_id bigint, p_serie text, p_correlativo text, p_fecha date) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.anular_compra(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.anular_compra(p_compra_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id int := get_user_id();
    v_found  boolean;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_compra', v_usr_id, jsonb_build_object('compra_id', p_compra_id));

    SELECT (fyh_elm IS NOT NULL) INTO v_found
    FROM doc.compra WHERE id = p_compra_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Compra #% no encontrada.', p_compra_id;
    END IF;
    IF v_found THEN
        RAISE EXCEPTION 'Compra #% ya está anulada.', p_compra_id;
    END IF;

    -- Block if any linked factura is still active
    IF EXISTS (
        SELECT 1
        FROM doc.compra_factura_proveedor cfp
        JOIN doc.factura_proveedor fp ON fp.id = cfp.factura_proveedor_id
        WHERE cfp.compra_id = p_compra_id
          AND fp.estado_pago <> 'anulado'
    ) THEN
        RAISE EXCEPTION 'No se puede anular la compra #%: tiene facturas activas vinculadas. Anule primero las facturas.', p_compra_id;
    END IF;

    UPDATE doc.compra
    SET usr_elm = v_usr_id, fyh_elm = NOW()
    WHERE id = p_compra_id;

    RETURN format('Compra #%s anulada.', p_compra_id);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_compra - User: %, compra: %, Error: %', v_usr_id, p_compra_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.anular_compra(p_compra_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.anular_devolucion_cliente(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.anular_devolucion_cliente(p_entrega_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id        int := get_user_id();
    v_entrega       RECORD;
    v_reversal_tipo SMALLINT;
    v_doc_mov_id    BIGINT;
    v_mov_count     INT;
    v_error_payload jsonb;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT gr.id, gr.fyh_elm, grt.codigo AS tipo_codigo
    INTO v_entrega
    FROM doc.entrega gr
    JOIN doc.entrega_tipo grt ON grt.id = gr.entrega_tipo_id
    WHERE gr.id = p_entrega_id
    FOR UPDATE OF gr;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Guía #% no encontrada.', p_entrega_id;
    END IF;
    IF v_entrega.tipo_codigo NOT IN ('DEVOLUCION_CLIENTE_SERVICIO', 'DEVOLUCION_CLIENTE_VENTA') THEN
        RAISE EXCEPTION 'Guía #% no es una devolución de cliente (tipo %); use doc.anular_entrega.',
            p_entrega_id, v_entrega.tipo_codigo;
    END IF;
    IF v_entrega.fyh_elm IS NOT NULL THEN
        RAISE EXCEPTION 'Guía #% ya está anulada.', p_entrega_id;
    END IF;

    -- Guard: lote must not have moved again since this devolución was posted
    SELECT jsonb_agg(jsonb_build_object('lote_id', ei.lote_id))
    INTO v_error_payload
    FROM (
        SELECT DISTINCT im.lote_id, im.id
        FROM inventario.item_movimientos im
        WHERE im.documento_tipo = 'entrega' AND im.documento_id = p_entrega_id
    ) ei
    WHERE EXISTS (
        SELECT 1 FROM inventario.item_movimientos im2
        WHERE im2.lote_id = ei.lote_id
          AND im2.id > ei.id
          AND NOT (im2.documento_tipo = 'entrega' AND im2.documento_id = p_entrega_id)
    );

    IF v_error_payload IS NOT NULL THEN
        RAISE EXCEPTION 'No se puede anular la devolución #%: uno o más rollos devueltos ya tienen movimientos posteriores.', p_entrega_id
            USING DETAIL = v_error_payload::text;
    END IF;

    SELECT id INTO v_reversal_tipo
    FROM inventario.item_movimiento_tipo
    WHERE codigo = CASE v_entrega.tipo_codigo
        WHEN 'DEVOLUCION_CLIENTE_VENTA'    THEN 'DEV_CLI_ING_REV'
        WHEN 'DEVOLUCION_CLIENTE_SERVICIO' THEN 'SERV_DEV_ING_REV'
    END;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_devolucion_cliente', v_usr_id, jsonb_build_object('entrega_id', p_entrega_id));

    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        origen_ubicacion_id, destino_ubicacion_id,
        cantidad, fecha_hora, documento_tipo, documento_id, observacion)
    SELECT
        v_doc_mov_id, im.item_id, im.lote_id, v_reversal_tipo,
        im.destino_ubicacion_id, im.origen_ubicacion_id,   -- swap
        im.cantidad, NOW(), 'entrega', p_entrega_id,
        'ANULACION devolución #' || p_entrega_id
    FROM inventario.item_movimientos im
    WHERE im.documento_tipo = 'entrega' AND im.documento_id = p_entrega_id;

    GET DIAGNOSTICS v_mov_count = ROW_COUNT;

    UPDATE doc.entrega SET usr_elm = v_usr_id, fyh_elm = NOW() WHERE id = p_entrega_id;

    -- Fulfillment cache: undoing a return re-dispatches the rolls — refresh.
    PERFORM doc.recompute_estado_comercial(root.root_id)
    FROM (
        SELECT DISTINCT COALESCE(p.partida_origen_id, p.id) AS root_id
        FROM doc.entrega_detalle ed
        JOIN inventario.lote l ON l.id = ed.lote_id
        JOIN mes.partida_paso_ejecucion pe ON pe.id = l.documento_id AND l.documento_tipo = 'partida_paso_ejecucion'
        JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
        JOIN mes.partida p ON p.id = pp.partida_id
        WHERE ed.entrega_id = p_entrega_id
    ) root;

    RETURN format('Devolución #%s anulada. %s movimiento(s) revertido(s).', p_entrega_id, v_mov_count);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
        v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT,
        v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_devolucion_cliente - User: %, entrega: %, Error: %',
        v_usr_id, p_entrega_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.anular_devolucion_cliente(p_entrega_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.anular_devolucion_crudo_cliente(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.anular_devolucion_crudo_cliente(p_entrega_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id        int := get_user_id();
    v_entrega       RECORD;
    v_reversal_tipo SMALLINT;
    v_doc_mov_id    BIGINT;
    v_mov_count     INT;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT gr.id, gr.fyh_elm, grt.codigo AS tipo_codigo
    INTO v_entrega
    FROM doc.entrega gr
    JOIN doc.entrega_tipo grt ON grt.id = gr.entrega_tipo_id
    WHERE gr.id = p_entrega_id
    FOR UPDATE OF gr;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Guía #% no encontrada.', p_entrega_id;
    END IF;
    IF v_entrega.tipo_codigo <> 'DEVOLUCION_CLIENTE_CRUDO' THEN
        RAISE EXCEPTION 'Guía #% no es una devolución de crudo a cliente (tipo %); use doc.anular_entrega.',
            p_entrega_id, v_entrega.tipo_codigo;
    END IF;
    IF v_entrega.fyh_elm IS NOT NULL THEN
        RAISE EXCEPTION 'Guía #% ya está anulada.', p_entrega_id;
    END IF;

    SELECT id INTO v_reversal_tipo FROM inventario.item_movimiento_tipo WHERE codigo = 'DEV_CLI_EGR_REV';

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_devolucion_crudo_cliente', v_usr_id, jsonb_build_object('entrega_id', p_entrega_id));

    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        origen_ubicacion_id, destino_ubicacion_id,
        cantidad, fecha_hora, documento_tipo, documento_id, observacion)
    SELECT
        v_doc_mov_id, im.item_id, im.lote_id, v_reversal_tipo,
        im.destino_ubicacion_id, im.origen_ubicacion_id,   -- swap
        im.cantidad, NOW(), 'entrega', p_entrega_id,
        'ANULACION devolución #' || p_entrega_id
    FROM inventario.item_movimientos im
    WHERE im.documento_tipo = 'entrega' AND im.documento_id = p_entrega_id;

    GET DIAGNOSTICS v_mov_count = ROW_COUNT;

    UPDATE doc.entrega SET usr_elm = v_usr_id, fyh_elm = NOW() WHERE id = p_entrega_id;

    -- Fulfillment cache: undoing a crudo return re-dispatches the rolls — refresh.
    PERFORM doc.recompute_estado_comercial(root.root_id)
    FROM (
        SELECT DISTINCT COALESCE(p.partida_origen_id, p.id) AS root_id
        FROM doc.entrega_detalle ed
        JOIN inventario.lote l ON l.id = ed.lote_id
        JOIN mes.partida_paso_ejecucion pe ON pe.id = l.documento_id AND l.documento_tipo = 'partida_paso_ejecucion'
        JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
        JOIN mes.partida p ON p.id = pp.partida_id
        WHERE ed.entrega_id = p_entrega_id
    ) root;

    RETURN format('Devolución #%s anulada. %s movimiento(s) revertido(s).', p_entrega_id, v_mov_count);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
        v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT,
        v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_devolucion_crudo_cliente - User: %, entrega: %, Error: %',
        v_usr_id, p_entrega_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.anular_devolucion_crudo_cliente(p_entrega_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.anular_devolucion_proveedor(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.anular_devolucion_proveedor(p_entrega_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id        int := get_user_id();
    v_entrega       RECORD;
    v_reversal_tipo SMALLINT;
    v_doc_mov_id    BIGINT;
    v_mov_count     INT;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT gr.id, gr.fyh_elm, grt.codigo AS tipo_codigo
    INTO v_entrega
    FROM doc.entrega gr
    JOIN doc.entrega_tipo grt ON grt.id = gr.entrega_tipo_id
    WHERE gr.id = p_entrega_id
    FOR UPDATE OF gr;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Guía #% no encontrada.', p_entrega_id;
    END IF;
    IF v_entrega.tipo_codigo <> 'DEVOLUCION_PROVEEDOR' THEN
        RAISE EXCEPTION 'Guía #% no es una devolución a proveedor (tipo %); use doc.anular_entrega.',
            p_entrega_id, v_entrega.tipo_codigo;
    END IF;
    IF v_entrega.fyh_elm IS NOT NULL THEN
        RAISE EXCEPTION 'Guía #% ya está anulada.', p_entrega_id;
    END IF;

    SELECT id INTO v_reversal_tipo FROM inventario.item_movimiento_tipo WHERE codigo = 'DEV_PROV_EGR_REV';

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_devolucion_proveedor', v_usr_id, jsonb_build_object('entrega_id', p_entrega_id));

    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        origen_ubicacion_id, destino_ubicacion_id,
        cantidad, fecha_hora, documento_tipo, documento_id, observacion)
    SELECT
        v_doc_mov_id, im.item_id, im.lote_id, v_reversal_tipo,
        im.destino_ubicacion_id, im.origen_ubicacion_id,   -- swap
        im.cantidad, NOW(), 'entrega', p_entrega_id,
        'ANULACION devolución #' || p_entrega_id
    FROM inventario.item_movimientos im
    WHERE im.documento_tipo = 'entrega' AND im.documento_id = p_entrega_id;

    GET DIAGNOSTICS v_mov_count = ROW_COUNT;

    UPDATE doc.entrega SET usr_elm = v_usr_id, fyh_elm = NOW() WHERE id = p_entrega_id;

    RETURN format('Devolución #%s anulada. %s movimiento(s) revertido(s).', p_entrega_id, v_mov_count);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
        v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT,
        v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_devolucion_proveedor - User: %, entrega: %, Error: %',
        v_usr_id, p_entrega_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.anular_devolucion_proveedor(p_entrega_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.anular_entrega(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.anular_entrega(p_entrega_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'doc', 'inventario', 'public'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id          int := get_user_id();
    v_entrega            RECORD;
    v_reversal_tipo   SMALLINT;
    v_doc_mov_id      BIGINT;
    v_mov_count       INT;
    v_lote_count      INT;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_entrega', v_usr_id, jsonb_build_object('entrega_id', p_entrega_id));

    SELECT gr.id, gr.fyh_elm, grt.flg_emitida, grt.codigo AS tipo_codigo,
           grt.item_movimiento_tipo_id
    INTO v_entrega
    FROM doc.entrega gr
    JOIN doc.entrega_tipo grt ON grt.id = gr.entrega_tipo_id
    WHERE gr.id = p_entrega_id
    FOR UPDATE OF gr;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Guía #% no encontrada.', p_entrega_id;
    END IF;
    IF v_entrega.fyh_elm IS NOT NULL THEN
        RAISE EXCEPTION 'Guía #% ya está anulada.', p_entrega_id;
    END IF;

    -- Devolution tipos have dedicated anulación RPCs (funciones/devoluciones.sql):
    -- their forward movement codes are real business events, not anulación
    -- scaffolding, so they reverse via dedicated *_REV codes, not this
    -- function's generic CASE map.
    IF v_entrega.tipo_codigo IN ('DEVOLUCION_CLIENTE_SERVICIO', 'DEVOLUCION_CLIENTE_VENTA') THEN
        RAISE EXCEPTION 'Use doc.anular_devolucion_cliente para anular esta devolución (%).', v_entrega.tipo_codigo;
    END IF;
    IF v_entrega.tipo_codigo = 'DEVOLUCION_CLIENTE_CRUDO' THEN
        RAISE EXCEPTION 'Use doc.anular_devolucion_crudo_cliente para anular esta devolución.';
    END IF;
    IF v_entrega.tipo_codigo = 'DEVOLUCION_PROVEEDOR' THEN
        RAISE EXCEPTION 'Use doc.anular_devolucion_proveedor para anular esta devolución.';
    END IF;

    -- ── Outbound guard: block if any active client invoice references this entrega
    IF v_entrega.flg_emitida THEN
        IF EXISTS (
            SELECT 1
            FROM doc.factura_detalle fd
            JOIN doc.factura f ON f.id = fd.factura_id AND f.estado <> 'anulada'
            WHERE fd.entrega_id = p_entrega_id
        ) THEN
            RAISE EXCEPTION
                'No se puede anular la guía #%: está referenciada en facturas activas. Anule primero las facturas.',
                p_entrega_id;
        END IF;
    END IF;

    -- ── Inbound guard: block if any created lote has downstream movements.
    -- PESAJE_POS/PESAJE_NEG are excluded here: pesaje-domain movements are
    -- never deleted (audit-trail convention), so old/reversed pesaje history
    -- would otherwise block forever. Active (unreversed) pesaje is caught by
    -- the dedicated guard below instead.
    IF NOT v_entrega.flg_emitida THEN
        IF EXISTS (
            SELECT 1
            FROM inventario.lote l
            JOIN inventario.item_movimientos im ON im.lote_id = l.id
            JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
            WHERE l.documento_tipo = 'entrega'
              AND l.documento_id   = p_entrega_id
              AND l.fyh_elm        IS NULL
              -- Any movement NOT from this entrega means the lote was used downstream
              AND NOT (im.documento_tipo = 'entrega' AND im.documento_id = p_entrega_id)
              AND imt.codigo NOT IN ('PESAJE_POS', 'PESAJE_NEG')
        ) THEN
            RAISE EXCEPTION
                'No se puede anular la guía #%: uno o más lotes recibidos ya tienen movimientos posteriores (consumo, producción o redespacho).',
                p_entrega_id;
        END IF;
    END IF;

    -- ── Inbound guard: block if any created lote still has an active
    -- (unreversed) pesaje record — must run inventario.anular_pesaje first.
    IF NOT v_entrega.flg_emitida THEN
        IF EXISTS (
            SELECT 1
            FROM inventario.lote l
            JOIN inventario.pesaje ps ON ps.lote_id = l.id
            WHERE l.documento_tipo = 'entrega'
              AND l.documento_id   = p_entrega_id
              AND l.fyh_elm        IS NULL
        ) THEN
            RAISE EXCEPTION
                'No se puede anular la guía #%: uno o más lotes recibidos tienen pesaje activo. Anule el pesaje (inventario.anular_pesaje) primero.',
                p_entrega_id;
        END IF;
    END IF;

    -- ── Inbound guard: block if any created lote is still reserved on an active partida
    IF NOT v_entrega.flg_emitida THEN
        IF EXISTS (
            SELECT 1
            FROM inventario.lote l
            JOIN mes.partida_componente pc ON pc.lote_id = l.id
            JOIN mes.partida pr             ON pr.id      = pc.partida_id
            WHERE l.documento_tipo = 'entrega'
              AND l.documento_id   = p_entrega_id
              AND l.fyh_elm        IS NULL
              AND pr.estado_produccion NOT IN ('CANCELADA', 'TECO', 'CERRADA')
        ) THEN
            RAISE EXCEPTION
                'No se puede anular la guía #%: uno o más rollos recibidos están reservados en una partida activa. Anule la partida (mes.anular_partida) antes de anular la guía.',
                p_entrega_id;
        END IF;
    END IF;

    -- ── Resolve reversal movement tipo
    SELECT imt2.id INTO v_reversal_tipo
    FROM inventario.item_movimiento_tipo imt1
    JOIN inventario.item_movimiento_tipo imt2 ON imt2.codigo = CASE imt1.codigo
        WHEN 'COMPRA_ING' THEN 'DEV_PROV_EGR'
        WHEN 'SERV_ING'   THEN 'DEV_CLI_EGR'
        WHEN 'SERV_EGR'   THEN 'SERV_DEV_ING'
        WHEN 'VENTA_EGR'  THEN 'DEV_CLI_ING'
        ELSE NULL
    END
    WHERE imt1.id = v_entrega.item_movimiento_tipo_id;

    IF v_reversal_tipo IS NULL THEN
        RAISE EXCEPTION
            'Guía #%: no existe tipo de movimiento de reversal para el tipo de guía "%". Contactar administrador.',
            p_entrega_id, v_entrega.tipo_codigo;
    END IF;

    -- ── Shared doc_movimiento_id for all reversal movements
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

    -- ── Post reversal movements (swaps origen_ubicacion_id ↔ destino_ubicacion_id)
    INSERT INTO inventario.item_movimientos (
        doc_movimiento_id,
        item_id, lote_id,
        item_movimiento_tipo_id,
        origen_ubicacion_id,
        destino_ubicacion_id,
        cantidad, fecha_hora,
        documento_tipo, documento_id,
        observacion
    )
    SELECT
        v_doc_mov_id,
        im.item_id, im.lote_id,
        v_reversal_tipo,
        im.destino_ubicacion_id,   -- swap: destination becomes the new origin
        im.origen_ubicacion_id,    -- swap: origin becomes the new destination
        im.cantidad,
        NOW(),
        'entrega',
        p_entrega_id,
        'ANULACION guía #' || p_entrega_id
    FROM inventario.item_movimientos im
    WHERE im.documento_tipo = 'entrega'
      AND im.documento_id   = p_entrega_id;

    GET DIAGNOSTICS v_mov_count = ROW_COUNT;

    -- ── For inbound entregas: retire the lotes that were created by this entrega
    IF NOT v_entrega.flg_emitida THEN
        UPDATE inventario.lote
        SET usr_elm = v_usr_id, fyh_elm = NOW()
        WHERE documento_tipo = 'entrega'
          AND documento_id   = p_entrega_id
          AND fyh_elm        IS NULL;

        GET DIAGNOSTICS v_lote_count = ROW_COUNT;
    END IF;

    -- ── Mark entrega as cancelled
    UPDATE doc.entrega
    SET usr_elm = v_usr_id, fyh_elm = NOW()
    WHERE id = p_entrega_id;

    -- Resync compra_detalle.cantidad_recibida if this entrega is linked to a PO
    -- (no-op if unlinked — fn_refresh_compra_detalle_qtys nets the DEV_PROV_EGR
    -- reversal just posted above against the original COMPRA_ING).
    PERFORM doc.fn_refresh_compra_detalle_qtys(ce.compra_id)
    FROM doc.compra_entrega ce
    WHERE ce.entrega_id = p_entrega_id;

    -- Fulfillment cache: undoing an outbound (dispatch) entrega un-dispatches its rolls;
    -- for inbound entregas this join simply finds no rows (harmless no-op).
    -- See doc.recompute_estado_comercial's closed call-site list.
    PERFORM doc.recompute_estado_comercial(root.root_id)
    FROM (
        SELECT DISTINCT COALESCE(p.partida_origen_id, p.id) AS root_id
        FROM doc.entrega_detalle ed
        JOIN inventario.lote l ON l.id = ed.lote_id
        JOIN mes.partida_paso_ejecucion pe ON pe.id = l.documento_id AND l.documento_tipo = 'partida_paso_ejecucion'
        JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
        JOIN mes.partida p ON p.id = pp.partida_id
        WHERE ed.entrega_id = p_entrega_id
    ) root;

    RETURN format('Guía #%s anulada. %s movimiento(s) revertido(s)%s.',
        p_entrega_id,
        v_mov_count,
        CASE WHEN NOT v_entrega.flg_emitida THEN format(', %s lote(s) dado(s) de baja', v_lote_count) ELSE '' END
    );
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_entrega - User: %, entrega: %, Error: %',
        v_usr_id, p_entrega_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.anular_entrega(p_entrega_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.anular_factura_cliente(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.anular_factura_cliente(p_factura_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'doc', 'mes', 'public'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id     INT := get_user_id();
    v_estado     factura_estado_enum;
    v_partidas   BIGINT[];
    v_reverted   INT;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_factura_cliente', v_usr_id, jsonb_build_object('factura_id', p_factura_id));

    SELECT estado INTO v_estado
    FROM doc.factura WHERE id = p_factura_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Factura #% no encontrada.', p_factura_id;
    END IF;
    IF v_estado = 'anulada' THEN
        RAISE EXCEPTION 'Factura #% ya está anulada.', p_factura_id;
    END IF;

    -- Block voiding an invoice that still has active customer payments.
    IF EXISTS (
        SELECT 1
        FROM doc.cobro_factura cf
        JOIN doc.cobro c ON c.id = cf.cobro_id
        WHERE cf.factura_id = p_factura_id
          AND c.estado = 'registrado'
    ) THEN
        RAISE EXCEPTION 'No se puede anular la factura #%: tiene cobros activos aplicados. Anule primero los cobros.', p_factura_id;
    END IF;

    -- Collect partidas referenced by this invoice before cancelling
    SELECT ARRAY(
        SELECT DISTINCT partida_id
        FROM doc.factura_detalle
        WHERE factura_id = p_factura_id AND partida_id IS NOT NULL
    ) INTO v_partidas;

    UPDATE doc.factura
    SET estado = 'anulada', estado_pago = 'anulado', usr_mod = v_usr_id, fyh_mod = NOW()
    WHERE id = p_factura_id;

    -- Revert 'facturado' partidas that now have pending weight again.
    -- vw_pendientes_facturacion excludes anulada invoices, so after the
    -- UPDATE above it reflects the true unbilled state.
    UPDATE mes.partida p
    SET estado_facturacion = 'pendiente',
        usr_mod = v_usr_id,
        fyh_mod = NOW()
    WHERE p.id = ANY(v_partidas)
      AND p.estado_facturacion = 'facturado'
      AND (
          EXISTS (SELECT 1 FROM doc.vw_pendientes_facturacion vpf WHERE vpf.partida_id = p.id)
          OR EXISTS (SELECT 1 FROM doc.vw_aprobados_sin_despacho vas WHERE vas.partida_id = p.id)
      );

    GET DIAGNOSTICS v_reverted = ROW_COUNT;

    RETURN format('Factura #%s anulada. %s partida(s) revertida(s) a pendiente.',
        p_factura_id, v_reverted);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_factura_cliente - User: %, factura: %, Error: %', v_usr_id, p_factura_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.anular_factura_cliente(p_factura_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.anular_factura_proveedor(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.anular_factura_proveedor(p_factura_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id     int := get_user_id();
    v_estado_pago estado_pago_enum;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_factura_proveedor', v_usr_id, jsonb_build_object('factura_id', p_factura_id));

    SELECT estado_pago INTO v_estado_pago
    FROM doc.factura_proveedor WHERE id = p_factura_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Factura #% no encontrada.', p_factura_id;
    END IF;
    IF v_estado_pago = 'anulado' THEN
        RAISE EXCEPTION 'Factura #% ya está anulada.', p_factura_id;
    END IF;

    -- Block if any letra that cleared this invoice is already paid
    IF EXISTS (
        SELECT 1
        FROM doc.letra_factura lf
        JOIN doc.letra l ON l.id = lf.letra_id
        WHERE lf.factura_proveedor_id = p_factura_id
          AND l.estado = 'pagada'
    ) THEN
        RAISE EXCEPTION 'No se puede anular la factura #%: tiene letras pagadas vinculadas. Revisar con contabilidad.', p_factura_id;
    END IF;

    UPDATE doc.factura_proveedor
    SET estado_pago = 'anulado', usr_mod = v_usr_id, fyh_mod = NOW()
    WHERE id = p_factura_id;

    RETURN format('Factura proveedor #%s anulada.', p_factura_id);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_factura_proveedor - User: %, factura: %, Error: %', v_usr_id, p_factura_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.anular_factura_proveedor(p_factura_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.anular_guia_remision(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.anular_guia_remision(p_guia_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'doc', 'inventario', 'public'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id          int := get_user_id();
    v_guia            RECORD;
    v_reversal_tipo   SMALLINT;
    v_doc_mov_id      BIGINT;
    v_mov_count       INT;
    v_lote_count      INT;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_guia_remision', v_usr_id, jsonb_build_object('guia_id', p_guia_id));

    SELECT gr.id, gr.fyh_elm, grt.flg_emitida, grt.codigo AS tipo_codigo,
           grt.item_movimiento_tipo_id
    INTO v_guia
    FROM doc.guia_remision gr
    JOIN doc.guia_remision_tipo grt ON grt.id = gr.guia_remision_tipo_id
    WHERE gr.id = p_guia_id
    FOR UPDATE OF gr;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Guía #% no encontrada.', p_guia_id;
    END IF;
    IF v_guia.fyh_elm IS NOT NULL THEN
        RAISE EXCEPTION 'Guía #% ya está anulada.', p_guia_id;
    END IF;

    -- ── Outbound guard: block if any active client invoice references this guia
    IF v_guia.flg_emitida THEN
        IF EXISTS (
            SELECT 1
            FROM doc.factura_detalle fd
            JOIN doc.factura f ON f.id = fd.factura_id AND f.estado <> 'anulada'
            WHERE fd.guia_remision_id = p_guia_id
        ) THEN
            RAISE EXCEPTION
                'No se puede anular la guía #%: está referenciada en facturas activas. Anule primero las facturas.',
                p_guia_id;
        END IF;
    END IF;

    -- ── Inbound guard: block if any created lote has downstream movements
    IF NOT v_guia.flg_emitida THEN
        IF EXISTS (
            SELECT 1
            FROM inventario.lote l
            JOIN inventario.item_movimientos im ON im.lote_id = l.id
            WHERE l.documento_tipo = 'GUIA_REMISION'
              AND l.documento_id   = p_guia_id
              AND l.fyh_elm        IS NULL
              -- Any movement NOT from this guia means the lote was used downstream
              AND NOT (im.documento_tipo = 'GUIA_REMISION' AND im.documento_id = p_guia_id)
        ) THEN
            RAISE EXCEPTION
                'No se puede anular la guía #%: uno o más lotes recibidos ya tienen movimientos posteriores (consumo, producción o redespacho).',
                p_guia_id;
        END IF;
    END IF;

    -- ── Resolve reversal movement tipo
    SELECT imt2.id INTO v_reversal_tipo
    FROM inventario.item_movimiento_tipo imt1
    JOIN inventario.item_movimiento_tipo imt2 ON imt2.codigo = CASE imt1.codigo
        WHEN 'COMPRA_ING' THEN 'DEV_PROV_EGR'
        WHEN 'SERV_ING'   THEN 'DEV_CLI_EGR'
        WHEN 'SERV_EGR'   THEN 'SERV_DEV_ING'
        WHEN 'VENTA_EGR'  THEN 'DEV_CLI_ING'
        ELSE NULL
    END
    WHERE imt1.id = v_guia.item_movimiento_tipo_id;

    IF v_reversal_tipo IS NULL THEN
        RAISE EXCEPTION
            'Guía #%: no existe tipo de movimiento de reversal para el tipo de guía "%". Contactar administrador.',
            p_guia_id, v_guia.tipo_codigo;
    END IF;

    -- ── Shared doc_movimiento_id for all reversal movements
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

    -- ── Post reversal movements (swaps origen_ubicacion_id ↔ destino_ubicacion_id)
    INSERT INTO inventario.item_movimientos (
        doc_movimiento_id,
        item_id, lote_id,
        item_movimiento_tipo_id,
        origen_ubicacion_id,
        destino_ubicacion_id,
        cantidad, fecha_hora,
        documento_tipo, documento_id,
        observacion
    )
    SELECT
        v_doc_mov_id,
        im.item_id, im.lote_id,
        v_reversal_tipo,
        im.destino_ubicacion_id,   -- swap: destination becomes the new origin
        im.origen_ubicacion_id,    -- swap: origin becomes the new destination
        im.cantidad,
        NOW(),
        'GUIA_REMISION',
        p_guia_id,
        'ANULACION guía #' || p_guia_id
    FROM inventario.item_movimientos im
    WHERE im.documento_tipo = 'GUIA_REMISION'
      AND im.documento_id   = p_guia_id;

    GET DIAGNOSTICS v_mov_count = ROW_COUNT;

    -- ── For inbound guias: retire the lotes that were created by this guia
    IF NOT v_guia.flg_emitida THEN
        UPDATE inventario.lote
        SET usr_elm = v_usr_id, fyh_elm = NOW()
        WHERE documento_tipo = 'GUIA_REMISION'
          AND documento_id   = p_guia_id
          AND fyh_elm        IS NULL;

        GET DIAGNOSTICS v_lote_count = ROW_COUNT;
    END IF;

    -- ── Mark guia as cancelled
    UPDATE doc.guia_remision
    SET usr_elm = v_usr_id, fyh_elm = NOW()
    WHERE id = p_guia_id;

    RETURN format('Guía #%s anulada. %s movimiento(s) revertido(s)%s.',
        p_guia_id,
        v_mov_count,
        CASE WHEN NOT v_guia.flg_emitida THEN format(', %s lote(s) dado(s) de baja', v_lote_count) ELSE '' END
    );
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_guia_remision - User: %, guia: %, Error: %',
        v_usr_id, p_guia_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.anular_guia_remision(p_guia_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.anular_letra(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.anular_letra(p_letra_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id       int := get_user_id();
    v_estado_actual letra_estado_enum;
    v_facturas_count int;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_letra', v_usr_id, jsonb_build_object('letra_id', p_letra_id));

    SELECT estado INTO v_estado_actual
    FROM doc.letra WHERE id = p_letra_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Letra #% no encontrada.', p_letra_id;
    END IF;
    IF v_estado_actual = 'pagada' THEN
        RAISE EXCEPTION 'No se puede anular la letra #%: ya fue pagada. Revisar con contabilidad.', p_letra_id;
    END IF;
    IF v_estado_actual = 'anulada' THEN
        RAISE EXCEPTION 'Letra #% ya está anulada.', p_letra_id;
    END IF;

    UPDATE doc.letra
    SET estado = 'anulada', usr_mod = v_usr_id, fyh_mod = NOW()
    WHERE id = p_letra_id;

    -- Cascade: recalculate estado_pago for every factura cleared by this letra.
    -- Skip facturas already anuladas.
    UPDATE doc.factura_proveedor fp
    SET estado_pago = CASE
            -- No paid letra at all → fully unpaid again
            WHEN NOT EXISTS (
                SELECT 1
                FROM doc.letra_factura lf2
                JOIN doc.letra l2 ON l2.id = lf2.letra_id
                WHERE lf2.factura_proveedor_id = fp.id
                  AND l2.estado = 'pagada'
            ) THEN 'pendiente'
            -- All non-anulada letras are paid → fully settled
            WHEN NOT EXISTS (
                SELECT 1
                FROM doc.letra_factura lf2
                JOIN doc.letra l2 ON l2.id = lf2.letra_id
                WHERE lf2.factura_proveedor_id = fp.id
                  AND l2.estado NOT IN ('pagada', 'anulada')
            ) THEN 'total'
            -- Mix: some paid, some still open
            ELSE 'parcial'
        END,
        usr_mod = v_usr_id,
        fyh_mod = NOW()
    WHERE fp.id IN (
        SELECT factura_proveedor_id FROM doc.letra_factura WHERE letra_id = p_letra_id
    )
    AND fp.estado_pago <> 'anulado';

    GET DIAGNOSTICS v_facturas_count = ROW_COUNT;

    RETURN format('Letra #%s anulada. %s factura(s) recalculada(s).', p_letra_id, v_facturas_count);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_letra - User: %, letra: %, Error: %', v_usr_id, p_letra_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.anular_letra(p_letra_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.anular_venta(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.anular_venta(p_venta_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id  int := get_user_id();
    v_estado  venta_estado_enum;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT estado INTO v_estado FROM doc.venta WHERE id = p_venta_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Venta #% no encontrada.', p_venta_id;
    END IF;
    IF v_estado = 'ANULADA' THEN
        RAISE EXCEPTION 'Venta #% ya está anulada.', p_venta_id;
    END IF;

    UPDATE doc.venta SET estado = 'ANULADA', usr_mod = v_usr_id WHERE id = p_venta_id;

    RETURN format('Venta #%s anulada.', p_venta_id);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_venta - User: %, venta: %, Error: %', v_usr_id, p_venta_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.anular_venta(p_venta_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.crear_compra(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.crear_compra(p_datos jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id    int := get_user_id();
    v_compra_id bigint;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('crear_compra', v_usr_id, p_datos);

    -- Validate entregas belong to the declared proveedor
    IF p_datos->'entrega_ids' IS NOT NULL AND jsonb_array_length(p_datos->'entrega_ids') > 0 THEN
        IF EXISTS (
            SELECT 1 FROM doc.entrega gr
            WHERE gr.id IN (
                SELECT jsonb_array_elements_text(p_datos->'entrega_ids')::bigint
            )
            AND gr.tercero_id IS DISTINCT FROM (p_datos->>'tercero_id')::INT
        ) THEN
            RAISE EXCEPTION 'Una o más guías no pertenecen al proveedor indicado.';
        END IF;
    END IF;

    -- Validate facturas belong to the declared proveedor
    IF p_datos->'factura_ids' IS NOT NULL AND jsonb_array_length(p_datos->'factura_ids') > 0 THEN
        IF EXISTS (
            SELECT 1 FROM doc.factura_proveedor fp
            WHERE fp.id IN (
                SELECT jsonb_array_elements_text(p_datos->'factura_ids')::bigint
            )
            AND fp.tercero_id IS DISTINCT FROM (p_datos->>'tercero_id')::INT
        ) THEN
            RAISE EXCEPTION 'Una o más facturas no pertenecen al proveedor indicado.';
        END IF;
    END IF;

    -- Insert header
    INSERT INTO doc.compra(tercero_id, fecha, observacion, usr_cre)
    VALUES (
        (p_datos->>'tercero_id')::INT,
        COALESCE((p_datos->>'fecha')::DATE, CURRENT_DATE),
        p_datos->>'observacion',
        v_usr_id
    )
    RETURNING id INTO v_compra_id;

    -- Insert line items
    INSERT INTO doc.compra_detalle(compra_id, item_id, cantidad, precio_unitario, usr_cre)
    SELECT v_compra_id,
           (d->>'item_id')::INT,
           (d->>'cantidad')::NUMERIC,
           (d->>'precio_unitario')::NUMERIC,
           v_usr_id
    FROM jsonb_array_elements(COALESCE(p_datos->'detalle', '[]'::jsonb)) d;

    -- Link entregas
    IF p_datos->'entrega_ids' IS NOT NULL AND jsonb_array_length(p_datos->'entrega_ids') > 0 THEN
        INSERT INTO doc.compra_entrega(compra_id, entrega_id)
        SELECT v_compra_id, jsonb_array_elements_text(p_datos->'entrega_ids')::bigint
        ON CONFLICT DO NOTHING;
    END IF;

    -- Link facturas
    IF p_datos->'factura_ids' IS NOT NULL AND jsonb_array_length(p_datos->'factura_ids') > 0 THEN
        INSERT INTO doc.compra_factura_proveedor(compra_id, factura_proveedor_id, usr_cre)
        SELECT v_compra_id, jsonb_array_elements_text(p_datos->'factura_ids')::bigint, v_usr_id
        ON CONFLICT DO NOTHING;
    END IF;

    RETURN v_compra_id;
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in crear_compra - User: %, Error: %', v_usr_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.crear_compra(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.crear_entrega(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.crear_entrega(p_entrega jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_message   text;
    v_detail    text;
    v_hint      text;
    v_context   text;
    v_sqlstate  text;
    v_entrega_id           BIGINT;
    v_entrega_tipo         entrega_tipo%ROWTYPE;
    v_doc_movimiento_id BIGINT;
    v_usr_id            int := get_user_id();
    v_lote_id           int;
    v_error_payload     jsonb;
    v_fecha_mov         TIMESTAMPTZ;
    v_detalle_id        BIGINT;
    v_linea_rec         RECORD;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

 SELECT * INTO v_entrega_tipo FROM entrega_tipo WHERE id = (p_entrega->>'entrega_tipo_id')::SMALLINT;
 IF NOT FOUND THEN
     RAISE EXCEPTION 'Tipo de guía con id % no existe', (p_entrega->>'entrega_tipo_id');
 END IF;

 -- COMPRA_INGRESO is handled by doc.registrar_entrega_compra (dedicated supplier flow).
 IF v_entrega_tipo.codigo = 'COMPRA_INGRESO' THEN
     RAISE EXCEPTION 'Use doc.registrar_entrega_compra para entregas de proveedor (COMPRA_INGRESO).'
         USING HINT = 'crear_entrega handles client flows only (SERVICIO_INGRESO, despacho, devolucion).';
 END IF;

 -- Devolution tipos have dedicated RPCs with domain-specific validation.
 IF v_entrega_tipo.codigo IN ('DEVOLUCION_CLIENTE_SERVICIO', 'DEVOLUCION_CLIENTE_VENTA') THEN
     RAISE EXCEPTION 'Use doc.registrar_devolucion_cliente para devoluciones de cliente (%).',
         v_entrega_tipo.codigo
         USING HINT = 'registrar_devolucion_cliente validates prior dispatch to the same tercero.';
 END IF;
 IF v_entrega_tipo.codigo = 'DEVOLUCION_CLIENTE_CRUDO' THEN
     RAISE EXCEPTION 'Use doc.registrar_devolucion_crudo_cliente para devoluciones de crudo.'
         USING HINT = 'registrar_devolucion_crudo_cliente validates service ingress origin.';
 END IF;
 IF v_entrega_tipo.codigo = 'DEVOLUCION_PROVEEDOR' THEN
     RAISE EXCEPTION 'Use doc.registrar_devolucion_proveedor para devoluciones a proveedor.'
         USING HINT = 'registrar_devolucion_proveedor validates INSUMO item tipo.';
 END IF;

 -- Movement timestamp: for incoming entregas use fecha_recepcion (allows backdating), for outgoing use now()
 v_fecha_mov := CASE
    WHEN v_entrega_tipo.flg_emitida THEN (p_entrega->>'fecha_emision')::TIMESTAMPTZ
    ELSE COALESCE((p_entrega->>'fecha_recepcion')::TIMESTAMPTZ, now())
END;

-- Single posting document id shared by all movements from this entrega call
SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

IF v_entrega_tipo.flg_emitida THEN
        -- SELECT im.lote_id,COALESCE(im.destino_ubicacion_id,im.origen_ubicacion_id),SUM(CASE WHEN im.movimiento_tipo = 'EGRESO' THEN -im.cantidad WHEN im.movimiento_tipo = 'INGRESO' THEN im.cantidad ELSE 0 END) FROM inventario.item_movimientos im
        -- JOIN jsonb_array_elements(p_entrega->'items') AS items ON items.item_id=im.item_id AND items.lote_id=im.lote_id AND items.ubicacion_id= COALESCE(im.destino_ubicacion_id,im.origen_ubicacion_id)
        -- GROUP BY im.lote_id,COALESCE(im.destino_ubicacion_id,im.origen_ubicacion_id)
        ---------------------
        --VALIDAR DISPONIBILIDAD DE items
        -------------------
        WITH entrega_items AS (
        SELECT
            (i->>'item_id')::int        AS item_id,
            (i->>'lote_id')::int        AS lote_id,
            (i->>'ubicacion_id')::int  AS ubicacion_id,
            SUM((i->>'cantidad')::numeric)  AS cantidad
        FROM jsonb_array_elements(p_entrega->'items') i
        GROUP BY 1,2,3
    ),errores AS (
    SELECT
        items.item_id,
        item.nombre AS item_nombre,
        items.lote_id,
        items.ubicacion_id,
        items.cantidad,
        COALESCE(sa.cantidad_disponible, 0) AS cantidad_disponible
    FROM entrega_items items
    LEFT JOIN inventario.vw_stock_lotes sa
        ON sa.item_id = items.item_id
        AND sa.lote_id = items.lote_id
    JOIN item ON item.id = items.item_id
    WHERE COALESCE(sa.cantidad_disponible, 0) < items.cantidad
)
 SELECT jsonb_agg(
        jsonb_build_object(
            'item_id', item_id,
            'item_nombre', item_nombre,
            'lote_id', lote_id,
            'ubicacion_id', ubicacion_id,
            'saldo_disponible', cantidad_disponible,
            'cantidad_requerida', cantidad
        )
    )
    INTO v_error_payload
    FROM errores;
    IF v_error_payload IS NOT NULL THEN
        RAISE EXCEPTION
            'Stock insuficiente para emitir la guía'
            USING
                DETAIL  = v_error_payload::text;
    END IF;
END IF; -- stock validation (flg_emitida only)

-- Guard: inbound devolutions (flg_emitida=false) must reference lots that are actually
-- out (saldo=0). vw_stock_lotes only contains rows with cantidad_disponible > 0, so a
-- JOIN hit means the lot is still in stock → already returned or never dispatched.
IF NOT v_entrega_tipo.flg_emitida AND v_entrega_tipo.codigo LIKE 'DEVOLUCION%' THEN
    SELECT jsonb_agg(jsonb_build_object('lote_id', ei.lote_id, 'cantidad_disponible', sl.cantidad_disponible))
    INTO v_error_payload
    FROM (
        SELECT DISTINCT (i->>'lote_id')::int AS lote_id
        FROM jsonb_array_elements(p_entrega->'items') i
        WHERE (i->>'lote_id') IS NOT NULL
    ) ei
    JOIN inventario.vw_stock_lotes sl ON sl.lote_id = ei.lote_id;

    IF v_error_payload IS NOT NULL THEN
        RAISE EXCEPTION 'Devolución inválida: los siguientes lotes ya tienen stock positivo (¿ya fueron devueltos?)'
            USING DETAIL = v_error_payload::text;
    END IF;
END IF;
-----------------------------------------------------------------------------------------------------------------------
-- tercero validation applies to all entrega types
IF (p_entrega->>'tercero_id') IS NULL THEN
    RAISE EXCEPTION 'Guía inválida: se esperaba tercero_id';
END IF;
IF v_entrega_tipo.flg_cliente AND NOT EXISTS (
    SELECT 1 FROM tercero WHERE id = (p_entrega->>'tercero_id')::INT AND flg_cliente = true
) THEN
    RAISE EXCEPTION 'Guía inválida: tercero_id % no corresponde a un cliente', (p_entrega->>'tercero_id');
ELSIF NOT v_entrega_tipo.flg_cliente AND NOT EXISTS (
    SELECT 1 FROM tercero WHERE id = (p_entrega->>'tercero_id')::INT AND flg_proveedor = true
) THEN
    RAISE EXCEPTION 'Guía inválida: tercero_id % no corresponde a un proveedor', (p_entrega->>'tercero_id');
END IF;


 INSERT INTO logs_api(function_name, user_id, params)
        VALUES ('crear_entrega', v_usr_id, p_entrega);

    INSERT INTO doc.entrega(entrega_tipo_id, tercero_id, serie, correlativo, fecha_emision, fecha_recepcion)
    VALUES (
        (p_entrega->>'entrega_tipo_id')::INT,
        (p_entrega->>'tercero_id')::INT,
        p_entrega->>'serie',
        p_entrega->>'correlativo',
        (p_entrega->>'fecha_emision')::TIMESTAMPTZ,
        CASE
            WHEN v_entrega_tipo.flg_emitida THEN NULL
            ELSE COALESCE((p_entrega->>'fecha_recepcion')::TIMESTAMPTZ, now())
        END
    )
    RETURNING id INTO v_entrega_id;

IF v_entrega_tipo.flg_emitida THEN
    
    -- Issued guides (dispatch/devolution-out): EGRESO of existing lotes.
    -- Insert detalle first (one line per item) capturing each line id, then post
    -- movements linked to their line via documento_linea_id (≈ MSEG.EBELP).
    WITH items AS (
        SELECT
            COALESCE((item->>'linea')::SMALLINT, idx::SMALLINT) AS linea,
            (item->>'item_id')::INT                             AS item_id,
            (item->>'cantidad')::NUMERIC(12,4)                  AS cantidad,
            (item->>'lote_id')::INT                             AS lote_id,
            (item->>'ubicacion_id')::INT                        AS ubicacion_id,
            (item->>'n_rollos')::INT                            AS n_rollos
        FROM jsonb_array_elements(p_entrega->'items') WITH ORDINALITY AS t(item, idx)
    ),
    det AS (
        INSERT INTO doc.entrega_detalle (entrega_id, linea, item_id, cantidad, lote_id, ubicacion_id, n_rollos)
        SELECT v_entrega_id, linea, item_id, cantidad, lote_id, ubicacion_id, n_rollos
        FROM items
        RETURNING id, linea
    )
    INSERT INTO inventario.item_movimientos (
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        origen_ubicacion_id, destino_ubicacion_id,
        cantidad, fecha_hora, documento_tipo, documento_id, documento_linea_id)
    SELECT
        v_doc_movimiento_id, i.item_id, i.lote_id, v_entrega_tipo.item_movimiento_tipo_id,
        i.ubicacion_id,   -- per-item origin location
        NULL,             -- destination is external
        i.cantidad, v_fecha_mov, 'entrega', v_entrega_id, d.id
    FROM items i
    JOIN det d ON d.linea = i.linea;
ELSE
    -- Inbound (non-emitida): two item kinds.
    --   (a) lote_id present → devolution: move an existing lote, no new lote.
    --   (b) lote_id absent  → new client rolls: create N lotes + lrd + movements.
    -- Both stamp documento_linea_id (≈ MSEG.EBELP) so receipts are line-auditable.

    -- (a) Devolution lines: detalle first, movements linked per line.
    WITH items AS (
        SELECT
            COALESCE((item->>'linea')::SMALLINT, idx::SMALLINT) AS linea,
            (item->>'item_id')::INT                             AS item_id,
            (item->>'cantidad')::NUMERIC(12,4)                  AS cantidad,
            (item->>'lote_id')::INT                             AS lote_id,
            (item->>'ubicacion_id')::INT                        AS ubicacion_id
        FROM jsonb_array_elements(p_entrega->'items') WITH ORDINALITY AS t(item, idx)
        WHERE item->>'lote_id' IS NOT NULL
    ),
    det AS (
        INSERT INTO doc.entrega_detalle (entrega_id, linea, item_id, cantidad, lote_id, ubicacion_id)
        SELECT v_entrega_id, linea, item_id, cantidad, lote_id, ubicacion_id
        FROM items
        RETURNING id, linea
    )
    INSERT INTO inventario.item_movimientos (
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        destino_ubicacion_id, cantidad, fecha_hora,
        documento_tipo, documento_id, documento_linea_id)
    SELECT
        v_doc_movimiento_id, i.item_id, i.lote_id, v_entrega_tipo.item_movimiento_tipo_id,
        i.ubicacion_id, i.cantidad, v_fecha_mov, 'entrega', v_entrega_id, d.id
    FROM items i
    JOIN det d ON d.linea = i.linea;

    -- (b) New client rolls — one declared line per item, expanded to N lotes,
    --     each lote/lrd/movement carrying that line's documento_linea_id.
    FOR v_linea_rec IN
        SELECT
            COALESCE((item->>'linea')::SMALLINT, idx::SMALLINT) AS linea,
            (item->>'item_id')::INT                             AS item_id,
            (item->>'ubicacion_id')::INT                        AS ubicacion_id,
            (item->>'cantidad')::NUMERIC                        AS cantidad,
            COALESCE((item->>'cantidad_rollos')::INT, 1)        AS cantidad_rollos
        FROM jsonb_array_elements(p_entrega->'items') WITH ORDINALITY AS t(item, idx)
        WHERE item->>'lote_id' IS NULL
    LOOP
        INSERT INTO doc.entrega_detalle (entrega_id, linea, item_id, cantidad, n_rollos)
        VALUES (v_entrega_id, v_linea_rec.linea, v_linea_rec.item_id,
                v_linea_rec.cantidad, v_linea_rec.cantidad_rollos)
        RETURNING id INTO v_detalle_id;

        WITH nuevos_lotes AS (
            INSERT INTO lote (item_id, documento_tipo, documento_id, cantidad, propietario_id)
            SELECT v_linea_rec.item_id, 'entrega', v_entrega_id,
                   COALESCE(v_linea_rec.cantidad / NULLIF(v_linea_rec.cantidad_rollos, 0),
                            v_linea_rec.cantidad),
                   (p_entrega->>'propietario_id')::INT
            FROM generate_series(1, v_linea_rec.cantidad_rollos)
            RETURNING id, item_id, cantidad
        ),
        lrd_rows AS (
            INSERT INTO inventario.lote_rollo_detalle (lote_id, entrega_id, flg_tenido)
            SELECT nl.id, v_entrega_id, false
            FROM nuevos_lotes nl
            JOIN item i       ON i.id = nl.item_id
            JOIN item_tipo it ON it.id = i.item_tipo_id AND it.codigo = 'ROLLO'
        )
        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, destino_ubicacion_id,
            cantidad, fecha_hora, documento_tipo, documento_id, documento_linea_id)
        SELECT
            v_doc_movimiento_id, nl.item_id, nl.id, v_entrega_tipo.item_movimiento_tipo_id,
            NULL, (p_entrega->>'destino_ubicacion_id')::INT,
            nl.cantidad, v_fecha_mov, 'entrega', v_entrega_id, v_detalle_id
        FROM nuevos_lotes nl;
    END LOOP;
END IF;
INSERT INTO notification.notifications(user_id,title,body,tipo,payload)
SELECT ur.user_id,'Nueva entrega y movimientos', COALESCE((SELECT COALESCE(nombre,'Usuario desconocido') || ' ' || apellido FROM usuario WHERE id=v_usr_id),'sistema') || ' creó una nueva guía de remisión y generó movimientos de inventario', 'info',jsonb_build_object('objeto_tipo','entrega','entrega_id',v_entrega_id)
FROM iam.user_rol ur LEFT JOIN usuario p ON p.id=ur.user_id
LEFT JOIN iam.rol r ON ur.rol_id=r.id
WHERE r.code IN ('jefe_planta','compras','inventario') AND v_usr_id<>ur.user_id;
   RETURN v_entrega_id;
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;

        RAISE LOG 'Error in crear_entrega - User: %, Params: %, Error: %, Detail: %',
                  v_usr_id, p_entrega::TEXT, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION doc.crear_entrega(p_entrega jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.crear_guia(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.crear_guia(p_guia jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_message   text;
    v_detail    text;
    v_hint      text;
    v_context   text;
    v_sqlstate  text;
    v_guia_id           BIGINT;
    v_guia_tipo         guia_remision_tipo%ROWTYPE;
    v_doc_movimiento_id BIGINT;
    v_usr_id            int := get_user_id();
    v_lote_id           int;
    v_error_payload     jsonb;
    v_fecha_mov         TIMESTAMPTZ;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

 SELECT * INTO v_guia_tipo FROM guia_remision_tipo WHERE id = (p_guia->>'guia_remision_tipo_id')::SMALLINT;
 IF NOT FOUND THEN
     RAISE EXCEPTION 'Tipo de guía con id % no existe', (p_guia->>'guia_remision_tipo_id');
 END IF;

 -- COMPRA_INGRESO must always be tied to a compra — ensures precio_unitario is available
 -- and stock is traceable to a PO. Use doc.ingresar_compra when no guia is in hand.
 IF v_guia_tipo.codigo = 'COMPRA_INGRESO' AND (p_guia->>'compra_id') IS NULL THEN
     RAISE EXCEPTION 'Guía tipo COMPRA_INGRESO requiere compra_id'
         USING HINT = 'Si no tiene guía física aún, use doc.ingresar_compra en su lugar.';
 END IF;

 -- Movement timestamp: for incoming guias use fecha_recepcion (allows backdating), for outgoing use now()
 v_fecha_mov := CASE
    WHEN v_guia_tipo.flg_emitida THEN (p_guia->>'fecha_emision')::TIMESTAMPTZ
    ELSE COALESCE((p_guia->>'fecha_recepcion')::TIMESTAMPTZ, now())
END;

-- Single posting document id shared by all movements from this guia call
SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

IF v_guia_tipo.flg_emitida THEN
        -- SELECT im.lote_id,COALESCE(im.destino_ubicacion_id,im.origen_ubicacion_id),SUM(CASE WHEN im.movimiento_tipo = 'EGRESO' THEN -im.cantidad WHEN im.movimiento_tipo = 'INGRESO' THEN im.cantidad ELSE 0 END) FROM inventario.item_movimientos im
        -- JOIN jsonb_array_elements(p_guia->'items') AS items ON items.item_id=im.item_id AND items.lote_id=im.lote_id AND items.ubicacion_id= COALESCE(im.destino_ubicacion_id,im.origen_ubicacion_id)
        -- GROUP BY im.lote_id,COALESCE(im.destino_ubicacion_id,im.origen_ubicacion_id)
        ---------------------
        --VALIDAR DISPONIBILIDAD DE items
        -------------------
        WITH guia_items AS (
        SELECT
            (i->>'item_id')::int        AS item_id,
            (i->>'lote_id')::int        AS lote_id,
            (i->>'ubicacion_id')::int  AS ubicacion_id,
            SUM((i->>'cantidad')::numeric)  AS cantidad
        FROM jsonb_array_elements(p_guia->'items') i
        GROUP BY 1,2,3
    ),errores AS (
    SELECT
        items.item_id,
        item.nombre AS item_nombre,
        items.lote_id,
        items.ubicacion_id,
        items.cantidad,
        COALESCE(sa.cantidad_disponible, 0) AS cantidad_disponible
    FROM guia_items items
    LEFT JOIN inventario.vw_stock_lotes sa
        ON sa.item_id = items.item_id
        AND sa.lote_id = items.lote_id
    JOIN item ON item.id = items.item_id
    WHERE COALESCE(sa.cantidad_disponible, 0) < items.cantidad
)
 SELECT jsonb_agg(
        jsonb_build_object(
            'item_id', item_id,
            'item_nombre', item_nombre,
            'lote_id', lote_id,
            'ubicacion_id', ubicacion_id,
            'saldo_disponible', cantidad_disponible,
            'cantidad_requerida', cantidad
        )
    )
    INTO v_error_payload
    FROM errores;
    IF v_error_payload IS NOT NULL THEN
        RAISE EXCEPTION
            'Stock insuficiente para emitir la guía'
            USING
                DETAIL  = v_error_payload::text;
    END IF;
END IF; -- stock validation (flg_emitida only)
-----------------------------------------------------------------------------------------------------------------------
-- tercero validation applies to all guia types
IF (p_guia->>'tercero_id') IS NULL THEN
    RAISE EXCEPTION 'Guía inválida: se esperaba tercero_id';
END IF;
IF v_guia_tipo.flg_cliente AND NOT EXISTS (
    SELECT 1 FROM tercero WHERE id = (p_guia->>'tercero_id')::INT AND flg_cliente = true
) THEN
    RAISE EXCEPTION 'Guía inválida: tercero_id % no corresponde a un cliente', (p_guia->>'tercero_id');
ELSIF NOT v_guia_tipo.flg_cliente AND NOT EXISTS (
    SELECT 1 FROM tercero WHERE id = (p_guia->>'tercero_id')::INT AND flg_proveedor = true
) THEN
    RAISE EXCEPTION 'Guía inválida: tercero_id % no corresponde a un proveedor', (p_guia->>'tercero_id');
END IF;


 INSERT INTO logs_api(function_name, user_id, params)
        VALUES ('crear_guia', v_usr_id, p_guia);

    INSERT INTO doc.guia_remision(guia_remision_tipo_id, tercero_id, serie, correlativo, fecha_emision, fecha_recepcion)
    VALUES (
        (p_guia->>'guia_remision_tipo_id')::INT,
        (p_guia->>'tercero_id')::INT,
        p_guia->>'serie',
        p_guia->>'correlativo',
        (p_guia->>'fecha_emision')::TIMESTAMPTZ,
        CASE
            WHEN v_guia_tipo.flg_emitida THEN NULL
            ELSE COALESCE((p_guia->>'fecha_recepcion')::TIMESTAMPTZ, now())
        END
    )
    RETURNING id INTO v_guia_id;

-- COMPRA_INGRESO: static document registration only.
-- Movements are always posted separately via doc.ingresar_compra.
-- Returning early here prevents any possibility of double-posting.
IF v_guia_tipo.codigo = 'COMPRA_INGRESO' THEN
    INSERT INTO doc.compra_guia_remision (compra_id, guia_remision_id)
    VALUES ((p_guia->>'compra_id')::BIGINT, v_guia_id)
    ON CONFLICT DO NOTHING;

    INSERT INTO doc.guia_remision_detalle (guia_remision_id, linea, item_id, cantidad, n_rollos)
    SELECT v_guia_id,
           COALESCE((item->>'linea')::SMALLINT, (row_number() OVER ())::SMALLINT),
           (item->>'item_id')::INT, (item->>'cantidad')::NUMERIC,
           (item->>'cantidad_rollos')::INT
    FROM jsonb_array_elements(p_guia->'items') AS item;

    RETURN format('Guía de remisión con ID %s registrada (documento SUNAT — sin movimientos).', v_guia_id);
END IF;

IF v_guia_tipo.flg_emitida THEN
    
    INSERT INTO doc.guia_remision_detalle (guia_remision_id, linea, item_id, cantidad, lote_id, ubicacion_id, n_rollos)
    SELECT
        v_guia_id,
        COALESCE((item->>'linea')::SMALLINT, (row_number() OVER ())::SMALLINT),
        (item->>'item_id')::INT,
        (item->>'cantidad')::NUMERIC(12,4),
        (item->>'lote_id')::INT,
        (item->>'ubicacion_id')::INT,
        (item->>'n_rollos')::INT
    FROM jsonb_array_elements(p_guia->'items') AS item;
    -- For issued guides, create item movements as EGRESO from warehouse
    INSERT INTO inventario.item_movimientos
    (
        doc_movimiento_id, item_id,
        lote_id,
        item_movimiento_tipo_id,
        origen_ubicacion_id,
        destino_ubicacion_id,
        cantidad, fecha_hora, documento_tipo, documento_id)
    SELECT
        v_doc_movimiento_id,
        (item->>'item_id')::INT,
        (item->>'lote_id')::INT,
        v_guia_tipo.item_movimiento_tipo_id,
        (item->>'ubicacion_id')::INT,  -- per-item origin location
        NULL, -- destination is external
        (item->>'cantidad')::NUMERIC(12,4),
        v_fecha_mov,
        'guia_remision',
        v_guia_id
    FROM jsonb_array_elements(p_guia->'items') AS item;
ELSE
    -- Devolution: items with existing lote_id — movement only, no new lote
    INSERT INTO inventario.item_movimientos
        (doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
         destino_ubicacion_id, cantidad, fecha_hora, documento_tipo, documento_id)
    SELECT v_doc_movimiento_id, (item->>'item_id')::INT, (item->>'lote_id')::INT,
           v_guia_tipo.item_movimiento_tipo_id, (item->>'ubicacion_id')::INT,
           (item->>'cantidad')::NUMERIC(12,4), v_fecha_mov, 'guia_remision', v_guia_id
    FROM jsonb_array_elements(p_guia->'items') AS item
    WHERE item->>'lote_id' IS NOT NULL;

    INSERT INTO doc.guia_remision_detalle (guia_remision_id, linea, item_id, cantidad, lote_id, ubicacion_id)
    SELECT v_guia_id,
           COALESCE((item->>'linea')::SMALLINT, (row_number() OVER ())::SMALLINT),
           (item->>'item_id')::INT, (item->>'cantidad')::NUMERIC,
           (item->>'lote_id')::INT, (item->>'ubicacion_id')::INT
    FROM jsonb_array_elements(p_guia->'items') AS item
    WHERE item->>'lote_id' IS NOT NULL;

    -- Document layer
    INSERT INTO doc.guia_remision_detalle (guia_remision_id, linea, item_id, cantidad, n_rollos)
    SELECT v_guia_id,
           COALESCE((item->>'linea')::SMALLINT, (row_number() OVER ())::SMALLINT),
           (item->>'item_id')::INT, (item->>'cantidad')::NUMERIC,
           (item->>'cantidad_rollos')::INT
    FROM jsonb_array_elements(p_guia->'items') AS item
    WHERE item->>'lote_id' IS NULL;

    WITH expanded AS (
        SELECT
            (item->>'item_id')::INT   AS item_id,
            (item->>'ubicacion_id')::INT AS ubicacion_id,
            (item->>'cantidad')::NUMERIC AS cantidad,
            (item->>'cantidad')::NUMERIC / NULLIF((item->>'cantidad_rollos')::INT, 0) AS peso_estimado,
            (p_guia->>'propietario_id')::INT AS propietario_id
        FROM jsonb_array_elements(p_guia->'items') AS item
        LEFT JOIN LATERAL generate_series(1, COALESCE((item->>'cantidad_rollos')::INT, 1)) rollo_numero ON true
        WHERE item->>'lote_id' IS NULL
    ),
    nuevos_lotes AS (
        INSERT INTO lote (item_id, documento_tipo, documento_id, cantidad, propietario_id)
        SELECT item.item_id, 'guia_remision', v_guia_id,
               COALESCE(item.peso_estimado, item.cantidad), item.propietario_id
        FROM expanded AS item
        RETURNING id, item_id, cantidad
    ),
    lrd_rows AS (
        INSERT INTO inventario.lote_rollo_detalle (lote_id, guia_remision_id, flg_tenido)
        SELECT nl.id, v_guia_id, false
        FROM nuevos_lotes nl
        JOIN item i   ON i.id = nl.item_id
        JOIN item_tipo it ON it.id = i.item_tipo_id AND it.codigo = 'ROLLO'
    )
    INSERT INTO inventario.item_movimientos (
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        origen_ubicacion_id, destino_ubicacion_id,
        cantidad, fecha_hora, documento_tipo, documento_id
    )
    SELECT v_doc_movimiento_id, nl.item_id, nl.id,
           v_guia_tipo.item_movimiento_tipo_id,
           NULL, (p_guia->>'destino_ubicacion_id')::INT,
           nl.cantidad, v_fecha_mov, 'guia_remision', v_guia_id
    FROM nuevos_lotes nl;
END IF;
INSERT INTO notification.notifications(user_id,title,body,tipo,payload)
SELECT ur.user_id,'Nueva Guia y movimientos', COALESCE((SELECT COALESCE(nombre,'Usuario desconocido') || ' ' || apellido FROM usuario WHERE id=v_usr_id),'sistema') || ' creó una nueva guía de remisión y generó movimientos de inventario', 'info',jsonb_build_object('objeto_tipo','guia_remision','guia_remision_id',v_guia_id)
FROM iam.user_rol ur LEFT JOIN usuario p ON p.id=ur.user_id
LEFT JOIN iam.rol r ON ur.rol_id=r.id
WHERE r.code IN ('jefe_planta','compras','inventario') AND v_usr_id<>ur.user_id;
   RETURN format('Guía de remisión con ID %s creada correctamente.', v_guia_id);
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;

        RAISE LOG 'Error in crear_guia - User: %, Params: %, Error: %, Detail: %',
                  v_usr_id, p_guia::TEXT, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION doc.crear_guia(p_guia jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.crear_ingreso_interno(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.crear_ingreso_interno(p_datos jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_usr_id         INT      := get_user_id();
    v_ent_tipo_id    SMALLINT;
    v_serv_ing_tipo  SMALLINT;
    v_ent_id         BIGINT;
    v_doc_mov_id     BIGINT;
    v_ubicacion_id   INT;
    v_fecha_mov      TIMESTAMPTZ;
    v_linea_json     JSONB;
    v_det_linea      SMALLINT := 1;
    v_det_id         BIGINT;
    v_new_lote_id    BIGINT;
    v_peso_por_rollo NUMERIC;
    v_item_id        INT;
    v_cant_rollos    INT;
    v_i              INT;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('crear_ingreso_interno', v_usr_id, p_datos);

    IF NULLIF(TRIM(p_datos->>'correlativo'), '') IS NULL THEN
        RAISE EXCEPTION 'crear_ingreso_interno: correlativo (factura hilo) es requerido';
    END IF;

    SELECT id INTO STRICT v_ent_tipo_id
    FROM doc.entrega_tipo WHERE codigo = 'INGRESO_INTERNO';

    SELECT id INTO STRICT v_serv_ing_tipo
    FROM inventario.item_movimiento_tipo WHERE codigo = 'SERV_ING';

    v_ubicacion_id := COALESCE(
        (p_datos->>'ubicacion_id')::INT,
        (SELECT ub.id
         FROM   inventario.ubicacion ub
         JOIN   inventario.almacen alm ON alm.id = ub.almacen_id
         WHERE  alm.codigo = 'ALM_CRU'
         LIMIT  1)
    );
    v_fecha_mov := COALESCE((p_datos->>'fecha_emision')::DATE::TIMESTAMPTZ, now());

    -- ── Entrega header ───────────────────────────────────────────
    INSERT INTO doc.entrega (
        entrega_tipo_id, tercero_id,
        serie,                  correlativo,
        fecha_emision, usr_cre
    ) VALUES (
        v_ent_tipo_id,
        1,  -- MLR self; INGRESO_INTERNO has no external counterparty
        'II-' || nextval('doc.ingreso_interno_seq')::TEXT,  -- auto, always unique
        p_datos->>'correlativo',  -- hilo supplier invoice/factura, e.g. 'F-201/2024'
        COALESCE((p_datos->>'fecha_emision')::DATE, CURRENT_DATE),
        v_usr_id
    )
    RETURNING id INTO v_ent_id;

    v_doc_mov_id := nextval('inventario.mov_doc_seq');

    -- ── Roll lines ───────────────────────────────────────────────
    FOR v_linea_json IN SELECT jsonb_array_elements(p_datos->'lineas')
    LOOP
        v_item_id     := (v_linea_json->>'item_id')::INT;
        v_cant_rollos := (v_linea_json->>'cantidad_rollos')::INT;

        IF v_cant_rollos IS NULL OR v_cant_rollos <= 0 THEN
            RAISE EXCEPTION 'crear_ingreso_interno: cada línea requiere cantidad_rollos > 0';
        END IF;

        v_peso_por_rollo := COALESCE(
            (v_linea_json->>'peso_total')::NUMERIC / NULLIF(v_cant_rollos, 0),
            0.1   -- sentinel; corrected at weighing gate
        );

        FOR v_i IN 1 .. v_cant_rollos
        LOOP
            -- lote (propietario_id=NULL → MLR-owned)
            INSERT INTO inventario.lote (
                item_id, documento_tipo, documento_id,
                cantidad, propietario_id, usr_cre
            ) VALUES (
                v_item_id, 'entrega', v_ent_id,
                v_peso_por_rollo, NULL, v_usr_id
            )
            RETURNING id INTO v_new_lote_id;

            -- lrd (entrega_id is NOT NULL after patch 35)
            INSERT INTO inventario.lote_rollo_detalle (
                lote_id,       entrega_id,
                ancho,         malla,
                rendimiento,   color_x_cliente_id,
                flg_tenido,    flg_antipilling
            ) VALUES (
                v_new_lote_id, v_ent_id,
                p_datos->>'ancho',
                v_linea_json->>'malla',
                p_datos->>'rendimiento',
                (v_linea_json->>'color_x_cliente_id')::INT,
                false,
                COALESCE((p_datos->>'flg_antipilling')::BOOLEAN, false)
            );

            -- entrega_detalle
            INSERT INTO doc.entrega_detalle (
                entrega_id, linea, lote_id, item_id, cantidad, ubicacion_id
            ) VALUES (
                v_ent_id, v_det_linea, v_new_lote_id, v_item_id,
                v_peso_por_rollo, v_ubicacion_id
            )
            RETURNING id INTO v_det_id;

            -- SERV_ING movement
            INSERT INTO inventario.item_movimientos (
                doc_movimiento_id, item_id, lote_id,
                item_movimiento_tipo_id,
                destino_ubicacion_id, cantidad, fecha_hora,
                documento_tipo, documento_id, documento_linea_id, usr_cre
            ) VALUES (
                v_doc_mov_id, v_item_id, v_new_lote_id,
                v_serv_ing_tipo,
                v_ubicacion_id, v_peso_por_rollo, v_fecha_mov,
                'entrega', v_ent_id, v_det_id, v_usr_id
            );

            v_det_linea := v_det_linea + 1;
        END LOOP;
    END LOOP;

    RETURN v_ent_id;
EXCEPTION
    WHEN OTHERS THEN
        RAISE LOG 'Error in crear_ingreso_interno - User: %, Params: %, Error: %',
                  v_usr_id, p_datos::TEXT, SQLERRM;
        RAISE;
END;
$$;


ALTER FUNCTION doc.crear_ingreso_interno(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.crear_orden_servicio(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.crear_orden_servicio(p_orden jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_usr_id        INT := get_user_id();
    v_os_id         BIGINT;
    v_linea         jsonb;
    v_detalle_id    BIGINT;
    v_recibir       jsonb := '[]'::jsonb;   -- accumulated first-receipt lines
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF (p_orden->>'tercero_id') IS NULL THEN
        RAISE EXCEPTION 'crear_orden_servicio: se requiere tercero_id';
    END IF;

    INSERT INTO doc.orden_servicio (
        tercero_id, serie, correlativo,
        fecha_entrega, rendimiento, ancho,
        flg_antipilling, flg_urgente,
        observacion, referencia_hilo, usr_cre
    ) VALUES (
        (p_orden->>'tercero_id')::INT,
        p_orden->>'serie',
        (p_orden->>'correlativo')::INT,
        (p_orden->>'fecha_entrega')::DATE,
        p_orden->>'rendimiento',
        p_orden->>'ancho',
        COALESCE((p_orden->>'flg_antipilling')::BOOLEAN, false),
        COALESCE((p_orden->>'flg_urgente')::BOOLEAN, false),
        p_orden->>'observacion',
        p_orden->>'referencia_hilo',
        v_usr_id
    )
    RETURNING id INTO v_os_id;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('crear_orden_servicio', v_usr_id, p_orden);

    -- Ordered lines (intent only — no stock posted here)
    FOR v_linea IN SELECT value FROM jsonb_array_elements(p_orden->'lineas')
    LOOP
        INSERT INTO doc.orden_servicio_detalle (
            orden_servicio_id, linea, item_id, malla,
            cantidad, color_x_cliente_id, tenido_id, flg_doble_bolsa
        ) VALUES (
            v_os_id,
            COALESCE((v_linea->>'linea')::SMALLINT, 1),
            (v_linea->>'item_id')::INT,
            v_linea->>'malla',
            (v_linea->>'cantidad_rollos')::INT,
            (v_linea->>'color_x_cliente_id')::INT,
            (v_linea->>'tenido_id')::INT,
            COALESCE((v_linea->>'flg_doble_bolsa')::BOOLEAN, false)
        )
        RETURNING id INTO v_detalle_id;

        v_recibir := v_recibir || jsonb_build_object(
            'detalle_id',     v_detalle_id,
            'cantidad_rollos', (v_linea->>'cantidad_rollos')::INT,
            'peso_total',      (v_linea->>'peso_total'),
            'factura_hilo',    (v_linea->>'factura_hilo')
        );
    END LOOP;

    -- First receipt: only when a destination is given (rolls arrived with the order)
    IF (p_orden->>'destino_ubicacion_id') IS NOT NULL THEN
        PERFORM doc.ingresar_orden_servicio(jsonb_build_object(
            'orden_servicio_id', v_os_id,
            'ubicacion_id',      (p_orden->>'destino_ubicacion_id')::INT,
            'lineas',            v_recibir
        ));
    END IF;

    INSERT INTO notification.notifications (user_id, title, body, tipo, payload)
    SELECT ur.user_id,
           'Nueva Orden de Servicio',
           COALESCE((SELECT COALESCE(nombre, 'Usuario desconocido') || ' ' || apellido FROM usuario WHERE id = v_usr_id), 'sistema')
               || ' creó la orden de servicio ' || (p_orden->>'serie') || '-' || (p_orden->>'correlativo'),
           'info',
           jsonb_build_object('objeto_tipo', 'orden_servicio', 'orden_servicio_id', v_os_id)
    FROM iam.user_rol ur
    LEFT JOIN iam.rol r ON ur.rol_id = r.id
    WHERE r.code IN ('jefe_planta', 'compras', 'inventario')
      AND v_usr_id <> ur.user_id;

    RETURN format('Orden de servicio %s creada con ID %s.', (p_orden->>'serie') || '-' || (p_orden->>'correlativo'), v_os_id);
EXCEPTION
    WHEN OTHERS THEN
        RAISE LOG 'Error in crear_orden_servicio - User: %, Params: %, Error: %',
                  v_usr_id, p_orden::TEXT, SQLERRM;
        RAISE;
END;
$$;


ALTER FUNCTION doc.crear_orden_servicio(p_orden jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.desvincular_entregas_compra(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.desvincular_entregas_compra(p_compra_id bigint, p_entrega_ids jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id   int := get_user_id();
    v_unlinked int;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('desvincular_entregas_compra', v_usr_id,
            jsonb_build_object('compra_id', p_compra_id, 'entrega_ids', p_entrega_ids));

    IF NOT EXISTS (SELECT 1 FROM doc.compra WHERE id = p_compra_id) THEN
        RAISE EXCEPTION 'Compra #% no encontrada.', p_compra_id;
    END IF;

    -- Clear line-level PO references on entrega_detalle lines
    UPDATE doc.entrega_detalle
    SET compra_detalle_id = NULL
    WHERE entrega_id IN (SELECT jsonb_array_elements_text(p_entrega_ids)::bigint)
      AND compra_detalle_id IN (
          SELECT id FROM doc.compra_detalle WHERE compra_id = p_compra_id
      );

    -- Remove header link
    DELETE FROM doc.compra_entrega
    WHERE compra_id = p_compra_id
      AND entrega_id IN (SELECT jsonb_array_elements_text(p_entrega_ids)::bigint);

    GET DIAGNOSTICS v_unlinked = ROW_COUNT;

    PERFORM doc.fn_refresh_compra_detalle_qtys(p_compra_id);

    RETURN format('%s guía(s) desvinculada(s) de compra #%s.', v_unlinked, p_compra_id);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in desvincular_entregas_compra - User: %, compra: %, Error: %', v_usr_id, p_compra_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.desvincular_entregas_compra(p_compra_id bigint, p_entrega_ids jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.desvincular_facturas_compra(bigint, jsonb)
