-- ---------------------------------------------------------------------
-- FUNCTION: doc.facturar_venta(bigint, text, integer, date)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.facturar_venta(p_venta_id bigint, p_serie text, p_numero integer, p_fecha_venc date DEFAULT NULL::date) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id  int := get_user_id();
    v_estado  venta_estado_enum;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT estado INTO v_estado FROM doc.venta WHERE id = p_venta_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Venta #% no encontrada.', p_venta_id;
    END IF;
    IF v_estado <> 'ABIERTA' THEN
        RAISE EXCEPTION 'Venta #% no está ABIERTA (estado actual: %) — no se puede facturar.', p_venta_id, v_estado;
    END IF;

    UPDATE doc.venta
    SET factura_serie = p_serie, factura_numero = p_numero, factura_fecha_venc = p_fecha_venc,
        estado = 'FACTURADA', usr_mod = v_usr_id
    WHERE id = p_venta_id;

    RETURN format('Venta #%s facturada con %s-%s.', p_venta_id, p_serie, p_numero);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in facturar_venta - User: %, venta: %, Error: %', v_usr_id, p_venta_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.facturar_venta(p_venta_id bigint, p_serie text, p_numero integer, p_fecha_venc date) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.fn_descripcion_linea(public.venta_linea_tipo_enum, smallint, integer, integer, integer, integer, boolean)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.fn_descripcion_linea(p_tipo public.venta_linea_tipo_enum, p_operacion_id smallint, p_item_id integer, p_grupo_articulo_id integer, p_color_x_cliente_id integer, p_tenido_id integer, p_flg_antipilling boolean) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'mes', 'doc'
    AS $$
    SELECT CASE
        WHEN p_tipo = 'VENTA' THEN
            COALESCE((SELECT nombre FROM item WHERE id = p_item_id), 'Producto')
        ELSE
            TRIM(BOTH ' · ' FROM
                COALESCE((SELECT nombre FROM mes.operacion WHERE id = p_operacion_id), '')
                || ' — '
                || COALESCE((SELECT nombre FROM grupo_articulo WHERE id = p_grupo_articulo_id), '')
                || COALESCE(' · ' || (SELECT color FROM vw_colores WHERE color_x_cliente_id = p_color_x_cliente_id), '')
                || COALESCE(' · ' || (SELECT tenido FROM tenido WHERE id = p_tenido_id), '')
                || CASE WHEN p_flg_antipilling THEN ' · Antipilling' ELSE '' END
            )
    END;
$$;


ALTER FUNCTION doc.fn_descripcion_linea(p_tipo public.venta_linea_tipo_enum, p_operacion_id smallint, p_item_id integer, p_grupo_articulo_id integer, p_color_x_cliente_id integer, p_tenido_id integer, p_flg_antipilling boolean) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.fn_familia_precio(integer, integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.fn_familia_precio(p_grupo_articulo_id integer, p_tercero_id integer) RETURNS integer
    LANGUAGE sql STABLE
    SET search_path TO 'doc', 'public'
    AS $$
    SELECT COALESCE(
        (SELECT f.familia_grupo_id
         FROM doc.articulo_tipo_familia f
         WHERE f.grupo_articulo_id = p_grupo_articulo_id
           AND (f.tercero_id = p_tercero_id OR f.tercero_id IS NULL)
         ORDER BY f.tercero_id NULLS LAST   -- specific client beats default
         LIMIT 1),
        p_grupo_articulo_id                 -- no mapping → itself
    );
$$;


ALTER FUNCTION doc.fn_familia_precio(p_grupo_articulo_id integer, p_tercero_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.fn_get_costo_receta(integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.fn_get_costo_receta(p_receta_id integer) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'receta', 'doc', 'public'
    AS $$
    SELECT ROUND(
        SUM(
            tpi.cantidad
            * CASE iid.medida
                WHEN 'g/L' THEN (5.0  / 1000.0)
                WHEN '%'   THEN (10.0 / 1000.0)
                ELSE            (1.0  / 1000.0)
              END
            * iid.factor_stock
            * COALESCE(
                -- Authoritative: latest supplier invoice line (ex-IGV)
                (
                    SELECT fpd.precio_unitario
                    FROM doc.factura_proveedor_detalle fpd
                    WHERE fpd.item_id = tpi.item_id
                    ORDER BY fpd.fyh_cre DESC
                    LIMIT 1
                ),
                -- Fallback: latest purchase order estimated price
                (
                    SELECT cd.precio_unitario
                    FROM doc.compra_detalle cd
                    WHERE cd.item_id = tpi.item_id
                    ORDER BY cd.fyh_cre DESC
                    LIMIT 1
                ),
                0
            )
        ),
        4
    )
    FROM receta.tenido_paso tp
    JOIN receta.tenido_paso_insumo tpi ON tpi.paso_id = tp.id
    JOIN public.item_insumo_detalle iid ON iid.item_id = tpi.item_id
    WHERE tp.receta_id = p_receta_id;
$$;


ALTER FUNCTION doc.fn_get_costo_receta(p_receta_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.fn_get_precio(smallint, integer, integer, integer, integer, smallint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.fn_get_precio(p_operacion_id smallint, p_color_x_cliente_id integer, p_tercero_id integer, p_grupo_articulo_id integer, p_tenido_id integer, p_fibra smallint) RETURNS numeric
    LANGUAGE sql STABLE
    SET search_path TO 'doc', 'public'
    AS $$
    SELECT cp.precio_kg
    FROM doc.catalogo_precios cp
    WHERE
        cp.operacion_id = p_operacion_id
        -- Client dimension: specific color, OR client-level wildcard, OR universal
        AND (cp.color_x_cliente_id IS NULL OR cp.color_x_cliente_id = p_color_x_cliente_id)
        AND (cp.tercero_id         IS NULL OR cp.tercero_id         = p_tercero_id)
        -- A color_x_cliente row must not be matched as a tercero-level row
        AND NOT (cp.color_x_cliente_id IS NULL AND cp.tercero_id IS NOT NULL
                 AND cp.tercero_id <> p_tercero_id)
        AND (cp.grupo_articulo_id  IS NULL OR cp.grupo_articulo_id  = p_grupo_articulo_id)
        AND (cp.tenido_id          IS NULL OR cp.tenido_id          = p_tenido_id)
        AND (cp.fibra              IS NULL OR cp.fibra              = p_fibra)
        AND cp.fyh_elm IS NULL
    ORDER BY
        -- color_x_cliente_id wins over tercero_id (implies the client + specific color)
        (CASE WHEN cp.color_x_cliente_id IS NOT NULL THEN 2 ELSE 0 END
       + CASE WHEN cp.tercero_id         IS NOT NULL THEN 1 ELSE 0 END
       + CASE WHEN cp.grupo_articulo_id  IS NOT NULL THEN 1 ELSE 0 END
       + CASE WHEN cp.tenido_id          IS NOT NULL THEN 1 ELSE 0 END
       + CASE WHEN cp.fibra              IS NOT NULL THEN 1 ELSE 0 END) DESC,
        cp.fyh_cre DESC
    LIMIT 1;
$$;


ALTER FUNCTION doc.fn_get_precio(p_operacion_id smallint, p_color_x_cliente_id integer, p_tercero_id integer, p_grupo_articulo_id integer, p_tenido_id integer, p_fibra smallint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.fn_precio_info(smallint, integer, integer, integer, integer, smallint, boolean)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.fn_precio_info(p_operacion_id smallint, p_color_x_cliente_id integer, p_tercero_id integer, p_grupo_articulo_id integer, p_tenido_id integer, p_fibra smallint, p_flg_antipilling boolean DEFAULT NULL::boolean) RETURNS TABLE(receta_id integer, costo_kg numeric, precio_kg numeric, margen numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'receta', 'doc', 'public'
    AS $$
DECLARE
    v_receta_id  INT;
    v_costo_kg   NUMERIC(10,4);
    v_precio_kg  NUMERIC(10,4);
BEGIN
    IF NOT jwt_has_permission('comercial.ver') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.ver'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- ⚠ NULL-KEY GUARD — TENIDO ONLY, deliberately narrow. This is the RPC
    -- surface: a caller still sending the retired articulo_tipo key, or a
    -- partida predating migration 30, arrives here as NULL. Without a guard
    -- fn_get_precio's `cp.grupo_articulo_id = p_grupo_articulo_id` equality
    -- never holds, so ONLY wildcard rows match and a plausible-looking wrong
    -- price comes back with no error.
    --
    -- Why NOT unconditional: NULL is a LEGITIMATE value here for operations
    -- with no article dimension — the ANTIPILLING lookup passes NULL for
    -- grupo/tenido/fibra by design (see get_precios_partida), and that must keep
    -- resolving its client-level wildcard row. Guarding every op would break it.
    -- TENIDO is the only operation that genuinely requires the key, because it
    -- is the only one routed through fn_familia_precio.
    --
    -- (fn_get_precio itself has no guard on purpose — it is LANGUAGE sql so the
    -- planner can inline it into the per-row billing views. See its header.)
    IF p_grupo_articulo_id IS NULL
       AND p_operacion_id = (SELECT id FROM mes.operacion WHERE codigo = 'TENIDO') THEN
        RAISE EXCEPTION 'fn_precio_info: TENIDO requiere grupo_articulo_id (recibido NULL). '
                        'El key articulo_tipo_id fue retirado en la migración 33.'
            USING ERRCODE = 'null_value_not_allowed';
    END IF;

    -- Find approved recipe matching p_flg_antipilling variant.
    -- NULL → skip recipe lookup (non-TENIDO or ANTIPILLING op).
    IF p_flg_antipilling IS NOT NULL THEN
        SELECT rt.id INTO v_receta_id
        FROM receta.tenido rt
        WHERE rt.color_x_cliente_id = p_color_x_cliente_id
          AND rt.grupo_articulo_id  = p_grupo_articulo_id
          AND rt.fibra               = p_fibra
          AND rt.tenido_id           = p_tenido_id
          AND rt.flg_antipilling     = p_flg_antipilling
          AND rt.flg_produccion      = true
          -- receta.tenido is shared across recipe types; pin to Teñido (7) so a
          -- desmontado/rebaje row on the same keys can't be returned. Matches the
          -- gate in doc.vw_precios_pendientes.
          AND rt.tipo_receta_id      = 7
        LIMIT 1;
    END IF;

    -- Compute chemical cost (NULL if no recipe)
    IF v_receta_id IS NOT NULL THEN
        v_costo_kg := doc.fn_get_costo_receta(v_receta_id);
    END IF;

    -- Fetch current catalog price. TENIDO: normalize the grupo to its pricing
    -- family so the preview shows the price that will actually bill. Recipe
    -- lookup above stays on the LITERAL grupo. No antipilling dimension in the
    -- catalog lookup — both variants bill at the same precio_kg.
    v_precio_kg := doc.fn_get_precio(
        p_operacion_id, p_color_x_cliente_id, p_tercero_id,
        CASE WHEN p_operacion_id = (SELECT id FROM mes.operacion WHERE codigo = 'TENIDO')
             THEN doc.fn_familia_precio(
                    p_grupo_articulo_id,
                    COALESCE(p_tercero_id,
                             (SELECT cxc.tercero_id FROM color_x_cliente cxc WHERE cxc.id = p_color_x_cliente_id)))
             ELSE p_grupo_articulo_id END,
        p_tenido_id, p_fibra
    );

    RETURN QUERY SELECT
        v_receta_id,
        v_costo_kg,
        v_precio_kg,
        CASE
            WHEN v_precio_kg IS NOT NULL AND v_costo_kg IS NOT NULL AND v_precio_kg > 0
            THEN ROUND((v_precio_kg - v_costo_kg) / v_precio_kg, 6)
            ELSE NULL
        END;
END;
$$;


ALTER FUNCTION doc.fn_precio_info(p_operacion_id smallint, p_color_x_cliente_id integer, p_tercero_id integer, p_grupo_articulo_id integer, p_tenido_id integer, p_fibra smallint, p_flg_antipilling boolean) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.fn_refresh_compra_detalle_qtys(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.fn_refresh_compra_detalle_qtys(p_compra_id bigint) RETURNS void
    LANGUAGE sql
    SET search_path TO 'doc', 'inventario', 'public'
    AS $$
    -- Recomputes cantidad_recibida from item_movimientos (ground truth).
    -- All COMPRA_ING movements are anchored to an entrega (even when the
    -- entrega is headless). Line match: compra_detalle_id when pinned,
    -- item_id fallback for single-compra deliveries.
    -- DEV_PROV_EGR movements posted by doc.anular_entrega (reversing a
    -- COMPRA_INGRESO) share the same documento_id as the original entrega,
    -- so they're netted out here. A standalone devolución a proveedor
    -- entrega is never compra_entrega-linked, so it can't leak in.
    UPDATE doc.compra_detalle cd
    SET cantidad_recibida = COALESCE((
        SELECT SUM(im.cantidad * CASE imt.codigo WHEN 'COMPRA_ING' THEN 1 ELSE -1 END)
        FROM inventario.item_movimientos im
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE imt.codigo IN ('COMPRA_ING', 'DEV_PROV_EGR')
          AND im.item_id = cd.item_id
          AND im.documento_tipo = 'entrega'
          AND im.documento_id IN (
              SELECT ed.entrega_id
              FROM doc.entrega_detalle ed
              JOIN doc.compra_entrega ce ON ce.entrega_id = ed.entrega_id
              WHERE ce.compra_id = p_compra_id
                AND (ed.compra_detalle_id = cd.id
                     OR (ed.compra_detalle_id IS NULL AND ed.item_id = cd.item_id))
          )
    ), 0)
    WHERE cd.compra_id = p_compra_id;
$$;


ALTER FUNCTION doc.fn_refresh_compra_detalle_qtys(p_compra_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.fn_trg_factura_prevent_hard_delete()
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.fn_trg_factura_prevent_hard_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.estado IN ('emitida', 'anulada') THEN
        RAISE EXCEPTION
            'Factura id=% (%) no puede eliminarse: es un documento tributario emitido. Use una Nota de Crédito para anularla.',
            OLD.id, OLD.estado
            USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN OLD;
END;
$$;


ALTER FUNCTION doc.fn_trg_factura_prevent_hard_delete() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.get_compra(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.get_compra(p_compra_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'doc', 'public'
    AS $$
SELECT jsonb_build_object(
    'id',          c.id,
    'tercero_id',  c.tercero_id,
    'proveedor',   t.nombre,
    'fecha',       c.fecha,
    'observacion', c.observacion,
    'fyh_elm',     c.fyh_elm,
    'fyh_cre',     c.fyh_cre,
    'detalle', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
            'id',                cd.id,
            'item_id',           cd.item_id,
            'item_codigo',       i.codigo,
            'item_nombre',       i.nombre,
            'cantidad',          cd.cantidad,
            'precio_unitario',   cd.precio_unitario,
            'cantidad_recibida', cd.cantidad_recibida
        ) ORDER BY cd.id)
        FROM doc.compra_detalle cd
        JOIN item i ON i.id = cd.item_id
        WHERE cd.compra_id = c.id
    ), '[]'::jsonb),
    'entregas', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
            'entrega_id', gr.id,
            'serie',            gr.serie,
            'correlativo',      gr.correlativo,
            'fecha_emision',    gr.fecha_emision,
            'tipo',             grt.nombre
        ) ORDER BY gr.fecha_emision, gr.id)
        FROM doc.compra_entrega cgr
        JOIN doc.entrega gr         ON gr.id = cgr.entrega_id
        JOIN doc.entrega_tipo grt   ON grt.id = gr.entrega_tipo_id
        WHERE cgr.compra_id = c.id
    ), '[]'::jsonb),
    'facturas', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
            'factura_proveedor_id', fp.id,
            'serie',                fp.serie,
            'numero',               fp.numero,
            'fecha_emision',        fp.fecha_emision,
            'total',                fp.total,
            'moneda',               fp.moneda,
            'estado_pago',          fp.estado_pago,
            'observacion',          fp.observacion
        ) ORDER BY fp.fecha_emision, fp.id)
        FROM doc.compra_factura_proveedor cfp
        JOIN doc.factura_proveedor fp ON fp.id = cfp.factura_proveedor_id
        WHERE cfp.compra_id = c.id
    ), '[]'::jsonb)
)
FROM doc.compra c
JOIN tercero t ON t.id = c.tercero_id
WHERE c.id = p_compra_id;
$$;


ALTER FUNCTION doc.get_compra(p_compra_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.get_despacho_partida(bigint[])
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.get_despacho_partida(p_partida_ids bigint[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'doc', 'mes', 'inventario', 'public'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id     int := get_user_id();
    v_n_terceros int;
    v_tercero_id int;
    v_cliente    text;
    v_result     JSONB;
BEGIN
    IF NOT jwt_has_permission('comercial.ver') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.ver'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT COUNT(DISTINCT p.tercero_id)
    INTO   v_n_terceros
    FROM   mes.partida p
    WHERE  p.id = ANY(p_partida_ids);

    IF v_n_terceros = 0 THEN
        RAISE EXCEPTION 'No se encontraron las partidas indicadas';
    END IF;
    IF v_n_terceros > 1 THEN
        RAISE EXCEPTION 'Las partidas seleccionadas pertenecen a distintos clientes';
    END IF;

    SELECT p.tercero_id, t.nombre
    INTO   v_tercero_id, v_cliente
    FROM   mes.partida p
    JOIN   tercero t ON t.id = p.tercero_id
    WHERE  p.id = ANY(p_partida_ids)
    LIMIT  1;

    SELECT jsonb_build_object(
        'tercero_id', v_tercero_id,
        'cliente',    v_cliente,
        'partidas',   (
            SELECT jsonb_agg(
                EXTRACT(YEAR FROM fyh_cre)::TEXT || '-' || LPAD(numero::TEXT, 4, '0')
                ORDER BY fyh_cre
            )
            FROM mes.partida WHERE id = ANY(p_partida_ids)
        ),
        'entregas', COALESCE((
            SELECT jsonb_agg(
                jsonb_build_object(
                    'entrega_tipo_id',     grt.id,
                    'entrega_tipo_codigo', grt.codigo,
                    'entrega_tipo_nombre', grt.nombre,
                    'tercero_id',          v_tercero_id,
                    'rolls',               lotes_agg.roll_count,
                    'kg_total',            ROUND(lotes_agg.kg_total::NUMERIC, 2),
                    'items',               lotes_agg.items
                )
                ORDER BY grt.codigo
            )
            FROM (
                SELECT
                    CASE WHEN l.propietario_id = 1
                         THEN 'VENTA_EGRESO'
                         ELSE 'DESPACHO_CLIENTE'
                    END                         AS tipo_codigo,
                    COUNT(*)                    AS roll_count,
                    SUM(sa.cantidad_disponible) AS kg_total,
                    jsonb_agg(
                        jsonb_build_object(
                            'item_id',              l.item_id,
                            'lote_id',              l.id,
                            'ubicacion_id',         sa.ubicacion_id,
                            -- Producing partida (root or rework child) — required by
                            -- doc.registrar_despacho's items[].partida_id (attributes the
                            -- charge). Not part of the GROUP BY below (grouping stays by
                            -- ownership only), so multi-partida dispatch is unaffected.
                            'partida_id',           pp.partida_id,
                            -- Exact balance, not rounded: this value is echoed straight back
                            -- into crear_entrega as the requested cantidad, so rounding up
                            -- (e.g. 12.3467 → 12.35) would request more than is in stock and
                            -- trip the "Stock insuficiente" check on freshly-produced lots.
                            'cantidad',             sa.cantidad_disponible,
                            'propietario_id',       l.propietario_id,
                            'color_x_cliente_id',   lrd.color_x_cliente_id,
                            'color',                vc.color,
                            'tono',                 vc.tono,
                            'color_hex',            vc.color_x_cliente_hex,
                            'ancho',                lrd.ancho,
                            'articulo_id',          ird.articulo_id,
                            'articulo_nombre',      art.nombre,
                            'entrega_serie',        ent.serie,
                            'entrega_correlativo',  ent.correlativo
                        )
                        ORDER BY l.id
                    ) AS items
                FROM mes.partida_paso pp
                JOIN mes.partida_paso_ejecucion pe  ON pe.partida_paso_id = pp.id
                                                    AND pe.estado = 'COMPLETADO'
                JOIN inventario.lote l
                    ON  l.documento_tipo = 'partida_paso_ejecucion'
                    AND l.documento_id   = pe.id
                JOIN inventario.lote_rollo_detalle lrd
                    ON  lrd.lote_id    = l.id
                    AND lrd.flg_tenido = true
                LEFT JOIN vw_colores vc             ON vc.color_x_cliente_id = lrd.color_x_cliente_id
                LEFT JOIN item_rollo_detalle ird            ON ird.item_id   = l.item_id
                LEFT JOIN articulo art              ON art.id                = ird.articulo_id
                LEFT JOIN doc.entrega ent           ON ent.id               = lrd.entrega_id
                JOIN inventario.vw_stock_lotes_ubicacion sa ON sa.lote_id = l.id
                WHERE pp.partida_id = ANY(p_partida_ids)
                  AND l.estado_calidad = 'APROBADO'
                GROUP BY
                    CASE WHEN l.propietario_id = 1 THEN 'VENTA_EGRESO' ELSE 'DESPACHO_CLIENTE' END
            ) lotes_agg
            JOIN doc.entrega_tipo grt ON grt.codigo = lotes_agg.tipo_codigo
        ), '[]'::jsonb)
    )
    INTO v_result;

    IF (v_result->>'entregas') = '[]' THEN
        RAISE EXCEPTION 'Las partidas seleccionadas no tienen rollos teñidos con stock disponible para despachar';
    END IF;

    RETURN v_result;
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in get_despacho_partida - User: %, partidas: %, Error: %',
        v_usr_id, p_partida_ids, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.get_despacho_partida(p_partida_ids bigint[]) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.get_entrega(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.get_entrega(p_entrega_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc', 'inventario'
    AS $$
SELECT jsonb_build_object(
    'id', gr.id,
    'entrega_tipo_id', gr.entrega_tipo_id,
    'tipo_codigo', grt.codigo,
    'tipo_nombre', grt.nombre,
    'flg_emitida', grt.flg_emitida,
    'fyh_elm', gr.fyh_elm,
    'serie', gr.serie,
    'correlativo', gr.correlativo,
    'fecha_emision', gr.fecha_emision,
    'fecha_recepcion', gr.fecha_recepcion,
    'tercero_id', gr.tercero_id,
    'tercero_codigo', t.codigo,
    'tercero_nombre', t.nombre,
    'tercero_ruc', t.ruc,
    'emisor',        CASE WHEN grt.flg_emitida THEN 'Manufacturas la Real' ELSE t.nombre END,
    'emisor_ruc',    CASE WHEN grt.flg_emitida THEN NULL                   ELSE t.ruc   END,
    'receptor',      CASE WHEN grt.flg_emitida THEN t.nombre ELSE 'Manufacturas la Real' END,
    'receptor_ruc',  CASE WHEN grt.flg_emitida THEN t.ruc   ELSE NULL                   END,
    'fyh_cre', gr.fyh_cre,
    'detalles', (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', grd.id,
                'item_id', grd.item_id,
                'item_codigo', i.codigo,
                'item_nombre', i.nombre,
                'cantidad', grd.cantidad,
                'unidad_codigo', u.codigo,
                'lote_id', grd.lote_id,
                'ubicacion_id', grd.ubicacion_id,
                'ubicacion_codigo', ub.codigo,
                'almacen_nombre', al.nombre,
                'saldo_actual', (
                    SELECT ROUND(SUM(sa.cantidad_disponible)::NUMERIC, 4)
                    FROM inventario.vw_stock_lotes sa
                    WHERE sa.lote_id = grd.lote_id
                )
            ) ORDER BY grd.id
        ), '[]'::jsonb)
        FROM doc.entrega_detalle grd
        LEFT JOIN item i ON i.id = grd.item_id
        LEFT JOIN unidad u ON u.id = i.unidad_id
        LEFT JOIN inventario.ubicacion ub ON ub.id = grd.ubicacion_id
        LEFT JOIN inventario.almacen al ON al.id = ub.almacen_id
        WHERE grd.entrega_id = gr.id
    ),
    'compras', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
            'compra_id',   c.id,
            'fecha',       c.fecha,
            'observacion', c.observacion,
            'fyh_elm',     c.fyh_elm
        ) ORDER BY c.fecha, c.id)
        FROM doc.compra_entrega cgr
        JOIN doc.compra c ON c.id = cgr.compra_id
        WHERE cgr.entrega_id = gr.id
    ), '[]'::jsonb)
)
FROM doc.entrega gr
LEFT JOIN doc.entrega_tipo grt ON grt.id = gr.entrega_tipo_id
LEFT JOIN tercero t ON t.id = gr.tercero_id
WHERE gr.id = p_entrega_id;
$$;


ALTER FUNCTION doc.get_entrega(p_entrega_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.get_entrega_anulacion_preview(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.get_entrega_anulacion_preview(p_entrega_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'doc', 'inventario', 'mes', 'public'
    AS $$
DECLARE
    v_entrega RECORD;
    v_result  jsonb;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT gr.id, gr.fyh_elm, grt.flg_emitida, grt.codigo AS tipo_codigo
    INTO v_entrega
    FROM doc.entrega gr
    JOIN doc.entrega_tipo grt ON grt.id = gr.entrega_tipo_id
    WHERE gr.id = p_entrega_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Guía #% no encontrada.', p_entrega_id;
    END IF;

    SELECT jsonb_build_object(
        'entrega_id',   p_entrega_id,
        'ya_anulada',   v_entrega.fyh_elm IS NOT NULL,
        'flg_emitida',  v_entrega.flg_emitida,

        'bloqueo_factura', CASE WHEN v_entrega.flg_emitida THEN (
            SELECT jsonb_agg(DISTINCT f.id)
            FROM doc.factura_detalle fd
            JOIN doc.factura f ON f.id = fd.factura_id AND f.estado <> 'anulada'
            WHERE fd.entrega_id = p_entrega_id
        ) END,

        'bloqueo_movimiento_posterior', CASE WHEN NOT v_entrega.flg_emitida THEN (
            -- PESAJE_POS/PESAJE_NEG movements (original + any reversal posted
            -- by inventario.anular_pesaje) are excluded here: they're pesaje-
            -- domain history, never deleted per this schema's audit-trail
            -- convention, and are resolved via bloqueo_pesaje_activo below
            -- (current pesaje state) rather than by presence of old movements.
            SELECT jsonb_agg(DISTINCT l.id)
            FROM inventario.lote l
            JOIN inventario.item_movimientos im ON im.lote_id = l.id
            JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
            WHERE l.documento_tipo = 'entrega' AND l.documento_id = p_entrega_id
              AND l.fyh_elm IS NULL
              AND NOT (im.documento_tipo = 'entrega' AND im.documento_id = p_entrega_id)
              AND imt.codigo NOT IN ('PESAJE_POS', 'PESAJE_NEG')
        ) END,

        'bloqueo_pesaje_activo', CASE WHEN NOT v_entrega.flg_emitida THEN (
            -- Lotes still weighed (inventario.pesaje not yet reversed via
            -- inventario.anular_pesaje). Must be cleared before anulación.
            SELECT jsonb_agg(DISTINCT l.id)
            FROM inventario.lote l
            JOIN inventario.pesaje ps ON ps.lote_id = l.id
            WHERE l.documento_tipo = 'entrega' AND l.documento_id = p_entrega_id
              AND l.fyh_elm IS NULL
        ) END,

        'partidas_afectadas', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'partida_id',         p.id,
                'numero',             p.numero,
                'estado_produccion',  p.estado_produccion,
                'rollos_de_esta_guia', sub.n_rollos,
                'tiene_pesaje', EXISTS (
                    SELECT 1 FROM mes.partida_componente pc2
                    JOIN inventario.pesaje ps ON ps.lote_id = pc2.lote_id
                    WHERE pc2.partida_id = p.id AND pc2.lote_id IS NOT NULL
                ),
                'tiene_ejecucion', EXISTS (
                    SELECT 1 FROM mes.partida_paso_ejecucion pe
                    JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
                    WHERE pp.partida_id = p.id
                )
            ))
            FROM (
                SELECT pc.partida_id, COUNT(*) AS n_rollos
                FROM mes.partida_componente pc
                JOIN inventario.lote l ON l.id = pc.lote_id
                WHERE l.documento_tipo = 'entrega'
                  AND l.documento_id   = p_entrega_id
                  AND pc.lote_id IS NOT NULL
                GROUP BY pc.partida_id
            ) sub
            JOIN mes.partida p ON p.id = sub.partida_id
            WHERE p.estado_produccion NOT IN ('CANCELADA', 'TECO', 'CERRADA')
        ), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;
END;
$$;


ALTER FUNCTION doc.get_entrega_anulacion_preview(p_entrega_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.get_factura_cliente(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.get_factura_cliente(p_factura_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'doc', 'mes', 'public'
    AS $$
SELECT jsonb_build_object(
    'id',               f.id,
    'tipo_comprobante', f.tipo_comprobante,
    'serie',            f.serie,
    'numero',           f.numero,
    'tercero_id',       f.tercero_id,
    'cliente',          t.nombre,
    'fecha_emision',    f.fecha_emision,
    'fecha_vencimiento',f.fecha_vencimiento,
    'moneda',           f.moneda,
    'tipo_cambio',      f.tipo_cambio,
    'subtotal',         f.subtotal,
    'igv',              f.igv,
    'total',            f.total,
    'estado',           f.estado,
    'observacion',      f.observacion,
    'lineas', COALESCE((
        SELECT jsonb_agg(
            jsonb_build_object(
                'id',               fd.id,
                'descripcion',      fd.descripcion,
                'operacion_id',     fd.operacion_id,
                'operacion',        o.nombre,
                'es_antipilling',   fd.es_antipilling,
                'partida_id',       fd.partida_id,
                'entrega_id', fd.entrega_id,
                'cantidad',         fd.cantidad,
                'unidad',           u.codigo,
                'precio_unitario',  fd.precio_unitario,
                'igv_porcentaje',   fd.igv_porcentaje,
                'subtotal_linea',   fd.subtotal_linea,
                'igv_linea',        fd.igv_linea,
                'total_linea',      fd.total_linea
            ) ORDER BY fd.id
        )
        FROM doc.factura_detalle fd
        LEFT JOIN mes.operacion o ON o.id = fd.operacion_id
        LEFT JOIN unidad u        ON u.id = fd.unidad_id
        WHERE fd.factura_id = f.id
    ), '[]'::jsonb)
)
FROM doc.factura f
JOIN tercero t ON t.id = f.tercero_id
WHERE f.id = p_factura_id;
$$;


ALTER FUNCTION doc.get_factura_cliente(p_factura_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.get_factura_proveedor(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.get_factura_proveedor(p_factura_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'doc', 'public'
    AS $$
SELECT jsonb_build_object(
    'id',                fp.id,
    'tercero_id',        fp.tercero_id,
    'proveedor',         t.nombre,
    'serie',             fp.serie,
    'numero',            fp.numero,
    'fecha_emision',     fp.fecha_emision,
    'fecha_vencimiento', fp.fecha_vencimiento,
    'tipo_pago',         fp.tipo_pago,
    'moneda',            fp.moneda,
    'tipo_cambio',       fp.tipo_cambio,
    'subtotal',          fp.subtotal,
    'igv',               fp.igv,
    'total',             fp.total,
    'estado_pago',       fp.estado_pago,
    'observacion',       fp.observacion,
    'fyh_cre',           fp.fyh_cre,
    'lineas', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
            'id',              fpd.id,
            'item_id',         fpd.item_id,
            'item_codigo',     i.codigo,
            'item_nombre',     i.nombre,
            'cantidad',        fpd.cantidad,
            'precio_unitario', fpd.precio_unitario,
            'igv_porcentaje',  fpd.igv_porcentaje,
            'subtotal_linea',  fpd.subtotal_linea,
            'igv_linea',       fpd.igv_linea,
            'total_linea',     fpd.total_linea
        ) ORDER BY fpd.id)
        FROM doc.factura_proveedor_detalle fpd
        JOIN item i ON i.id = fpd.item_id
        WHERE fpd.factura_proveedor_id = fp.id
    ), '[]'::jsonb),
    'letras', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
            'letra_id',           l.id,
            'numero',             l.numero,
            'monto',              l.monto,
            'monto_aplicado',     lf.monto_aplicado,
            'fecha_vencimiento',  l.fecha_vencimiento,
            'fecha_pago',         l.fecha_pago,
            'banco',              l.banco,
            'estado',             l.estado
        ) ORDER BY l.fecha_vencimiento, l.id)
        FROM doc.letra_factura lf
        JOIN doc.letra l ON l.id = lf.letra_id
        WHERE lf.factura_proveedor_id = fp.id
          AND l.estado != 'anulada'
    ), '[]'::jsonb),
    'compras', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
            'compra_id',   c.id,
            'fecha',       c.fecha,
            'observacion', c.observacion,
            'monto_total', COALESCE((
                SELECT SUM(cd.cantidad * cd.precio_unitario)
                FROM doc.compra_detalle cd WHERE cd.compra_id = c.id
            ), 0),
            'total_items', COALESCE((
                SELECT COUNT(*) FROM doc.compra_detalle cd WHERE cd.compra_id = c.id
            ), 0),
            'fyh_elm',     c.fyh_elm
        ) ORDER BY c.fecha, c.id)
        FROM doc.compra_factura_proveedor cfp
        JOIN doc.compra c ON c.id = cfp.compra_id
        WHERE cfp.factura_proveedor_id = fp.id
    ), '[]'::jsonb)
)
FROM doc.factura_proveedor fp
JOIN tercero t ON t.id = fp.tercero_id
WHERE fp.id = p_factura_id;
$$;


ALTER FUNCTION doc.get_factura_proveedor(p_factura_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.get_guia_remision(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.get_guia_remision(p_guia_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc', 'inventario'
    AS $$
SELECT jsonb_build_object(
    'id', gr.id,
    'guia_remision_tipo_id', gr.guia_remision_tipo_id,
    'tipo_codigo', grt.codigo,
    'tipo_nombre', grt.nombre,
    'flg_emitida', grt.flg_emitida,
    'fyh_elm', gr.fyh_elm,
    'serie', gr.serie,
    'correlativo', gr.correlativo,
    'fecha_emision', gr.fecha_emision,
    'fecha_recepcion', gr.fecha_recepcion,
    'tercero_id', gr.tercero_id,
    'tercero_codigo', t.codigo,
    'tercero_nombre', t.nombre,
    'tercero_ruc', t.ruc,
    'emisor',        CASE WHEN grt.flg_emitida THEN 'Manufacturas la Real' ELSE t.nombre END,
    'emisor_ruc',    CASE WHEN grt.flg_emitida THEN NULL                   ELSE t.ruc   END,
    'receptor',      CASE WHEN grt.flg_emitida THEN t.nombre ELSE 'Manufacturas la Real' END,
    'receptor_ruc',  CASE WHEN grt.flg_emitida THEN t.ruc   ELSE NULL                   END,
    'fyh_cre', gr.fyh_cre,
    'detalles', (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', grd.id,
                'item_id', grd.item_id,
                'item_codigo', i.codigo,
                'item_nombre', i.nombre,
                'cantidad', grd.cantidad,
                'unidad_codigo', u.codigo,
                'lote_id', grd.lote_id,
                'ubicacion_id', grd.ubicacion_id,
                'ubicacion_codigo', ub.codigo,
                'almacen_nombre', al.nombre,
                'saldo_actual', (
                    SELECT ROUND(SUM(sa.cantidad_disponible)::NUMERIC, 4)
                    FROM inventario.vw_stock_lotes sa
                    WHERE sa.lote_id = grd.lote_id
                )
            ) ORDER BY grd.id
        ), '[]'::jsonb)
        FROM doc.guia_remision_detalle grd
        LEFT JOIN item i ON i.id = grd.item_id
        LEFT JOIN unidad u ON u.id = i.unidad_id
        LEFT JOIN inventario.ubicacion ub ON ub.id = grd.ubicacion_id
        LEFT JOIN inventario.almacen al ON al.id = ub.almacen_id
        WHERE grd.guia_remision_id = gr.id
    ),
    'compras', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
            'compra_id',   c.id,
            'fecha',       c.fecha,
            'observacion', c.observacion,
            'fyh_elm',     c.fyh_elm
        ) ORDER BY c.fecha, c.id)
        FROM doc.compra_guia_remision cgr
        JOIN doc.compra c ON c.id = cgr.compra_id
        WHERE cgr.guia_remision_id = gr.id
    ), '[]'::jsonb)
)
FROM doc.guia_remision gr
LEFT JOIN doc.guia_remision_tipo grt ON grt.id = gr.guia_remision_tipo_id
LEFT JOIN tercero t ON t.id = gr.tercero_id
WHERE gr.id = p_guia_id;
$$;


ALTER FUNCTION doc.get_guia_remision(p_guia_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.get_letra(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.get_letra(p_letra_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'doc', 'public'
    AS $$
SELECT jsonb_build_object(
    'id',                l.id,
    'tercero_id',        l.tercero_id,
    'proveedor',         t.nombre,
    'numero',            l.numero,
    'monto',             l.monto,
    'fecha_giro',        l.fecha_giro,
    'fecha_vencimiento', l.fecha_vencimiento,
    'fecha_pago',        l.fecha_pago,
    'banco',             l.banco,
    'estado',            l.estado,
    'observacion',       l.observacion,
    'facturas', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
            'factura_proveedor_id', fp.id,
            'serie',                fp.serie,
            'numero',               fp.numero,
            'fecha_emision',        fp.fecha_emision,
            'total',                fp.total,
            'moneda',               fp.moneda,
            'monto_aplicado',       lf.monto_aplicado,
            'estado_pago',          fp.estado_pago
        ) ORDER BY fp.fecha_emision, fp.id)
        FROM doc.letra_factura lf
        JOIN doc.factura_proveedor fp ON fp.id = lf.factura_proveedor_id
        WHERE lf.letra_id = l.id
    ), '[]'::jsonb)
)
FROM doc.letra l
JOIN tercero t ON t.id = l.tercero_id
WHERE l.id = p_letra_id;
$$;


ALTER FUNCTION doc.get_letra(p_letra_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.get_orden_servicio(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.get_orden_servicio(p_os_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc', 'inventario'
    AS $$
SELECT jsonb_build_object(
    'id',               os.id,
    'tercero_id',       os.tercero_id,
    'tercero_nombre',   t.nombre,
    'tercero_ruc',      t.ruc,
    'serie',            os.serie,
    'correlativo',      os.correlativo,
    'fecha_emision',    os.fecha_emision,
    'fecha_entrega',    os.fecha_entrega,
    'rendimiento',      os.rendimiento,
    'ancho',            os.ancho,
    'flg_antipilling',  os.flg_antipilling,
    'flg_urgente',      os.flg_urgente,
    'observacion',      os.observacion,
    'factura',          os.factura,
    'fyh_cre',          os.fyh_cre,
    'lineas', (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id',                   osd.id,
                'linea',                osd.linea,
                'articulo_id',          ird.articulo_id,
                'articulo_nombre',      a.nombre,
                'malla',                osd.malla,
                'cantidad',             osd.cantidad,
                'cantidad_recibida',    osd.cantidad_recibida,
                'color_x_cliente_id',   osd.color_x_cliente_id,
                'color',                vc.color,
                'tono',                 vc.tono,
                'color_hex',            vc.color_x_cliente_hex,
                'tenido_id',            osd.tenido_id,
                'tenido',               ten.tenido,
                'flg_doble_bolsa',      osd.flg_doble_bolsa
            ) ORDER BY osd.linea
        ), '[]'::jsonb)
        FROM doc.orden_servicio_detalle osd
        LEFT JOIN item_rollo_detalle ird ON ird.item_id = osd.item_id
        LEFT JOIN articulo          a   ON a.id   = ird.articulo_id
        LEFT JOIN vw_colores        vc  ON vc.color_x_cliente_id = osd.color_x_cliente_id
        LEFT JOIN tenido            ten ON ten.id  = osd.tenido_id
        WHERE osd.orden_servicio_id = os.id
    ),
    'rollos', (
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'lote_id',          l.id,
                'codigo',           EXTRACT(YEAR FROM l.fyh_cre)::int % 100
                                    || '-' || LPAD(l.secuencia::text, 5, '0'),
                'cantidad',         l.cantidad,
                'flg_pesado',       EXISTS (
                                        SELECT 1 FROM inventario.pesaje p
                                        WHERE p.lote_id = l.id
                                    ),
                'item_id',          l.item_id,
                'detalle_id',       im.documento_linea_id,
                'factura_hilo',     lrd.factura_hilo
            ) ORDER BY l.id
        ), '[]'::jsonb)
        FROM inventario.lote_rollo_detalle lrd
        JOIN inventario.lote l ON l.id = lrd.lote_id AND l.fyh_elm IS NULL
        JOIN inventario.item_movimientos im
            ON im.lote_id          = l.id
           AND im.documento_tipo   = 'orden_servicio'
           AND im.documento_id     = os.id
        WHERE lrd.orden_servicio_id = os.id
    )
)
FROM doc.orden_servicio os
LEFT JOIN tercero t ON t.id = os.tercero_id
WHERE os.id = p_os_id
  AND os.flg_elm = false;
$$;


ALTER FUNCTION doc.get_orden_servicio(p_os_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.get_precio_info_partida(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.get_precio_info_partida(p_partida_id bigint) RETURNS TABLE(operacion_id smallint, operacion text, es_antipilling boolean, receta_id integer, costo_kg numeric, precio_kg numeric, margen numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'receta', 'doc', 'mes', 'public'
    AS $$
DECLARE
    v_p          mes.partida%ROWTYPE;
    v_fibra      SMALLINT;
BEGIN
    IF NOT jwt_has_permission('comercial.ver') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.ver'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO v_p FROM mes.partida WHERE id = p_partida_id AND fyh_elm IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Partida % no encontrada', p_partida_id;
    END IF;

    SELECT ar.fibra::SMALLINT INTO v_fibra
    FROM mes.partida_componente pc
    JOIN inventario.lote l      ON l.id = pc.lote_id
    JOIN item_rollo_detalle ird ON ird.item_id = l.item_id
    JOIN articulo ar            ON ar.id = ird.articulo_id
    WHERE pc.partida_id = p_partida_id AND pc.lote_id IS NOT NULL
    LIMIT 1;

    -- Base line per completed operacion
    RETURN QUERY
    SELECT
        op.id::SMALLINT,
        op.nombre,
        false,
        (pi).*
    FROM mes.partida_paso pp
    JOIN mes.operacion op ON op.id = pp.operacion_id
    JOIN LATERAL doc.fn_precio_info(
        op.id::SMALLINT,
        v_p.color_x_cliente_id,
        v_p.tercero_id,
        v_p.grupo_articulo_id,
        CASE WHEN op.codigo = 'TENIDO' THEN v_p.tenido_id ELSE NULL END,
        v_fibra,
        CASE WHEN op.codigo = 'TENIDO' THEN v_p.flg_antipilling ELSE NULL END
    ) pi ON true
    WHERE pp.partida_id = p_partida_id
      AND EXISTS (
          SELECT 1 FROM mes.partida_paso_ejecucion pe
          WHERE pe.partida_paso_id = pp.id AND pe.estado = 'COMPLETADO'
      );

    -- Antipilling surcharge line (when TENIDO completed + flag set)
    IF v_p.flg_antipilling THEN
        RETURN QUERY
        SELECT
            antipil_op.id::SMALLINT,
            'Antipilling'::TEXT,
            true,
            (pi).*
        FROM mes.operacion antipil_op
        JOIN LATERAL doc.fn_precio_info(
            antipil_op.id::SMALLINT,
            NULL, v_p.tercero_id,
            NULL, NULL, NULL, NULL
        ) pi ON true
        WHERE antipil_op.codigo = 'ANTIPILLING'
          AND EXISTS (
              SELECT 1 FROM mes.partida_paso pp2
              JOIN mes.operacion op2 ON op2.id = pp2.operacion_id AND op2.codigo = 'TENIDO'
              JOIN mes.partida_paso_ejecucion pe2 ON pe2.partida_paso_id = pp2.id AND pe2.estado = 'COMPLETADO'
              WHERE pp2.partida_id = p_partida_id
          );
    END IF;
END;
$$;


ALTER FUNCTION doc.get_precio_info_partida(p_partida_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.get_precios_partida(bigint[])
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.get_precios_partida(p_partida_ids bigint[]) RETURNS TABLE(partida_id bigint, operacion_id smallint, operacion text, es_antipilling boolean, precio_kg numeric, sin_precio boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'doc', 'mes', 'public'
    AS $$
    WITH partidas AS (
        SELECT
            p.id                          AS partida_id,
            p.color_x_cliente_id,
            p.tercero_id,
            p.tenido_id,
            p.flg_antipilling,
            p.grupo_articulo_id           AS grupo_articulo_id,
            p.fibra::smallint             AS fibra,
            -- Distinct completed operaciones across ALL ops for this partida (repartida included)
            ARRAY(
                SELECT DISTINCT opp.operacion_id
                FROM mes.partida_paso opp
                WHERE opp.partida_id = p.id
                  AND EXISTS (
                      SELECT 1 FROM mes.partida_paso_ejecucion pe_c
                      WHERE pe_c.partida_paso_id = opp.id AND pe_c.estado = 'COMPLETADO'
                  )
            ) AS operacion_ids
        FROM mes.partida p
        WHERE p.id = ANY(p_partida_ids) AND p.fyh_elm IS NULL
    ),
    lineas AS (
        -- Base line per completed operacion
        SELECT
            pt.partida_id,
            op.id::smallint                         AS operacion_id,
            op.nombre                               AS operacion,
            false                                   AS es_antipilling,
            doc.fn_get_precio(
                op.id::smallint,
                pt.color_x_cliente_id,
                pt.tercero_id,
                -- TENIDO: normalize the grupo to its pricing family (client-aware)
                CASE WHEN op.codigo = 'TENIDO'
                     THEN doc.fn_familia_precio(pt.grupo_articulo_id, pt.tercero_id)
                     ELSE pt.grupo_articulo_id END,
                CASE WHEN op.codigo = 'TENIDO' THEN pt.tenido_id ELSE NULL END,
                pt.fibra
            )                                       AS precio_kg
        FROM partidas pt
        JOIN LATERAL unnest(pt.operacion_ids) AS oid ON true
        JOIN mes.operacion op ON op.id = oid

        UNION ALL

        -- Antipilling service charge line: billed when TENIDO completed + partida has flag.
        -- Client-level only — only tercero_id matters (Urban vs others).
        SELECT
            pt.partida_id,
            antipil_op.id::smallint,
            'Antipilling',
            true,
            doc.fn_get_precio(
                antipil_op.id::smallint,
                NULL,
                pt.tercero_id,
                NULL, NULL, NULL
            )
        FROM partidas pt
        JOIN mes.operacion antipil_op ON antipil_op.codigo = 'ANTIPILLING'
        JOIN mes.operacion tenido_op  ON tenido_op.codigo  = 'TENIDO'
        WHERE pt.flg_antipilling = true
          AND tenido_op.id = ANY(pt.operacion_ids)
    )
    SELECT
        l.partida_id,
        l.operacion_id,
        l.operacion,
        l.es_antipilling,
        l.precio_kg,
        (l.precio_kg IS NULL) AS sin_precio
    FROM lineas l
    ORDER BY l.partida_id, l.operacion_id, l.es_antipilling;
$$;


ALTER FUNCTION doc.get_precios_partida(p_partida_ids bigint[]) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.ingresar_orden_servicio(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.ingresar_orden_servicio(p_datos jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_usr_id            INT    := get_user_id();
    v_os_id             BIGINT := (p_datos->>'orden_servicio_id')::BIGINT;
    v_os                RECORD;
    v_serv_ing_tipo_id  SMALLINT;
    v_doc_mov_id        BIGINT;
    v_ubicacion_id      INT;
    v_fecha_mov         TIMESTAMPTZ;
    v_linea             jsonb;
    v_detalle_id        BIGINT;
    v_extra             INT;
    v_item_id           INT;
    v_malla             TEXT;
    v_factura_hilo      TEXT;
    v_peso_por_rollo    NUMERIC;
    v_new_lote_id       INT;
    v_recibida          INT;
    v_ordenada          INT;
    i                   INT;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('ingresar_orden_servicio', v_usr_id, p_datos);

    SELECT * INTO v_os FROM doc.orden_servicio
    WHERE id = v_os_id AND flg_elm = false;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'orden_servicio % no existe o fue eliminada.', v_os_id;
    END IF;

    SELECT id INTO STRICT v_serv_ing_tipo_id
    FROM inventario.item_movimiento_tipo WHERE codigo = 'SERV_ING';

    IF (p_datos->>'ubicacion_id') IS NOT NULL THEN
        v_ubicacion_id := (p_datos->>'ubicacion_id')::INT;
    ELSE
        SELECT ub.id INTO STRICT v_ubicacion_id
        FROM inventario.ubicacion ub
        JOIN inventario.almacen alm ON alm.id = ub.almacen_id
        WHERE alm.codigo = 'ALM_CRU' LIMIT 1;
    END IF;

    v_fecha_mov  := COALESCE((p_datos->>'fecha_recepcion')::TIMESTAMPTZ, now());
    v_doc_mov_id := nextval('inventario.mov_doc_seq');

    FOR v_linea IN SELECT jsonb_array_elements(p_datos->'lineas')
    LOOP
        v_detalle_id := (v_linea->>'detalle_id')::BIGINT;
        v_extra      := (v_linea->>'cantidad_rollos')::INT;

        IF v_extra IS NULL OR v_extra <= 0 THEN
            RAISE EXCEPTION 'Línea %: cantidad_rollos debe ser > 0.', v_detalle_id;
        END IF;

        SELECT osd.item_id, osd.malla
        INTO v_item_id, v_malla
        FROM doc.orden_servicio_detalle osd
        JOIN item it_      ON it_.id = osd.item_id
        JOIN item_tipo itp ON itp.id = it_.item_tipo_id
        WHERE osd.id = v_detalle_id
          AND osd.orden_servicio_id = v_os_id
          AND itp.codigo = 'ROLLO';
        IF NOT FOUND THEN
            RAISE EXCEPTION 'detalle % no es una línea ROLLO de la orden_servicio %.', v_detalle_id, v_os_id;
        END IF;

        -- peso_total optional; 0.1 kg/roll sentinel until weighing corrects it
        v_peso_por_rollo := COALESCE(
            (v_linea->>'peso_total')::NUMERIC / NULLIF(v_extra, 0),
            0.1
        );

        -- factura_hilo line-level fallback (used when no grupos)
        v_factura_hilo := v_linea->>'factura_hilo';
        IF v_factura_hilo IS NULL THEN
            SELECT lrd.factura_hilo INTO v_factura_hilo
            FROM inventario.lote_rollo_detalle lrd
            JOIN inventario.item_movimientos im ON im.lote_id = lrd.lote_id
            WHERE im.documento_tipo     = 'orden_servicio'
              AND im.documento_id       = v_os_id
              AND im.documento_linea_id = v_detalle_id
            LIMIT 1;
        END IF;

        -- Build normalised groups: [{cantidad_rollos, factura_hilo}, ...]
        -- If caller supplies "grupos" array, validate its sum; otherwise treat
        -- the whole line as one group using the line-level factura_hilo.
        DECLARE
            v_grupos       JSONB;
            v_grupo        JSONB;
            v_grupo_cant   INT;
            v_grupo_fac    TEXT;
            v_grupos_sum   INT := 0;
        BEGIN
            v_grupos := v_linea->'grupos';

            IF v_grupos IS NOT NULL AND jsonb_array_length(v_grupos) > 0 THEN
                -- validate sum matches cantidad_rollos
                SELECT SUM((g->>'cantidad_rollos')::INT)
                INTO v_grupos_sum
                FROM jsonb_array_elements(v_grupos) g;

                IF v_grupos_sum <> v_extra THEN
                    RAISE EXCEPTION
                        'Línea %: suma de grupos (%) ≠ cantidad_rollos (%).',
                        v_detalle_id, v_grupos_sum, v_extra;
                END IF;
            ELSE
                -- synthesise a single group from line-level fields
                v_grupos := jsonb_build_array(
                    jsonb_build_object(
                        'cantidad_rollos', v_extra,
                        'factura_hilo',    v_factura_hilo
                    )
                );
            END IF;

            FOR v_grupo IN SELECT jsonb_array_elements(v_grupos)
            LOOP
                v_grupo_cant := (v_grupo->>'cantidad_rollos')::INT;
                v_grupo_fac  := v_grupo->>'factura_hilo';

                FOR i IN 1 .. v_grupo_cant
                LOOP
                    INSERT INTO inventario.lote (item_id, documento_tipo, documento_id, cantidad, propietario_id, usr_cre)
                    VALUES (v_item_id, 'orden_servicio', v_os_id, v_peso_por_rollo, NULL, v_usr_id)
                    RETURNING id INTO v_new_lote_id;

                    INSERT INTO inventario.lote_rollo_detalle (
                        lote_id, orden_servicio_id, ancho, malla, rendimiento,
                        flg_tenido, flg_antipilling, factura_hilo
                    ) VALUES (
                        v_new_lote_id, v_os_id, v_os.ancho, v_malla, v_os.rendimiento,
                        false, COALESCE(v_os.flg_antipilling, false), v_grupo_fac
                    );

                    INSERT INTO inventario.item_movimientos (
                        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
                        destino_ubicacion_id, cantidad, fecha_hora,
                        documento_tipo, documento_id, documento_linea_id, usr_cre
                    ) VALUES (
                        v_doc_mov_id, v_item_id, v_new_lote_id, v_serv_ing_tipo_id,
                        v_ubicacion_id, v_peso_por_rollo, v_fecha_mov,
                        'orden_servicio', v_os_id, v_detalle_id, v_usr_id
                    );
                END LOOP;
            END LOOP;
        END;

        UPDATE doc.orden_servicio_detalle
        SET cantidad_recibida = cantidad_recibida + v_extra
        WHERE id = v_detalle_id
        RETURNING cantidad_recibida, cantidad INTO v_recibida, v_ordenada;

        IF v_recibida > v_ordenada THEN
            RAISE NOTICE 'detalle %: recibido % supera lo ordenado % (over-receipt).',
                         v_detalle_id, v_recibida, v_ordenada;
        END IF;
    END LOOP;

    RETURN v_doc_mov_id;
EXCEPTION
    WHEN OTHERS THEN
        RAISE LOG 'Error in ingresar_orden_servicio - User: %, Params: %, Error: %',
                  v_usr_id, p_datos::TEXT, SQLERRM;
        RAISE;
END;
$$;


ALTER FUNCTION doc.ingresar_orden_servicio(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.marcar_compra_recibida(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.marcar_compra_recibida(p_compra_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id  int := get_user_id();
    v_rows    int;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('marcar_compra_recibida', v_usr_id, jsonb_build_object('compra_id', p_compra_id));

    IF NOT EXISTS (SELECT 1 FROM doc.compra WHERE id = p_compra_id AND fyh_elm IS NULL) THEN
        RAISE EXCEPTION 'Compra #% no encontrada o anulada.', p_compra_id;
    END IF;

    UPDATE doc.compra_detalle
    SET cantidad_recibida = cantidad
    WHERE compra_id = p_compra_id
      AND cantidad_recibida < cantidad;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        RAISE EXCEPTION 'Compra #% ya está completamente recibida.', p_compra_id;
    END IF;

    RETURN format('Compra #%s marcada como recibida (%s línea(s) cerrada(s)).', p_compra_id, v_rows);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in marcar_compra_recibida - User: %, compra: %, Error: %', v_usr_id, p_compra_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.marcar_compra_recibida(p_compra_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.marcar_letras_vencidas()
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.marcar_letras_vencidas() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'doc', 'public'
    AS $$
DECLARE
    v_count int;
BEGIN
    UPDATE doc.letra
    SET estado  = 'vencida',
        fyh_mod = NOW()
    WHERE estado = 'emitida'
      AND fecha_vencimiento < CURRENT_DATE;

    GET DIAGNOSTICS v_count = ROW_COUNT;

    IF v_count > 0 THEN
        RAISE LOG 'marcar_letras_vencidas: % letra(s) marcada(s) como vencida.', v_count;
    END IF;

    RETURN v_count;
END;
$$;


ALTER FUNCTION doc.marcar_letras_vencidas() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.pagar_letra(bigint, date, integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.pagar_letra(p_letra_id bigint, p_fecha_pago date DEFAULT CURRENT_DATE, p_cuenta_financiera_id integer DEFAULT NULL::integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc', 'tesoreria'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id          int := get_user_id();
    v_letra           doc.letra%ROWTYPE;
    v_facturas_count  int := 0;
    v_factura_rec     record;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO v_letra FROM doc.letra WHERE id = p_letra_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Letra #% no encontrada.', p_letra_id;
    END IF;
    IF v_letra.estado NOT IN ('emitida', 'vencida') THEN
        RAISE EXCEPTION 'La letra #% ya está en estado %. Solo se pueden pagar letras emitidas o vencidas.',
            p_letra_id, v_letra.estado;
    END IF;

    UPDATE doc.letra
    SET estado     = 'pagada',
        fecha_pago = p_fecha_pago,
        usr_mod    = v_usr_id,
        fyh_mod    = NOW()
    WHERE id = p_letra_id;

    -- Cash ledger (EGRESO). No-op when no paying account supplied.
    PERFORM tesoreria.registrar_movimiento(
        p_cuenta_financiera_id := p_cuenta_financiera_id,
        p_tipo                 := 'EGRESO',
        p_monto                := v_letra.monto,
        p_moneda               := 'USD',
        p_documento_tipo       := 'letra',
        p_documento_id         := p_letra_id,
        p_fecha                := p_fecha_pago,
        p_medio_pago           := 'LETRA',
        p_referencia           := v_letra.numero,
        p_glosa                := format('Pago letra #%s proveedor %s', p_letra_id, v_letra.tercero_id)
    );

    -- Recompute estado_pago (amount-based) on every factura this letra cleared.
    FOR v_factura_rec IN
        SELECT factura_proveedor_id FROM doc.letra_factura WHERE letra_id = p_letra_id
    LOOP
        PERFORM doc.recalcular_estado_pago_factura_proveedor(v_factura_rec.factura_proveedor_id);
        v_facturas_count := v_facturas_count + 1;
    END LOOP;

    RETURN format('Letra #%s pagada el %s. %s factura(s) actualizada(s).',
        p_letra_id, p_fecha_pago, v_facturas_count);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in pagar_letra - User: %, letra: %, Error: %', v_usr_id, p_letra_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.pagar_letra(p_letra_id bigint, p_fecha_pago date, p_cuenta_financiera_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.recompute_estado_comercial(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.recompute_estado_comercial(p_partida_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'mes', 'inventario', 'doc'
    AS $$
DECLARE
    v_root_id      BIGINT;
    v_total        INT;
    v_dispatched   INT;   -- currently out (no return has undone it)
    v_ever_dispatched INT; -- has a dispatch movement at all (regardless of return)
    v_estado       partida_estado_comercial_enum;
BEGIN
    SELECT COALESCE(partida_origen_id, id) INTO v_root_id
    FROM mes.partida WHERE id = p_partida_id AND fyh_elm IS NULL;

    IF v_root_id IS NULL THEN
        RETURN;  -- partida not found / soft-deleted: nothing to recompute
    END IF;

    WITH terminal AS (
        SELECT lote_id FROM mes.vw_partida_familia_output
        WHERE root_id = v_root_id AND estado_calidad = 'APROBADO'
    )
    SELECT
        COUNT(*),
        COUNT(*) FILTER (
            WHERE EXISTS (
                SELECT 1 FROM inventario.item_movimientos im
                JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
                WHERE im.lote_id = terminal.lote_id AND imt.codigo IN ('SERV_EGR','VENTA_EGR')
            )
            AND NOT EXISTS (
                SELECT 1 FROM inventario.item_movimientos im2
                JOIN inventario.item_movimiento_tipo imt2 ON imt2.id = im2.item_movimiento_tipo_id
                WHERE im2.lote_id = terminal.lote_id AND imt2.codigo IN ('SERV_DEV_ING','DEV_CLI_ING')
            )
        ),
        COUNT(*) FILTER (
            WHERE EXISTS (
                SELECT 1 FROM inventario.item_movimientos im
                JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
                WHERE im.lote_id = terminal.lote_id AND imt.codigo IN ('SERV_EGR','VENTA_EGR')
            )
        )
    INTO v_total, v_dispatched, v_ever_dispatched
    FROM terminal;

    v_estado := CASE
        WHEN v_total = 0                                   THEN 'PENDIENTE'
        WHEN v_dispatched = 0 AND v_ever_dispatched = v_total THEN 'DEVUELTA_TOTAL'
        WHEN v_dispatched < v_ever_dispatched               THEN 'DEVUELTA_PARCIAL'
        WHEN v_dispatched >= v_total                        THEN 'ENTREGADA'
        WHEN v_dispatched > 0                                THEN 'ENTREGA_PARCIAL'
        ELSE 'PENDIENTE'
    END;

    UPDATE mes.partida
    SET estado_comercial = v_estado
    WHERE id = v_root_id AND estado_comercial IS DISTINCT FROM v_estado;
END;
$$;


ALTER FUNCTION doc.recompute_estado_comercial(p_partida_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.reconciliar_entrega_compra(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.reconciliar_entrega_compra(p_datos jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message       text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id        int    := get_user_id();
    v_entrega_id    bigint := (p_datos->>'entrega_id')::bigint;
    v_compra_id     bigint := (p_datos->>'compra_id')::bigint;
    v_entrega_tercero int;
    v_compra_tercero  int;
    v_tipo          text;
    v_linea         jsonb;
    v_matched       int := 0;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('reconciliar_entrega_compra', v_usr_id, p_datos);

    -- Validate entrega
    SELECT et.codigo, e.tercero_id
    INTO v_tipo, v_entrega_tercero
    FROM doc.entrega e
    JOIN doc.entrega_tipo et ON et.id = e.entrega_tipo_id
    WHERE e.id = v_entrega_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Entrega #% no encontrada.', v_entrega_id;
    END IF;
    IF v_tipo <> 'COMPRA_INGRESO' THEN
        RAISE EXCEPTION 'Entrega #% no es de tipo COMPRA_INGRESO.', v_entrega_id;
    END IF;

    -- Validate compra
    SELECT tercero_id INTO v_compra_tercero
    FROM doc.compra WHERE id = v_compra_id AND fyh_elm IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Compra #% no encontrada o anulada.', v_compra_id;
    END IF;

    -- Same supplier
    IF v_entrega_tercero IS DISTINCT FROM v_compra_tercero THEN
        RAISE EXCEPTION 'La entrega #% pertenece a un proveedor distinto a la compra #%.',
            v_entrega_id, v_compra_id;
    END IF;

    -- Header link (idempotent)
    INSERT INTO doc.compra_entrega(compra_id, entrega_id)
    VALUES (v_compra_id, v_entrega_id)
    ON CONFLICT DO NOTHING;

    IF p_datos ? 'lineas' AND jsonb_array_length(p_datos->'lineas') > 0 THEN
        -- Explicit line mapping
        FOR v_linea IN SELECT jsonb_array_elements(p_datos->'lineas') LOOP
            UPDATE doc.entrega_detalle
            SET compra_detalle_id = (v_linea->>'compra_detalle_id')::bigint
            WHERE id = (v_linea->>'entrega_detalle_id')::bigint
              AND entrega_id = v_entrega_id;

            IF NOT FOUND THEN
                RAISE EXCEPTION 'entrega_detalle #% no pertenece a entrega #%.',
                    v_linea->>'entrega_detalle_id', v_entrega_id;
            END IF;
            v_matched := v_matched + 1;
        END LOOP;
    ELSE
        -- Auto-match by item_id
        UPDATE doc.entrega_detalle ed
        SET compra_detalle_id = (
            SELECT cd.id
            FROM doc.compra_detalle cd
            WHERE cd.compra_id = v_compra_id
              AND cd.item_id   = ed.item_id
            ORDER BY cd.id
            LIMIT 1
        )
        WHERE ed.entrega_id = v_entrega_id;

        GET DIAGNOSTICS v_matched = ROW_COUNT;

        -- Warn if any line couldn't be matched
        IF EXISTS (
            SELECT 1 FROM doc.entrega_detalle
            WHERE entrega_id = v_entrega_id AND compra_detalle_id IS NULL
        ) THEN
            RAISE WARNING 'Algunas líneas de entrega #% no tienen ítem equivalente en compra #%. Revise con lineas explícitas.',
                v_entrega_id, v_compra_id;
        END IF;
    END IF;

    PERFORM doc.fn_refresh_compra_detalle_qtys(v_compra_id);

    RETURN format('Entrega #%s reconciliada con compra #%s (%s línea(s) mapeada(s)).',
                  v_entrega_id, v_compra_id, v_matched);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in reconciliar_entrega_compra - User: %, Error: %', v_usr_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.reconciliar_entrega_compra(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.registrar_compra_completa(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.registrar_compra_completa(p_datos jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'inventario', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id     int    := get_user_id();
    v_tercero_id int    := (p_datos->>'tercero_id')::int;
    v_compra_id  bigint;
    v_entrega_id bigint;
    v_factura_id bigint;
    v_elem       jsonb;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_compra_completa', v_usr_id, p_datos);

    IF v_tercero_id IS NULL THEN
        RAISE EXCEPTION 'tercero_id es requerido.';
    END IF;

    -- ── 1. Compra (PO) ───────────────────────────────────────────
    INSERT INTO doc.compra (tercero_id, fecha, observacion, usr_cre)
    VALUES (v_tercero_id,
            COALESCE((p_datos->>'fecha')::DATE, CURRENT_DATE),
            p_datos->>'observacion',
            v_usr_id)
    RETURNING id INTO v_compra_id;

    INSERT INTO doc.compra_detalle (compra_id, item_id, cantidad, precio_unitario, usr_cre)
    SELECT v_compra_id,
           (item->>'item_id')::int,
           (item->>'cantidad')::numeric,
           (item->>'precio_unitario')::numeric,
           v_usr_id
    FROM jsonb_array_elements(p_datos->'items') item;

    -- ── 2. Entrega + stock ───────────────────────────────────────
    -- Always creates an entrega (headless when no guia) and posts stock.
    SELECT doc.registrar_entrega_compra(jsonb_build_object(
        'compra_id',    v_compra_id,
        'serie',        NULLIF(p_datos->'guia'->>'serie', ''),
        'correlativo',  NULLIF(p_datos->'guia'->>'correlativo', ''),
        'fecha',        COALESCE(p_datos->'guia'->>'fecha', p_datos->>'fecha'),
        'ubicacion_id', p_datos->>'ubicacion_id',
        'items', (
            SELECT jsonb_agg(jsonb_build_object(
                'item_id',  item->>'item_id',
                'cantidad', item->>'cantidad',
                'n_rollos', item->>'n_rollos'
            ))
            FROM jsonb_array_elements(p_datos->'items') item
        )
    )) INTO v_entrega_id;

    -- ── 3. Factura proveedor ─────────────────────────────────────
    IF p_datos ? 'factura' AND (p_datos->'factura'->>'numero') IS NOT NULL THEN
        SELECT doc.registrar_factura_proveedor(
            p_datos->'factura'
            || jsonb_build_object(
                'tercero_id', v_tercero_id,
                'compra_id',  v_compra_id,
                'lineas', (
                    SELECT jsonb_agg(jsonb_build_object(
                        'item_id',        item->>'item_id',
                        'cantidad',       item->>'cantidad',
                        'precio_unitario',item->>'precio_unitario'
                    ))
                    FROM jsonb_array_elements(p_datos->'items') item
                )
            )
        ) INTO v_factura_id;
    END IF;

    RETURN jsonb_build_object(
        'compra_id',  v_compra_id,
        'entrega_id', v_entrega_id,
        'factura_id', v_factura_id
    );

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
        v_message = MESSAGE_TEXT, v_detail = PG_EXCEPTION_DETAIL,
        v_hint    = PG_EXCEPTION_HINT, v_context = PG_EXCEPTION_CONTEXT,
        v_sqlstate = RETURNED_SQLSTATE;
    RAISE EXCEPTION 'registrar_compra_completa: % | detail: % | hint: % | context: % | state: %',
        v_message, v_detail, v_hint, v_context, v_sqlstate;
END;
$$;


ALTER FUNCTION doc.registrar_compra_completa(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.registrar_despacho(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.registrar_despacho(p_datos jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'mes', 'inventario'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id        int  := get_user_id();
    v_tercero_id    int  := (p_datos->>'tercero_id')::int;
    v_venta_id      bigint;
    v_entrega_ids   bigint[] := '{}';
    v_cargo_ids     bigint[] := '{}';
    v_entrega_id    bigint;
    v_tipo_codigo   text;
    v_tipo_id       smallint;
    v_guia          jsonb;
    v_items_grupo   jsonb;
    v_root_id       BIGINT;
    v_cargo         jsonb;
    v_cargo_id      bigint;
    v_partida       RECORD;
    v_precio_kg     NUMERIC(12,4);
    v_tipo_venta    venta_linea_tipo_enum;
    v_linea         SMALLINT;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF jsonb_array_length(COALESCE(p_datos->'items', '[]'::jsonb)) = 0 THEN
        RAISE EXCEPTION 'registrar_despacho: se requiere al menos un item.';
    END IF;

    IF v_tercero_id IS NULL THEN
        SELECT DISTINCT p.tercero_id INTO v_tercero_id
        FROM mes.partida p
        WHERE p.id = ANY(
            SELECT DISTINCT (c->>'partida_id')::bigint
            FROM jsonb_array_elements(COALESCE(p_datos->'cargos', '[]'::jsonb)) c
        );
    END IF;
    IF v_tercero_id IS NULL THEN
        RAISE EXCEPTION 'registrar_despacho: no se pudo determinar tercero_id (proporcione tercero_id o cargos con partida_id).';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_despacho', v_usr_id, p_datos);

    -- ── 1. Physical side: one entrega per ownership group, via crear_entrega ──
    -- Loops over exactly 2 fixed groups (ownership is structurally binary — see
    -- decision #5) but the BODY is 6 real steps (filter, tipo/guia lookup, build
    -- payload, call, recover id) — looping avoids duplicating that sequence, not
    -- just a value, so this earns its keep despite the fixed cardinality.
    --
    -- crear_entrega is reused as-is (not reimplemented, not wrapped) — it's ~140
    -- lines of already-live validated logic (stock checks, tercero validation,
    -- movement posting) called directly by the existing two-step frontend flow
    -- (get_despacho_partida → crear_entrega). As of 2026-07-14 it RETURNS bigint
    -- (the entrega_id) — changed from `text` specifically so this SELECT..INTO
    -- is clean, no currval/session-sequence trick needed. That change is
    -- breaking for BOTH of crear_entrega's direct callers (receipt AND
    -- dispatch) — see the note on crear_entrega itself (funciones/core.sql)
    -- and VENTA_MODULE_HANDOFF.md item 6b.
    FOR v_tipo_codigo IN SELECT unnest(ARRAY['VENTA_EGRESO','DESPACHO_CLIENTE'])
    LOOP
        SELECT jsonb_agg(item) INTO v_items_grupo
        FROM jsonb_array_elements(p_datos->'items') item
        WHERE (v_tipo_codigo = 'VENTA_EGRESO'    AND (item->>'propietario_id')::int = 1)
           OR (v_tipo_codigo = 'DESPACHO_CLIENTE' AND (item->>'propietario_id')::int IS DISTINCT FROM 1);

        CONTINUE WHEN v_items_grupo IS NULL;

        SELECT id INTO v_tipo_id FROM doc.entrega_tipo WHERE codigo = v_tipo_codigo;
        v_guia := (p_datos->'guias')->v_tipo_codigo;

        SELECT doc.crear_entrega(jsonb_build_object(
            'entrega_tipo_id', v_tipo_id,
            'tercero_id',      v_tercero_id,
            'serie',           v_guia->>'serie',
            'correlativo',     v_guia->>'correlativo',
            'fecha_emision',   COALESCE(v_guia->>'fecha_emision', now()::text),
            'items',           v_items_grupo
        )) INTO v_entrega_id;

        v_entrega_ids := array_append(v_entrega_ids, v_entrega_id);
    END LOOP;

    IF array_length(v_entrega_ids, 1) IS NULL THEN
        RAISE EXCEPTION 'registrar_despacho: ningún item resolvió a un grupo de despacho válido.';
    END IF;

    -- ── 2. Commercial side: open/reuse the ABIERTA venta for this tercero ──
    SELECT id INTO v_venta_id
    FROM doc.venta
    WHERE tercero_id = v_tercero_id AND estado = 'ABIERTA'
    ORDER BY fyh_cre DESC
    LIMIT 1
    FOR UPDATE;

    IF v_venta_id IS NULL THEN
        INSERT INTO doc.venta (tercero_id, usr_cre)
        VALUES (v_tercero_id, v_usr_id)
        RETURNING id INTO v_venta_id;
    END IF;

    UPDATE doc.entrega SET venta_id = v_venta_id WHERE id = ANY(v_entrega_ids);

    -- ── 3. Charge lines — snapshot dims from each cargo's INTENT partida ──
    v_linea := 0;
    FOR v_cargo IN SELECT * FROM jsonb_array_elements(COALESCE(p_datos->'cargos', '[]'::jsonb))
    LOOP
        v_linea := v_linea + 1;

        SELECT COALESCE(partida_origen_id, id) INTO v_root_id
        FROM mes.partida WHERE id = (v_cargo->>'partida_id')::bigint;

        IF v_root_id IS NULL THEN
            RAISE EXCEPTION 'registrar_despacho: partida % (cargo) no existe.', v_cargo->>'partida_id';
        END IF;

        SELECT p.tercero_id, p.color_x_cliente_id, p.tenido_id, p.grupo_articulo_id,
               p.fibra, p.flg_antipilling, p.precio_kg
        INTO v_partida
        FROM mes.partida p WHERE p.id = v_root_id;

        -- Ownership guard: this cargo's dispatched items (by root partida) must not mix owners.
        SELECT CASE
                 WHEN bool_and((item->>'propietario_id')::int = 1)          THEN 'VENTA'
                 WHEN bool_and((item->>'propietario_id')::int IS DISTINCT FROM 1) THEN 'SERVICIO'
                 ELSE NULL
               END
        INTO v_tipo_venta
        FROM jsonb_array_elements(p_datos->'items') item
        WHERE (
            SELECT COALESCE(partida_origen_id, id) FROM mes.partida
            WHERE id = (item->>'partida_id')::bigint
        ) = v_root_id;

        IF v_tipo_venta IS NULL THEN
            RAISE EXCEPTION 'registrar_despacho: partida % mezcla rollos propios y de cliente en este despacho — no se puede facturar como una sola línea.',
                v_root_id;
        END IF;

        v_precio_kg := COALESCE(
            (v_cargo->>'precio_kg')::numeric,
            v_partida.precio_kg,
            -- ⚠ Pre-existing gap, preserved as-is (documented in patch 46 step 11b):
            -- unlike fn_precio_info/get_precios_partida, this call site never routes
            -- TENIDO through fn_familia_precio. Out of scope for this rekey.
            doc.fn_get_precio(
                (v_cargo->>'operacion_id')::smallint,
                v_partida.color_x_cliente_id,
                v_partida.tercero_id,
                v_partida.grupo_articulo_id,
                v_partida.tenido_id,
                v_partida.fibra
            )
        );

        IF v_precio_kg IS NULL THEN
            RAISE EXCEPTION 'registrar_despacho: no se encontró precio para partida % / operación % — indique precio_kg manualmente.',
                v_root_id, v_cargo->>'operacion_id';
        END IF;

        INSERT INTO doc.venta_detalle (
            venta_id, linea, tipo, operacion_id, item_id,
            color_x_cliente_id, tenido_id, grupo_articulo_id, flg_antipilling,
            partida_id, descripcion, cantidad_kg, precio_kg, usr_cre
        ) VALUES (
            v_venta_id, v_linea, v_tipo_venta::venta_linea_tipo_enum,
            (v_cargo->>'operacion_id')::smallint,
            NULLIF(v_cargo->>'item_id','')::int,
            v_partida.color_x_cliente_id, v_partida.tenido_id, v_partida.grupo_articulo_id, v_partida.flg_antipilling,
            v_root_id, v_cargo->>'descripcion',
            (v_cargo->>'cantidad_kg')::numeric, v_precio_kg, v_usr_id
        )
        RETURNING id INTO v_cargo_id;

        v_cargo_ids := array_append(v_cargo_ids, v_cargo_id);
    END LOOP;

    -- ── 4. Refresh the fulfillment cache for every distinct partida touched ──
    PERFORM doc.recompute_estado_comercial(DISTINCT_ROOT.root_id)
    FROM (
        SELECT DISTINCT COALESCE(p.partida_origen_id, p.id) AS root_id
        FROM jsonb_array_elements(p_datos->'items') item
        JOIN mes.partida p ON p.id = (item->>'partida_id')::bigint
    ) DISTINCT_ROOT;

    RETURN jsonb_build_object(
        'venta_id',    v_venta_id,
        'entrega_ids', to_jsonb(v_entrega_ids),
        'cargo_ids',   to_jsonb(v_cargo_ids)
    );
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_despacho - User: %, Error: %', v_usr_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.registrar_despacho(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.registrar_devolucion_cliente(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.registrar_devolucion_cliente(p_datos jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id        int  := get_user_id();
    v_entrega_id    BIGINT;
    v_entrega_tipo  entrega_tipo%ROWTYPE;
    v_doc_mov_id    BIGINT;
    v_fecha_mov     TIMESTAMPTZ;
    v_error_payload jsonb;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO v_entrega_tipo
    FROM entrega_tipo
    WHERE id = (p_datos->>'entrega_tipo_id')::SMALLINT;

    IF NOT FOUND OR v_entrega_tipo.codigo NOT IN ('DEVOLUCION_CLIENTE_SERVICIO', 'DEVOLUCION_CLIENTE_VENTA') THEN
        RAISE EXCEPTION 'entrega_tipo_id inválido: use DEVOLUCION_CLIENTE_SERVICIO (8) o DEVOLUCION_CLIENTE_VENTA (7)';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM tercero WHERE id = (p_datos->>'tercero_id')::INT AND flg_cliente = true
    ) THEN
        RAISE EXCEPTION 'tercero_id % no corresponde a un cliente', (p_datos->>'tercero_id');
    END IF;

    -- Guard: lotes must be fully out of stock (saldo = 0 ↔ absent from vw_stock_lotes)
    SELECT jsonb_agg(jsonb_build_object(
        'lote_id',             ei.lote_id,
        'cantidad_disponible', sl.cantidad_disponible
    ))
    INTO v_error_payload
    FROM (
        SELECT DISTINCT (i->>'lote_id')::int AS lote_id
        FROM jsonb_array_elements(p_datos->'items') i
    ) ei
    JOIN inventario.vw_stock_lotes sl ON sl.lote_id = ei.lote_id;

    IF v_error_payload IS NOT NULL THEN
        RAISE EXCEPTION 'Devolución inválida: los siguientes lotes aún tienen stock positivo (¿ya devueltos o nunca despachados?)'
            USING DETAIL = v_error_payload::text;
    END IF;

    -- Guard: each lote must have been dispatched to this client at least once
    SELECT jsonb_agg(jsonb_build_object('lote_id', ei.lote_id))
    INTO v_error_payload
    FROM (
        SELECT DISTINCT (i->>'lote_id')::int AS lote_id
        FROM jsonb_array_elements(p_datos->'items') i
    ) ei
    WHERE NOT EXISTS (
        SELECT 1
        FROM inventario.item_movimientos im
        JOIN doc.entrega e ON e.id = im.documento_id AND im.documento_tipo = 'entrega'
        WHERE im.lote_id       = ei.lote_id
          AND e.tercero_id     = (p_datos->>'tercero_id')::INT
          AND im.origen_ubicacion_id IS NOT NULL  -- outbound (EGRESO) direction
    );

    IF v_error_payload IS NOT NULL THEN
        RAISE EXCEPTION 'Devolución inválida: los siguientes lotes no registran despacho previo a este cliente'
            USING DETAIL = v_error_payload::text;
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_devolucion_cliente', v_usr_id, p_datos);

    v_fecha_mov := COALESCE((p_datos->>'fecha_recepcion')::TIMESTAMPTZ, now());
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

    INSERT INTO doc.entrega(entrega_tipo_id, tercero_id, serie, correlativo, fecha_emision, fecha_recepcion)
    VALUES (
        v_entrega_tipo.id,
        (p_datos->>'tercero_id')::INT,
        p_datos->>'serie',
        p_datos->>'correlativo',
        v_fecha_mov,
        v_fecha_mov
    )
    RETURNING id INTO v_entrega_id;

    WITH items AS (
        SELECT
            COALESCE((item->>'linea')::SMALLINT, idx::SMALLINT) AS linea,
            (item->>'item_id')::INT                             AS item_id,
            (item->>'cantidad')::NUMERIC(12,4)                  AS cantidad,
            (item->>'lote_id')::INT                             AS lote_id,
            (item->>'ubicacion_id')::INT                        AS ubicacion_id
        FROM jsonb_array_elements(p_datos->'items') WITH ORDINALITY AS t(item, idx)
    ),
    det AS (
        INSERT INTO doc.entrega_detalle(entrega_id, linea, item_id, cantidad, lote_id, ubicacion_id)
        SELECT v_entrega_id, linea, item_id, cantidad, lote_id, ubicacion_id
        FROM items
        RETURNING id, linea
    )
    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        destino_ubicacion_id, cantidad, fecha_hora,
        documento_tipo, documento_id, documento_linea_id)
    SELECT
        v_doc_mov_id, i.item_id, i.lote_id, v_entrega_tipo.item_movimiento_tipo_id,
        i.ubicacion_id,   -- incoming destination location
        i.cantidad, v_fecha_mov,
        'entrega', v_entrega_id, d.id
    FROM items i
    JOIN det d ON d.linea = i.linea;

    -- Link this return to the SAME venta its original dispatch belonged to
    -- (entrega.venta_id — see migration/27_venta.sql). Assumes all returned
    -- lotes in one call trace to a single venta (reasonable: single tercero
    -- already enforced above).
    UPDATE doc.entrega
    SET venta_id = (
        SELECT e2.venta_id
        FROM inventario.item_movimientos im
        JOIN doc.entrega e2 ON e2.id = im.documento_id AND im.documento_tipo = 'entrega'
        WHERE im.lote_id = ANY(
            SELECT (item->>'lote_id')::int FROM jsonb_array_elements(p_datos->'items') item
        )
        AND im.origen_ubicacion_id IS NOT NULL  -- outbound direction: the original dispatch
        AND e2.venta_id IS NOT NULL
        LIMIT 1
    )
    WHERE id = v_entrega_id;

    -- Fulfillment cache: a return un-dispatches rolls — refresh every partida touched.
    -- See doc.recompute_estado_comercial's closed call-site list (funciones/despacho.sql).
    PERFORM doc.recompute_estado_comercial(root.root_id)
    FROM (
        SELECT DISTINCT COALESCE(p.partida_origen_id, p.id) AS root_id
        FROM doc.entrega_detalle ed
        JOIN inventario.lote l ON l.id = ed.lote_id
        JOIN mes.partida_paso_ejecucion pe ON pe.id = l.documento_id AND l.documento_tipo = 'partida_paso_ejecucion'
        JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
        JOIN mes.partida p ON p.id = pp.partida_id
        WHERE ed.entrega_id = v_entrega_id
    ) root;

    RETURN format('Devolución de cliente registrada. Guía #%s creada.', v_entrega_id);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
        v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT,
        v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_devolucion_cliente - User: %, Params: %, Error: %',
        v_usr_id, p_datos::TEXT, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.registrar_devolucion_cliente(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.registrar_devolucion_crudo_cliente(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.registrar_devolucion_crudo_cliente(p_datos jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id        int  := get_user_id();
    v_entrega_id    BIGINT;
    v_entrega_tipo  entrega_tipo%ROWTYPE;
    v_doc_mov_id    BIGINT;
    v_fecha_mov     TIMESTAMPTZ;
    v_error_payload jsonb;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO v_entrega_tipo FROM entrega_tipo WHERE codigo = 'DEVOLUCION_CLIENTE_CRUDO';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Tipo DEVOLUCION_CLIENTE_CRUDO no encontrado en entrega_tipo';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM tercero WHERE id = (p_datos->>'tercero_id')::INT AND flg_cliente = true
    ) THEN
        RAISE EXCEPTION 'tercero_id % no corresponde a un cliente', (p_datos->>'tercero_id');
    END IF;

    -- Guard: only ROLLO lotes allowed (not insumos)
    SELECT jsonb_agg(jsonb_build_object('lote_id', ei.lote_id, 'item_tipo', it.codigo))
    INTO v_error_payload
    FROM (
        SELECT DISTINCT (i->>'lote_id')::int AS lote_id
        FROM jsonb_array_elements(p_datos->'items') i
    ) ei
    JOIN inventario.lote l  ON l.id = ei.lote_id
    JOIN item               ON item.id = l.item_id
    JOIN item_tipo it       ON it.id = item.item_tipo_id
    WHERE it.codigo <> 'ROLLO';

    IF v_error_payload IS NOT NULL THEN
        RAISE EXCEPTION 'Devolución de crudo inválida: solo se pueden devolver rollos (no insumos)'
            USING DETAIL = v_error_payload::text;
    END IF;

    -- Guard: lotes must have entered MLR from this client (SERV_ING movement via entrega)
    SELECT jsonb_agg(jsonb_build_object('lote_id', ei.lote_id))
    INTO v_error_payload
    FROM (
        SELECT DISTINCT (i->>'lote_id')::int AS lote_id
        FROM jsonb_array_elements(p_datos->'items') i
    ) ei
    WHERE NOT EXISTS (
        SELECT 1
        FROM inventario.item_movimientos im
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id AND imt.codigo = 'SERV_ING'
        JOIN doc.entrega e ON e.id = im.documento_id AND im.documento_tipo = 'entrega'
        WHERE im.lote_id   = ei.lote_id
          AND e.tercero_id = (p_datos->>'tercero_id')::INT
    );

    IF v_error_payload IS NOT NULL THEN
        RAISE EXCEPTION 'Devolución de crudo inválida: los siguientes lotes no ingresaron como material de servicio de este cliente'
            USING DETAIL = v_error_payload::text;
    END IF;

    -- Guard: sufficient available stock to dispatch
    WITH entrega_items AS (
        SELECT
            (i->>'item_id')::int        AS item_id,
            (i->>'lote_id')::int        AS lote_id,
            (i->>'ubicacion_id')::int   AS ubicacion_id,
            SUM((i->>'cantidad')::numeric) AS cantidad
        FROM jsonb_array_elements(p_datos->'items') i
        GROUP BY 1, 2, 3
    )
    SELECT jsonb_agg(jsonb_build_object(
        'item_id',            items.item_id,
        'lote_id',            items.lote_id,
        'saldo_disponible',   COALESCE(sl.cantidad_disponible, 0),
        'cantidad_requerida', items.cantidad
    ))
    INTO v_error_payload
    FROM entrega_items items
    LEFT JOIN inventario.vw_stock_lotes sl
        ON sl.lote_id = items.lote_id AND sl.item_id = items.item_id
    WHERE COALESCE(sl.cantidad_disponible, 0) < items.cantidad;

    IF v_error_payload IS NOT NULL THEN
        RAISE EXCEPTION 'Stock insuficiente para devolución de crudo'
            USING DETAIL = v_error_payload::text;
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_devolucion_crudo_cliente', v_usr_id, p_datos);

    v_fecha_mov := COALESCE((p_datos->>'fecha_emision')::TIMESTAMPTZ, now());
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

    INSERT INTO doc.entrega(entrega_tipo_id, tercero_id, serie, correlativo, fecha_emision, fecha_recepcion)
    VALUES (
        v_entrega_tipo.id,
        (p_datos->>'tercero_id')::INT,
        p_datos->>'serie',
        p_datos->>'correlativo',
        v_fecha_mov,
        NULL
    )
    RETURNING id INTO v_entrega_id;

    WITH items AS (
        SELECT
            COALESCE((item->>'linea')::SMALLINT, idx::SMALLINT) AS linea,
            (item->>'item_id')::INT                             AS item_id,
            (item->>'cantidad')::NUMERIC(12,4)                  AS cantidad,
            (item->>'lote_id')::INT                             AS lote_id,
            (item->>'ubicacion_id')::INT                        AS ubicacion_id,
            (item->>'n_rollos')::INT                            AS n_rollos
        FROM jsonb_array_elements(p_datos->'items') WITH ORDINALITY AS t(item, idx)
    ),
    det AS (
        INSERT INTO doc.entrega_detalle(entrega_id, linea, item_id, cantidad, lote_id, ubicacion_id, n_rollos)
        SELECT v_entrega_id, linea, item_id, cantidad, lote_id, ubicacion_id, n_rollos
        FROM items
        RETURNING id, linea
    )
    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        origen_ubicacion_id, destino_ubicacion_id,
        cantidad, fecha_hora, documento_tipo, documento_id, documento_linea_id)
    SELECT
        v_doc_mov_id, i.item_id, i.lote_id, v_entrega_tipo.item_movimiento_tipo_id,
        i.ubicacion_id,  -- origin stock location at MLR
        NULL,            -- destination is client (external)
        i.cantidad, v_fecha_mov,
        'entrega', v_entrega_id, d.id
    FROM items i
    JOIN det d ON d.linea = i.linea;

    -- Link this return to the SAME venta its original dispatch belonged to.
    UPDATE doc.entrega
    SET venta_id = (
        SELECT e2.venta_id
        FROM inventario.item_movimientos im
        JOIN doc.entrega e2 ON e2.id = im.documento_id AND im.documento_tipo = 'entrega'
        WHERE im.lote_id = ANY(
            SELECT (item->>'lote_id')::int FROM jsonb_array_elements(p_datos->'items') item
        )
        AND im.origen_ubicacion_id IS NOT NULL
        AND e2.venta_id IS NOT NULL
        LIMIT 1
    )
    WHERE id = v_entrega_id;

    -- Fulfillment cache: crudo rolls returned un-dispatched too — refresh every partida touched.
    PERFORM doc.recompute_estado_comercial(root.root_id)
    FROM (
        SELECT DISTINCT COALESCE(p.partida_origen_id, p.id) AS root_id
        FROM doc.entrega_detalle ed
        JOIN inventario.lote l ON l.id = ed.lote_id
        JOIN mes.partida_paso_ejecucion pe ON pe.id = l.documento_id AND l.documento_tipo = 'partida_paso_ejecucion'
        JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
        JOIN mes.partida p ON p.id = pp.partida_id
        WHERE ed.entrega_id = v_entrega_id
    ) root;

    RETURN format('Devolución de crudo a cliente registrada. Guía #%s creada.', v_entrega_id);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
        v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT,
        v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_devolucion_crudo_cliente - User: %, Params: %, Error: %',
        v_usr_id, p_datos::TEXT, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.registrar_devolucion_crudo_cliente(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.registrar_devolucion_proveedor(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.registrar_devolucion_proveedor(p_datos jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id        int  := get_user_id();
    v_entrega_id    BIGINT;
    v_entrega_tipo  entrega_tipo%ROWTYPE;
    v_doc_mov_id    BIGINT;
    v_fecha_mov     TIMESTAMPTZ;
    v_error_payload jsonb;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO v_entrega_tipo FROM entrega_tipo WHERE codigo = 'DEVOLUCION_PROVEEDOR';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Tipo DEVOLUCION_PROVEEDOR no encontrado en entrega_tipo';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM tercero WHERE id = (p_datos->>'tercero_id')::INT AND flg_proveedor = true
    ) THEN
        RAISE EXCEPTION 'tercero_id % no corresponde a un proveedor', (p_datos->>'tercero_id');
    END IF;

    -- Guard: only INSUMO lotes (not rolls)
    SELECT jsonb_agg(jsonb_build_object('lote_id', ei.lote_id, 'item_tipo', it.codigo))
    INTO v_error_payload
    FROM (
        SELECT DISTINCT (i->>'lote_id')::int AS lote_id
        FROM jsonb_array_elements(p_datos->'items') i
    ) ei
    JOIN inventario.lote l  ON l.id = ei.lote_id
    JOIN item               ON item.id = l.item_id
    JOIN item_tipo it       ON it.id = item.item_tipo_id
    WHERE it.codigo <> 'INSUMO';

    IF v_error_payload IS NOT NULL THEN
        RAISE EXCEPTION 'Devolución a proveedor inválida: solo se pueden devolver insumos (no rollos)'
            USING DETAIL = v_error_payload::text;
    END IF;

    -- Guard: sufficient available stock
    WITH entrega_items AS (
        SELECT
            (i->>'item_id')::int        AS item_id,
            (i->>'lote_id')::int        AS lote_id,
            (i->>'ubicacion_id')::int   AS ubicacion_id,
            SUM((i->>'cantidad')::numeric) AS cantidad
        FROM jsonb_array_elements(p_datos->'items') i
        GROUP BY 1, 2, 3
    )
    SELECT jsonb_agg(jsonb_build_object(
        'item_id',            items.item_id,
        'lote_id',            items.lote_id,
        'saldo_disponible',   COALESCE(sl.cantidad_disponible, 0),
        'cantidad_requerida', items.cantidad
    ))
    INTO v_error_payload
    FROM entrega_items items
    LEFT JOIN inventario.vw_stock_lotes sl
        ON sl.lote_id = items.lote_id AND sl.item_id = items.item_id
    WHERE COALESCE(sl.cantidad_disponible, 0) < items.cantidad;

    IF v_error_payload IS NOT NULL THEN
        RAISE EXCEPTION 'Stock insuficiente para devolución a proveedor'
            USING DETAIL = v_error_payload::text;
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_devolucion_proveedor', v_usr_id, p_datos);

    v_fecha_mov := COALESCE((p_datos->>'fecha_emision')::TIMESTAMPTZ, now());
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

    INSERT INTO doc.entrega(entrega_tipo_id, tercero_id, serie, correlativo, fecha_emision, fecha_recepcion)
    VALUES (
        v_entrega_tipo.id,
        (p_datos->>'tercero_id')::INT,
        p_datos->>'serie',
        p_datos->>'correlativo',
        v_fecha_mov,
        NULL
    )
    RETURNING id INTO v_entrega_id;

    WITH items AS (
        SELECT
            COALESCE((item->>'linea')::SMALLINT, idx::SMALLINT) AS linea,
            (item->>'item_id')::INT                             AS item_id,
            (item->>'cantidad')::NUMERIC(12,4)                  AS cantidad,
            (item->>'lote_id')::INT                             AS lote_id,
            (item->>'ubicacion_id')::INT                        AS ubicacion_id
        FROM jsonb_array_elements(p_datos->'items') WITH ORDINALITY AS t(item, idx)
    ),
    det AS (
        INSERT INTO doc.entrega_detalle(entrega_id, linea, item_id, cantidad, lote_id, ubicacion_id)
        SELECT v_entrega_id, linea, item_id, cantidad, lote_id, ubicacion_id
        FROM items
        RETURNING id, linea
    )
    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        origen_ubicacion_id, destino_ubicacion_id,
        cantidad, fecha_hora, documento_tipo, documento_id, documento_linea_id)
    SELECT
        v_doc_mov_id, i.item_id, i.lote_id, v_entrega_tipo.item_movimiento_tipo_id,
        i.ubicacion_id,  -- origin stock location at MLR
        NULL,            -- destination is supplier (external)
        i.cantidad, v_fecha_mov,
        'entrega', v_entrega_id, d.id
    FROM items i
    JOIN det d ON d.linea = i.linea;

    RETURN format('Devolución a proveedor registrada. Guía #%s creada.', v_entrega_id);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
        v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT,
        v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_devolucion_proveedor - User: %, Params: %, Error: %',
        v_usr_id, p_datos::TEXT, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.registrar_devolucion_proveedor(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.registrar_entrega_compra(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.registrar_entrega_compra(p_datos jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'inventario', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id          int      := get_user_id();
    v_compra_id       bigint   := (p_datos->>'compra_id')::bigint;
    v_entrega_id      bigint;
    v_entrega_tipo_id smallint;
    v_tercero_id      int;
    v_ubicacion_id    int;
    v_fecha_mov       timestamptz;
    v_doc_mov_id      bigint;
    v_mov_tipo_id     smallint;
    v_elem            jsonb;
    v_item_id         int;
    v_cantidad        numeric;
    v_n_rollos        int;
    v_detalle_id      bigint;   -- entrega_detalle.id  (LIPS line)
    v_compra_det_id   bigint;   -- compra_detalle.id   (EKPO link)
    v_lote_id         int;
    v_linea           smallint := 0;
    v_flg_rollo       boolean;
    v_flg_rib         boolean;
    v_prorate         boolean;
    v_peso_rollo      numeric;
    i                 int;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_entrega_compra', v_usr_id, p_datos);

    SELECT id INTO STRICT v_entrega_tipo_id
    FROM doc.entrega_tipo WHERE codigo = 'COMPRA_INGRESO';

    IF v_compra_id IS NOT NULL THEN
        IF NOT EXISTS (SELECT 1 FROM doc.compra WHERE id = v_compra_id AND fyh_elm IS NULL) THEN
            RAISE EXCEPTION 'Compra #% no existe o fue anulada.', v_compra_id;
        END IF;
        SELECT tercero_id INTO v_tercero_id FROM doc.compra WHERE id = v_compra_id;
    ELSE
        v_tercero_id := (p_datos->>'tercero_id')::int;
        IF v_tercero_id IS NULL THEN
            RAISE EXCEPTION 'tercero_id requerido cuando no se especifica compra_id.';
        END IF;
    END IF;

    v_fecha_mov := COALESCE((p_datos->>'fecha')::timestamptz, now());

    INSERT INTO doc.entrega (entrega_tipo_id, tercero_id, serie, correlativo, fecha_emision, fecha_recepcion)
    VALUES (v_entrega_tipo_id, v_tercero_id, p_datos->>'serie', p_datos->>'correlativo',
            v_fecha_mov, v_fecha_mov)
    RETURNING id INTO v_entrega_id;

    -- Stock always posts via entrega — resolve movement infra before item loop
    v_doc_mov_id := nextval('inventario.mov_doc_seq');
    SELECT id INTO STRICT v_mov_tipo_id
    FROM inventario.item_movimiento_tipo WHERE codigo = 'COMPRA_ING';

    IF (p_datos->>'ubicacion_id') IS NOT NULL THEN
        v_ubicacion_id := (p_datos->>'ubicacion_id')::int;
    ELSE
        SELECT ub.id INTO STRICT v_ubicacion_id
        FROM inventario.ubicacion ub
        JOIN inventario.almacen alm ON alm.id = ub.almacen_id
        WHERE alm.codigo = 'ALM_CRU' LIMIT 1;
    END IF;

    IF v_compra_id IS NOT NULL THEN
        INSERT INTO doc.compra_entrega (compra_id, entrega_id)
        VALUES (v_compra_id, v_entrega_id)
        ON CONFLICT DO NOTHING;
    END IF;

    FOR v_elem IN SELECT jsonb_array_elements(p_datos->'items') LOOP
        v_item_id       := (v_elem->>'item_id')::int;
        v_cantidad      := (v_elem->>'cantidad')::numeric;
        v_n_rollos      := (v_elem->>'n_rollos')::int;
        v_linea         := v_linea + 1;

        -- Resolve EKPO link: explicit from payload, or auto-match by item_id
        v_compra_det_id := (v_elem->>'compra_detalle_id')::bigint;
        IF v_compra_det_id IS NULL AND v_compra_id IS NOT NULL THEN
            SELECT id INTO v_compra_det_id
            FROM doc.compra_detalle
            WHERE compra_id = v_compra_id AND item_id = v_item_id
            ORDER BY id LIMIT 1;
        END IF;

        INSERT INTO doc.entrega_detalle (entrega_id, linea, item_id, cantidad, n_rollos, compra_detalle_id)
        VALUES (v_entrega_id, v_linea, v_item_id, v_cantidad, v_n_rollos, v_compra_det_id)
        RETURNING id INTO v_detalle_id;

        SELECT EXISTS (
            SELECT 1 FROM item i
            JOIN item_tipo it ON it.id = i.item_tipo_id AND it.codigo = 'ROLLO'
            WHERE i.id = v_item_id
        ) INTO v_flg_rollo;

        IF v_flg_rollo AND v_n_rollos IS NOT NULL THEN
            v_prorate    := COALESCE((v_elem->>'prorate')::boolean, true);
            v_peso_rollo := CASE WHEN v_prorate THEN v_cantidad / v_n_rollos ELSE v_cantidad END;

            SELECT COALESCE(flg_rib, false) INTO v_flg_rib
            FROM item_rollo_detalle WHERE item_id = v_item_id;

            FOR i IN 1 .. v_n_rollos LOOP
                INSERT INTO inventario.lote (item_id, documento_tipo, documento_id, cantidad, propietario_id, usr_cre)
                VALUES (v_item_id, 'entrega', v_entrega_id, v_peso_rollo, NULL, v_usr_id)
                RETURNING id INTO v_lote_id;

                INSERT INTO inventario.lote_rollo_detalle (lote_id, entrega_id, flg_tenido)
                VALUES (v_lote_id, v_entrega_id, false);

                INSERT INTO inventario.item_movimientos (
                    doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
                    destino_ubicacion_id, cantidad, fecha_hora,
                    documento_tipo, documento_id, documento_linea_id, usr_cre
                ) VALUES (
                    v_doc_mov_id, v_item_id, v_lote_id, v_mov_tipo_id,
                    v_ubicacion_id, v_peso_rollo, v_fecha_mov,
                    'entrega', v_entrega_id, v_detalle_id, v_usr_id
                );
            END LOOP;

        ELSE
            INSERT INTO inventario.lote (item_id, documento_tipo, documento_id, cantidad, propietario_id, usr_cre)
            VALUES (v_item_id, 'entrega', v_entrega_id, v_cantidad, NULL, v_usr_id)
            RETURNING id INTO v_lote_id;

            INSERT INTO inventario.item_movimientos (
                doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
                destino_ubicacion_id, cantidad, fecha_hora,
                documento_tipo, documento_id, documento_linea_id, usr_cre
            ) VALUES (
                v_doc_mov_id, v_item_id, v_lote_id, v_mov_tipo_id,
                v_ubicacion_id, v_cantidad, v_fecha_mov,
                'entrega', v_entrega_id, v_detalle_id, v_usr_id
            );
        END IF;

    END LOOP;

    -- Sync PO receipt counter when linked to a compra
    IF v_compra_id IS NOT NULL THEN
        PERFORM doc.fn_refresh_compra_detalle_qtys(v_compra_id);
    END IF;

    -- Notify warehouse roles
    INSERT INTO notification.notifications(user_id, title, body, tipo, payload)
    SELECT ur.user_id,
           'Ingreso de compra',
           COALESCE((SELECT COALESCE(nombre, 'Usuario desconocido') || ' ' || apellido FROM usuario WHERE id = v_usr_id), 'sistema')
               || CASE WHEN v_compra_id IS NOT NULL
                        THEN ' ingresó stock contra compra #' || v_compra_id
                        ELSE ' registró entrega sin compra asociada'
                  END,
           'info',
           jsonb_build_object(
               'objeto_tipo',    'entrega',
               'entrega_id',     v_entrega_id,
               'compra_id',      v_compra_id,
               'doc_movimiento_id', v_doc_mov_id
           )
    FROM iam.user_rol ur
    LEFT JOIN iam.rol r ON ur.rol_id = r.id
    WHERE r.code IN ('jefe_planta', 'compras', 'inventario')
      AND v_usr_id <> ur.user_id;

    RETURN v_entrega_id;

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
        v_message = MESSAGE_TEXT, v_detail = PG_EXCEPTION_DETAIL,
        v_hint    = PG_EXCEPTION_HINT, v_context = PG_EXCEPTION_CONTEXT,
        v_sqlstate = RETURNED_SQLSTATE;
    RAISE EXCEPTION 'registrar_entrega_compra: % | detail: % | hint: % | context: % | state: %',
        v_message, v_detail, v_hint, v_context, v_sqlstate;
END;
$$;


ALTER FUNCTION doc.registrar_entrega_compra(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.registrar_factura_cliente(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.registrar_factura_cliente(p_factura jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'doc', 'mes', 'public'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id     INT := get_user_id();
    v_factura_id BIGINT;
    v_subtotal   NUMERIC(12,2);
    v_igv        NUMERIC(12,2);
    v_total      NUMERIC(12,2);
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_factura_cliente', v_usr_id, p_factura);

    IF NOT (p_factura ? 'lineas') OR jsonb_array_length(p_factura->'lineas') = 0 THEN
        RAISE EXCEPTION 'La factura debe tener al menos una línea de detalle.';
    END IF;

    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_factura->'lineas') l
        WHERE COALESCE((l->>'precio_unitario')::NUMERIC, 0) <= 0
    ) THEN
        RAISE EXCEPTION 'Todas las líneas deben tener un precio unitario mayor a cero.';
    END IF;

    -- Clean break, same as crear_partida (migration 30 decision 7): reject the
    -- retired key outright rather than accept it silently and drop it on the
    -- floor. A caller still sending articulo_tipo_id is stale and needs to know.
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_factura->'lineas') l
        WHERE l ? 'articulo_tipo_id'
    ) THEN
        RAISE EXCEPTION 'articulo_tipo_id fue retirado (migración 33) — envíe grupo_articulo_id.';
    END IF;

    -- Insert header with placeholder totals; updated after lines are inserted
    INSERT INTO doc.factura (
        tipo_comprobante, serie, numero, tercero_id,
        fecha_emision, fecha_vencimiento,
        moneda, tipo_cambio,
        subtotal, igv, total,
        estado, observacion, usr_cre
    ) VALUES (
        (p_factura->>'tipo_comprobante')::CHAR(2),
        p_factura->>'serie',
        (p_factura->>'numero')::INT,
        (p_factura->>'tercero_id')::INT,
        (p_factura->>'fecha_emision')::DATE,
        (p_factura->>'fecha_vencimiento')::DATE,
        COALESCE(p_factura->>'moneda', 'USD')::CHAR(3),
        (p_factura->>'tipo_cambio')::NUMERIC,
        0, 0, 0,
        'emitida',
        p_factura->>'observacion',
        v_usr_id
    )
    RETURNING id INTO v_factura_id;

    INSERT INTO doc.factura_detalle (
        factura_id,
        entrega_id,
        partida_id,
        operacion_id,
        es_antipilling,
        grupo_articulo_id,
        color_x_cliente_id,
        tenido_id,
        descripcion,
        cantidad,
        unidad_id,
        precio_unitario,
        igv_porcentaje,
        usr_cre
    )
    SELECT
        v_factura_id,
        (l->>'entrega_id')::BIGINT,
        (l->>'partida_id')::BIGINT,
        (l->>'operacion_id')::SMALLINT,
        COALESCE((l->>'es_antipilling')::BOOLEAN, false),
        (l->>'grupo_articulo_id')::INT,
        (l->>'color_x_cliente_id')::INT,
        (l->>'tenido_id')::INT,
        l->>'descripcion',
        (l->>'cantidad')::NUMERIC,
        (l->>'unidad_id')::INT,
        (l->>'precio_unitario')::NUMERIC,
        COALESCE((l->>'igv_porcentaje')::NUMERIC, 18),
        v_usr_id
    FROM jsonb_array_elements(p_factura->'lineas') l;

    -- Compute totals from generated columns on detail lines
    SELECT SUM(subtotal_linea), SUM(igv_linea), SUM(total_linea)
    INTO v_subtotal, v_igv, v_total
    FROM doc.factura_detalle
    WHERE factura_id = v_factura_id;

    UPDATE doc.factura
    SET subtotal = v_subtotal,
        igv      = v_igv,
        total    = v_total
    WHERE id = v_factura_id;

    -- Auto-close partidas that are now fully billed
    UPDATE mes.partida p
    SET estado_facturacion = 'facturado',
        usr_mod = v_usr_id,
        fyh_mod = NOW()
    WHERE p.id IN (
        SELECT DISTINCT (l->>'partida_id')::BIGINT
        FROM jsonb_array_elements(p_factura->'lineas') l
        WHERE l->>'partida_id' IS NOT NULL
    )
    AND NOT EXISTS (
        SELECT 1 FROM doc.vw_pendientes_facturacion vpf
        WHERE vpf.partida_id = p.id
    )
    AND NOT EXISTS (
        SELECT 1 FROM doc.vw_aprobados_sin_despacho vas
        WHERE vas.partida_id = p.id
    );

    RETURN v_factura_id;
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_factura_cliente - User: %, Error: %', v_usr_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.registrar_factura_cliente(p_factura jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.registrar_factura_proveedor(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.registrar_factura_proveedor(p_datos jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id     int    := get_user_id();
    v_factura_id bigint;
    v_compra_id  bigint := (p_datos->>'compra_id')::BIGINT;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_factura_proveedor', v_usr_id, p_datos);

    IF COALESCE((p_datos->>'subtotal')::NUMERIC, 0) <= 0 THEN
        RAISE EXCEPTION 'El subtotal debe ser mayor a cero.';
    END IF;
    IF COALESCE((p_datos->>'total')::NUMERIC, 0) <= 0 THEN
        RAISE EXCEPTION 'El total debe ser mayor a cero.';
    END IF;

    -- subtotal + igv must equal total (tolerance matches table CHECK: < 0.01)
    IF ABS(
        (p_datos->>'total')::NUMERIC -
        (COALESCE((p_datos->>'subtotal')::NUMERIC, 0) + COALESCE((p_datos->>'igv')::NUMERIC, 0))
    ) > 0.01 THEN
        RAISE EXCEPTION 'Total (%) no coincide con subtotal + IGV (% + % = %)',
            p_datos->>'total',
            p_datos->>'subtotal',
            p_datos->>'igv',
            COALESCE((p_datos->>'subtotal')::NUMERIC, 0) + COALESCE((p_datos->>'igv')::NUMERIC, 0);
    END IF;

    -- tipo_cambio required for USD invoices
    IF COALESCE(p_datos->>'moneda', 'USD') = 'USD'
       AND (p_datos->>'tipo_cambio') IS NULL THEN
        RAISE EXCEPTION 'Se requiere tipo_cambio para facturas en USD.';
    END IF;

    INSERT INTO doc.factura_proveedor(
        tercero_id, serie, numero,
        fecha_emision, fecha_vencimiento,
        tipo_pago, moneda, tipo_cambio,
        subtotal, igv, total,
        observacion, usr_cre
    )
    VALUES (
        (p_datos->>'tercero_id')::INT,
        p_datos->>'serie',
        (p_datos->>'numero')::INT,
        (p_datos->>'fecha_emision')::DATE,
        (p_datos->>'fecha_vencimiento')::DATE,
        COALESCE((p_datos->>'tipo_pago')::tipo_pago_enum, 'al contado'),
        COALESCE(p_datos->>'moneda', 'USD'),
        (p_datos->>'tipo_cambio')::NUMERIC,
        (p_datos->>'subtotal')::NUMERIC,
        COALESCE((p_datos->>'igv')::NUMERIC, 0),
        (p_datos->>'total')::NUMERIC,
        p_datos->>'observacion',
        v_usr_id
    )
    RETURNING id INTO v_factura_id;

    -- Insert detail lines if provided
    -- p_datos->'lineas': [{item_id, cantidad, precio_unitario, igv_porcentaje?}]
    IF p_datos ? 'lineas' AND jsonb_array_length(p_datos->'lineas') > 0 THEN
        INSERT INTO doc.factura_proveedor_detalle (
            factura_proveedor_id, item_id, cantidad, precio_unitario, igv_porcentaje, usr_cre
        )
        SELECT
            v_factura_id,
            (l->>'item_id')::INT,
            (l->>'cantidad')::NUMERIC,
            (l->>'precio_unitario')::NUMERIC,
            COALESCE((l->>'igv_porcentaje')::NUMERIC, 18),
            v_usr_id
        FROM jsonb_array_elements(p_datos->'lineas') l;
    END IF;

    -- Link to compra if provided
    IF v_compra_id IS NOT NULL THEN
        IF NOT EXISTS (
            SELECT 1 FROM doc.compra
            WHERE id = v_compra_id
              AND tercero_id = (p_datos->>'tercero_id')::INT
        ) THEN
            RAISE EXCEPTION 'Compra #% no encontrada o no pertenece al mismo proveedor.', v_compra_id;
        END IF;

        INSERT INTO doc.compra_factura_proveedor(compra_id, factura_proveedor_id, usr_cre)
        VALUES (v_compra_id, v_factura_id, v_usr_id)
        ON CONFLICT DO NOTHING;
    END IF;

    RETURN v_factura_id;
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_factura_proveedor - User: %, Error: %', v_usr_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.registrar_factura_proveedor(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.registrar_letra(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.registrar_letra(p_datos jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id        int    := get_user_id();
    v_tercero_id    int    := (p_datos->>'tercero_id')::INT;
    v_letra_id      bigint;
    v_total_aplicado numeric;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_letra', v_usr_id, p_datos);

    -- All linked facturas must belong to the same tercero as the letra
    IF p_datos ? 'facturas' AND jsonb_array_length(p_datos->'facturas') > 0 THEN
        IF EXISTS (
            SELECT 1 FROM doc.factura_proveedor fp
            WHERE fp.id IN (
                SELECT (f->>'factura_proveedor_id')::bigint
                FROM jsonb_array_elements(p_datos->'facturas') f
            )
            AND fp.tercero_id IS DISTINCT FROM v_tercero_id
        ) THEN
            RAISE EXCEPTION 'Una o más facturas no pertenecen al tercero indicado (%).', v_tercero_id;
        END IF;

        IF EXISTS (
            SELECT 1 FROM doc.factura_proveedor fp
            WHERE fp.id IN (
                SELECT (f->>'factura_proveedor_id')::bigint
                FROM jsonb_array_elements(p_datos->'facturas') f
            )
            AND fp.estado_pago IN ('total', 'anulado')
        ) THEN
            RAISE EXCEPTION 'Una o más facturas ya están completamente pagadas o anuladas.';
        END IF;
    END IF;

    -- Validate sum of monto_aplicado does not exceed letra monto
    SELECT COALESCE(SUM((f->>'monto_aplicado')::NUMERIC), 0)
    INTO v_total_aplicado
    FROM jsonb_array_elements(COALESCE(p_datos->'facturas', '[]'::jsonb)) f;

    IF v_total_aplicado > (p_datos->>'monto')::NUMERIC THEN
        RAISE EXCEPTION 'Monto aplicado total (%) excede monto de letra (%).',
            v_total_aplicado, (p_datos->>'monto')::NUMERIC;
    END IF;

    -- Create the letra header
    INSERT INTO doc.letra(
        tercero_id, numero, monto,
        fecha_giro, fecha_vencimiento, banco, usr_cre
    )
    VALUES (
        v_tercero_id,
        p_datos->>'numero',
        (p_datos->>'monto')::NUMERIC,
        (p_datos->>'fecha_giro')::DATE,
        (p_datos->>'fecha_vencimiento')::DATE,
        p_datos->>'banco',
        v_usr_id
    )
    RETURNING id INTO v_letra_id;

    -- Link to invoices via clearing junction
    IF p_datos ? 'facturas' AND jsonb_array_length(p_datos->'facturas') > 0 THEN
        INSERT INTO doc.letra_factura(letra_id, factura_proveedor_id, monto_aplicado, fyh_cre)
        SELECT
            v_letra_id,
            (f->>'factura_proveedor_id')::bigint,
            (f->>'monto_aplicado')::NUMERIC,
            NOW()
        FROM jsonb_array_elements(p_datos->'facturas') f;

        -- Mark linked facturas as credito payment type
        UPDATE doc.factura_proveedor
        SET tipo_pago = 'credito', usr_mod = v_usr_id, fyh_mod = NOW()
        WHERE id IN (
            SELECT (f->>'factura_proveedor_id')::bigint
            FROM jsonb_array_elements(p_datos->'facturas') f
        );
    END IF;

    RETURN v_letra_id;
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_letra - User: %, Error: %', v_usr_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.registrar_letra(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.registrar_muestra_ingreso(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.registrar_muestra_ingreso(p_datos jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'inventario', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id          int      := get_user_id();
    v_entrega_id      bigint;
    v_entrega_tipo_id smallint;
    v_tercero_id      int;
    v_ubicacion_id    int;
    v_fecha_mov       timestamptz;
    v_observacion     text;
    v_doc_mov_id      bigint;
    v_mov_tipo_id     smallint;
    v_elem            jsonb;
    v_item_id         int;
    v_cantidad        numeric;
    v_n_rollos        int;
    v_detalle_id      bigint;
    v_lote_id         int;
    v_linea           smallint := 0;
    v_flg_rollo       boolean;
    v_prorate         boolean;
    v_peso_rollo      numeric;
    i                 int;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_muestra_ingreso', v_usr_id, p_datos);

    v_tercero_id := (p_datos->>'tercero_id')::int;
    IF v_tercero_id IS NULL THEN
        RAISE EXCEPTION 'tercero_id requerido: la muestra debe registrar su procedencia.';
    END IF;

    SELECT id INTO STRICT v_entrega_tipo_id
    FROM doc.entrega_tipo WHERE codigo = 'MUESTRA_INGRESO';

    SELECT id INTO STRICT v_mov_tipo_id
    FROM inventario.item_movimiento_tipo WHERE codigo = 'MUESTRA_ING';

    v_fecha_mov   := COALESCE((p_datos->>'fecha')::timestamptz, now());
    v_observacion := p_datos->>'observacion';

    INSERT INTO doc.entrega (entrega_tipo_id, tercero_id, serie, correlativo, fecha_emision, fecha_recepcion)
    VALUES (v_entrega_tipo_id, v_tercero_id, p_datos->>'serie', p_datos->>'correlativo',
            v_fecha_mov, v_fecha_mov)
    RETURNING id INTO v_entrega_id;

    v_doc_mov_id := nextval('inventario.mov_doc_seq');

    IF (p_datos->>'ubicacion_id') IS NOT NULL THEN
        v_ubicacion_id := (p_datos->>'ubicacion_id')::int;
    ELSE
        SELECT ub.id INTO STRICT v_ubicacion_id
        FROM inventario.ubicacion ub
        JOIN inventario.almacen alm ON alm.id = ub.almacen_id
        WHERE alm.codigo = 'ALM_CRU' LIMIT 1;
    END IF;

    FOR v_elem IN SELECT jsonb_array_elements(p_datos->'items') LOOP
        v_item_id  := (v_elem->>'item_id')::int;
        v_cantidad := (v_elem->>'cantidad')::numeric;
        v_n_rollos := (v_elem->>'n_rollos')::int;
        v_linea    := v_linea + 1;

        INSERT INTO doc.entrega_detalle (entrega_id, linea, item_id, cantidad, n_rollos)
        VALUES (v_entrega_id, v_linea, v_item_id, v_cantidad, v_n_rollos)
        RETURNING id INTO v_detalle_id;

        SELECT EXISTS (
            SELECT 1 FROM item i
            JOIN item_tipo it ON it.id = i.item_tipo_id AND it.codigo = 'ROLLO'
            WHERE i.id = v_item_id
        ) INTO v_flg_rollo;

        IF v_flg_rollo AND v_n_rollos IS NOT NULL THEN
            v_prorate    := COALESCE((v_elem->>'prorate')::boolean, true);
            v_peso_rollo := CASE WHEN v_prorate THEN v_cantidad / v_n_rollos ELSE v_cantidad END;

            FOR i IN 1 .. v_n_rollos LOOP
                INSERT INTO inventario.lote (item_id, documento_tipo, documento_id, cantidad, propietario_id, usr_cre)
                VALUES (v_item_id, 'entrega', v_entrega_id, v_peso_rollo, NULL, v_usr_id)
                RETURNING id INTO v_lote_id;

                INSERT INTO inventario.lote_rollo_detalle (lote_id, entrega_id, flg_tenido)
                VALUES (v_lote_id, v_entrega_id, false);

                INSERT INTO inventario.item_movimientos (
                    doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
                    destino_ubicacion_id, cantidad, fecha_hora,
                    documento_tipo, documento_id, documento_linea_id, observacion, usr_cre
                ) VALUES (
                    v_doc_mov_id, v_item_id, v_lote_id, v_mov_tipo_id,
                    v_ubicacion_id, v_peso_rollo, v_fecha_mov,
                    'entrega', v_entrega_id, v_detalle_id, v_observacion, v_usr_id
                );
            END LOOP;

        ELSE
            INSERT INTO inventario.lote (item_id, documento_tipo, documento_id, cantidad, propietario_id, usr_cre)
            VALUES (v_item_id, 'entrega', v_entrega_id, v_cantidad, NULL, v_usr_id)
            RETURNING id INTO v_lote_id;

            INSERT INTO inventario.item_movimientos (
                doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
                destino_ubicacion_id, cantidad, fecha_hora,
                documento_tipo, documento_id, documento_linea_id, observacion, usr_cre
            ) VALUES (
                v_doc_mov_id, v_item_id, v_lote_id, v_mov_tipo_id,
                v_ubicacion_id, v_cantidad, v_fecha_mov,
                'entrega', v_entrega_id, v_detalle_id, v_observacion, v_usr_id
            );
        END IF;

    END LOOP;

    INSERT INTO notification.notifications(user_id, title, body, tipo, payload)
    SELECT ur.user_id,
           'Ingreso de muestra',
           COALESCE((SELECT COALESCE(nombre, 'Usuario desconocido') || ' ' || apellido FROM usuario WHERE id = v_usr_id), 'sistema')
               || ' registró una muestra sin costo (no valorizada).',
           'info',
           jsonb_build_object(
               'objeto_tipo',       'entrega',
               'entrega_id',        v_entrega_id,
               'doc_movimiento_id', v_doc_mov_id
           )
    FROM iam.user_rol ur
    LEFT JOIN iam.rol r ON ur.rol_id = r.id
    WHERE r.code IN ('jefe_planta', 'compras', 'inventario')
      AND v_usr_id <> ur.user_id;

    RETURN v_entrega_id;

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
        v_message = MESSAGE_TEXT, v_detail = PG_EXCEPTION_DETAIL,
        v_hint    = PG_EXCEPTION_HINT, v_context = PG_EXCEPTION_CONTEXT,
        v_sqlstate = RETURNED_SQLSTATE;
    RAISE EXCEPTION 'registrar_muestra_ingreso: % | detail: % | hint: % | context: % | state: %',
        v_message, v_detail, v_hint, v_context, v_sqlstate;
END;
$$;


ALTER FUNCTION doc.registrar_muestra_ingreso(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.registrar_numero_entrega(bigint, text, text)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.registrar_numero_entrega(p_entrega_id bigint, p_serie text, p_correlativo text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'doc', 'public'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id       int := get_user_id();
    v_serie_actual text;
    v_fyh_elm      timestamptz;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_serie IS NULL OR trim(p_serie) = ''
       OR p_correlativo IS NULL OR trim(p_correlativo) = '' THEN
        RAISE EXCEPTION 'Se requieren serie y correlativo para numerar la guía.';
    END IF;

    SELECT gr.serie, gr.fyh_elm
    INTO   v_serie_actual, v_fyh_elm
    FROM   doc.entrega gr
    WHERE  gr.id = p_entrega_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Guía #% no encontrada.', p_entrega_id;
    END IF;
    IF v_fyh_elm IS NOT NULL THEN
        RAISE EXCEPTION 'Guía #% está anulada y no puede numerarse.', p_entrega_id;
    END IF;
    IF v_serie_actual IS NOT NULL THEN
        RAISE EXCEPTION 'Guía #% ya tiene número (%-%). Para corregirlo, anule y reemita.',
            p_entrega_id, v_serie_actual, (SELECT correlativo FROM doc.entrega WHERE id = p_entrega_id);
    END IF;

    BEGIN
        UPDATE doc.entrega
        SET serie       = trim(p_serie),
            correlativo = trim(p_correlativo),
            usr_mod     = v_usr_id,
            fyh_mod     = now()
        WHERE id = p_entrega_id;
    EXCEPTION WHEN unique_violation THEN
        RAISE EXCEPTION 'El número %-% ya existe para este cliente y tipo de guía.',
            trim(p_serie), trim(p_correlativo);
    END;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_numero_entrega', v_usr_id,
            jsonb_build_object('entrega_id', p_entrega_id,
                               'serie', trim(p_serie),
                               'correlativo', trim(p_correlativo)));

    RETURN format('Guía #%s numerada como %s-%s.', p_entrega_id, trim(p_serie), trim(p_correlativo));

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_numero_entrega - User: %, entrega: %, Error: %',
        v_usr_id, p_entrega_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.registrar_numero_entrega(p_entrega_id bigint, p_serie text, p_correlativo text) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.revertir_recepcion_orden_servicio(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.revertir_recepcion_orden_servicio(p_datos jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'mes', 'inventario'
    AS $$
DECLARE
    v_usr_id         INT    := get_user_id();
    v_os_id          BIGINT := (p_datos->>'orden_servicio_id')::BIGINT;
    v_rev_tipo_id    SMALLINT;
    v_serv_ing_id    SMALLINT;
    v_doc_mov_id     BIGINT;
    v_motivo         TEXT   := p_datos->>'motivo';
    v_lote           RECORD;
    v_ubic           INT;
    v_detalle_id     BIGINT;
BEGIN
    -- reversal/anular is an editar-tier action (per the entrega convention)
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('revertir_recepcion_orden_servicio', v_usr_id, p_datos);

    IF NOT EXISTS (SELECT 1 FROM doc.orden_servicio WHERE id = v_os_id AND flg_elm = false) THEN
        RAISE EXCEPTION 'orden_servicio % no existe o fue eliminada.', v_os_id;
    END IF;

    SELECT id INTO STRICT v_rev_tipo_id FROM inventario.item_movimiento_tipo WHERE codigo = 'SERV_ING_REV';
    SELECT id INTO STRICT v_serv_ing_id FROM inventario.item_movimiento_tipo WHERE codigo = 'SERV_ING';
    v_doc_mov_id := nextval('inventario.mov_doc_seq');

    FOR v_lote IN
        SELECT l.id, l.item_id, l.cantidad
        FROM inventario.lote l
        WHERE l.id IN (SELECT (jsonb_array_elements_text(p_datos->'lote_ids'))::INT)
          AND l.documento_tipo = 'orden_servicio'
          AND l.documento_id   = v_os_id
          AND l.fyh_elm IS NULL
    LOOP
        -- reserved by an active partida → block
        IF EXISTS (
            SELECT 1 FROM mes.partida_componente pc
            JOIN mes.partida p ON p.id = pc.partida_id
            WHERE pc.lote_id = v_lote.id
              AND p.estado_produccion NOT IN ('CANCELADA','TECO','CERRADA')
        ) THEN
            RAISE EXCEPTION 'Rollo % está reservado en una partida activa; no se puede revertir.', v_lote.id;
        END IF;

        -- any movement other than its SERV_ING ingress → already in play, block
        IF EXISTS (
            SELECT 1 FROM inventario.item_movimientos im
            WHERE im.lote_id = v_lote.id
              AND im.item_movimiento_tipo_id <> v_serv_ing_id
        ) THEN
            RAISE EXCEPTION 'Rollo % tiene movimientos posteriores; no se puede revertir.', v_lote.id;
        END IF;

        -- locate current location + the line from the ingress movement
        SELECT im.destino_ubicacion_id, im.documento_linea_id
        INTO v_ubic, v_detalle_id
        FROM inventario.item_movimientos im
        WHERE im.lote_id = v_lote.id
          AND im.documento_tipo = 'orden_servicio'
          AND im.documento_id   = v_os_id
        ORDER BY im.id LIMIT 1;

        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, cantidad, fecha_hora,
            documento_tipo, documento_id, documento_linea_id, observacion, usr_cre
        ) VALUES (
            v_doc_mov_id, v_lote.item_id, v_lote.id, v_rev_tipo_id,
            v_ubic, v_lote.cantidad, now(),
            'orden_servicio', v_os_id, v_detalle_id, v_motivo, v_usr_id
        );

        UPDATE inventario.lote SET fyh_elm = now(), usr_elm = v_usr_id WHERE id = v_lote.id;

        UPDATE doc.orden_servicio_detalle
        SET cantidad_recibida = GREATEST(cantidad_recibida - 1, 0)
        WHERE id = v_detalle_id;
    END LOOP;

    RETURN v_doc_mov_id;
EXCEPTION
    WHEN OTHERS THEN
        RAISE LOG 'Error in revertir_recepcion_orden_servicio - User: %, Params: %, Error: %',
                  v_usr_id, p_datos::TEXT, SQLERRM;
        RAISE;
END;
$$;


ALTER FUNCTION doc.revertir_recepcion_orden_servicio(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.upsert_catalogo_precio(smallint, integer, integer, integer, integer, smallint, numeric)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.upsert_catalogo_precio(p_operacion_id smallint, p_color_x_cliente_id integer, p_tercero_id integer, p_grupo_articulo_id integer, p_tenido_id integer, p_fibra smallint, p_precio_kg numeric) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'receta', 'doc', 'public'
    AS $$
DECLARE
    v_usr_id       INT := get_user_id();
    v_id           BIGINT;
    v_receta_id    INT;
    v_costo_kg     NUMERIC(10,4);
    v_tenido_op_id SMALLINT;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('upsert_catalogo_precio', v_usr_id, jsonb_build_object(
        'operacion_id', p_operacion_id,
        'color_x_cliente_id', p_color_x_cliente_id,
        'tercero_id', p_tercero_id,
        'grupo_articulo_id', p_grupo_articulo_id,
        'tenido_id', p_tenido_id,
        'fibra', p_fibra,
        'precio_kg', p_precio_kg
    ));

    IF p_color_x_cliente_id IS NOT NULL AND p_tercero_id IS NOT NULL THEN
        RAISE EXCEPTION 'color_x_cliente_id and tercero_id are mutually exclusive';
    END IF;

    SELECT id INTO v_tenido_op_id FROM mes.operacion WHERE codigo = 'TENIDO';

    -- Cost snapshot is contextual only — no longer tied to a specific recipe
    -- variant. Grab whichever approved recipe matches the other dimensions;
    -- prefer the base (non-antipilling) one, tie-break most recent.
    IF p_operacion_id = v_tenido_op_id THEN
        SELECT rt.id INTO v_receta_id
        FROM receta.tenido rt
        WHERE rt.color_x_cliente_id = p_color_x_cliente_id
          AND rt.grupo_articulo_id  = p_grupo_articulo_id
          AND rt.fibra               = p_fibra
          AND rt.tenido_id           = p_tenido_id
          AND rt.flg_produccion      = true
          -- receta.tenido is shared across recipe types; pin to Teñido (7) so the
          -- cost snapshot can't be taken from a desmontado/rebaje row on the same
          -- keys. Matches the gate in doc.vw_precios_pendientes.
          AND rt.tipo_receta_id      = 7
        ORDER BY rt.flg_antipilling ASC, rt.fyh_produccion DESC NULLS LAST
        LIMIT 1;

        IF v_receta_id IS NOT NULL THEN
            v_costo_kg := doc.fn_get_costo_receta(v_receta_id);
        END IF;
    END IF;

    -- Normalize the TENIDO grupo to its pricing family AFTER the recipe/cost
    -- lookup above (recipes match the LITERAL grupo) so the catalog row is stored
    -- under the same bucket the price lookup normalizes to.
    IF p_operacion_id = v_tenido_op_id THEN
        p_grupo_articulo_id := doc.fn_familia_precio(
            p_grupo_articulo_id,
            COALESCE(p_tercero_id,
                     (SELECT cxc.tercero_id FROM color_x_cliente cxc WHERE cxc.id = p_color_x_cliente_id))
        );
    END IF;

    -- The COALESCE(...,-1) shape must stay in lockstep with
    -- uq_catalogo_precios_activo (re-keyed onto grupo_articulo_id in
    -- migration/33b). If they diverge, this close-then-insert stops matching the
    -- row the index considers a duplicate and the INSERT below fails on the
    -- unique violation instead of replacing cleanly.
    UPDATE doc.catalogo_precios
    SET fyh_elm = NOW(), usr_elm = v_usr_id
    WHERE
        operacion_id = p_operacion_id
        AND COALESCE(color_x_cliente_id,   -1) = COALESCE(p_color_x_cliente_id,   -1)
        AND COALESCE(tercero_id,           -1) = COALESCE(p_tercero_id,           -1)
        AND COALESCE(grupo_articulo_id,    -1) = COALESCE(p_grupo_articulo_id,    -1)
        AND COALESCE(tenido_id,            -1) = COALESCE(p_tenido_id,            -1)
        AND COALESCE(fibra::int,           -1) = COALESCE(p_fibra::int,           -1)
        AND fyh_elm IS NULL;

    INSERT INTO doc.catalogo_precios (
        operacion_id, color_x_cliente_id, tercero_id, grupo_articulo_id,
        tenido_id, fibra, precio_kg, costo_kg, usr_cre
    ) VALUES (
        p_operacion_id, p_color_x_cliente_id, p_tercero_id, p_grupo_articulo_id,
        p_tenido_id, p_fibra, p_precio_kg, v_costo_kg, v_usr_id
    )
    RETURNING id INTO v_id;

    RETURN v_id;
END;
$$;


ALTER FUNCTION doc.upsert_catalogo_precio(p_operacion_id smallint, p_color_x_cliente_id integer, p_tercero_id integer, p_grupo_articulo_id integer, p_tenido_id integer, p_fibra smallint, p_precio_kg numeric) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.upsert_familia_precio(integer, integer, integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.upsert_familia_precio(p_grupo_articulo_id integer, p_tercero_id integer, p_familia_grupo_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'doc', 'public'
    AS $$
DECLARE
    v_usr_id INT := get_user_id();
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_grupo_articulo_id IS NULL OR p_familia_grupo_id IS NULL THEN
        RAISE EXCEPTION 'grupo_articulo_id y familia_grupo_id son obligatorios';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('upsert_familia_precio', v_usr_id, jsonb_build_object(
        'grupo_articulo_id', p_grupo_articulo_id,
        'tercero_id', p_tercero_id,
        'familia_grupo_id', p_familia_grupo_id
    ));

    UPDATE doc.articulo_tipo_familia
    SET familia_grupo_id = p_familia_grupo_id,
        usr_mod = v_usr_id,
        fyh_mod = NOW()
    WHERE grupo_articulo_id = p_grupo_articulo_id
      AND tercero_id IS NOT DISTINCT FROM p_tercero_id;

    IF NOT FOUND THEN
        INSERT INTO doc.articulo_tipo_familia
            (grupo_articulo_id, tercero_id, familia_grupo_id, usr_cre)
        VALUES
            (p_grupo_articulo_id, p_tercero_id, p_familia_grupo_id, v_usr_id);
    END IF;
END;
$$;


ALTER FUNCTION doc.upsert_familia_precio(p_grupo_articulo_id integer, p_tercero_id integer, p_familia_grupo_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.vincular_facturas_compra(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.vincular_facturas_compra(p_compra_id bigint, p_factura_ids jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id    int := get_user_id();
    v_proveedor int;
    v_linked    int;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT tercero_id INTO v_proveedor
    FROM doc.compra WHERE id = p_compra_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Compra #% no encontrada.', p_compra_id;
    END IF;

    IF EXISTS (
        SELECT 1 FROM doc.factura_proveedor
        WHERE id IN (SELECT jsonb_array_elements_text(p_factura_ids)::bigint)
          AND tercero_id IS DISTINCT FROM v_proveedor
    ) THEN
        RAISE EXCEPTION 'Una o más facturas no pertenecen al proveedor de la compra #%.', p_compra_id;
    END IF;

    INSERT INTO doc.compra_factura_proveedor(compra_id, factura_proveedor_id, usr_cre)
    SELECT p_compra_id, jsonb_array_elements_text(p_factura_ids)::bigint, v_usr_id
    ON CONFLICT DO NOTHING;

    GET DIAGNOSTICS v_linked = ROW_COUNT;

    RETURN format('%s factura(s) vinculada(s) a compra #%s.', v_linked, p_compra_id);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in vincular_facturas_compra - User: %, compra: %, Error: %', v_usr_id, p_compra_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.vincular_facturas_compra(p_compra_id bigint, p_factura_ids jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: doc.vincular_guias_compra(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION doc.vincular_guias_compra(p_compra_id bigint, p_guia_ids jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id     int := get_user_id();
    v_proveedor  int;
    v_linked     int;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT tercero_id INTO v_proveedor
    FROM doc.compra WHERE id = p_compra_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Compra #% no encontrada.', p_compra_id;
    END IF;

    -- All guias must belong to the same tercero as the compra
    IF EXISTS (
        SELECT 1 FROM doc.guia_remision
        WHERE id IN (SELECT jsonb_array_elements_text(p_guia_ids)::bigint)
          AND tercero_id IS DISTINCT FROM v_proveedor
    ) THEN
        RAISE EXCEPTION 'Una o más guías no pertenecen al proveedor de la compra #%.', p_compra_id;
    END IF;

    INSERT INTO doc.compra_guia_remision(compra_id, guia_remision_id)
    SELECT p_compra_id, jsonb_array_elements_text(p_guia_ids)::bigint
    ON CONFLICT DO NOTHING;

    GET DIAGNOSTICS v_linked = ROW_COUNT;

    RETURN format('%s guía(s) vinculada(s) a compra #%s.', v_linked, p_compra_id);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in vincular_guias_compra - User: %, compra: %, Error: %', v_usr_id, p_compra_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION doc.vincular_guias_compra(p_compra_id bigint, p_guia_ids jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.anular_cuadre_ejecutado(bigint, text)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.anular_cuadre_ejecutado(p_cuadre_id bigint, p_motivo text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int  := get_user_id();
    v_cuadre_estado     text;
    v_tipo_ajuste_pos   smallint;
    v_tipo_ajuste_neg   smallint;
    v_doc_mov_id        bigint;
    v_orig_doc_mov_ids  bigint[];
    v_count_neg         int;
    v_count_pos         int;
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_motivo IS NULL OR trim(p_motivo) = '' THEN
        RAISE EXCEPTION 'Se requiere motivo para anular el cuadre.';
    END IF;

    SELECT estado INTO v_cuadre_estado FROM inventario.cuadre WHERE id = p_cuadre_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cuadre % no encontrado.', p_cuadre_id;
    END IF;
    IF v_cuadre_estado <> 'ejecutado' THEN
        RAISE EXCEPTION 'El cuadre #% está en estado %. Solo se pueden anular cuadres en estado ejecutado.',
            p_cuadre_id, v_cuadre_estado;
    END IF;

    SELECT id INTO v_tipo_ajuste_pos FROM inventario.item_movimiento_tipo WHERE codigo = 'AJUSTE_POS';
    SELECT id INTO v_tipo_ajuste_neg FROM inventario.item_movimiento_tipo WHERE codigo = 'AJUSTE_NEG';
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

    -- Scope to only the movements posted by the most recent finalizar_cuadre
    -- call (its single doc_movimiento_id batch). A cuadre may have been
    -- finalized more than once historically (finalize -> anular -> finalize
    -- again); reversing the whole documento_id history would also re-touch
    -- prior, already-settled batches and (worse) the counter-movements this
    -- same call is about to insert, since they share documento_id too.
    SELECT ARRAY[MAX(im.doc_movimiento_id)]
    INTO   v_orig_doc_mov_ids
    FROM   inventario.item_movimientos im
    JOIN   inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
    WHERE  im.documento_tipo = 'cuadre'
      AND  im.documento_id   = p_cuadre_id
      AND  imt.codigo IN ('AJUSTE_NEG','AJUSTE_POS');

    -- Guard: surplus lotes created by this batch must have no downstream movements
    IF EXISTS (
        SELECT 1
        FROM   inventario.lote l
        JOIN   inventario.item_movimientos im      ON im.lote_id = l.id
        JOIN   inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE  l.documento_tipo = 'cuadre'
          AND  l.documento_id   = p_cuadre_id
          AND  EXISTS (
              SELECT 1 FROM inventario.item_movimientos im2
              JOIN inventario.item_movimiento_tipo imt2 ON imt2.id = im2.item_movimiento_tipo_id
              WHERE im2.lote_id = l.id
                AND im2.doc_movimiento_id = ANY(v_orig_doc_mov_ids)
                AND imt2.codigo = 'AJUSTE_POS'
          )
          AND  im.doc_movimiento_id <> ALL(v_orig_doc_mov_ids)
    ) THEN
        RAISE EXCEPTION
            'No se puede anular el cuadre #%: los lotes de sobrante ya tienen movimientos posteriores. Anule esos documentos primero.',
            p_cuadre_id;
    END IF;

    -- Reverse AJUSTE_NEG (faltantes): restore each deducted lote back to stock
    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        destino_ubicacion_id, cantidad, precio_unitario, documento_tipo, documento_id
    )
    SELECT
        v_doc_mov_id,
        im.item_id, im.lote_id, v_tipo_ajuste_pos,
        im.origen_ubicacion_id,   -- was taken from here → restore to same location
        im.cantidad,
        im.precio_unitario,
        'cuadre', p_cuadre_id
    FROM   inventario.item_movimientos im
    JOIN   inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
    WHERE  im.documento_tipo   = 'cuadre'
      AND  im.documento_id     = p_cuadre_id
      AND  im.doc_movimiento_id = ANY(v_orig_doc_mov_ids)
      AND  imt.codigo          = 'AJUSTE_NEG';

    GET DIAGNOSTICS v_count_neg = ROW_COUNT;

    -- Reverse AJUSTE_POS (sobrantes): remove each surplus lote from stock
    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        origen_ubicacion_id, cantidad, precio_unitario, documento_tipo, documento_id
    )
    SELECT
        v_doc_mov_id,
        im.item_id, im.lote_id, v_tipo_ajuste_neg,
        im.destino_ubicacion_id,  -- was added here → remove from same location
        im.cantidad,
        im.precio_unitario,
        'cuadre', p_cuadre_id
    FROM   inventario.item_movimientos im
    JOIN   inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
    WHERE  im.documento_tipo   = 'cuadre'
      AND  im.documento_id     = p_cuadre_id
      AND  im.doc_movimiento_id = ANY(v_orig_doc_mov_ids)
      AND  imt.codigo          = 'AJUSTE_POS';

    GET DIAGNOSTICS v_count_pos = ROW_COUNT;

    -- Soft-delete surplus lotes created by the batch being reversed
    UPDATE inventario.lote l
    SET fyh_elm = NOW(), usr_elm = v_usr_id
    WHERE l.documento_tipo = 'cuadre'
      AND l.documento_id   = p_cuadre_id
      AND l.fyh_elm        IS NULL
      AND EXISTS (
          SELECT 1
          FROM   inventario.item_movimientos im
          JOIN   inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
          WHERE  im.lote_id = l.id
            AND  im.doc_movimiento_id = ANY(v_orig_doc_mov_ids)
            AND  imt.codigo = 'AJUSTE_POS'
      );

    -- Reset cuadre to borrador
    UPDATE inventario.cuadre
    SET estado       = 'borrador',
        fecha_cierre = NULL,
        usr_mod      = v_usr_id,
        fyh_mod      = NOW()
    WHERE id = p_cuadre_id;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_cuadre_ejecutado', v_usr_id,
            jsonb_build_object('cuadre_id', p_cuadre_id, 'motivo', p_motivo,
                               'faltantes_revertidos', v_count_neg,
                               'sobrantes_revertidos', v_count_pos));

    RETURN format('Cuadre #%s anulado: %s ajuste(s) de faltante y %s ajuste(s) de sobrante revertidos.',
                  p_cuadre_id, v_count_neg, v_count_pos);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_cuadre_ejecutado - User: %, Cuadre: %, Error: %, Detail: %',
              v_usr_id, p_cuadre_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION inventario.anular_cuadre_ejecutado(p_cuadre_id bigint, p_motivo text) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.anular_pesaje(bigint, text)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.anular_pesaje(p_lote_id bigint, p_motivo text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int     := get_user_id();
    v_item_id           int;
    v_entrega_id        bigint;
    v_peso_actual       numeric;
    v_peso_declarado    numeric;
    v_ubicacion_id      int;
    v_pesaje_pos_id     smallint;
    v_pesaje_neg_id     smallint;
    v_doc_mov_id        bigint;
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_motivo IS NULL OR trim(p_motivo) = '' THEN
        RAISE EXCEPTION 'Se requiere motivo para anular el pesaje.';
    END IF;

    -- Resolve lote + originating entrega header
    SELECT l.item_id, l.cantidad, lrd.entrega_id
    INTO   v_item_id, v_peso_actual, v_entrega_id
    FROM   inventario.lote l
    JOIN   inventario.lote_rollo_detalle lrd ON lrd.lote_id = l.id
    WHERE  l.id = p_lote_id AND l.fyh_elm IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Lote % no encontrado, ya anulado, o sin registro de rollo asociado.', p_lote_id;
    END IF;

    IF v_entrega_id IS NULL THEN
        RAISE EXCEPTION 'Lote % no tiene guía de ingreso asociada.', p_lote_id;
    END IF;

    -- Declared weight: prefer a per-roll line (lote_id set directly).
    -- Fall back to an aggregated line (lote_id NULL, n_rollos > 1, used by
    -- compra-sourced ingresos — see funciones/compras.sql) prorated evenly
    -- across its declared roll count.
    SELECT grd.cantidad INTO v_peso_declarado
    FROM doc.entrega_detalle grd
    WHERE grd.lote_id = p_lote_id;

    IF NOT FOUND THEN
        SELECT grd.cantidad / NULLIF(grd.n_rollos, 0) INTO v_peso_declarado
        FROM doc.entrega_detalle grd
        WHERE grd.entrega_id = v_entrega_id
          AND grd.item_id    = v_item_id
          AND grd.lote_id IS NULL;
    END IF;

    IF v_peso_declarado IS NULL THEN
        RAISE EXCEPTION 'Lote % (guía %): no se encontró línea de entrega_detalle para determinar el peso declarado.',
            p_lote_id, v_entrega_id;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM inventario.pesaje WHERE lote_id = p_lote_id) THEN
        RAISE EXCEPTION 'Lote % no tiene registro de pesaje activo.', p_lote_id;
    END IF;

    -- Guard: no downstream beyond PESAJE_POS/NEG and the lote's own ingress
    -- movement (roll not yet in production). The ingress movement itself
    -- (documento_tipo='entrega', documento_id=v_entrega_id) is what created
    -- the lote and is not a downstream event — exclude it, mirroring the
    -- equivalent guard in doc.anular_entrega.
    IF EXISTS (
        SELECT 1 FROM inventario.item_movimientos im
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE im.lote_id = p_lote_id
          AND imt.codigo NOT IN ('PESAJE_POS', 'PESAJE_NEG')
          AND NOT (im.documento_tipo = 'entrega' AND im.documento_id = v_entrega_id)
    ) THEN
        RAISE EXCEPTION
            'Lote % ya tiene movimientos de producción u otros. No se puede anular el pesaje.',
            p_lote_id;
    END IF;

    PERFORM 1 FROM inventario.lote WHERE id = p_lote_id FOR UPDATE;

    -- Post counter-movement only if weight actually changed from declared
    IF v_peso_actual <> v_peso_declarado THEN
        SELECT id INTO v_pesaje_pos_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_POS';
        SELECT id INTO v_pesaje_neg_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_NEG';

        SELECT sa.ubicacion_id INTO v_ubicacion_id
        FROM   inventario.vw_stock_lotes_ubicacion sa
        WHERE  sa.lote_id = p_lote_id
        LIMIT  1;

        SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

        INSERT INTO inventario.item_movimientos(
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, destino_ubicacion_id,
            cantidad, documento_tipo, documento_id
        )
        VALUES (
            v_doc_mov_id,
            v_item_id,
            p_lote_id,
            CASE WHEN v_peso_actual > v_peso_declarado THEN v_pesaje_neg_id ELSE v_pesaje_pos_id END,
            CASE WHEN v_peso_actual > v_peso_declarado THEN v_ubicacion_id  ELSE NULL END,
            CASE WHEN v_peso_actual < v_peso_declarado THEN v_ubicacion_id  ELSE NULL END,
            ABS(v_peso_actual - v_peso_declarado),
            'anulacion_pesaje',
            p_lote_id
        );
    END IF;

    UPDATE inventario.lote SET cantidad = v_peso_declarado WHERE id = p_lote_id;
    DELETE FROM inventario.pesaje WHERE lote_id = p_lote_id;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_pesaje', v_usr_id,
            jsonb_build_object('lote_id', p_lote_id, 'motivo', p_motivo,
                               'peso_revertido', v_peso_actual,
                               'peso_restaurado', v_peso_declarado));

    RETURN format('Pesaje del lote #%s anulado. Peso restaurado a %s kg (peso declarado en guía).',
                  p_lote_id, v_peso_declarado);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_pesaje - User: %, Lote: %, Error: %, Detail: %',
              v_usr_id, p_lote_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION inventario.anular_pesaje(p_lote_id bigint, p_motivo text) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.corregir_pesaje_produccion(bigint, numeric, numeric)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.corregir_pesaje_produccion(p_partida_id bigint, p_peso_regular numeric, p_peso_rib numeric) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'mes', 'inventario'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int := get_user_id();
    v_estado            partida_estado_produccion_enum;
    v_cantidad_regular     int;
    v_cantidad_rib         int;
    v_peso_por_regular  numeric;
    v_peso_por_rib      numeric;
    v_count             int;
    v_pesaje_pos_id     smallint;
    v_pesaje_neg_id     smallint;
    v_doc_movimiento_id BIGINT;
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT estado_produccion INTO v_estado
    FROM mes.partida WHERE id = p_partida_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Orden de producción con ID % no encontrada.', p_partida_id;
    END IF;
    IF v_estado IN ('TECO','CERRADA','CANCELADA') THEN
        RAISE EXCEPTION 'No se pueden corregir pesos de una orden en estado %.', v_estado;
    END IF;

    -- Count rolls by type
    SELECT
        COUNT(*) FILTER (WHERE ird.flg_rib = false),
        COUNT(*) FILTER (WHERE ird.flg_rib = true)
    INTO v_cantidad_regular, v_cantidad_rib
    FROM mes.partida_componente opi
    JOIN inventario.lote l      ON l.id = opi.lote_id AND l.fyh_elm IS NULL
    JOIN item_rollo_detalle ird ON ird.item_id = l.item_id
    WHERE opi.partida_id = p_partida_id;

    IF v_cantidad_regular = 0 AND v_cantidad_rib = 0 THEN
        RAISE EXCEPTION 'La orden % no tiene items', p_partida_id;
    END IF;
    IF p_peso_regular IS NOT NULL AND v_cantidad_regular = 0 THEN
        RAISE EXCEPTION 'Se proporcionó peso_regular pero la orden #% no tiene rollos regulares asignados.', p_partida_id;
    END IF;
    IF p_peso_rib IS NOT NULL AND v_cantidad_rib = 0 THEN
        RAISE EXCEPTION 'Se proporcionó peso_rib pero la orden #% no tiene rollos rib asignados.', p_partida_id;
    END IF;

    v_peso_por_regular := CASE WHEN v_cantidad_regular > 0 AND p_peso_regular IS NOT NULL
                               THEN ROUND(p_peso_regular / v_cantidad_regular, 4) END;
    v_peso_por_rib     := CASE WHEN v_cantidad_rib > 0 AND p_peso_rib IS NOT NULL
                               THEN ROUND(p_peso_rib / v_cantidad_rib, 4) END;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('corregir_pesaje_produccion', v_usr_id,
            jsonb_build_object('partida_id', p_partida_id, 'peso_regular', p_peso_regular, 'peso_rib', p_peso_rib));

    SELECT id INTO v_pesaje_pos_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_POS';
    SELECT id INTO v_pesaje_neg_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_NEG';
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

    WITH rolls AS (
        SELECT
            l.id        AS lote_id,
            l.item_id,
            l.cantidad  AS peso_anterior,
            sa.ubicacion_id,
            ird.flg_rib,
            CASE WHEN ird.flg_rib THEN v_peso_por_rib ELSE v_peso_por_regular END AS peso_nuevo
        FROM mes.partida_componente opi
        JOIN inventario.lote l      ON l.id = opi.lote_id AND l.fyh_elm IS NULL
        JOIN item_rollo_detalle ird ON ird.item_id = l.item_id
        JOIN inventario.vw_stock_lotes_ubicacion sa ON sa.lote_id = l.id
        WHERE opi.partida_id = p_partida_id
          AND CASE WHEN ird.flg_rib THEN v_peso_por_rib     IS NOT NULL
                   ELSE                  v_peso_por_regular IS NOT NULL END
    ),
    pesajes AS (
        INSERT INTO inventario.pesaje (lote_id, tipo, peso_real, usr_cre)
        SELECT r.lote_id, 'CORRECCION', r.peso_nuevo, v_usr_id
        FROM rolls r
        ON CONFLICT (lote_id) DO UPDATE
            SET peso_real = EXCLUDED.peso_real,
                tipo      = EXCLUDED.tipo
        RETURNING id, lote_id
    ),
    movimientos AS (
        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, destino_ubicacion_id,
            cantidad, documento_tipo, documento_id
        )
        SELECT
            v_doc_movimiento_id,
            r.item_id, r.lote_id,
            CASE WHEN r.peso_nuevo > r.peso_anterior THEN v_pesaje_pos_id ELSE v_pesaje_neg_id END,
            CASE WHEN r.peso_nuevo < r.peso_anterior THEN r.ubicacion_id ELSE NULL END,
            CASE WHEN r.peso_nuevo > r.peso_anterior THEN r.ubicacion_id ELSE NULL END,
            ABS(r.peso_nuevo - r.peso_anterior),
            'partida', p_partida_id
        FROM rolls r
        JOIN pesajes p ON p.lote_id = r.lote_id
        WHERE ABS(r.peso_nuevo - r.peso_anterior) > 0
    )
    UPDATE inventario.lote l
    SET cantidad = r.peso_nuevo
    FROM rolls r
    WHERE l.id = r.lote_id;

    GET DIAGNOSTICS v_count = ROW_COUNT;

    RETURN format(
        '%s pesos corregidos para orden #%s (%s regulares × %s kg, %s rib × %s kg).',
        v_count, p_partida_id,
        COALESCE(v_cantidad_regular, 0), COALESCE(v_peso_por_regular::text, 'sin cambio'),
        COALESCE(v_cantidad_rib, 0),     COALESCE(v_peso_por_rib::text,     'sin cambio')
    );

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
        v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in corregir_pesaje_produccion - User: %, orden: %, Error: %, Detail: %',
              v_usr_id, p_partida_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION inventario.corregir_pesaje_produccion(p_partida_id bigint, p_peso_regular numeric, p_peso_rib numeric) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.crear_almacen(json)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.crear_almacen(p_almacen json) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_message   text;
    v_detail    text;
    v_hint      text;
    v_context   text;
    v_sqlstate  text;
    v_almacen_id   INT;
    v_entrega_tipo entrega_tipo%ROWTYPE;
    v_usr_id int := get_user_id();
    v_lote_id int;
    v_error_payload jsonb;
BEGIN
    IF NOT jwt_has_permission('configuracion.operacional') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere configuracion.operacional'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

INSERT INTO inventario.almacen(codigo,nombre,usr_cre)
VALUES ((p_almacen->>'codigo')::TEXT,(p_almacen->>'nombre')::TEXT,v_usr_id)
RETURNING id INTO v_almacen_id;
IF p_almacen ? 'ubicaciones' THEN
    INSERT INTO inventario.ubicacion(almacen_id,codigo,nombre,usr_cre)
    SELECT v_almacen_id,(u->>'codigo')::TEXT,(u->>'nombre')::TEXT,v_usr_id
    FROM jsonb_array_elements(p_almacen->'ubicaciones') AS u;
END IF;

INSERT INTO notification.notifications(user_id,title,body,tipo,payload)
SELECT ur.user_id,'Nuevo almacen y ubicaciones', COALESCE((SELECT COALESCE(nombre,'Usuario desconocido') || ' ' || apellido FROM usuario WHERE id=v_usr_id),'sistema') || ' creó un nuevo almacen y ubicaciones', 'info',jsonb_build_object('objeto_tipo','almacen','almacen_id',v_almacen_id)
FROM iam.user_rol ur LEFT JOIN usuario p ON p.id=ur.user_id
LEFT JOIN iam.rol r ON ur.rol_id=r.id
WHERE r.code IN ('jefe_planta','compras','inventario') AND v_usr_id<>ur.user_id;
   RETURN format('Almacen con ID %s creado correctamente.', v_almacen_id);
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;

        RAISE LOG 'Error in crear_almacen - User: %, Params: %, Error: %, Detail: %',
                  v_usr_id, p_almacen::TEXT, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION inventario.crear_almacen(p_almacen json) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.crear_cuadre(integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.crear_cuadre(p_almacen_id integer DEFAULT NULL::integer) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'inventario', 'mes'
    AS $$
DECLARE
    v_cuadre_id BIGINT;
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- Cancel any pending cuadres for the same almacen (NULL = global).
    -- Concurrent cuadres for different almacenes are allowed.
    UPDATE inventario.cuadre
    SET estado  = 'cancelado',
        usr_mod = get_user_id(),
        fyh_mod = now()
    WHERE estado IN ('borrador', 'preparado')
      AND (almacen_id IS NOT DISTINCT FROM p_almacen_id);

    INSERT INTO inventario.cuadre (almacen_id, usr_cre)
    VALUES (p_almacen_id, get_user_id())
    RETURNING id INTO v_cuadre_id;

    -- Source from item catalog (all INSUMOs), not vw_stock_items.
    -- vw_stock_items only includes items with qty > 0 — items fully consumed
    -- wouldn't appear on the count sheet, preventing discovery of phantom stock.
    -- cantidad_sistema = 0 for items with no open lotes; operators can still flag them.
    -- When p_almacen_id is set, stock is summed only across that almacen's ubicaciones.
    INSERT INTO inventario.cuadre_detalle (
        cuadre_id,
        item_id,
        cantidad_sistema,
        precio_promedio_sistema,
        stock_valorado_sistema,
        ult_precio_compra
    )
    SELECT
        v_cuadre_id,
        i.id,
        COALESCE(sg.cantidad_total, 0),
        COALESCE(iv.precio_promedio, 0),
        COALESCE(iv.stock_valorado,  0),
        -- last purchase price: most recent COMPRA_ING movement for this item
        (SELECT im2.precio_unitario
         FROM inventario.item_movimientos im2
         JOIN inventario.item_movimiento_tipo imt2 ON imt2.id = im2.item_movimiento_tipo_id
         WHERE im2.item_id = i.id
           AND imt2.codigo = 'COMPRA_ING'
         ORDER BY im2.fecha_hora DESC NULLS LAST
         LIMIT 1)
    FROM item i
    JOIN item_tipo it ON it.id = i.item_tipo_id AND it.codigo = 'INSUMO'
    LEFT JOIN (
        SELECT si.item_id, SUM(si.cantidad_actual) AS cantidad_total
        FROM inventario.item_saldo si
        LEFT JOIN inventario.ubicacion u ON u.id = si.ubicacion_id
        WHERE p_almacen_id IS NULL OR u.almacen_id = p_almacen_id
        GROUP BY si.item_id
    ) sg ON sg.item_id = i.id
    LEFT JOIN inventario.item_valoracion iv ON iv.item_id = i.id
    WHERE i.fyh_elm IS NULL;

    RETURN v_cuadre_id;
END;
$$;


ALTER FUNCTION inventario.crear_cuadre(p_almacen_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.eliminar_almacen(integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.eliminar_almacen(p_almacen_id integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_message   text;
    v_detail    text;
    v_hint      text;
    v_context   text;
    v_sqlstate  text;
    v_almacen_id   INT;
    v_entrega_tipo entrega_tipo%ROWTYPE;
    v_usr_id int := get_user_id();
    v_almacen_nombre text;
    v_error_payload jsonb;
BEGIN
    IF NOT jwt_has_permission('configuracion.operacional') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere configuracion.operacional'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

DELETE FROM inventario.ubicacion WHERE almacen_id = p_almacen_id;
DELETE FROM inventario.almacen WHERE id = p_almacen_id
RETURNING nombre INTO v_almacen_nombre;

INSERT INTO notification.notifications(user_id,title,body,tipo,payload)
SELECT ur.user_id,'Almacen eliminado', COALESCE((SELECT COALESCE(nombre,'Usuario desconocido') || ' ' || apellido FROM usuario WHERE id=v_usr_id),'sistema') || ' eliminó un almacen y sus ubicaciones', 'info',jsonb_build_object('objeto_tipo','almacen','almacen_id',p_almacen_id)
FROM iam.user_rol ur LEFT JOIN usuario p ON p.id=ur.user_id
LEFT JOIN iam.rol r ON ur.rol_id=r.id
WHERE r.code IN ('jefe_planta','compras','inventario') AND v_usr_id<>ur.user_id;
   RETURN format('Almacen %s eliminado ', v_almacen_nombre);
EXCEPTION
    WHEN foreign_key_violation THEN
        RAISE EXCEPTION 'No se puede eliminar el almacen porque tiene ubicaciones en uso.';
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;

        RAISE LOG 'Error in eliminar_almacen - User: %, Params: %, Error: %, Detail: %',
                  v_usr_id, p_almacen_id, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION inventario.eliminar_almacen(p_almacen_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.finalizar_cuadre(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.finalizar_cuadre(p_cuadre_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'inventario', 'mes'
    AS $$
DECLARE
    v_faltantes         JSONB;
    v_cuadre_estado     inventario.cuadre_estado_enum;
    v_fecha_cierre      TIMESTAMPTZ;
    v_almacen_id        INT;
    v_doc_movimiento_id BIGINT;
    v_tipo_ajuste_neg   SMALLINT;
    v_tipo_ajuste_pos   SMALLINT;
    v_ubicacion_id      INT;
    v_fifo_result       JSONB;
    v_rec               RECORD;
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- Guard: all items must have been counted
    SELECT jsonb_agg(jsonb_build_object('id', id, 'item_id', item_id))
    INTO v_faltantes
    FROM inventario.cuadre_detalle
    WHERE cuadre_id = p_cuadre_id AND cantidad_contada IS NULL;

    IF v_faltantes IS NOT NULL THEN
        RAISE EXCEPTION USING
            MESSAGE = 'Hay items sin cantidad contada',
            DETAIL  = v_faltantes::text,
            HINT    = 'Completa los conteos antes de ejecutar el cuadre';
    END IF;

    -- Guard: cuadre must be in borrador or preparado
    SELECT estado, fecha_cierre, almacen_id
    INTO v_cuadre_estado, v_fecha_cierre, v_almacen_id
    FROM inventario.cuadre WHERE id = p_cuadre_id;

    IF v_fecha_cierre IS NOT NULL OR v_cuadre_estado NOT IN ('borrador','preparado') THEN
        RAISE EXCEPTION USING
            MESSAGE = 'El cuadre no puede ejecutarse',
            DETAIL  = jsonb_build_object(
                          'estado',       v_cuadre_estado,
                          'fecha_cierre', v_fecha_cierre
                      )::text,
            HINT    = 'Solo cuadres en borrador o preparado pueden ejecutarse';
    END IF;

    -- Cache movement type IDs and default ALM_INS location
    SELECT id INTO v_tipo_ajuste_neg FROM inventario.item_movimiento_tipo WHERE codigo = 'AJUSTE_NEG';
    SELECT id INTO v_tipo_ajuste_pos FROM inventario.item_movimiento_tipo WHERE codigo = 'AJUSTE_POS';
    IF v_almacen_id IS NOT NULL THEN
        SELECT u.id INTO v_ubicacion_id
        FROM inventario.ubicacion u
        WHERE u.almacen_id = v_almacen_id
        ORDER BY u.id
        LIMIT 1;
    ELSE
        SELECT u.id INTO v_ubicacion_id
        FROM inventario.ubicacion u
        JOIN inventario.almacen a ON a.id = u.almacen_id
        WHERE a.codigo = 'ALM_INS'
        LIMIT 1;
    END IF;

    -- One posting event for the entire cuadre
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

    -- ── AJUSTE_NEG: sistema > contada (faltantes físicos) ──────────────────
    -- Build FIFO input from all short items in one call, then post movements.
    SELECT mes.calcular_fifo(
        jsonb_agg(
            jsonb_build_object(
                'item_id',  item_id,
                'cantidad', cantidad_sistema - cantidad_contada
            )
        )
    )
    INTO v_fifo_result
    FROM inventario.cuadre_detalle
    WHERE cuadre_id = p_cuadre_id
      AND cantidad_sistema > cantidad_contada;

    IF v_fifo_result IS NOT NULL THEN
        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, cantidad,
            precio_unitario,
            documento_tipo, documento_id
        )
        SELECT
            v_doc_movimiento_id,
            (f->>'item_id')::INT,
            (f->>'lote_id')::INT,
            v_tipo_ajuste_neg,
            (f->>'ubicacion_id')::INT,
            (f->>'cantidad')::NUMERIC,
            iv.precio_promedio,        -- stamp MAP at time of adjustment
            'cuadre',
            p_cuadre_id
        FROM jsonb_array_elements(v_fifo_result) f
        LEFT JOIN inventario.item_valoracion iv ON iv.item_id = (f->>'item_id')::INT;
    END IF;

    -- ── AJUSTE_POS: contada > sistema (sobrantes físicos) ──────────────────
    -- Create a new lote per surplus item and post ingress movement.
    -- Uses CURRENT MAP from item_valoracion (not snapshot): purchases between
    -- cuadre creation and finalization may have changed the price, and the
    -- surplus item was physically present all along at current value.
    -- Falls back to precio_promedio_sistema if no MAP row exists yet.
    FOR v_rec IN
        SELECT cd.item_id,
               cd.cantidad_contada - cd.cantidad_sistema AS diferencia,
               COALESCE(iv.precio_promedio, cd.precio_promedio_sistema, 0) AS precio
        FROM inventario.cuadre_detalle cd
        LEFT JOIN inventario.item_valoracion iv ON iv.item_id = cd.item_id
        WHERE cd.cuadre_id = p_cuadre_id
          AND cd.cantidad_contada > cd.cantidad_sistema
    LOOP
        WITH ins_lote AS (
            INSERT INTO inventario.lote (item_id, documento_tipo, documento_id, cantidad)
            VALUES (v_rec.item_id, 'cuadre', p_cuadre_id, v_rec.diferencia)
            RETURNING id
        ),
        ins_lrd AS (
            -- Stub lote_rollo_detalle for surplus ROLLO lotes found during cuadre.
            -- No entrega_id — these rolls have no ingress document.
            INSERT INTO inventario.lote_rollo_detalle (lote_id, flg_tenido)
            SELECT ins_lote.id, false
            FROM ins_lote
            WHERE EXISTS (
                SELECT 1 FROM item i
                JOIN item_tipo it ON it.id = i.item_tipo_id AND it.codigo = 'ROLLO'
                WHERE i.id = v_rec.item_id
            )
        )
        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            destino_ubicacion_id, cantidad,
            precio_unitario,
            documento_tipo, documento_id
        )
        SELECT
            v_doc_movimiento_id,
            v_rec.item_id,
            ins_lote.id,
            v_tipo_ajuste_pos,
            v_ubicacion_id,
            v_rec.diferencia,
            v_rec.precio,    -- enter at MAP so weighted average stays stable
            'cuadre',
            p_cuadre_id
        FROM ins_lote;
    END LOOP;

    -- Close the cuadre
    UPDATE inventario.cuadre
    SET fecha_cierre = now(),
        estado       = 'ejecutado',
        usr_mod      = get_user_id(),
        fyh_mod      = now()
    WHERE id = p_cuadre_id;

    RETURN jsonb_build_object(
        'message',    'Cuadre finalizado correctamente',
        'cuadre_id',  p_cuadre_id
    );
END;
$$;


ALTER FUNCTION inventario.finalizar_cuadre(p_cuadre_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.fn_trg_actualizar_map()
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.fn_trg_actualizar_map() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_flg_valorizable boolean;
    v_flg_recalcula   boolean;
    v_map             numeric(12,4);
    v_stock_qty       numeric(15,7);  -- widened with item_valoracion.stock_qty
    v_stock_valorado  numeric(16,4);
BEGIN
    IF NEW.precio_unitario IS NULL THEN RETURN NEW; END IF;

    SELECT imt.flg_valorizable, imt.flg_recalcula_costo
    INTO v_flg_valorizable, v_flg_recalcula
    FROM inventario.item_movimiento_tipo imt
    WHERE imt.id = NEW.item_movimiento_tipo_id;

    IF NOT v_flg_valorizable THEN RETURN NEW; END IF;

    INSERT INTO inventario.item_valoracion (item_id, precio_promedio, stock_qty, stock_valorado)
    VALUES (NEW.item_id, 0, 0, 0)
    ON CONFLICT (item_id) DO NOTHING;

    SELECT precio_promedio, stock_qty, stock_valorado
    INTO v_map, v_stock_qty, v_stock_valorado
    FROM inventario.item_valoracion
    WHERE item_id = NEW.item_id
    FOR UPDATE;

    IF NEW.destino_ubicacion_id IS NOT NULL THEN
        IF v_flg_recalcula THEN
            v_stock_valorado := v_stock_valorado + (NEW.cantidad * NEW.precio_unitario);
            v_stock_qty      := v_stock_qty + NEW.cantidad;
            v_map            := CASE WHEN v_stock_qty > 0
                                     THEN ROUND(v_stock_valorado / v_stock_qty, 4) ELSE 0 END;
        ELSE
            v_stock_valorado := v_stock_valorado + (NEW.cantidad * v_map);
            v_stock_qty      := v_stock_qty + NEW.cantidad;
        END IF;
    ELSE
        v_stock_valorado := GREATEST(0, v_stock_valorado - (NEW.cantidad * v_map));
        v_stock_qty      := GREATEST(0, v_stock_qty - NEW.cantidad);
        IF v_stock_qty = 0 THEN v_stock_valorado := 0; END IF;
    END IF;

    INSERT INTO inventario.item_valoracion (item_id, precio_promedio, stock_qty, stock_valorado, fyh_mod)
    VALUES (NEW.item_id, v_map, v_stock_qty, v_stock_valorado, now())
    ON CONFLICT (item_id) DO UPDATE
        SET precio_promedio = EXCLUDED.precio_promedio,
            stock_qty       = EXCLUDED.stock_qty,
            stock_valorado  = EXCLUDED.stock_valorado,
            fyh_mod         = EXCLUDED.fyh_mod;
    RETURN NEW;
END;
$$;


ALTER FUNCTION inventario.fn_trg_actualizar_map() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.fn_trg_check_corte_cuadre()
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.fn_trg_check_corte_cuadre() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'inventario', 'public'
    AS $$
DECLARE
    v_almacen_ids INT[];
    v_corte       TIMESTAMPTZ;
BEGIN
    -- Resolve which almacenes this movement touches via its ubicaciones.
    SELECT array_agg(DISTINCT u.almacen_id)
    INTO v_almacen_ids
    FROM inventario.ubicacion u
    WHERE u.id IN (NEW.origen_ubicacion_id, NEW.destino_ubicacion_id);

    -- Global cuadres (almacen_id IS NULL) apply to all movements.
    -- Warehouse-scoped cuadres apply only when the movement touches that almacen.
    -- Only 'ejecutado' (finalized) cuadres lock the cutoff.
    SELECT MAX(fecha_cuadre)
    INTO v_corte
    FROM inventario.cuadre
    WHERE estado = 'ejecutado'
      AND (
          almacen_id IS NULL
          OR (v_almacen_ids IS NOT NULL AND almacen_id = ANY(v_almacen_ids))
      );

    IF v_corte IS NOT NULL AND NEW.fecha_hora < v_corte THEN
        RAISE EXCEPTION
            'Movimiento rechazado: fecha_hora (%) es anterior al corte de inventario (%).',
            NEW.fecha_hora, v_corte;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION inventario.fn_trg_check_corte_cuadre() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.fn_trg_gen_codigo_ubicacion()
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.fn_trg_gen_codigo_ubicacion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_abbrev TEXT;
    v_seq    INT;
BEGIN
    IF NEW.codigo IS NULL THEN
        SELECT regexp_replace(codigo, '^ALM_', '') INTO v_abbrev
        FROM inventario.almacen WHERE id = NEW.almacen_id;
        SELECT COUNT(*) + 1 INTO v_seq
        FROM inventario.ubicacion WHERE almacen_id = NEW.almacen_id;
        NEW.codigo := v_abbrev || '-' || LPAD(v_seq::text, 2, '0');
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION inventario.fn_trg_gen_codigo_ubicacion() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.fn_trg_resync_cuadre_detalle()
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.fn_trg_resync_cuadre_detalle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'inventario', 'public'
    AS $$
DECLARE
    v_almacen_ids INT[];
BEGIN
    SELECT array_agg(DISTINCT u.almacen_id)
    INTO v_almacen_ids
    FROM inventario.ubicacion u
    WHERE u.id IN (NEW.origen_ubicacion_id, NEW.destino_ubicacion_id);

    UPDATE inventario.cuadre_detalle cd
    SET cantidad_sistema        = COALESCE(sg.cantidad_total, 0),
        precio_promedio_sistema = COALESCE(iv.precio_promedio, 0),
        stock_valorado_sistema  = COALESCE(iv.stock_valorado, 0),
        fyh_mod                 = now()
    FROM inventario.cuadre c
    LEFT JOIN LATERAL (
        SELECT SUM(si.cantidad_actual) AS cantidad_total
        FROM inventario.item_saldo si
        LEFT JOIN inventario.ubicacion u ON u.id = si.ubicacion_id
        WHERE si.item_id = NEW.item_id
          AND (c.almacen_id IS NULL OR u.almacen_id = c.almacen_id)
    ) sg ON true
    LEFT JOIN inventario.item_valoracion iv ON iv.item_id = NEW.item_id
    WHERE cd.cuadre_id = c.id
      AND cd.item_id = NEW.item_id
      AND c.estado IN ('borrador', 'preparado')
      AND (
          c.almacen_id IS NULL
          OR (v_almacen_ids IS NOT NULL AND c.almacen_id = ANY(v_almacen_ids))
      );

    RETURN NEW;
END;
$$;


ALTER FUNCTION inventario.fn_trg_resync_cuadre_detalle() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.fn_trg_sync_cantidad_actual()
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.fn_trg_sync_cantidad_actual() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_factor SMALLINT;
BEGIN
    -- Ingress: credit destino when present.
    -- Runs even when origen is also set (transfer — SAP 311 pattern).
    IF NEW.destino_ubicacion_id IS NOT NULL THEN
        IF NEW.lote_id IS NOT NULL THEN
            INSERT INTO inventario.lote_saldo (lote_id, ubicacion_id, cantidad_actual)
            VALUES (NEW.lote_id, NEW.destino_ubicacion_id, NEW.cantidad)
            ON CONFLICT (lote_id, ubicacion_id) DO UPDATE
                SET cantidad_actual = inventario.lote_saldo.cantidad_actual + EXCLUDED.cantidad_actual;
        END IF;
        INSERT INTO inventario.item_saldo (item_id, ubicacion_id, cantidad_actual)
        VALUES (NEW.item_id, NEW.destino_ubicacion_id, NEW.cantidad)
        ON CONFLICT (item_id, ubicacion_id) DO UPDATE
            SET cantidad_actual = inventario.item_saldo.cantidad_actual + EXCLUDED.cantidad_actual;
    END IF;

    -- Egress: debit origen when present.
    -- Runs even when destino is also set (transfer).
    IF NEW.origen_ubicacion_id IS NOT NULL THEN
        IF NEW.lote_id IS NOT NULL THEN
            INSERT INTO inventario.lote_saldo (lote_id, ubicacion_id, cantidad_actual)
            VALUES (NEW.lote_id, NEW.origen_ubicacion_id, -NEW.cantidad)
            ON CONFLICT (lote_id, ubicacion_id) DO UPDATE
                SET cantidad_actual = inventario.lote_saldo.cantidad_actual + EXCLUDED.cantidad_actual;
        END IF;
        INSERT INTO inventario.item_saldo (item_id, ubicacion_id, cantidad_actual)
        VALUES (NEW.item_id, NEW.origen_ubicacion_id, -NEW.cantidad)
        ON CONFLICT (item_id, ubicacion_id) DO UPDATE
            SET cantidad_actual = inventario.item_saldo.cantidad_actual + EXCLUDED.cantidad_actual;
    END IF;

    -- Location-agnostic: both null — use movement type factor.
    -- Covers fungible consumption/ingress where no location is known.
    -- Credits/debits item_saldo at ubicacion_id = NULL (suspense bucket).
    IF NEW.origen_ubicacion_id IS NULL AND NEW.destino_ubicacion_id IS NULL THEN
        SELECT imt.factor INTO v_factor
        FROM inventario.item_movimiento_tipo imt
        WHERE imt.id = NEW.item_movimiento_tipo_id;

        IF v_factor <> 0 THEN
            INSERT INTO inventario.item_saldo (item_id, ubicacion_id, cantidad_actual)
            VALUES (NEW.item_id, NULL, v_factor * NEW.cantidad)
            ON CONFLICT (item_id, ubicacion_id) DO UPDATE
                SET cantidad_actual = inventario.item_saldo.cantidad_actual + EXCLUDED.cantidad_actual;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION inventario.fn_trg_sync_cantidad_actual() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.get_almacen(integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.get_almacen(p_almacen_id integer) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
SELECT 
jsonb_build_object(
    'id', a.id,
    'codigo', a.codigo,
    'nombre', a.nombre,
    'ubicaciones', (
        SELECT jsonb_agg( 
            jsonb_build_object(
                'id', u.id,
                'codigo', u.codigo,
                'nombre', u.nombre
            )
        )
        FROM inventario.ubicacion u
        WHERE u.almacen_id = a.id
    )
)FROM inventario.almacen a WHERE a.id = p_almacen_id;
$$;


ALTER FUNCTION inventario.get_almacen(p_almacen_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.get_cuadre(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.get_cuadre(p_cuadre_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'inventario', 'mes'
    AS $$
DECLARE
    result JSONB;
BEGIN
    SELECT jsonb_build_object(
        'cuadre_id',    c.id,
        'fecha_cuadre', c.fecha_cuadre,
        'fecha_cierre', c.fecha_cierre,
        'estado',       c.estado,
        'usr_cre',      c.usr_cre,
        'fyh_cre',      c.fyh_cre,
        'detalle', COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'id',                      cd.id,
                    'item_id',                 cd.item_id,
                    'item_codigo',             i.codigo,
                    'item_nombre',             i.nombre,
                    'cantidad_sistema',        cd.cantidad_sistema,
                    'cantidad_contada',        cd.cantidad_contada,
                    'precio_promedio_sistema', cd.precio_promedio_sistema,
                    'stock_valorado_sistema',  cd.stock_valorado_sistema,
                    'ult_precio_compra',       cd.ult_precio_compra
                ) ORDER BY i.nombre
            ) FILTER (WHERE cd.id IS NOT NULL),
            '[]'::jsonb
        )
    )
    INTO result
    FROM inventario.cuadre c
    LEFT JOIN inventario.cuadre_detalle cd ON cd.cuadre_id = c.id
    LEFT JOIN item i ON i.id = cd.item_id
    WHERE c.id = p_cuadre_id
    GROUP BY c.id;

    IF result IS NULL THEN
        RAISE EXCEPTION 'Cuadre % no existe', p_cuadre_id;
    END IF;

    RETURN result;
END;
$$;


ALTER FUNCTION inventario.get_cuadre(p_cuadre_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.get_item_movimientos_cuadre(integer, bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.get_item_movimientos_cuadre(p_item_id integer, p_cuadre_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'inventario', 'mes'
    AS $$
DECLARE
    v_fyh_desde  TIMESTAMPTZ;
    v_fyh_hasta  TIMESTAMPTZ;
    v_almacen_id INT;
BEGIN
    SELECT ult_cuadre_ejecutado_fecha, fecha_cuadre, almacen_id
    INTO v_fyh_desde, v_fyh_hasta, v_almacen_id
    FROM inventario.vw_cuadre
    WHERE cuadre_id = p_cuadre_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cuadre % no existe', p_cuadre_id;
    END IF;

    RETURN (
        SELECT jsonb_agg(
            jsonb_build_object(
                'id',             im.id,
                'tipo_codigo',    imt.codigo,
                'tipo_nombre',    imt.nombre,
                'cantidad',       im.cantidad * (
                    CASE WHEN im.destino_ubicacion_id IS NOT NULL THEN  1 ELSE 0 END +
                    CASE WHEN im.origen_ubicacion_id  IS NOT NULL THEN -1 ELSE 0 END
                ),
                'precio',         im.precio_unitario,
                'documento_tipo', im.documento_tipo,
                'documento_id',   im.documento_id,
                'fecha_hora',     im.fecha_hora
            ) ORDER BY im.fecha_hora
        )
        FROM inventario.item_movimientos im
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE im.item_id   = p_item_id
          AND im.fecha_hora >= COALESCE(v_fyh_desde, '2020-01-01')
          AND im.fecha_hora <  v_fyh_hasta
          AND (
              v_almacen_id IS NULL
              OR EXISTS (
                  SELECT 1 FROM inventario.ubicacion u
                  WHERE u.id IN (im.origen_ubicacion_id, im.destino_ubicacion_id)
                    AND u.almacen_id = v_almacen_id
              )
          )
    );
END;
$$;


ALTER FUNCTION inventario.get_item_movimientos_cuadre(p_item_id integer, p_cuadre_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.get_movimientos_item(integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.get_movimientos_item(p_item_id integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'inventario', 'mes', 'doc'
    AS $$
DECLARE
    v_item   JSONB;
    v_movs   JSONB;
BEGIN
    -- Header
    SELECT jsonb_build_object(
        'item_id',        it.id,
        'item_codigo',    it.codigo,
        'item_nombre',    it.nombre,
        'item_tipo',      ity.descripcion,
        'flg_fungible',   it.flg_fungible,
        'unidad',         u.codigo,
        'stock_actual',   COALESCE(sg.cantidad_total, 0),
        'precio_promedio', iv.precio_promedio,
        'stock_valorado', ROUND((COALESCE(sg.cantidad_total, 0) * COALESCE(iv.precio_promedio, 0))::numeric, 4)
    )
    INTO v_item
    FROM item it
    JOIN item_tipo ity                  ON ity.id = it.item_tipo_id
    JOIN unidad u                       ON u.id   = it.unidad_id
    LEFT JOIN inventario.vw_stock_items sg  ON sg.item_id  = it.id
    LEFT JOIN inventario.item_valoracion iv ON iv.item_id  = it.id
    WHERE it.id = p_item_id;

    IF v_item IS NULL THEN
        RAISE EXCEPTION 'Item #% no encontrado.', p_item_id;
    END IF;

    -- Movements with running balance
    SELECT jsonb_agg(
        jsonb_build_object(
            'id',                 m.id,
            'fecha_hora',         m.fecha_hora,
            'tipo_codigo',        m.tipo_codigo,
            'tipo_nombre',        m.tipo_nombre,
            'categoria',          m.categoria,
            'factor',             m.factor,
            'cantidad',           m.cantidad,
            'cantidad_neta',      m.cantidad_neta,
            'saldo_acumulado',    m.saldo_acumulado,
            'lote_id',            m.lote_id,
            'motivo_codigo',      m.motivo_codigo,
            'motivo_nombre',      m.motivo_nombre,
            'origen_ubicacion',   m.origen_ubicacion,
            'destino_ubicacion',  m.destino_ubicacion,
            'observacion',        m.observacion,
            'documento',          m.documento
        )
        ORDER BY m.fecha_hora, m.id
    )
    INTO v_movs
    FROM (
        SELECT
            im.id,
            im.fecha_hora,
            imt.codigo              AS tipo_codigo,
            imt.nombre              AS tipo_nombre,
            imt.categoria,
            imt.factor,
            im.cantidad,
            im.cantidad * imt.factor AS cantidad_neta,
            SUM(im.cantidad * imt.factor) OVER (
                ORDER BY im.fecha_hora, im.id
                ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
            )                        AS saldo_acumulado,
            im.lote_id,
            imm.codigo              AS motivo_codigo,
            imm.nombre              AS motivo_nombre,
            uo.nombre || COALESCE(' / ' || ao.nombre, '') AS origen_ubicacion,
            ud.nombre || COALESCE(' / ' || ad.nombre, '') AS destino_ubicacion,
            im.observacion,
            CASE im.documento_tipo
                WHEN 'partida_paso_ejecucion' THEN jsonb_build_object(
                    'tipo',           'partida',
                    'ejecucion_id',   ppe.id,
                    'partida_id',     p.id,
                    'partida_codigo', EXTRACT(YEAR FROM p.fyh_cre)::TEXT
                                      || '-' || LPAD(p.numero::TEXT, 4, '0'),
                    'operacion',      op.nombre
                )
                WHEN 'entrega' THEN jsonb_build_object(
                    'tipo',      'entrega',
                    'entrega_id',   gr.id,
                    'numero',    gr.serie || '-' || gr.correlativo,
                    'proveedor', t.nombre
                )
                ELSE NULL
            END                      AS documento
        FROM inventario.item_movimientos im
        JOIN inventario.item_movimiento_tipo imt  ON imt.id = im.item_movimiento_tipo_id
        LEFT JOIN inventario.item_movimiento_motivo imm ON imm.id = im.motivo_id
        LEFT JOIN inventario.ubicacion uo ON uo.id = im.origen_ubicacion_id
        LEFT JOIN inventario.almacen   ao ON ao.id = uo.almacen_id
        LEFT JOIN inventario.ubicacion ud ON ud.id = im.destino_ubicacion_id
        LEFT JOIN inventario.almacen   ad ON ad.id = ud.almacen_id
        -- partida_paso_ejecucion context
        LEFT JOIN mes.partida_paso_ejecucion ppe
            ON ppe.id = im.documento_id
           AND im.documento_tipo = 'partida_paso_ejecucion'
        LEFT JOIN mes.partida_paso pp ON pp.id = ppe.partida_paso_id
        LEFT JOIN mes.partida      p  ON p.id  = pp.partida_id
        LEFT JOIN mes.operacion    op ON op.id = pp.operacion_id
        -- entrega context
        LEFT JOIN doc.entrega gr
            ON gr.id = im.documento_id
           AND im.documento_tipo = 'entrega'
        LEFT JOIN tercero t ON t.id = gr.tercero_id
        WHERE im.item_id = p_item_id
    ) m;

    RETURN jsonb_build_object(
        'item',        v_item,
        'movimientos', COALESCE(v_movs, '[]'::jsonb)
    );
END;
$$;


ALTER FUNCTION inventario.get_movimientos_item(p_item_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.marcar_cuadre_preparado(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.marcar_cuadre_preparado(p_cuadre_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'inventario'
    AS $$
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    UPDATE inventario.cuadre
    SET estado   = 'preparado',
        usr_mod  = get_user_id(),
        fyh_mod  = now()
    WHERE id = p_cuadre_id
      AND estado = 'borrador';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cuadre % no existe o no está en estado borrador', p_cuadre_id;
    END IF;
END;
$$;


ALTER FUNCTION inventario.marcar_cuadre_preparado(p_cuadre_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.modificar_almacen(json)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.modificar_almacen(p_almacen json) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'inventario'
    AS $$
DECLARE
    v_message   text;
    v_detail    text;
    v_hint      text;
    v_context   text;
    v_sqlstate  text;
    v_almacen_id   INT;
    v_entrega_tipo entrega_tipo%ROWTYPE;
    v_usr_id int := get_user_id();
    v_lote_id int;
    v_error_payload jsonb;
BEGIN
    IF NOT jwt_has_permission('configuracion.operacional') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere configuracion.operacional'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

v_almacen_id := (p_almacen->>'id')::INT;

UPDATE inventario.almacen
SET codigo = (p_almacen->>'codigo')::TEXT,
    nombre = (p_almacen->>'nombre')::TEXT,
    usr_mod = v_usr_id,
    fyh_mod = NOW()
WHERE id = v_almacen_id;

IF p_almacen ? 'ubicaciones' THEN
    INSERT INTO inventario.ubicacion(almacen_id,codigo,nombre,usr_cre)
    SELECT (p_almacen->>'id')::INT,(u->>'codigo')::TEXT,(u->>'nombre')::TEXT,v_usr_id
    FROM jsonb_array_elements(p_almacen->'ubicaciones') AS u
    ON CONFLICT (almacen_id,codigo_canon) DO UPDATE SET nombre = EXCLUDED.nombre, usr_mod = v_usr_id, fyh_mod = NOW();

    DELETE FROM inventario.ubicacion WHERE almacen_id = (p_almacen->>'id')::INT
    AND codigo NOT IN (SELECT u->>'codigo' FROM jsonb_array_elements(p_almacen->'ubicaciones') AS u);
END IF;

INSERT INTO notification.notifications(user_id,title,body,tipo,payload)
SELECT ur.user_id,'Almacen y/o ubicaciones actualizadas', COALESCE((SELECT COALESCE(nombre,'Usuario desconocido') || ' ' || apellido FROM usuario WHERE id=v_usr_id),'sistema') || ' modifico un almacen y/o sus ubicaciones', 'info',jsonb_build_object('objeto_tipo','almacen','almacen_id',v_almacen_id)
FROM iam.user_rol ur LEFT JOIN usuario p ON p.id=ur.user_id
LEFT JOIN iam.rol r ON ur.rol_id=r.id
WHERE r.code IN ('jefe_planta','compras','inventario') AND v_usr_id<>ur.user_id;
   RETURN format('Almacen con ID %s modificado correctamente.', v_almacen_id);
EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;

        RAISE LOG 'Error in modificar_almacen - User: %, Params: %, Error: %, Detail: %',
                  v_usr_id, p_almacen::TEXT, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION inventario.modificar_almacen(p_almacen json) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.registrar_ajuste(integer, integer, numeric, text)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.registrar_ajuste(p_item_id integer, p_ubicacion_id integer, p_cantidad numeric, p_observacion text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int := get_user_id();
    v_doc_movimiento_id BIGINT;
    v_tipo_id           SMALLINT;
    v_lote_id           INT;
    v_precio            NUMERIC(12,4);
    v_fifo_result       JSONB;
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_cantidad = 0 THEN
        RAISE EXCEPTION 'La cantidad del ajuste no puede ser cero.';
    END IF;

    IF p_observacion IS NULL OR trim(p_observacion) = '' THEN
        RAISE EXCEPTION 'La observación es obligatoria para registrar un ajuste.';
    END IF;

    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

    SELECT COALESCE(iv.precio_promedio, 0)
    INTO v_precio
    FROM inventario.item_valoracion iv
    WHERE iv.item_id = p_item_id;

    IF p_cantidad > 0 THEN
        -- AJUSTE_POS: create a new lote and credit stock
        SELECT id INTO v_tipo_id FROM inventario.item_movimiento_tipo WHERE codigo = 'AJUSTE_POS';

        INSERT INTO inventario.lote (item_id, documento_tipo, cantidad)
        VALUES (p_item_id, 'ajuste', p_cantidad)
        RETURNING id INTO v_lote_id;

        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            destino_ubicacion_id, cantidad, precio_unitario,
            documento_tipo, documento_id, observacion
        ) VALUES (
            v_doc_movimiento_id, p_item_id, v_lote_id, v_tipo_id,
            p_ubicacion_id, p_cantidad, v_precio,
            'ajuste', v_lote_id, p_observacion
        );

    ELSE
        -- AJUSTE_NEG: FIFO debit from existing lotes
        -- KNOWN LIMITATION (not a problem today, single-warehouse): calcular_fifo
        -- resolves lotes by item_id across ALL ubicaciones, so p_ubicacion_id is
        -- ignored on the debit side — a negative adjustment scoped to one ubicación
        -- can deplete a lote in another. Scope FIFO to p_ubicacion_id if/when stock
        -- is split across locations.
        SELECT id INTO v_tipo_id FROM inventario.item_movimiento_tipo WHERE codigo = 'AJUSTE_NEG';

        v_fifo_result := mes.calcular_fifo(
            jsonb_build_array(jsonb_build_object('item_id', p_item_id, 'cantidad', ABS(p_cantidad)))
        );

        IF v_fifo_result IS NULL OR jsonb_array_length(v_fifo_result) = 0 THEN
            RAISE EXCEPTION 'Stock insuficiente para registrar ajuste negativo de % en item #%.',
                ABS(p_cantidad), p_item_id;
        END IF;

        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, cantidad, precio_unitario,
            documento_tipo, documento_id, observacion
        )
        SELECT
            v_doc_movimiento_id,
            (f->>'item_id')::INT,
            (f->>'lote_id')::INT,
            v_tipo_id,
            (f->>'ubicacion_id')::INT,
            (f->>'cantidad')::NUMERIC,
            v_precio,
            'ajuste', v_doc_movimiento_id, p_observacion
        FROM jsonb_array_elements(v_fifo_result) f;
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_ajuste', v_usr_id, jsonb_build_object(
        'item_id', p_item_id, 'ubicacion_id', p_ubicacion_id,
        'cantidad', p_cantidad, 'observacion', p_observacion
    ));

    RETURN format('Ajuste de %s registrado para item #%s (doc #%s).',
                  p_cantidad, p_item_id, v_doc_movimiento_id);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_ajuste - User: %, item: %, Error: %, Detail: %',
              v_usr_id, p_item_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION inventario.registrar_ajuste(p_item_id integer, p_ubicacion_id integer, p_cantidad numeric, p_observacion text) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.registrar_ajuste_a_total(integer, integer, numeric, text)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.registrar_ajuste_a_total(p_item_id integer, p_ubicacion_id integer, p_cantidad_objetivo numeric, p_observacion text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes'
    AS $$
DECLARE
    v_saldo_actual NUMERIC(15,7);
    v_delta        NUMERIC;
    v_obs          TEXT;
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_cantidad_objetivo IS NULL OR p_cantidad_objetivo < 0 THEN
        RAISE EXCEPTION 'La cantidad objetivo no puede ser nula ni negativa.';
    END IF;

    IF p_observacion IS NULL OR trim(p_observacion) = '' THEN
        RAISE EXCEPTION 'La observación es obligatoria para registrar un ajuste.';
    END IF;

    -- Lock the saldo row so no other movement can change it between read and post.
    SELECT cantidad_actual
    INTO v_saldo_actual
    FROM inventario.item_saldo
    WHERE item_id = p_item_id AND ubicacion_id = p_ubicacion_id
    FOR UPDATE;

    v_saldo_actual := COALESCE(v_saldo_actual, 0);
    v_delta        := p_cantidad_objetivo - v_saldo_actual;

    IF v_delta = 0 THEN
        RETURN format('Sin cambios: el saldo del item #%s ya es %s.',
                      p_item_id, p_cantidad_objetivo);
    END IF;

    -- Preserve intent in the audit trail: target, saldo-at-the-moment, delta.
    v_obs := format('%s [objetivo=%s, saldo=%s, delta=%s]',
                    p_observacion, p_cantidad_objetivo, v_saldo_actual, v_delta);

    -- Delegate to the delta-based core (shared posting / FIFO / valuation logic).
    RETURN inventario.registrar_ajuste(p_item_id, p_ubicacion_id, v_delta, v_obs);
END;
$$;


ALTER FUNCTION inventario.registrar_ajuste_a_total(p_item_id integer, p_ubicacion_id integer, p_cantidad_objetivo numeric, p_observacion text) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.registrar_pesaje_entrega(bigint, numeric, numeric)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.registrar_pesaje_entrega(p_entrega_id bigint, p_peso_regular numeric, p_peso_rib numeric) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int := get_user_id();
    v_pesaje_pos_id     smallint;
    v_pesaje_neg_id     smallint;
    v_doc_movimiento_id bigint;
    v_cantidad_regular     int;
    v_cantidad_rib         int;
    v_peso_por_regular  numeric;
    v_peso_por_rib      numeric;
    v_updated           int := 0;
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM doc.entrega WHERE id = p_entrega_id) THEN
        RAISE EXCEPTION 'Guía #% no encontrada.', p_entrega_id;
    END IF;

    -- Guard: no roll from this entrega may already be in production
    IF EXISTS (
        SELECT 1
        FROM inventario.lote_rollo_detalle lrd
        JOIN inventario.item_movimientos im  ON im.lote_id = lrd.lote_id
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE lrd.entrega_id = p_entrega_id
          AND imt.codigo = 'PROD_CONSUMO'
    ) THEN
        RAISE EXCEPTION
            'No se puede modificar pesos de la guía #%: uno o más rollos ya tienen movimientos de producción.',
            p_entrega_id;
    END IF;

    -- Count rolls by type that arrived on this entrega
    SELECT
        COUNT(*) FILTER (WHERE ird.flg_rib = false),
        COUNT(*) FILTER (WHERE ird.flg_rib = true)
    INTO v_cantidad_regular, v_cantidad_rib
    FROM inventario.lote_rollo_detalle lrd
    JOIN inventario.lote l      ON l.id = lrd.lote_id AND l.fyh_elm IS NULL
    JOIN item_rollo_detalle ird ON ird.item_id = l.item_id
    WHERE lrd.entrega_id = p_entrega_id;

    IF v_cantidad_regular = 0 AND v_cantidad_rib = 0 THEN
        RAISE EXCEPTION 'La guía #% no tiene rollos asociados.', p_entrega_id;
    END IF;
    IF p_peso_regular IS NOT NULL AND v_cantidad_regular = 0 THEN
        RAISE EXCEPTION 'Se proporcionó peso_regular pero la guía #% no tiene rollos regulares.', p_entrega_id;
    END IF;
    IF p_peso_rib IS NOT NULL AND v_cantidad_rib = 0 THEN
        RAISE EXCEPTION 'Se proporcionó peso_rib pero la guía #% no tiene rollos rib.', p_entrega_id;
    END IF;

    v_peso_por_regular := CASE WHEN v_cantidad_regular > 0 AND p_peso_regular IS NOT NULL
                               THEN ROUND(p_peso_regular / v_cantidad_regular, 4) END;
    v_peso_por_rib     := CASE WHEN v_cantidad_rib > 0 AND p_peso_rib IS NOT NULL
                               THEN ROUND(p_peso_rib / v_cantidad_rib, 4) END;

    SELECT id INTO v_pesaje_pos_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_POS';
    SELECT id INTO v_pesaje_neg_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_NEG';
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

    WITH rolls AS (
        SELECT
            l.id        AS lote_id,
            l.item_id,
            l.cantidad  AS peso_anterior,
            sa.ubicacion_id,
            ird.flg_rib,
            CASE WHEN ird.flg_rib THEN v_peso_por_rib ELSE v_peso_por_regular END AS peso_nuevo
        FROM inventario.lote_rollo_detalle lrd
        JOIN inventario.lote l             ON l.id = lrd.lote_id AND l.fyh_elm IS NULL
        JOIN item_rollo_detalle ird        ON ird.item_id = l.item_id
        JOIN inventario.vw_stock_lotes_ubicacion sa ON sa.lote_id = l.id
        WHERE lrd.entrega_id = p_entrega_id
          AND CASE WHEN ird.flg_rib THEN v_peso_por_rib     IS NOT NULL
                   ELSE                  v_peso_por_regular IS NOT NULL END
    ),
    pesajes AS (
        INSERT INTO inventario.pesaje (lote_id, tipo, peso_real, usr_cre)
        SELECT r.lote_id, 'INGRESO', r.peso_nuevo, v_usr_id
        FROM rolls r
        ON CONFLICT (lote_id) DO UPDATE
            SET peso_real = EXCLUDED.peso_real,
                tipo      = EXCLUDED.tipo
        RETURNING lote_id
    ),
    movimientos AS (
        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, destino_ubicacion_id,
            cantidad, documento_tipo, documento_id
        )
        SELECT
            v_doc_movimiento_id,
            r.item_id, r.lote_id,
            CASE WHEN r.peso_nuevo > r.peso_anterior THEN v_pesaje_pos_id
                 ELSE v_pesaje_neg_id END,
            CASE WHEN r.peso_nuevo < r.peso_anterior THEN r.ubicacion_id ELSE NULL END,
            CASE WHEN r.peso_nuevo > r.peso_anterior THEN r.ubicacion_id ELSE NULL END,
            ABS(r.peso_nuevo - r.peso_anterior),
            'entrega', p_entrega_id
        FROM rolls r
        JOIN pesajes p ON p.lote_id = r.lote_id
        WHERE r.peso_nuevo <> r.peso_anterior
    )
    UPDATE inventario.lote l
    SET cantidad = r.peso_nuevo
    FROM rolls r
    WHERE l.id = r.lote_id;

    GET DIAGNOSTICS v_updated = ROW_COUNT;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_pesaje_entrega', v_usr_id, jsonb_build_object(
        'entrega_id', p_entrega_id,
        'peso_regular', p_peso_regular,
        'peso_rib', p_peso_rib
    ));

    RETURN format(
        'Pesaje registrado para guía #%s: %s rollos actualizados (%s regulares × %s kg, %s rib × %s kg).',
        p_entrega_id, v_updated,
        COALESCE(v_cantidad_regular, 0), COALESCE(v_peso_por_regular::text, 'sin cambio'),
        COALESCE(v_cantidad_rib, 0),     COALESCE(v_peso_por_rib::text,     'sin cambio')
    );

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_pesaje_entrega - User: %, entrega: %, Error: %, Detail: %',
              v_usr_id, p_entrega_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION inventario.registrar_pesaje_entrega(p_entrega_id bigint, p_peso_regular numeric, p_peso_rib numeric) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.registrar_pesaje_entrega_individual(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.registrar_pesaje_entrega_individual(p_entrega_id bigint, p_pesos jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int := get_user_id();
    v_pesaje_pos_id     smallint;
    v_pesaje_neg_id     smallint;
    v_doc_movimiento_id bigint;
    v_updated           int := 0;
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM doc.entrega WHERE id = p_entrega_id) THEN
        RAISE EXCEPTION 'Guía #% no encontrada.', p_entrega_id;
    END IF;

    -- Guard: all submitted lotes must belong to this entrega
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(p_pesos) e
        LEFT JOIN inventario.lote_rollo_detalle lrd
               ON lrd.lote_id = (e->>'lote_id')::INT
              AND lrd.entrega_id = p_entrega_id
        WHERE lrd.lote_id IS NULL
    ) THEN
        RAISE EXCEPTION
            'Uno o más lotes no pertenecen a la guía #%.', p_entrega_id;
    END IF;

    -- Guard: no roll may already be in production
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(p_pesos) e
        JOIN inventario.item_movimientos im  ON im.lote_id = (e->>'lote_id')::INT
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE imt.codigo = 'PROD_CONSUMO'
    ) THEN
        RAISE EXCEPTION
            'No se puede modificar pesos: uno o más rollos ya tienen movimientos de producción.';
    END IF;

    SELECT id INTO v_pesaje_pos_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_POS';
    SELECT id INTO v_pesaje_neg_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_NEG';
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

    WITH input AS (
        SELECT
            (e->>'lote_id')::INT     AS lote_id,
            (e->>'peso_kg')::NUMERIC AS peso_nuevo
        FROM jsonb_array_elements(p_pesos) e
    ),
    rolls AS (
        SELECT
            i.lote_id,
            l.item_id,
            l.cantidad              AS peso_anterior,
            sa.ubicacion_id,
            i.peso_nuevo
        FROM input i
        JOIN inventario.lote l             ON l.id = i.lote_id AND l.fyh_elm IS NULL
        JOIN inventario.vw_stock_lotes_ubicacion sa ON sa.lote_id = l.id
    ),
    pesajes AS (
        INSERT INTO inventario.pesaje (lote_id, tipo, peso_real, usr_cre)
        SELECT r.lote_id, 'INGRESO', r.peso_nuevo, v_usr_id
        FROM rolls r
        ON CONFLICT (lote_id) DO UPDATE
            SET peso_real = EXCLUDED.peso_real,
                tipo      = EXCLUDED.tipo
        RETURNING lote_id
    ),
    movimientos AS (
        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, destino_ubicacion_id,
            cantidad, documento_tipo, documento_id
        )
        SELECT
            v_doc_movimiento_id,
            r.item_id, r.lote_id,
            CASE WHEN r.peso_nuevo > r.peso_anterior THEN v_pesaje_pos_id
                 ELSE v_pesaje_neg_id END,
            CASE WHEN r.peso_nuevo < r.peso_anterior THEN r.ubicacion_id ELSE NULL END,
            CASE WHEN r.peso_nuevo > r.peso_anterior THEN r.ubicacion_id ELSE NULL END,
            ABS(r.peso_nuevo - r.peso_anterior),
            'entrega', p_entrega_id
        FROM rolls r
        JOIN pesajes p ON p.lote_id = r.lote_id
        WHERE r.peso_nuevo <> r.peso_anterior
    )
    UPDATE inventario.lote l
    SET cantidad = r.peso_nuevo
    FROM rolls r
    WHERE l.id = r.lote_id;

    GET DIAGNOSTICS v_updated = ROW_COUNT;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_pesaje_entrega_individual', v_usr_id, jsonb_build_object(
        'entrega_id', p_entrega_id,
        'pesos', p_pesos
    ));

    RETURN format('Pesaje individual registrado para guía #%s: %s rollos actualizados.', p_entrega_id, v_updated);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_pesaje_entrega_individual - User: %, entrega: %, Error: %, Detail: %',
              v_usr_id, p_entrega_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION inventario.registrar_pesaje_entrega_individual(p_entrega_id bigint, p_pesos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.registrar_pesaje_grupo(bigint, bigint, integer, boolean, numeric)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.registrar_pesaje_grupo(p_partida_id bigint, p_entrega_id bigint, p_item_id integer, p_flg_rib boolean, p_peso_total_kg numeric) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int := get_user_id();
    v_pesaje_pos_id     smallint;
    v_pesaje_neg_id     smallint;
    v_doc_movimiento_id bigint;
    v_count             int;
    v_peso_cada         numeric;
    v_updated           int := 0;
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_peso_total_kg IS NULL OR p_peso_total_kg <= 0 THEN
        RAISE EXCEPTION 'p_peso_total_kg debe ser mayor que cero.';
    END IF;

    -- Guard: no roll in this group may already be consumed in production
    IF EXISTS (
        SELECT 1
        FROM mes.partida_componente          pc
        JOIN inventario.lote                 l   ON l.id  = pc.lote_id AND l.fyh_elm IS NULL
        JOIN item_rollo_detalle              ird ON ird.item_id = l.item_id
                                                AND ird.flg_rib = p_flg_rib
        LEFT JOIN inventario.lote_rollo_detalle lrd ON lrd.lote_id = l.id
        JOIN inventario.item_movimientos     im  ON im.lote_id = l.id
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
                                                AND imt.codigo = 'PROD_CONSUMO'
        WHERE pc.partida_id = p_partida_id
          AND l.item_id     = p_item_id
          AND (
              (p_entrega_id IS NULL AND lrd.entrega_id IS NULL)
              OR lrd.entrega_id = p_entrega_id
          )
    ) THEN
        RAISE EXCEPTION
            'No se puede pesar el grupo: uno o más rollos ya tienen movimientos de producción (partida #%, item #%, guía %).',
            p_partida_id, p_item_id, COALESCE(p_entrega_id::text, 'sin guía');
    END IF;

    -- Count rolls in this group
    SELECT COUNT(DISTINCT l.id)
    INTO v_count
    FROM mes.partida_componente             pc
    JOIN inventario.lote                    l   ON l.id  = pc.lote_id AND l.fyh_elm IS NULL
    JOIN item_rollo_detalle                 ird ON ird.item_id = l.item_id
                                             AND ird.flg_rib = p_flg_rib
    LEFT JOIN inventario.lote_rollo_detalle lrd ON lrd.lote_id = l.id
    WHERE pc.partida_id = p_partida_id
      AND l.item_id     = p_item_id
      AND (
          (p_entrega_id IS NULL AND lrd.entrega_id IS NULL)
          OR lrd.entrega_id = p_entrega_id
      );

    IF v_count = 0 THEN
        RAISE EXCEPTION
            'No se encontraron rollos para el grupo (partida #%, item #%, guía %, flg_rib %).',
            p_partida_id, p_item_id, COALESCE(p_entrega_id::text, 'sin guía'), p_flg_rib;
    END IF;

    v_peso_cada := ROUND(p_peso_total_kg / v_count, 4);

    SELECT id INTO v_pesaje_pos_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_POS';
    SELECT id INTO v_pesaje_neg_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_NEG';
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

    -- Upsert pesaje + post weight-delta movement + update lote.cantidad
    WITH rolls AS (
        SELECT DISTINCT ON (l.id)
            l.id       AS lote_id,
            l.item_id,
            l.cantidad AS peso_anterior,
            sa.ubicacion_id,
            v_peso_cada AS peso_nuevo
        FROM mes.partida_componente             pc
        JOIN inventario.lote                    l   ON l.id  = pc.lote_id AND l.fyh_elm IS NULL
        JOIN item_rollo_detalle                 ird ON ird.item_id = l.item_id
                                                 AND ird.flg_rib = p_flg_rib
        LEFT JOIN inventario.lote_rollo_detalle lrd ON lrd.lote_id = l.id
        JOIN inventario.vw_stock_lotes_ubicacion sa  ON sa.lote_id = l.id
        WHERE pc.partida_id = p_partida_id
          AND l.item_id     = p_item_id
          AND (
              (p_entrega_id IS NULL AND lrd.entrega_id IS NULL)
              OR lrd.entrega_id = p_entrega_id
          )
    ),
    pesajes AS (
        INSERT INTO inventario.pesaje (lote_id, tipo, peso_real, usr_cre)
        SELECT r.lote_id, 'INGRESO', r.peso_nuevo, v_usr_id
        FROM rolls r
        ON CONFLICT (lote_id) DO UPDATE
            SET peso_real = EXCLUDED.peso_real,
                tipo      = EXCLUDED.tipo
        RETURNING lote_id
    ),
    movimientos AS (
        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, destino_ubicacion_id,
            cantidad, documento_tipo, documento_id
        )
        SELECT
            v_doc_movimiento_id,
            r.item_id, r.lote_id,
            CASE WHEN r.peso_nuevo > r.peso_anterior THEN v_pesaje_pos_id
                 ELSE v_pesaje_neg_id END,
            CASE WHEN r.peso_nuevo < r.peso_anterior THEN r.ubicacion_id ELSE NULL END,
            CASE WHEN r.peso_nuevo > r.peso_anterior THEN r.ubicacion_id ELSE NULL END,
            ABS(r.peso_nuevo - r.peso_anterior),
            'partida', p_partida_id
        FROM rolls r
        JOIN pesajes p ON p.lote_id = r.lote_id
        WHERE r.peso_nuevo <> r.peso_anterior
    )
    UPDATE inventario.lote l
    SET cantidad = r.peso_nuevo
    FROM rolls r
    WHERE l.id = r.lote_id;

    GET DIAGNOSTICS v_updated = ROW_COUNT;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_pesaje_grupo', v_usr_id, jsonb_build_object(
        'partida_id',       p_partida_id,
        'entrega_id', p_entrega_id,
        'item_id',          p_item_id,
        'flg_rib',          p_flg_rib,
        'peso_total_kg',    p_peso_total_kg
    ));

    RETURN format(
        'Pesaje registrado: partida #%s, item #%s, guía %s — %s rollos × %s kg (total %s kg).',
        p_partida_id, p_item_id,
        COALESCE(p_entrega_id::text, 'sin guía'),
        v_count, v_peso_cada, p_peso_total_kg
    );

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error en registrar_pesaje_grupo - User: %, partida: %, item: %, Error: %, Detail: %',
              v_usr_id, p_partida_id, p_item_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION inventario.registrar_pesaje_grupo(p_partida_id bigint, p_entrega_id bigint, p_item_id integer, p_flg_rib boolean, p_peso_total_kg numeric) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.registrar_pesaje_guia(bigint, numeric, numeric)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.registrar_pesaje_guia(p_guia_id bigint, p_peso_regular numeric, p_peso_rib numeric) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int := get_user_id();
    v_pesaje_pos_id     smallint;
    v_pesaje_neg_id     smallint;
    v_doc_movimiento_id bigint;
    v_cantidad_regular     int;
    v_cantidad_rib         int;
    v_peso_por_regular  numeric;
    v_peso_por_rib      numeric;
    v_updated           int := 0;
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM doc.guia_remision WHERE id = p_guia_id) THEN
        RAISE EXCEPTION 'Guía #% no encontrada.', p_guia_id;
    END IF;

    -- Guard: no roll from this guia may already be in production
    IF EXISTS (
        SELECT 1
        FROM inventario.lote_rollo_detalle lrd
        JOIN inventario.item_movimientos im  ON im.lote_id = lrd.lote_id
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE lrd.guia_remision_id = p_guia_id
          AND imt.codigo = 'PROD_CONSUMO'
    ) THEN
        RAISE EXCEPTION
            'No se puede modificar pesos de la guía #%: uno o más rollos ya tienen movimientos de producción.',
            p_guia_id;
    END IF;

    -- Count rolls by type that arrived on this guia
    SELECT
        COUNT(*) FILTER (WHERE ird.flg_rib = false),
        COUNT(*) FILTER (WHERE ird.flg_rib = true)
    INTO v_cantidad_regular, v_cantidad_rib
    FROM inventario.lote_rollo_detalle lrd
    JOIN inventario.lote l      ON l.id = lrd.lote_id AND l.fyh_elm IS NULL
    JOIN item_rollo_detalle ird ON ird.item_id = l.item_id
    WHERE lrd.guia_remision_id = p_guia_id;

    IF v_cantidad_regular = 0 AND v_cantidad_rib = 0 THEN
        RAISE EXCEPTION 'La guía #% no tiene rollos asociados.', p_guia_id;
    END IF;
    IF p_peso_regular IS NOT NULL AND v_cantidad_regular = 0 THEN
        RAISE EXCEPTION 'Se proporcionó peso_regular pero la guía #% no tiene rollos regulares.', p_guia_id;
    END IF;
    IF p_peso_rib IS NOT NULL AND v_cantidad_rib = 0 THEN
        RAISE EXCEPTION 'Se proporcionó peso_rib pero la guía #% no tiene rollos rib.', p_guia_id;
    END IF;

    v_peso_por_regular := CASE WHEN v_cantidad_regular > 0 AND p_peso_regular IS NOT NULL
                               THEN ROUND(p_peso_regular / v_cantidad_regular, 4) END;
    v_peso_por_rib     := CASE WHEN v_cantidad_rib > 0 AND p_peso_rib IS NOT NULL
                               THEN ROUND(p_peso_rib / v_cantidad_rib, 4) END;

    SELECT id INTO v_pesaje_pos_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_POS';
    SELECT id INTO v_pesaje_neg_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_NEG';
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

    WITH rolls AS (
        SELECT
            l.id        AS lote_id,
            l.item_id,
            l.cantidad  AS peso_anterior,
            sa.ubicacion_id,
            ird.flg_rib,
            CASE WHEN ird.flg_rib THEN v_peso_por_rib ELSE v_peso_por_regular END AS peso_nuevo
        FROM inventario.lote_rollo_detalle lrd
        JOIN inventario.lote l             ON l.id = lrd.lote_id AND l.fyh_elm IS NULL
        JOIN item_rollo_detalle ird        ON ird.item_id = l.item_id
        JOIN inventario.vw_stock_lotes_ubicacion sa ON sa.lote_id = l.id
        WHERE lrd.guia_remision_id = p_guia_id
          AND CASE WHEN ird.flg_rib THEN v_peso_por_rib     IS NOT NULL
                   ELSE                  v_peso_por_regular IS NOT NULL END
    ),
    pesajes AS (
        INSERT INTO inventario.pesaje (lote_id, tipo, peso_real, usr_cre)
        SELECT r.lote_id, 'INGRESO', r.peso_nuevo, v_usr_id
        FROM rolls r
        ON CONFLICT (lote_id) DO UPDATE
            SET peso_real = EXCLUDED.peso_real,
                tipo      = EXCLUDED.tipo
        RETURNING lote_id
    ),
    movimientos AS (
        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, destino_ubicacion_id,
            cantidad, documento_tipo, documento_id
        )
        SELECT
            v_doc_movimiento_id,
            r.item_id, r.lote_id,
            CASE WHEN r.peso_nuevo > r.peso_anterior THEN v_pesaje_pos_id
                 ELSE v_pesaje_neg_id END,
            CASE WHEN r.peso_nuevo < r.peso_anterior THEN r.ubicacion_id ELSE NULL END,
            CASE WHEN r.peso_nuevo > r.peso_anterior THEN r.ubicacion_id ELSE NULL END,
            ABS(r.peso_nuevo - r.peso_anterior),
            'guia_remision', p_guia_id
        FROM rolls r
        JOIN pesajes p ON p.lote_id = r.lote_id
        WHERE r.peso_nuevo <> r.peso_anterior
    )
    UPDATE inventario.lote l
    SET cantidad = r.peso_nuevo
    FROM rolls r
    WHERE l.id = r.lote_id;

    GET DIAGNOSTICS v_updated = ROW_COUNT;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_pesaje_guia', v_usr_id, jsonb_build_object(
        'guia_id', p_guia_id,
        'peso_regular', p_peso_regular,
        'peso_rib', p_peso_rib
    ));

    RETURN format(
        'Pesaje registrado para guía #%s: %s rollos actualizados (%s regulares × %s kg, %s rib × %s kg).',
        p_guia_id, v_updated,
        COALESCE(v_cantidad_regular, 0), COALESCE(v_peso_por_regular::text, 'sin cambio'),
        COALESCE(v_cantidad_rib, 0),     COALESCE(v_peso_por_rib::text,     'sin cambio')
    );

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_pesaje_guia - User: %, guia: %, Error: %, Detail: %',
              v_usr_id, p_guia_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION inventario.registrar_pesaje_guia(p_guia_id bigint, p_peso_regular numeric, p_peso_rib numeric) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.registrar_pesaje_guia_individual(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.registrar_pesaje_guia_individual(p_guia_id bigint, p_pesos jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int := get_user_id();
    v_pesaje_pos_id     smallint;
    v_pesaje_neg_id     smallint;
    v_doc_movimiento_id bigint;
    v_updated           int := 0;
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM doc.guia_remision WHERE id = p_guia_id) THEN
        RAISE EXCEPTION 'Guía #% no encontrada.', p_guia_id;
    END IF;

    -- Guard: all submitted lotes must belong to this guia
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(p_pesos) e
        LEFT JOIN inventario.lote_rollo_detalle lrd
               ON lrd.lote_id = (e->>'lote_id')::INT
              AND lrd.guia_remision_id = p_guia_id
        WHERE lrd.lote_id IS NULL
    ) THEN
        RAISE EXCEPTION
            'Uno o más lotes no pertenecen a la guía #%.', p_guia_id;
    END IF;

    -- Guard: no roll may already be in production
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(p_pesos) e
        JOIN inventario.item_movimientos im  ON im.lote_id = (e->>'lote_id')::INT
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE imt.codigo = 'PROD_CONSUMO'
    ) THEN
        RAISE EXCEPTION
            'No se puede modificar pesos: uno o más rollos ya tienen movimientos de producción.';
    END IF;

    SELECT id INTO v_pesaje_pos_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_POS';
    SELECT id INTO v_pesaje_neg_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_NEG';
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

    WITH input AS (
        SELECT
            (e->>'lote_id')::INT     AS lote_id,
            (e->>'peso_kg')::NUMERIC AS peso_nuevo
        FROM jsonb_array_elements(p_pesos) e
    ),
    rolls AS (
        SELECT
            i.lote_id,
            l.item_id,
            l.cantidad              AS peso_anterior,
            sa.ubicacion_id,
            i.peso_nuevo
        FROM input i
        JOIN inventario.lote l             ON l.id = i.lote_id AND l.fyh_elm IS NULL
        JOIN inventario.vw_stock_lotes_ubicacion sa ON sa.lote_id = l.id
    ),
    pesajes AS (
        INSERT INTO inventario.pesaje (lote_id, tipo, peso_real, usr_cre)
        SELECT r.lote_id, 'INGRESO', r.peso_nuevo, v_usr_id
        FROM rolls r
        ON CONFLICT (lote_id) DO UPDATE
            SET peso_real = EXCLUDED.peso_real,
                tipo      = EXCLUDED.tipo
        RETURNING lote_id
    ),
    movimientos AS (
        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, destino_ubicacion_id,
            cantidad, documento_tipo, documento_id
        )
        SELECT
            v_doc_movimiento_id,
            r.item_id, r.lote_id,
            CASE WHEN r.peso_nuevo > r.peso_anterior THEN v_pesaje_pos_id
                 ELSE v_pesaje_neg_id END,
            CASE WHEN r.peso_nuevo < r.peso_anterior THEN r.ubicacion_id ELSE NULL END,
            CASE WHEN r.peso_nuevo > r.peso_anterior THEN r.ubicacion_id ELSE NULL END,
            ABS(r.peso_nuevo - r.peso_anterior),
            'guia_remision', p_guia_id
        FROM rolls r
        JOIN pesajes p ON p.lote_id = r.lote_id
        WHERE r.peso_nuevo <> r.peso_anterior
    )
    UPDATE inventario.lote l
    SET cantidad = r.peso_nuevo
    FROM rolls r
    WHERE l.id = r.lote_id;

    GET DIAGNOSTICS v_updated = ROW_COUNT;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_pesaje_guia_individual', v_usr_id, jsonb_build_object(
        'guia_id', p_guia_id,
        'pesos', p_pesos
    ));

    RETURN format('Pesaje individual registrado para guía #%s: %s rollos actualizados.', p_guia_id, v_updated);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_pesaje_guia_individual - User: %, guia: %, Error: %, Detail: %',
              v_usr_id, p_guia_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION inventario.registrar_pesaje_guia_individual(p_guia_id bigint, p_pesos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.registrar_pesaje_produccion(bigint, numeric, numeric)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.registrar_pesaje_produccion(p_partida_id bigint, p_peso_regular numeric, p_peso_rib numeric) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int := get_user_id();
    v_pesaje_pos_id     smallint;
    v_pesaje_neg_id     smallint;
    v_doc_movimiento_id bigint;
    v_cantidad_regular     int;
    v_cantidad_rib         int;
    v_peso_por_regular  numeric;
    v_peso_por_rib      numeric;
    v_updated           int := 0;
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM mes.partida WHERE id = p_partida_id) THEN
        RAISE EXCEPTION 'partida #% no encontrado.', p_partida_id;
    END IF;

    -- Guard: no roll assigned to this partida may already be in production
    IF EXISTS (
        SELECT 1
        FROM mes.partida_componente opi
        JOIN inventario.item_movimientos im  ON im.lote_id = opi.lote_id
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE opi.partida_id = p_partida_id
          AND imt.codigo = 'PROD_CONSUMO'
    ) THEN
        RAISE EXCEPTION
            'No se puede modificar pesos del partida #%: uno o más rollos ya tienen movimientos de producción.',
            p_partida_id;
    END IF;

    -- Count rolls by type assigned to this partida via partida_componente
    SELECT
        COUNT(*) FILTER (WHERE ird.flg_rib = false),
        COUNT(*) FILTER (WHERE ird.flg_rib = true)
    INTO v_cantidad_regular, v_cantidad_rib
    FROM mes.partida_componente opi
    JOIN inventario.lote l             ON l.id = opi.lote_id AND l.fyh_elm IS NULL
    JOIN item_rollo_detalle ird        ON ird.item_id = l.item_id
    WHERE opi.partida_id = p_partida_id;

    IF v_cantidad_regular = 0 AND v_cantidad_rib = 0 THEN
        RAISE EXCEPTION 'El partida #% no tiene rollos asignados.', p_partida_id;
    END IF;
    IF p_peso_regular IS NOT NULL AND v_cantidad_regular = 0 THEN
        RAISE EXCEPTION 'Se proporcionó peso_regular pero el partida #% no tiene rollos regulares asignados.', p_partida_id;
    END IF;
    IF p_peso_rib IS NOT NULL AND v_cantidad_rib = 0 THEN
        RAISE EXCEPTION 'Se proporcionó peso_rib pero el partida #% no tiene rollos rib asignados.', p_partida_id;
    END IF;

    v_peso_por_regular := CASE WHEN v_cantidad_regular > 0 AND p_peso_regular IS NOT NULL
                               THEN ROUND(p_peso_regular / v_cantidad_regular, 4) END;
    v_peso_por_rib     := CASE WHEN v_cantidad_rib > 0 AND p_peso_rib IS NOT NULL
                               THEN ROUND(p_peso_rib / v_cantidad_rib, 4) END;

    SELECT id INTO v_pesaje_pos_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_POS';
    SELECT id INTO v_pesaje_neg_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_NEG';
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

    -- Upsert pesaje + post weight-delta movement + update lote.cantidad
    WITH rolls AS (
        SELECT DISTINCT ON (l.id)
            l.id        AS lote_id,
            l.item_id,
            l.cantidad  AS peso_anterior,
            sa.ubicacion_id,
            ird.flg_rib,
            CASE WHEN ird.flg_rib THEN v_peso_por_rib ELSE v_peso_por_regular END AS peso_nuevo
        FROM mes.partida_componente opi
        JOIN inventario.lote l             ON l.id = opi.lote_id AND l.fyh_elm IS NULL
        JOIN item_rollo_detalle ird        ON ird.item_id = l.item_id
        JOIN inventario.vw_stock_lotes_ubicacion sa ON sa.lote_id = l.id
        WHERE opi.partida_id = p_partida_id
          AND CASE WHEN ird.flg_rib THEN v_peso_por_rib     IS NOT NULL
                   ELSE                  v_peso_por_regular IS NOT NULL END
    ),
    pesajes AS (
        INSERT INTO inventario.pesaje (lote_id, tipo, peso_real, usr_cre)
        SELECT r.lote_id, 'INGRESO', r.peso_nuevo, v_usr_id
        FROM rolls r
        ON CONFLICT (lote_id) DO UPDATE
            SET peso_real = EXCLUDED.peso_real,
                tipo      = EXCLUDED.tipo
        RETURNING lote_id
    ),
    movimientos AS (
        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, destino_ubicacion_id,
            cantidad, documento_tipo, documento_id
        )
        SELECT
            v_doc_movimiento_id,
            r.item_id, r.lote_id,
            CASE WHEN r.peso_nuevo > r.peso_anterior THEN v_pesaje_pos_id
                 ELSE v_pesaje_neg_id END,
            CASE WHEN r.peso_nuevo < r.peso_anterior THEN r.ubicacion_id ELSE NULL END,
            CASE WHEN r.peso_nuevo > r.peso_anterior THEN r.ubicacion_id ELSE NULL END,
            ABS(r.peso_nuevo - r.peso_anterior),
            'partida', p_partida_id
        FROM rolls r
        JOIN pesajes p ON p.lote_id = r.lote_id
        WHERE r.peso_nuevo <> r.peso_anterior
    )
    UPDATE inventario.lote l
    SET cantidad = r.peso_nuevo
    FROM rolls r
    WHERE l.id = r.lote_id;

    GET DIAGNOSTICS v_updated = ROW_COUNT;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_pesaje_produccion', v_usr_id, jsonb_build_object(
        'partida_id', p_partida_id,
        'peso_regular', p_peso_regular,
        'peso_rib', p_peso_rib
    ));

    RETURN format(
        'Pesaje registrado para partida #%s: %s rollos actualizados (%s regulares × %s kg, %s rib × %s kg).',
        p_partida_id, v_updated,
        COALESCE(v_cantidad_regular, 0), COALESCE(v_peso_por_regular::text, 'sin cambio'),
        COALESCE(v_cantidad_rib, 0),     COALESCE(v_peso_por_rib::text,     'sin cambio')
    );

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error en registrar_pesaje_produccion - User: %, partida: %, Error: %, Detail: %',
              v_usr_id, p_partida_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION inventario.registrar_pesaje_produccion(p_partida_id bigint, p_peso_regular numeric, p_peso_rib numeric) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.revertir_cuadre_preparado(bigint, text)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.revertir_cuadre_preparado(p_cuadre_id bigint, p_motivo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id int := get_user_id();
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_motivo IS NULL OR trim(p_motivo) = '' THEN
        RAISE EXCEPTION 'Se requiere motivo para revertir el cuadre.';
    END IF;

    UPDATE inventario.cuadre
    SET estado  = 'borrador',
        usr_mod = v_usr_id,
        fyh_mod = now()
    WHERE id = p_cuadre_id AND estado = 'preparado';

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Cuadre % no existe o no está en estado preparado.', p_cuadre_id;
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('revertir_cuadre_preparado', v_usr_id,
            jsonb_build_object('cuadre_id', p_cuadre_id, 'motivo', p_motivo));

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in revertir_cuadre_preparado - User: %, Cuadre: %, Error: %, Detail: %',
              v_usr_id, p_cuadre_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION inventario.revertir_cuadre_preparado(p_cuadre_id bigint, p_motivo text) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.trfn_generar_secuencia_lote()
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.trfn_generar_secuencia_lote() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ano INT;
BEGIN
    v_ano := date_part('year', COALESCE(NEW.fyh_cre, NOW()));
    INSERT INTO inventario.lote_secuencia_anual (ano, ultimo_valor)
    VALUES (v_ano, 1)
    ON CONFLICT (ano)
    DO UPDATE SET ultimo_valor = inventario.lote_secuencia_anual.ultimo_valor + 1
    RETURNING ultimo_valor INTO NEW.secuencia;
    RETURN NEW;
END;
$$;


ALTER FUNCTION inventario.trfn_generar_secuencia_lote() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: inventario.update_cuadre_detalles(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION inventario.update_cuadre_detalles(p_json jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'inventario', 'mes'
    AS $$
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    UPDATE inventario.cuadre_detalle d
    SET cantidad_contada = u.cantidad_contada,
        fyh_mod          = now(),
        usr_mod          = get_user_id()
    FROM jsonb_to_recordset(p_json) AS u(id bigint, cantidad_contada numeric)
    WHERE d.id = u.id;
END;
$$;


ALTER FUNCTION inventario.update_cuadre_detalles(p_json jsonb) OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

-- ---------------------------------------------------------------------
-- FUNCTION: mes._assert_reproceso_reversible(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes._assert_reproceso_reversible(p_reproceso_id bigint) RETURNS mes.partida
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_child mes.partida%ROWTYPE;
BEGIN
    SELECT * INTO v_child
    FROM mes.partida
    WHERE id = p_reproceso_id AND fyh_elm IS NULL
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Reproceso % no encontrado o ya anulado.', p_reproceso_id
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    IF v_child.partida_origen_id IS NULL THEN
        RAISE EXCEPTION 'Partida % no es un reproceso (partida_origen_id IS NULL).', p_reproceso_id
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    -- Gate 1: no paso ejecuciones
    IF EXISTS (
        SELECT 1 FROM mes.partida_paso pp
        JOIN mes.partida_paso_ejecucion ppe ON ppe.partida_paso_id = pp.id
        WHERE pp.partida_id = p_reproceso_id
    ) THEN
        RAISE EXCEPTION 'Reproceso % ya tiene ejecuciones de paso; no puede revertirse. Anule la producción primero.', p_reproceso_id
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    -- Gate 2: no movements tied to its pasos' ejecuciones (belt-and-suspenders)
    IF EXISTS (
        SELECT 1 FROM inventario.item_movimientos im
        WHERE im.documento_tipo = 'partida_paso_ejecucion'
          AND im.documento_id IN (
              SELECT ppe.id FROM mes.partida_paso pp
              JOIN mes.partida_paso_ejecucion ppe ON ppe.partida_paso_id = pp.id
              WHERE pp.partida_id = p_reproceso_id
          )
    ) THEN
        RAISE EXCEPTION 'Reproceso % tiene movimientos de inventario; no puede revertirse.', p_reproceso_id
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    RETURN v_child;
END;
$$;


ALTER FUNCTION mes._assert_reproceso_reversible(p_reproceso_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes._recount_reproceso_detalle(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes._recount_reproceso_detalle(p_partida_id bigint) RETURNS void
    LANGUAGE sql
    AS $$
    UPDATE mes.partida_detalle pd
    SET cantidad = GREATEST(sub.n, 1),
        usr_mod = get_user_id(), fyh_mod = NOW()
    FROM (
        SELECT l.item_id, COUNT(*) AS n
        FROM mes.partida_componente pc
        JOIN inventario.lote l ON l.id = pc.lote_id
        WHERE pc.partida_id = p_partida_id AND pc.lote_id IS NOT NULL
        GROUP BY l.item_id
    ) sub
    WHERE pd.partida_id = p_partida_id AND pd.item_id = sub.item_id;
$$;


ALTER FUNCTION mes._recount_reproceso_detalle(p_partida_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.actualizar_componentes_partida(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.actualizar_componentes_partida(p_partida_id bigint, p_componentes jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'mes', 'inventario'
    AS $$
DECLARE
    v_message  text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id               int  := get_user_id();
    v_estado               partida_estado_produccion_enum;
    v_error_payload        jsonb;
    v_overflow_item_id     INT;
    v_rollos_submitted     INT;
    v_cantidad_planificada NUMERIC;
BEGIN
    IF NOT jwt_has_permission('produccion.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT estado_produccion INTO v_estado
    FROM mes.partida
    WHERE id = p_partida_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Orden de producción con ID % no encontrada.', p_partida_id;
    END IF;

    IF v_estado IN ('TECO','CERRADA','CANCELADA') THEN
        RAISE EXCEPTION 'No se pueden modificar componentes de una orden en estado %.', v_estado;
    END IF;

    IF EXISTS (
        SELECT 1 FROM mes.partida_paso pp
        JOIN mes.partida_paso_ejecucion ppe ON ppe.partida_paso_id = pp.id
        WHERE pp.partida_id = p_partida_id
          AND ppe.estado IN ('EN_PROCESO','COMPLETADO','OMITIDO')
    ) THEN
        RAISE EXCEPTION
            'No se pueden modificar los componentes porque uno o más pasos ya han sido iniciados o completados.'
            USING ERRCODE = 'check_violation';
    END IF;

    WITH partida_rollos AS (
        SELECT
            (i->>'item_id')::int       AS item_id,
            (i->>'lote_id')::int       AS lote_id,
            (i->>'ubicacion_id')::int  AS ubicacion_id,
            SUM((i->>'cantidad')::numeric) AS cantidad
        FROM jsonb_array_elements(p_componentes) i
        GROUP BY 1,2,3
    ), errores AS (
        SELECT
            im.item_id,
            im.lote_id,
            COALESCE(im.destino_ubicacion_id, im.origen_ubicacion_id) AS ubicacion_id,
            items.cantidad,
            SUM(im.cantidad * (
                CASE WHEN im.destino_ubicacion_id IS NOT NULL THEN  1 ELSE 0 END +
                CASE WHEN im.origen_ubicacion_id  IS NOT NULL THEN -1 ELSE 0 END
            )) AS saldo
        FROM inventario.item_movimientos im
        JOIN partida_rollos AS items
          ON items.lote_id = im.lote_id
         AND items.ubicacion_id = COALESCE(im.destino_ubicacion_id, im.origen_ubicacion_id)
        GROUP BY im.item_id, im.lote_id,
                 COALESCE(im.destino_ubicacion_id, im.origen_ubicacion_id),
                 items.cantidad
        HAVING SUM(im.cantidad * (
            CASE WHEN im.destino_ubicacion_id IS NOT NULL THEN  1 ELSE 0 END +
            CASE WHEN im.origen_ubicacion_id  IS NOT NULL THEN -1 ELSE 0 END
        )) < items.cantidad
    )
    SELECT jsonb_agg(
        jsonb_build_object(
            'item_id', item_id,
            'lote_id', lote_id,
            'ubicacion_id', ubicacion_id,
            'saldo_disponible', saldo,
            'cantidad_requerida', cantidad
        )
    )
    INTO v_error_payload
    FROM errores;

    IF v_error_payload IS NOT NULL THEN
        RAISE EXCEPTION 'Stock insuficiente para asignar los componentes'
            USING DETAIL = v_error_payload::text;
    END IF;
    -- Per-item roll count guard: submitted rolls per item_id must not exceed partida_detalle.cantidad.
    -- Also catches rolls whose item has no partida_detalle entry (unplanned item).
    SELECT l.item_id, COUNT(*)::int, pd.cantidad
    INTO v_overflow_item_id, v_rollos_submitted, v_cantidad_planificada
    FROM jsonb_array_elements(p_componentes) i
    JOIN inventario.lote l ON l.id = (i->>'lote_id')::int
    LEFT JOIN mes.partida_detalle pd ON pd.item_id = l.item_id
                                    AND pd.partida_id = p_partida_id
    WHERE (i->>'lote_id') IS NOT NULL
    GROUP BY l.item_id, pd.cantidad
    HAVING COUNT(*) > COALESCE(pd.cantidad, 0)
    LIMIT 1;

    IF v_overflow_item_id IS NOT NULL THEN
        RAISE EXCEPTION
            'El ítem % tiene % rollos asignados pero solo % están planificados.',
            v_overflow_item_id, v_rollos_submitted, COALESCE(v_cantidad_planificada, 0)
            USING ERRCODE = 'check_violation';
    END IF;

    -- Reservation conflict check (exclude current order, rolls only)
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(p_componentes) i
        JOIN mes.partida_componente pc ON pc.lote_id = (i->>'lote_id')::int
        JOIN mes.partida pr ON pr.id = pc.partida_id
        WHERE pc.lote_id IS NOT NULL
          AND pr.estado_produccion NOT IN ('CANCELADA','TECO','CERRADA')
          AND pc.partida_id <> p_partida_id
    ) THEN
        RAISE EXCEPTION 'Uno o más rollos ya están reservados en otra orden activa'
            USING ERRCODE = 'check_violation';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('actualizar_componentes_partida', v_usr_id,
            jsonb_build_object('partida_id', p_partida_id, 'componentes', p_componentes));

    -- Remove roll components no longer in the list (never touch chemical rows)
    DELETE FROM mes.partida_componente
    WHERE partida_id = p_partida_id
      AND lote_id IS NOT NULL
      AND NOT EXISTS (
          SELECT 1 FROM jsonb_array_elements(p_componentes) i
          WHERE (i->>'lote_id')::int = lote_id
      );

    -- Migration 38 §5(a): drop scope rows for rolls just removed above. Not
    -- FK-cascaded — partida_paso_lote.lote_id references inventario.lote
    -- directly, not partida_componente, since the matrix keys on the roll's
    -- stable identity, not the reservation row. sincronizar_alcance_pasos is
    -- additive-only by design (never undoes a manual scope exclusion), so
    -- removal has to be explicit here rather than left to the sync call below.
    -- Safe irrespective of the guard at the top of this function (no paso
    -- started): every row deleted here is still PENDIENTE with no ejecucion_id.
    DELETE FROM mes.partida_paso_lote ppl
    USING mes.partida_paso pp
    WHERE ppl.partida_paso_id = pp.id
      AND pp.partida_id = p_partida_id
      AND NOT EXISTS (
          SELECT 1 FROM mes.partida_componente pc
          WHERE pc.partida_id = p_partida_id AND pc.lote_id = ppl.lote_id
      );

    -- Insert/update roll components (skip elements with missing/null lote_id)
    INSERT INTO mes.partida_componente(partida_id, lote_id, cantidad_reservada, usr_cre)
    SELECT p_partida_id,
           (i->>'lote_id')::int,
           (i->>'cantidad')::numeric,
           v_usr_id
    FROM jsonb_array_elements(p_componentes) i
    WHERE (i->>'lote_id') IS NOT NULL
    ON CONFLICT (partida_id, lote_id) WHERE lote_id IS NOT NULL
    DO UPDATE SET cantidad_reservada = EXCLUDED.cantidad_reservada;

    -- Migration 38 §5(a): scope rows for any newly-added rolls.
    PERFORM mes.sincronizar_alcance_pasos(p_partida_id);

    -- Roll weight changed → chemical reservations are stale; force re-generation per paso
    DELETE FROM mes.partida_componente
    WHERE item_id IS NOT NULL
      AND partida_paso_id IN (
          SELECT id FROM mes.partida_paso WHERE partida_id = p_partida_id
      );

    RETURN format('Componentes actualizados para orden #%s.', p_partida_id);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
        v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in actualizar_componentes_partida - User: %, partida: %, Error: %, Detail: %',
              v_usr_id, p_partida_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION mes.actualizar_componentes_partida(p_partida_id bigint, p_componentes jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.actualizar_estado_partida(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.actualizar_estado_partida(p_partida_id bigint) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'mes'
    AS $$
DECLARE
    v_hay_en_proceso   boolean;
    v_todos_terminados boolean;
    v_hay_pasos        boolean;
    v_hay_programacion boolean;
    v_estado_actual    partida_estado_produccion_enum;
BEGIN
    SELECT estado_produccion INTO v_estado_actual
    FROM mes.partida WHERE id = p_partida_id;

    -- Never touch terminal states
    IF v_estado_actual IN ('CERRADA', 'CANCELADA') THEN RETURN; END IF;

    -- Use paso-level estado, not ejecucion-level: a paso that still has rolls to process
    -- stays EN_PROCESO even when its last ejecucion is COMPLETADO (split-run model).
    -- Reading pp.estado avoids the premature-TECO bug where the first partial run closes
    -- its ejecucion but the paso itself is correctly still open.
    SELECT
        BOOL_OR(pp.estado = 'EN_PROCESO'),
        BOOL_AND(pp.estado IN ('COMPLETADO','OMITIDO')),
        COUNT(*) > 0
    INTO v_hay_en_proceso, v_todos_terminados, v_hay_pasos
    FROM mes.partida_paso pp
    WHERE pp.partida_id = p_partida_id;

    -- Execution-layer transitions take priority
    IF v_hay_pasos AND v_todos_terminados THEN
        UPDATE mes.partida
        SET estado_produccion = 'TECO',
            fyh_fin           = COALESCE(fyh_fin, NOW()),
            fyh_mod           = NOW()
        WHERE id = p_partida_id;
        RETURN;
    END IF;

    IF v_hay_pasos AND v_hay_en_proceso THEN
        UPDATE mes.partida
        SET estado_produccion = 'EN_PRODUCCION',
            fyh_inicio        = COALESCE(fyh_inicio, NOW()),
            fyh_fin           = NULL,
            fyh_mod           = NOW()
        WHERE id = p_partida_id;
        RETURN;
    END IF;

    -- Planning-layer transitions: only when no execution has started
    IF v_estado_actual NOT IN ('EN_PRODUCCION', 'TECO') THEN
        IF NOT v_hay_pasos THEN RETURN; END IF;  -- no steps yet, stay CREADA

        SELECT EXISTS (
            SELECT 1
            FROM mes.partida_paso pp
            JOIN mes.programacion prog
              ON prog.actividad_tipo = 'partida_paso'
             AND prog.actividad_id   = pp.id
             AND prog.fecha         >= CURRENT_DATE
            WHERE pp.partida_id = p_partida_id
        ) INTO v_hay_programacion;

        IF v_hay_programacion THEN
            UPDATE mes.partida SET estado_produccion = 'PROGRAMADA', fyh_mod = NOW()
            WHERE id = p_partida_id AND estado_produccion != 'PROGRAMADA';
        ELSE
            UPDATE mes.partida SET estado_produccion = 'PLANIFICADA', fyh_mod = NOW()
            WHERE id = p_partida_id AND estado_produccion != 'PLANIFICADA';
        END IF;
    END IF;
END;
$$;


ALTER FUNCTION mes.actualizar_estado_partida(p_partida_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.actualizar_partida(integer, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.actualizar_partida(p_partida_id integer, p_partida jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'mes'
    AS $$
DECLARE
    v_message   text;
    v_detail    text;
    v_hint      text;
    v_context   text;
    v_sqlstate  text;
    v_estado    text;
    v_usr_id    int := get_user_id();
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('actualizar_partida', v_usr_id, jsonb_build_object('partida_id', p_partida_id, 'partida', p_partida));

    -- Get current state
    SELECT estado_produccion INTO v_estado
    FROM mes.partida
    WHERE id = p_partida_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Partida con ID % no encontrada.', p_partida_id;
    END IF;

    -- Reject if terminal state
    IF v_estado IN ('CERRADA', 'CANCELADA') THEN
        RAISE EXCEPTION 'No se puede modificar una partida en estado %.', v_estado;
    END IF;

    -------------------------------------------------------------------------
    -- Always editable: prioridad_id, observacion
    -------------------------------------------------------------------------
    UPDATE mes.partida
    SET prioridad_id = (p_partida->>'prioridad_id')::INT,
        observacion  = p_partida->>'observacion'
    WHERE id = p_partida_id;

    -------------------------------------------------------------------------
    -- CREADA or PLANIFICADA: also malla, rendimiento
    -------------------------------------------------------------------------
    IF v_estado IN ('CREADA', 'PLANIFICADA') THEN
        UPDATE mes.partida
        SET malla          = (p_partida->>'malla')::TEXT,
            rendimiento    = p_partida->>'rendimiento',
            fecha_acordada = (p_partida->>'fecha_acordada')::DATE
        WHERE id = p_partida_id;
    END IF;

    -------------------------------------------------------------------------
    -- CREADA only: identity fields — tercero, tenido, color, grupo_articulo, fibra, antipilling
    -------------------------------------------------------------------------
    IF v_estado = 'CREADA' THEN
        UPDATE mes.partida
        SET tercero_id          = COALESCE((p_partida->>'tercero_id')::INT,           tercero_id),
            tenido_id           = COALESCE((p_partida->>'tenido_id')::INT,            tenido_id),
            color_x_cliente_id  = COALESCE((p_partida->>'color_x_cliente_id')::INT,  color_x_cliente_id),
            -- Identidad de sustrato: grupo_articulo_id. grupo_articulo_id lo deriva el
            -- trigger trg_bi_partida_derive_grupo_articulo; nunca se escribe aquí.
            grupo_articulo_id   = COALESCE((p_partida->>'grupo_articulo_id')::INT,   grupo_articulo_id),
            fibra               = COALESCE((p_partida->>'fibra')::SMALLINT,           fibra),
            flg_antipilling     = COALESCE((p_partida->>'flg_antipilling')::BOOLEAN,  flg_antipilling),
            flg_doble_bolsa     = COALESCE((p_partida->>'flg_doble_bolsa')::BOOLEAN,  flg_doble_bolsa),
            fecha_acordada      = (p_partida->>'fecha_acordada')::DATE
        WHERE id = p_partida_id;

        -- Full replace of detail rows
       -- Remove rows no longer in the incoming array
DELETE FROM mes.partida_detalle pd
WHERE pd.partida_id = p_partida_id
  AND NOT EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_partida->'partida_detalles') u
      WHERE (u->>'item_id')::INT = pd.item_id
  );

-- Upsert the rest
INSERT INTO mes.partida_detalle(partida_id, item_id, cantidad,unidad_id)
SELECT p_partida_id, (u->>'item_id')::INT, (u->>'cantidad')::INT, (u->>'unidad_id')::INT
FROM jsonb_array_elements(p_partida->'partida_detalles') u
ON CONFLICT (partida_id, item_id) DO UPDATE
  SET cantidad = EXCLUDED.cantidad;

    END IF;

    -------------------------------------------------------------------------
    -- Notification
    -------------------------------------------------------------------------
    INSERT INTO notification.notifications(user_id, title, body, tipo, payload)
    SELECT ur.user_id,
           'Partida Modificada',
           COALESCE(
               (SELECT COALESCE(nombre, 'Usuario desconocido') || ' ' || apellido
                FROM usuario WHERE id = v_usr_id),
               'sistema'
           ) || ' modificó la partida #' || p_partida_id,
           'info',
           jsonb_build_object('objeto_tipo', 'partida', 'partida_id', p_partida_id)
    FROM iam.user_rol ur
    LEFT JOIN usuario p ON p.id = ur.user_id
    LEFT JOIN iam.rol r ON ur.rol_id = r.id
    WHERE r.code IN ('jefe_planta', 'compras')
      AND v_usr_id <> ur.user_id;

    RETURN format('Partida con ID %s actualizada correctamente.', p_partida_id);

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;

        RAISE LOG 'Error en actualizar_partida - User: %, Params: %, Error: %, Detail: %',
                  v_usr_id, p_partida::TEXT, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION mes.actualizar_partida(p_partida_id integer, p_partida jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.actualizar_pasos_partida(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.actualizar_pasos_partida(p_partida_id bigint, p_pasos jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'mes'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id    int := get_user_id();
    v_estado    partida_estado_produccion_enum;
    v_count     int;
BEGIN
    IF NOT jwt_has_permission('produccion.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- Validar que la orden existe y no está en estado terminal
    SELECT estado_produccion INTO v_estado
    FROM mes.partida
    WHERE id = p_partida_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Orden de producción con ID % no encontrada.', p_partida_id;
    END IF;

    IF v_estado IN ('TECO','CERRADA','CANCELADA') THEN
        RAISE EXCEPTION 'No se pueden modificar pasos de una orden en estado %.', v_estado;
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('actualizar_pasos_partida', v_usr_id, jsonb_build_object('partida_id', p_partida_id, 'pasos', p_pasos));

    -- Clear chemical reservations for pasos where receta_id is changing;
    -- generar_receta re-populates them after the frontend confirms the new recipe
    DELETE FROM mes.partida_componente
    WHERE item_id IS NOT NULL
      AND partida_paso_id IN (
          SELECT pp.id
          FROM mes.partida_paso pp
          JOIN jsonb_array_elements(p_pasos) p
            ON (p->>'secuencia')::SMALLINT = pp.secuencia
          WHERE pp.partida_id = p_partida_id
            AND pp.receta_id IS DISTINCT FROM (p->>'receta_id')::INT
      );

    -- Bulk upsert: update existing, insert new (planning columns only)
    -- Machine is assigned on the scheduling board (mes.programacion), not on the step.
    -- Bath ratio lives on programacion (machine-coupled), not on paso.
    -- Backend computes secuencia from array position to avoid frontend desync bugs.
    --
    -- secuencia MUST be numbered once across the whole ordered array — existing and
    -- new pasos share the range, so numbering them in two independent passes lets a
    -- new paso reuse a secuencia already held by an existing one (violates
    -- partida_paso_partida_id_secuencia_key). We therefore:
    --   0) delete removed pasos first (frees their secuencia slots),
    --   1) park surviving existing pasos in a temporary high range so no live row
    --      blocks the target secuencia (the unique constraint is not deferrable),
    --   2) UPDATE existing + INSERT new using one unified ROW_NUMBER over the array.

    -- 0) Eliminar pasos que ya no están en la lista (solo si no han sido ejecutados).
    -- Cascade first into mes.programacion: a deleted paso may still be sitting on
    -- the scheduling board, and leaving that row behind creates an orphan whose
    -- actividad_id points at nothing (get_programacion_diaria then silently
    -- returns paso_id=NULL for it, which poisons the frontend's next save).
    DELETE FROM mes.programacion
    WHERE actividad_tipo = 'partida_paso'
      AND actividad_id IN (
          SELECT pp.id
          FROM mes.partida_paso pp
          WHERE pp.partida_id = p_partida_id
            AND pp.id NOT IN (
                SELECT (p->>'id')::BIGINT
                FROM jsonb_array_elements(p_pasos) p
                WHERE p->>'id' IS NOT NULL
            )
            AND NOT EXISTS (
                SELECT 1 FROM mes.partida_paso_ejecucion pe
                WHERE pe.partida_paso_id = pp.id
            )
      );

    DELETE FROM mes.partida_paso
    WHERE partida_id = p_partida_id
      AND id NOT IN (
          SELECT (p->>'id')::BIGINT
          FROM jsonb_array_elements(p_pasos) p
          WHERE p->>'id' IS NOT NULL
      )
      AND NOT EXISTS (
          SELECT 1 FROM mes.partida_paso_ejecucion pe
          WHERE pe.partida_paso_id = mes.partida_paso.id
      );

    -- 1) Park all surviving pasos out of the target secuencia range so neither the
    --    UPDATE nor the INSERT below transiently collides with a not-yet-moved row.
    UPDATE mes.partida_paso
    SET secuencia = secuencia + 10000
    WHERE partida_id = p_partida_id
      AND secuencia < 10000;

    -- Unified ordering: existing (has id) and new (no id) pasos numbered together
    -- by array position → 10, 20, 30 … with no cross-set overlap.
    WITH datos AS (
        SELECT
            (p->>'id')::BIGINT                    AS id,
            (ROW_NUMBER() OVER ()) * 10           AS secuencia,
            (p->>'operacion_id')::SMALLINT        AS operacion_id,
            (p->>'receta_id')::INT                AS receta_id,
            (p->>'ph_objetivo')::NUMERIC          AS ph_objetivo,
            (p->>'temperatura_objetivo')::NUMERIC AS temperatura_objetivo,
            (p->>'tiempo_estandar')::INT          AS tiempo_estandar
        FROM jsonb_array_elements(p_pasos) AS p
    )
    -- 2a) Update existing pasos by id
    UPDATE mes.partida_paso pp
    SET secuencia = d.secuencia,
        operacion_id = d.operacion_id,
        receta_id = d.receta_id,
        ph_objetivo = d.ph_objetivo,
        temperatura_objetivo = d.temperatura_objetivo,
        tiempo_estandar = d.tiempo_estandar,
        usr_mod = v_usr_id,
        fyh_mod = NOW()
    FROM datos d
    WHERE d.id IS NOT NULL
      AND pp.id = d.id
      AND NOT EXISTS (
          SELECT 1 FROM mes.partida_paso_ejecucion pe
          WHERE pe.partida_paso_id = pp.id
            AND pe.estado IN ('EN_PROCESO', 'COMPLETADO', 'OMITIDO')
      );

    -- 2a-bis) Executed pasos are protected from column edits above, but their
    -- secuencia must still follow their array position (kept in sync with the
    -- reordered range) — otherwise the parked +10000 value would linger or the
    -- restore step would land on a slot already taken. Move only secuencia.
    UPDATE mes.partida_paso pp
    SET secuencia = d.secuencia
    FROM (
        SELECT
            (p->>'id')::BIGINT          AS id,
            (ROW_NUMBER() OVER ()) * 10 AS secuencia
        FROM jsonb_array_elements(p_pasos) AS p
    ) d
    WHERE d.id IS NOT NULL
      AND pp.id = d.id
      AND pp.secuencia >= 10000
      AND EXISTS (
          SELECT 1 FROM mes.partida_paso_ejecucion pe
          WHERE pe.partida_paso_id = pp.id
            AND pe.estado IN ('EN_PROCESO', 'COMPLETADO', 'OMITIDO')
      );

    -- 2b) Insert new pasos (without id), reusing the same unified secuencia
    INSERT INTO mes.partida_paso(
        partida_id, secuencia, operacion_id,
        receta_id,
        ph_objetivo, temperatura_objetivo, tiempo_estandar,
        usr_cre
    )
    WITH datos AS (
        SELECT
            (p->>'id')::BIGINT                    AS id,
            (ROW_NUMBER() OVER ()) * 10           AS secuencia,
            (p->>'operacion_id')::SMALLINT        AS operacion_id,
            (p->>'receta_id')::INT                AS receta_id,
            (p->>'ph_objetivo')::NUMERIC          AS ph_objetivo,
            (p->>'temperatura_objetivo')::NUMERIC AS temperatura_objetivo,
            (p->>'tiempo_estandar')::INT          AS tiempo_estandar
        FROM jsonb_array_elements(p_pasos) AS p
    )
    SELECT p_partida_id, d.secuencia, d.operacion_id,
           d.receta_id, d.ph_objetivo, d.temperatura_objetivo, d.tiempo_estandar,
           v_usr_id
    FROM datos d
    WHERE d.id IS NULL;

    GET DIAGNOSTICS v_count = ROW_COUNT;

    -- Safety net: any paso still parked (present in DB but absent from p_pasos and
    -- undeletable due to an ejecucion) gets restored below the reordered range so it
    -- never collides. Should be empty in normal edits — the frontend always sends
    -- every non-removable paso — but guarantees no row is left stranded at +10000.
    UPDATE mes.partida_paso
    SET secuencia = secuencia - 10000 + 100000
    WHERE partida_id = p_partida_id
      AND secuencia >= 10000;

    -- Migration 38 §5(a): new pasos need scope rows for whatever rolls are
    -- already assigned. Removed pasos' scope rows are dropped automatically
    -- (partida_paso_lote.partida_paso_id is ON DELETE CASCADE).
    PERFORM mes.sincronizar_alcance_pasos(p_partida_id);

    PERFORM mes.actualizar_estado_partida(p_partida_id);

    RETURN format('%s pasos actualizados para orden #%s.', v_count, p_partida_id);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
        v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in actualizar_pasos_partida - User: %, orden: %, Error: %, Detail: %',
              v_usr_id, p_partida_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION mes.actualizar_pasos_partida(p_partida_id bigint, p_pasos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.actualizar_pesos_individuales_partida(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.actualizar_pesos_individuales_partida(p_partida_id bigint, p_items jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'mes', 'inventario'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int := get_user_id();
    v_estado            partida_estado_produccion_enum;
    v_count             int;
    v_pesaje_pos_id     smallint;
    v_pesaje_neg_id     smallint;
    v_doc_movimiento_id BIGINT;
BEGIN
    IF NOT jwt_has_permission('inventario.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT estado_produccion INTO v_estado
    FROM mes.partida WHERE id = p_partida_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Orden de producción con ID % no encontrada.', p_partida_id;
    END IF;
    IF v_estado IN ('TECO', 'CERRADA', 'CANCELADA') THEN
        RAISE EXCEPTION 'No se pueden modificar pesos de una orden en estado %.', v_estado;
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('actualizar_pesos_individuales_partida', v_usr_id,
            jsonb_build_object('partida_id', p_partida_id, 'items', p_items));

    SELECT id INTO v_pesaje_pos_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_POS';
    SELECT id INTO v_pesaje_neg_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PESAJE_NEG';

    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

    WITH
    input_items AS (
        SELECT (i->>'id')::BIGINT AS opi_id, (i->>'peso_kg')::NUMERIC AS peso_nuevo
        FROM jsonb_array_elements(p_items) i
    ),
    lotes_data AS (
        SELECT
            ii.peso_nuevo,
            l.id AS lote_id,
            l.item_id,
            l.cantidad AS peso_anterior,
            sa.ubicacion_id,
            ii.peso_nuevo - l.cantidad AS diferencia
        FROM input_items ii
        JOIN mes.partida_componente opi ON opi.id = ii.opi_id
            AND opi.partida_id = p_partida_id
        JOIN inventario.lote l ON l.id = opi.lote_id AND l.item_id = opi.item_id
        JOIN inventario.vw_stock_lotes_ubicacion sa ON sa.lote_id = l.id
    ),
    pesajes AS (
        INSERT INTO inventario.pesaje (lote_id, tipo, peso_real, usr_cre)
        SELECT ld.lote_id, 'CORRECCION', ld.peso_nuevo, v_usr_id
        FROM lotes_data ld
        ON CONFLICT (lote_id) DO UPDATE
            SET peso_real = EXCLUDED.peso_real,
                tipo      = EXCLUDED.tipo
        RETURNING id, lote_id
    ),
    movimientos AS (
        INSERT INTO inventario.item_movimientos (
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, destino_ubicacion_id,
            cantidad, documento_tipo, documento_id
        )
        SELECT
            v_doc_movimiento_id,
            ld.item_id, ld.lote_id,
            CASE WHEN ld.diferencia > 0 THEN v_pesaje_pos_id ELSE v_pesaje_neg_id END,
            CASE WHEN ld.diferencia < 0 THEN ld.ubicacion_id ELSE NULL END,
            CASE WHEN ld.diferencia > 0 THEN ld.ubicacion_id ELSE NULL END,
            ABS(ld.diferencia),
            'partida', p_partida_id
        FROM lotes_data ld
        JOIN pesajes p ON p.lote_id = ld.lote_id
        WHERE ld.diferencia <> 0
    )
    UPDATE inventario.lote l
    SET cantidad = ld.peso_nuevo
    FROM lotes_data ld
    WHERE l.id = ld.lote_id;

    GET DIAGNOSTICS v_count = ROW_COUNT;

    RETURN format('%s pesos actualizados individualmente para orden #%s.', v_count, p_partida_id);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS
        v_message = MESSAGE_TEXT, v_detail = PG_EXCEPTION_DETAIL,
        v_hint = PG_EXCEPTION_HINT, v_context = PG_EXCEPTION_CONTEXT,
        v_sqlstate = RETURNED_SQLSTATE;
    RAISE LOG 'Error in actualizar_pesos_individuales_partida - User: %, orden: %, Error: %, Detail: %',
              v_usr_id, p_partida_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION mes.actualizar_pesos_individuales_partida(p_partida_id bigint, p_items jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.actualizar_plantilla(integer, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.actualizar_plantilla(p_plantilla_id integer, p_plantilla jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'inventario', 'doc', 'mes'
    AS $$
DECLARE
    v_usr_id int := get_user_id();
BEGIN
    IF NOT jwt_has_permission('produccion.configurar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.configurar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('actualizar_plantilla', v_usr_id, p_plantilla);

    UPDATE ruta_plantilla 
    SET nombre = p_plantilla->>'nombre', usr_mod = v_usr_id, fyh_mod = NOW()
    WHERE id = p_plantilla_id;

    DELETE FROM ruta_plantilla_detalle WHERE ruta_plantilla_id = p_plantilla_id;

    INSERT INTO ruta_plantilla_detalle (ruta_plantilla_id, operacion_id, secuencia, ph, temperatura, tiempo_estandar)
    SELECT p_plantilla_id,
           (d->>'operacion_id')::INT,
           (d->>'secuencia')::SMALLINT,
           (d->>'ph')::NUMERIC(4,2),
           (d->>'temperatura')::NUMERIC(5,2),
           (d->>'tiempo_estandar')::INT
    FROM jsonb_array_elements(p_plantilla->'plantilla_detalles') AS d;

    RETURN format('Plantilla con ID %s actualizada correctamente.', p_plantilla_id);
END;
$$;


ALTER FUNCTION mes.actualizar_plantilla(p_plantilla_id integer, p_plantilla jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.anular_omision_paso(bigint, text)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.anular_omision_paso(p_paso_id bigint, p_motivo text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'mes'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id         int  := get_user_id();
    v_partida_id     bigint;
    v_secuencia      smallint;
    v_op_nombre      text;
    v_partida_estado partida_estado_produccion_enum;
    v_ejecucion_id   bigint;
BEGIN
    IF NOT jwt_has_permission('produccion.administrar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.administrar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_motivo IS NULL OR trim(p_motivo) = '' THEN
        RAISE EXCEPTION 'Se requiere motivo para anular la omisión.';
    END IF;

    SELECT pp.partida_id, pp.secuencia, o.nombre
    INTO   v_partida_id, v_secuencia, v_op_nombre
    FROM   mes.partida_paso pp
    JOIN   mes.operacion o ON o.id = pp.operacion_id
    WHERE  pp.id = p_paso_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Paso % no encontrado.', p_paso_id;
    END IF;

    SELECT estado_produccion INTO v_partida_estado FROM mes.partida WHERE id = v_partida_id;

    IF v_partida_estado IN ('CERRADA', 'CANCELADA') THEN
        RAISE EXCEPTION 'La partida #% está en estado % y no permite modificaciones.',
            v_partida_id, v_partida_estado;
    END IF;

    SELECT id INTO v_ejecucion_id
    FROM   mes.partida_paso_ejecucion
    WHERE  partida_paso_id = p_paso_id AND estado = 'OMITIDO'
    LIMIT  1;

    IF v_ejecucion_id IS NULL THEN
        RAISE EXCEPTION 'El paso % (#%) no tiene una ejecución OMITIDO activa.', v_op_nombre, p_paso_id;
    END IF;

    -- Guard: no subsequent paso COMPLETADO that depended on this omission
    IF EXISTS (
        SELECT 1
        FROM   mes.partida_paso pp2
        JOIN   mes.partida_paso_ejecucion pe2 ON pe2.partida_paso_id = pp2.id
        WHERE  pp2.partida_id = v_partida_id
          AND  pp2.secuencia  > v_secuencia
          AND  pe2.estado     = 'COMPLETADO'
    ) THEN
        RAISE EXCEPTION
            'No se puede anular la omisión del paso % porque hay pasos posteriores ya completados que dependen de él.',
            v_op_nombre;
    END IF;

    -- omitir_paso only inserted an ejecucion row with no movements — safe to DELETE
    DELETE FROM mes.partida_paso_ejecucion WHERE id = v_ejecucion_id;

    UPDATE mes.partida_paso
    SET estado  = 'PENDIENTE',
        fyh_mod = NOW()
    WHERE id = p_paso_id;

    PERFORM mes.actualizar_estado_partida(v_partida_id);

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_omision_paso', v_usr_id,
            jsonb_build_object('paso_id', p_paso_id, 'ejecucion_id', v_ejecucion_id,
                               'motivo', p_motivo));

    RETURN format('Omisión del paso %s (#%s) anulada. El paso está disponible para ejecución.',
                  v_op_nombre, p_paso_id);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_omision_paso - User: %, Paso: %, Error: %, Detail: %',
              v_usr_id, p_paso_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION mes.anular_omision_paso(p_paso_id bigint, p_motivo text) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.anular_partida(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.anular_partida(p_partida_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'mes', 'inventario'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id  int := get_user_id();
    v_estado  partida_estado_produccion_enum;
BEGIN
    IF NOT jwt_has_permission('comercial.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT estado_produccion INTO v_estado
    FROM mes.partida
    WHERE id = p_partida_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Partida #% no encontrada.', p_partida_id;
    END IF;

    IF v_estado IN ('TECO', 'CERRADA', 'CANCELADA') THEN
        RAISE EXCEPTION 'Partida #% ya está en estado %; no se puede anular.', p_partida_id, v_estado;
    END IF;

    -- Guard: no ejecución has ever run on any paso of this partida
    IF EXISTS (
        SELECT 1
        FROM mes.partida_paso_ejecucion pe
        JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
        WHERE pp.partida_id = p_partida_id
    ) THEN
        RAISE EXCEPTION
            'Partida #%: ya tiene ejecuciones registradas. Anule cada ejecución (mes.anular_produccion / mes.anular_reproceso) antes de anular la partida.',
            p_partida_id;
    END IF;

    -- Guard: no assigned roll has been weighed
    IF EXISTS (
        SELECT 1
        FROM mes.partida_componente pc
        JOIN inventario.pesaje ps ON ps.lote_id = pc.lote_id
        WHERE pc.partida_id = p_partida_id
          AND pc.lote_id IS NOT NULL
    ) THEN
        RAISE EXCEPTION
            'Partida #%: tiene rollos ya pesados. Anule el pesaje (inventario.anular_pesaje) antes de anular la partida.',
            p_partida_id;
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_partida', v_usr_id, jsonb_build_object('partida_id', p_partida_id));

    -- Release roll reservations — rolls return to available stock
    DELETE FROM mes.partida_componente
    WHERE partida_id = p_partida_id
      AND lote_id IS NOT NULL;

    UPDATE mes.partida
    SET estado_produccion = 'CANCELADA',
        usr_elm = v_usr_id,
        fyh_elm = NOW()
    WHERE id = p_partida_id;

    RETURN format('Partida #%s anulada.', p_partida_id);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_partida - User: %, partida: %, Error: %', v_usr_id, p_partida_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION mes.anular_partida(p_partida_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.anular_produccion(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.anular_produccion(p_ejecucion_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'inventario', 'mes', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int := get_user_id();
    v_partida_id        bigint;
    v_paso_id           bigint;
    v_estado            paso_ejecucion_estado_enum;
    v_ing_rev_id        smallint;
    v_consumo_rev_id    smallint;
    v_doc_movimiento_id bigint;
    v_output_count      int;
BEGIN
    IF NOT jwt_has_permission('produccion.ejecutar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.ejecutar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- 1. Ejecucion must exist and be COMPLETADO
    SELECT pe.estado, pp.partida_id, pp.id
    INTO v_estado, v_partida_id, v_paso_id
    FROM mes.partida_paso_ejecucion pe
    JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
    WHERE pe.id = p_ejecucion_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ejecución #% no encontrada.', p_ejecucion_id;
    END IF;
    IF v_estado <> 'COMPLETADO' THEN
        RAISE EXCEPTION 'Solo se puede anular una ejecución COMPLETADA. Estado actual: %', v_estado;
    END IF;

    -- 2. Guard: no downstream movements on output lotes
    IF EXISTS (
        SELECT 1
        FROM inventario.lote l
        JOIN inventario.item_movimientos im      ON im.lote_id = l.id
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE l.documento_tipo = 'partida_paso_ejecucion'
          AND l.documento_id   = p_ejecucion_id
          AND l.fyh_elm        IS NULL
          AND imt.codigo NOT IN ('PROD_ING', 'PROD_ING_REV')
    ) THEN
        RAISE EXCEPTION
            'No se puede anular la ejecución #%: uno o más lotes de salida ya tienen movimientos posteriores (despacho, ajuste, etc.). Anule esos documentos primero.',
            p_ejecucion_id;
    END IF;

    -- 2b. Guard: no live QC inspection on the output lotes. crear_inspeccion writes no
    -- item_movimientos row when the result isn't a rejection, so the guard above alone
    -- would miss it — letting this function soft-delete a lote a live inspeccion still
    -- points at, orphaning it (calidad.anular_inspeccion then can't recover it, since the
    -- lote wasn't soft-deleted via PROD_SCRAP).
    IF EXISTS (
        SELECT 1
        FROM inventario.lote l
        JOIN calidad.inspeccion ci ON ci.lote_id = l.id
        WHERE l.documento_tipo = 'partida_paso_ejecucion'
          AND l.documento_id   = p_ejecucion_id
          AND l.fyh_elm        IS NULL
    ) THEN
        RAISE EXCEPTION
            'No se puede anular la ejecución #%: uno o más lotes de salida tienen una inspección de calidad registrada. Anule esa inspección primero (calidad.anular_inspeccion).',
            p_ejecucion_id;
    END IF;

    -- 3. Lock rows
    PERFORM 1 FROM inventario.lote
    WHERE documento_tipo = 'partida_paso_ejecucion' AND documento_id = p_ejecucion_id
    FOR UPDATE;

    PERFORM 1 FROM mes.partida WHERE id = v_partida_id FOR UPDATE;

    -- 4. Fetch reversal movement type IDs
    SELECT id INTO v_ing_rev_id     FROM inventario.item_movimiento_tipo WHERE codigo = 'PROD_ING_REV';
    SELECT id INTO v_consumo_rev_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PROD_CONSUMO_REV';

    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

    -- 5. PROD_ING_REV: reverse ingress of output lotes
    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        origen_ubicacion_id, cantidad, documento_tipo, documento_id
    )
    SELECT
        v_doc_movimiento_id,
        l.item_id,
        l.id,
        v_ing_rev_id,
        sa.ubicacion_id,
        l.cantidad,
        'partida_paso_ejecucion',
        p_ejecucion_id
    FROM inventario.lote l
    JOIN inventario.vw_stock_lotes_ubicacion sa ON sa.lote_id = l.id
    WHERE l.documento_tipo = 'partida_paso_ejecucion'
      AND l.documento_id   = p_ejecucion_id
      AND l.fyh_elm        IS NULL;

    GET DIAGNOSTICS v_output_count = ROW_COUNT;

    -- 6. PROD_CONSUMO_REV: restore input lotes consumed by this execution run.
    --    Nets against any prior partial reversals (e.g. corregir_matizado) so
    --    already-reversed lots are not double-credited. Only lotes with net
    --    unconsumed quantity receive a reversal row.
    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        destino_ubicacion_id, cantidad, documento_tipo, documento_id
    )
    SELECT
        v_doc_movimiento_id,
        agg.item_id,
        agg.lote_id,
        v_consumo_rev_id,
        agg.origen_ubicacion_id,
        agg.net_cantidad,
        'partida_paso_ejecucion',
        p_ejecucion_id
    FROM (
        SELECT
            m.item_id,
            m.lote_id,
            m.origen_ubicacion_id,
            SUM(CASE WHEN m.item_movimiento_tipo_id = v_consumo_rev_id THEN -m.cantidad ELSE m.cantidad END) AS net_cantidad
        FROM inventario.item_movimientos m
        WHERE m.documento_tipo          = 'partida_paso_ejecucion'
          AND m.documento_id            = p_ejecucion_id
          AND m.item_movimiento_tipo_id IN (
              v_consumo_rev_id,
              (SELECT id FROM inventario.item_movimiento_tipo WHERE codigo = 'PROD_CONSUMO')
          )
        GROUP BY m.item_id, m.lote_id, m.origen_ubicacion_id
        HAVING SUM(CASE WHEN m.item_movimiento_tipo_id = v_consumo_rev_id THEN -m.cantidad ELSE m.cantidad END) > 0
    ) agg;

    -- 7. Soft-delete output lotes + their batch classification rows
    UPDATE inventario.lote
    SET usr_elm = v_usr_id, fyh_elm = NOW()
    WHERE documento_tipo = 'partida_paso_ejecucion'
      AND documento_id   = p_ejecucion_id
      AND fyh_elm        IS NULL;

    DELETE FROM inventario.lote_rollo_detalle
    WHERE lote_id IN (
        SELECT id FROM inventario.lote
        WHERE documento_tipo = 'partida_paso_ejecucion'
          AND documento_id   = p_ejecucion_id
    );

    -- 8. Reset execution run back to EN_PROCESO
    UPDATE mes.partida_paso_ejecucion
    SET estado  = 'EN_PROCESO',
        fyh_fin = NULL,
        usr_mod = v_usr_id,
        fyh_mod = NOW()
    WHERE id = p_ejecucion_id;

    UPDATE mes.partida_paso SET estado = 'EN_PROCESO', fyh_mod = NOW() WHERE id = v_paso_id;

    -- 9. Recount confirmed output — same logic as registrar_produccion so both
    -- functions always agree. The soft-delete above already excludes reversed lotes.
    UPDATE mes.partida_detalle pd
    SET cantidad_producida = (
        SELECT COUNT(*)
        FROM inventario.lote l
        JOIN mes.partida_paso_ejecucion pe
            ON pe.id = l.documento_id AND l.documento_tipo = 'partida_paso_ejecucion'
        JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
        WHERE pp.partida_id = v_partida_id
          AND l.item_id     = pd.item_id
          AND l.fyh_elm     IS NULL
    ),
    usr_mod = v_usr_id,
    fyh_mod = NOW()
    WHERE pd.partida_id = v_partida_id;

    PERFORM mes.actualizar_estado_partida(v_partida_id);

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_produccion', v_usr_id, jsonb_build_object('ejecucion_id', p_ejecucion_id));

    RETURN format('Producción de ejecución #%s anulada: %s lotes de salida revertidos.', p_ejecucion_id, v_output_count);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_produccion - User: %, ejecucion: %, Error: %, Detail: %',
              v_usr_id, p_ejecucion_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION mes.anular_produccion(p_ejecucion_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.anular_reproceso(bigint, public.calidad_estado_enum)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.anular_reproceso(p_reproceso_id bigint, p_estado_calidad public.calidad_estado_enum DEFAULT NULL::public.calidad_estado_enum) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'mes', 'inventario', 'calidad'
    AS $$
DECLARE
    v_usr_id  INT := get_user_id();
    v_lotes   INT[];
BEGIN
    IF NOT jwt_has_permission('produccion.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- Guard early (also locks the child) and confirm it's a reproceso.
    PERFORM mes._assert_reproceso_reversible(p_reproceso_id);

    SELECT ARRAY_AGG(lote_id) INTO v_lotes
    FROM mes.partida_componente
    WHERE partida_id = p_reproceso_id AND lote_id IS NOT NULL;

    IF v_lotes IS NULL THEN
        -- No rolls at all — just soft-delete the empty child.
        UPDATE mes.partida
        SET estado_produccion = 'CANCELADA', fyh_elm = NOW(), usr_elm = v_usr_id
        WHERE id = p_reproceso_id;

        INSERT INTO logs_api(function_name, user_id, params)
        VALUES ('anular_reproceso', v_usr_id,
                jsonb_build_object('reproceso_id', p_reproceso_id, 'lotes', '[]'::jsonb));

        RETURN jsonb_build_object('reproceso_id', p_reproceso_id, 'reproceso_anulado', true,
                                  'lotes_movidos', 0,
                                  'message', format('Reproceso %s anulado (no tenía rollos).', p_reproceso_id));
    END IF;

    RETURN mes.mover_lotes_reproceso(p_reproceso_id, v_lotes, p_estado_calidad);
END;
$$;


ALTER FUNCTION mes.anular_reproceso(p_reproceso_id bigint, p_estado_calidad public.calidad_estado_enum) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.anular_transferencia_rollo(integer, bigint, bigint, text)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.anular_transferencia_rollo(p_lote_id integer, p_partida_actual bigint, p_partida_original bigint, p_motivo text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'mes', 'inventario'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id           int := get_user_id();
    v_estado_actual    partida_estado_produccion_enum;
    v_estado_original  partida_estado_produccion_enum;
BEGIN
    IF NOT jwt_has_permission('produccion.administrar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.administrar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_motivo IS NULL OR trim(p_motivo) = '' THEN
        RAISE EXCEPTION 'Se requiere motivo para anular la transferencia.';
    END IF;

    -- Roll must currently be in p_partida_actual
    IF NOT EXISTS (
        SELECT 1 FROM mes.partida_componente
        WHERE lote_id = p_lote_id AND partida_id = p_partida_actual
    ) THEN
        RAISE EXCEPTION 'El rollo (lote #%) no está asignado a la partida #%.',
            p_lote_id, p_partida_actual;
    END IF;

    -- Roll must not have been consumed in p_partida_actual
    IF EXISTS (
        SELECT 1 FROM inventario.item_movimientos im
        JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
        WHERE im.lote_id = p_lote_id AND imt.codigo = 'PROD_CONSUMO'
    ) THEN
        RAISE EXCEPTION
            'El rollo (lote #%) ya fue consumido en producción. No se puede revertir la transferencia.',
            p_lote_id;
    END IF;

    -- Estado checks
    SELECT estado_produccion INTO v_estado_actual FROM mes.partida WHERE id = p_partida_actual;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Partida actual #% no encontrada.', p_partida_actual;
    END IF;
    IF v_estado_actual IN ('CERRADA', 'CANCELADA') THEN
        RAISE EXCEPTION 'La partida actual #% está en estado % y no permite modificaciones.',
            p_partida_actual, v_estado_actual;
    END IF;

    SELECT estado_produccion INTO v_estado_original FROM mes.partida WHERE id = p_partida_original;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Partida original #% no encontrada.', p_partida_original;
    END IF;
    IF v_estado_original IN ('CERRADA', 'CANCELADA') THEN
        RAISE EXCEPTION 'La partida original #% está en estado % y no puede recibir rollos.',
            p_partida_original, v_estado_original;
    END IF;

    -- Not already in p_partida_original
    IF EXISTS (
        SELECT 1 FROM mes.partida_componente
        WHERE lote_id = p_lote_id AND partida_id = p_partida_original
    ) THEN
        RAISE EXCEPTION 'El rollo (lote #%) ya está asignado a la partida original #%.',
            p_lote_id, p_partida_original;
    END IF;

    UPDATE mes.partida_componente
    SET partida_id = p_partida_original,
        usr_mod    = v_usr_id,
        fyh_mod    = now()
    WHERE lote_id    = p_lote_id
      AND partida_id = p_partida_actual;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('anular_transferencia_rollo', v_usr_id,
            jsonb_build_object('lote_id', p_lote_id,
                               'partida_actual', p_partida_actual,
                               'partida_original', p_partida_original,
                               'motivo', p_motivo));

    RETURN format('Rollo (lote #%s) revertido de partida #%s a partida #%s.',
                  p_lote_id, p_partida_actual, p_partida_original);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in anular_transferencia_rollo - User: %, Lote: %, Error: %, Detail: %',
              v_usr_id, p_lote_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION mes.anular_transferencia_rollo(p_lote_id integer, p_partida_actual bigint, p_partida_original bigint, p_motivo text) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.calcular_fifo(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.calcular_fifo(p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'inventario', 'mes'
    AS $$
DECLARE
    v_consumos jsonb;
BEGIN
    -- Pre-aggregate by item_id before joining to stock: duplicate item_ids in p_items
    -- would otherwise double every stock lot in the window partition, causing the running
    -- sum to be inflated and silently dropping some of the requested quantity.
    WITH input_agg AS (
        SELECT (i->>'item_id')::INT AS item_id, SUM((i->>'cantidad')::NUMERIC) AS cantidad
        FROM jsonb_array_elements(p_items) i
        GROUP BY 1
    ),
    fifo AS (
        SELECT
            st.lote_id,
            st.item_id,
            st.ubicacion_id,
            st.cantidad_disponible,
            st.fecha_hora_ingreso,
            inp.cantidad AS cantidad_solicitada,
            SUM(st.cantidad_disponible) OVER (
                PARTITION BY st.item_id ORDER BY st.fecha_hora_ingreso
            ) AS cantidad_acumulada
        FROM inventario.vw_stock_lotes_ubicacion st
        JOIN input_agg inp ON inp.item_id = st.item_id
    ),
    inventario_prev AS (
        SELECT
            *,
            LAG(cantidad_acumulada, 1, 0) OVER (
                PARTITION BY item_id ORDER BY fecha_hora_ingreso
            ) AS acumulado_previo
        FROM fifo
    ),
    inventario_consumo AS (
        SELECT
            lote_id,
            item_id,
            ubicacion_id,
            LEAST(
                cantidad_disponible,
                GREATEST(cantidad_solicitada - acumulado_previo, 0)
            ) AS cantidad_a_usar
        FROM inventario_prev
        WHERE acumulado_previo < cantidad_solicitada
    )
    SELECT jsonb_agg(jsonb_build_object(
        'lote_id', lote_id,
        'item_id', item_id,
        'ubicacion_id', ubicacion_id,
        'cantidad', cantidad_a_usar
    )) INTO v_consumos
    FROM inventario_consumo;

    RETURN v_consumos;
END;
$$;


ALTER FUNCTION mes.calcular_fifo(p_items jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.cerrar_partida(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.cerrar_partida(p_partida_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'mes', 'doc'
    AS $$
DECLARE
    v_message            text; v_detail text;
    v_usr_id             int := get_user_id();
    v_estado_produccion  partida_estado_produccion_enum;
    v_estado_comercial   partida_estado_comercial_enum;
    v_estado_facturacion partida_facturacion_enum;
    v_target_qty         numeric;
    v_output_qty         numeric;
    v_warning            text := '';
BEGIN
    IF NOT jwt_has_permission('produccion.administrar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.administrar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- Rework children are TECO-terminal: commercial settlement (estado_comercial,
    -- estado_facturacion) always runs on the parent order. Close the parent once
    -- all reprocesos are in TECO/CERRADA/CANCELADA — not each child individually.
    IF EXISTS (SELECT 1 FROM mes.partida WHERE id = p_partida_id AND partida_origen_id IS NOT NULL) THEN
        RAISE EXCEPTION
            'Partida % es un reproceso y no puede cerrarse directamente. Cierre la partida origen una vez que todos sus reprocesos estén en TECO.',
            p_partida_id;
    END IF;

    SELECT estado_produccion, estado_comercial, estado_facturacion
    INTO v_estado_produccion, v_estado_comercial, v_estado_facturacion
    FROM mes.partida
    WHERE id = p_partida_id
      AND fyh_elm IS NULL;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Partida % no encontrada.', p_partida_id;
    END IF;

    IF v_estado_produccion <> 'TECO' THEN
        RAISE EXCEPTION
            'Solo se puede cerrar una partida en estado TECO. Estado actual: %',
            v_estado_produccion;
    END IF;

    IF EXISTS (
        SELECT 1 FROM mes.partida
        WHERE partida_origen_id = p_partida_id
          AND estado_produccion NOT IN ('TECO','CERRADA','CANCELADA')
    ) THEN
        RAISE EXCEPTION
            'Partida % tiene reprocesos activos pendientes. Finalícelos antes de cerrar.',
            p_partida_id;
    END IF;

    IF v_estado_comercial NOT IN ('ENTREGADA','DEVUELTA_PARCIAL','DEVUELTA_TOTAL') THEN
        RAISE EXCEPTION
            'Partida % no puede cerrarse: estado comercial % no indica entrega registrada.',
            p_partida_id, v_estado_comercial;
    END IF;

    IF v_estado_facturacion <> 'facturado' THEN
        RAISE EXCEPTION
            'Partida % no puede cerrarse: facturación en estado %. Se requiere facturación completa.',
            p_partida_id, v_estado_facturacion;
    END IF;

    -- Soft warning: approved family output vs intended demand. Reads the same
    -- definition the commercial views use (mes.vw_partida_familia) so the number
    -- can't drift between here, get_partida_familia, and the board. p_partida_id
    -- is guaranteed to be a root (children were rejected above), which is the
    -- grain of vw_partida_familia.
    SELECT demanda_rollos, producido_bueno
    INTO   v_target_qty, v_output_qty
    FROM   mes.vw_partida_familia
    WHERE  partida_id = p_partida_id;

    IF v_output_qty < v_target_qty THEN
        v_warning := format(' ATENCIÓN: producción aprobada (%s rollos) es menor al objetivo (%s rollos). Verifique antes de cerrar.', v_output_qty, v_target_qty);
    END IF;

    UPDATE mes.partida
    SET estado_produccion = 'CERRADA',
        fyh_mod           = NOW(),
        usr_mod           = v_usr_id
    WHERE id = p_partida_id;

    RETURN format('Partida #%s cerrada correctamente.%s', p_partida_id, v_warning);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL;
    RAISE LOG 'Error in cerrar_partida - User: %, partida: %, Error: %', v_usr_id, p_partida_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION mes.cerrar_partida(p_partida_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.completar_lavado_retroactivo(bigint, bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.completar_lavado_retroactivo(p_lavado_id bigint, p_cuadre_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes', 'receta'
    AS $$
DECLARE
    v_usr_id       INT   := get_user_id();
    v_lavado       mes.lavado_maquina%ROWTYPE;
    v_cuadre       inventario.cuadre%ROWTYPE;
    v_insumos      JSONB;
    v_egr_tipo_id  SMALLINT;
    v_ing_tipo_id  SMALLINT;
    v_motivo_id    SMALLINT;
    v_doc_mov_id   BIGINT;
    v_ubicacion_id INT;
    v_fyh_ts       TIMESTAMPTZ;
    v_rec          RECORD;
    v_lote_id      INT;
BEGIN
    IF NOT jwt_has_permission('produccion.administrar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.administrar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO v_lavado FROM mes.lavado_maquina WHERE id = p_lavado_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'lavado_maquina id=% no encontrado.', p_lavado_id;
    END IF;
    IF v_lavado.estado NOT IN ('PENDIENTE', 'EN_PROCESO') THEN
        RAISE EXCEPTION 'lavado_maquina id=% estado=%: solo PENDIENTE/EN_PROCESO aceptado.',
            p_lavado_id, v_lavado.estado;
    END IF;

    SELECT * INTO v_cuadre FROM inventario.cuadre WHERE id = p_cuadre_id;
    IF NOT FOUND OR v_cuadre.estado <> 'ejecutado' THEN
        RAISE EXCEPTION 'cuadre id=% no encontrado o no está en estado ejecutado.', p_cuadre_id;
    END IF;

    IF v_lavado.fyh_cre >= v_cuadre.fecha_cierre THEN
        RAISE EXCEPTION 'lavado_maquina id=% fue creado después del cierre del cuadre id=% — no aplica.',
            p_lavado_id, p_cuadre_id;
    END IF;

    -- Estimate timestamp from ordinal position in the day's schedule.
    -- Strategy: find the completed partida_paso runs scheduled on the same
    -- machine/date, bracket the lavado by secuencia, then interpolate:
    --   • both neighbours known  → midpoint between prev.fyh_fin and next.fyh_inicio
    --   • only prev known        → prev.fyh_fin + 30 min
    --   • only next known        → next.fyh_inicio - 30 min
    --   • no neighbours at all   → noon on the scheduled date
    --   • no programacion row    → day before cuadre snapshot at noon (last resort)
    -- NOTE: caller must disable trg_bi_item_movimientos_corte_cuadre first —
    -- the cutoff trigger blocks fecha_hora < MAX(fecha_cuadre).
    WITH lav_prog AS (
        -- Most recent schedule entry (lavado may have been rescheduled across dates)
        SELECT p.maquina_id, p.fecha, p.secuencia
        FROM mes.programacion p
        WHERE p.actividad_tipo = 'LAVADO_MAQUINA'
          AND p.actividad_id   = p_lavado_id
        ORDER BY p.fecha DESC
        LIMIT 1
    ),
    paso_runs AS (
        -- completed ejecucion timestamps for partida_pasos on the same machine/date
        SELECT
            pr.secuencia,
            MAX(ppe.fyh_fin)    AS fyh_fin,
            MIN(ppe.fyh_inicio) AS fyh_inicio
        FROM mes.programacion pr
        JOIN mes.partida_paso_ejecucion ppe
               ON ppe.partida_paso_id = pr.actividad_id
        WHERE pr.actividad_tipo = 'partida_paso'
          AND pr.maquina_id     = (SELECT maquina_id FROM lav_prog)
          AND pr.fecha          = (SELECT fecha       FROM lav_prog)
          AND ppe.fyh_fin IS NOT NULL
        GROUP BY pr.secuencia
    ),
    bracket AS (
        SELECT
            (SELECT MAX(fyh_fin)    FROM paso_runs r, lav_prog lp WHERE r.secuencia < lp.secuencia) AS prev_end,
            (SELECT MIN(fyh_inicio) FROM paso_runs r, lav_prog lp WHERE r.secuencia > lp.secuencia) AS next_start,
            (SELECT fecha FROM lav_prog) AS sched_date
    )
    SELECT COALESCE(
        CASE
            -- Normal bracket: prev finished before next started → midpoint
            WHEN prev_end IS NOT NULL AND next_start IS NOT NULL
                 AND prev_end < next_start
                THEN prev_end + (next_start - prev_end) / 2
            -- Inverted bracket: secuencia order doesn't match wall-clock order
            -- (step rescheduled after execution). Anchor just before next_start.
            WHEN prev_end IS NOT NULL AND next_start IS NOT NULL
                 AND prev_end >= next_start
                THEN next_start - INTERVAL '30 minutes'
            WHEN prev_end IS NOT NULL
                THEN prev_end   + INTERVAL '30 minutes'
            WHEN next_start IS NOT NULL
                THEN next_start - INTERVAL '30 minutes'
            ELSE (sched_date + TIME '12:00:00')::TIMESTAMPTZ
        END
    )
    INTO v_fyh_ts
    FROM bracket;

    IF v_fyh_ts IS NULL THEN
        -- No programacion row at all — fall back to day before cuadre snapshot
        v_fyh_ts := (v_cuadre.fecha_cuadre::DATE - 1 + TIME '12:00:00')::TIMESTAMPTZ;
    END IF;

    -- Aggregate recipe insumos (identical logic to finalizar_lavado_maquina)
    SELECT jsonb_agg(jsonb_build_object('item_id', item_id, 'cantidad', cantidad))
    INTO v_insumos
    FROM (
        SELECT lmpi.item_id, SUM(lmpi.cantidad) AS cantidad
        FROM receta.lavado_maquina_paso lmp
        JOIN receta.lavado_maquina_paso_insumo lmpi ON lmpi.paso_id = lmp.id
        WHERE lmp.receta_id = v_lavado.receta_id
        GROUP BY lmpi.item_id
    ) agg;

    IF v_insumos IS NOT NULL THEN
        SELECT id INTO v_egr_tipo_id FROM inventario.item_movimiento_tipo WHERE codigo = 'PROD_CONSUMO';
        SELECT id INTO v_ing_tipo_id  FROM inventario.item_movimiento_tipo WHERE codigo = 'AJUSTE_POS';
        SELECT id INTO v_motivo_id
            FROM inventario.item_movimiento_motivo
            WHERE item_movimiento_tipo_id = v_egr_tipo_id AND codigo = 'LAVADO_MAQUINA';

        -- Default insumo storage location
        SELECT u.id INTO v_ubicacion_id
        FROM inventario.ubicacion u
        JOIN inventario.almacen a ON a.id = u.almacen_id
        WHERE a.codigo = 'ALM_INS'
        LIMIT 1;

        SELECT nextval('inventario.mov_doc_seq') INTO v_doc_mov_id;

        FOR v_rec IN
            SELECT
                (i->>'item_id')::INT        AS item_id,
                (i->>'cantidad')::NUMERIC   AS cantidad,
                COALESCE(iv.precio_promedio, 0) AS precio
            FROM jsonb_array_elements(v_insumos) i
            LEFT JOIN inventario.item_valoracion iv
                   ON iv.item_id = (i->>'item_id')::INT
        LOOP
            -- Phantom lote: enters and exits in the same operation.
            -- Linked to the cuadre so its origin is traceable.
            INSERT INTO inventario.lote (
                item_id, documento_tipo, documento_id, cantidad, fyh_cre
            ) VALUES (
                v_rec.item_id, 'cuadre', p_cuadre_id::INT, v_rec.cantidad, v_fyh_ts
            )
            RETURNING id INTO v_lote_id;

            -- AJUSTE_POS: credits back what the cuadre's AJUSTE_NEG absorbed
            -- for this lavado's consumption.  Net stock effect = 0 after the
            -- PROD_CONSUMO below.
            INSERT INTO inventario.item_movimientos (
                doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
                destino_ubicacion_id,
                cantidad, precio_unitario,
                documento_tipo, documento_id,
                observacion, fecha_hora, fyh_cre
            ) VALUES (
                v_doc_mov_id,
                v_rec.item_id, v_lote_id, v_ing_tipo_id,
                v_ubicacion_id,
                v_rec.cantidad, v_rec.precio,
                'cuadre', p_cuadre_id::INT,
                'Corrección retroactiva lavado_maquina id=' || p_lavado_id
                    || ': devuelve lo absorbido por cuadre id=' || p_cuadre_id,
                v_fyh_ts, v_fyh_ts
            );

            -- PROD_CONSUMO: the actual consumption tied to this lavado for traceability.
            INSERT INTO inventario.item_movimientos (
                doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
                origen_ubicacion_id,
                cantidad, precio_unitario,
                documento_tipo, documento_id, motivo_id,
                observacion, fecha_hora, fyh_cre
            ) VALUES (
                v_doc_mov_id,
                v_rec.item_id, v_lote_id, v_egr_tipo_id,
                v_ubicacion_id,
                v_rec.cantidad, v_rec.precio,
                'lavado_maquina', p_lavado_id::INT, v_motivo_id,
                'Corrección retroactiva: consumo real, cuadre id=' || p_cuadre_id
                    || ' había absorbido el déficit.',
                v_fyh_ts, v_fyh_ts
            );
        END LOOP;
    END IF;

    -- Mark COMPLETADO
    UPDATE mes.lavado_maquina SET
        estado      = 'COMPLETADO',
        fyh_inicio  = COALESCE(fyh_inicio, fyh_cre),
        fyh_fin     = v_fyh_ts,
        fyh_mod     = now()
    WHERE id = p_lavado_id;

    -- Update machine maintenance stamp (same as finalizar_lavado_maquina)
    UPDATE mes.maquina SET
        ultimo_mantenimiento = v_fyh_ts,
        fyh_mod              = now()
    WHERE id = v_lavado.maquina_id;
END;
$$;


ALTER FUNCTION mes.completar_lavado_retroactivo(p_lavado_id bigint, p_cuadre_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.completar_lavados_pre_cuadre(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.completar_lavados_pre_cuadre(p_cuadre_id bigint) RETURNS TABLE(lavado_id bigint, receta_id integer, maquina_id integer, resultado text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes', 'receta'
    AS $$
DECLARE
    v_cuadre inventario.cuadre%ROWTYPE;
    v_lm     mes.lavado_maquina%ROWTYPE;
BEGIN
    SELECT * INTO v_cuadre FROM inventario.cuadre WHERE id = p_cuadre_id;
    IF NOT FOUND OR v_cuadre.estado <> 'ejecutado' THEN
        RAISE EXCEPTION 'cuadre id=% no encontrado o no está ejecutado.', p_cuadre_id;
    END IF;

    FOR v_lm IN
        SELECT lm.*
        FROM mes.lavado_maquina lm
        WHERE lm.estado IN ('PENDIENTE', 'EN_PROCESO')
          AND lm.fyh_cre < v_cuadre.fecha_cierre
        ORDER BY lm.fyh_cre
    LOOP
        BEGIN
            PERFORM mes.completar_lavado_retroactivo(v_lm.id, p_cuadre_id);
            lavado_id  := v_lm.id;
            receta_id  := v_lm.receta_id;
            maquina_id := v_lm.maquina_id;
            resultado  := 'OK';
            RETURN NEXT;
        EXCEPTION WHEN OTHERS THEN
            lavado_id  := v_lm.id;
            receta_id  := v_lm.receta_id;
            maquina_id := v_lm.maquina_id;
            resultado  := SQLERRM;
            RETURN NEXT;
        END;
    END LOOP;
END;
$$;


ALTER FUNCTION mes.completar_lavados_pre_cuadre(p_cuadre_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.corregir_matizado(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.corregir_matizado(p_ejecucion_id bigint, p_consumos jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id              int     := get_user_id();
    v_consumo_tipo_id     smallint;
    v_consumo_rev_id      smallint;
    v_matizado_motivo_id  smallint;
    v_doc_movimiento_id   BIGINT;
    v_rev_count           int;
    v_consumos_fifo       jsonb;
    v_consumos_std        jsonb;
    v_error_payload       jsonb;
    v_fung_count          int := 0;
BEGIN
    IF NOT jwt_has_permission('produccion.ejecutar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.ejecutar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- 1. Validate ejecucion exists and is COMPLETADO
    IF NOT EXISTS (
        SELECT 1 FROM mes.partida_paso_ejecucion
        WHERE id = p_ejecucion_id AND estado = 'COMPLETADO'
    ) THEN
        RAISE EXCEPTION 'Ejecución #% no encontrada o no está COMPLETADA.', p_ejecucion_id;
    END IF;

    -- 2. Fetch movement type / motivo IDs
    SELECT id INTO v_consumo_tipo_id    FROM inventario.item_movimiento_tipo   WHERE codigo = 'PROD_CONSUMO';
    SELECT id INTO v_consumo_rev_id     FROM inventario.item_movimiento_tipo   WHERE codigo = 'PROD_CONSUMO_REV';
    SELECT id INTO v_matizado_motivo_id FROM inventario.item_movimiento_motivo WHERE codigo = 'MATIZADO';

    -- 3. Guard: one correction per execution — motivo_id on REV distinguishes this from anular_produccion
    IF EXISTS (
        SELECT 1 FROM inventario.item_movimientos
        WHERE documento_tipo          = 'partida_paso_ejecucion'
          AND documento_id            = p_ejecucion_id
          AND item_movimiento_tipo_id = v_consumo_rev_id
          AND motivo_id               = v_matizado_motivo_id
    ) THEN
        RAISE EXCEPTION
            'La ejecución #% ya tiene una corrección de matizado aplicada. Para corregir nuevamente use anular_produccion y rehaga el paso desde cero.',
            p_ejecucion_id;
    END IF;

    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

    -- 4. Reverse all existing MATIZADO consumos for this execution
    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        destino_ubicacion_id, cantidad, documento_tipo, documento_id, motivo_id
    )
    SELECT
        v_doc_movimiento_id,
        m.item_id,
        m.lote_id,
        v_consumo_rev_id,
        m.origen_ubicacion_id,
        m.cantidad,
        'partida_paso_ejecucion',
        p_ejecucion_id,
        v_matizado_motivo_id
    FROM inventario.item_movimientos m
    WHERE m.documento_tipo          = 'partida_paso_ejecucion'
      AND m.documento_id            = p_ejecucion_id
      AND m.item_movimiento_tipo_id = v_consumo_tipo_id
      AND m.motivo_id               = v_matizado_motivo_id;

    GET DIAGNOSTICS v_rev_count = ROW_COUNT;

    -- v_rev_count = 0 is valid: retroactive registration (matizado was never recorded)

    -- 5. Stock check against new quantities (reversal already visible within this tx)
    WITH consumos AS (
        SELECT (i->>'item_id')::int AS item_id, SUM((i->>'cantidad')::numeric) AS cantidad
        FROM jsonb_array_elements(p_consumos) i
        GROUP BY 1
    ),
    errores AS (
        SELECT c.item_id, it.nombre AS item_nombre, c.cantidad,
               COALESCE(sg.cantidad_total, 0) AS cantidad_disponible
        FROM consumos c
        LEFT JOIN inventario.vw_stock_items sg ON sg.item_id = c.item_id
        JOIN item it ON it.id = c.item_id
        WHERE COALESCE(sg.cantidad_total, 0) < c.cantidad
          AND it.flg_fungible = FALSE
    )
    SELECT jsonb_agg(jsonb_build_object(
        'item_id', item_id, 'item_nombre', item_nombre,
        'saldo_disponible', cantidad_disponible, 'cantidad_requerida', cantidad
    ))
    INTO v_error_payload FROM errores;

    IF v_error_payload IS NOT NULL THEN
        RAISE EXCEPTION 'Stock insuficiente para corregir matizado'
            USING DETAIL = v_error_payload::text;
    END IF;

    -- ── Non-fungible: FIFO ───────────────────────────────────────
    SELECT jsonb_agg(item || jsonb_build_object('motivo_id', v_matizado_motivo_id))
    INTO v_consumos_std
    FROM jsonb_array_elements(p_consumos) AS item
    JOIN item it ON it.id = (item->>'item_id')::int
    WHERE it.flg_fungible = FALSE;

    IF v_consumos_std IS NOT NULL THEN
        v_consumos_fifo := mes.calcular_fifo(v_consumos_std);

        INSERT INTO inventario.item_movimientos(
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, cantidad, precio_unitario,
            documento_tipo, documento_id, motivo_id
        )
        SELECT
            v_doc_movimiento_id,
            (v->>'item_id')::INT,
            (v->>'lote_id')::INT,
            v_consumo_tipo_id,
            (v->>'ubicacion_id')::INT,
            (v->>'cantidad')::NUMERIC,
            (SELECT iv.precio_promedio FROM inventario.item_valoracion iv
             WHERE iv.item_id = (v->>'item_id')::INT),
            'partida_paso_ejecucion',
            p_ejecucion_id,
            v_matizado_motivo_id
        FROM jsonb_array_elements(v_consumos_fifo) v;
    END IF;

    -- ── Fungible: lotless with fallback chain ────────────────────
    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        origen_ubicacion_id, cantidad, precio_unitario,
        documento_tipo, documento_id, motivo_id
    )
    SELECT
        v_doc_movimiento_id,
        fung.item_id,
        NULL,
        v_consumo_tipo_id,
        COALESCE(
            (SELECT ubicacion_id FROM inventario.item_saldo
             WHERE item_id = fung.item_id
             ORDER BY cantidad_actual DESC LIMIT 1),
            (SELECT im2.origen_ubicacion_id FROM inventario.item_movimientos im2
             WHERE im2.item_id = fung.item_id
               AND im2.origen_ubicacion_id IS NOT NULL
             ORDER BY im2.id DESC LIMIT 1),
            (SELECT ity.ubicacion_default_id FROM item it2
             JOIN item_tipo ity ON ity.id = it2.item_tipo_id
             WHERE it2.id = fung.item_id)
        ),
        fung.cantidad,
        (SELECT precio_promedio FROM inventario.item_valoracion WHERE item_id = fung.item_id),
        'partida_paso_ejecucion',
        p_ejecucion_id,
        v_matizado_motivo_id
    FROM (
        SELECT (i->>'item_id')::int AS item_id,
               SUM((i->>'cantidad')::numeric) AS cantidad
        FROM jsonb_array_elements(p_consumos) i
        JOIN item it ON it.id = (i->>'item_id')::int
        WHERE it.flg_fungible = TRUE
        GROUP BY 1
    ) fung;

    GET DIAGNOSTICS v_fung_count = ROW_COUNT;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('corregir_matizado', v_usr_id,
            jsonb_build_object('ejecucion_id', p_ejecucion_id, 'consumos', p_consumos));

    RETURN CASE
        WHEN v_rev_count = 0
        THEN format('Matizado registrado retroactivamente en ejecución #%s.', p_ejecucion_id)
        ELSE format('Matizado corregido en ejecución #%s: %s movimientos revertidos, nuevos consumos registrados.', p_ejecucion_id, v_rev_count)
    END;

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in corregir_matizado - User: %, ejecucion: %, Error: %, Detail: %',
              v_usr_id, p_ejecucion_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION mes.corregir_matizado(p_ejecucion_id bigint, p_consumos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.crear_lavado_maquina(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.crear_lavado_maquina(p_datos jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes', 'receta'
    AS $$
DECLARE
    v_id        BIGINT;
    v_usr_id    INT     := get_user_id();
    v_receta_id INT     := (p_datos->>'receta_id')::INT;
    v_maq_id    INT     := (p_datos->>'maquina_id')::INT;
BEGIN
    IF NOT jwt_has_permission('produccion.ejecutar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.ejecutar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM receta.lavado_maquina WHERE id = v_receta_id AND flg_activo = true
    ) THEN
        RAISE EXCEPTION 'Receta lavado máquina id=% no existe o no está activa.', v_receta_id;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mes.maquina WHERE id = v_maq_id AND fyh_elm IS NULL
    ) THEN
        RAISE EXCEPTION 'Máquina id=% no encontrada.', v_maq_id;
    END IF;

    INSERT INTO mes.lavado_maquina(
        receta_id, maquina_id, empleado_id, nota,
        estado, usr_cre, fyh_cre
    ) VALUES (
        v_receta_id,
        v_maq_id,
        (p_datos->>'empleado_id')::SMALLINT,
        p_datos->>'nota',
        'PENDIENTE',
        v_usr_id, now()
    )
    RETURNING id INTO v_id;

    RETURN v_id;
END;$$;


ALTER FUNCTION mes.crear_lavado_maquina(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.crear_partida(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.crear_partida(p_partida jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'doc', 'mes', 'inventario'
    AS $$
DECLARE
    v_message        text;
    v_detail         text;
    v_hint           text;
    v_context        text;
    v_sqlstate       text;
    v_partida_id           BIGINT;
    v_usr_id               int := get_user_id();
    v_error_payload        jsonb;
    v_overflow_item_id     INT;
    v_rollos_submitted     INT;
    v_cantidad_planificada NUMERIC;
    v_grupo                INT;
    v_fibra                SMALLINT;
    v_fibra_max            SMALLINT;
BEGIN
    IF NOT jwt_has_permission('comercial.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere comercial.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- ── Required header fields ────────────────────────────────────────────────
    IF (p_partida->>'tercero_id') IS NULL THEN
        RAISE EXCEPTION 'tercero_id es requerido' USING ERRCODE = 'not_null_violation';
    END IF;
    IF (p_partida->>'color_x_cliente_id') IS NULL THEN
        RAISE EXCEPTION 'color_x_cliente_id es requerido' USING ERRCODE = 'not_null_violation';
    END IF;
    IF (p_partida->>'tenido_id') IS NULL THEN
        RAISE EXCEPTION 'tenido_id es requerido' USING ERRCODE = 'not_null_violation';
    END IF;
    -- CLEAN BREAK (migración 32): la partida se identifica por grupo_articulo_id.
    -- grupo_articulo_id no se acepta ni se escribe aquí — lo deriva del grupo el
    -- trigger trg_bi_partida_derive_grupo_articulo (puente temporal hasta que la
    -- migración de precios mueva a sus lectores).
    IF (p_partida->>'grupo_articulo_id') IS NULL THEN
        RAISE EXCEPTION 'grupo_articulo_id es requerido' USING ERRCODE = 'not_null_violation';
    END IF;
    IF (p_partida->>'fibra') IS NULL THEN
        RAISE EXCEPTION 'fibra es requerido' USING ERRCODE = 'not_null_violation';
    END IF;

    v_grupo := (p_partida->>'grupo_articulo_id')::int;
    v_fibra := (p_partida->>'fibra')::smallint;

    PERFORM 1 FROM grupo_articulo WHERE id = v_grupo AND fyh_elm IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'grupo_articulo_id % no existe o está dado de baja.', v_grupo
            USING ERRCODE = 'foreign_key_violation';
    END IF;

    -- ── Techo de fibra ────────────────────────────────────────────────────────
    -- fibra = sistemas de tintura EJECUTADOS. Puede ser MENOR a lo que el sustrato
    -- requiere (colores jaspeados: reactivo solo sobre algodón/poliéster deja el
    -- poliéster blanco), pero nunca MAYOR — correr disperso sobre algodón puro no
    -- tiene sentido. El techo es el MAX de lo que requieren los miembros del grupo.
    SELECT MAX(a.fibra) INTO v_fibra_max
    FROM grupo_articulo_miembro gm
    JOIN articulo a ON a.id = gm.articulo_id
    WHERE gm.grupo_articulo_id = v_grupo;

    IF v_fibra_max IS NOT NULL AND v_fibra > v_fibra_max THEN
        RAISE EXCEPTION
            'fibra % excede el máximo del grupo (%): no se pueden correr más sistemas de tintura de los que requiere el sustrato.',
            v_fibra, v_fibra_max
            USING ERRCODE = 'check_violation';
    END IF;

    -- ── Roll validations (only when componentes provided) ────────────────────
    IF p_partida->'componentes' IS NOT NULL AND jsonb_array_length(p_partida->'componentes') > 0 THEN

        -- Stock availability: ubicacion derived from item_movimientos (rolls are unsplittable)
        WITH solicitado AS (
            SELECT (c->>'lote_id')::int      AS lote_id,
                   (c->>'cantidad')::numeric  AS cantidad
            FROM jsonb_array_elements(p_partida->'componentes') c
        )
        SELECT jsonb_agg(jsonb_build_object(
            'lote_id',            s.lote_id,
            'cantidad_requerida', s.cantidad,
            'saldo_disponible',   COALESCE(sa.cantidad_disponible, 0)
        ))
        INTO v_error_payload
        FROM solicitado s
        LEFT JOIN inventario.vw_stock_lotes sa ON sa.lote_id = s.lote_id
        WHERE COALESCE(sa.cantidad_disponible, 0) < s.cantidad;

        IF v_error_payload IS NOT NULL THEN
            RAISE EXCEPTION 'Stock insuficiente para reservar los rollos'
                USING DETAIL = v_error_payload::text;
        END IF;

        -- Composición: cada rollo asignado debe pertenecer al grupo de la partida.
        -- Reemplaza la antigua igualdad contra grupo_articulo_id: misma severidad,
        -- pero expresable para lotes mezclados — un grupo con varios miembros acepta
        -- rollos de cualquiera de ellos, y sigue rechazando telas ajenas al grupo.
        IF EXISTS (
            SELECT 1
            FROM jsonb_array_elements(p_partida->'componentes') c
            JOIN inventario.lote l      ON l.id  = (c->>'lote_id')::int
            JOIN item_rollo_detalle ird ON ird.item_id = l.item_id
            JOIN articulo a             ON a.id   = ird.articulo_id
            WHERE NOT EXISTS (
                SELECT 1 FROM grupo_articulo_miembro gm
                WHERE gm.grupo_articulo_id = v_grupo
                  AND gm.articulo_id       = a.id
            )
        ) THEN
            RAISE EXCEPTION 'Los rollos asignados no pertenecen al grupo de artículo de la partida'
                USING ERRCODE = 'check_violation';
        END IF;

        -- Double-booking: roll must not be reserved in another active order
        IF EXISTS (
            SELECT 1
            FROM jsonb_array_elements(p_partida->'componentes') c
            JOIN mes.partida_componente pc ON pc.lote_id  = (c->>'lote_id')::int
            JOIN mes.partida pr            ON pr.id       = pc.partida_id
            WHERE pc.lote_id IS NOT NULL
              AND pr.estado_produccion NOT IN ('CANCELADA', 'TECO', 'CERRADA')
        ) THEN
            RAISE EXCEPTION 'Uno o más rollos ya están reservados en otra orden activa'
                USING ERRCODE = 'check_violation';
        END IF;

    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('crear_partida', v_usr_id, p_partida);

    -- ── Header ────────────────────────────────────────────────────────────────
    INSERT INTO mes.partida (
        prioridad_id, tercero_id, tenido_id, grupo_articulo_id, fibra,
        malla, rendimiento, ancho, color_x_cliente_id, flg_antipilling, flg_doble_bolsa,
        fecha_acordada, observacion
    )
    VALUES (
        (p_partida->>'prioridad_id')::int,
        (p_partida->>'tercero_id')::int,
        (p_partida->>'tenido_id')::int,
        v_grupo,
        v_fibra,
        p_partida->>'malla',
        p_partida->>'rendimiento',
        p_partida->>'ancho',
        (p_partida->>'color_x_cliente_id')::int,
        COALESCE((p_partida->>'flg_antipilling')::boolean, false),
        COALESCE((p_partida->>'flg_doble_bolsa')::boolean, false),
        (p_partida->>'fecha_acordada')::date,
        p_partida->>'observacion'
    )
    RETURNING id INTO v_partida_id;

    -- ── Planned items / quantities ────────────────────────────────────────────
    INSERT INTO mes.partida_detalle(partida_id, item_id, cantidad, unidad_id)
    SELECT v_partida_id,
           (u->>'item_id')::int,
           (u->>'cantidad')::numeric,
           (u->>'unidad_id')::int
    FROM jsonb_array_elements(p_partida->'partida_detalles') u;

    -- ── Steps (optional at creation; add later via actualizar_pasos_partida) ──
    IF p_partida->'pasos' IS NOT NULL AND jsonb_array_length(p_partida->'pasos') > 0 THEN
        -- Machine is assigned later on the scheduling board (mes.programacion), not here.
        -- Bath ratio lives on programacion (machine-coupled), not on paso.
        -- Backend computes secuencia from array position to avoid frontend desync bugs.
        INSERT INTO mes.partida_paso(
            partida_id, secuencia, operacion_id,
            receta_id,
            ph_objetivo, temperatura_objetivo, tiempo_estandar
        )
        SELECT
            v_partida_id,
            (ROW_NUMBER() OVER ()) * 10,
            (p->>'operacion_id')::smallint,
            (p->>'receta_id')::int,
            (p->>'ph_objetivo')::numeric,
            (p->>'temperatura_objetivo')::numeric,
            (p->>'tiempo_estandar')::int
        FROM jsonb_array_elements(p_partida->'pasos') WITH ORDINALITY AS t(p, idx);
    END IF;

    -- ── Roll reservations (optional at creation; validated above if present) ──
    IF p_partida->'componentes' IS NOT NULL AND jsonb_array_length(p_partida->'componentes') > 0 THEN

        -- Per-item roll count guard: submitted rolls per item_id must not exceed partida_detalle.cantidad.
        -- Also catches rolls whose item has no partida_detalle entry (unplanned item).
        SELECT l.item_id, COUNT(*)::int, pd.cantidad
        INTO v_overflow_item_id, v_rollos_submitted, v_cantidad_planificada
        FROM jsonb_array_elements(p_partida->'componentes') c
        JOIN inventario.lote l ON l.id = (c->>'lote_id')::int
        LEFT JOIN mes.partida_detalle pd ON pd.item_id = l.item_id
                                        AND pd.partida_id = v_partida_id
        WHERE (c->>'lote_id') IS NOT NULL
        GROUP BY l.item_id, pd.cantidad
        HAVING COUNT(*) > COALESCE(pd.cantidad, 0)
        LIMIT 1;

        IF v_overflow_item_id IS NOT NULL THEN
            RAISE EXCEPTION
                'El ítem % tiene % rollos asignados pero solo % están planificados.',
                v_overflow_item_id, v_rollos_submitted, COALESCE(v_cantidad_planificada, 0)
                USING ERRCODE = 'check_violation';
        END IF;

        INSERT INTO mes.partida_componente(partida_id, lote_id, cantidad_reservada)
        SELECT v_partida_id,
               (c->>'lote_id')::int,
               (c->>'cantidad')::numeric
        FROM jsonb_array_elements(p_partida->'componentes') c
        WHERE (c->>'lote_id') IS NOT NULL;

        -- Migration 38 §5(a): scope rows for the paso×rollo matrix. Both pasos
        -- and componentes are settled by this point in the function.
        PERFORM mes.sincronizar_alcance_pasos(v_partida_id);
    END IF;

    -- -- ── Auto-request recipe if no live recipe exists for this spec ────────────
    -- PERFORM receta.solicitar_si_ausente(v_partida_id);

    -- ── Notify plant staff ────────────────────────────────────────────────────
    INSERT INTO notification.notifications(user_id, title, body, tipo, payload)
    SELECT ur.user_id,
           'Nueva Orden de Producción',
           COALESCE(
               (SELECT COALESCE(nombre, 'Usuario desconocido') || ' ' || apellido
                FROM usuario WHERE id = v_usr_id),
               'sistema'
           ) || ' creó la orden de producción #' || v_partida_id,
           'info',
           jsonb_build_object('objeto_tipo', 'partida', 'partida_id', v_partida_id)
    FROM iam.user_rol ur
    LEFT JOIN usuario p ON p.id = ur.user_id
    LEFT JOIN iam.rol r ON ur.rol_id = r.id
    WHERE r.code IN ('jefe_planta', 'compras')
      AND v_usr_id <> ur.user_id;

    PERFORM mes.actualizar_estado_partida(v_partida_id);

    RETURN jsonb_build_object(
        'partida_id', v_partida_id,
        'message',    format('Orden de producción #%s creada correctamente.', v_partida_id)
    );

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;
        RAISE LOG 'Error in crear_partida - User: %, Params: %, Error: %, Detail: %',
                  v_usr_id, p_partida::TEXT, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION mes.crear_partida(p_partida jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.crear_plantilla(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.crear_plantilla(p_plantilla jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'inventario', 'doc', 'mes'
    AS $$
DECLARE
    v_message   text;
    v_detail    text;
    v_hint      text;
    v_context   text;
    v_sqlstate  text;
    v_plantilla_id   INT;
    v_tipo_codigo text;
    v_usr_id int := get_user_id();
BEGIN
    IF NOT jwt_has_permission('produccion.configurar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.configurar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

 INSERT INTO logs_api(function_name, user_id, params)
        VALUES ('crear_plantilla', v_usr_id, p_plantilla);

INSERT INTO ruta_plantilla (nombre)
    SELECT 
        p_plantilla->>'nombre'
    RETURNING id INTO v_plantilla_id;

INSERT INTO ruta_plantilla_detalle (ruta_plantilla_id, operacion_id, secuencia, ph, temperatura, tiempo_estandar)
    SELECT v_plantilla_id,
           (detalle->>'operacion_id')::INT,
           (detalle->>'secuencia')::SMALLINT,
           (detalle->>'ph')::NUMERIC(4,2),
           (detalle->>'temperatura')::NUMERIC(5,2),
           (detalle->>'tiempo_estandar')::INT
           FROM jsonb_array_elements(p_plantilla->'plantilla_detalles') AS detalle;

INSERT INTO notification.notifications(user_id,title,body,tipo,payload)
SELECT ur.user_id,'Nueva Plantilla Creada', COALESCE((SELECT COALESCE(nombre,'Usuario desconocido') || ' ' || apellido FROM usuario WHERE id=v_usr_id),'sistema') || ' creó una nueva plantilla', 'info',jsonb_build_object('objeto_tipo','plantilla','plantilla_id',v_plantilla_id)
FROM iam.user_rol ur LEFT JOIN usuario p ON p.id=ur.user_id
LEFT JOIN iam.rol r ON ur.rol_id=r.id
WHERE r.code IN ('jefe_planta','compras') AND v_usr_id<>ur.user_id;
   RETURN format('Plantilla con ID %s creada correctamente.', v_plantilla_id);
 EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;

        RAISE LOG 'Error in crear_plantilla - User: %, Params: %, Error: %, Detail: %',
                  v_usr_id, p_plantilla::TEXT, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION mes.crear_plantilla(p_plantilla jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.crear_reproceso(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.crear_reproceso(p_partida_id bigint, p_datos jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'mes', 'inventario'
    AS $$
DECLARE
    v_message   text;
    v_detail    text;
    v_hint      text;
    v_context   text;
    v_sqlstate  text;
    v_usr_id    INT := get_user_id();
    v_origen    mes.partida%ROWTYPE;
    v_child_id  BIGINT;
    v_root_id   BIGINT;
    v_lotes     JSONB;
BEGIN
    IF NOT jwt_has_permission('produccion.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    v_lotes := p_datos->'lotes';

    IF v_lotes IS NULL OR jsonb_array_length(v_lotes) = 0 THEN
        RAISE EXCEPTION 'Se requiere al menos un lote para crear reproceso.';
    END IF;

    SELECT * INTO v_origen
    FROM mes.partida
    WHERE id = p_partida_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Partida % no encontrada.', p_partida_id;
    END IF;

    IF v_origen.estado_produccion NOT IN ('EN_PRODUCCION','TECO') THEN
        RAISE EXCEPTION 'Reproceso requiere partida EN_PRODUCCION o TECO. Estado actual: %.',
            v_origen.estado_produccion;
    END IF;

    -- Flat rework topology: all children link to the original root.
    -- If p_partida_id is itself a rework child, the new sibling links to the same root.
    v_root_id := COALESCE(v_origen.partida_origen_id, v_origen.id);

    -- Validate every supplied lote against the whole family (two valid sources):
    --   A) input rolls already in partida_componente of any family member
    --   B) output lotes (PROD_ING) from paso_ejecucion of any family member (post-final-paso re-dye)
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_lotes) e
        WHERE NOT (
            EXISTS (
                SELECT 1 FROM mes.partida_componente pc
                JOIN mes.partida p ON p.id = pc.partida_id
                WHERE pc.lote_id = (e.value::TEXT)::INT
                  AND (p.id = v_root_id OR p.partida_origen_id = v_root_id)
            )
            OR
            EXISTS (
                SELECT 1 FROM inventario.lote l
                JOIN mes.partida_paso_ejecucion pe
                    ON pe.id = l.documento_id AND l.documento_tipo = 'partida_paso_ejecucion'
                JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
                WHERE l.id = (e.value::TEXT)::INT
                  AND pp.partida_id IN (
                      SELECT id FROM mes.partida
                      WHERE id = v_root_id OR partida_origen_id = v_root_id
                  )
                  AND l.fyh_elm IS NULL
            )
        )
    ) THEN
        RAISE EXCEPTION 'Uno o más lotes no pertenecen a la familia de la partida %.', v_root_id;
    END IF;

    -- Create rework child. Immutable specs always inherited; fecha_acordada overridable.
    -- grupo_articulo_id se hereda del origen igual que el resto de la identidad de
    -- sustrato (migración 32: la columna es NOT NULL, así que omitirla rompe el
    -- reproceso). grupo_articulo_id NO se escribe: lo deriva el trigger
    -- trg_bi_partida_derive_grupo_articulo a partir del grupo.
    INSERT INTO mes.partida (
        partida_origen_id, prioridad_id, tercero_id, tenido_id,
        color_x_cliente_id, grupo_articulo_id, fibra, malla, rendimiento,
        ancho, flg_antipilling, fecha_acordada, estado_produccion, usr_cre
    )
    VALUES (
        v_root_id, v_origen.prioridad_id, v_origen.tercero_id, v_origen.tenido_id,
        v_origen.color_x_cliente_id, v_origen.grupo_articulo_id, v_origen.fibra,
        v_origen.malla, v_origen.rendimiento, v_origen.ancho, v_origen.flg_antipilling,
        COALESCE((p_datos->>'fecha_acordada')::date, v_origen.fecha_acordada),
        'CREADA', v_usr_id
    )
    RETURNING id INTO v_child_id;

    -- Paso structure: caller-specified (flexible subset + corrective recipe), or no pasos
    -- (blank draft — planner adds steps after creation). Rework children intentionally skip
    -- PLANIFICADA/PROGRAMADA — iniciar_paso has no estado_produccion guard so execution
    -- can begin from CREADA immediately once steps are defined.
    IF p_datos->'pasos' IS NOT NULL AND jsonb_array_length(p_datos->'pasos') > 0 THEN
        INSERT INTO mes.partida_paso (
            partida_id, secuencia, operacion_id,
            receta_id, tiempo_estandar, ph_objetivo, temperatura_objetivo,
            usr_cre
        )
        SELECT
            v_child_id,
            COALESCE((e->>'secuencia')::smallint, rn::smallint),
            (e->>'operacion_id')::smallint,
            (e->>'receta_id')::int,
            (e->>'tiempo_estandar')::int,
            (e->>'ph_objetivo')::numeric,
            (e->>'temperatura_objetivo')::numeric,
            v_usr_id
        FROM jsonb_array_elements(p_datos->'pasos') WITH ORDINALITY AS arr(e, rn);
    -- If no pasos provided, child is created as a blank draft — planner adds steps explicitly.
    END IF;


    -- Auto-create partida_detalle for the rework child.
    -- Mirrors root's item structure; cantidad = rolls being reworked (one roll = one billing unit).
    INSERT INTO mes.partida_detalle (partida_id, item_id, cantidad, unidad_id, usr_cre)
    SELECT v_child_id, pd.item_id, COUNT(l.id), pd.unidad_id, v_usr_id
    FROM mes.partida_detalle pd
    LEFT JOIN inventario.lote l ON l.item_id = pd.item_id
        AND l.id IN (SELECT (e.value::TEXT)::INT FROM jsonb_array_elements(v_lotes) e)
    WHERE pd.partida_id = v_root_id
    GROUP BY pd.item_id, pd.unidad_id
    HAVING COUNT(l.id) > 0;

    -- Case A: move input rolls (already in partida_componente of any family member).
    UPDATE mes.partida_componente
    SET partida_id = v_child_id
    WHERE lote_id IN (SELECT (e.value::TEXT)::INT FROM jsonb_array_elements(v_lotes) e)
      AND partida_id IN (
          SELECT id FROM mes.partida
          WHERE id = v_root_id OR partida_origen_id = v_root_id
      );

    -- Reset quality state so rolls enter the rework cycle as pending inspection.
    -- Applies to all reworked lotes (both input rolls and output rolls being re-dyed).
    -- The previous QC result is preserved in calidad.inspeccion; estado_calidad reflects
    -- the current production context, not historical determinations.
    UPDATE inventario.lote
    SET estado_calidad = 'PENDIENTE'
    WHERE id IN (SELECT (e.value::TEXT)::INT FROM jsonb_array_elements(v_lotes) e);

    -- Case B: register output lotes as input for the rework child (post-final-paso re-dye).
    -- These PROD_ING lotes have no partida_componente entry yet.
    INSERT INTO mes.partida_componente (partida_id, lote_id, cantidad_reservada, usr_cre)
    SELECT v_child_id, l.id, l.cantidad, v_usr_id
    FROM inventario.lote l
    WHERE l.id IN (SELECT (e.value::TEXT)::INT FROM jsonb_array_elements(v_lotes) e)
      AND l.documento_tipo = 'partida_paso_ejecucion'
      AND NOT EXISTS (
          SELECT 1 FROM mes.partida_componente pc
          WHERE pc.lote_id = l.id AND pc.partida_id = v_child_id
      );

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('crear_reproceso', v_usr_id,
            p_datos || jsonb_build_object('partida_id', p_partida_id));

    PERFORM mes.actualizar_estado_partida(v_child_id);

    RETURN jsonb_build_object(
        'reproceso_partida_id', v_child_id,
        'partida_origen_id',    v_root_id,
        'lotes_movidos',        jsonb_array_length(v_lotes),
        'message', format('Reproceso %s creado desde partida %s con %s rollo(s).',
                          v_child_id, p_partida_id, jsonb_array_length(v_lotes))
    );

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;
        RAISE LOG 'Error in crear_reproceso - User: %, Partida: %, Error: %, Detail: %',
                  v_usr_id, p_partida_id, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION mes.crear_reproceso(p_partida_id bigint, p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.finalizar_lavado_maquina(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.finalizar_lavado_maquina(p_id bigint, p_datos jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes', 'receta'
    AS $$
DECLARE
    v_usr_id            INT := get_user_id();
    v_lavado            mes.lavado_maquina%ROWTYPE;
    v_egr_tipo_id       SMALLINT;
    v_motivo_id         SMALLINT;
    v_doc_movimiento_id BIGINT;
    v_insumos           JSONB;
    v_consumos          JSONB;
    v_error_payload     JSONB;
    v_fyh_fin           TIMESTAMPTZ;
BEGIN
    IF NOT jwt_has_permission('produccion.ejecutar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.ejecutar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO v_lavado FROM mes.lavado_maquina WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'lavado_maquina id=% no encontrado.', p_id;
    END IF;

    -- PENDIENTE accepted for backdated transcription (fyh_inicio supplied in payload).
    -- EN_PROCESO is the normal live path.
    IF v_lavado.estado NOT IN ('EN_PROCESO', 'PENDIENTE') THEN
        RAISE EXCEPTION 'lavado_maquina id=% en estado % — se esperaba EN_PROCESO o PENDIENTE.', p_id, v_lavado.estado;
    END IF;

    v_fyh_fin := COALESCE((p_datos->>'fyh_fin')::TIMESTAMPTZ, now());

    -- Aggregate insumos across all recipe pasos, summed by item (fixed quantities, no scaling)
    SELECT jsonb_agg(jsonb_build_object('item_id', item_id, 'cantidad', cantidad))
    INTO v_insumos
    FROM (
        SELECT lmpi.item_id, SUM(lmpi.cantidad) AS cantidad
        FROM receta.lavado_maquina_paso     lmp
        JOIN receta.lavado_maquina_paso_insumo lmpi ON lmpi.paso_id = lmp.id
        WHERE lmp.receta_id = v_lavado.receta_id
        GROUP BY lmpi.item_id
    ) agg;

    IF v_insumos IS NOT NULL THEN
        -- Stock check
        WITH consumos AS (
            SELECT (i->>'item_id')::INT    AS item_id,
                   (i->>'cantidad')::NUMERIC AS cantidad
            FROM jsonb_array_elements(v_insumos) i
        )
        SELECT jsonb_agg(jsonb_build_object(
            'item_id',           c.item_id,
            'item_nombre',       it.nombre,
            'saldo_disponible',  COALESCE(sg.cantidad_total, 0),
            'cantidad_requerida', c.cantidad
        ))
        INTO v_error_payload
        FROM consumos c
        LEFT JOIN inventario.vw_stock_items sg ON sg.item_id = c.item_id
        JOIN item it ON it.id = c.item_id
        WHERE COALESCE(sg.cantidad_total, 0) < c.cantidad;

        IF v_error_payload IS NOT NULL THEN
            RAISE EXCEPTION 'Stock insuficiente para lavado_maquina id=%', p_id
    USING DETAIL = v_error_payload::text;
        END IF;

        SELECT id INTO v_egr_tipo_id
        FROM inventario.item_movimiento_tipo WHERE codigo = 'PROD_CONSUMO';

        SELECT id INTO v_motivo_id
        FROM inventario.item_movimiento_motivo
        WHERE item_movimiento_tipo_id = v_egr_tipo_id AND codigo = 'LAVADO_MAQUINA';

        v_consumos := mes.calcular_fifo(v_insumos);
        SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

        INSERT INTO inventario.item_movimientos(
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, cantidad, precio_unitario,
            documento_tipo, documento_id, motivo_id, fecha_hora
        )
        SELECT
            v_doc_movimiento_id,
            (c->>'item_id')::INT,
            (c->>'lote_id')::INT,
            v_egr_tipo_id,
            (c->>'ubicacion_id')::INT,
            (c->>'cantidad')::NUMERIC,
            (SELECT iv.precio_promedio FROM inventario.item_valoracion iv
             WHERE iv.item_id = (c->>'item_id')::INT),
            'lavado_maquina',
            p_id,
            v_motivo_id,
            v_fyh_fin
        FROM jsonb_array_elements(v_consumos) c;
    END IF;

    UPDATE mes.lavado_maquina SET
        estado      = 'COMPLETADO',
        fyh_inicio  = COALESCE(fyh_inicio, (p_datos->>'fyh_inicio')::TIMESTAMPTZ, now()),
        fyh_fin     = v_fyh_fin,
        nota        = COALESCE(p_datos->>'nota', nota),
        usr_mod     = v_usr_id,
        fyh_mod     = now()
    WHERE id = p_id;

    UPDATE mes.maquina SET
        ultimo_mantenimiento = v_fyh_fin,
        usr_mod = v_usr_id,
        fyh_mod = now()
    WHERE id = v_lavado.maquina_id;
END;$$;


ALTER FUNCTION mes.finalizar_lavado_maquina(p_id bigint, p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.finalizar_paso(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.finalizar_paso(p_paso_id bigint, p_datos jsonb DEFAULT '{}'::jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'mes'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int := get_user_id();
    v_partida_id        bigint;
    v_maquina_id        int;
    v_ejecucion_id      bigint;
    v_op_nombre         text;
    v_op_codigo         text;
    v_rollos_asignados  int;
    v_prod_result       text;
    v_variance_payload  jsonb;
    v_peso_kg           numeric;
    v_flg_ultimo        boolean;
BEGIN
    IF NOT jwt_has_permission('produccion.ejecutar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.ejecutar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- Fetch paso info and its active execution run in one shot
    SELECT pp.partida_id, o.nombre, o.codigo, pe.id, pe.maquina_id
    INTO v_partida_id, v_op_nombre, v_op_codigo, v_ejecucion_id, v_maquina_id
    FROM mes.partida_paso pp
    JOIN mes.operacion o ON o.id = pp.operacion_id
    JOIN mes.partida_paso_ejecucion pe ON pe.partida_paso_id = pp.id AND pe.estado = 'EN_PROCESO'
    WHERE pp.id = p_paso_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Paso #% no encontrado o sin ejecución EN_PROCESO.', p_paso_id;
    END IF;

    -- flg_ultimo: true when no other non-omitted paso of this partida has a higher secuencia.
    -- Mirrors the derivation in get_partida_detalle (mes.sql ~3705) — kept in sync manually,
    -- there is no stored column for this.
    SELECT NOT EXISTS (
        SELECT 1
        FROM mes.partida_paso pp3
        WHERE pp3.partida_id = v_partida_id
          AND pp3.secuencia > (SELECT pp4.secuencia FROM mes.partida_paso pp4 WHERE pp4.id = p_paso_id)
          AND NOT EXISTS (
              SELECT 1 FROM mes.partida_paso_ejecucion pe3
              WHERE pe3.partida_paso_id = pp3.id AND pe3.estado = 'OMITIDO'
          )
    ) INTO v_flg_ultimo;

    -- Guard: the last step of a partida must not close rolls as processed without producing
    -- output for them. Silently skipping registrar_produccion here (e.g. a frontend bug that
    -- omits ubicacion_id) previously let rolls get marked COMPLETADO with no output lote and
    -- no backflush — kg vanished from the pipeline with no error raised anywhere.
    -- Fully-scrapped runs are exempt: cantidad_scrap covering the whole submitted quantity
    -- legitimately produces zero output.
    IF v_flg_ultimo
       AND (p_datos->>'cantidad_rollos') IS NOT NULL
       AND (p_datos->>'cantidad_rollos')::NUMERIC > COALESCE((p_datos->>'cantidad_scrap')::NUMERIC, 0)
       AND COALESCE(jsonb_array_length(p_datos->'produccion'->'output'), 0) = 0
    THEN
        RAISE EXCEPTION 'Paso #% es el último de la partida: debe registrar producción (output) para los rollos no descartados por scrap.', p_paso_id
            USING ERRCODE = 'check_violation';
    END IF;

    -- Cantidad guard: existing COMPLETADO runs + this submission must not exceed assigned rolls.
    -- Mirrors the same guard in the backfill function. Skipped when cantidad is not submitted.
    IF (p_datos->>'cantidad_rollos') IS NOT NULL THEN
        SELECT COUNT(*) INTO v_rollos_asignados
        FROM mes.partida_componente
        WHERE partida_id = v_partida_id AND lote_id IS NOT NULL;

        IF (p_datos->>'cantidad_rollos')::NUMERIC +
           COALESCE((
               SELECT SUM(pe2.cantidad_rollos)
               FROM mes.partida_paso_ejecucion pe2
               WHERE pe2.partida_paso_id = p_paso_id
                 AND pe2.estado = 'COMPLETADO'
           ), 0) > v_rollos_asignados
        THEN
            RAISE EXCEPTION 'La cantidad (%) excede los % rollos asignados a la partida.',
                (p_datos->>'cantidad_rollos')::NUMERIC, v_rollos_asignados;
        END IF;
    END IF;

    -- Process recipe consumptions if provided
    IF p_datos->'consumos' IS NOT NULL AND jsonb_array_length(p_datos->'consumos') > 0 THEN
        PERFORM mes.registrar_consumo_paso(p_paso_id, p_datos->'consumos');
    END IF;

    -- Process matizado corrections — same consumo path, motivo resolved internally
    IF p_datos->'matizados' IS NOT NULL AND jsonb_array_length(p_datos->'matizados') > 0 THEN
        PERFORM mes.registrar_consumo_paso(
            p_paso_id,
            (SELECT jsonb_agg(item || jsonb_build_object('motivo_id', m.id))
             FROM jsonb_array_elements(p_datos->'matizados') AS item
             CROSS JOIN (SELECT id FROM inventario.item_movimiento_motivo WHERE codigo = 'MATIZADO') m)
        );
    END IF;

    -- Variance alert: actual consumptions vs partida_componente chemical reservations (>10%)
    SELECT jsonb_agg(jsonb_build_object(
        'item_id',       pc.item_id,
        'item_nombre',   it.nombre,
        'planificado',   pc.cantidad_reservada,
        'real',          COALESCE(actual.total, 0),
        'variacion_pct', ROUND(
            (ABS(COALESCE(actual.total, 0) - pc.cantidad_reservada)
             / NULLIF(pc.cantidad_reservada, 0)) * 100, 2
        )
    ))
    INTO v_variance_payload
    FROM mes.partida_componente pc
    JOIN item it ON it.id = pc.item_id
    LEFT JOIN (
        SELECT item_id, SUM(ABS(cantidad)) AS total
        FROM inventario.item_movimientos
        WHERE documento_tipo = 'partida_paso_ejecucion'
          AND documento_id = v_ejecucion_id
        GROUP BY item_id
    ) actual ON actual.item_id = pc.item_id
    WHERE pc.partida_paso_id = p_paso_id
      AND pc.item_id IS NOT NULL
      AND pc.cantidad_reservada > 0
      AND ABS(COALESCE(actual.total, 0) - pc.cantidad_reservada)
          / NULLIF(pc.cantidad_reservada, 0) > 0.10;

    IF v_variance_payload IS NOT NULL THEN
        INSERT INTO notification.notifications(user_id, title, body, tipo, payload)
        SELECT ur.user_id,
               'Variación de consumo en paso',
               format('Paso %s (#%s): variación > 10%% respecto a receta.', v_op_nombre, p_paso_id),
               'warning',
               jsonb_build_object('objeto_tipo','partida_paso','paso_id', p_paso_id,
                                  'partida_id', v_partida_id, 'variaciones', v_variance_payload)
        FROM iam.user_rol ur
        JOIN iam.rol r ON ur.rol_id = r.id
        WHERE r.code IN ('jefe_planta','supervisor_produccion');
    END IF;

    -- Register production output if caller submitted it (TENIDO step)
    -- p_datos->'produccion' shape: {output: [...], ubicacion_id: N, peso_rollos?: N, peso_rib?: N}
    IF (p_datos->'produccion'->'output') IS NOT NULL
       AND jsonb_array_length(p_datos->'produccion'->'output') > 0 THEN
        v_prod_result := mes.registrar_produccion(v_ejecucion_id, p_datos->'produccion');
    END IF;

    -- Snapshot peso_kg at close time: immune to future reproceso splits.
    -- Final step (registrar_produccion called): use output lote weights.
    -- Non-final step: prorate total input roll weight by this run's roll fraction.
    SELECT COALESCE(
        (SELECT SUM(l.cantidad) FROM inventario.lote l
         WHERE l.documento_tipo = 'partida_paso_ejecucion'
           AND l.documento_id   = v_ejecucion_id
           AND l.fyh_elm IS NULL),
        (SELECT ROUND(
             SUM(l.cantidad)
             * COALESCE((p_datos->>'cantidad_rollos')::numeric, MAX(totals.cnt))
             / NULLIF(MAX(totals.cnt), 0),
             4)
         FROM mes.partida_componente pc
         JOIN inventario.lote l ON l.id = pc.lote_id
         CROSS JOIN (
             SELECT COUNT(*)::numeric AS cnt
             FROM mes.partida_componente
             WHERE partida_id = v_partida_id AND lote_id IS NOT NULL
         ) totals
         WHERE pc.partida_id = v_partida_id AND pc.lote_id IS NOT NULL)
    ) INTO v_peso_kg;

    -- Close the execution run with actual measured params.
    -- fyh_fin accepts a historical timestamp for backfill; live callers omit it → NOW().
    UPDATE mes.partida_paso_ejecucion
    SET estado             = 'COMPLETADO',
        fyh_fin            = COALESCE((p_datos->>'fyh_fin')::TIMESTAMPTZ, NOW()),
        ph_real            = COALESCE((p_datos->>'ph_real')::NUMERIC,            ph_real),
        temperatura_real   = COALESCE((p_datos->>'temperatura_real')::NUMERIC,   temperatura_real),
        relacion_bano_real = COALESCE((p_datos->>'relacion_bano_real')::NUMERIC, relacion_bano_real),
        cantidad_rollos    = COALESCE((p_datos->>'cantidad_rollos')::NUMERIC,           cantidad_rollos),
        cantidad_scrap     = COALESCE((p_datos->>'cantidad_scrap')::NUMERIC,     cantidad_scrap),
        notas              = COALESCE(p_datos->>'notas',                         notas),
        ancho_entrada      = COALESCE((p_datos->>'ancho_entrada')::NUMERIC,      ancho_entrada),
        ancho_salida       = COALESCE((p_datos->>'ancho_salida')::NUMERIC,       ancho_salida),
        velocidad          = COALESCE((p_datos->>'velocidad')::NUMERIC,          velocidad),
        entrada            = COALESCE((p_datos->>'entrada')::NUMERIC,            entrada),
        salida             = COALESCE((p_datos->>'salida')::NUMERIC,             salida),
        rendimiento        = COALESCE((p_datos->>'rendimiento')::NUMERIC,        rendimiento),
        pases              = COALESCE((p_datos->>'pases')::SMALLINT,             pases),
        malla_alimentacion = COALESCE((p_datos->>'malla_alimentacion')::NUMERIC, malla_alimentacion),
        peso_kg            = v_peso_kg,
        usr_mod            = v_usr_id,
        fyh_mod            = NOW()
    WHERE id = v_ejecucion_id;

    -- Paso is COMPLETADO only when cumulative confirmed quantity covers all assigned rolls.
    -- Multiple ejecuciones per paso are normal (one machine run per batch subset).
    UPDATE mes.partida_paso
    SET estado = CASE
            WHEN (
                SELECT COALESCE(SUM(pe.cantidad_rollos) FILTER (WHERE pe.estado = 'COMPLETADO'), 0)
                FROM mes.partida_paso_ejecucion pe
                WHERE pe.partida_paso_id = p_paso_id
            ) >= (
                SELECT COUNT(*)
                FROM mes.partida_componente pc
                WHERE pc.partida_id = v_partida_id
                  AND pc.lote_id IS NOT NULL
            ) THEN 'COMPLETADO'::partida_paso_estado_enum
            ELSE 'EN_PROCESO'::partida_paso_estado_enum
        END,
        fyh_mod = NOW()
    WHERE id = p_paso_id;

    -- TERMOFIJADO extension: fields with no cross-operation meaning.
    -- ancho_entrada / ancho_salida / temperatura_real are on the base update above.
    IF v_op_codigo = 'TERMOFIJADO' THEN
        INSERT INTO mes.partida_paso_ejecucion_termofijado (
            ejecucion_id,
            ancho_marco, vel_maquina, vel_alimentacion,
            densidad_entrada, densidad_salida,
            lm, galga,
            usr_cre, fyh_cre
        ) VALUES (
            v_ejecucion_id,
            (p_datos->>'ancho_marco')::numeric,
            (p_datos->>'vel_maquina')::numeric,
            (p_datos->>'vel_alimentacion')::numeric,
            (p_datos->>'densidad_entrada')::numeric,
            (p_datos->>'densidad_salida')::numeric,
            (p_datos->>'lm')::numeric,
            (p_datos->>'galga')::numeric,
            v_usr_id, NOW()
        )
        ON CONFLICT (ejecucion_id) DO UPDATE SET
            ancho_marco      = EXCLUDED.ancho_marco,
            vel_maquina      = EXCLUDED.vel_maquina,
            vel_alimentacion = EXCLUDED.vel_alimentacion,
            densidad_entrada = EXCLUDED.densidad_entrada,
            densidad_salida  = EXCLUDED.densidad_salida,
            lm               = EXCLUDED.lm,
            galga            = EXCLUDED.galga,
            usr_mod          = v_usr_id,
            fyh_mod          = NOW();
    END IF;

    -- Release machine
    IF v_maquina_id IS NOT NULL THEN
        UPDATE mes.maquina SET estado_actual = 'espera'
        WHERE id = v_maquina_id;
    END IF;

    PERFORM mes.actualizar_estado_partida(v_partida_id);

    INSERT INTO notification.notifications(user_id, title, body, tipo, payload)
    SELECT ur.user_id, 'Paso Completado',
           COALESCE((SELECT COALESCE(nombre,'Usuario desconocido') || ' ' || apellido
                     FROM usuario WHERE id = v_usr_id), 'sistema')
           || format(' completó el paso %s (orden #%s)', v_op_nombre, v_partida_id), 'info',
           jsonb_build_object('objeto_tipo','partida_paso','paso_id', p_paso_id, 'partida_id', v_partida_id)
    FROM iam.user_rol ur LEFT JOIN iam.rol r ON ur.rol_id = r.id
    WHERE r.code IN ('jefe_planta','supervisor_produccion') AND v_usr_id <> ur.user_id;

    RETURN format('Paso %s (#%s) completado.%s', v_op_nombre, p_paso_id,
                  CASE WHEN v_prod_result IS NOT NULL THEN ' ' || v_prod_result ELSE '' END);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in finalizar_paso - User: %, ID: %, Error: %', v_usr_id, p_paso_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION mes.finalizar_paso(p_paso_id bigint, p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.fn_trg_check_cantidad_rollos_asignados()
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.fn_trg_check_cantidad_rollos_asignados() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'mes', 'public'
    AS $$
DECLARE
    v_partida_id  BIGINT;
    v_asignados   NUMERIC;
    v_confirmados NUMERIC;
BEGIN
    -- Only the confirmed (COMPLETADO) quantity counts against the roll pool;
    -- EN_PROCESO runs are in-flight and not yet a committed consumption.
    IF NEW.estado <> 'COMPLETADO' OR NEW.cantidad_rollos IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT partida_id INTO v_partida_id
    FROM mes.partida_paso
    WHERE id = NEW.partida_paso_id;

    SELECT COUNT(*) INTO v_asignados
    FROM mes.partida_componente
    WHERE partida_id = v_partida_id AND lote_id IS NOT NULL;

    -- id IS DISTINCT FROM NEW.id excludes this row on UPDATE; on INSERT (BEFORE
    -- trigger, identity not yet assigned) NEW.id is NULL so nothing is excluded.
    SELECT COALESCE(SUM(cantidad_rollos), 0) INTO v_confirmados
    FROM mes.partida_paso_ejecucion
    WHERE partida_paso_id = NEW.partida_paso_id
      AND estado = 'COMPLETADO'
      AND id IS DISTINCT FROM NEW.id;

    IF v_confirmados + NEW.cantidad_rollos > v_asignados THEN
        RAISE EXCEPTION
            'La cantidad de rollos (%) del paso % excede los % rollos asignados a la partida.',
            NEW.cantidad_rollos, NEW.partida_paso_id, v_asignados
            USING ERRCODE = 'check_violation';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION mes.fn_trg_check_cantidad_rollos_asignados() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.fn_trg_ejecucion_receta_immutable()
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.fn_trg_ejecucion_receta_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.receta_id IS NOT NULL AND OLD.receta_id IS DISTINCT FROM NEW.receta_id THEN
        RAISE EXCEPTION 'receta_id es inmutable en partida_paso_ejecucion (id=%). La receta se fija al iniciar el paso.', OLD.id;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION mes.fn_trg_ejecucion_receta_immutable() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.fn_trg_gen_codigo_maquina()
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.fn_trg_gen_codigo_maquina() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    v_tipo_codigo TEXT;
    v_seq         INT;
BEGIN
    IF NEW.codigo IS NULL THEN
        SELECT codigo INTO v_tipo_codigo FROM mes.maquina_tipo WHERE id = NEW.maquina_tipo_id;
        SELECT COALESCE(MAX(
            CASE WHEN codigo ~ ('^' || v_tipo_codigo || '-[0-9]+$')
                 THEN (regexp_match(codigo, '[0-9]+$'))[1]::int
                 ELSE 0 END
        ), 0) + 1
        INTO v_seq
        FROM mes.maquina WHERE maquina_tipo_id = NEW.maquina_tipo_id;
        NEW.codigo := v_tipo_codigo || '-' || LPAD(v_seq::text, 3, '0');
    END IF;
    RETURN NEW;
END;
$_$;


ALTER FUNCTION mes.fn_trg_gen_codigo_maquina() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.generar_receta(bigint, integer, numeric, boolean)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.generar_receta(p_paso_id bigint, p_maquina_id integer DEFAULT NULL::integer, p_relacion_bano numeric DEFAULT NULL::numeric, p_commit boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'receta', 'mes', 'doc'
    AS $$
DECLARE
    v_receta           jsonb;
    v_receta_id        int;
    v_maquina_id       int;
    v_maq_nombre       text;
    v_maq_codigo       text;
    v_rb               numeric;  -- effective bath ratio (resolved after batch weight is known)
    v_rb_paso          numeric;  -- scheduled override (programacion.relacion_bano)
    v_rb_maquina       numeric;  -- machine standard ratio
    v_cap_min_kg       numeric;  -- machine minimum operational load (kg)
    v_peso             numeric;
    v_cantidad         numeric;
    v_cantidad_regular numeric;
    v_cantidad_rib     numeric;
    v_volumen          numeric;
    v_peso_volumen     numeric;  -- effective weight for volume calc (floored to cap_min_kg)
    v_flg_cap_minima   boolean;  -- true when batch is below machine minimum
    v_usr_id           int := get_user_id();
    v_partida_id         bigint;
    v_op_nombre        text;
    v_stock_error      jsonb;
    v_message          text;
    v_detail           text;
    v_hint             text;
    v_context          text;
    v_sqlstate         text;
    v_completado       boolean;
BEGIN
    IF NOT jwt_has_permission('produccion.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- 1. Validate paso, get receta + machine capacity data.
    -- Machine resolution (no more maquina_planificada_id — routing step carries no machine):
    --   tentative override (p_maquina_id) wins, else the scheduled machine (programacion).
    -- A caller previewing a recipe before scheduling passes p_maquina_id; committed
    -- generation reads the machine the paso is scheduled on.
    v_maquina_id := COALESCE(
        p_maquina_id,
        (SELECT maquina_id FROM mes.programacion
         WHERE actividad_tipo = 'partida_paso' AND actividad_id = p_paso_id
         ORDER BY fyh_cre DESC
         LIMIT 1)
    );

    SELECT pp.receta_id,
           prog.relacion_bano,
           m.relacion_bano, m.capacidad_min_kg,
           pp.partida_id, o.nombre
    INTO v_receta_id, v_rb_paso,
         v_rb_maquina, v_cap_min_kg,
         v_partida_id, v_op_nombre
    FROM mes.partida_paso pp
    LEFT JOIN mes.operacion o ON o.id = pp.operacion_id
    LEFT JOIN mes.maquina m   ON m.id = v_maquina_id
    LEFT JOIN LATERAL (
        SELECT relacion_bano FROM mes.programacion
        WHERE actividad_tipo = 'partida_paso'
          AND actividad_id   = p_paso_id
          AND maquina_id     = v_maquina_id
        ORDER BY fyh_cre DESC
        LIMIT 1
    ) prog ON true
    WHERE pp.id = p_paso_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Paso con ID % no encontrado.', p_paso_id;
    END IF;
    IF v_receta_id IS NULL THEN
        RAISE EXCEPTION 'Paso ID % sin receta asignada.', p_paso_id;
    END IF;
    IF v_maquina_id IS NULL THEN
        RAISE EXCEPTION 'Debe programar el paso en una máquina o indicar una máquina tentativa para generar la receta.'
            USING ERRCODE = 'P0001';
    END IF;

    -- 2. Machine info
    SELECT m.nombre, m.codigo INTO v_maq_nombre, v_maq_codigo
    FROM mes.maquina m WHERE m.id = v_maquina_id;

    -- 3. Roll aggregation (weight + count) from all components of this order
    --    Guard: all rolls must be weighed before recipe generation so that
    --    lote.cantidad reflects real weight, not the entrega-declared estimate.
    IF EXISTS (
        SELECT 1
        FROM mes.partida_componente pc
        JOIN inventario.lote l ON l.id = pc.lote_id
        WHERE pc.partida_id = v_partida_id
          AND pc.lote_id IS NOT NULL
          AND NOT EXISTS (
              SELECT 1 FROM inventario.pesaje p WHERE p.lote_id = pc.lote_id
          )
    ) THEN
        RAISE EXCEPTION 'Todos los rollos deben estar pesados antes de generar la receta.'
            USING ERRCODE = 'P0001';
    END IF;

    SELECT
        SUM(l.cantidad),
        SUM(CASE ird.flg_rib WHEN false THEN 1 ELSE 0 END),
        SUM(CASE ird.flg_rib WHEN true  THEN 1 ELSE 0 END)
    INTO v_peso, v_cantidad_regular, v_cantidad_rib
    FROM mes.partida_componente opi
    JOIN inventario.lote l    ON l.id   = opi.lote_id
    JOIN item_rollo_detalle ird ON ird.item_id = l.item_id
    WHERE opi.partida_id = v_partida_id;

    v_cantidad := COALESCE(v_cantidad_regular, 0) + COALESCE(v_cantidad_rib, 0);

    -- 4. Resolve effective bath ratio, then compute volume.
    -- Order-step override wins; otherwise use machine's configured ratio.
    -- When batch weight is below machine minimum, volume is floored to cap_min_kg * rb
    -- so the bath covers the machine drum properly — g/L chemicals scale up accordingly.
    -- % chemicals always scale on actual fabric weight (v_peso), not the floor.
    -- tentative override wins, then the scheduled custom ratio, then the machine standard
    v_rb           := COALESCE(p_relacion_bano, v_rb_paso, v_rb_maquina);
    v_flg_cap_minima := v_cap_min_kg IS NOT NULL AND v_peso < v_cap_min_kg;
    v_peso_volumen := CASE WHEN v_flg_cap_minima THEN v_cap_min_kg ELSE v_peso END;
    v_volumen      := v_peso_volumen * v_rb;

    -- 5. Build JSON
    -- pasos: chemistry steps with nested insumos (new hierarchical model)
    -- Breaking change from flat insumos[]: frontend flattens pasos[].insumos[] for consumption form
    SELECT jsonb_build_object(
        'receta_id',         pp.receta_id,
        'partida_id',        p.id,
        'partida_origen_id', p.partida_origen_id,
        'tercero_id',        p.tercero_id,
        'observacion',       p.observacion,
        'flg_doble_bolsa',   p.flg_doble_bolsa,
        'flg_antipilling',   p.flg_antipilling,
        'cliente',           cli.nombre,
        'tipo_receta',       tr.tipo_receta,
        'grupo_articulo_id', r.grupo_articulo_id,
        'grupo_articulo',     ga.nombre,
        'fibra',             r.fibra,
        'peso',              v_peso,
        'cantidad',          v_cantidad,
        'cantidad_regular',  v_cantidad_regular,
        'cantidad_rib',      v_cantidad_rib,
        'volumen',           ROUND(v_volumen::NUMERIC, 2),
        'cap_minima_aplicada', v_flg_cap_minima,
        'cap_min_kg',        v_cap_min_kg,
        'maquina',           jsonb_build_object(
                                 'id',     v_maquina_id,
                                 'codigo', v_maq_codigo,
                                 'nombre', v_maq_nombre
                             ),
        'costo_quimicos_kg', doc.fn_get_costo_receta(r.id),
        'pasos', (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'orden',        rtp.orden,
                    'operacion_id', ro.id,
                    'operacion',    ro.nombre,
                    'ph',           rtp.ph,
                    'temperatura',  rtp.temperatura,
                    'tiempo_min',   rtp.tiempo_min,
                    'nota',         rtp.nota,
                    'insumos', (
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'item_id',               rtpi.item_id,
                                'orden',                 rtpi.orden,
                                'codigo',                i.codigo,
                                'nombre',                i.nombre,
                                'cantidad',              rtpi.cantidad,
                                'medida',                iid.medida,
                                -- g/L × volume(L) and % × peso(kg) × 10 both yield GRAMS;
                                -- ÷1000 → kg (the item stock unit). 7 decimals keeps the
                                -- recipe's 4 gram-decimals after the 3-place shift (frontend ×1000 to show g).
                                'cantidad_requerida_kg', ROUND(CASE
                                    WHEN iid.medida = 'g/L' THEN rtpi.cantidad * v_volumen / 1000
                                    WHEN iid.medida = '%'   THEN rtpi.cantidad * v_peso * 10 / 1000
                                END, 7),
                                'precio_kg',             pr.precio_kg,
                                'costo_insumo',          ROUND(CASE
                                    WHEN iid.medida = 'g/L' THEN rtpi.cantidad * v_volumen / 1000
                                    WHEN iid.medida = '%'   THEN rtpi.cantidad * v_peso * 10 / 1000
                                    ELSE 0
                                END * pr.precio_kg, 4)
                            ) ORDER BY rtpi.orden
                        )
                        FROM receta.tenido_paso_insumo rtpi
                        JOIN item i                  ON i.id        = rtpi.item_id
                        JOIN item_insumo_detalle iid  ON iid.item_id = rtpi.item_id
                        LEFT JOIN LATERAL (
                            SELECT COALESCE(
                                (SELECT fpd.precio_unitario FROM doc.factura_proveedor_detalle fpd
                                 WHERE fpd.item_id = rtpi.item_id ORDER BY fpd.fyh_cre DESC LIMIT 1),
                                (SELECT cd.precio_unitario FROM doc.compra_detalle cd
                                 WHERE cd.item_id = rtpi.item_id ORDER BY cd.fyh_cre DESC LIMIT 1),
                                0
                            ) AS precio_kg
                        ) pr ON true
                        WHERE rtpi.paso_id = rtp.id
                    )
                ) ORDER BY rtp.orden
            )
            FROM receta.tenido_paso rtp
            JOIN receta.operacion ro ON ro.id = rtp.operacion_id
            WHERE rtp.receta_id = r.id
        )
    ) INTO v_receta
    FROM mes.partida_paso pp
    JOIN receta.tenido r     ON r.id   = pp.receta_id
    JOIN mes.partida p       ON p.id   = pp.partida_id
    LEFT JOIN tipo_receta tr ON tr.id  = r.tipo_receta_id
    JOIN grupo_articulo ga    ON ga.id  = r.grupo_articulo_id
    LEFT JOIN tercero cli    ON cli.id = p.tercero_id
    WHERE pp.id = p_paso_id;

    -- Preview mode (p_commit = false): return the scaled JSON only — no reservation
    -- write, no notification. Used to compare machines / bath ratios before scheduling.
    IF NOT p_commit THEN
        RETURN v_receta;
    END IF;

    -- Stock gate: only for pasos not yet completed (historical reprints skip this).
    -- Checks each insumo's scaled requirement against current stock; raises if any deficit.
    --
    -- TEMPORARILY DISABLED (2026-07-10): a physical insumo ingress was missed in the
    -- system, so system stock reads short while stock exists on the floor. Recipes need
    -- to print ASAP; the ledger already tolerates negatives. Re-enable once the missing
    -- ingress is registered. See partida_componente reservation + variance-alert backstop.
    SELECT (estado = 'COMPLETADO') INTO v_completado
    FROM mes.partida_paso WHERE id = p_paso_id;

    -- reservado_otros check below is commented out (2026-07-20): stale reservations
    -- from stalled/abandoned partidas (e.g. partida 6135) were never getting cleared,
    -- causing false "stock insuficiente" on unrelated items. Re-enable once
    -- stale-reservation cleanup is in place. Stock gate itself remains active.
    IF NOT v_completado THEN
        WITH required AS (
            SELECT rtpi.item_id,
                   ROUND(SUM(CASE
                       WHEN iid.medida = 'g/L' THEN rtpi.cantidad * v_volumen * iid.factor_stock / 1000
                       WHEN iid.medida = '%'   THEN rtpi.cantidad * v_peso * 10 * iid.factor_stock / 1000
                   END), 7) AS cantidad_requerida
            FROM receta.tenido_paso rtp
            JOIN receta.tenido_paso_insumo rtpi ON rtpi.paso_id = rtp.id
            JOIN item_insumo_detalle iid ON iid.item_id = rtpi.item_id
            WHERE rtp.receta_id = v_receta_id
            GROUP BY rtpi.item_id
        ),
        -- COMMENTED OUT (2026-07-20): reservado_otros competed for stock against OTHER
        -- still-open pasos, but stale reservations from stalled/abandoned partidas
        -- (e.g. partida 6135) were never getting cleared, causing false "stock
        -- insuficiente" on unrelated items. Re-enable once stale-reservation cleanup
        -- is in place. Mirrors the active-paso filter used for roll availability
        -- (vw_lotes_rollos_disponibles) and get_actividades_sin_programar.
        -- reservado_otros AS (
        --     SELECT pc.item_id, SUM(pc.cantidad_reservada) AS cantidad_reservada
        --     FROM mes.partida_componente pc
        --     JOIN mes.partida_paso pp2 ON pp2.id = pc.partida_paso_id
        --     JOIN mes.partida p2       ON p2.id = pc.partida_id
        --     WHERE pc.item_id IS NOT NULL
        --       AND pc.partida_paso_id <> p_paso_id
        --       AND p2.estado_produccion NOT IN ('CERRADA', 'CANCELADA', 'TECO')
        --       AND p2.fyh_elm IS NULL
        --       AND pp2.estado NOT IN ('COMPLETADO', 'OMITIDO')
        --     GROUP BY pc.item_id
        -- ),
        deficit AS (
            SELECT r.item_id, i.nombre AS item_nombre,
                   r.cantidad_requerida,
                   COALESCE(s.cantidad_total, 0) AS stock_disponible
            FROM required r
            JOIN item i ON i.id = r.item_id
            LEFT JOIN inventario.vw_stock_items s ON s.item_id = r.item_id
            WHERE COALESCE(s.cantidad_total, 0) < r.cantidad_requerida
        )
        SELECT jsonb_agg(jsonb_build_object(
            'item_id', item_id, 'item_nombre', item_nombre,
            'stock_disponible', stock_disponible,
            'cantidad_requerida', cantidad_requerida
        ))
        INTO v_stock_error FROM deficit;
    
        IF v_stock_error IS NOT NULL THEN
            RAISE EXCEPTION 'Stock insuficiente para generar la receta'
                USING DETAIL = v_stock_error::text, ERRCODE = 'P0001';
        END IF;
    END IF;

    -- Write scaled chemical reservations into partida_componente (RESB chemical rows).
    -- Skipped for completed pasos: a historical reprint must not overwrite the
    -- cantidad_reservada baseline that finalizar_paso's variance alert already used,
    -- and re-inserting it here would be a stale row with no stock effect anyway.
    IF NOT v_completado THEN
        DELETE FROM mes.partida_componente
        WHERE partida_paso_id = p_paso_id AND item_id IS NOT NULL;

        INSERT INTO mes.partida_componente (partida_id, item_id, partida_paso_id, cantidad_reservada, usr_cre)
        SELECT v_partida_id,
               rtpi.item_id,
               p_paso_id,
               -- ÷1000: g/L×L and %×kg×10 yield GRAMS; reserved qty is stored in kg (stock unit). 7 dp = 4 gram-decimals.
               ROUND(CASE
                   WHEN iid.medida = 'g/L' THEN SUM(rtpi.cantidad) * v_volumen * iid.factor_stock / 1000
                   WHEN iid.medida = '%'   THEN SUM(rtpi.cantidad) * v_peso    * 10 * iid.factor_stock / 1000
               END, 7),
               v_usr_id
        FROM receta.tenido_paso rtp
        JOIN receta.tenido_paso_insumo rtpi ON rtpi.paso_id  = rtp.id
        JOIN item_insumo_detalle iid        ON iid.item_id   = rtpi.item_id
        WHERE rtp.receta_id = v_receta_id
        GROUP BY rtpi.item_id, iid.medida, iid.factor_stock;
    END IF;

    INSERT INTO notification.notifications(user_id, title, body, tipo, payload)
    SELECT ur.user_id, 'Receta Generada',
           COALESCE((SELECT COALESCE(nombre,'Usuario desconocido') || ' ' || apellido
                     FROM usuario WHERE id = v_usr_id), 'sistema')
           || format(' generó la receta del paso %s (orden #%s)', v_op_nombre, v_partida_id), 'info',
           jsonb_build_object('objeto_tipo','partida_paso','paso_id', p_paso_id, 'partida_id', v_partida_id, 'partida_origen_id', (v_receta->>'partida_origen_id')::bigint)
    FROM iam.user_rol ur LEFT JOIN iam.rol r ON ur.rol_id = r.id
    WHERE r.code IN ('jefe_planta','supervisor_produccion') AND v_usr_id <> ur.user_id;

    RETURN v_receta;

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in generar_receta - User: %, ID: %, Error: %', v_usr_id, p_paso_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION mes.generar_receta(p_paso_id bigint, p_maquina_id integer, p_relacion_bano numeric, p_commit boolean) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.generar_receta_lavado_maquina(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.generar_receta_lavado_maquina(p_lavado_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes', 'receta', 'doc'
    AS $$
DECLARE
    v_usr_id   INT := get_user_id();
    v_receta   jsonb;
    v_message  text;
    v_detail   text;
    v_hint     text;
    v_context  text;
    v_sqlstate text;
BEGIN
    IF NOT jwt_has_permission('produccion.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT jsonb_build_object(
        'lavado_maquina_id',  lm.id,
        'receta_id',          r.id,
        'tipo_lavado',        tlm.nombre,
        'color_origen_id',    r.valor_origen_id,
        'color_origen',       vo.valor,
        'color_destino_id',   r.valor_destino_id,
        'color_destino',      vd.valor,
        'maquina_id',         lm.maquina_id,
        'maquina',            jsonb_build_object('id', m.id, 'codigo', m.codigo, 'nombre', m.nombre),
        'estado',             lm.estado,
        'fyh_cre',            lm.fyh_cre,
        'pasos', (
            SELECT jsonb_agg(
                jsonb_build_object(
                    'orden',       lmp.orden,
                    'operacion_id', ro.id,
                    'operacion',   ro.nombre,
                    'ph',          lmp.ph,
                    'temperatura', lmp.temperatura,
                    'tiempo_min',  lmp.tiempo_min,
                    'nota',        lmp.nota,
                    'insumos', (
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'item_id',  lmpi.item_id,
                                'orden',    lmpi.orden,
                                'codigo',   i.codigo,
                                'nombre',   i.nombre,
                                'cantidad', lmpi.cantidad,
                                'medida',   'kg'
                            ) ORDER BY lmpi.orden
                        )
                        FROM receta.lavado_maquina_paso_insumo lmpi
                        JOIN item i ON i.id = lmpi.item_id
                        WHERE lmpi.paso_id = lmp.id
                    )
                ) ORDER BY lmp.orden
            )
            FROM receta.lavado_maquina_paso lmp
            JOIN receta.operacion ro ON ro.id = lmp.operacion_id
            WHERE lmp.receta_id = r.id
        )
    ) INTO v_receta
    FROM mes.lavado_maquina         lm
    JOIN receta.lavado_maquina      r   ON r.id   = lm.receta_id
    JOIN mes.maquina                m   ON m.id   = lm.maquina_id
    LEFT JOIN tipo_lavado_maquina   tlm ON tlm.id = r.tipo_lavado_mq_id
    LEFT JOIN public.valor          vo  ON vo.id  = r.valor_origen_id
    LEFT JOIN public.valor          vd  ON vd.id  = r.valor_destino_id
    WHERE lm.id = p_lavado_id;

    IF v_receta IS NULL THEN
        RAISE EXCEPTION 'lavado_maquina id=% no encontrado.', p_lavado_id;
    END IF;

    RETURN v_receta;

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in generar_receta_lavado_maquina - User: %, ID: %, Error: %', v_usr_id, p_lavado_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION mes.generar_receta_lavado_maquina(p_lavado_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.get_actividades_sin_programar()
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.get_actividades_sin_programar() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'doc', 'mes', 'inventario', 'receta'
    AS $$
WITH
pasos_pendientes AS MATERIALIZED (
    SELECT pp.id AS partida_paso_id, pp.partida_id
    FROM mes.partida_paso pp
    JOIN mes.partida p ON p.id = pp.partida_id
    WHERE p.estado_produccion NOT IN ('CERRADA', 'CANCELADA', 'TECO')
      AND p.fyh_elm IS NULL
      AND pp.estado NOT IN ('COMPLETADO', 'OMITIDO')
      AND EXISTS (
          SELECT 1 FROM mes.partida_componente pc
          WHERE pc.partida_id = pp.partida_id AND pc.lote_id IS NOT NULL
      )
      AND NOT EXISTS (
          SELECT 1 FROM mes.partida_paso_ejecucion pe
          WHERE pe.partida_paso_id = pp.id AND pe.estado = 'EN_PROCESO'
      )
      AND NOT EXISTS (
          SELECT 1 FROM mes.programacion prog
          WHERE prog.actividad_tipo = 'partida_paso'
            AND prog.actividad_id = pp.id
            AND prog.fecha >= CURRENT_DATE
      )
),
entregas_partida AS (
    SELECT
        pc.partida_id,
        jsonb_agg(DISTINCT jsonb_build_object(
            'tipo',              'entrega',
            'id',                lrd.entrega_id,
            'entrega_serie',     gr.serie,
            'entrega_correlativo', gr.correlativo
        )) AS entregas
    FROM mes.partida_componente        pc
    JOIN inventario.lote_rollo_detalle lrd ON lrd.lote_id = pc.lote_id
    LEFT JOIN doc.entrega              gr  ON gr.id = lrd.entrega_id
    WHERE pc.lote_id IS NOT NULL
      AND pc.partida_id IN (SELECT partida_id FROM pasos_pendientes)
    GROUP BY pc.partida_id
),
rollos_partida AS (
    SELECT
        pc.partida_id,
        COUNT(*) FILTER (WHERE ird.flg_rib = false) AS cantidad_regular,
        COUNT(*) FILTER (WHERE ird.flg_rib = true)  AS cantidad_rib,
        COUNT(*)                                     AS total_rollos
    FROM mes.partida_componente pc
    JOIN inventario.lote l      ON l.id        = pc.lote_id
    JOIN item_rollo_detalle ird ON ird.item_id = l.item_id
    WHERE pc.lote_id IS NOT NULL
      AND pc.partida_id IN (SELECT partida_id FROM pasos_pendientes)
    GROUP BY pc.partida_id
)
SELECT COALESCE(jsonb_agg(row_obj ORDER BY fyh_cre DESC), '[]'::jsonb)
FROM (
    -- Production pasos (PENDIENTE, not yet on board)
    SELECT
        p.fyh_cre,
        jsonb_build_object(
            'actividad_tipo',     'partida_paso',
            'actividad_id',       pp.id,
            'paso_id',            pp.id,
            'partida_id',         p.id,
            'partida_origen_id',  p.partida_origen_id,
            'operacion_id',       o.id,
            'operacion',          o.nombre,
            'operacion_codigo',   o.codigo,
            'partida_codigo',     EXTRACT(YEAR FROM p.fyh_cre)::TEXT || '-' || LPAD(p.numero::TEXT, 4, '0'),
            'grupo_articulo_id',  p.grupo_articulo_id,
            'grupo_articulo',           ga.nombre,
            'cliente',            c.nombre,
            'color',              vc.color,
            'color_hex',          vc.color_hex,
            'valor',              vclr.valor,
            'tenido',             t.tenido,
            'ancho',              p.ancho,
            'malla',              p.malla,
            'rendimiento',        p.rendimiento,
            'fibra',              p.fibra,
            'receta_tenido_id',   pp.receta_id,
            'tipo_receta',        tr.tipo_receta,
            'total_rollos',       rp.total_rollos,
            'cantidad_regular',   rp.cantidad_regular,
            'cantidad_rib',       rp.cantidad_rib,
            'entregas',              gp.entregas,
            'ejecucion_fyh_inicio', ppe.fyh_inicio
        ) AS row_obj
    FROM pasos_pendientes pend
    JOIN mes.partida_paso pp     ON pp.id = pend.partida_paso_id
    JOIN mes.operacion o         ON o.id  = pp.operacion_id
    JOIN mes.partida p           ON p.id  = pp.partida_id
    LEFT JOIN receta.tenido rt      ON rt.id  = pp.receta_id
    LEFT JOIN tipo_receta tr        ON tr.id  = rt.tipo_receta_id
    LEFT JOIN grupo_articulo ga      ON ga.id  = p.grupo_articulo_id
    LEFT JOIN tenido t              ON t.id   = p.tenido_id
    LEFT JOIN tercero c             ON c.id   = p.tercero_id
    LEFT JOIN vw_colores vc         ON vc.color_x_cliente_id = p.color_x_cliente_id
    LEFT JOIN color_x_cliente cxc   ON cxc.id = p.color_x_cliente_id
    LEFT JOIN public.valor vclr     ON vclr.id = cxc.valor_id
    LEFT JOIN entregas_partida gp      ON gp.partida_id = p.id
    LEFT JOIN rollos_partida rp     ON rp.partida_id = p.id
    LEFT JOIN mes.partida_paso_ejecucion ppe ON ppe.partida_paso_id = pp.id AND ppe.estado = 'EN_PROCESO'

    UNION ALL

    -- Machine wash activities (PENDIENTE, not yet on board)
    SELECT
        lm.fyh_cre,
        jsonb_build_object(
            'actividad_tipo',            'LAVADO_MAQUINA',
            'actividad_id',              lm.id,
            'lavado_id',                 lm.id,
            'receta_lavado_maquina_id',  lm.receta_id,  -- FIX BUG5: was lm.receta_lavado_maquina_id
            'maquina_id',                lm.maquina_id,
            'nota',                      lm.nota
        ) AS row_obj
    FROM mes.lavado_maquina lm
    LEFT JOIN mes.programacion prog_lav
           ON prog_lav.actividad_tipo = 'LAVADO_MAQUINA'
          AND prog_lav.actividad_id   = lm.id
          AND prog_lav.fecha         >= CURRENT_DATE
    WHERE lm.estado = 'PENDIENTE'
      AND prog_lav.id IS NULL
) sub;
$$;


ALTER FUNCTION mes.get_actividades_sin_programar() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.get_componentes_disponibles(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.get_componentes_disponibles(p_partida_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'mes', 'inventario'
    AS $$
SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
        'lote_id',            pc.lote_id,
        'item_id',            l.item_id,
        'item_codigo',        i.codigo,
        'item_nombre',        i.nombre,
        'lote_codigo',        EXTRACT(YEAR FROM l.fyh_cre)%100 || '-' || LPAD(l.secuencia::TEXT, 5, '0'),
        'cantidad',           l.cantidad,
        'cantidad_reservada', pc.cantidad_reservada,
        'saldo_actual',       (
            SELECT SUM(cantidad_disponible)
            FROM inventario.vw_stock_lotes
            WHERE lote_id = pc.lote_id
        ),
        'estado_calidad',     l.estado_calidad,
        'flg_rib',            ird.flg_rib,
        'ancho',              lrd.ancho,
        'malla',              lrd.malla
    )
ORDER BY pc.lote_id), '[]'::jsonb)
FROM mes.partida_componente pc
JOIN inventario.lote l                      ON l.id        = pc.lote_id
JOIN item i                                 ON i.id        = l.item_id
LEFT JOIN item_rollo_detalle ird             ON ird.item_id = l.item_id
LEFT JOIN inventario.lote_rollo_detalle lrd  ON lrd.lote_id = l.id
WHERE pc.partida_id = p_partida_id
  AND pc.lote_id IS NOT NULL
  AND EXISTS (
      SELECT 1 FROM inventario.vw_stock_lotes
      WHERE lote_id = pc.lote_id
  );
$$;


ALTER FUNCTION mes.get_componentes_disponibles(p_partida_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.get_matizado(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.get_matizado(p_ejecucion_id bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'mes', 'inventario'
    AS $$
SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
        'item_id',     agg.item_id,
        'item_codigo', agg.item_codigo,
        'item_nombre', agg.item_nombre,
        'cantidad',    agg.cantidad
    )
    ORDER BY agg.item_nombre
), '[]'::jsonb)
FROM (
    SELECT m.item_id, i.codigo AS item_codigo, i.nombre AS item_nombre,
           SUM(m.cantidad) AS cantidad
    FROM inventario.item_movimientos m
    JOIN item i ON i.id = m.item_id
    WHERE m.documento_tipo          = 'partida_paso_ejecucion'
      AND m.documento_id            = p_ejecucion_id
      AND m.item_movimiento_tipo_id = (SELECT id FROM inventario.item_movimiento_tipo   WHERE codigo = 'PROD_CONSUMO')
      AND m.motivo_id               = (SELECT id FROM inventario.item_movimiento_motivo WHERE codigo = 'MATIZADO')
    GROUP BY m.item_id, i.codigo, i.nombre
) agg;
$$;


ALTER FUNCTION mes.get_matizado(p_ejecucion_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.get_partida(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.get_partida(p_partida_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'inventario', 'doc', 'mes', 'calidad'
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    SELECT jsonb_build_object(
        -- Header
        'id', p.id,
        'partida_origen_id', p.partida_origen_id,
        'numero', p.numero,
        'codigo', EXTRACT(YEAR FROM p.fyh_cre)::TEXT || '-' || LPAD(p.numero::TEXT, 4, '0'),
        'prioridad_id', p.prioridad_id,
        'prioridad', pri.prioridad,
        'tercero_id', p.tercero_id,
        'cliente', c.nombre,
        'color_x_cliente_id', p.color_x_cliente_id,
        'color', vc.color,
        'color_hex', vc.color_hex,
        'color_x_cliente_hex', vc.color_x_cliente_hex,
        'tono', vc.tono,
        'grupo_articulo_id', p.grupo_articulo_id,
        'grupo_articulo', ga.nombre,
        'flg_antipilling', p.flg_antipilling,
        'tenido_id', p.tenido_id,
        'tenido', tenido.tenido,
        'malla', p.malla,
        'rendimiento', p.rendimiento,
        'ancho', p.ancho,
        'estado_comercial', p.estado_comercial,
        'estado_produccion', p.estado_produccion,
        'estado_facturacion', p.estado_facturacion,
        'fecha_acordada', p.fecha_acordada,
        'fyh_inicio', p.fyh_inicio,
        'fyh_fin', p.fyh_fin,
        'fyh_cre', p.fyh_cre,
        'flg_doble_bolsa', p.flg_doble_bolsa,
        'observacion', p.observacion,

        -- Planned output items
        'partida_detalles', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', pd.id,
                'item_id', pd.item_id,
                'item_tipo_codigo', vi.item_tipo_codigo,
                'item_codigo', vi.item_codigo,
                'item_nombre', vi.item_nombre,
                'cantidad', pd.cantidad,
                'unidad', u.codigo,
                'unidad_id', u.id,
                'cantidad_producida', pd.cantidad_producida,
                'fyh_mod', pd.fyh_mod
            ) ORDER BY pd.id)
            FROM mes.partida_detalle pd
            LEFT JOIN vw_items vi ON vi.item_id = pd.item_id
            LEFT JOIN unidad u ON u.id = pd.unidad_id
            WHERE pd.partida_id = p.id
        ), '[]'::jsonb),

        'resumen_progreso', jsonb_build_object(
            'total_pasos', (SELECT COUNT(*) FROM mes.partida_paso WHERE partida_id = p.id),
            'pasos_completados', (
                SELECT COUNT(*) FROM mes.partida_paso
                WHERE partida_id = p.id
                  AND EXISTS (SELECT 1 FROM mes.partida_paso_ejecucion pe
                              WHERE pe.partida_paso_id = mes.partida_paso.id AND pe.estado = 'COMPLETADO')
            ),
            'porcentaje_completado', (
                SELECT ROUND(
                    COUNT(DISTINCT ppe.partida_paso_id) FILTER (WHERE ppe.estado = 'COMPLETADO')::NUMERIC
                    / NULLIF(COUNT(DISTINCT pp.id), 0) * 100, 2
                )
                FROM mes.partida_paso pp
                LEFT JOIN mes.partida_paso_ejecucion ppe ON ppe.partida_paso_id = pp.id
                WHERE pp.partida_id = p.id
            )
        ),

        'resumen_consumo_total', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'item_id', subq.item_id,
                'item_codigo', subq.item_codigo,
                'item_nombre', subq.item_nombre,
                'cantidad_total', subq.cantidad_total,
                'unidad', subq.unidad
            ))
            FROM (
                SELECT m.item_id, vi.item_codigo, vi.item_nombre,
                       vi.unidad_codigo AS unidad,
                       SUM(CASE WHEN m.item_movimiento_tipo_id = (
                               SELECT id FROM inventario.item_movimiento_tipo WHERE codigo = 'PROD_CONSUMO_REV'
                           ) THEN -m.cantidad ELSE m.cantidad END) AS cantidad_total
                FROM inventario.item_movimientos m
                JOIN vw_items vi ON vi.item_id = m.item_id
                WHERE m.documento_tipo = 'partida_paso_ejecucion'
                  AND m.documento_id IN (
                      SELECT pe.id FROM mes.partida_paso_ejecucion pe
                      JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
                      WHERE pp.partida_id = p.id
                  )
                  AND m.item_movimiento_tipo_id IN (
                      SELECT id FROM inventario.item_movimiento_tipo WHERE codigo IN ('PROD_CONSUMO', 'PROD_CONSUMO_REV')
                  )
                GROUP BY m.item_id, vi.item_codigo, vi.item_nombre, vi.unidad_codigo
                HAVING SUM(CASE WHEN m.item_movimiento_tipo_id = (
                               SELECT id FROM inventario.item_movimiento_tipo WHERE codigo = 'PROD_CONSUMO_REV'
                           ) THEN -m.cantidad ELSE m.cantidad END) > 0
            ) subq
        ), '[]'::jsonb),

        -- Steps
        'pasos', COALESCE((
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id', opp.id,
                    'secuencia', opp.secuencia,
                    'operacion_id', opp.operacion_id,
                    'operacion_codigo', o.codigo,
                    'operacion_nombre', o.nombre,
                    'maquina_programada_id', prog.maquina_id,
                    'maquina_programada_nombre', maquina.nombre,
                    'ph_objetivo', opp.ph_objetivo,
                    'relacion_bano_objetivo', prog.relacion_bano,
                    'temperatura_objetivo', opp.temperatura_objetivo,
                    'tiempo_estandar', opp.tiempo_estandar,
                    'receta_id', opp.receta_id,
                    -- True for the last non-omitted step; frontend shows production output form here.
                    'flg_ultimo', (
                        opp.secuencia = (
                            SELECT MAX(pp2.secuencia)
                            FROM mes.partida_paso pp2
                            WHERE pp2.partida_id = p_partida_id
                              AND NOT EXISTS (
                                  SELECT 1 FROM mes.partida_paso_ejecucion pe2
                                  WHERE pe2.partida_paso_id = pp2.id AND pe2.estado = 'OMITIDO'
                              )
                        )
                    ),
                    'cantidad_procesada', (
                        SELECT COALESCE(SUM(pe.cantidad_rollos) FILTER (WHERE pe.estado = 'COMPLETADO'), 0)
                        FROM mes.partida_paso_ejecucion pe
                        WHERE pe.partida_paso_id = opp.id
                    ),
                    'estado', opp.estado,
                    'consumo', COALESCE((
                        SELECT jsonb_agg(jsonb_build_object(
                            'item_id',             sub.item_id,
                            'item_codigo',         sub.item_codigo,
                            'item_nombre',         sub.item_nombre,
                            'lote_id',             sub.lote_id,
                            'cantidad',            sub.cantidad,
                            'unidad',              sub.unidad,
                            'motivo_id',           sub.motivo_id,
                            'motivo_codigo',       sub.motivo_codigo,
                            'origen_ubicacion_id', sub.origen_ubicacion_id,
                            'origen_ubicacion',    sub.origen_ubicacion,
                            'origen_almacen',      sub.origen_almacen
                        ) ORDER BY sub.item_nombre)
                        FROM (
                            SELECT m.item_id, vi_mov.item_codigo, vi_mov.item_nombre, m.lote_id,
                                   SUM(CASE WHEN mt.codigo = 'PROD_CONSUMO_REV' THEN -m.cantidad ELSE m.cantidad END) AS cantidad,
                                   vi_mov.unidad_codigo AS unidad, m.motivo_id, mot.codigo AS motivo_codigo,
                                   m.origen_ubicacion_id, ubi.nombre AS origen_ubicacion, al.nombre AS origen_almacen
                            FROM inventario.item_movimientos m
                            LEFT JOIN vw_items vi_mov ON vi_mov.item_id = m.item_id
                            LEFT JOIN inventario.item_movimiento_tipo mt ON mt.id = m.item_movimiento_tipo_id
                            LEFT JOIN inventario.item_movimiento_motivo mot ON mot.id = m.motivo_id
                            LEFT JOIN inventario.ubicacion ubi ON ubi.id = m.origen_ubicacion_id
                            LEFT JOIN inventario.almacen al ON al.id = ubi.almacen_id
                            WHERE m.documento_tipo = 'partida_paso_ejecucion'
                              AND m.documento_id IN (
                                  SELECT pe.id FROM mes.partida_paso_ejecucion pe
                                  WHERE pe.partida_paso_id = opp.id
                              )
                              AND m.item_movimiento_tipo_id IN (
                                  SELECT id FROM inventario.item_movimiento_tipo WHERE codigo IN ('PROD_CONSUMO', 'PROD_CONSUMO_REV')
                              )
                            GROUP BY m.item_id, vi_mov.item_codigo, vi_mov.item_nombre, m.lote_id,
                                     vi_mov.unidad_codigo, m.motivo_id, mot.codigo,
                                     m.origen_ubicacion_id, ubi.nombre, al.nombre
                            HAVING SUM(CASE WHEN mt.codigo = 'PROD_CONSUMO_REV' THEN -m.cantidad ELSE m.cantidad END) > 0
                        ) sub
                    ), '[]'::jsonb),
                    'ejecuciones', COALESCE((
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'id',                  pe.id,
                                'receta_id',           pe.receta_id,
                                'maquina_id',          pe.maquina_id,
                                'empleado_id',         pe.empleado_id,
                                'estado',              pe.estado,
                                'fyh_inicio',          pe.fyh_inicio,
                                'fyh_fin',             pe.fyh_fin,
                                'ph_real',             pe.ph_real,
                                'temperatura_real',    pe.temperatura_real,
                                'relacion_bano_real',  pe.relacion_bano_real,
                                'cantidad_rollos',     pe.cantidad_rollos,
                                'notas',               pe.notas,
                                'ancho_entrada',       pe.ancho_entrada,
                                'ancho_salida',        pe.ancho_salida,
                                'velocidad',           pe.velocidad,
                                'entrada',             pe.entrada,
                                'salida',              pe.salida,
                                'rendimiento',         pe.rendimiento,
                                'pases',               pe.pases,
                                'malla_alimentacion',  pe.malla_alimentacion,
                                'termofijado', CASE WHEN pt.ejecucion_id IS NOT NULL THEN jsonb_build_object(
                                    'ancho_marco',      pt.ancho_marco,
                                    'vel_maquina',      pt.vel_maquina,
                                    'vel_alimentacion', pt.vel_alimentacion,
                                    'densidad_entrada', pt.densidad_entrada,
                                    'densidad_salida',  pt.densidad_salida,
                                    'lm',               pt.lm,
                                    'galga',            pt.galga
                                ) END,
                                'consumo', COALESCE((
                                    SELECT jsonb_agg(jsonb_build_object(
                                        'item_id',             sub.item_id,
                                        'item_codigo',         sub.item_codigo,
                                        'item_nombre',         sub.item_nombre,
                                        'lote_id',             sub.lote_id,
                                        'cantidad',            sub.cantidad,
                                        'unidad',              sub.unidad,
                                        'motivo_id',           sub.motivo_id,
                                        'motivo_codigo',       sub.motivo_codigo,
                                        'origen_ubicacion_id', sub.origen_ubicacion_id,
                                        'origen_ubicacion',    sub.origen_ubicacion,
                                        'origen_almacen',      sub.origen_almacen
                                    ) ORDER BY sub.item_nombre)
                                    FROM (
                                        SELECT m.item_id, vi_mov.item_codigo, vi_mov.item_nombre, m.lote_id,
                                               SUM(CASE WHEN mt.codigo = 'PROD_CONSUMO_REV' THEN -m.cantidad ELSE m.cantidad END) AS cantidad,
                                               vi_mov.unidad_codigo AS unidad, m.motivo_id, mot.codigo AS motivo_codigo,
                                               m.origen_ubicacion_id, ubi.nombre AS origen_ubicacion, al.nombre AS origen_almacen
                                        FROM inventario.item_movimientos m
                                        LEFT JOIN vw_items vi_mov ON vi_mov.item_id = m.item_id
                                        LEFT JOIN inventario.item_movimiento_tipo mt ON mt.id = m.item_movimiento_tipo_id
                                        LEFT JOIN inventario.item_movimiento_motivo mot ON mot.id = m.motivo_id
                                        LEFT JOIN inventario.ubicacion ubi ON ubi.id = m.origen_ubicacion_id
                                        LEFT JOIN inventario.almacen al ON al.id = ubi.almacen_id
                                        WHERE m.documento_tipo          = 'partida_paso_ejecucion'
                                          AND m.documento_id            = pe.id
                                          AND m.item_movimiento_tipo_id IN (
                                              SELECT id FROM inventario.item_movimiento_tipo WHERE codigo IN ('PROD_CONSUMO', 'PROD_CONSUMO_REV')
                                          )
                                        GROUP BY m.item_id, vi_mov.item_codigo, vi_mov.item_nombre, m.lote_id,
                                                 vi_mov.unidad_codigo, m.motivo_id, mot.codigo,
                                                 m.origen_ubicacion_id, ubi.nombre, al.nombre
                                        HAVING SUM(CASE WHEN mt.codigo = 'PROD_CONSUMO_REV' THEN -m.cantidad ELSE m.cantidad END) > 0
                                    ) sub
                                ), '[]'::jsonb)
                            ) ORDER BY pe.fyh_inicio
                        )
                        FROM mes.partida_paso_ejecucion pe
                        LEFT JOIN mes.partida_paso_ejecucion_termofijado pt ON pt.ejecucion_id = pe.id
                        WHERE pe.partida_paso_id = opp.id
                    ), '[]'::jsonb)
                ) ORDER BY opp.secuencia
            )
            FROM mes.partida_paso opp
            LEFT JOIN mes.operacion o ON o.id = opp.operacion_id
            LEFT JOIN LATERAL (
                SELECT maquina_id, relacion_bano FROM mes.programacion
                WHERE actividad_tipo = 'partida_paso' AND actividad_id = opp.id
                ORDER BY fyh_cre DESC LIMIT 1
            ) prog ON true
            LEFT JOIN mes.maquina ON maquina.id = prog.maquina_id
            WHERE opp.partida_id = p.id
        ), '[]'::jsonb),

        -- Input rolls reserved for this order
        'materiales_reservados', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', opi.id,
                'lote_id', opi.lote_id,
                'lote_codigo', EXTRACT(YEAR FROM l.fyh_cre)%100 || '-' || LPAD(l.secuencia::TEXT, 5, '0'),
                'item_id', l.item_id,
                'item_codigo', vi_mat.item_codigo,
                'item_nombre', vi_mat.item_nombre,
                'cantidad', l.cantidad,
                'unidad', vi_mat.unidad_codigo,
                'estado_calidad', l.estado_calidad,
                'entrega_id',   lrd_in.entrega_id,
                'entrega_serie',         gr_in.serie,
                'entrega_correlativo',   gr_in.correlativo,
                'ancho',              lrd_in.ancho,
                'malla',              lrd_in.malla,
                'flg_tenido',         lrd_in.flg_tenido,
                'flg_antipilling',    lrd_in.flg_antipilling,
                'color_x_cliente_id', lrd_in.color_x_cliente_id,
                'tenido_id',          lrd_in.tenido_id,
                'peso_real',          ps.peso_real,
                'flg_pesado',         (ps.lote_id IS NOT NULL)
            ) ORDER BY opi.id)
            FROM mes.partida_componente opi
            LEFT JOIN inventario.lote l ON l.id = opi.lote_id
            LEFT JOIN vw_items vi_mat ON vi_mat.item_id = l.item_id
            LEFT JOIN inventario.lote_rollo_detalle lrd_in ON lrd_in.lote_id = l.id
            LEFT JOIN doc.entrega gr_in ON gr_in.id = lrd_in.entrega_id
            LEFT JOIN inventario.pesaje ps ON ps.lote_id = l.id
            WHERE opi.partida_id = p.id
              AND opi.lote_id IS NOT NULL
        ), '[]'::jsonb),

        -- Finished goods produced
        'produccion', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id', l.id,
                'lote_codigo', EXTRACT(YEAR FROM l.fyh_cre)%100 || '-' || LPAD(l.secuencia::TEXT, 5, '0'),
                'item_id', l.item_id,
                'item_codigo', vi_prod.item_codigo,
                'item_nombre', vi_prod.item_nombre,
                'cantidad', l.cantidad,
                'unidad', vi_prod.unidad_codigo,
                'estado_calidad', l.estado_calidad,
                'fyh_cre', l.fyh_cre,
                'entrega_id',   lrd_out.entrega_id,
                'entrega_serie',         gr_out.serie,
                'entrega_correlativo',   gr_out.correlativo,
                'ancho',              lrd_out.ancho,
                'malla',              lrd_out.malla,
                'rendimiento',        lrd_out.rendimiento,
                'flg_tenido',         lrd_out.flg_tenido,
                'flg_antipilling',    lrd_out.flg_antipilling,
                'color_x_cliente_id', lrd_out.color_x_cliente_id,
                'tenido_id',          lrd_out.tenido_id,
                'inspecciones', COALESCE((
                    SELECT jsonb_agg(jsonb_build_object(
                        'id', insp.id,
                        'resultado', insp.resultado,
                        'observacion', insp.observacion,
                        'empleado_id', insp.empleado_id,
                        'empleado_nombre', CONCAT(emp.nombre, ' ', emp.apellido),
                        'fyh_inspeccion', insp.fyh_inspeccion
                    ) ORDER BY insp.fyh_inspeccion DESC)
                    FROM calidad.inspeccion insp
                    LEFT JOIN mes.empleado emp ON emp.id = insp.empleado_id
                    WHERE insp.lote_id = l.id
                ), '[]'::jsonb)
            ) ORDER BY l.fyh_cre)
            FROM inventario.lote l
            JOIN mes.partida_paso_ejecucion pe ON pe.id = l.documento_id
            JOIN mes.partida_paso opp ON opp.id = pe.partida_paso_id AND opp.partida_id = p.id
            LEFT JOIN vw_items vi_prod ON vi_prod.item_id = l.item_id
            LEFT JOIN inventario.lote_rollo_detalle lrd_out ON lrd_out.lote_id = l.id
            LEFT JOIN doc.entrega gr_out ON gr_out.id = lrd_out.entrega_id
            WHERE l.documento_tipo = 'partida_paso_ejecucion'
              AND l.fyh_elm        IS NULL
        ), '[]'::jsonb),

        -- Lotes flagged for reproceso — two sources:
        --   1. output lotes (post-production) where estado_calidad = 'REPROCESO'
        --   2. input lotes (pre-output QC) where reserved roll was flagged before final paso completed
        'lotes_reproceso', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'lote_id',    src.lote_id,
                'lote_codigo', src.lote_codigo,
                'item_nombre', src.item_nombre,
                'cantidad',   src.cantidad,
                'unidad',     src.unidad
            ) ORDER BY src.lote_id)
            FROM (
                -- Source 1: output lotes produced by this partida's executions
                SELECT l.id AS lote_id,
                       EXTRACT(YEAR FROM l.fyh_cre)%100 || '-' || LPAD(l.secuencia::TEXT, 5, '0') AS lote_codigo,
                       vi.item_nombre,
                       l.cantidad,
                       vi.unidad_codigo AS unidad
                FROM inventario.lote l
                JOIN mes.partida_paso_ejecucion pe ON pe.id = l.documento_id
                JOIN mes.partida_paso opp          ON opp.id = pe.partida_paso_id AND opp.partida_id = p.id
                LEFT JOIN vw_items vi ON vi.item_id = l.item_id
                WHERE l.documento_tipo = 'partida_paso_ejecucion'
                  AND l.estado_calidad = 'REPROCESO'
                  AND l.fyh_elm        IS NULL
                UNION ALL
                -- Source 2: reserved input lotes flagged before production completes
                SELECT l.id AS lote_id,
                       EXTRACT(YEAR FROM l.fyh_cre)%100 || '-' || LPAD(l.secuencia::TEXT, 5, '0') AS lote_codigo,
                       vi.item_nombre,
                       l.cantidad,
                       vi.unidad_codigo AS unidad
                FROM mes.partida_componente pc
                JOIN inventario.lote l ON l.id = pc.lote_id
                LEFT JOIN vw_items vi ON vi.item_id = l.item_id
                WHERE pc.partida_id = p.id
                  AND pc.lote_id IS NOT NULL
                  AND l.estado_calidad = 'REPROCESO'
            ) src
        ), '[]'::jsonb),

        -- Direct rework partidas (partida_origen_id = this partida; no grandchildren)
        'reprocesos', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id',                 ph.id,
                'codigo',             EXTRACT(YEAR FROM ph.fyh_cre)::TEXT || '-' || LPAD(ph.numero::TEXT, 4, '0'),
                'estado_produccion',  ph.estado_produccion,
                'estado_comercial',   ph.estado_comercial
            ) ORDER BY ph.fyh_cre)
            FROM mes.partida ph
            WHERE ph.partida_origen_id = p.id
        ), '[]'::jsonb)

    ) INTO v_result
    FROM mes.partida p
    LEFT JOIN prioridad pri       ON pri.id = p.prioridad_id
    LEFT JOIN tercero c           ON c.id = p.tercero_id
    LEFT JOIN tenido              ON tenido.id = p.tenido_id
    LEFT JOIN vw_colores vc       ON vc.color_x_cliente_id = p.color_x_cliente_id
    LEFT JOIN grupo_articulo ga    ON ga.id = p.grupo_articulo_id
    WHERE p.id = p_partida_id;

    RETURN v_result;
END;
$$;


ALTER FUNCTION mes.get_partida(p_partida_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.get_partida_familia(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.get_partida_familia(p_partida_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes'
    AS $$
DECLARE
    v_root_id BIGINT;
    v_result  JSONB;
BEGIN
    -- Resolve to the family root: any member resolves to the original.
    SELECT COALESCE(p.partida_origen_id, p.id) INTO v_root_id
    FROM mes.partida p
    WHERE p.id = p_partida_id AND p.fyh_elm IS NULL;

    IF v_root_id IS NULL THEN
        RAISE EXCEPTION 'Partida % no encontrada.', p_partida_id;
    END IF;

    SELECT jsonb_build_object(
        -- Header (root)
        'root_id',             r.id,
        'codigo',              EXTRACT(YEAR FROM r.fyh_cre)::TEXT
                                   || '-' || LPAD(r.numero::TEXT, 4, '0'),
        'tercero_id',          r.tercero_id,
        'cliente',             c.nombre,
        'grupo_articulo_id',   r.grupo_articulo_id,
        'grupo_articulo',       ga.nombre,
        'color_x_cliente_id',  r.color_x_cliente_id,
        'color',               vc.color,
        'color_hex',           vc.color_hex,
        'estado_produccion',   r.estado_produccion,
        'estado_comercial',    r.estado_comercial,
        'estado_facturacion',  r.estado_facturacion,
        'prioridad_id',        r.prioridad_id,
        'prioridad',           pri.prioridad,
        'fecha_acordada',      r.fecha_acordada,
        'fyh_cre',             r.fyh_cre,
        'num_reprocesos',      (SELECT COUNT(*) FROM mes.partida rw
                                 WHERE rw.partida_origen_id = r.id),
        'tiene_rework_activo', EXISTS (SELECT 1 FROM mes.partida rw
                                 WHERE rw.partida_origen_id = r.id
                                   AND rw.estado_produccion NOT IN ('TECO','CERRADA','CANCELADA')),

        -- Family-level fulfillment totals. Computed straight from the shared
        -- terminal-deliverable base view filtered to THIS family — no whole-table
        -- aggregation (the rollup view mes.vw_partida_familia is for the board,
        -- not for single-row getters). The dedup rule stays DRY in the base view;
        -- only the trivial arithmetic (faltante, %) is repeated here.
        'cumplimiento', (
            SELECT jsonb_build_object(
                'demanda_rollos',          dem.demanda,
                'producido_bueno',         sal.bueno,
                'producido_pendiente',     sal.pendiente,
                'producido_reproceso',     sal.reproceso,
                'producido_terminal',      sal.terminal,
                'faltante',                GREATEST(0, dem.demanda - sal.bueno),
                'porcentaje_cumplimiento', CASE WHEN dem.demanda > 0
                                                THEN ROUND(sal.bueno::numeric / dem.demanda * 100, 0)
                                                ELSE NULL END,
                'flg_cumplida',            (sal.bueno >= dem.demanda AND dem.demanda > 0)
            )
            FROM (
                SELECT COALESCE(SUM(cantidad), 0) AS demanda
                FROM mes.partida_detalle WHERE partida_id = v_root_id
            ) dem
            CROSS JOIN (
                SELECT
                    COUNT(*) FILTER (WHERE estado_calidad = 'APROBADO')  AS bueno,
                    COUNT(*) FILTER (WHERE estado_calidad = 'PENDIENTE') AS pendiente,
                    COUNT(*) FILTER (WHERE estado_calidad = 'REPROCESO') AS reproceso,
                    COUNT(*)                                             AS terminal
                FROM mes.vw_partida_familia_output WHERE root_id = v_root_id
            ) sal
        ),

        -- Per-item breakdown: intent (root detalle) vs terminal output (family)
        'cumplimiento_por_item', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'item_id',             it.item_id,
                'item_codigo',         vi.item_codigo,
                'item_nombre',         vi.item_nombre,
                'demanda_rollos',      it.demanda,
                'producido_bueno',     it.bueno,
                'producido_pendiente', it.pendiente,
                'producido_reproceso', it.reproceso,
                'faltante',            GREATEST(0, it.demanda - it.bueno)
            ) ORDER BY vi.item_nombre)
            FROM (
                SELECT
                    COALESCE(dd.item_id, oo.item_id) AS item_id,
                    COALESCE(dd.demanda, 0)          AS demanda,
                    COALESCE(oo.bueno, 0)            AS bueno,
                    COALESCE(oo.pendiente, 0)        AS pendiente,
                    COALESCE(oo.reproceso, 0)        AS reproceso
                FROM (
                    SELECT item_id, SUM(cantidad) AS demanda
                    FROM mes.partida_detalle
                    WHERE partida_id = v_root_id
                    GROUP BY item_id
                ) dd
                FULL JOIN (
                    SELECT item_id,
                        COUNT(*) FILTER (WHERE estado_calidad = 'APROBADO')  AS bueno,
                        COUNT(*) FILTER (WHERE estado_calidad = 'PENDIENTE') AS pendiente,
                        COUNT(*) FILTER (WHERE estado_calidad = 'REPROCESO') AS reproceso
                    FROM mes.vw_partida_familia_output
                    WHERE root_id = v_root_id
                    GROUP BY item_id
                ) oo ON oo.item_id = dd.item_id
            ) it
            LEFT JOIN vw_items vi ON vi.item_id = it.item_id
        ), '[]'::jsonb),

        -- Members: root + each reproceso, with its own terminal output tally
        'miembros', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
                'id',                 m.id,
                'codigo',             EXTRACT(YEAR FROM m.fyh_cre)::TEXT
                                          || '-' || LPAD(m.numero::TEXT, 4, '0'),
                'rol',                CASE WHEN m.partida_origen_id IS NULL
                                           THEN 'ORIGEN' ELSE 'REPROCESO' END,
                'estado_produccion',  m.estado_produccion,
                'estado_comercial',   m.estado_comercial,
                'fyh_cre',            m.fyh_cre,
                'producido_bueno',    (SELECT COUNT(*) FROM mes.vw_partida_familia_output o
                                        WHERE o.partida_id = m.id AND o.estado_calidad = 'APROBADO'),
                'producido_terminal', (SELECT COUNT(*) FROM mes.vw_partida_familia_output o
                                        WHERE o.partida_id = m.id)
            ) ORDER BY m.partida_origen_id NULLS FIRST, m.fyh_cre)
            FROM mes.partida m
            WHERE (m.id = v_root_id OR m.partida_origen_id = v_root_id)
              AND m.fyh_elm IS NULL
        ), '[]'::jsonb)

    ) INTO v_result
    FROM mes.partida r
    LEFT JOIN tercero c        ON c.id  = r.tercero_id
    LEFT JOIN grupo_articulo ga ON ga.id = r.grupo_articulo_id
    LEFT JOIN vw_colores vc    ON vc.color_x_cliente_id = r.color_x_cliente_id
    LEFT JOIN prioridad pri    ON pri.id = r.prioridad_id
    WHERE r.id = v_root_id;

    RETURN v_result;
END;
$$;


ALTER FUNCTION mes.get_partida_familia(p_partida_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.get_pasos_sin_programar()
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.get_pasos_sin_programar() RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'doc', 'mes'
    AS $$
SELECT COALESCE(jsonb_agg(row_obj), '[]'::jsonb)
FROM (
    SELECT jsonb_build_object(
        'actividad_tipo',     'partida_paso',
        'paso_id',            pp.id,
        'partida_id',           p.id,
        'operacion',          o.nombre,
        'operacion_codigo',   o.codigo,
        'partida_codigo',     EXTRACT(YEAR FROM p.fyh_cre)::TEXT || '-' || LPAD(p.numero::TEXT, 4, '0'),
        'articulo_tipo_id',   p.articulo_tipo_id,
        'fibra',              p.fibra,
        'cliente',            c.nombre,
        'color',              vc.color,
        'color_hex',          vc.color_hex,
        'valor',              vclr.valor,
        'tenido',             t.tenido
    ) AS row_obj
    FROM mes.partida_paso pp
    JOIN mes.operacion o ON o.id = pp.operacion_id
    JOIN mes.partida p   ON p.id = pp.partida_id
    LEFT JOIN tenido t         ON t.id  = p.tenido_id
    LEFT JOIN tercero c        ON c.id  = p.tercero_id
    LEFT JOIN vw_colores vc    ON vc.color_x_cliente_id = p.color_x_cliente_id
    LEFT JOIN color_x_cliente cxc ON cxc.id = p.color_x_cliente_id
    LEFT JOIN public.valor vclr   ON vclr.id = cxc.valor_id
    WHERE NOT EXISTS (
          SELECT 1 FROM mes.partida_paso_ejecucion pe
          WHERE pe.partida_paso_id = pp.id AND pe.estado IN ('EN_PROCESO','COMPLETADO','OMITIDO')
      )
      -- Pasos scheduled for past dates that were never executed must reappear here.
      -- Using >= CURRENT_DATE so stale programacion rows don't hide them.
    --   AND NOT EXISTS (SELECT 1 FROM mes.programacion prog WHERE prog.actividad_tipo = 'partida_paso' AND prog.actividad_id = pp.id)
      AND NOT EXISTS (
          SELECT 1 FROM mes.programacion prog
          WHERE prog.actividad_tipo = 'partida_paso' AND prog.actividad_id = pp.id
            AND prog.fecha >= CURRENT_DATE
      )
    ORDER BY p.fyh_cre DESC
) sub;
$$;


ALTER FUNCTION mes.get_pasos_sin_programar() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.get_programacion_diaria(date)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.get_programacion_diaria(p_fecha date) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'doc', 'mes', 'inventario', 'receta'
    AS $$
WITH partidas_del_dia AS MATERIALIZED (
    -- Single scan of programacion for the date; both entregas_partida and rollos_partida reference this.
    SELECT pp2.partida_id
    FROM mes.programacion prog2
    JOIN mes.partida_paso pp2 ON pp2.id = prog2.actividad_id
    WHERE prog2.fecha = p_fecha AND prog2.actividad_tipo = 'partida_paso'
),
entregas_partida AS (
    SELECT
        pc.partida_id,
        jsonb_agg(DISTINCT jsonb_build_object(
            'tipo',              'entrega',
            'id',                lrd.entrega_id,
            'entrega_serie',     gr.serie,
            'entrega_correlativo', gr.correlativo
        )) AS entregas
    FROM mes.partida_componente        pc
    JOIN inventario.lote_rollo_detalle lrd ON lrd.lote_id = pc.lote_id
    LEFT JOIN doc.entrega              gr  ON gr.id = lrd.entrega_id
    WHERE pc.lote_id IS NOT NULL
      AND pc.partida_id IN (SELECT partida_id FROM partidas_del_dia)
    GROUP BY pc.partida_id
),
rollos_partida AS (
    SELECT
        pc.partida_id,
        COUNT(*) FILTER (WHERE ird.flg_rib = false) AS cantidad_regular,
        COUNT(*) FILTER (WHERE ird.flg_rib = true)  AS cantidad_rib,
        COUNT(*)                                     AS total_rollos
    FROM mes.partida_componente pc
    JOIN inventario.lote l      ON l.id        = pc.lote_id
    JOIN item_rollo_detalle ird ON ird.item_id = l.item_id
    WHERE pc.lote_id IS NOT NULL
      AND pc.partida_id IN (SELECT partida_id FROM partidas_del_dia)
    GROUP BY pc.partida_id
)
SELECT COALESCE(jsonb_agg(row_obj), '[]'::jsonb)
FROM (
    SELECT jsonb_build_object(
        'id',                        prog.id,
        'maquina_id',                prog.maquina_id,
        'secuencia',                 prog.secuencia,
        'nota',                      prog.nota,
        'relacion_bano',             prog.relacion_bano,
        'actividad_tipo',            prog.actividad_tipo,
        -- Production paso fields (null when actividad_tipo = 'LAVADO_MAQUINA')
        'paso_id',                   pp.id,
        'operacion_id',              o.id,
        'operacion',                 o.nombre,
        'operacion_codigo',          o.codigo,
        'receta_tenido_id',          pp.receta_id,
        'tipo_receta',               tr.tipo_receta,
        'paso_estado',               pp.estado,
        'partida_id',                p.id,
        'partida_origen_id',         p.partida_origen_id,
        'partida_codigo',            EXTRACT(YEAR FROM p.fyh_cre)::TEXT || '-' || LPAD(p.numero::TEXT, 4, '0'),
        'cliente',                   c.nombre,
        'grupo_articulo_id',         p.grupo_articulo_id,
        'color',                     vc.color,
        'color_hex',                 vc.color_hex,
        'valor',                     vclr.valor,
        'tenido',                    t.tenido,
        'ancho',                     p.ancho,
        'malla',                     p.malla,
        'rendimiento',               p.rendimiento,
        'articulo',                  ga.nombre,
        'fibra',                     p.fibra,
        'flg_antipilling',           p.flg_antipilling,
        'flg_doble_bolsa',           p.flg_doble_bolsa,
        'observacion',               p.observacion,
        'total_rollos',              rp.total_rollos,
        'cantidad_total',            rp.total_rollos,
        'cantidad_regular',          rp.cantidad_regular,
        'cantidad_rib',              rp.cantidad_rib,
        'entregas',                     gp.entregas,
        'ejecucion_fyh_inicio',      ppe.fyh_inicio,
        -- Lavado maquina fields (null when actividad_tipo = 'partida_paso')
        'lavado_id',                 lm.id,
        'lavado_estado',             lm.estado,
        'lavado_nota',               lm.nota,
        'lavado_fyh_inicio',         lm.fyh_inicio,
        'lavado_fyh_fin',            lm.fyh_fin,
        'empleado_id',               lm.empleado_id,
        'empleado',                  NULLIF(TRIM(COALESCE(emp.nombre,'') || ' ' || COALESCE(emp.apellido,'')), ''),
        'receta_lavado_maquina_id',  lm.receta_id,
        'tipo_lavado',               tlm.nombre,
        'color_origen',              vo.valor,
        'color_destino',             vd.valor
    ) AS row_obj
    FROM mes.programacion prog
    LEFT JOIN mes.partida_paso pp         ON prog.actividad_tipo = 'partida_paso' AND pp.id = prog.actividad_id
    LEFT JOIN mes.operacion o             ON o.id = pp.operacion_id
    LEFT JOIN receta.tenido rt            ON rt.id = pp.receta_id
    LEFT JOIN tipo_receta tr              ON tr.id = rt.tipo_receta_id
    LEFT JOIN mes.partida p               ON p.id = pp.partida_id
    LEFT JOIN tenido t                    ON t.id = p.tenido_id
    LEFT JOIN tercero c                   ON c.id = p.tercero_id
    LEFT JOIN vw_colores vc               ON vc.color_x_cliente_id = p.color_x_cliente_id
    LEFT JOIN color_x_cliente cxc         ON cxc.id = p.color_x_cliente_id
    LEFT JOIN public.valor vclr           ON vclr.id = cxc.valor_id
    LEFT JOIN grupo_articulo ga            ON ga.id         = p.grupo_articulo_id
    LEFT JOIN rollos_partida rp           ON rp.partida_id = p.id
    LEFT JOIN entregas_partida gp            ON gp.partida_id = p.id
    LEFT JOIN mes.lavado_maquina lm       ON prog.actividad_tipo = 'LAVADO_MAQUINA' AND lm.id = prog.actividad_id
    LEFT JOIN receta.lavado_maquina rlm   ON rlm.id = lm.receta_id
    LEFT JOIN tipo_lavado_maquina tlm     ON tlm.id = rlm.tipo_lavado_mq_id
    LEFT JOIN public.valor vo             ON vo.id  = rlm.valor_origen_id
    LEFT JOIN public.valor vd             ON vd.id  = rlm.valor_destino_id
    LEFT JOIN mes.empleado emp            ON emp.id = lm.empleado_id
    LEFT JOIN mes.partida_paso_ejecucion ppe ON prog.actividad_tipo = 'partida_paso' AND ppe.partida_paso_id = pp.id AND ppe.estado = 'EN_PROCESO'
    WHERE prog.fecha = p_fecha
    ORDER BY prog.maquina_id, prog.secuencia
) sub;
$$;


ALTER FUNCTION mes.get_programacion_diaria(p_fecha date) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.get_proyeccion(date, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.get_proyeccion(p_fecha date, p_horas jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'mes'
    AS $$
    WITH base AS MATERIALIZED (
        SELECT * FROM mes.get_proyeccion_tenido(p_fecha, p_horas)
    ),
    resumen AS (
        SELECT
            m.id                                                AS maquina_id,
            m.codigo                                            AS maquina_codigo,
            m.nombre,
            COALESCE(ROUND(SUM(b.produccion_dia),   2), 0)     AS produccion_dia,
            COALESCE(ROUND(SUM(b.produccion_total), 2), 0)     AS produccion_total
        FROM base b
        JOIN mes.maquina m ON m.id = b.maquina_id
        GROUP BY ROLLUP((m.id, m.codigo, m.nombre))
        ORDER BY m.id NULLS LAST
    )
    SELECT jsonb_build_object(
        'detail',  COALESCE((SELECT jsonb_agg(row_to_json(b)) FROM base    b), '[]'),
        'resumen', COALESCE((SELECT jsonb_agg(row_to_json(r)) FROM resumen r), '[]')
    );
$$;


ALTER FUNCTION mes.get_proyeccion(p_fecha date, p_horas jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.get_proyeccion_tenido(date, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.get_proyeccion_tenido(p_fecha date, p_horas jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(fecha date, maquina_id integer, secuencia smallint, tipo_registro text, actividad_id bigint, color text, tenido text, valor text, flg_antipilling boolean, kilos_raw numeric, kilos numeric, duracion interval, fyh_inicio timestamp with time zone, hora_inicio interval, hora_fin interval, produccion_dia numeric, produccion_total numeric)
    LANGUAGE sql STABLE
    AS $$
    SELECT
        v.fecha,
        v.maquina_id,
        v.secuencia,
        v.tipo_registro,
        v.actividad_id,
        v.color,
        v.tenido,
        v.valor,
        v.flg_antipilling,
        v.kilos_raw,
        v.kilos,
        v.duracion,
        v.fyh_inicio,
        -- Shift start for this machine (default 07:00 if not supplied)
        make_interval(
            hours => EXTRACT(hour   FROM COALESCE(
                (p_horas->>(v.maquina_id::text))::time, '07:00'::time
            ))::int,
            mins  => EXTRACT(minute FROM COALESCE(
                (p_horas->>(v.maquina_id::text))::time, '07:00'::time
            ))::int
        ) + v.offset_inicio                                 AS hora_inicio,
        make_interval(
            hours => EXTRACT(hour   FROM COALESCE(
                (p_horas->>(v.maquina_id::text))::time, '07:00'::time
            ))::int,
            mins  => EXTRACT(minute FROM COALESCE(
                (p_horas->>(v.maquina_id::text))::time, '07:00'::time
            ))::int
        ) + v.offset_fin                                    AS hora_fin,
        v.produccion_dia,
        v.produccion_total
    FROM mes.vw_proyeccion_tenido v
    WHERE v.fecha = p_fecha
    ORDER BY v.maquina_id, v.secuencia;
$$;


ALTER FUNCTION mes.get_proyeccion_tenido(p_fecha date, p_horas jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.get_reporte_matizados(date, date, integer, integer, boolean)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.get_reporte_matizados(p_fecha_desde date, p_fecha_hasta date, p_cliente_id integer DEFAULT NULL::integer, p_insumo_id integer DEFAULT NULL::integer, p_incluir_reversiones boolean DEFAULT true) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'mes', 'inventario'
    AS $$
SELECT COALESCE(jsonb_agg(row_obj ORDER BY fecha, partida_numero, insumo, movimiento_id), '[]'::jsonb)
FROM (
    SELECT jsonb_build_object(
        'movimiento_id',    m.id,
        'fecha',            DATE(m.fecha_hora AT TIME ZONE 'America/Lima'),
        'fyh_movimiento',   m.fecha_hora,
        'turno',            CASE WHEN EXTRACT(HOUR FROM m.fecha_hora AT TIME ZONE 'America/Lima') BETWEEN 7 AND 18
                                 THEN 'DIA' ELSE 'NOCHE' END,
        'ejecucion_id',     ppe.id,
        'partida_id',       p.id,
        'partida_codigo',   EXTRACT(YEAR FROM p.fyh_cre)::TEXT || '-' || LPAD(p.numero::TEXT, 4, '0'),
        'cliente',          c.nombre,
        'es_reproceso',     p.partida_origen_id IS NOT NULL,
        'operacion_id',     pp.operacion_id,
        'operacion',        o.nombre,
        'operacion_codigo', o.codigo,
        'maquina_id',       ppe.maquina_id,
        'maquina',          mq.nombre,
        'insumo_id',        i.id,
        'insumo_codigo',    i.codigo,
        'insumo',           i.nombre,
        'unidad',           u.codigo,
        'es_reversion',     t.factor = 1,
        -- consumo positivo, reversión negativo (firma por -factor)
        'cantidad',         ROUND((m.cantidad * (-t.factor))::numeric, 5),
        'precio_unitario',  m.precio_unitario,
        'monto',            ROUND((m.cantidad * (-t.factor) * COALESCE(m.precio_unitario, 0))::numeric, 4)
    )                 AS row_obj,
    DATE(m.fecha_hora AT TIME ZONE 'America/Lima') AS fecha,
    p.numero          AS partida_numero,
    i.nombre          AS insumo,
    m.id              AS movimiento_id
    FROM inventario.item_movimientos m
    JOIN inventario.item_movimiento_tipo   t  ON t.id  = m.item_movimiento_tipo_id
    JOIN inventario.item_movimiento_motivo mo ON mo.id = m.motivo_id AND mo.codigo = 'MATIZADO'
    JOIN item    i ON i.id = m.item_id
    JOIN unidad  u ON u.id = i.unidad_id
    JOIN mes.partida_paso_ejecucion ppe ON ppe.id = m.documento_id
                                       AND m.documento_tipo = 'partida_paso_ejecucion'
    JOIN mes.partida_paso pp ON pp.id = ppe.partida_paso_id
    JOIN mes.partida      p  ON p.id  = pp.partida_id
    JOIN mes.operacion    o  ON o.id  = pp.operacion_id
    LEFT JOIN mes.maquina mq ON mq.id = ppe.maquina_id
    LEFT JOIN tercero     c  ON c.id  = p.tercero_id
    WHERE DATE(m.fecha_hora AT TIME ZONE 'America/Lima') BETWEEN p_fecha_desde AND p_fecha_hasta
      AND (p_cliente_id IS NULL OR p.tercero_id = p_cliente_id)
      AND (p_insumo_id  IS NULL OR m.item_id    = p_insumo_id)
      AND (p_incluir_reversiones OR t.factor = -1)   -- factor -1 = consumo; +1 = reversión
) sub;
$$;


ALTER FUNCTION mes.get_reporte_matizados(p_fecha_desde date, p_fecha_hasta date, p_cliente_id integer, p_insumo_id integer, p_incluir_reversiones boolean) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.get_reporte_produccion_acabado(date, date, integer, boolean)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.get_reporte_produccion_acabado(p_fecha_desde date, p_fecha_hasta date, p_operacion_id integer DEFAULT NULL::integer, p_solo_reproceso boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'mes', 'inventario'
    AS $$
WITH ejecuciones AS (
    SELECT
        ppe.id              AS ejecucion_id,
        ppe.fyh_inicio,
        ppe.fyh_fin,
        ppe.fyh_inicio AT TIME ZONE 'America/Lima' AS inicio_local,
        ppe.fyh_fin    AT TIME ZONE 'America/Lima' AS fin_local,
        ppe.maquina_id,
        pp.operacion_id,
        p.id                AS partida_id,
        p.numero            AS partida_numero,
        p.fyh_cre           AS partida_fyh_cre,
        p.tercero_id,
        p.partida_origen_id,
        ppe.cantidad_rollos AS rollos_total,
        ppe.peso_kg         AS kg_total,
        EXTRACT(EPOCH FROM (ppe.fyh_fin - ppe.fyh_inicio)) AS duracion_total_seg
    FROM mes.partida_paso_ejecucion ppe
    JOIN mes.partida_paso pp ON pp.id = ppe.partida_paso_id
    JOIN mes.partida p       ON p.id  = pp.partida_id
    WHERE ppe.estado    = 'COMPLETADO'
      AND ppe.fyh_fin   IS NOT NULL
      AND (p_operacion_id   IS NULL OR pp.operacion_id = p_operacion_id)
      AND (p_solo_reproceso IS NULL
           OR (p_solo_reproceso = TRUE  AND p.partida_origen_id IS NOT NULL)
           OR (p_solo_reproceso = FALSE AND p.partida_origen_id IS     NULL))
      -- Loose pre-filter (±1 día); la atribución exacta al día se hace por segmento.
      AND DATE(ppe.fyh_inicio AT TIME ZONE 'America/Lima') <= p_fecha_hasta + 1
      AND DATE(ppe.fyh_fin   AT TIME ZONE 'America/Lima') >= p_fecha_desde - 1
),
-- Expande cada ejecución en un segmento por día de producción (corte 07:00).
-- Genera inicios de día desde las 07:00 del día previo al inicio, en pasos
-- de 24 h → siempre en 07:00; el día = fecha del inicio del segmento.
segmentos AS (
    SELECT
        e.*,
        slot.dia_start::date                                 AS dia,
        GREATEST(e.inicio_local, slot.dia_start)             AS seg_inicio,
        LEAST(e.fin_local, slot.dia_start + interval '24 hours') AS seg_fin
    FROM ejecuciones e
    CROSS JOIN LATERAL generate_series(
        date_trunc('day', e.inicio_local) - interval '17 hours',  -- 07:00 del día previo
        e.fin_local,
        interval '24 hours'
    ) AS slot(dia_start)
    -- fecha = día de producción (07:00→07:00); filtro exacto al rango pedido
    WHERE slot.dia_start::date BETWEEN p_fecha_desde AND p_fecha_hasta
      -- descarta segmentos sin solape real
      AND LEAST(e.fin_local, slot.dia_start + interval '24 hours')
        > GREATEST(e.inicio_local, slot.dia_start)
),
segmentos_fraccion AS (
    SELECT
        s.*,
        CASE
            WHEN s.duracion_total_seg > 0
            THEN EXTRACT(EPOCH FROM (s.seg_fin - s.seg_inicio)) / s.duracion_total_seg
            ELSE 1.0
        END AS fraccion
    FROM segmentos s
),
-- Reparto de rollos por RESTO MAYOR (Hamilton) dentro de cada ejecución:
-- los enteros por segmento suman EXACTO al total en rango de la ejecución,
-- sin inflar (redondear cada segmento por separado sí inflaba).
--   rollos_target   = entero objetivo del tramo en rango
--   rollos_base     = piso por segmento
--   leftover R      = rollos_target - Σ pisos; va a los R restos mayores
-- kg queda continuo (sin redondear aquí); se formatea al mostrar.
segmentos_rollos AS (
    SELECT
        sf.*,
        FLOOR(COALESCE(sf.rollos_total, 0) * sf.fraccion)::int AS rollos_base,
        (ROUND(SUM(COALESCE(sf.rollos_total, 0) * sf.fraccion)
               OVER (PARTITION BY sf.ejecucion_id)))::int      AS rollos_target,
        (SUM(FLOOR(COALESCE(sf.rollos_total, 0) * sf.fraccion))
               OVER (PARTITION BY sf.ejecucion_id))::int       AS rollos_base_sum,
        ROW_NUMBER() OVER (
            PARTITION BY sf.ejecucion_id
            ORDER BY (COALESCE(sf.rollos_total, 0) * sf.fraccion)
                     - FLOOR(COALESCE(sf.rollos_total, 0) * sf.fraccion) DESC,
                     sf.seg_inicio
        )                                                       AS rem_rank
    FROM segmentos_fraccion sf
)
SELECT COALESCE(jsonb_agg(row_obj ORDER BY dia, operacion, ejecucion_id), '[]'::jsonb)
FROM (
    SELECT jsonb_build_object(
        'fecha',              sr.dia,
        'ejecucion_id',       sr.ejecucion_id,
        'operacion_id',       sr.operacion_id,
        'operacion',          o.nombre,
        'operacion_codigo',   o.codigo,
        'maquina_id',         sr.maquina_id,
        'maquina',            m.nombre,
        'partida_id',         sr.partida_id,
        'partida_codigo',     EXTRACT(YEAR FROM sr.partida_fyh_cre)::TEXT || '-' || LPAD(sr.partida_numero::TEXT, 4, '0'),
        'cliente',            c.nombre,
        'es_reproceso',       sr.partida_origen_id IS NOT NULL,
        'partida_origen_id',  sr.partida_origen_id,
        -- base + 1 si el segmento está entre los R restos mayores de la ejecución
        'rollos',             sr.rollos_base
                              + CASE WHEN sr.rem_rank <= (sr.rollos_target - sr.rollos_base_sum)
                                     THEN 1 ELSE 0 END,
        'kg',                 ROUND((COALESCE(sr.kg_total, 0) * sr.fraccion)::numeric, 4),
        'fyh_inicio',         sr.fyh_inicio,
        'fyh_fin',            sr.fyh_fin,
        'fraccion',           ROUND(sr.fraccion::numeric, 4)
    )                    AS row_obj,
    sr.dia               AS dia,
    o.nombre             AS operacion,
    sr.ejecucion_id      AS ejecucion_id
    FROM segmentos_rollos sr
    JOIN mes.operacion o  ON o.id  = sr.operacion_id
    JOIN mes.partida p    ON p.id  = sr.partida_id
    LEFT JOIN mes.maquina m  ON m.id  = sr.maquina_id
    LEFT JOIN tercero c   ON c.id  = sr.tercero_id
) sub;
$$;


ALTER FUNCTION mes.get_reporte_produccion_acabado(p_fecha_desde date, p_fecha_hasta date, p_operacion_id integer, p_solo_reproceso boolean) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.get_reporte_produccion_acabado_turno(date, date, integer, boolean)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.get_reporte_produccion_acabado_turno(p_fecha_desde date, p_fecha_hasta date, p_operacion_id integer DEFAULT NULL::integer, p_solo_reproceso boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'mes', 'inventario'
    AS $$
WITH ejecuciones AS (
    SELECT
        ppe.id              AS ejecucion_id,
        ppe.fyh_inicio,
        ppe.fyh_fin,
        ppe.fyh_inicio AT TIME ZONE 'America/Lima' AS inicio_local,
        ppe.fyh_fin    AT TIME ZONE 'America/Lima' AS fin_local,
        ppe.maquina_id,
        pp.operacion_id,
        p.id                AS partida_id,
        p.numero            AS partida_numero,
        p.fyh_cre           AS partida_fyh_cre,
        p.tercero_id,
        p.partida_origen_id,
        ppe.cantidad_rollos AS rollos_total,
        ppe.peso_kg         AS kg_total,
        EXTRACT(EPOCH FROM (ppe.fyh_fin - ppe.fyh_inicio)) AS duracion_total_seg
    FROM mes.partida_paso_ejecucion ppe
    JOIN mes.partida_paso pp ON pp.id = ppe.partida_paso_id
    JOIN mes.partida p       ON p.id  = pp.partida_id
    WHERE ppe.estado    = 'COMPLETADO'
      AND ppe.fyh_fin   IS NOT NULL
      AND (p_operacion_id   IS NULL OR pp.operacion_id = p_operacion_id)
      AND (p_solo_reproceso IS NULL
           OR (p_solo_reproceso = TRUE  AND p.partida_origen_id IS NOT NULL)
           OR (p_solo_reproceso = FALSE AND p.partida_origen_id IS     NULL))
      -- Loose pre-filter (±1 día); la atribución exacta al turno se hace por segmento.
      AND DATE(ppe.fyh_inicio AT TIME ZONE 'America/Lima') <= p_fecha_hasta + 1
      AND DATE(ppe.fyh_fin   AT TIME ZONE 'America/Lima') >= p_fecha_desde - 1
),
-- Expande cada ejecución en un segmento por turno que atraviesa.
-- Genera límites de turno desde las 19:00 del día previo al inicio,
-- en pasos de 12 h → 19:00, 07:00, 19:00, ... (siempre en :00).
segmentos AS (
    SELECT
        e.*,
        slot.shift_start::date                                AS dia,
        CASE WHEN EXTRACT(HOUR FROM slot.shift_start) = 7
             THEN 'DIA' ELSE 'NOCHE' END                      AS turno,
        GREATEST(e.inicio_local, slot.shift_start)            AS seg_inicio,
        LEAST(e.fin_local, slot.shift_start + interval '12 hours') AS seg_fin
    FROM ejecuciones e
    CROSS JOIN LATERAL generate_series(
        date_trunc('day', e.inicio_local) - interval '5 hours',  -- 19:00 del día previo
        e.fin_local,
        interval '12 hours'
    ) AS slot(shift_start)
    -- fecha = día de inicio del turno; filtro exacto al rango pedido
    WHERE slot.shift_start::date BETWEEN p_fecha_desde AND p_fecha_hasta
      -- descarta segmentos sin solape real
      AND LEAST(e.fin_local, slot.shift_start + interval '12 hours')
        > GREATEST(e.inicio_local, slot.shift_start)
),
segmentos_fraccion AS (
    SELECT
        s.*,
        CASE
            WHEN s.duracion_total_seg > 0
            THEN EXTRACT(EPOCH FROM (s.seg_fin - s.seg_inicio)) / s.duracion_total_seg
            ELSE 1.0
        END AS fraccion
    FROM segmentos s
),
-- Reparto de rollos por RESTO MAYOR (Hamilton) dentro de cada ejecución:
-- los enteros por segmento suman EXACTO al total en rango de la ejecución,
-- sin inflar (redondear cada segmento por separado sí inflaba).
-- kg queda continuo (sin redondear aquí); se formatea al mostrar.
segmentos_rollos AS (
    SELECT
        sf.*,
        FLOOR(COALESCE(sf.rollos_total, 0) * sf.fraccion)::int AS rollos_base,
        (ROUND(SUM(COALESCE(sf.rollos_total, 0) * sf.fraccion)
               OVER (PARTITION BY sf.ejecucion_id)))::int      AS rollos_target,
        (SUM(FLOOR(COALESCE(sf.rollos_total, 0) * sf.fraccion))
               OVER (PARTITION BY sf.ejecucion_id))::int       AS rollos_base_sum,
        ROW_NUMBER() OVER (
            PARTITION BY sf.ejecucion_id
            ORDER BY (COALESCE(sf.rollos_total, 0) * sf.fraccion)
                     - FLOOR(COALESCE(sf.rollos_total, 0) * sf.fraccion) DESC,
                     sf.seg_inicio
        )                                                       AS rem_rank
    FROM segmentos_fraccion sf
)
SELECT COALESCE(jsonb_agg(row_obj ORDER BY dia, turno, operacion, ejecucion_id), '[]'::jsonb)
FROM (
    SELECT jsonb_build_object(
        'fecha',              sr.dia,
        'turno',              sr.turno,
        'ejecucion_id',       sr.ejecucion_id,
        'operacion_id',       sr.operacion_id,
        'operacion',          o.nombre,
        'operacion_codigo',   o.codigo,
        'maquina_id',         sr.maquina_id,
        'maquina',            m.nombre,
        'partida_id',         sr.partida_id,
        'partida_codigo',     EXTRACT(YEAR FROM sr.partida_fyh_cre)::TEXT || '-' || LPAD(sr.partida_numero::TEXT, 4, '0'),
        'cliente',            c.nombre,
        'es_reproceso',       sr.partida_origen_id IS NOT NULL,
        'partida_origen_id',  sr.partida_origen_id,
        -- base + 1 si el segmento está entre los R restos mayores de la ejecución
        'rollos',             sr.rollos_base
                              + CASE WHEN sr.rem_rank <= (sr.rollos_target - sr.rollos_base_sum)
                                     THEN 1 ELSE 0 END,
        'kg',                 ROUND((COALESCE(sr.kg_total, 0) * sr.fraccion)::numeric, 4),
        'fyh_inicio',         sr.fyh_inicio,
        'fyh_fin',            sr.fyh_fin,
        'fraccion',           ROUND(sr.fraccion::numeric, 4)
    )                    AS row_obj,
    sr.dia               AS dia,
    sr.turno             AS turno,
    o.nombre             AS operacion,
    sr.ejecucion_id      AS ejecucion_id
    FROM segmentos_rollos sr
    JOIN mes.operacion o  ON o.id  = sr.operacion_id
    JOIN mes.partida p    ON p.id  = sr.partida_id
    LEFT JOIN mes.maquina m  ON m.id  = sr.maquina_id
    LEFT JOIN tercero c   ON c.id  = sr.tercero_id
) sub;
$$;


ALTER FUNCTION mes.get_reporte_produccion_acabado_turno(p_fecha_desde date, p_fecha_hasta date, p_operacion_id integer, p_solo_reproceso boolean) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.guardar_programacion(date, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.guardar_programacion(p_fecha date, p_programaciones jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'mes'
    AS $$
DECLARE
    v_usr_id          INT := get_user_id();
    v_invalid_lavados JSONB;
    v_partida_id      BIGINT;
BEGIN
    IF NOT jwt_has_permission('produccion.programar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.programar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- 1b. Validate every element carries a non-null actividad_id (stale client
    -- state / a slot never bound to a real paso/lavado would otherwise surface
    -- as an opaque NOT NULL constraint violation on mes.programacion).
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_programaciones) elem
        WHERE elem->>'actividad_id' IS NULL
    ) THEN
        RAISE EXCEPTION
            'Se recibió una actividad sin actividad_id (estado local corrupto). Recargue el tablero e intente de nuevo.';
    END IF;

    -- 2. Validate lavados: must not be COMPLETADO
    SELECT jsonb_agg(jsonb_build_object('actividad_id', lm.id, 'estado', lm.estado))
    INTO v_invalid_lavados
    FROM jsonb_array_elements(p_programaciones) elem
    JOIN mes.lavado_maquina lm ON lm.id = (elem->>'actividad_id')::BIGINT
    WHERE elem->>'actividad_tipo' = 'LAVADO_MAQUINA'
      AND lm.estado = 'COMPLETADO';

    IF v_invalid_lavados IS NOT NULL THEN
        RAISE EXCEPTION 'Lavados no programables (ya COMPLETADO): %', v_invalid_lavados;
    END IF;

    -- 3. Full replace for the date
    DELETE FROM mes.programacion WHERE fecha = p_fecha;

    INSERT INTO mes.programacion (actividad_tipo, actividad_id, maquina_id, fecha, secuencia, nota, relacion_bano)
    SELECT
        elem->>'actividad_tipo',
        (elem->>'actividad_id')::BIGINT,
        (elem->>'maquina_id')::INT,
        p_fecha,
        (elem->>'secuencia')::SMALLINT,
        elem->>'nota',
        (elem->>'relacion_bano')::NUMERIC
    FROM jsonb_array_elements(p_programaciones) elem;

    -- Advance/revert PLANIFICADA ↔ PROGRAMADA for every affected partida.
    -- actualizar_estado_partida is the single owner of estado_produccion.
    FOR v_partida_id IN
        SELECT DISTINCT pp.partida_id
        FROM mes.partida_paso pp
        WHERE pp.id IN (
            SELECT (elem->>'actividad_id')::BIGINT
            FROM jsonb_array_elements(p_programaciones) elem
            WHERE elem->>'actividad_tipo' = 'partida_paso'
        )
        UNION
        SELECT DISTINCT pp.partida_id
        FROM mes.partida_paso pp
        JOIN mes.programacion prog ON prog.actividad_tipo = 'partida_paso'
                                  AND prog.actividad_id = pp.id
        WHERE prog.fecha = p_fecha
    LOOP
        PERFORM mes.actualizar_estado_partida(v_partida_id);
    END LOOP;

    RETURN 'Programación guardada correctamente para ' || p_fecha;
END;
$$;


ALTER FUNCTION mes.guardar_programacion(p_fecha date, p_programaciones jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.iniciar_lavado_maquina(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.iniciar_lavado_maquina(p_id bigint, p_datos jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes', 'receta'
    AS $$
DECLARE
    v_usr_id INT := get_user_id();
    v_lavado mes.lavado_maquina%ROWTYPE;
BEGIN
    IF NOT jwt_has_permission('produccion.ejecutar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.ejecutar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO v_lavado FROM mes.lavado_maquina WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'lavado_maquina id=% no encontrado.', p_id;
    END IF;

    IF v_lavado.estado <> 'PENDIENTE' THEN
        RAISE EXCEPTION 'lavado_maquina id=% en estado % — se esperaba PENDIENTE.', p_id, v_lavado.estado;
    END IF;

    UPDATE mes.lavado_maquina SET
        estado      = 'EN_PROCESO',
        fyh_inicio  = COALESCE((p_datos->>'fyh_inicio')::TIMESTAMPTZ, now()),
        empleado_id = COALESCE((p_datos->>'empleado_id')::SMALLINT, empleado_id),
        usr_mod     = v_usr_id,
        fyh_mod     = now()
    WHERE id = p_id;
END;$$;


ALTER FUNCTION mes.iniciar_lavado_maquina(p_id bigint, p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.iniciar_paso(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.iniciar_paso(p_paso_id bigint, p_datos jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'mes'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id          int := get_user_id();
    v_partida_id        bigint;
    v_op_nombre       text;
    v_secuencia       smallint;
    v_requiere_receta boolean;
    v_requiere_maquina boolean;
    v_receta_id       int;
    v_maquina_id      int;
    v_ejecucion_id    bigint;
BEGIN
    IF NOT jwt_has_permission('produccion.ejecutar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.ejecutar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT pp.partida_id, o.nombre, pp.secuencia, o.requiere_receta, o.requiere_maquina, pp.receta_id
    INTO v_partida_id, v_op_nombre, v_secuencia, v_requiere_receta, v_requiere_maquina, v_receta_id
    FROM mes.partida_paso pp
    JOIN mes.operacion o ON o.id = pp.operacion_id
    WHERE pp.id = p_paso_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Paso con ID % no encontrado.', p_paso_id;
    END IF;

    -- Guard: paso already has an active or completed run
    IF EXISTS (
        SELECT 1 FROM mes.partida_paso_ejecucion
        WHERE partida_paso_id = p_paso_id AND estado IN ('EN_PROCESO','OMITIDO')
    ) THEN
        RAISE EXCEPTION 'El paso % ya tiene una ejecución en curso o fue omitido.', v_op_nombre;
    END IF;

    IF v_requiere_receta AND v_receta_id IS NULL THEN
        RAISE EXCEPTION 'No se puede iniciar el paso % porque no tiene receta asignada.', v_op_nombre;
    END IF;

    -- Resolve machine: explicit override → scheduled programacion → fail
    v_maquina_id := COALESCE(
        (p_datos->>'maquina_id')::INT,
        (SELECT maquina_id FROM mes.programacion WHERE id = (p_datos->>'programacion_id')::BIGINT)
    );

    IF v_requiere_maquina AND v_maquina_id IS NULL THEN
        RAISE EXCEPTION 'No se puede iniciar el paso % porque no tiene máquina (indique maquina_id o programe el paso primero).', v_op_nombre;
    END IF;

    -- Guard: previous pasos in sequence must be complete and have no active run
    IF EXISTS (
        SELECT 1 FROM mes.partida_paso pp
        WHERE pp.partida_id = v_partida_id
          AND pp.secuencia < v_secuencia
          AND (
              NOT EXISTS (
                  SELECT 1 FROM mes.partida_paso_ejecucion pe
                  WHERE pe.partida_paso_id = pp.id AND pe.estado IN ('COMPLETADO','OMITIDO')
              )
              OR EXISTS (
                  SELECT 1 FROM mes.partida_paso_ejecucion pe
                  WHERE pe.partida_paso_id = pp.id AND pe.estado = 'EN_PROCESO'
              )
          )
    ) THEN
        RAISE EXCEPTION 'No se puede iniciar el paso % porque hay pasos anteriores no completados o en ejecución.', v_op_nombre;
    END IF;

    IF v_requiere_receta AND NOT EXISTS (
        SELECT 1 FROM mes.partida_componente WHERE partida_id = v_partida_id
    ) THEN
        RAISE EXCEPTION 'No se puede iniciar el paso % porque la orden no tiene rollos asignados.', v_op_nombre;
    END IF;

    -- Create execution run record.
    -- fyh_inicio / fyh_cre accept a historical timestamp for backfill; live callers omit it → NOW().
    INSERT INTO mes.partida_paso_ejecucion(partida_paso_id, estado, maquina_id, empleado_id, fyh_inicio, programacion_id, receta_id, relacion_bano_real, usr_cre, fyh_cre)
    VALUES (
        p_paso_id, 'EN_PROCESO',
        v_maquina_id,
        (p_datos->>'empleado_id')::SMALLINT,
        COALESCE((p_datos->>'fyh_inicio')::TIMESTAMPTZ, NOW()),
        (p_datos->>'programacion_id')::BIGINT,
        v_receta_id,
        -- pre-populate from scheduled custom ratio, else machine standard (operator overrides at finalization)
        COALESCE(
            (p_datos->>'relacion_bano')::NUMERIC,
            (SELECT COALESCE(prog.relacion_bano, m.relacion_bano)
             FROM mes.programacion prog
             JOIN mes.maquina m ON m.id = prog.maquina_id
             WHERE prog.id = (p_datos->>'programacion_id')::BIGINT),
            (SELECT relacion_bano FROM mes.maquina WHERE id = v_maquina_id)
        ),
        v_usr_id,
        COALESCE((p_datos->>'fyh_inicio')::TIMESTAMPTZ, NOW())
    )
    RETURNING id INTO v_ejecucion_id;

    UPDATE mes.partida_paso SET estado = 'EN_PROCESO', fyh_mod = NOW() WHERE id = p_paso_id;

    PERFORM mes.actualizar_estado_partida(v_partida_id);

    -- Update machine state
    IF v_maquina_id IS NOT NULL THEN
        UPDATE mes.maquina SET estado_actual = 'activa'
        WHERE id = v_maquina_id;
    END IF;

    INSERT INTO notification.notifications(user_id, title, body, tipo, payload)
    SELECT ur.user_id, 'Paso Iniciado',
           COALESCE((SELECT COALESCE(nombre,'Usuario desconocido') || ' ' || apellido
                     FROM usuario WHERE id = v_usr_id), 'sistema')
           || format(' inició el paso %s (orden #%s)', v_op_nombre, v_partida_id), 'info',
           jsonb_build_object('objeto_tipo','partida_paso','paso_id', p_paso_id, 'partida_id', v_partida_id)
    FROM iam.user_rol ur LEFT JOIN iam.rol r ON ur.rol_id = r.id
    WHERE r.code IN ('jefe_planta','supervisor_produccion') AND v_usr_id <> ur.user_id;

    RETURN jsonb_build_object(
        'ejecucion_id', v_ejecucion_id,
        'message', format('Paso %s (#%s) iniciado correctamente.', v_op_nombre, p_paso_id)
    );
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in iniciar_paso - User: %, ID: %, Error: %', v_usr_id, p_paso_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION mes.iniciar_paso(p_paso_id bigint, p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.mover_lotes_reproceso(bigint, integer[], public.calidad_estado_enum)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.mover_lotes_reproceso(p_reproceso_id bigint, p_lote_ids integer[], p_estado_calidad public.calidad_estado_enum DEFAULT NULL::public.calidad_estado_enum) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'mes', 'inventario', 'calidad'
    AS $$
DECLARE
    v_message  text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id   INT := get_user_id();
    v_child    mes.partida%ROWTYPE;
    v_root_id  BIGINT;
    v_bad      INT[];
    v_moved    INT;
    v_remaining INT;
    v_child_deleted BOOLEAN := false;
BEGIN
    IF NOT jwt_has_permission('produccion.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF p_lote_ids IS NULL OR array_length(p_lote_ids, 1) IS NULL THEN
        RAISE EXCEPTION 'Se requiere al menos un lote para mover.';
    END IF;

    v_child   := mes._assert_reproceso_reversible(p_reproceso_id);
    v_root_id := v_child.partida_origen_id;

    -- Every supplied lote must currently be a component of THIS child.
    SELECT ARRAY_AGG(u) INTO v_bad
    FROM UNNEST(p_lote_ids) u
    WHERE NOT EXISTS (
        SELECT 1 FROM mes.partida_componente pc
        WHERE pc.partida_id = p_reproceso_id AND pc.lote_id = u
    );
    IF v_bad IS NOT NULL THEN
        RAISE EXCEPTION 'Lotes % no son componentes del reproceso %.', v_bad, p_reproceso_id
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    -- 1) Move the componente rows back to the root.
    UPDATE mes.partida_componente
    SET partida_id = v_root_id, usr_mod = v_usr_id, fyh_mod = NOW()
    WHERE partida_id = p_reproceso_id
      AND lote_id = ANY(p_lote_ids);
    GET DIAGNOSTICS v_moved = ROW_COUNT;

    -- 2) Restore estado_calidad per roll: explicit override, else the verdict
    --    immediately preceding the rework pull, else PENDIENTE.
    UPDATE inventario.lote l
    SET estado_calidad = COALESCE(
            p_estado_calidad,
            -- last NON-rework verdict (the state before it was wrongly pulled);
            -- exclude REPROCESO/BAJA so we never restore the erroneous verdict.
            (SELECT ci.resultado
             FROM calidad.inspeccion ci
             JOIN mes.partida_paso_ejecucion ppe ON ppe.id = ci.partida_paso_ejecucion_id
             JOIN mes.partida_paso pp ON pp.id = ppe.partida_paso_id
             WHERE ci.lote_id = l.id
               AND pp.partida_id = v_root_id
               AND ci.resultado NOT IN ('REPROCESO','BAJA')
             ORDER BY ci.fyh_cre DESC
             LIMIT 1),
            'PENDIENTE'::calidad_estado_enum
        ),
        usr_mod = v_usr_id, fyh_mod = NOW()
    WHERE l.id = ANY(p_lote_ids);

    -- 3) Delete the erroneous rework verdict rows on the root's pasos for these
    --    rolls (the REPROCESO/BAJA inspection that pulled them in). inspeccion
    --    has no soft-delete, so hard DELETE — the verdict was itself the error.
    DELETE FROM calidad.inspeccion ci
    USING mes.partida_paso_ejecucion ppe, mes.partida_paso pp
    WHERE ci.partida_paso_ejecucion_id = ppe.id
      AND ppe.partida_paso_id = pp.id
      AND pp.partida_id = v_root_id
      AND ci.lote_id = ANY(p_lote_ids)
      AND ci.resultado IN ('REPROCESO','BAJA');

    -- 4) If the child now has no rolls left, soft-delete it (full undo).
    SELECT COUNT(*) INTO v_remaining
    FROM mes.partida_componente WHERE partida_id = p_reproceso_id AND lote_id IS NOT NULL;

    IF v_remaining = 0 THEN
        UPDATE mes.partida
        SET estado_produccion = 'CANCELADA', fyh_elm = NOW(), usr_elm = v_usr_id
        WHERE id = p_reproceso_id;
        v_child_deleted := true;
    END IF;

    -- 5) Recompute partida_detalle roll-count intent on the CHILD only.
    --    The root's partida_detalle is original demand/intent — crear_reproceso
    --    never decremented it when the rolls left, so we must not re-derive it
    --    from components on the way back (that would overwrite demand with a live
    --    component count). Leave the root's detalle untouched.
    IF NOT v_child_deleted THEN
        PERFORM mes._recount_reproceso_detalle(p_reproceso_id);
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('mover_lotes_reproceso', v_usr_id,
            jsonb_build_object('reproceso_id', p_reproceso_id, 'lote_ids', p_lote_ids,
                               'estado_calidad', p_estado_calidad));

    RETURN jsonb_build_object(
        'reproceso_id',    p_reproceso_id,
        'partida_root_id', v_root_id,
        'lotes_movidos',   v_moved,
        'reproceso_anulado', v_child_deleted,
        'message', format('%s rollo(s) devuelto(s) a la partida %s%s.',
                          v_moved, v_root_id,
                          CASE WHEN v_child_deleted
                               THEN format('; reproceso %s anulado (sin rollos)', p_reproceso_id)
                               ELSE '' END)
    );

EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message = MESSAGE_TEXT, v_detail = PG_EXCEPTION_DETAIL,
            v_hint = PG_EXCEPTION_HINT, v_context = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;
        RAISE LOG 'Error in mover_lotes_reproceso - User: %, Reproceso: %, Lotes: %, Error: %, Detail: %',
                  v_usr_id, p_reproceso_id, p_lote_ids, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION mes.mover_lotes_reproceso(p_reproceso_id bigint, p_lote_ids integer[], p_estado_calidad public.calidad_estado_enum) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.omitir_paso(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.omitir_paso(p_paso_id bigint, p_datos jsonb DEFAULT '{}'::jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'mes'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id    int := get_user_id();
    v_partida_id  bigint;
    v_op_nombre text;
    v_secuencia smallint;
BEGIN
    IF NOT jwt_has_permission('produccion.editar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.editar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT pp.partida_id, o.nombre, pp.secuencia
    INTO v_partida_id, v_op_nombre, v_secuencia
    FROM mes.partida_paso pp
    JOIN mes.operacion o ON o.id = pp.operacion_id
    WHERE pp.id = p_paso_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Paso con ID % no encontrado.', p_paso_id;
    END IF;

    IF EXISTS (
        SELECT 1 FROM mes.partida_paso_ejecucion
        WHERE partida_paso_id = p_paso_id AND estado IN ('EN_PROCESO','COMPLETADO')
    ) THEN
        RAISE EXCEPTION 'El paso % ya tiene una ejecución en curso o completada; no se puede omitir.', v_op_nombre;
    END IF;

    IF EXISTS (
        SELECT 1 FROM mes.partida_paso pp
        WHERE pp.partida_id = v_partida_id
          AND pp.secuencia < v_secuencia
          AND (
              NOT EXISTS (
                  SELECT 1 FROM mes.partida_paso_ejecucion pe
                  WHERE pe.partida_paso_id = pp.id AND pe.estado IN ('COMPLETADO','OMITIDO')
              )
              OR EXISTS (
                  SELECT 1 FROM mes.partida_paso_ejecucion pe
                  WHERE pe.partida_paso_id = pp.id AND pe.estado = 'EN_PROCESO'
              )
          )
    ) THEN
        RAISE EXCEPTION 'No se puede omitir el paso % porque hay pasos anteriores no completados o en ejecución.', v_op_nombre;
    END IF;

    INSERT INTO mes.partida_paso_ejecucion(partida_paso_id, estado, fyh_inicio, fyh_fin, notas, usr_cre)
    VALUES (p_paso_id, 'OMITIDO', NOW(), NOW(), p_datos->>'notas', v_usr_id);

    UPDATE mes.partida_paso SET estado = 'OMITIDO', fyh_mod = NOW() WHERE id = p_paso_id;

    PERFORM mes.actualizar_estado_partida(v_partida_id);

    RETURN format('Paso %s (#%s) omitido.', v_op_nombre, p_paso_id);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in omitir_paso - User: %, Paso: %, Error: %', v_usr_id, p_paso_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION mes.omitir_paso(p_paso_id bigint, p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.registrar_consumo_paso(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.registrar_consumo_paso(p_paso_id bigint, p_consumos jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int     := get_user_id();
    v_consumos          jsonb;
    v_consumos_std      jsonb;
    v_egr_tipo_id       smallint;
    v_error_payload     jsonb;
    v_doc_movimiento_id BIGINT;
    v_ejecucion_id      BIGINT;
    v_fung_count        int := 0;
BEGIN
    IF NOT jwt_has_permission('produccion.ejecutar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.ejecutar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT pe.id INTO v_ejecucion_id
    FROM mes.partida_paso_ejecucion pe
    WHERE pe.partida_paso_id = p_paso_id AND pe.estado = 'EN_PROCESO'
    ORDER BY pe.fyh_inicio DESC LIMIT 1;

    IF v_ejecucion_id IS NULL THEN
        RAISE EXCEPTION 'Paso #% no tiene una ejecución EN_PROCESO activa.', p_paso_id;
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_consumo_paso', v_usr_id,
            jsonb_build_object('paso_id', p_paso_id, 'ejecucion_id', v_ejecucion_id, 'consumos', p_consumos));

    SELECT id INTO v_egr_tipo_id
    FROM inventario.item_movimiento_tipo WHERE codigo = 'PROD_CONSUMO';

    -- Convert physical recipe amounts → stock SKU quantities using factor_stock.
    -- The recipe displays diluted/physical amounts; the actual stock unit may differ
    -- (e.g. a 10% solution: factor_stock=10, so 1 kg physical → 10 kg SKU deducted).
    SELECT jsonb_agg(
        jsonb_set(i, '{cantidad}', to_jsonb(
            ((i->>'cantidad')::numeric * COALESCE(iid.factor_stock, 1))
        ))
    )
    INTO p_consumos
    FROM jsonb_array_elements(p_consumos) i
    LEFT JOIN item_insumo_detalle iid ON iid.item_id = (i->>'item_id')::int;

    -- Stock check: fungible items bypass (may go negative)
    -- Excludes chemical reservations held by OTHER still-open pasos from availability
    -- (this paso's own reservation is what's being fulfilled here, not competing demand).
    -- Same active-paso filter as generar_receta's stock gate.
    WITH consumos AS (
        SELECT (i->>'item_id')::int AS item_id, SUM((i->>'cantidad')::numeric) AS cantidad
        FROM jsonb_array_elements(p_consumos) i
        GROUP BY 1
    ),
    reservado_otros AS (
        SELECT pc.item_id, SUM(pc.cantidad_reservada) AS cantidad_reservada
        FROM mes.partida_componente pc
        JOIN mes.partida_paso pp2 ON pp2.id = pc.partida_paso_id
        JOIN mes.partida p2       ON p2.id = pc.partida_id
        WHERE pc.item_id IS NOT NULL
          AND pc.partida_paso_id <> p_paso_id
          AND p2.estado_produccion NOT IN ('CERRADA', 'CANCELADA', 'TECO')
          AND p2.fyh_elm IS NULL
          AND pp2.estado NOT IN ('COMPLETADO', 'OMITIDO')
        GROUP BY pc.item_id
    ),
    errores AS (
        SELECT c.item_id, it.nombre AS item_nombre, c.cantidad,
               COALESCE(sg.cantidad_total, 0) AS cantidad_disponible,
               COALESCE(ro.cantidad_reservada, 0) AS reservado_otros_pasos,
               COALESCE(sg.cantidad_total, 0) - COALESCE(ro.cantidad_reservada, 0) AS stock_neto
        FROM consumos c
        LEFT JOIN inventario.vw_stock_items sg ON sg.item_id = c.item_id
        LEFT JOIN reservado_otros ro ON ro.item_id = c.item_id
        JOIN item it ON it.id = c.item_id
        WHERE COALESCE(sg.cantidad_total, 0) - COALESCE(ro.cantidad_reservada, 0) < c.cantidad
          AND it.flg_fungible = FALSE
    )
    SELECT jsonb_agg(jsonb_build_object(
        'item_id', item_id, 'item_nombre', item_nombre,
        'saldo_disponible', cantidad_disponible,
        'reservado_otros_pasos', reservado_otros_pasos,
        'stock_neto', stock_neto,
        'cantidad_requerida', cantidad
    ))
    INTO v_error_payload FROM errores;

    IF v_error_payload IS NOT NULL THEN
        RAISE EXCEPTION 'Stock insuficiente para emitir la guía'
            USING DETAIL = v_error_payload::text;
    END IF;

    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

    -- ── Non-fungible: FIFO lot resolution ───────────────────────
    SELECT jsonb_agg(i)
    INTO v_consumos_std
    FROM jsonb_array_elements(p_consumos) i
    JOIN item it ON it.id = (i->>'item_id')::int
    WHERE it.flg_fungible = FALSE;

    IF v_consumos_std IS NOT NULL THEN
        v_consumos := mes.calcular_fifo(v_consumos_std);

        INSERT INTO inventario.item_movimientos(
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, cantidad, precio_unitario,
            documento_tipo, documento_id, motivo_id, observacion
        )
        SELECT
            v_doc_movimiento_id,
            (v_consumo->>'item_id')::INT,
            (v_consumo->>'lote_id')::INT,
            v_egr_tipo_id,
            (v_consumo->>'ubicacion_id')::INT,
            (v_consumo->>'cantidad')::NUMERIC,
            (SELECT iv.precio_promedio FROM inventario.item_valoracion iv
             WHERE iv.item_id = (v_consumo->>'item_id')::INT),
            'partida_paso_ejecucion',
            v_ejecucion_id,
            p_consumo.motivo_id,
            p_consumo.observacion
        FROM jsonb_array_elements(v_consumos) v_consumo
        -- motivo_id/observacion taken from first entry per item_id
        JOIN (
            SELECT (pc->>'item_id') AS item_id,
                   MIN((pc->>'motivo_id')::SMALLINT) AS motivo_id,
                   MIN(pc->>'observacion')            AS observacion
            FROM jsonb_array_elements(p_consumos) pc
            GROUP BY pc->>'item_id'
        ) p_consumo ON v_consumo->>'item_id' = p_consumo.item_id;
    END IF;

    -- ── Fungible: lotless consumption ────────────────────────────
    -- Fallback chain for origen_ubicacion_id:
    --   1. highest-balance location from item_saldo
    --   2. last known ingress location from item_movimientos
    --   3. item_tipo.ubicacion_default_id
    --   4. NULL → trigger uses factor=-1, debits item_saldo(item_id, NULL)
    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        origen_ubicacion_id, cantidad, precio_unitario,
        documento_tipo, documento_id, motivo_id, observacion
    )
    SELECT
        v_doc_movimiento_id,
        fung.item_id,
        NULL,
        v_egr_tipo_id,
        COALESCE(
            (SELECT ubicacion_id FROM inventario.item_saldo
             WHERE item_id = fung.item_id
             ORDER BY cantidad_actual DESC LIMIT 1),
            (SELECT im2.origen_ubicacion_id FROM inventario.item_movimientos im2
             WHERE im2.item_id = fung.item_id
               AND im2.origen_ubicacion_id IS NOT NULL
             ORDER BY im2.id DESC LIMIT 1),
            (SELECT ity.ubicacion_default_id FROM item it2
             JOIN item_tipo ity ON ity.id = it2.item_tipo_id
             WHERE it2.id = fung.item_id)
        ),
        fung.cantidad,
        (SELECT precio_promedio FROM inventario.item_valoracion WHERE item_id = fung.item_id),
        'partida_paso_ejecucion',
        v_ejecucion_id,
        pc.motivo_id,
        pc.observacion
    FROM (
        SELECT (i->>'item_id')::int AS item_id,
               SUM((i->>'cantidad')::numeric) AS cantidad
        FROM jsonb_array_elements(p_consumos) i
        JOIN item it ON it.id = (i->>'item_id')::int
        WHERE it.flg_fungible = TRUE
        GROUP BY 1
    ) fung
    JOIN (
        SELECT (pc->>'item_id') AS item_id,
               MIN((pc->>'motivo_id')::SMALLINT) AS motivo_id,
               MIN(pc->>'observacion')            AS observacion
        FROM jsonb_array_elements(p_consumos) pc
        GROUP BY pc->>'item_id'
    ) pc ON fung.item_id::text = pc.item_id;

    GET DIAGNOSTICS v_fung_count = ROW_COUNT;

    RETURN format('%s consumos registrados para paso #%s.',
                  COALESCE(jsonb_array_length(v_consumos), 0) + v_fung_count,
                  p_paso_id);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_consumo_paso - User: %, paso: %, Error: %, Detail: %',
              v_usr_id, p_paso_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION mes.registrar_consumo_paso(p_paso_id bigint, p_consumos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.registrar_ejecucion_partida(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.registrar_ejecucion_partida(p_data jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'mes'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id           INT := get_user_id();
    v_partida_id         INT;
    v_paso             JSONB;
    v_paso_id          BIGINT;
    v_ejecucion_id     BIGINT;
    v_receta_id        INT;
    v_paso_count       INT := 0;
    v_already_executed BIGINT;
    v_rollos_asignados INT;
    v_overflow_paso    BIGINT;
BEGIN
    IF NOT jwt_has_permission('produccion.ejecutar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.ejecutar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    v_partida_id := (p_data->>'partida_id')::INT;

    IF v_partida_id IS NULL THEN
        RAISE EXCEPTION 'partida_id es requerido.';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM mes.partida WHERE id = v_partida_id) THEN
        RAISE EXCEPTION 'Orden de producción % no encontrada.', v_partida_id;
    END IF;

    SELECT COUNT(*) INTO v_rollos_asignados
    FROM mes.partida_componente
    WHERE partida_id = v_partida_id AND lote_id IS NOT NULL;
    IF jsonb_array_length(p_data->'pasos') = 0 THEN
        RAISE EXCEPTION 'Se requiere al menos un paso en p_data.pasos.';
    END IF;

    -- Idempotency guard: reject exact duplicate runs (same paso_id + fyh_inicio + maquina_id).
    -- Allows multiple runs per paso: interrupted/restarted steps and parallel runs on different machines.
    SELECT pe.partida_paso_id INTO v_already_executed
    FROM mes.partida_paso_ejecucion pe
    JOIN (
        SELECT (el->>'paso_id')::BIGINT         AS paso_id,
               (el->>'fyh_inicio')::TIMESTAMPTZ AS fyh_inicio,
               (el->>'maquina_id')::INT         AS maquina_id
        FROM jsonb_array_elements(p_data->'pasos') el
    ) submitted ON submitted.paso_id   = pe.partida_paso_id
               AND submitted.fyh_inicio = pe.fyh_inicio
               AND submitted.maquina_id IS NOT DISTINCT FROM pe.maquina_id
    LIMIT 1;

    IF v_already_executed IS NOT NULL THEN
        RAISE EXCEPTION
            'Ya existe una ejecución para el paso % con el mismo fyh_inicio y máquina. Posible envío duplicado.',
            v_already_executed;
    END IF;

    -- Cantidad guard: per-paso, existing + submitted cantidad must not exceed assigned roll count.
    -- Only checked when cantidad is provided; NULL means not recorded for this run.
    SELECT s.paso_id INTO v_overflow_paso
    FROM (
        SELECT
            sub.paso_id,
            COALESCE(SUM(pe.cantidad_rollos), 0) + sub.cantidad_submitted AS total
        FROM (
            SELECT (el->>'paso_id')::BIGINT          AS paso_id,
                   SUM((el->>'cantidad_rollos')::NUMERIC)   AS cantidad_submitted
            FROM jsonb_array_elements(p_data->'pasos') el
            WHERE (el->>'cantidad_rollos') IS NOT NULL
            GROUP BY (el->>'paso_id')::BIGINT
        ) sub
        LEFT JOIN mes.partida_paso_ejecucion pe ON pe.partida_paso_id = sub.paso_id
        GROUP BY sub.paso_id, sub.cantidad_submitted
    ) s
    WHERE s.total > v_rollos_asignados
    LIMIT 1;

    IF v_overflow_paso IS NOT NULL THEN
        RAISE EXCEPTION
            'El paso % excede los % rollos asignados a la partida.',
            v_overflow_paso, v_rollos_asignados;
    END IF;

    FOR v_paso IN SELECT * FROM jsonb_array_elements(p_data->'pasos') LOOP
        v_paso_id := (v_paso->>'paso_id')::BIGINT;

        IF v_paso_id IS NULL THEN
            RAISE EXCEPTION 'Cada paso debe incluir paso_id.';
        END IF;

        SELECT receta_id INTO v_receta_id FROM mes.partida_paso WHERE id = v_paso_id;
        IF (v_paso->>'fyh_inicio') IS NULL OR (v_paso->>'fyh_fin') IS NULL THEN
            RAISE EXCEPTION 'Cada paso debe incluir fyh_inicio y fyh_fin (paso_id=%).', v_paso_id;
        END IF;

        -- Insert as EN_PROCESO first so registrar_consumo_paso and registrar_produccion
        -- can find the row via their estado = 'EN_PROCESO' guard.
        -- fyh_fin is withheld until after inventory side-effects are written, then patched
        -- to the historical timestamp.  fyh_cre mirrors fyh_inicio so reporting looks correct.
        -- No trigger on partida_paso_ejecucion overrides fyh_cre, so this is safe.
        INSERT INTO mes.partida_paso_ejecucion(
            partida_paso_id,
            estado,
            fyh_inicio,
            fyh_fin,
            empleado_id,
            maquina_id,
            receta_id,
            ph_real,
            temperatura_real,
            relacion_bano_real,
            cantidad_rollos,
            cantidad_scrap,
            notas,
            ancho_entrada,
            ancho_salida,
            velocidad,
            entrada,
            salida,
            rendimiento,
            pases,
            malla_alimentacion,
            usr_cre,
            fyh_cre
        ) VALUES (
            v_paso_id,
            'EN_PROCESO',
            (v_paso->>'fyh_inicio')::TIMESTAMPTZ,
            NULL,                                   -- patched to historical value below
            (v_paso->>'empleado_id')::SMALLINT,
            (v_paso->>'maquina_id')::INT,
            v_receta_id,
            (v_paso->>'ph_real')::NUMERIC,
            (v_paso->>'temperatura_real')::NUMERIC,
            (v_paso->>'relacion_bano_real')::NUMERIC,
            (v_paso->>'cantidad_rollos')::NUMERIC,
            (v_paso->>'cantidad_scrap')::NUMERIC,
            v_paso->>'observacion',
            (v_paso->>'ancho_entrada')::NUMERIC,
            (v_paso->>'ancho_salida')::NUMERIC,
            (v_paso->>'velocidad')::NUMERIC,
            (v_paso->>'entrada')::NUMERIC,
            (v_paso->>'salida')::NUMERIC,
            (v_paso->>'rendimiento')::NUMERIC,
            (v_paso->>'pases')::SMALLINT,
            (v_paso->>'malla_alimentacion')::NUMERIC,
            v_usr_id,
            (v_paso->>'fyh_inicio')::TIMESTAMPTZ
        ) RETURNING id INTO v_ejecucion_id;

        IF v_paso->'consumos' IS NOT NULL AND jsonb_array_length(v_paso->'consumos') > 0 THEN
            PERFORM mes.registrar_consumo_paso(v_paso_id, v_paso->'consumos');
        END IF;

        IF v_paso->'produccion' IS NOT NULL THEN
            PERFORM mes.registrar_produccion(v_ejecucion_id, v_paso->'produccion');
        END IF;

        -- Seal the ejecucion with the historical end timestamp + snapshotted weight.
        UPDATE mes.partida_paso_ejecucion
        SET estado  = 'COMPLETADO',
            fyh_fin = (v_paso->>'fyh_fin')::TIMESTAMPTZ,
            peso_kg = COALESCE(
                (SELECT SUM(l.cantidad) FROM inventario.lote l
                 WHERE l.documento_tipo = 'partida_paso_ejecucion'
                   AND l.documento_id   = v_ejecucion_id
                   AND l.fyh_elm IS NULL),
                (SELECT ROUND(
                     SUM(l.cantidad)
                     * COALESCE((v_paso->>'cantidad_rollos')::numeric, MAX(totals.cnt))
                     / NULLIF(MAX(totals.cnt), 0),
                     4)
                 FROM mes.partida_componente pc
                 JOIN inventario.lote l ON l.id = pc.lote_id
                 CROSS JOIN (
                     SELECT COUNT(*)::numeric AS cnt
                     FROM mes.partida_componente
                     WHERE partida_id = v_partida_id AND lote_id IS NOT NULL
                 ) totals
                 WHERE pc.partida_id = v_partida_id AND pc.lote_id IS NOT NULL)
            )
        WHERE id = v_ejecucion_id;

        UPDATE mes.partida_paso
        SET estado = CASE
                WHEN (
                    SELECT COALESCE(SUM(pe.cantidad_rollos) FILTER (WHERE pe.estado = 'COMPLETADO'), 0)
                    FROM mes.partida_paso_ejecucion pe
                    WHERE pe.partida_paso_id = v_paso_id
                ) >= (
                    SELECT COUNT(*)
                    FROM mes.partida_componente pc
                    WHERE pc.partida_id = v_partida_id
                      AND pc.lote_id IS NOT NULL
                ) THEN 'COMPLETADO'::partida_paso_estado_enum
                ELSE 'EN_PROCESO'::partida_paso_estado_enum
            END,
            fyh_mod = NOW()
        WHERE id = v_paso_id;

        PERFORM mes.actualizar_estado_partida(v_partida_id);

        v_paso_count := v_paso_count + 1;
    END LOOP;

    RETURN format('Ejecución registrada: %s paso(s) confirmados para orden %s.',
                  v_paso_count, v_partida_id);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_ejecucion_partida - User: %, Orden: %, Error: %',
              v_usr_id, v_partida_id, v_message;
    RAISE;
END;
$$;


ALTER FUNCTION mes.registrar_ejecucion_partida(p_data jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.registrar_items_procesados(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.registrar_items_procesados(p_paso_id bigint, p_items jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'mes'
    AS $$
BEGIN
    RAISE EXCEPTION 'registrar_items_procesados está deprecado. El asignación de rollos es automática al iniciar el paso.'
        USING ERRCODE = 'feature_not_supported';
END;
$$;


ALTER FUNCTION mes.registrar_items_procesados(p_paso_id bigint, p_items jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.registrar_lavado_maquina(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.registrar_lavado_maquina(p_datos jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes', 'receta'
    AS $$
DECLARE
    v_id                BIGINT;
    v_usr_id            INT     := get_user_id();
    v_receta_id         INT     := (p_datos->>'receta_id')::INT;
    v_maq_id            INT     := (p_datos->>'maquina_id')::INT;
    v_egr_tipo_id       SMALLINT;
    v_motivo_id         SMALLINT;
    v_doc_movimiento_id BIGINT;
    v_insumos           JSONB;
    v_consumos          JSONB;
    v_error_payload     JSONB;
BEGIN
    IF NOT jwt_has_permission('produccion.ejecutar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.ejecutar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF (p_datos->>'fyh_inicio') IS NULL OR (p_datos->>'fyh_fin') IS NULL THEN
        RAISE EXCEPTION 'fyh_inicio y fyh_fin son requeridos para registrar_lavado_maquina.';
    END IF;

    IF (p_datos->>'fyh_inicio')::TIMESTAMPTZ >= (p_datos->>'fyh_fin')::TIMESTAMPTZ THEN
        RAISE EXCEPTION 'fyh_inicio debe ser anterior a fyh_fin.';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM receta.lavado_maquina WHERE id = v_receta_id AND flg_activo = true
    ) THEN
        RAISE EXCEPTION 'Receta lavado máquina id=% no existe o no está activa.', v_receta_id;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM mes.maquina WHERE id = v_maq_id AND fyh_elm IS NULL
    ) THEN
        RAISE EXCEPTION 'Máquina id=% no encontrada.', v_maq_id;
    END IF;

    -- Aggregate insumos across all recipe pasos, summed by item
    SELECT jsonb_agg(jsonb_build_object('item_id', item_id, 'cantidad', cantidad))
    INTO v_insumos
    FROM (
        SELECT lmpi.item_id, SUM(lmpi.cantidad) AS cantidad
        FROM receta.lavado_maquina_paso        lmp
        JOIN receta.lavado_maquina_paso_insumo lmpi ON lmpi.paso_id = lmp.id
        WHERE lmp.receta_id = v_receta_id
        GROUP BY lmpi.item_id
    ) agg;

    IF v_insumos IS NOT NULL THEN
        -- Stock check
        WITH consumos AS (
            SELECT (i->>'item_id')::INT      AS item_id,
                   (i->>'cantidad')::NUMERIC AS cantidad
            FROM jsonb_array_elements(v_insumos) i
        )
        SELECT jsonb_agg(jsonb_build_object(
            'item_id',            c.item_id,
            'item_nombre',        it.nombre,
            'saldo_disponible',   COALESCE(sg.cantidad_total, 0),
            'cantidad_requerida', c.cantidad
        ))
        INTO v_error_payload
        FROM consumos c
        LEFT JOIN inventario.vw_stock_items sg ON sg.item_id = c.item_id
        JOIN item it ON it.id = c.item_id
        WHERE COALESCE(sg.cantidad_total, 0) < c.cantidad;

        IF v_error_payload IS NOT NULL THEN
            RAISE EXCEPTION 'Stock insuficiente para registrar lavado'
                USING DETAIL = v_error_payload::text;
        END IF;

        SELECT id INTO v_egr_tipo_id
        FROM inventario.item_movimiento_tipo WHERE codigo = 'PROD_CONSUMO';

        SELECT id INTO v_motivo_id
        FROM inventario.item_movimiento_motivo
        WHERE item_movimiento_tipo_id = v_egr_tipo_id AND codigo = 'LAVADO_MAQUINA';

        v_consumos := mes.calcular_fifo(v_insumos);
        SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;
    END IF;

    -- Insert directly as COMPLETADO
    INSERT INTO mes.lavado_maquina(
        receta_id, maquina_id, empleado_id, nota,
        estado, fyh_inicio, fyh_fin,
        usr_cre, fyh_cre
    ) VALUES (
        v_receta_id,
        v_maq_id,
        (p_datos->>'empleado_id')::SMALLINT,
        p_datos->>'nota',
        'COMPLETADO',
        (p_datos->>'fyh_inicio')::TIMESTAMPTZ,
        (p_datos->>'fyh_fin')::TIMESTAMPTZ,
        v_usr_id, now()
    )
    RETURNING id INTO v_id;

    IF v_consumos IS NOT NULL THEN
        INSERT INTO inventario.item_movimientos(
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            origen_ubicacion_id, cantidad, precio_unitario,
            documento_tipo, documento_id, motivo_id
        )
        SELECT
            v_doc_movimiento_id,
            (c->>'item_id')::INT,
            (c->>'lote_id')::INT,
            v_egr_tipo_id,
            (c->>'ubicacion_id')::INT,
            (c->>'cantidad')::NUMERIC,
            (SELECT iv.precio_promedio FROM inventario.item_valoracion iv
             WHERE iv.item_id = (c->>'item_id')::INT),
            'lavado_maquina',
            v_id,
            v_motivo_id
        FROM jsonb_array_elements(v_consumos) c;
    END IF;

    UPDATE mes.maquina SET
        ultimo_mantenimiento = (p_datos->>'fyh_fin')::TIMESTAMPTZ,
        usr_mod = v_usr_id,
        fyh_mod = now()
    WHERE id = v_maq_id;

    RETURN v_id;
END;$$;


ALTER FUNCTION mes.registrar_lavado_maquina(p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.registrar_matizado(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.registrar_matizado(p_paso_id bigint, p_consumos jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes'
    AS $$
DECLARE
    v_augmented jsonb;
BEGIN
    IF NOT jwt_has_permission('produccion.ejecutar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.ejecutar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT jsonb_agg(item || jsonb_build_object('motivo_id', m.id))
    INTO v_augmented
    FROM jsonb_array_elements(p_consumos) AS item
    CROSS JOIN (SELECT id FROM inventario.item_movimiento_motivo WHERE codigo = 'MATIZADO') m;

    RETURN mes.registrar_consumo_paso(p_paso_id, v_augmented);
END;
$$;


ALTER FUNCTION mes.registrar_matizado(p_paso_id bigint, p_consumos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.registrar_produccion(bigint, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.registrar_produccion(p_ejecucion_id bigint, p_datos jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'inventario', 'mes', 'doc'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id            int := get_user_id();
    v_partida_id        bigint;
    v_ing_tipo_id       smallint;
    v_egr_tipo_id       smallint;
    v_consumed          int;
    -- Loop variables for output lote creation
    v_elem              jsonb;
    v_input_lote_id     int;
    v_peso_salida       numeric;
    v_out_item_id       int;
    v_out_propietario   int;
    v_new_lote_id           int;
    v_entrega_id      bigint;
    v_doc_movimiento_id     BIGINT;
    v_flg_rib               BOOLEAN;
    v_lote_cantidad         NUMERIC;
    -- Distributed weight per roll when totals are provided
    v_count_regular         INT;
    v_count_rib             INT;
    v_peso_por_regular      NUMERIC;
    v_peso_por_rib          NUMERIC;
    -- True when peso_salida came from a physical measurement (per-roll), not prorated
    v_peso_salida_is_medido BOOLEAN;
    -- Partida attributes copied to each output lrd row
    v_partida_ancho             TEXT;
    v_partida_malla             TEXT;
    v_partida_rendimiento       TEXT;
    v_partida_color_x_cliente   INT;
    v_partida_tenido_id         INT;
    v_partida_flg_antipilling   BOOLEAN;
    v_p_output                  JSONB;
    v_ubicacion_id              INT;
    v_peso_rollos               NUMERIC;
    v_peso_rib                  NUMERIC;
BEGIN
    IF NOT jwt_has_permission('produccion.ejecutar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.ejecutar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    v_p_output    := p_datos->'output';
    v_ubicacion_id := (p_datos->>'ubicacion_id')::INT;
    v_peso_rollos  := (p_datos->>'peso_rollos')::NUMERIC;
    v_peso_rib     := (p_datos->>'peso_rib')::NUMERIC;

    IF v_ubicacion_id IS NULL THEN
        RAISE EXCEPTION 'p_datos.ubicacion_id es obligatorio (destino de los rollos de salida).';
    END IF;

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('registrar_produccion', v_usr_id, p_datos || jsonb_build_object('ejecucion_id', p_ejecucion_id));

    -- 1. Resolve partida from the execution run
    SELECT pp.partida_id
    INTO v_partida_id
    FROM mes.partida_paso_ejecucion pe
    JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
    WHERE pe.id = p_ejecucion_id AND pe.estado = 'EN_PROCESO';
    v_partida_id := v_partida_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Ejecución #% no encontrada o no está EN_PROCESO.', p_ejecucion_id;
    END IF;

    PERFORM 1 FROM mes.partida_detalle WHERE partida_id = v_partida_id FOR UPDATE;

    -- Lock existing output lotes for this execution run
    PERFORM 1 FROM inventario.lote
    WHERE documento_tipo = 'partida_paso_ejecucion' AND documento_id = p_ejecucion_id
    FOR UPDATE;

    -- Lock input roll lotes to prevent concurrent consumption
    PERFORM 1
    FROM inventario.lote l
    JOIN mes.partida_componente pc ON pc.lote_id = l.id
    WHERE pc.partida_id = v_partida_id
    FOR UPDATE OF l;

    PERFORM 1 FROM mes.partida WHERE id = v_partida_id FOR UPDATE;

    -- 2. Validate all input_lote_ids belong to this partida
    IF EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_p_output) i
        WHERE NOT EXISTS (
            SELECT 1 FROM mes.partida_componente pc
            WHERE pc.partida_id = v_partida_id
              AND pc.lote_id = (i->>'input_lote_id')::INT
        )
    ) THEN
        RAISE EXCEPTION 'Uno o más input_lote_id no pertenecen a esta orden.';
    END IF;

    SELECT id INTO v_ing_tipo_id
    FROM inventario.item_movimiento_tipo WHERE codigo = 'PROD_ING';
    SELECT id INTO v_egr_tipo_id
    FROM inventario.item_movimiento_tipo WHERE codigo = 'PROD_CONSUMO';

    -- Fetch partida attributes once; copied to every output lrd row
    SELECT ancho, malla, rendimiento, color_x_cliente_id, tenido_id, flg_antipilling
    INTO v_partida_ancho, v_partida_malla, v_partida_rendimiento,
         v_partida_color_x_cliente, v_partida_tenido_id, v_partida_flg_antipilling
    FROM mes.partida WHERE id = v_partida_id;

    -- If total weights provided, pre-count rib vs regular output rolls and compute per-roll weight
    IF v_peso_rollos IS NOT NULL OR v_peso_rib IS NOT NULL THEN
        SELECT
            COUNT(*) FILTER (WHERE ird.flg_rib = false),
            COUNT(*) FILTER (WHERE ird.flg_rib = true)
        INTO v_count_regular, v_count_rib
        FROM jsonb_array_elements(v_p_output) i
        JOIN inventario.lote l      ON l.id = (i->>'input_lote_id')::INT
        JOIN item_rollo_detalle ird ON ird.item_id = l.item_id;

        IF v_peso_rollos IS NOT NULL THEN
            IF v_count_regular = 0 THEN
                RAISE EXCEPTION 'Se proporcionó peso_rollos pero no hay rollos regulares en el output.';
            END IF;
            v_peso_por_regular := ROUND(v_peso_rollos / v_count_regular, 4);
        END IF;
        IF v_peso_rib IS NOT NULL THEN
            IF v_count_rib = 0 THEN
                RAISE EXCEPTION 'Se proporcionó peso_rib pero no hay rollos rib en el output.';
            END IF;
            v_peso_por_rib := ROUND(v_peso_rib / v_count_rib, 4);
        END IF;
    END IF;

    -- Single posting id shared by backflush + output movements
    SELECT nextval('inventario.mov_doc_seq') INTO v_doc_movimiento_id;

    -- 4a. Backflush: consume input rolls assigned to this execution run
    INSERT INTO inventario.item_movimientos(
        doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
        origen_ubicacion_id, cantidad,
        documento_tipo, documento_id
    )
    SELECT
        v_doc_movimiento_id,
        l.item_id,
        pc.lote_id,
        v_egr_tipo_id,
        sa.ubicacion_id,
        l.cantidad,
        'partida_paso_ejecucion',
        p_ejecucion_id
    FROM (SELECT DISTINCT (i->>'input_lote_id')::INT AS lote_id FROM jsonb_array_elements(v_p_output) i) inp
    JOIN mes.partida_componente pc ON pc.lote_id = inp.lote_id AND pc.partida_id = v_partida_id
    JOIN inventario.lote l ON l.id = pc.lote_id
    LEFT JOIN LATERAL (
        SELECT ubicacion_id FROM inventario.vw_stock_lotes_ubicacion WHERE lote_id = pc.lote_id LIMIT 1
    ) sa ON true;

    GET DIAGNOSTICS v_consumed = ROW_COUNT;

    -- 4b. Create output lotes (same item_id as input), PROD_ING movements,
    --     and lote_rollo_detalle carrying entrega_id forward.
    FOR v_elem IN SELECT value FROM jsonb_array_elements(v_p_output)
    LOOP
        v_input_lote_id := (v_elem->>'input_lote_id')::INT;

        -- Inherit item_id, propietario, billing anchor, rib flag, and original quantity from input lote
        SELECT l.item_id, l.propietario_id, lrd.entrega_id, ird.flg_rib, l.cantidad
        INTO v_out_item_id, v_out_propietario, v_entrega_id, v_flg_rib, v_lote_cantidad
        FROM inventario.lote l
        JOIN inventario.lote_rollo_detalle lrd ON lrd.lote_id = l.id
        JOIN item_rollo_detalle ird             ON ird.item_id = l.item_id
        WHERE l.id = v_input_lote_id;

        -- Resolve output weight.
        -- Totals param (prorated) takes precedence over per-roll peso_salida.
        -- v_peso_salida_is_medido: true only when weight is a physical measurement,
        -- not a prorated calculation — drives whether a pesaje audit record is created.
        IF v_flg_rib AND v_peso_por_rib IS NOT NULL THEN
            v_peso_salida         := v_peso_por_rib;
            v_peso_salida_is_medido := false;
        ELSIF NOT v_flg_rib AND v_peso_por_regular IS NOT NULL THEN
            v_peso_salida         := v_peso_por_regular;
            v_peso_salida_is_medido := false;
        ELSE
            v_peso_salida         := (v_elem->>'peso_salida')::NUMERIC;
            v_peso_salida_is_medido := true;
        END IF;

        IF v_peso_salida IS NULL THEN
            IF v_lote_cantidad IS NULL THEN
                RAISE EXCEPTION 'Falta peso_salida para el lote de entrada #%. Proporcione peso_salida en el array o use p_peso_rollos/p_peso_rib.', v_input_lote_id;
            END IF;
            v_peso_salida := v_lote_cantidad;
            v_peso_salida_is_medido := false;
        END IF;

        INSERT INTO inventario.lote(item_id, documento_tipo, documento_id, cantidad, propietario_id)
        VALUES (v_out_item_id, 'partida_paso_ejecucion', p_ejecucion_id, v_peso_salida, v_out_propietario)
        RETURNING id INTO v_new_lote_id;

        INSERT INTO inventario.item_movimientos(
            doc_movimiento_id, item_id, lote_id, item_movimiento_tipo_id,
            destino_ubicacion_id, cantidad, documento_tipo, documento_id
        )
        VALUES (v_doc_movimiento_id, v_out_item_id, v_new_lote_id, v_ing_tipo_id,
                v_ubicacion_id, v_peso_salida, 'partida_paso_ejecucion', p_ejecucion_id);

        -- Batch classification: carry ingress doc anchor + parent-batch link forward;
        -- populate dyeing identity from partida.
        INSERT INTO inventario.lote_rollo_detalle(
            lote_id, entrega_id, origen_lote_id,
            ancho, malla, rendimiento,
            color_x_cliente_id, tenido_id,
            flg_tenido, flg_antipilling
        )
        VALUES (
            v_new_lote_id, v_entrega_id, v_input_lote_id,
            v_partida_ancho, v_partida_malla, v_partida_rendimiento,
            v_partida_color_x_cliente, v_partida_tenido_id,
            true, v_partida_flg_antipilling
        );

        -- Output weighing audit: only when weight was physically measured per-roll,
        -- not when prorated from p_peso_rollos/p_peso_rib totals.
        IF v_peso_salida_is_medido THEN
            INSERT INTO inventario.pesaje(lote_id, tipo, peso_real, usr_cre)
            VALUES (v_new_lote_id, 'SALIDA', v_peso_salida, v_usr_id);
        END IF;
    END LOOP;

    -- 5. Sync confirmed roll count onto the order item.
    -- Recounts all non-deleted output lotes across ALL ejecuciones for this partida,
    -- not just the current run — correct for send-ahead (multiple runs on same paso).
    UPDATE mes.partida_detalle pd
    SET cantidad_producida = (
        SELECT COUNT(*)
        FROM inventario.lote l
        JOIN mes.partida_paso_ejecucion pe
            ON pe.id = l.documento_id AND l.documento_tipo = 'partida_paso_ejecucion'
        JOIN mes.partida_paso pp ON pp.id = pe.partida_paso_id
        WHERE pp.partida_id = v_partida_id
          AND l.item_id     = pd.item_id
          AND l.fyh_elm     IS NULL
    ),
    usr_mod = v_usr_id,
    fyh_mod = NOW()
    WHERE pd.partida_id = v_partida_id;

    -- 6. Notifications
    INSERT INTO notification.notifications(user_id, title, body, tipo, payload)
    SELECT ur.user_id, 'Producción Registrada',
           COALESCE((SELECT COALESCE(nombre,'Usuario desconocido') || ' ' || apellido
                     FROM usuario WHERE id = v_usr_id), 'sistema')
           || format(' registró %s lotes de producción en orden #%s', jsonb_array_length(v_p_output), v_partida_id), 'info',
           jsonb_build_object('objeto_tipo','partida','partida_id', v_partida_id)
    FROM iam.user_rol ur LEFT JOIN iam.rol r ON ur.rol_id = r.id
    WHERE r.code IN ('jefe_planta','calidad') AND v_usr_id <> ur.user_id;

    RETURN format('%s rollos consumidos, %s lotes creados para orden #%s.', v_consumed, jsonb_array_length(v_p_output), v_partida_id);
EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in registrar_produccion - User: %, ejecucion: %, Error: %, Detail: %',
              v_usr_id, p_ejecucion_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION mes.registrar_produccion(p_ejecucion_id bigint, p_datos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.revertir_inicio_paso(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.revertir_inicio_paso(p_paso_id bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'inventario', 'mes'
    AS $$
DECLARE
    v_message text; v_detail text; v_hint text; v_context text; v_sqlstate text;
    v_usr_id        int := get_user_id();
    v_partida_id    bigint;
    v_op_nombre     text;
    v_maquina_id    int;
    v_ejecucion_id  bigint;
BEGIN
    IF NOT jwt_has_permission('produccion.ejecutar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.ejecutar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- Resolve the active run for this paso
    SELECT pp.partida_id, o.nombre, pe.id, pe.maquina_id
    INTO   v_partida_id, v_op_nombre, v_ejecucion_id, v_maquina_id
    FROM   mes.partida_paso pp
    JOIN   mes.operacion o ON o.id = pp.operacion_id
    JOIN   mes.partida_paso_ejecucion pe ON pe.partida_paso_id = pp.id AND pe.estado = 'EN_PROCESO'
    WHERE  pp.id = p_paso_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Paso #% no tiene una ejecución EN_PROCESO para revertir.', p_paso_id;
    END IF;

    -- Guard: net unconsumed quantity > 0 (anular_produccion posts PROD_CONSUMO_REV which nets to 0)
    IF EXISTS (
        SELECT 1
        FROM (
            SELECT SUM(CASE WHEN imt.codigo = 'PROD_CONSUMO_REV' THEN -im.cantidad
                            ELSE im.cantidad END) AS net
            FROM inventario.item_movimientos im
            JOIN inventario.item_movimiento_tipo imt ON imt.id = im.item_movimiento_tipo_id
            WHERE im.documento_tipo = 'partida_paso_ejecucion'
              AND im.documento_id   = v_ejecucion_id
              AND imt.codigo IN ('PROD_CONSUMO', 'PROD_CONSUMO_REV')
        ) s WHERE s.net > 0
    ) THEN
        RAISE EXCEPTION
            'No se puede deshacer el inicio del paso %: ya tiene consumos registrados. Use anular_produccion.',
            v_op_nombre;
    END IF;

    -- Guard: no live (non-reversed) output lotes produced by this run
    IF EXISTS (
        SELECT 1 FROM inventario.lote
        WHERE documento_tipo = 'partida_paso_ejecucion'
          AND documento_id   = v_ejecucion_id
          AND fyh_elm        IS NULL
    ) THEN
        RAISE EXCEPTION
            'No se puede deshacer el inicio del paso %: ya registró producción. Use anular_produccion.',
            v_op_nombre;
    END IF;

    -- Guard: no QC inspection references this run (crear_inspeccion stamps
    -- partida_paso_ejecucion_id on every inspection, input or output roll) —
    -- the hard DELETE below would otherwise fail on inspeccion_partida_paso_ejecucion_id_fkey.
    IF EXISTS (
        SELECT 1 FROM calidad.inspeccion WHERE partida_paso_ejecucion_id = v_ejecucion_id
    ) THEN
        RAISE EXCEPTION
            'No se puede deshacer el inicio del paso %: tiene inspecciones de calidad registradas. Anule esas inspecciones primero (calidad.anular_inspeccion).',
            v_op_nombre;
    END IF;

    -- iniciar_paso only inserted the run row — safe to DELETE
    DELETE FROM mes.partida_paso_ejecucion WHERE id = v_ejecucion_id;

    -- Reset paso: PENDIENTE if this was the only run, else keep EN_PROCESO (partial batches remain)
    UPDATE mes.partida_paso
    SET estado = CASE
            WHEN EXISTS (
                SELECT 1 FROM mes.partida_paso_ejecucion
                WHERE partida_paso_id = p_paso_id
            ) THEN 'EN_PROCESO'::partida_paso_estado_enum
            ELSE 'PENDIENTE'::partida_paso_estado_enum
        END,
        fyh_mod = NOW()
    WHERE id = p_paso_id;

    -- Release the machine the start had marked active
    IF v_maquina_id IS NOT NULL THEN
        UPDATE mes.maquina SET estado_actual = 'espera' WHERE id = v_maquina_id;
    END IF;

    PERFORM mes.actualizar_estado_partida(v_partida_id);

    INSERT INTO logs_api(function_name, user_id, params)
    VALUES ('revertir_inicio_paso', v_usr_id,
            jsonb_build_object('paso_id', p_paso_id, 'ejecucion_id', v_ejecucion_id));

    RETURN format('Inicio del paso %s (#%s) deshecho. El paso vuelve a estar disponible.',
                  v_op_nombre, p_paso_id);

EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_message=MESSAGE_TEXT, v_detail=PG_EXCEPTION_DETAIL,
        v_hint=PG_EXCEPTION_HINT, v_context=PG_EXCEPTION_CONTEXT, v_sqlstate=RETURNED_SQLSTATE;
    RAISE LOG 'Error in revertir_inicio_paso - User: %, Paso: %, Error: %, Detail: %',
              v_usr_id, p_paso_id, v_message, v_detail;
    RAISE;
END;
$$;


ALTER FUNCTION mes.revertir_inicio_paso(p_paso_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: mes.set_tiempo_estandar_lavado(smallint, interval)
-- ---------------------------------------------------------------------
CREATE FUNCTION mes.set_tiempo_estandar_lavado(p_tipo_lavado_mq_id smallint, p_duracion interval) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public', 'mes'
    AS $$
DECLARE
    v_usr_id  int := get_user_id();
    v_old_id  smallint;
    v_new_id  smallint;
BEGIN
    IF NOT jwt_has_permission('produccion.configurar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.configurar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    UPDATE mes.tiempos_estandar_lavado
    SET    flg_activo = false,
           usr_mod    = v_usr_id,
           fyh_mod    = NOW()
    WHERE  tipo_lavado_mq_id = p_tipo_lavado_mq_id
      AND  flg_activo        = true
    RETURNING id INTO v_old_id;

    INSERT INTO mes.tiempos_estandar_lavado
        (tipo_lavado_mq_id, duracion, flg_activo, usr_cre)
    VALUES
        (p_tipo_lavado_mq_id, p_duracion, true, v_usr_id)
    RETURNING id INTO v_new_id;

    RETURN jsonb_build_object(
        'id',          v_new_id,
        'anterior_id', v_old_id,
        'duracion',    p_duracion::text
    );
END;
$$;


ALTER FUNCTION mes.set_tiempo_estandar_lavado(p_tipo_lavado_mq_id smallint, p_duracion interval) OWNER TO postgres;

