-- ---------------------------------------------------------------------
-- FUNCTION: notification.notifications_cambios()
-- ---------------------------------------------------------------------
CREATE FUNCTION notification.notifications_cambios() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
begin
  perform realtime.broadcast_changes(
    'topic:' || NEW.user_id::text,       -- topic - the topic to which you're broadcasting where you can use the topic id to build the topic name
    'notificacion',                                             -- event - the event that triggered the function
    TG_OP,                                             -- operation - the operation that triggered the function
    TG_TABLE_NAME,                                     -- table - the table that caused the trigger
    TG_TABLE_SCHEMA,                                   -- schema - the schema of the table that caused the trigger
    NEW,                                               -- new record - the record after the change
    OLD                                                -- old record - the record before the change
  );
  return null;
end;
$$;


ALTER FUNCTION notification.notifications_cambios() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: public.approve_full_entrada_inventario(integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION public.approve_full_entrada_inventario(entrada_id integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public'
    AS $$DECLARE
    id_compra INT;
    msj_error TEXT;
    v_cantidad_restante INT;
    v_pk_compra INT;
    v_fyh_ingreso_real timestamptz;
BEGIN
    -- Ensure the entrada is still pending
    IF (SELECT estado FROM entrada_inventario WHERE id = entrada_id) <> 'pendiente' THEN
        RETURN 'Error: El ingreso ya fue aprobado o rechazado.';
    END IF;

    -- Check for excess in case of compra
    IF (SELECT motivo FROM entrada_inventario WHERE id = entrada_id) = 'compra' THEN
        WITH ingresos AS (
            SELECT
                eid.compra_x_insumo_id,
                ci.cantidad - SUM(eid.cantidad_recibida) AS cantidad_restante
            FROM entrada_inventario_detalle eid
            LEFT JOIN compra_x_insumo ci
              ON ci.id = eid.compra_x_insumo_id
              AND ci.id IN (
                  SELECT compra_x_insumo_id
                  FROM entrada_inventario_detalle
                  WHERE entrada_inventario_id = entrada_id
              )
            WHERE estado = 'aprobado'
            GROUP BY eid.compra_x_insumo_id, ci.cantidad
        )
        SELECT string_agg(
            format(
                'Insumo: %s excede el restante por ingresar %s de la compra',
                eid.cantidad_recibida, i.cantidad_restante
            ),
            E'\n'
        )
        INTO msj_error
        FROM ingresos i
        JOIN entrada_inventario_detalle eid
            ON i.compra_x_insumo_id = eid.compra_x_insumo_id
        WHERE eid.entrada_inventario_id = entrada_id
          AND i.cantidad_restante < eid.cantidad_recibida;

        IF msj_error IS NOT NULL THEN
            RETURN msj_error;
        END IF;
    END IF;

    -- Approve all lines
    UPDATE entrada_inventario_detalle
    SET
        cantidad_recibida = cantidad_solicitada,
        estado = 'aprobado'::estado_entrada_inventario_enum
    WHERE entrada_inventario_id = entrada_id;

    -- Update entrada
    UPDATE entrada_inventario
    SET
        estado = 'aprobado'::estado_entrada_inventario_enum,
        fyh_revision = CURRENT_TIMESTAMP,
        usr_revisa = get_user_id()
    WHERE id = entrada_id
    RETURNING fyh_entrada_real INTO v_fyh_ingreso_real;
    -- Insert into inventario
    INSERT INTO inventario(entrada_inventario_detalle_id, insumo_x_proveedor_id, cantidad,fyh_ingreso)
    SELECT id, insumo_x_proveedor_id, cantidad_recibida,v_fyh_ingreso_real
    FROM entrada_inventario_detalle
    WHERE entrada_inventario_id = entrada_id;

    -- Update compra if relevant
    IF (SELECT motivo FROM entrada_inventario WHERE id = entrada_id) = 'compra' THEN
        SELECT compra_id INTO v_pk_compra
        FROM entrada_inventario ei
            JOIN entrada_inventario_detalle eid ON ei.id = eid.entrada_inventario_id
            LEFT JOIN vw_compra_insumos cxi ON cxi.compra_x_insumo_id = eid.compra_x_insumo_id
        WHERE ei.id = entrada_id
        GROUP by compra_id
        LIMIT 1
        ;
    RAISE NOTICE 'Evaluando Compra';--'Debug: entrada_id = %', entrada_id;
        SELECT compra_id,SUM(COALESCE(cantidad_restante,0)) INTO id_compra,v_cantidad_restante
        FROM vw_compra_insumos cxi
        WHERE compra_id = v_pk_compra
        GROUP BY compra_id;
        IF NOT FOUND THEN
  id_compra := v_pk_compra;
  v_cantidad_restante := 0;
END IF;
RAISE NOTICE 'Debug: id_compra = %', id_compra;
RAISE NOTICE 'Debug: v_cantidad_restante = %', v_cantidad_restante;
       IF id_compra IS NOT NULL AND COALESCE(v_cantidad_restante, 0) = 0 THEN
           RAISE NOTICE 'Debug: Actualizando estado de compra a completo';
    UPDATE compra
    SET estado_ingreso = 'completo'::estado_ingreso_compra_enum
    WHERE id = id_compra;
ELSE
    RAISE NOTICE 'Debug: Actualizando estado de compra a parcial';
    UPDATE compra
    SET estado_ingreso = 'parcial'::estado_ingreso_compra_enum
    WHERE id = id_compra;
END IF;

    END IF;
    UPDATE compra
SET estado_ingreso='completo'
WHERE id IN(SELECT id FROM comrpas_pendientes_completas);

INSERT INTO notification.notifications(user_id,title,body,tipo,payload)
SELECT ur.user_id,'Solicitud de Ingreso Aprobada', COALESCE((SELECT COALESCE(first_name,'Usuario desconocido') || ' ' || last_name FROM profiles WHERE id_usuario=get_user_id()),'sistema') || ' aprobó el ingreso total de la solicitud N°' || entrada_id, 'info',jsonb_build_object('objeto_tipo','entrada','objeto_id',entrada_id)
FROM iam.user_rol ur LEFT JOIN profiles p ON p.id_usuario=ur.user_id
LEFT JOIN iam.rol r ON ur.rol_id=r.id
WHERE r.code IN ('jefe_planta','compras');

    RETURN format('Ingreso #%s aprobado completamente.', entrada_id);
END;$$;


ALTER FUNCTION public.approve_full_entrada_inventario(entrada_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: public.crear_item(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION public.crear_item(p_item jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public'
    AS $$
DECLARE
    v_message   text;
    v_detail    text;
    v_hint      text;
    v_context   text;
    v_sqlstate  text;
    v_item_id   INT;
    v_tipo_codigo text;
    v_usr_id int := get_user_id();
BEGIN
    IF NOT jwt_has_permission('inventario.crear') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere inventario.crear'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

 INSERT INTO logs_api(function_name, user_id, params)
        VALUES ('crear_item', v_usr_id, p_item);
    INSERT INTO item (codigo, nombre, item_tipo_id, unidad_id)
    VALUES (
        p_item->>'codigo',
        p_item->>'nombre',
        (p_item->>'item_tipo_id')::INT,
        (p_item->>'unidad_id')::INT
    )
    RETURNING id INTO v_item_id;
     SELECT codigo INTO v_tipo_codigo FROM item_tipo WHERE id = (p_item->>'item_tipo_id')::INT;

    -- Create rollo or insumo detail
    IF v_tipo_codigo = 'ROLLO' THEN
        PERFORM crear_item_rollo(p_item, v_item_id);
    ELSIF v_tipo_codigo = 'INSUMO' THEN
        PERFORM crear_item_insumo(p_item, v_item_id);
    END IF;
INSERT INTO notification.notifications(user_id,title,body,tipo,payload)
SELECT ur.user_id,'Nuevo Item Creado', COALESCE((SELECT COALESCE(nombre,'Usuario desconocido') || ' ' || apellido FROM usuario WHERE id=v_usr_id),'sistema') || ' creó un nuevo item de tipo' || COALESCE(p_item->>'nombre','sin nombre'), 'info',jsonb_build_object('objeto_tipo','item','item_id',v_item_id)
FROM iam.user_rol ur LEFT JOIN usuario p ON p.id=ur.user_id
LEFT JOIN iam.rol r ON ur.rol_id=r.id
WHERE r.code IN ('jefe_planta','compras') AND v_usr_id<>ur.user_id;
   RETURN format('Item con ID %s creado correctamente.', v_item_id);
 EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;

        RAISE LOG 'Error in crear_item - User: %, Params: %, Error: %, Detail: %',
                  v_usr_id, p_item::TEXT, v_message, v_detail;
        RAISE;
END;
$$;


ALTER FUNCTION public.crear_item(p_item jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: public.crear_item_insumo(jsonb, integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION public.crear_item_insumo(p_item jsonb, p_item_id integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public'
    AS $$
DECLARE
    v_message   text;
    v_detail    text;
    v_hint      text;
    v_context   text;
    v_sqlstate  text;
    v_usr_id int := get_user_id();
BEGIN
    IF p_item ? 'medida' AND p_item ? 'insumo_tipo_id' THEN
    BEGIN
        INSERT INTO item_insumo_detalle (item_id, medida, insumo_tipo_id, colorante_tipo_id)
        VALUES (
            p_item_id,
            (p_item->>'medida')::medida_enum,
            (p_item->>'insumo_tipo_id')::SMALLINT,
            CASE
                WHEN p_item ? 'colorante_tipo_id' THEN (p_item->>'colorante_tipo_id')::SMALLINT
                ELSE NULL
            END
        );
        EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;

        RAISE LOG 'Error in crear_item_insumo - User: %, Params: %, Error: %, Detail: %',
                  v_usr_id, p_item::TEXT, v_message, v_detail;
        RAISE;
        END;
    ELSE
       RAISE EXCEPTION
        'Los campos medida e insumo_tipo_id son obligatorios para crear un item de tipo insumo';
    END IF;
    RETURN format('Detalle de insumo para item_id %s creado correctamente.', p_item_id);
END;
$$;


ALTER FUNCTION public.crear_item_insumo(p_item jsonb, p_item_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: public.crear_item_rollo(jsonb, integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION public.crear_item_rollo(p_item jsonb, p_item_id integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'notification', 'public'
    AS $$
DECLARE
    v_message   text;
    v_detail    text;
    v_hint      text;
    v_context   text;
    v_sqlstate  text;
    v_usr_id int := get_user_id();
BEGIN
    IF p_item ? 'articulo_id' THEN
    BEGIN
        INSERT INTO item_rollo_detalle (item_id, articulo_id, flg_rib)
        VALUES (
            p_item_id,
            (p_item->>'articulo_id')::INT,
            COALESCE((p_item->>'flg_rib')::BOOLEAN, FALSE)
        );
        EXCEPTION
    WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS
            v_message  = MESSAGE_TEXT,
            v_detail   = PG_EXCEPTION_DETAIL,
            v_hint     = PG_EXCEPTION_HINT,
            v_context  = PG_EXCEPTION_CONTEXT,
            v_sqlstate = RETURNED_SQLSTATE;

        RAISE LOG 'Error in crear_item_rollo - User: %, Params: %, Error: %, Detail: %',
                  v_usr_id, p_item::TEXT, v_message, v_detail;
        RAISE;
        END;
    ELSE
       RAISE EXCEPTION
        'El campo articulo_id es obligatorio para crear un item de tipo rollo';
    END IF;
    RETURN format('Detalle de rollo para item_id %s creado correctamente.', p_item_id);
END;
$$;


ALTER FUNCTION public.crear_item_rollo(p_item jsonb, p_item_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: public.custom_access_token_hook(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION public.custom_access_token_hook(event jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'iam'
    AS $$
DECLARE
  claims        jsonb;
  v_numeric_id  integer;
  v_permissions text[];
  v_role_codes  text[];
BEGIN
  -- Bridge auth UUID → numeric id
  SELECT id INTO v_numeric_id
  FROM public.usuario
  WHERE auth_id = (event->>'user_id')::uuid;

  -- No usuario row = no permissions, id_usuario JWT claim stays NULL.
  IF v_numeric_id IS NULL THEN
    claims := event->'claims';
    claims := jsonb_set(claims, '{user_permissions}', '[]'::jsonb);
    claims := jsonb_set(claims, '{user_roles}',       '[]'::jsonb);
    claims := jsonb_set(claims, '{id_usuario}',       'null'::jsonb);
    RETURN jsonb_set(event, '{claims}', claims);
  END IF;

  -- Collect all permission codes across all roles
  SELECT ARRAY_AGG(DISTINCT p.code) INTO v_permissions
  FROM iam.user_rol ur
  JOIN iam.rol_permiso rp ON rp.rol_id = ur.rol_id
  JOIN iam.permiso p ON p.id = rp.permiso_id
  WHERE ur.user_id = v_numeric_id;

  -- Collect role codes
  SELECT ARRAY_AGG(DISTINCT r.code) INTO v_role_codes
  FROM iam.user_rol ur
  JOIN iam.rol r ON r.id = ur.rol_id
  WHERE ur.user_id = v_numeric_id;

  claims := event->'claims';
  claims := jsonb_set(claims, '{user_permissions}', COALESCE(to_jsonb(v_permissions), '[]'::jsonb));
  claims := jsonb_set(claims, '{user_roles}',       COALESCE(to_jsonb(v_role_codes),  '[]'::jsonb));
  claims := jsonb_set(claims, '{id_usuario}',       to_jsonb(v_numeric_id));

  RETURN jsonb_set(event, '{claims}', claims);
END;
$$;


ALTER FUNCTION public.custom_access_token_hook(event jsonb) OWNER TO postgres;

