-- FUNCTION: public.fn_trg_gen_codigo_color()
-- ---------------------------------------------------------------------
CREATE FUNCTION public.fn_trg_gen_codigo_color() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.codigo IS NULL THEN
        NEW.codigo := UPPER(regexp_replace(NEW.color, '[^a-zA-Z0-9]', '', 'g'));
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_trg_gen_codigo_color() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: public.fn_trg_gen_codigo_item_insumo()
-- ---------------------------------------------------------------------
CREATE FUNCTION public.fn_trg_gen_codigo_item_insumo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_it_codigo TEXT;
    v_ct_codigo TEXT;
    v_nombre    TEXT;
    v_codigo    TEXT;
BEGIN
    SELECT it.codigo, ct.codigo, i.nombre
      INTO v_it_codigo, v_ct_codigo, v_nombre
      FROM item i
      JOIN insumo_tipo it ON it.id = NEW.insumo_tipo_id
      LEFT JOIN colorante_tipo ct ON ct.id = NEW.colorante_tipo_id
     WHERE i.id = NEW.item_id;

    v_codigo := 'I-' || v_it_codigo;
    IF v_ct_codigo IS NOT NULL THEN
        v_codigo := v_codigo || '-' || v_ct_codigo;
    END IF;
    v_codigo := v_codigo || '-' ||
        trim(both '-' from
            regexp_replace(
                regexp_replace(UPPER(v_nombre) COLLATE "C", '\s+', ' ', 'g'),
                '[^A-Z0-9]+', '-', 'g'));

    UPDATE item SET codigo = v_codigo WHERE id = NEW.item_id AND codigo IS NULL;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_trg_gen_codigo_item_insumo() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: public.fn_trg_gen_codigo_item_rollo()
-- ---------------------------------------------------------------------
CREATE FUNCTION public.fn_trg_gen_codigo_item_rollo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_articulo_codigo TEXT;
    v_fibra           TEXT;
    v_rib             TEXT;
BEGIN
    SELECT codigo INTO v_articulo_codigo FROM articulo WHERE id = NEW.articulo_id;
    SELECT COALESCE(fibra::text, '1') INTO v_fibra FROM articulo WHERE id = NEW.articulo_id;
    v_rib    := CASE WHEN COALESCE(NEW.flg_rib, false) THEN 'RB-' ELSE '' END;
    UPDATE item
       SET codigo = UPPER('R-' || v_rib || v_articulo_codigo || '-' || v_fibra)
     WHERE id = NEW.item_id AND codigo IS NULL;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_trg_gen_codigo_item_rollo() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: public.fn_trg_grupo_articulo_firma()
-- ---------------------------------------------------------------------
CREATE FUNCTION public.fn_trg_grupo_articulo_firma() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP IN ('INSERT', 'UPDATE') THEN
        PERFORM fn_grupo_articulo_recalc_firma(NEW.grupo_articulo_id);
    END IF;
    IF TG_OP IN ('DELETE', 'UPDATE') THEN
        PERFORM fn_grupo_articulo_recalc_firma(OLD.grupo_articulo_id);
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION public.fn_trg_grupo_articulo_firma() OWNER TO postgres;

