-- FUNCTION: public.get_receta_detalles_partida(integer, integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION public.get_receta_detalles_partida(partida_id integer, id_tipo_receta integer) RETURNS json
    LANGUAGE plpgsql
    AS $$DECLARE
