-- ---------------------------------------------------------------------
-- FUNCTION: public.get_receta_detalles_partida2(integer, integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION public.get_receta_detalles_partida2(partida_id integer, id_tipo_receta integer) RETURNS json
    LANGUAGE plpgsql
