LEFT JOIN iam.rol r ON ur.rol_id=r.id
WHERE r.code IN ('jefe_planta','inventario');


    RETURN 'Solicitud de ingreso registrada correctamente. N° Solicitud: ' || new_entrada_id;
EXCEPTION
    WHEN OTHERS THEN
        RETURN format('Error: %s', SQLERRM);
END;$$;


