-- ---------------------------------------------------------------------
-- FUNCTION: public.prorratear_kilos_turno(time without time zone, interval, numeric)
-- ---------------------------------------------------------------------
CREATE FUNCTION public.prorratear_kilos_turno(hora_inicio time without time zone, duracion interval, kilos numeric) RETURNS TABLE(kilos_dia numeric, kilos_noche numeric)
    LANGUAGE plpgsql
    AS $$
DECLARE
  ts_inicio TIMESTAMP := '2000-01-01'::timestamp + hora_inicio;
  ts_fin TIMESTAMP := ts_inicio + duracion;
  ts_aux TIMESTAMP;

  dia_duracion INTERVAL := interval '0';
  noche_duracion INTERVAL := interval '0';

  turno_dia_ini TIME := '07:00:00';
  turno_dia_fin TIME := '19:00:00';

  bloque_ini TIMESTAMP;
  bloque_fin TIMESTAMP;
BEGIN
  WHILE ts_inicio < ts_fin LOOP
    ts_aux := LEAST(ts_fin, date_trunc('day', ts_inicio) + interval '1 day');

    -- Rango día (07:00–19:00)
    bloque_ini := date_trunc('day', ts_inicio) + turno_dia_ini;
    bloque_fin := date_trunc('day', ts_inicio) + turno_dia_fin;

    dia_duracion := dia_duracion + GREATEST(
      LEAST(ts_aux, bloque_fin) - GREATEST(ts_inicio, bloque_ini),
      interval '0'
    );

    -- Resto es noche
    noche_duracion := noche_duracion + GREATEST(
      ts_aux - ts_inicio - GREATEST(
        LEAST(ts_aux, bloque_fin) - GREATEST(ts_inicio, bloque_ini),
        interval '0'
      ),
      interval '0'
    );

    ts_inicio := ts_aux;
  END LOOP;

  IF (EXTRACT(EPOCH FROM dia_duracion) + EXTRACT(EPOCH FROM noche_duracion)) = 0 THEN
    RETURN QUERY SELECT 0::numeric, 0::numeric;
  END IF;

  RETURN QUERY SELECT
    ROUND(kilos * EXTRACT(EPOCH FROM dia_duracion) / EXTRACT(EPOCH FROM duracion), 4),
    ROUND(kilos * EXTRACT(EPOCH FROM noche_duracion) / EXTRACT(EPOCH FROM duracion), 4);
END;
$$;


ALTER FUNCTION public.prorratear_kilos_turno(hora_inicio time without time zone, duracion interval, kilos numeric) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.activar_lavado_maquina(integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.activar_lavado_maquina(p_receta_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'receta'
    AS $$
DECLARE
    v_receta receta.lavado_maquina%ROWTYPE;
    v_usr_id INT := get_user_id();
BEGIN
    IF NOT jwt_has_permission('produccion.configurar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.configurar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO v_receta FROM receta.lavado_maquina WHERE id = p_receta_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'receta.lavado_maquina id=% no encontrada.', p_receta_id;
    END IF;

    IF v_receta.flg_activo THEN
        RETURN;  -- already active, no-op
    END IF;

    UPDATE receta.lavado_maquina
    SET flg_activo = false, usr_mod = v_usr_id, fyh_mod = now()
    WHERE tipo_lavado_mq_id = v_receta.tipo_lavado_mq_id
      AND valor_origen_id   = v_receta.valor_origen_id
      AND valor_destino_id  = v_receta.valor_destino_id
      AND flg_activo        = true
      AND id               <> p_receta_id;

    UPDATE receta.lavado_maquina
    SET flg_activo = true, usr_mod = v_usr_id, fyh_mod = now()
    WHERE id = p_receta_id;
END;$$;


ALTER FUNCTION receta.activar_lavado_maquina(p_receta_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.actualizar_lavado_maquina(integer, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.actualizar_lavado_maquina(p_receta_id integer, p_pasos jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'receta'
    AS $$
DECLARE
    v_usr_id INT := get_user_id();
BEGIN
    IF NOT jwt_has_permission('produccion.configurar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.configurar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM receta.lavado_maquina WHERE id = p_receta_id) THEN
        RAISE EXCEPTION 'receta.lavado_maquina id=% no encontrada.', p_receta_id;
    END IF;

    IF EXISTS (
        SELECT 1 FROM mes.lavado_maquina
        WHERE receta_id = p_receta_id AND estado = 'COMPLETADO'
    ) THEN
        RAISE EXCEPTION 'receta.lavado_maquina id=% no es editable: tiene ejecuciones completadas.', p_receta_id;
    END IF;

    DELETE FROM receta.lavado_maquina_paso WHERE receta_id = p_receta_id;

    WITH paso_ins AS (
        INSERT INTO receta.lavado_maquina_paso (receta_id, operacion_id, orden, ph, temperatura, tiempo_min, nota)
        SELECT
            p_receta_id,
            (p->>'operacion_id')::SMALLINT,
            (p->>'orden')::SMALLINT,
            (p->>'ph')::NUMERIC,
            (p->>'temperatura')::NUMERIC,
            (p->>'tiempo_min')::SMALLINT,
            p->>'nota'
        FROM jsonb_array_elements(p_pasos) p
        RETURNING id, orden
    )
    INSERT INTO receta.lavado_maquina_paso_insumo (paso_id, item_id, cantidad, orden)
    SELECT
        pi.id,
        (i->>'item_id')::INT,
        (i->>'cantidad')::NUMERIC,
        (i->>'orden')::SMALLINT
    FROM paso_ins pi
    JOIN jsonb_array_elements(p_pasos) p ON (p->>'orden')::SMALLINT = pi.orden
    CROSS JOIN jsonb_array_elements(COALESCE(p->'insumos', '[]')) i;

    UPDATE receta.lavado_maquina
    SET usr_mod = v_usr_id, fyh_mod = now()
    WHERE id = p_receta_id;
END;$$;


ALTER FUNCTION receta.actualizar_lavado_maquina(p_receta_id integer, p_pasos jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.actualizar_tenido(integer, jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.actualizar_tenido(p_receta_id integer, p_data jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'receta'
    AS $$
DECLARE
    v_receta receta.tenido%ROWTYPE;
    v_usr_id INT := get_user_id();
BEGIN
    IF NOT jwt_has_permission('produccion.configurar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.configurar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    SELECT * INTO v_receta FROM receta.tenido WHERE id = p_receta_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Receta ID % no encontrada.', p_receta_id;
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM estado_desarrollo_color
        WHERE id = v_receta.estado_id AND codigo IN ('EN_DESARROLLO', 'RE_LAB')
    ) THEN
        RAISE EXCEPTION 'Receta ID % no es editable en su estado actual.', p_receta_id;
    END IF;

    UPDATE receta.tenido SET
        color_x_cliente_id = COALESCE((p_data->>'color_x_cliente_id')::INT,     color_x_cliente_id),
        -- articulo_tipo_id lo deriva trg_bi_tenido_derive_articulo_tipo; nunca aquí.
        grupo_articulo_id  = COALESCE((p_data->>'grupo_articulo_id')::INT,       grupo_articulo_id),
        fibra              = COALESCE((p_data->>'fibra')::SMALLINT,              fibra),
        tenido_id          = COALESCE((p_data->>'tenido_id')::INT,               tenido_id),
        tipo_receta_id     = COALESCE((p_data->>'tipo_receta_id')::SMALLINT,     tipo_receta_id),
        usr_mod            = v_usr_id,
        fyh_mod            = now()
    WHERE id = p_receta_id;

    IF p_data ? 'pasos' THEN
        DELETE FROM receta.tenido_paso WHERE receta_id = p_receta_id;

        WITH paso_ins AS (
            INSERT INTO receta.tenido_paso (receta_id, operacion_id, orden, ph, temperatura, tiempo_min, nota)
            SELECT
                p_receta_id,
                (p->>'operacion_id')::SMALLINT,
                (p->>'orden')::SMALLINT,
                (p->>'ph')::NUMERIC,
                (p->>'temperatura')::NUMERIC,
                (p->>'tiempo_min')::SMALLINT,
                p->>'nota'
            FROM jsonb_array_elements(p_data->'pasos') p
            RETURNING id, orden
        )
        INSERT INTO receta.tenido_paso_insumo (paso_id, item_id, cantidad, orden)
        SELECT
            pi.id,
            (i->>'item_id')::INT,
            (i->>'cantidad')::NUMERIC,
            (i->>'orden')::SMALLINT
        FROM paso_ins pi
        JOIN jsonb_array_elements(p_data->'pasos') p ON (p->>'orden')::SMALLINT = pi.orden
        CROSS JOIN jsonb_array_elements(COALESCE(p->'insumos', '[]')) i;

        -- Recompute flg_antipilling from the saved insumo set.
        -- Driven by item_insumo_detalle.flg_antipilling on the chemical item — no hardcoded IDs.
        UPDATE receta.tenido
        SET flg_antipilling = EXISTS (
            SELECT 1
            FROM receta.tenido_paso tp
            JOIN receta.tenido_paso_insumo tpi ON tpi.paso_id = tp.id
            JOIN item_insumo_detalle iid ON iid.item_id = tpi.item_id
            WHERE tp.receta_id = p_receta_id AND iid.flg_antipilling = true
        )
        WHERE id = p_receta_id;
    END IF;
END;$$;


ALTER FUNCTION receta.actualizar_tenido(p_receta_id integer, p_data jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.crear_lavado_maquina(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.crear_lavado_maquina(p_data jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'receta'
    AS $$
DECLARE
    v_id     INT;
    v_usr_id INT := get_user_id();
BEGIN
    IF NOT jwt_has_permission('produccion.configurar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.configurar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    INSERT INTO receta.lavado_maquina (
        tipo_lavado_mq_id, valor_origen_id, valor_destino_id,
        flg_activo, usr_cre, fyh_cre
    ) VALUES (
        (p_data->>'tipo_lavado_mq_id')::SMALLINT,
        (p_data->>'valor_origen_id')::SMALLINT,
        (p_data->>'valor_destino_id')::SMALLINT,
        false, v_usr_id, now()
    )
    RETURNING id INTO v_id;

    IF p_data ? 'pasos' THEN
        WITH paso_ins AS (
            INSERT INTO receta.lavado_maquina_paso (receta_id, operacion_id, orden, ph, temperatura, tiempo_min, nota)
            SELECT
                v_id,
                (p->>'operacion_id')::SMALLINT,
                (p->>'orden')::SMALLINT,
                (p->>'ph')::NUMERIC,
                (p->>'temperatura')::NUMERIC,
                (p->>'tiempo_min')::SMALLINT,
                p->>'nota'
            FROM jsonb_array_elements(p_data->'pasos') p
            RETURNING id, orden
        )
        INSERT INTO receta.lavado_maquina_paso_insumo (paso_id, item_id, cantidad, orden)
        SELECT
            pi.id,
            (i->>'item_id')::INT,
            (i->>'cantidad')::NUMERIC,
            (i->>'orden')::SMALLINT
        FROM paso_ins pi
        JOIN jsonb_array_elements(p_data->'pasos') p ON (p->>'orden')::SMALLINT = pi.orden
        CROSS JOIN jsonb_array_elements(COALESCE(p->'insumos', '[]')) i;
    END IF;

    RETURN v_id;
END;$$;


ALTER FUNCTION receta.crear_lavado_maquina(p_data jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.crear_tenido(jsonb)
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.crear_tenido(p_data jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'receta'
    AS $$
DECLARE
    v_id        INT;
    v_estado_id SMALLINT;
    v_usr_id    INT := get_user_id();
    v_grupo     INT := (p_data->>'grupo_articulo_id')::INT;
BEGIN
    IF NOT jwt_has_permission('produccion.configurar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.configurar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF v_grupo IS NULL THEN
        RAISE EXCEPTION 'grupo_articulo_id es requerido'
            USING ERRCODE = 'not_null_violation';
    END IF;

    SELECT id INTO v_estado_id FROM estado_desarrollo_color WHERE codigo = 'EN_DESARROLLO';

    INSERT INTO receta.tenido (
        color_x_cliente_id,
        grupo_articulo_id,
        fibra,
        tenido_id,
        flg_antipilling,
        tipo_receta_id,
        estado_id,
        usr_cre,
        fyh_cre
    ) VALUES (
        (p_data->>'color_x_cliente_id')::INT,
        v_grupo,
        (p_data->>'fibra')::SMALLINT,
        (p_data->>'tenido_id')::INT,
        COALESCE((p_data->>'flg_antipilling')::BOOLEAN, false),
        (p_data->>'tipo_receta_id')::SMALLINT,
        v_estado_id,
        v_usr_id,
        now()
    )
    RETURNING id INTO v_id;

    RETURN v_id;
END;$$;


ALTER FUNCTION receta.crear_tenido(p_data jsonb) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.desactivar_lavado_maquina(integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.desactivar_lavado_maquina(p_receta_id integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'receta'
    AS $$
DECLARE
    v_usr_id INT := get_user_id();
BEGIN
    IF NOT jwt_has_permission('produccion.configurar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.configurar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM receta.lavado_maquina WHERE id = p_receta_id) THEN
        RAISE EXCEPTION 'receta.lavado_maquina id=% no encontrada.', p_receta_id;
    END IF;

    UPDATE receta.lavado_maquina
    SET flg_activo = false, usr_mod = v_usr_id, fyh_mod = now()
    WHERE id = p_receta_id;
END;$$;


ALTER FUNCTION receta.desactivar_lavado_maquina(p_receta_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.fn_trg_lavado_maquina_immutable()
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.fn_trg_lavado_maquina_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM mes.lavado_maquina
        WHERE receta_id = OLD.id AND estado = 'COMPLETADO'
    ) THEN
        RAISE EXCEPTION
            'receta.lavado_maquina id=% cannot be modified: it has completed executions',
            OLD.id;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION receta.fn_trg_lavado_maquina_immutable() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.fn_trg_tenido_immutable()
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.fn_trg_tenido_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM mes.partida_paso pp
        JOIN mes.partida_paso_ejecucion pe ON pe.partida_paso_id = pp.id
        WHERE pp.receta_id = OLD.id
          AND pe.estado IN ('EN_PROCESO', 'COMPLETADO')
    ) THEN
        RAISE EXCEPTION
            'No se puede modificar receta.tenido id=%: tiene ejecuciones en proceso o completadas.',
            OLD.id;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION receta.fn_trg_tenido_immutable() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.fn_trg_tenido_paso_immutable()
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.fn_trg_tenido_paso_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_receta_id INT := COALESCE(OLD.receta_id, NEW.receta_id);
BEGIN
    IF EXISTS (
        SELECT 1
        FROM mes.partida_paso pp
        JOIN mes.partida_paso_ejecucion pe ON pe.partida_paso_id = pp.id
        WHERE pp.receta_id = v_receta_id
          AND pe.estado IN ('EN_PROCESO', 'COMPLETADO')
    ) THEN
        RAISE EXCEPTION
            'No se puede modificar receta.tenido_paso id=%: su receta tiene ejecuciones en proceso o completadas.',
            OLD.id;
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


ALTER FUNCTION receta.fn_trg_tenido_paso_immutable() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.fn_trg_tenido_paso_insumo_immutable()
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.fn_trg_tenido_paso_insumo_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE v_receta_id INT;
BEGIN
    SELECT tp.receta_id INTO v_receta_id
    FROM receta.tenido_paso tp
    WHERE tp.id = COALESCE(OLD.paso_id, NEW.paso_id);

    IF EXISTS (
        SELECT 1
        FROM mes.partida_paso pp
        JOIN mes.partida_paso_ejecucion pe ON pe.partida_paso_id = pp.id
        WHERE pp.receta_id = v_receta_id
          AND pe.estado IN ('EN_PROCESO', 'COMPLETADO')
    ) THEN
        RAISE EXCEPTION
            'No se puede modificar receta.tenido_paso_insumo id=%: su receta tiene ejecuciones en proceso o completadas.',
            OLD.id;
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;


ALTER FUNCTION receta.fn_trg_tenido_paso_insumo_immutable() OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.get_lavado_maquina(integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.get_lavado_maquina(p_receta_id integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'receta'
    AS $$
    SELECT jsonb_build_object(
        'id',               r.id,
        'tipo_lavado_mq_id',r.tipo_lavado_mq_id,
        'valor_origen_id',  r.valor_origen_id,
        'valor_destino_id', r.valor_destino_id,
        'flg_activo',       r.flg_activo,
        'pasos', COALESCE((
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id',              p.id,
                    'operacion_id',    p.operacion_id,
                    'operacion_codigo',op.codigo,
                    'operacion_nombre',op.nombre,
                    'orden',           p.orden,
                    'ph',              p.ph,
                    'temperatura',     p.temperatura,
                    'tiempo_min',      p.tiempo_min,
                    'nota',            p.nota,
                    'insumos', COALESCE((
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'id',          pi.id,
                                'item_id',     pi.item_id,
                                'item_codigo', i.codigo,
                                'item_nombre', i.nombre,
                                'cantidad',    pi.cantidad,
                                'orden',       pi.orden
                            ) ORDER BY pi.orden
                        )
                        FROM receta.lavado_maquina_paso_insumo pi
                        JOIN public.item i ON i.id = pi.item_id
                        WHERE pi.paso_id = p.id
                    ), '[]'::jsonb)
                ) ORDER BY p.orden
            )
            FROM receta.lavado_maquina_paso p
            JOIN receta.operacion op ON op.id = p.operacion_id
            WHERE p.receta_id = r.id
        ), '[]'::jsonb)
    )
    FROM receta.lavado_maquina r
    WHERE r.id = p_receta_id;
$$;


ALTER FUNCTION receta.get_lavado_maquina(p_receta_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.get_tenido(integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.get_tenido(p_receta_id integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'receta', 'doc'
    AS $$
    SELECT jsonb_build_object(
        'id',                 t.id,
        'color_x_cliente_id', t.color_x_cliente_id,
        'color_nombre',       vc.color,
        'tercero_nombre',      vc.cliente,
        'tercero_id',          vc.tercero_id,
        'color_hex',          vc.color_x_cliente_hex,
        'grupo_articulo_id',  t.grupo_articulo_id,
        'articulo_nombre',    ga.nombre,
        'fibra',              t.fibra,
        'tenido_id',          t.tenido_id,
        'tenido_nombre',      td.tenido,
        'flg_antipilling',    t.flg_antipilling,
        'tipo_receta_id',     t.tipo_receta_id,
        'tipo_receta_nombre', tr.tipo_receta,
        'estado_id',          t.estado_id,
        'estado_codigo',      e.codigo,
        'estado_nombre',      e.nombre,
        'flg_produccion',     t.flg_produccion,
        'fyh_produccion',     t.fyh_produccion,
        'fyh_cre',            t.fyh_cre,
        'costo_estimado_kg',  doc.fn_get_costo_receta(t.id),
        'pasos', COALESCE((
            SELECT jsonb_agg(
                jsonb_build_object(
                    'id',              tp.id,
                    'operacion_id',    tp.operacion_id,
                    'operacion_codigo',op.codigo,
                    'operacion_nombre',op.nombre,
                    'orden',           tp.orden,
                    'ph',              tp.ph,
                    'temperatura',     tp.temperatura,
                    'tiempo_min',      tp.tiempo_min,
                    'nota',            tp.nota,
                    'insumos', COALESCE((
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'id',          tpi.id,
                                'item_id',     tpi.item_id,
                                'item_codigo', i.codigo,
                                'item_nombre', i.nombre,
                                'cantidad',    tpi.cantidad,
                                'medida',      iid.medida,
                                'factor_stock', iid.factor_stock,
                                'precio_kg',   pr.precio_kg,
                                'costo_linea', ROUND(
                                    tpi.cantidad
                                    * CASE iid.medida
                                        WHEN 'g/L' THEN (5.0  / 1000.0)
                                        WHEN '%'   THEN (10.0 / 1000.0)
                                        ELSE            (1.0  / 1000.0)
                                      END
                                    * iid.factor_stock
                                    * COALESCE(pr.precio_kg, 0),
                                    4
                                ),
                                'orden',       tpi.orden
                            ) ORDER BY tpi.orden
                        )
                        FROM receta.tenido_paso_insumo tpi
                        JOIN public.item i ON i.id = tpi.item_id
                        JOIN public.item_insumo_detalle iid ON iid.item_id = tpi.item_id
                        LEFT JOIN LATERAL (
                            SELECT COALESCE(
                                (SELECT fpd.precio_unitario FROM doc.factura_proveedor_detalle fpd
                                 WHERE fpd.item_id = tpi.item_id ORDER BY fpd.fyh_cre DESC LIMIT 1),
                                (SELECT cd.precio_unitario FROM doc.compra_detalle cd
                                 WHERE cd.item_id = tpi.item_id ORDER BY cd.fyh_cre DESC LIMIT 1)
                            ) AS precio_kg
                        ) pr ON true
                        WHERE tpi.paso_id = tp.id
                    ), '[]'::jsonb)
                ) ORDER BY tp.orden
            )
            FROM receta.tenido_paso tp
            JOIN receta.operacion op ON op.id = tp.operacion_id
            WHERE tp.receta_id = t.id
        ), '[]'::jsonb)
    )
    FROM receta.tenido t
    JOIN  estado_desarrollo_color e  ON e.id  = t.estado_id
    LEFT JOIN vw_colores          vc ON vc.color_x_cliente_id = t.color_x_cliente_id
    LEFT JOIN grupo_articulo        ga ON ga.id = t.grupo_articulo_id
    LEFT JOIN public.tenido        td ON td.id = t.tenido_id
    LEFT JOIN tipo_receta          tr ON tr.id = t.tipo_receta_id
    WHERE t.id = p_receta_id;
$$;


ALTER FUNCTION receta.get_tenido(p_receta_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.get_tenido_para_partida(bigint, smallint)
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.get_tenido_para_partida(p_partida_id bigint, p_tipo_receta_id smallint DEFAULT NULL::smallint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'receta', 'doc'
    AS $$
    SELECT receta.get_tenido(receta.resolver_tenido_id(p_partida_id, p_tipo_receta_id));
$$;


ALTER FUNCTION receta.get_tenido_para_partida(p_partida_id bigint, p_tipo_receta_id smallint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.get_tenido_versiones(integer)
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.get_tenido_versiones(p_receta_id integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'receta'
    AS $$
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'id',             v.id,
            'estado_codigo',  v.estado_codigo,
            'estado_nombre',  v.estado_nombre,
            'flg_produccion', v.flg_produccion,
            'fyh_cre',        v.fyh_cre,
            'fyh_produccion', v.fyh_produccion,
            'fyh_mod',        v.fyh_mod
        ) ORDER BY v.fyh_cre DESC
    ), '[]'::jsonb)
    FROM receta.vw_tenido v
    WHERE (v.color_x_cliente_id, v.grupo_articulo_id, v.fibra, v.tenido_id, v.flg_antipilling) = (
        SELECT t.color_x_cliente_id, t.grupo_articulo_id, t.fibra, t.tenido_id, t.flg_antipilling
        FROM receta.tenido t
        WHERE t.id = p_receta_id
    );
$$;


ALTER FUNCTION receta.get_tenido_versiones(p_receta_id integer) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.resolver_tenido_id(bigint, smallint)
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.resolver_tenido_id(p_partida_id bigint, p_tipo_receta_id smallint DEFAULT NULL::smallint) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'receta', 'doc'
    AS $$
DECLARE
    v_receta_id    INT;
    v_flg_antipill BOOLEAN;
    v_op_tipo      partida_tipo_enum;
BEGIN
    -- MIGRACIÓN 32 — muro de lotes mezclados ELIMINADO.
    -- Antes esta función contaba COUNT(DISTINCT (articulo_tipo_id, fibra)) sobre los
    -- rollos y lanzaba excepción si había más de una combinación. Ese muro es la
    -- razón por la que existían los artículos forjados ('J 30/1- Gam 50/1') y el
    -- flg_rib: la única forma de meter dos telas en un baño era disfrazarlas de una.
    --
    -- Ya no hace falta. La receta se resuelve por el grupo_articulo_id DECLARADO en
    -- la partida, no infiriéndolo de los rollos — y la composición la valida
    -- crear_partida contra grupo_articulo_miembro. Una partida mezclada resuelve la
    -- receta de su mezcla; una pura, la suya. Sin ambigüedad y sin muro.
    SELECT flg_antipilling INTO v_flg_antipill FROM mes.partida WHERE id = p_partida_id;

    -- REPROCESO: antipilling already applied on first dyeing — always match false
    IF p_tipo_receta_id IS NOT NULL THEN
        SELECT partida_tipo INTO v_op_tipo FROM tipo_receta WHERE id = p_tipo_receta_id;
        IF v_op_tipo = 'REPROCESO' THEN
            v_flg_antipill := false;
        END IF;
    END IF;

    -- Match sobre lo DECLARADO en la partida (grupo + fibra ejecutada), sin pasar
    -- por los rollos. fibra viene de la partida, no del artículo: es el número de
    -- sistemas que se corren, y puede ser menor al que la tela requiere (jaspeados).
    --
    -- LIMIT 1 es seguro porque uq_receta_tenido_aprobada es único sobre
    -- (color, grupo, fibra, tenido, antipilling, tipo_receta) WHERE flg_produccion.
    -- OJO: tipo_receta_id es parte de esa clave — existen ~50 specs con una receta
    -- aprobada por tipo (teñido / reproceso / desmontado). Sin ese filtro el LIMIT 1
    -- elegiría arbitrariamente entre ellas.
    SELECT rt.id INTO v_receta_id
    FROM mes.partida p
    JOIN receta.tenido rt
        ON  rt.color_x_cliente_id = p.color_x_cliente_id
        AND rt.tenido_id          = p.tenido_id
        AND rt.flg_antipilling    = v_flg_antipill
        AND rt.grupo_articulo_id  = p.grupo_articulo_id
        AND rt.fibra              = p.fibra
        AND rt.flg_produccion     = true
        AND (p_tipo_receta_id IS NULL OR rt.tipo_receta_id = p_tipo_receta_id)
    WHERE p.id = p_partida_id
    LIMIT 1;

    RETURN v_receta_id;
END;$$;


ALTER FUNCTION receta.resolver_tenido_id(p_partida_id bigint, p_tipo_receta_id smallint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.solicitar_si_ausente(bigint)
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.solicitar_si_ausente(p_partida_id bigint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'receta', 'doc'
    AS $$
DECLARE
    v_receta_id INT;
    v_estado_id SMALLINT;
    v_usr_id    INT := get_user_id();
    v_key       RECORD;
BEGIN
    -- MIGRACIÓN 32: la spec se toma de la partida (grupo + fibra declarados); ya no
    -- se infiere desde los rollos. Desaparece el chequeo de "una sola combinación
    -- articulo_tipo/fibra" — gemelo del muro eliminado en resolver_tenido_id, y por
    -- el mismo motivo: una partida mezclada tiene una spec perfectamente definida,
    -- la de su grupo.
    SELECT
        p.color_x_cliente_id,
        p.grupo_articulo_id,
        p.fibra,
        p.tenido_id,
        p.flg_antipilling
    INTO v_key
    FROM mes.partida p
    WHERE p.id = p_partida_id;

    IF NOT FOUND OR v_key.grupo_articulo_id IS NULL THEN
        RETURN NULL;
    END IF;

    -- Serialize concurrent calls for the same spec key to prevent duplicate INGRESADO rows.
    -- Advisory lock is transaction-scoped — auto-released on commit/rollback.
    PERFORM pg_advisory_xact_lock(
        hashtext('receta.solicitar_si_ausente'),
        hashtext(format('%s|%s|%s|%s|%s',
            v_key.color_x_cliente_id, v_key.grupo_articulo_id,
            v_key.fibra, v_key.tenido_id, v_key.flg_antipilling))
    );

    -- Skip if any live recipe already exists for this spec
    IF EXISTS (
        SELECT 1 FROM receta.tenido t
        JOIN estado_desarrollo_color e ON e.id = t.estado_id
        WHERE t.color_x_cliente_id = v_key.color_x_cliente_id
          AND t.grupo_articulo_id  = v_key.grupo_articulo_id
          AND t.fibra              = v_key.fibra
          AND t.tenido_id          = v_key.tenido_id
          AND t.flg_antipilling    = v_key.flg_antipilling
          AND e.codigo NOT IN ('HISTORICO', 'CANCELADO', 'RECHAZADO')
    ) THEN
        RETURN NULL;
    END IF;

    SELECT id INTO v_estado_id FROM estado_desarrollo_color WHERE codigo = 'INGRESADO';

    -- articulo_tipo_id lo deriva trg_bi_tenido_derive_articulo_tipo (NULL en mezclas).
    INSERT INTO receta.tenido (
        color_x_cliente_id, grupo_articulo_id, fibra, tenido_id,
        flg_antipilling, estado_id, usr_cre, fyh_cre
    ) VALUES (
        v_key.color_x_cliente_id,
        v_key.grupo_articulo_id,
        v_key.fibra, v_key.tenido_id,
        v_key.flg_antipilling, v_estado_id, v_usr_id, now()
    )
    RETURNING id INTO v_receta_id;

    RETURN v_receta_id;
END;$$;


ALTER FUNCTION receta.solicitar_si_ausente(p_partida_id bigint) OWNER TO postgres;

-- ---------------------------------------------------------------------
-- FUNCTION: receta.transicionar_tenido(integer, smallint)
-- ---------------------------------------------------------------------
CREATE FUNCTION receta.transicionar_tenido(p_receta_id integer, p_estado_id smallint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'iam', 'public', 'receta'
    AS $$
DECLARE
    v_receta       receta.tenido%ROWTYPE;
    v_aprobado_id  SMALLINT;
    v_historico_id SMALLINT;
    v_usr_id       INT := get_user_id();
BEGIN
    IF NOT jwt_has_permission('produccion.configurar') THEN
        RAISE EXCEPTION 'Sin permiso: se requiere produccion.configurar'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- Lock and fetch current recipe
    SELECT * INTO v_receta FROM receta.tenido WHERE id = p_receta_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Receta ID % no encontrada.', p_receta_id;
    END IF;

    -- Validate target state exists
    IF NOT EXISTS (SELECT 1 FROM estado_desarrollo_color WHERE id = p_estado_id) THEN
        RAISE EXCEPTION 'estado_id % no válido.', p_estado_id;
    END IF;

    -- Guard: already in target state — no-op
    IF v_receta.estado_id = p_estado_id THEN
        RETURN;
    END IF;

    -- Enforce allowed transitions (backend is authoritative — frontend may hide buttons
    -- as UX but cannot be the only enforcement).
    IF NOT EXISTS (
        SELECT 1
        FROM (VALUES
            ('INGRESADO',       'EN_DESARROLLO'),
            ('EN_DESARROLLO',   'ENVIADO_CLIENTE'),
            ('EN_DESARROLLO',   'RECHAZADO'),
            ('EN_DESARROLLO',   'CANCELADO'),
            ('ENVIADO_CLIENTE', 'APROBADO'),
            ('ENVIADO_CLIENTE', 'RECHAZADO'),
            ('ENVIADO_CLIENTE', 'RE_LAB'),
            ('RE_LAB',          'ENVIADO_CLIENTE'),
            ('RE_LAB',          'RECHAZADO'),
            ('RE_LAB',          'CANCELADO')
        ) AS allowed(desde, hasta)
        JOIN estado_desarrollo_color e_desde ON e_desde.codigo = allowed.desde AND e_desde.id = v_receta.estado_id
        JOIN estado_desarrollo_color e_hasta ON e_hasta.codigo = allowed.hasta AND e_hasta.id = p_estado_id
    ) THEN
        RAISE EXCEPTION 'Transición no permitida para receta %.', p_receta_id;
    END IF;

    SELECT id INTO v_aprobado_id  FROM estado_desarrollo_color WHERE codigo = 'APROBADO';
    SELECT id INTO v_historico_id FROM estado_desarrollo_color WHERE codigo = 'HISTORICO';

    -- Block leaving APROBADO to any state other than HISTORICO if production pasos exist.
    -- Those pasos hold a FK to this recipe — reverting it would corrupt traceability.
    -- Correct action: create a new version via crear_tenido.
    IF v_receta.flg_produccion = true AND p_estado_id != v_historico_id THEN
        IF EXISTS (SELECT 1 FROM mes.partida_paso WHERE receta_id = p_receta_id) THEN
            RAISE EXCEPTION
                'Receta % está asignada a pasos de producción — crear una nueva versión en lugar de revertir.',
                p_receta_id;
        END IF;
    END IF;

    -- On approval: supersede any existing approved recipe for the same spec.
    -- flg_produccion = true identifies the current APROBADO (trigger-maintained).
    -- Keyed on grupo_articulo_id to mirror uq_receta_tenido_aprobada_grupo exactly
    -- (migration 31). Plain '=' not IS NOT DISTINCT FROM: the unique index treats
    -- NULLs as distinct, so NULL-grupo wildcard rows must not supersede each other.
    IF p_estado_id = v_aprobado_id THEN
        UPDATE receta.tenido
        SET estado_id = v_historico_id,
            usr_mod   = v_usr_id,
            fyh_mod   = now()
        WHERE color_x_cliente_id = v_receta.color_x_cliente_id
          AND grupo_articulo_id  = v_receta.grupo_articulo_id
          AND fibra              = v_receta.fibra
          AND tenido_id          = v_receta.tenido_id
          AND flg_antipilling    = v_receta.flg_antipilling
          AND tipo_receta_id     IS NOT DISTINCT FROM v_receta.tipo_receta_id
          AND flg_produccion     = true   -- trigger-maintained: true only when APROBADO
          AND id                <> p_receta_id;
    END IF;

    -- Apply transition (trigger updates flg_produccion automatically)
    UPDATE receta.tenido
    SET estado_id      = p_estado_id,
        fyh_produccion = CASE WHEN p_estado_id = v_aprobado_id THEN now() ELSE fyh_produccion END,
        usr_mod        = v_usr_id,
        fyh_mod        = now()
    WHERE id = p_receta_id;
END;$$;


ALTER FUNCTION receta.transicionar_tenido(p_receta_id integer, p_estado_id smallint) OWNER TO postgres;

