-- ---------------------------------------------------------------------
-- VIEW: public.vw_colores
-- ---------------------------------------------------------------------
CREATE VIEW public.vw_colores AS
 SELECT a.id AS color_x_cliente_id,
    b.id AS color_id,
    b.color,
    (a.cliente_id)::integer AS cliente_id,
    t.nombre AS tono,
    t.nombre AS cliente,
    a.hex AS color_x_cliente_hex,
    b.hex AS color_hex,
    a.tercero_id
   FROM ((public.color_x_cliente a
     JOIN public.color b ON ((a.color_id = b.id)))
     LEFT JOIN public.tercero t ON ((a.tercero_id = t.id)));


ALTER VIEW public.vw_colores OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: public.vw_items
-- ---------------------------------------------------------------------
CREATE VIEW public.vw_items AS
 SELECT i.id AS item_id,
    i.codigo AS item_codigo,
    i.nombre AS item_nombre,
    i.item_tipo_id,
    i.unidad_id,
    it.codigo AS item_tipo_codigo,
    u.codigo AS unidad_codigo
   FROM ((public.item i
     JOIN public.item_tipo it ON ((i.item_tipo_id = it.id)))
     JOIN public.unidad u ON ((i.unidad_id = u.id)));


ALTER VIEW public.vw_items OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: calidad.vw_lotes_pendientes_inspeccion
-- ---------------------------------------------------------------------
CREATE VIEW calidad.vw_lotes_pendientes_inspeccion AS
 SELECT l.id AS lote_id,
    ((((EXTRACT(year FROM l.fyh_cre))::integer % 100) || '-'::text) || lpad((l.secuencia)::text, 5, '0'::text)) AS lote_codigo,
    l.item_id,
    vi.item_codigo,
    vi.item_nombre,
    l.documento_tipo,
    l.documento_id,
        CASE
            WHEN (pc.lote_id IS NOT NULL) THEN active_ppe.ejecucion_id
            ELSE pe.id
        END AS partida_paso_ejecucion_id,
        CASE
            WHEN (pc.lote_id IS NOT NULL) THEN active_ppe.paso_id
            ELSE pp.id
        END AS partida_paso_id,
    m.id AS maquina_id,
    m.codigo AS maquina_codigo,
    o.id AS operacion_id,
    o.codigo AS operacion_codigo,
    p.id AS partida_id,
    p.partida_origen_id,
    (((EXTRACT(year FROM p.fyh_cre))::text || '-'::text) || lpad((p.numero)::text, 4, '0'::text)) AS partida_codigo,
    p.ancho,
    p.rendimiento,
    p.malla,
    p.flg_antipilling,
    p.prioridad_id,
    pr.prioridad,
    p.color_x_cliente_id,
    vc.color_id,
    vc.color AS color_nombre,
    vc.color_hex,
    vc.color_x_cliente_hex,
    l.propietario_id,
    c.nombre AS cliente_nombre,
    l.fyh_cre AS fecha_creacion_lote,
        CASE
            WHEN (pc.lote_id IS NOT NULL) THEN active_ppe.active_fyh_fin
            ELSE pe.fyh_fin
        END AS fecha_produccion,
    (pc.lote_id IS NULL) AS es_output
   FROM (((((((((((inventario.lote l
     JOIN public.vw_items vi ON (((vi.item_id = l.item_id) AND (vi.item_tipo_codigo = 'ROLLO'::text))))
     LEFT JOIN mes.partida_paso_ejecucion pe ON (((pe.id = l.documento_id) AND (l.documento_tipo = 'partida_paso_ejecucion'::text))))
     LEFT JOIN mes.partida_paso pp ON ((pp.id = pe.partida_paso_id)))
     LEFT JOIN mes.partida_componente pc ON ((pc.lote_id = l.id)))
     LEFT JOIN LATERAL ( SELECT ppe.id AS ejecucion_id,
            ppe.maquina_id AS active_maquina_id,
            pp2.id AS paso_id,
            pp2.operacion_id AS active_operacion_id,
            ppe.fyh_fin AS active_fyh_fin
           FROM (mes.partida_paso_ejecucion ppe
             JOIN mes.partida_paso pp2 ON ((pp2.id = ppe.partida_paso_id)))
          WHERE ((pp2.partida_id = pc.partida_id) AND (ppe.estado = ANY (ARRAY['EN_PROCESO'::public.paso_ejecucion_estado_enum, 'COMPLETADO'::public.paso_ejecucion_estado_enum])))
          ORDER BY
                CASE
                    WHEN (ppe.estado = 'EN_PROCESO'::public.paso_ejecucion_estado_enum) THEN 0
                    ELSE 1
                END, pp2.secuencia DESC, ppe.fyh_inicio DESC
         LIMIT 1) active_ppe ON ((pc.lote_id IS NOT NULL)))
     LEFT JOIN mes.operacion o ON ((o.id =
        CASE
            WHEN (pc.lote_id IS NOT NULL) THEN active_ppe.active_operacion_id
            ELSE pp.operacion_id
        END)))
     LEFT JOIN mes.maquina m ON ((m.id =
        CASE
            WHEN (pc.lote_id IS NOT NULL) THEN active_ppe.active_maquina_id
            ELSE pe.maquina_id
        END)))
     LEFT JOIN mes.partida p ON ((p.id =
        CASE
            WHEN (pc.lote_id IS NOT NULL) THEN pc.partida_id
            ELSE pp.partida_id
        END)))
     LEFT JOIN public.tercero c ON ((c.id = p.tercero_id)))
     LEFT JOIN public.prioridad pr ON ((pr.id = p.prioridad_id)))
     LEFT JOIN public.vw_colores vc ON ((vc.color_x_cliente_id = p.color_x_cliente_id)))
  WHERE ((((pc.lote_id IS NULL) AND (pe.id IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
           FROM calidad.inspeccion ci
          WHERE ((ci.lote_id = l.id) AND (ci.partida_paso_ejecucion_id = pe.id)))))) OR ((pc.lote_id IS NOT NULL) AND (active_ppe.ejecucion_id IS NOT NULL) AND (NOT (EXISTS ( SELECT 1
           FROM (calidad.inspeccion ci
             JOIN mes.partida_paso_ejecucion ppe_chk ON ((ppe_chk.id = ci.partida_paso_ejecucion_id)))
          WHERE ((ci.lote_id = l.id) AND (ppe_chk.partida_paso_id = active_ppe.paso_id))))) AND (EXISTS ( SELECT 1
           FROM inventario.lote_saldo ls
          WHERE ((ls.lote_id = l.id) AND (ls.cantidad_actual > (0)::numeric)))))) AND (COALESCE(p.estado_produccion, 'CREADA'::public.partida_estado_produccion_enum) <> ALL (ARRAY['CERRADA'::public.partida_estado_produccion_enum, 'CANCELADA'::public.partida_estado_produccion_enum])));


ALTER VIEW calidad.vw_lotes_pendientes_inspeccion OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: calidad.vw_auditoria_pendiente
-- ---------------------------------------------------------------------
CREATE VIEW calidad.vw_auditoria_pendiente AS
 SELECT p.id AS partida_id,
    (((EXTRACT(year FROM p.fyh_cre))::text || '-'::text) || lpad((p.numero)::text, 4, '0'::text)) AS partida_codigo,
    ter.nombre AS cliente,
    vc.color,
    vc.color_hex,
    t.tenido,
    ga.nombre AS grupo_articulo,
    p.fibra,
    p.malla,
    p.ancho,
    p.rendimiento,
    p.observacion,
    gr.id AS entrega_id,
    gr.serie AS entrega_serie,
    gr.correlativo AS entrega_correlativo,
    i.id AS item_id,
    i.codigo AS item_codigo,
    i.nombre AS item_nombre,
    ird.flg_rib,
    (count(*))::integer AS rollos
   FROM ((((((((((calidad.vw_lotes_pendientes_inspeccion vl
     JOIN inventario.lote l ON ((l.id = vl.lote_id)))
     JOIN mes.partida p ON ((p.id = vl.partida_id)))
     LEFT JOIN public.tercero ter ON ((ter.id = p.tercero_id)))
     LEFT JOIN public.vw_colores vc ON ((vc.color_x_cliente_id = p.color_x_cliente_id)))
     LEFT JOIN public.tenido t ON ((t.id = p.tenido_id)))
     LEFT JOIN public.grupo_articulo ga ON ((ga.id = p.grupo_articulo_id)))
     JOIN public.item i ON ((i.id = l.item_id)))
     LEFT JOIN public.item_rollo_detalle ird ON ((ird.item_id = l.item_id)))
     LEFT JOIN inventario.lote_rollo_detalle lrd ON ((lrd.lote_id = l.id)))
     LEFT JOIN doc.entrega gr ON ((gr.id = lrd.entrega_id)))
  GROUP BY p.id, p.numero, p.fyh_cre, p.tercero_id, ter.nombre, p.color_x_cliente_id, vc.color, vc.color_hex, p.tenido_id, t.tenido, p.grupo_articulo_id, ga.nombre, p.fibra, p.malla, p.rendimiento, p.ancho, p.observacion, gr.id, gr.serie, gr.correlativo, i.id, i.codigo, i.nombre, ird.flg_rib;


ALTER VIEW calidad.vw_auditoria_pendiente OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: calidad.vw_inspecciones
-- ---------------------------------------------------------------------
CREATE VIEW calidad.vw_inspecciones AS
 SELECT i.id AS inspeccion_id,
    i.lote_id,
    ((((EXTRACT(year FROM l.fyh_cre))::integer % 100) || '-'::text) || lpad((l.secuencia)::text, 5, '0'::text)) AS lote_codigo,
    l.item_id,
    vi.item_codigo,
    vi.item_nombre,
    i.partida_paso_ejecucion_id,
    p.id AS partida_id,
    (((EXTRACT(year FROM p.fyh_cre))::text || '-'::text) || lpad((p.numero)::text, 4, '0'::text)) AS partida_codigo,
    p.partida_origen_id,
    t.nombre AS cliente_nombre,
    vc.color_id,
    vc.color AS color_nombre,
    vc.color_hex,
    vc.color_x_cliente_hex,
    op.codigo AS operacion_codigo,
    i.resultado,
    i.observacion,
    i.empleado_id,
    e.nombre AS empleado_nombre,
    i.fyh_inspeccion
   FROM (((((((((calidad.inspeccion i
     LEFT JOIN inventario.lote l ON ((l.id = i.lote_id)))
     LEFT JOIN public.vw_items vi ON ((vi.item_id = l.item_id)))
     LEFT JOIN mes.partida_paso_ejecucion ppe ON ((ppe.id = i.partida_paso_ejecucion_id)))
     LEFT JOIN mes.partida_paso pp ON ((pp.id = ppe.partida_paso_id)))
     LEFT JOIN mes.partida p ON ((p.id = pp.partida_id)))
     LEFT JOIN public.tercero t ON ((t.id = p.tercero_id)))
     LEFT JOIN public.vw_colores vc ON ((vc.color_x_cliente_id = p.color_x_cliente_id)))
     LEFT JOIN mes.operacion op ON ((op.id = pp.operacion_id)))
     LEFT JOIN mes.empleado e ON ((e.id = i.empleado_id)));


ALTER VIEW calidad.vw_inspecciones OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: calidad.vw_partidas_pendientes_calidad
-- ---------------------------------------------------------------------
CREATE VIEW calidad.vw_partidas_pendientes_calidad AS
 WITH base AS (
         SELECT v.partida_id,
            v.partida_codigo,
            v.partida_origen_id,
            v.cliente_nombre,
            v.prioridad_id,
            v.color_id,
            v.color_nombre,
            v.color_hex,
            v.color_x_cliente_hex,
            v.operacion_codigo,
            v.lote_id,
            v.fecha_creacion_lote,
            v.es_output,
            l.cantidad AS peso_kg
           FROM (calidad.vw_lotes_pendientes_inspeccion v
             JOIN inventario.lote l ON ((l.id = v.lote_id)))
          WHERE (v.partida_id IS NOT NULL)
        ), agg AS (
         SELECT base.partida_id,
            base.partida_codigo,
            base.partida_origen_id,
            base.cliente_nombre,
            base.prioridad_id,
            base.color_id,
            base.color_nombre,
            base.color_hex,
            base.color_x_cliente_hex,
            count(*) AS lotes_pendientes_qc,
            array_agg(DISTINCT base.operacion_codigo ORDER BY base.operacion_codigo) FILTER (WHERE (base.operacion_codigo IS NOT NULL)) AS operaciones_pendientes,
            min(base.fecha_creacion_lote) AS lote_pendiente_mas_antiguo,
            count(*) FILTER (WHERE base.es_output) AS lotes_output_pendientes_qc,
            COALESCE(sum(base.peso_kg) FILTER (WHERE base.es_output), (0)::numeric) AS peso_output_pendiente_kg
           FROM base
          GROUP BY base.partida_id, base.partida_codigo, base.partida_origen_id, base.cliente_nombre, base.prioridad_id, base.color_id, base.color_nombre, base.color_hex, base.color_x_cliente_hex
        )
 SELECT a.partida_id,
    a.partida_codigo,
    a.partida_origen_id,
    a.cliente_nombre,
    a.prioridad_id,
    a.color_id,
    a.color_nombre,
    a.color_hex,
    a.color_x_cliente_hex,
    a.lotes_pendientes_qc,
    a.operaciones_pendientes,
    a.lote_pendiente_mas_antiguo,
    a.lotes_output_pendientes_qc,
    a.peso_output_pendiente_kg,
    ( SELECT count(DISTINCT pc.lote_id) AS count
           FROM mes.partida_componente pc
          WHERE ((pc.partida_id = a.partida_id) AND (pc.lote_id IS NOT NULL) AND (EXISTS ( SELECT 1
                   FROM (mes.partida_paso pp
                     JOIN mes.partida_paso_ejecucion ppe ON ((ppe.partida_paso_id = pp.id)))
                  WHERE ((pp.partida_id = a.partida_id) AND (ppe.estado = 'EN_PROCESO'::public.paso_ejecucion_estado_enum)))))) AS lotes_en_produccion,
    ( SELECT count(*) AS count
           FROM mes.partida_componente
          WHERE ((partida_componente.partida_id = a.partida_id) AND (partida_componente.lote_id IS NOT NULL))) AS lotes_asignados_total,
    (EXISTS ( SELECT 1
           FROM mes.partida rw
          WHERE ((rw.partida_origen_id = a.partida_id) AND (rw.estado_produccion <> ALL (ARRAY['CANCELADA'::public.partida_estado_produccion_enum, 'TECO'::public.partida_estado_produccion_enum, 'CERRADA'::public.partida_estado_produccion_enum]))))) AS tiene_rework_activo
   FROM agg a
  ORDER BY a.lote_pendiente_mas_antiguo;


ALTER VIEW calidad.vw_partidas_pendientes_calidad OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_aprobados_sin_despacho
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_aprobados_sin_despacho AS
 WITH lineas AS (
         SELECT lrd.entrega_id,
            gr_ing.serie,
            gr_ing.correlativo,
            (gr_ing.fecha_emision)::date AS fecha_emision,
            p.tercero_id,
            t.nombre AS cliente,
            p.id AS partida_id,
            o.id AS operacion_id,
            o.nombre AS operacion,
            o.codigo AS op_codigo,
            false AS es_antipilling,
            p.grupo_articulo_id,
            ga.nombre AS grupo_articulo,
            p.color_x_cliente_id,
            c.color,
            p.tenido_id,
            ten.tenido,
            ar.fibra,
            p.tercero_id AS partida_tercero_id,
            p.flg_antipilling,
            sum(COALESCE(source_l.cantidad, l_1.cantidad)) AS peso_kg
           FROM ((((((((((((((inventario.lote l_1
             JOIN mes.partida_paso_ejecucion pe_out ON ((pe_out.id = l_1.documento_id)))
             JOIN mes.partida_paso opp_out ON ((opp_out.id = pe_out.partida_paso_id)))
             JOIN mes.partida p ON (((p.id = opp_out.partida_id) AND (p.fyh_elm IS NULL))))
             JOIN public.tercero t ON ((t.id = p.tercero_id)))
             LEFT JOIN inventario.lote_rollo_detalle lrd ON ((lrd.lote_id = l_1.id)))
             LEFT JOIN doc.entrega gr_ing ON ((gr_ing.id = lrd.entrega_id)))
             LEFT JOIN inventario.lote source_l ON ((source_l.id = lrd.origen_lote_id)))
             JOIN mes.partida_paso opp ON (((opp.partida_id = p.id) AND (EXISTS ( SELECT 1
                   FROM mes.partida_paso_ejecucion pe_c
                  WHERE ((pe_c.partida_paso_id = opp.id) AND (pe_c.estado = 'COMPLETADO'::public.paso_ejecucion_estado_enum)))))))
             JOIN mes.operacion o ON ((o.id = opp.operacion_id)))
             JOIN LATERAL ( SELECT ar2.fibra
                   FROM (public.item_rollo_detalle ird2
                     JOIN public.articulo ar2 ON ((ar2.id = ird2.articulo_id)))
                  WHERE (ird2.item_id = l_1.item_id)
                 LIMIT 1) ar ON (true))
             JOIN public.grupo_articulo ga ON ((ga.id = p.grupo_articulo_id)))
             JOIN public.color_x_cliente cxc ON ((cxc.id = p.color_x_cliente_id)))
             JOIN public.color c ON ((c.id = cxc.color_id)))
             LEFT JOIN public.tenido ten ON (((ten.id = p.tenido_id) AND (o.codigo = 'TENIDO'::text))))
          WHERE ((l_1.documento_tipo = 'partida_paso_ejecucion'::text) AND (l_1.fyh_elm IS NULL) AND (NOT (EXISTS ( SELECT 1
                   FROM ((doc.entrega_detalle grd2
                     JOIN doc.entrega gr2 ON (((gr2.id = grd2.entrega_id) AND (gr2.fyh_elm IS NULL))))
                     JOIN doc.entrega_tipo grt2 ON (((grt2.id = gr2.entrega_tipo_id) AND (grt2.codigo = 'DESPACHO_CLIENTE'::text))))
                  WHERE (grd2.lote_id = l_1.id)))))
          GROUP BY lrd.entrega_id, gr_ing.serie, gr_ing.correlativo, gr_ing.fecha_emision, p.tercero_id, t.nombre, p.id, o.id, o.nombre, o.codigo, p.grupo_articulo_id, ga.nombre, p.color_x_cliente_id, c.color, p.tenido_id, ten.tenido, ar.fibra, p.flg_antipilling
        ), antipilling AS (
         SELECT l_1.entrega_id,
            l_1.serie,
            l_1.correlativo,
            l_1.fecha_emision,
            l_1.tercero_id,
            l_1.cliente,
            l_1.partida_id,
            ( SELECT o.id
                   FROM mes.operacion o
                  WHERE (o.codigo = 'ANTIPILLING'::text)) AS operacion_id,
            'Antipilling'::text AS operacion,
            'ANTIPILLING'::text AS op_codigo,
            true AS es_antipilling,
            l_1.grupo_articulo_id,
            l_1.grupo_articulo,
            l_1.color_x_cliente_id,
            l_1.color,
            l_1.tenido_id,
            l_1.tenido,
            l_1.fibra,
            l_1.partida_tercero_id,
            l_1.flg_antipilling,
            l_1.peso_kg
           FROM lineas l_1
          WHERE ((l_1.flg_antipilling = true) AND (l_1.op_codigo = 'TENIDO'::text))
        ), all_lineas AS (
         SELECT lineas.entrega_id,
            lineas.serie,
            lineas.correlativo,
            lineas.fecha_emision,
            lineas.tercero_id,
            lineas.cliente,
            lineas.partida_id,
            lineas.operacion_id,
            lineas.operacion,
            lineas.op_codigo,
            lineas.es_antipilling,
            lineas.grupo_articulo_id,
            lineas.grupo_articulo,
            lineas.color_x_cliente_id,
            lineas.color,
            lineas.tenido_id,
            lineas.tenido,
            lineas.fibra,
            lineas.partida_tercero_id,
            lineas.flg_antipilling,
            lineas.peso_kg
           FROM lineas
        UNION ALL
         SELECT antipilling.entrega_id,
            antipilling.serie,
            antipilling.correlativo,
            antipilling.fecha_emision,
            antipilling.tercero_id,
            antipilling.cliente,
            antipilling.partida_id,
            antipilling.operacion_id,
            antipilling.operacion,
            antipilling.op_codigo,
            antipilling.es_antipilling,
            antipilling.grupo_articulo_id,
            antipilling.grupo_articulo,
            antipilling.color_x_cliente_id,
            antipilling.color,
            antipilling.tenido_id,
            antipilling.tenido,
            antipilling.fibra,
            antipilling.partida_tercero_id,
            antipilling.flg_antipilling,
            antipilling.peso_kg
           FROM antipilling
        )
 SELECT l.entrega_id,
    l.serie,
    l.correlativo,
    l.fecha_emision,
    l.tercero_id,
    l.cliente,
    l.partida_id,
    l.operacion_id,
    l.operacion,
    l.es_antipilling,
    l.grupo_articulo_id,
    l.grupo_articulo,
    l.color_x_cliente_id,
    l.color,
    l.tenido_id,
    l.tenido,
    l.peso_kg AS peso_total,
    billed.peso_facturado,
    (l.peso_kg - billed.peso_facturado) AS peso_pendiente,
    px.precio_kg,
    round(((l.peso_kg - billed.peso_facturado) * px.precio_kg), 2) AS subtotal,
    (px.precio_kg IS NULL) AS sin_precio,
    (((((
        CASE
            WHEN l.es_antipilling THEN 'Antipilling'::text
            ELSE COALESCE(l.tenido, l.operacion)
        END || ' '::text) || l.grupo_articulo) || ' '::text) || (l.color)::text) || COALESCE((((' - Ref. '::text || l.serie) || '-'::text) || l.correlativo), ''::text)) AS descripcion
   FROM ((all_lineas l
     LEFT JOIN LATERAL ( SELECT
                CASE
                    WHEN l.es_antipilling THEN doc.fn_get_precio(l.operacion_id, NULL::integer, l.partida_tercero_id, NULL::integer, NULL::integer, NULL::smallint)
                    ELSE doc.fn_get_precio(l.operacion_id, l.color_x_cliente_id, l.partida_tercero_id,
                    CASE
                        WHEN (l.op_codigo = 'TENIDO'::text) THEN doc.fn_familia_precio(l.grupo_articulo_id, l.partida_tercero_id)
                        ELSE l.grupo_articulo_id
                    END,
                    CASE
                        WHEN (l.op_codigo = 'TENIDO'::text) THEN l.tenido_id
                        ELSE NULL::integer
                    END, l.fibra)
                END AS precio_kg) px ON (true))
     LEFT JOIN LATERAL ( SELECT COALESCE(sum(fd.cantidad), (0)::numeric) AS peso_facturado
           FROM (doc.factura_detalle fd
             JOIN doc.factura f ON (((f.id = fd.factura_id) AND (f.estado <> 'anulada'::public.factura_estado_enum))))
          WHERE ((NOT (fd.entrega_id IS DISTINCT FROM l.entrega_id)) AND (fd.partida_id = l.partida_id) AND (fd.operacion_id = l.operacion_id) AND (fd.grupo_articulo_id = l.grupo_articulo_id) AND (fd.color_x_cliente_id = l.color_x_cliente_id) AND (NOT (fd.tenido_id IS DISTINCT FROM l.tenido_id)) AND (fd.es_antipilling = l.es_antipilling))) billed ON (true))
  WHERE ((l.peso_kg - billed.peso_facturado) > 0.001);


ALTER VIEW doc.vw_aprobados_sin_despacho OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_catalogo_precios_historico
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_catalogo_precios_historico AS
 SELECT cp.id,
    cp.operacion_id,
    op.nombre AS operacion,
    cp.color_x_cliente_id,
    c.color,
    cp.tercero_id,
    t.nombre AS cliente,
    cp.grupo_articulo_id,
    ga.nombre AS grupo_articulo,
    cp.tenido_id,
    ten.tenido,
    cp.fibra,
    cp.precio_kg,
    cp.costo_kg,
    cp.usr_cre,
    cp.fyh_cre,
    cp.usr_elm,
    cp.fyh_elm,
    (cp.fyh_elm IS NULL) AS activo
   FROM ((((((doc.catalogo_precios cp
     JOIN mes.operacion op ON ((op.id = cp.operacion_id)))
     LEFT JOIN public.color_x_cliente cxc ON ((cxc.id = cp.color_x_cliente_id)))
     LEFT JOIN public.color c ON ((c.id = cxc.color_id)))
     LEFT JOIN public.tercero t ON ((t.id = COALESCE(cp.tercero_id, cxc.tercero_id))))
     LEFT JOIN public.grupo_articulo ga ON ((ga.id = cp.grupo_articulo_id)))
     LEFT JOIN public.tenido ten ON ((ten.id = cp.tenido_id)))
  ORDER BY cp.fyh_cre DESC;


ALTER VIEW doc.vw_catalogo_precios_historico OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_compras
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_compras AS
 SELECT c.id,
    c.tercero_id,
    p.nombre AS proveedor_nombre,
    c.fecha,
    facturas.total_facturas,
    facturas.facturas_ids,
    facturas.facturas_numeros,
    facturas.monto_facturas_total,
    facturas.estado_pago_consolidado,
    COALESCE(det.total_items, (0)::bigint) AS total_items,
    COALESCE(det.monto_total, (0)::numeric) AS monto_total,
    COALESCE(entregas.total_entregas, (0)::bigint) AS total_entregas,
    COALESCE(letras.total_letras, (0)::bigint) AS total_letras,
    COALESCE(letras.monto_letras_pendiente, (0)::numeric) AS monto_letras_pendiente,
        CASE
            WHEN (det.total_items = 0) THEN 'sin_lineas'::text
            WHEN (COALESCE(recepcion.qty_recibida, (0)::numeric) = (0)::numeric) THEN 'pendiente'::text
            WHEN (COALESCE(recepcion.qty_pendiente, (0)::numeric) <= (0)::numeric) THEN 'completo'::text
            ELSE 'parcial'::text
        END AS estado_ingreso,
    c.observacion,
    c.fyh_elm,
    c.usr_cre,
    c.fyh_cre
   FROM ((((((doc.compra c
     JOIN public.tercero p ON ((p.id = c.tercero_id)))
     LEFT JOIN LATERAL ( SELECT count(*) AS total_facturas,
            jsonb_agg(fp.id ORDER BY fp.fyh_cre) AS facturas_ids,
            string_agg(((fp.serie || '-'::text) || fp.numero), ', '::text ORDER BY fp.fyh_cre) AS facturas_numeros,
            sum(fp.total) AS monto_facturas_total,
                CASE
                    WHEN (count(*) = 0) THEN 'sin_factura'::text
                    WHEN bool_and((fp.estado_pago = 'total'::public.estado_pago_enum)) THEN 'total'::text
                    WHEN bool_or((fp.estado_pago <> 'pendiente'::public.estado_pago_enum)) THEN 'parcial'::text
                    ELSE 'pendiente'::text
                END AS estado_pago_consolidado
           FROM (doc.compra_factura_proveedor cfp
             JOIN doc.factura_proveedor fp ON ((fp.id = cfp.factura_proveedor_id)))
          WHERE (cfp.compra_id = c.id)) facturas ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS total_items,
            sum((cd.cantidad * cd.precio_unitario)) AS monto_total
           FROM doc.compra_detalle cd
          WHERE (cd.compra_id = c.id)) det ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS total_entregas
           FROM doc.compra_entrega cgr
          WHERE (cgr.compra_id = c.id)) entregas ON (true))
     LEFT JOIN LATERAL ( SELECT count(DISTINCT lf.letra_id) AS total_letras,
            sum(lf.monto_aplicado) FILTER (WHERE (l.estado = 'emitida'::public.letra_estado_enum)) AS monto_letras_pendiente
           FROM ((doc.compra_factura_proveedor cfp
             JOIN doc.letra_factura lf ON ((lf.factura_proveedor_id = cfp.factura_proveedor_id)))
             JOIN doc.letra l ON ((l.id = lf.letra_id)))
          WHERE (cfp.compra_id = c.id)) letras ON (true))
     LEFT JOIN LATERAL ( SELECT sum((cd.cantidad - cd.cantidad_recibida)) AS qty_pendiente,
            sum(cd.cantidad_recibida) AS qty_recibida
           FROM doc.compra_detalle cd
          WHERE (cd.compra_id = c.id)) recepcion ON (true));


ALTER VIEW doc.vw_compras OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_compras_item_mes
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_compras_item_mes AS
 WITH facturas_con_detalle AS (
         SELECT DISTINCT factura_proveedor_detalle.factura_proveedor_id
           FROM doc.factura_proveedor_detalle
        ), lineas AS (
         SELECT fp.id AS factura_proveedor_id,
            fp.tercero_id,
            fp.fecha_emision,
            fpd.item_id,
            fpd.cantidad,
            fpd.subtotal_linea AS monto_exigv,
            fpd.total_linea AS monto_conigv,
            'factura'::text AS fuente
           FROM (doc.factura_proveedor_detalle fpd
             JOIN doc.factura_proveedor fp ON ((fp.id = fpd.factura_proveedor_id)))
          WHERE (fp.estado_pago <> 'anulado'::public.estado_pago_enum)
        UNION ALL
         SELECT fp.id AS factura_proveedor_id,
            fp.tercero_id,
            fp.fecha_emision,
            cd.item_id,
            cd.cantidad,
            (cd.cantidad * cd.precio_unitario) AS monto_exigv,
            ((cd.cantidad * cd.precio_unitario) * 1.18) AS monto_conigv,
            'compra'::text AS fuente
           FROM ((doc.compra_factura_proveedor cfp
             JOIN doc.factura_proveedor fp ON ((fp.id = cfp.factura_proveedor_id)))
             JOIN doc.compra_detalle cd ON ((cd.compra_id = cfp.compra_id)))
          WHERE ((fp.estado_pago <> 'anulado'::public.estado_pago_enum) AND (NOT (EXISTS ( SELECT 1
                   FROM facturas_con_detalle fcd
                  WHERE (fcd.factura_proveedor_id = fp.id)))))
        )
 SELECT l.tercero_id,
    t.nombre AS proveedor_nombre,
    l.item_id,
    i.codigo AS item_codigo,
    i.nombre AS item_nombre,
    un.codigo AS unidad_codigo,
    (EXTRACT(year FROM l.fecha_emision))::integer AS ano,
    (EXTRACT(month FROM l.fecha_emision))::integer AS mes,
    to_char((l.fecha_emision)::timestamp with time zone, 'YYYY-MM'::text) AS ano_mes,
    sum(l.cantidad) AS cantidad_total,
    sum(l.monto_exigv) AS monto_exigv,
    sum(l.monto_conigv) AS monto_conigv,
        CASE
            WHEN bool_and((l.fuente = 'factura'::text)) THEN 'factura'::text
            WHEN bool_and((l.fuente = 'compra'::text)) THEN 'compra'::text
            ELSE 'mixto'::text
        END AS fuente
   FROM (((lineas l
     JOIN public.tercero t ON ((t.id = l.tercero_id)))
     JOIN public.item i ON ((i.id = l.item_id)))
     JOIN public.unidad un ON ((un.id = i.unidad_id)))
  GROUP BY l.tercero_id, t.nombre, l.item_id, i.codigo, i.nombre, un.codigo, (EXTRACT(year FROM l.fecha_emision)), (EXTRACT(month FROM l.fecha_emision)), (to_char((l.fecha_emision)::timestamp with time zone, 'YYYY-MM'::text));


ALTER VIEW doc.vw_compras_item_mes OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_compras_recepcion
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_compras_recepcion AS
 SELECT c.id AS compra_id,
    c.tercero_id,
    t.nombre AS proveedor_nombre,
    c.fecha,
    cd.id AS compra_detalle_id,
    cd.item_id,
    i.codigo AS item_codigo,
    i.nombre AS item_nombre,
    un.codigo AS unidad_codigo,
    cd.cantidad AS cantidad_ordenada,
    cd.cantidad_recibida,
    (cd.cantidad - cd.cantidad_recibida) AS cantidad_pendiente,
    cd.precio_unitario,
    (cd.cantidad * cd.precio_unitario) AS valor_linea,
        CASE
            WHEN (cd.cantidad_recibida = (0)::numeric) THEN 'pendiente'::text
            WHEN (cd.cantidad_recibida >= cd.cantidad) THEN 'completo'::text
            ELSE 'parcial'::text
        END AS estado_linea,
    c.fyh_elm
   FROM ((((doc.compra c
     JOIN public.tercero t ON ((t.id = c.tercero_id)))
     JOIN doc.compra_detalle cd ON ((cd.compra_id = c.id)))
     JOIN public.item i ON ((i.id = cd.item_id)))
     JOIN public.unidad un ON ((un.id = i.unidad_id)));


ALTER VIEW doc.vw_compras_recepcion OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_cuentas_por_pagar
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_cuentas_por_pagar AS
 SELECT fp.id AS factura_id,
    fp.tercero_id,
    t.nombre AS proveedor_nombre,
    ((fp.serie || '-'::text) || (fp.numero)::text) AS factura_numero,
    fp.fecha_emision,
    fp.fecha_vencimiento AS factura_fecha_vencimiento,
    fp.moneda,
    fp.tipo_cambio,
    fp.subtotal,
    fp.igv,
    fp.total AS factura_total,
    fp.tipo_pago,
    fp.estado_pago,
        CASE
            WHEN (fp.estado_pago = ANY (ARRAY['total'::public.estado_pago_enum, 'anulado'::public.estado_pago_enum])) THEN NULL::integer
            ELSE GREATEST(0, (CURRENT_DATE - fp.fecha_vencimiento))
        END AS factura_dias_vencido,
    (fp.total - COALESCE(saldo.monto_aplicado_total, (0)::numeric)) AS factura_saldo,
    l.id AS letra_id,
    l.numero AS letra_numero,
    lf.monto_aplicado,
    l.monto AS letra_monto,
    l.fecha_giro,
    l.fecha_vencimiento AS letra_fecha_vencimiento,
    l.fecha_pago,
    l.banco,
    l.estado AS letra_estado,
        CASE
            WHEN (l.id IS NULL) THEN NULL::integer
            WHEN (l.estado = ANY (ARRAY['pagada'::public.letra_estado_enum, 'anulada'::public.letra_estado_enum])) THEN NULL::integer
            ELSE GREATEST(0, (CURRENT_DATE - l.fecha_vencimiento))
        END AS letra_dias_vencido
   FROM ((((doc.factura_proveedor fp
     JOIN public.tercero t ON ((t.id = fp.tercero_id)))
     LEFT JOIN LATERAL ( SELECT sum(lf2.monto_aplicado) FILTER (WHERE (l2.estado <> 'anulada'::public.letra_estado_enum)) AS monto_aplicado_total
           FROM (doc.letra_factura lf2
             JOIN doc.letra l2 ON ((l2.id = lf2.letra_id)))
          WHERE (lf2.factura_proveedor_id = fp.id)) saldo ON (true))
     LEFT JOIN doc.letra_factura lf ON ((lf.factura_proveedor_id = fp.id)))
     LEFT JOIN doc.letra l ON ((l.id = lf.letra_id)));


ALTER VIEW doc.vw_cuentas_por_pagar OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_despacho_pendiente
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_despacho_pendiente AS
SELECT
    NULL::bigint AS partida_id,
    NULL::integer AS numero,
    NULL::text AS codigo,
    NULL::public.partida_estado_produccion_enum AS estado,
    NULL::integer AS tercero_id,
    NULL::text AS cliente,
    NULL::integer AS color_x_cliente_id,
    NULL::character varying(25) AS color,
    NULL::text AS tono,
    NULL::date AS fecha_acordada,
    NULL::bigint AS rolls_pendientes,
    NULL::numeric AS kg_pendientes,
    NULL::boolean AS tiene_rolls_mlr,
    NULL::boolean AS tiene_rolls_cliente,
    NULL::boolean AS tiene_mixto;


ALTER VIEW doc.vw_despacho_pendiente OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_entregas_sin_numerar
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_entregas_sin_numerar AS
 SELECT gr.id AS entrega_id,
    gr.entrega_tipo_id,
    grt.codigo AS tipo_codigo,
    grt.nombre AS tipo_nombre,
    grt.flg_emitida,
    gr.tercero_id,
    t.nombre AS tercero,
    gr.fecha_emision,
    gr.fyh_cre,
    count(grd.id) AS lineas,
    COALESCE(sum(grd.n_rollos), (0)::bigint) AS rollos,
    round(COALESCE(sum(grd.cantidad), (0)::numeric), 2) AS kg_total,
    array_agg(DISTINCT (((EXTRACT(year FROM p.fyh_cre))::text || '-'::text) || lpad((p.numero)::text, 4, '0'::text))) FILTER (WHERE (p.id IS NOT NULL)) AS partidas
   FROM (((((((doc.entrega gr
     JOIN doc.entrega_tipo grt ON ((grt.id = gr.entrega_tipo_id)))
     JOIN public.tercero t ON ((t.id = gr.tercero_id)))
     LEFT JOIN doc.entrega_detalle grd ON ((grd.entrega_id = gr.id)))
     LEFT JOIN inventario.lote l ON ((l.id = grd.lote_id)))
     LEFT JOIN mes.partida_paso_ejecucion pe ON (((pe.id = l.documento_id) AND (l.documento_tipo = 'partida_paso_ejecucion'::text))))
     LEFT JOIN mes.partida_paso pp ON ((pp.id = pe.partida_paso_id)))
     LEFT JOIN mes.partida p ON ((p.id = pp.partida_id)))
  WHERE ((gr.serie IS NULL) AND (gr.fyh_elm IS NULL))
  GROUP BY gr.id, gr.entrega_tipo_id, grt.codigo, grt.nombre, grt.flg_emitida, gr.tercero_id, t.nombre, gr.fecha_emision, gr.fyh_cre;


ALTER VIEW doc.vw_entregas_sin_numerar OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_facturas_proveedor
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_facturas_proveedor AS
 SELECT fp.id,
    fp.tercero_id,
    t.nombre AS proveedor_nombre,
    fp.serie,
    fp.numero,
    ((fp.serie || '-'::text) || (fp.numero)::text) AS numero_completo,
    fp.fecha_emision,
    fp.fecha_vencimiento,
    fp.tipo_pago,
    fp.moneda,
    fp.tipo_cambio,
    fp.subtotal,
    fp.igv,
    fp.total,
    fp.estado_pago,
    fp.observacion,
    COALESCE(lineas.total_lineas, (0)::bigint) AS total_lineas,
    COALESCE(letras.total_letras, (0)::bigint) AS total_letras,
    COALESCE(letras.monto_aplicado_total, (0)::numeric) AS monto_aplicado_total,
    (fp.total - COALESCE(letras.monto_aplicado_total, (0)::numeric)) AS saldo_pendiente,
        CASE
            WHEN (fp.estado_pago = ANY (ARRAY['total'::public.estado_pago_enum, 'anulado'::public.estado_pago_enum])) THEN NULL::integer
            ELSE GREATEST(0, (CURRENT_DATE - fp.fecha_vencimiento))
        END AS dias_vencido,
    COALESCE(compras.total_compras, (0)::bigint) AS total_compras,
    fp.fyh_cre,
    fp.usr_cre
   FROM ((((doc.factura_proveedor fp
     JOIN public.tercero t ON ((t.id = fp.tercero_id)))
     LEFT JOIN LATERAL ( SELECT count(*) AS total_lineas
           FROM doc.factura_proveedor_detalle fpd
          WHERE (fpd.factura_proveedor_id = fp.id)) lineas ON (true))
     LEFT JOIN LATERAL ( SELECT count(DISTINCT lf.letra_id) AS total_letras,
            sum(lf.monto_aplicado) FILTER (WHERE (l.estado <> 'anulada'::public.letra_estado_enum)) AS monto_aplicado_total
           FROM (doc.letra_factura lf
             JOIN doc.letra l ON ((l.id = lf.letra_id)))
          WHERE (lf.factura_proveedor_id = fp.id)) letras ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS total_compras
           FROM doc.compra_factura_proveedor cfp
          WHERE (cfp.factura_proveedor_id = fp.id)) compras ON (true));


ALTER VIEW doc.vw_facturas_proveedor OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_familia_precio
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_familia_precio AS
 SELECT f.grupo_articulo_id,
    g.nombre AS grupo_articulo,
    f.tercero_id,
    t.nombre AS cliente,
    (f.tercero_id IS NULL) AS flg_default,
    f.familia_grupo_id,
    gf.nombre AS familia_grupo,
    (EXISTS ( SELECT 1
           FROM doc.articulo_tipo_familia f2
          WHERE (f2.grupo_articulo_id = f.familia_grupo_id))) AS flg_bucket_remapped,
    f.usr_cre,
    f.fyh_cre,
    f.usr_mod,
    f.fyh_mod
   FROM (((doc.articulo_tipo_familia f
     JOIN public.grupo_articulo g ON ((g.id = f.grupo_articulo_id)))
     JOIN public.grupo_articulo gf ON ((gf.id = f.familia_grupo_id)))
     LEFT JOIN public.tercero t ON ((t.id = f.tercero_id)))
  ORDER BY g.nombre, (f.tercero_id IS NULL) DESC;


ALTER VIEW doc.vw_familia_precio OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_letras
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_letras AS
 SELECT l.id,
    l.tercero_id,
    t.nombre AS proveedor_nombre,
    l.numero,
    l.monto,
    l.fecha_giro,
    l.fecha_vencimiento,
    l.fecha_pago,
    l.banco,
    l.estado,
    l.observacion,
    COALESCE(facturas.total_facturas, (0)::bigint) AS total_facturas,
    COALESCE(facturas.monto_aplicado_total, (0)::numeric) AS monto_aplicado_total,
    (l.monto - COALESCE(facturas.monto_aplicado_total, (0)::numeric)) AS monto_libre,
        CASE
            WHEN (l.estado = ANY (ARRAY['pagada'::public.letra_estado_enum, 'anulada'::public.letra_estado_enum])) THEN NULL::integer
            ELSE GREATEST(0, (CURRENT_DATE - l.fecha_vencimiento))
        END AS dias_vencido,
    l.fyh_cre,
    l.usr_cre
   FROM ((doc.letra l
     JOIN public.tercero t ON ((t.id = l.tercero_id)))
     LEFT JOIN LATERAL ( SELECT count(*) AS total_facturas,
            sum(lf.monto_aplicado) AS monto_aplicado_total
           FROM doc.letra_factura lf
          WHERE (lf.letra_id = l.id)) facturas ON (true));


ALTER VIEW doc.vw_letras OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_pendientes_facturacion
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_pendientes_facturacion AS
 WITH lineas AS (
         SELECT lrd.entrega_id,
            gr_ing.serie,
            gr_ing.correlativo,
            (gr_ing.fecha_emision)::date AS fecha_emision,
            p.tercero_id,
            t.nombre AS cliente,
            p.id AS partida_id,
            o.id AS operacion_id,
            o.nombre AS operacion,
            o.codigo AS op_codigo,
            false AS es_antipilling,
            p.grupo_articulo_id,
            ga.nombre AS grupo_articulo,
            p.color_x_cliente_id,
            c.color,
            p.tenido_id,
            ten.tenido,
            ar.fibra,
            p.tercero_id AS partida_tercero_id,
            p.flg_antipilling,
            sum(COALESCE(source_l.cantidad, grd.cantidad)) AS peso_kg
           FROM (((((((((((((((((doc.entrega gr
             JOIN doc.entrega_tipo grt ON (((grt.id = gr.entrega_tipo_id) AND (grt.codigo = 'DESPACHO_CLIENTE'::text))))
             JOIN doc.entrega_detalle grd ON ((grd.entrega_id = gr.id)))
             JOIN inventario.lote l_1 ON (((l_1.id = grd.lote_id) AND (l_1.documento_tipo = 'partida_paso_ejecucion'::text))))
             LEFT JOIN inventario.lote_rollo_detalle lrd ON ((lrd.lote_id = l_1.id)))
             LEFT JOIN doc.entrega gr_ing ON ((gr_ing.id = lrd.entrega_id)))
             LEFT JOIN inventario.lote source_l ON ((source_l.id = lrd.origen_lote_id)))
             JOIN mes.partida_paso_ejecucion pe_out ON ((pe_out.id = l_1.documento_id)))
             JOIN mes.partida_paso opp_out ON ((opp_out.id = pe_out.partida_paso_id)))
             JOIN mes.partida p ON (((p.id = opp_out.partida_id) AND (p.fyh_elm IS NULL))))
             JOIN public.tercero t ON ((t.id = p.tercero_id)))
             JOIN mes.partida_paso opp ON (((opp.partida_id = p.id) AND (EXISTS ( SELECT 1
                   FROM mes.partida_paso_ejecucion pe_c
                  WHERE ((pe_c.partida_paso_id = opp.id) AND (pe_c.estado = 'COMPLETADO'::public.paso_ejecucion_estado_enum)))))))
             JOIN mes.operacion o ON ((o.id = opp.operacion_id)))
             JOIN LATERAL ( SELECT ar2.fibra
                   FROM (public.item_rollo_detalle ird2
                     JOIN public.articulo ar2 ON ((ar2.id = ird2.articulo_id)))
                  WHERE (ird2.item_id = l_1.item_id)
                 LIMIT 1) ar ON (true))
             JOIN public.grupo_articulo ga ON ((ga.id = p.grupo_articulo_id)))
             JOIN public.color_x_cliente cxc ON ((cxc.id = p.color_x_cliente_id)))
             JOIN public.color c ON ((c.id = cxc.color_id)))
             LEFT JOIN public.tenido ten ON (((ten.id = p.tenido_id) AND (o.codigo = 'TENIDO'::text))))
          WHERE (gr.fyh_elm IS NULL)
          GROUP BY lrd.entrega_id, gr_ing.serie, gr_ing.correlativo, gr_ing.fecha_emision, p.tercero_id, t.nombre, p.id, o.id, o.nombre, o.codigo, p.grupo_articulo_id, ga.nombre, p.color_x_cliente_id, c.color, p.tenido_id, ten.tenido, ar.fibra, p.flg_antipilling
        ), antipilling AS (
         SELECT l_1.entrega_id,
            l_1.serie,
            l_1.correlativo,
            l_1.fecha_emision,
            l_1.tercero_id,
            l_1.cliente,
            l_1.partida_id,
            ( SELECT o.id
                   FROM mes.operacion o
                  WHERE (o.codigo = 'ANTIPILLING'::text)) AS operacion_id,
            'Antipilling'::text AS operacion,
            'ANTIPILLING'::text AS op_codigo,
            true AS es_antipilling,
            l_1.grupo_articulo_id,
            l_1.grupo_articulo,
            l_1.color_x_cliente_id,
            l_1.color,
            l_1.tenido_id,
            l_1.tenido,
            l_1.fibra,
            l_1.partida_tercero_id,
            l_1.flg_antipilling,
            l_1.peso_kg
           FROM lineas l_1
          WHERE ((l_1.flg_antipilling = true) AND (l_1.op_codigo = 'TENIDO'::text))
        ), all_lineas AS (
         SELECT lineas.entrega_id,
            lineas.serie,
            lineas.correlativo,
            lineas.fecha_emision,
            lineas.tercero_id,
            lineas.cliente,
            lineas.partida_id,
            lineas.operacion_id,
            lineas.operacion,
            lineas.op_codigo,
            lineas.es_antipilling,
            lineas.grupo_articulo_id,
            lineas.grupo_articulo,
            lineas.color_x_cliente_id,
            lineas.color,
            lineas.tenido_id,
            lineas.tenido,
            lineas.fibra,
            lineas.partida_tercero_id,
            lineas.flg_antipilling,
            lineas.peso_kg
           FROM lineas
        UNION ALL
         SELECT antipilling.entrega_id,
            antipilling.serie,
            antipilling.correlativo,
            antipilling.fecha_emision,
            antipilling.tercero_id,
            antipilling.cliente,
            antipilling.partida_id,
            antipilling.operacion_id,
            antipilling.operacion,
            antipilling.op_codigo,
            antipilling.es_antipilling,
            antipilling.grupo_articulo_id,
            antipilling.grupo_articulo,
            antipilling.color_x_cliente_id,
            antipilling.color,
            antipilling.tenido_id,
            antipilling.tenido,
            antipilling.fibra,
            antipilling.partida_tercero_id,
            antipilling.flg_antipilling,
            antipilling.peso_kg
           FROM antipilling
        )
 SELECT l.entrega_id,
    l.serie,
    l.correlativo,
    l.fecha_emision,
    l.tercero_id,
    l.cliente,
    l.partida_id,
    l.operacion_id,
    l.operacion,
    l.es_antipilling,
    l.grupo_articulo_id,
    l.grupo_articulo,
    l.color_x_cliente_id,
    l.color,
    l.tenido_id,
    l.tenido,
    l.peso_kg AS peso_total,
    billed.peso_facturado,
    (l.peso_kg - billed.peso_facturado) AS peso_pendiente,
    px.precio_kg,
    round(((l.peso_kg - billed.peso_facturado) * px.precio_kg), 2) AS subtotal,
    (px.precio_kg IS NULL) AS sin_precio,
    (((((
        CASE
            WHEN l.es_antipilling THEN 'Antipilling'::text
            ELSE COALESCE(l.tenido, l.operacion)
        END || ' '::text) || l.grupo_articulo) || ' '::text) || (l.color)::text) || COALESCE((((' - Ref. '::text || l.serie) || '-'::text) || l.correlativo), ''::text)) AS descripcion
   FROM ((all_lineas l
     LEFT JOIN LATERAL ( SELECT
                CASE
                    WHEN l.es_antipilling THEN doc.fn_get_precio(l.operacion_id, NULL::integer, l.partida_tercero_id, NULL::integer, NULL::integer, NULL::smallint)
                    ELSE doc.fn_get_precio(l.operacion_id, l.color_x_cliente_id, l.partida_tercero_id,
                    CASE
                        WHEN (l.op_codigo = 'TENIDO'::text) THEN doc.fn_familia_precio(l.grupo_articulo_id, l.partida_tercero_id)
                        ELSE l.grupo_articulo_id
                    END,
                    CASE
                        WHEN (l.op_codigo = 'TENIDO'::text) THEN l.tenido_id
                        ELSE NULL::integer
                    END, l.fibra)
                END AS precio_kg) px ON (true))
     LEFT JOIN LATERAL ( SELECT COALESCE(sum(fd.cantidad), (0)::numeric) AS peso_facturado
           FROM (doc.factura_detalle fd
             JOIN doc.factura f ON (((f.id = fd.factura_id) AND (f.estado <> 'anulada'::public.factura_estado_enum))))
          WHERE ((NOT (fd.entrega_id IS DISTINCT FROM l.entrega_id)) AND (fd.partida_id = l.partida_id) AND (fd.operacion_id = l.operacion_id) AND (fd.grupo_articulo_id = l.grupo_articulo_id) AND (fd.color_x_cliente_id = l.color_x_cliente_id) AND (NOT (fd.tenido_id IS DISTINCT FROM l.tenido_id)) AND (fd.es_antipilling = l.es_antipilling))) billed ON (true))
  WHERE ((l.peso_kg - billed.peso_facturado) > 0.001);


ALTER VIEW doc.vw_pendientes_facturacion OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_stock_lotes
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_stock_lotes AS
 SELECT l.id AS lote_id,
    l.item_id,
    sum(ls.cantidad_actual) AS cantidad_disponible,
    l.fyh_cre AS fecha_hora_ingreso
   FROM (inventario.lote l
     JOIN inventario.lote_saldo ls ON ((ls.lote_id = l.id)))
  WHERE (l.fyh_elm IS NULL)
  GROUP BY l.id, l.item_id, l.fyh_cre
 HAVING (sum(ls.cantidad_actual) > (0)::numeric);


ALTER VIEW inventario.vw_stock_lotes OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_pendientes_proceso
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_pendientes_proceso AS
 WITH rollos AS (
         SELECT lrd.entrega_id,
            ((gr.serie || '-'::text) || COALESCE(gr.correlativo, (gr.id)::text)) AS documento,
            (gr.fecha_emision)::date AS fecha_emision,
            gr.tercero_id,
            tg.nombre AS cliente,
            ird.articulo_id,
            art.nombre AS articulo,
            art.articulo_tipo_id,
            at.nombre AS articulo_tipo,
            art.fibra,
            l.cantidad AS peso_kg,
            lrd.flg_tenido,
            lrd.origen_lote_id,
            (EXISTS ( SELECT 1
                   FROM (mes.partida_componente pc
                     JOIN mes.partida p ON ((p.id = pc.partida_id)))
                  WHERE ((pc.lote_id = l.id) AND (pc.item_id IS NULL) AND (p.estado_produccion <> ALL (ARRAY['TECO'::public.partida_estado_produccion_enum, 'CERRADA'::public.partida_estado_produccion_enum, 'CANCELADA'::public.partida_estado_produccion_enum])) AND (p.fyh_elm IS NULL)))) AS asignado
           FROM (((((((inventario.lote l
             JOIN inventario.lote_rollo_detalle lrd ON ((lrd.lote_id = l.id)))
             JOIN inventario.vw_stock_lotes sl ON ((sl.lote_id = l.id)))
             LEFT JOIN public.item_rollo_detalle ird ON ((ird.item_id = l.item_id)))
             LEFT JOIN public.articulo art ON ((art.id = ird.articulo_id)))
             LEFT JOIN public.articulo_tipo at ON ((at.id = art.articulo_tipo_id)))
             LEFT JOIN doc.entrega gr ON ((gr.id = lrd.entrega_id)))
             LEFT JOIN public.tercero tg ON ((tg.id = gr.tercero_id)))
          WHERE ((l.fyh_elm IS NULL) AND (gr.fyh_elm IS NULL) AND (lrd.entrega_id IS NOT NULL))
        )
 SELECT rollos.entrega_id,
    rollos.documento,
    rollos.fecha_emision,
    rollos.tercero_id,
    rollos.cliente,
    rollos.articulo_id,
    rollos.articulo,
    rollos.articulo_tipo_id,
    rollos.articulo_tipo,
    rollos.fibra,
    count(*) AS rollos_en_stock,
    count(*) FILTER (WHERE (NOT rollos.asignado)) AS rollos_sin_asignar,
    count(*) FILTER (WHERE rollos.asignado) AS rollos_asignados_pendientes,
    count(*) FILTER (WHERE (NOT rollos.flg_tenido)) AS rollos_sin_tenir,
    round(sum(rollos.peso_kg), 2) AS kg_en_stock
   FROM rollos
  WHERE ((rollos.origen_lote_id IS NULL) OR rollos.asignado)
  GROUP BY rollos.entrega_id, rollos.documento, rollos.fecha_emision, rollos.tercero_id, rollos.cliente, rollos.articulo_id, rollos.articulo, rollos.articulo_tipo_id, rollos.articulo_tipo, rollos.fibra;


ALTER VIEW doc.vw_pendientes_proceso OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_precios_estado
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_precios_estado AS
 WITH combos AS (
         SELECT DISTINCT op.id AS operacion_id,
            op.codigo AS operacion_codigo,
            op.nombre AS operacion,
            p.color_x_cliente_id,
            cxc.color_id,
            c.color,
            cxc.tercero_id,
            t.nombre AS cliente,
            p.grupo_articulo_id,
            ga.nombre AS grupo_articulo,
                CASE
                    WHEN (op.codigo = 'TENIDO'::text) THEN p.tenido_id
                    ELSE NULL::integer
                END AS tenido_id,
            ten.tenido,
            p.fibra
           FROM (((((((mes.partida p
             JOIN public.color_x_cliente cxc ON ((cxc.id = p.color_x_cliente_id)))
             JOIN public.color c ON ((c.id = cxc.color_id)))
             JOIN public.tercero t ON ((t.id = cxc.tercero_id)))
             JOIN mes.partida_paso opp ON (((opp.partida_id = p.id) AND (EXISTS ( SELECT 1
                   FROM mes.partida_paso_ejecucion pe_c
                  WHERE ((pe_c.partida_paso_id = opp.id) AND (pe_c.estado = 'COMPLETADO'::public.paso_ejecucion_estado_enum)))))))
             JOIN mes.operacion op ON ((op.id = opp.operacion_id)))
             JOIN public.grupo_articulo ga ON ((ga.id = p.grupo_articulo_id)))
             LEFT JOIN public.tenido ten ON (((ten.id = p.tenido_id) AND (op.codigo = 'TENIDO'::text))))
          WHERE ((p.fyh_elm IS NULL) AND (p.partida_origen_id IS NULL) AND (p.estado_facturacion <> 'facturado'::public.partida_facturacion_enum) AND ((op.codigo <> 'TENIDO'::text) OR (EXISTS ( SELECT 1
                   FROM receta.tenido rt
                  WHERE ((rt.flg_produccion = true) AND (rt.tipo_receta_id = 7) AND ((rt.color_x_cliente_id IS NULL) OR (rt.color_x_cliente_id = p.color_x_cliente_id)) AND (rt.grupo_articulo_id = p.grupo_articulo_id) AND (rt.fibra = p.fibra) AND ((rt.tenido_id IS NULL) OR (rt.tenido_id = p.tenido_id)))))))
        )
 SELECT k.operacion_id,
    k.operacion,
    k.color_x_cliente_id,
    k.color_id,
    k.color,
    k.tercero_id,
    k.cliente,
    k.grupo_articulo_id,
    k.grupo_articulo,
    k.tenido_id,
    k.tenido,
    k.fibra,
    pr.precio_kg,
        CASE
            WHEN (pr.precio_kg IS NULL) THEN 'sin_precio'::text
            ELSE 'con_precio'::text
        END AS estado
   FROM (combos k
     LEFT JOIN LATERAL doc.fn_get_precio(k.operacion_id, k.color_x_cliente_id, k.tercero_id,
        CASE
            WHEN (k.operacion_codigo = 'TENIDO'::text) THEN doc.fn_familia_precio(k.grupo_articulo_id, k.tercero_id)
            ELSE k.grupo_articulo_id
        END, k.tenido_id, k.fibra) pr(precio_kg) ON (true));


ALTER VIEW doc.vw_precios_estado OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_precios_pendientes
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_precios_pendientes AS
 SELECT vw_precios_estado.operacion_id,
    vw_precios_estado.operacion,
    vw_precios_estado.color_x_cliente_id,
    vw_precios_estado.color_id,
    vw_precios_estado.color,
    vw_precios_estado.tercero_id,
    vw_precios_estado.cliente,
    vw_precios_estado.grupo_articulo_id,
    vw_precios_estado.grupo_articulo,
    vw_precios_estado.tenido_id,
    vw_precios_estado.tenido,
    vw_precios_estado.fibra
   FROM doc.vw_precios_estado
  WHERE (vw_precios_estado.estado = 'sin_precio'::text);


ALTER VIEW doc.vw_precios_pendientes OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: doc.vw_venta
-- ---------------------------------------------------------------------
CREATE VIEW doc.vw_venta AS
 SELECT v.id AS venta_id,
    v.tercero_id,
    t.nombre AS cliente,
    v.fecha,
    v.factura_serie,
    v.factura_numero,
    v.factura_fecha_venc,
    v.estado,
    vd.id AS detalle_id,
    vd.linea,
    vd.tipo,
    vd.operacion_id,
    op.nombre AS operacion_nombre,
    vd.item_id,
    it.nombre AS item_nombre,
    vd.partida_id,
    pcod.codigo AS partida_codigo,
    vd.color_x_cliente_id,
    vc.color,
    vd.tenido_id,
    ten.tenido,
    vd.grupo_articulo_id,
    ga.nombre AS grupo_articulo,
    vd.flg_antipilling,
    COALESCE(vd.descripcion, doc.fn_descripcion_linea(vd.tipo, vd.operacion_id, vd.item_id, vd.grupo_articulo_id, vd.color_x_cliente_id, vd.tenido_id, vd.flg_antipilling)) AS descripcion,
    vd.cantidad_kg,
    vd.precio_kg,
    vd.importe
   FROM ((((((((doc.venta v
     JOIN public.tercero t ON ((t.id = v.tercero_id)))
     LEFT JOIN doc.venta_detalle vd ON ((vd.venta_id = v.id)))
     LEFT JOIN mes.operacion op ON ((op.id = vd.operacion_id)))
     LEFT JOIN public.item it ON ((it.id = vd.item_id)))
     LEFT JOIN public.vw_colores vc ON ((vc.color_x_cliente_id = vd.color_x_cliente_id)))
     LEFT JOIN public.tenido ten ON ((ten.id = vd.tenido_id)))
     LEFT JOIN public.grupo_articulo ga ON ((ga.id = vd.grupo_articulo_id)))
     LEFT JOIN LATERAL ( SELECT (((EXTRACT(year FROM p.fyh_cre))::text || '-'::text) || lpad((p.numero)::text, 4, '0'::text)) AS codigo
           FROM mes.partida p
          WHERE (p.id = vd.partida_id)) pcod ON (true));


ALTER VIEW doc.vw_venta OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_cuadre
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_cuadre AS
 SELECT c.id AS cuadre_id,
    c.fecha_cuadre,
    c.fecha_cierre,
    c.estado,
    c.almacen_id,
    ( SELECT max(c2.fecha_cierre) AS max
           FROM inventario.cuadre c2
          WHERE ((c2.estado = 'ejecutado'::inventario.cuadre_estado_enum) AND (c2.id < c.id) AND ((c2.almacen_id = c.almacen_id) OR ((c2.almacen_id IS NULL) AND (c.almacen_id IS NULL))))) AS ult_cuadre_ejecutado_fecha
   FROM inventario.cuadre c;


ALTER VIEW inventario.vw_cuadre OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_entregas_rollos_pendientes
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_entregas_rollos_pendientes AS
 SELECT gr.id AS entrega_id,
    ((gr.serie || '-'::text) || gr.correlativo) AS entrega_numero,
    gr.fecha_emision,
    gr.tercero_id,
    t.nombre AS tercero_nombre,
    (CURRENT_DATE - (gr.fecha_emision)::date) AS dias_espera,
    count(l.id) AS total_rollos,
    count(l.id) FILTER (WHERE (pc.lote_id IS NULL)) AS rollos_pendientes,
    count(l.id) FILTER (WHERE (pc.lote_id IS NOT NULL)) AS rollos_asignados,
    sum(sl.cantidad_disponible) FILTER (WHERE (pc.lote_id IS NULL)) AS peso_pendiente_kg,
    sum(sl.cantidad_disponible) FILTER (WHERE (pc.lote_id IS NOT NULL)) AS peso_asignado_kg,
    sum(sl.cantidad_disponible) AS peso_total_kg
   FROM ((((((doc.entrega gr
     JOIN doc.entrega_tipo grt ON (((grt.id = gr.entrega_tipo_id) AND (grt.codigo = 'CLIENTE_ENVIO_PROCESO'::text))))
     JOIN public.tercero t ON ((t.id = gr.tercero_id)))
     JOIN inventario.lote_rollo_detalle lrd ON ((lrd.entrega_id = gr.id)))
     JOIN inventario.lote l ON (((l.id = lrd.lote_id) AND (l.fyh_elm IS NULL))))
     JOIN inventario.vw_stock_lotes sl ON ((sl.lote_id = l.id)))
     LEFT JOIN mes.partida_componente pc ON ((pc.lote_id = l.id)))
  GROUP BY gr.id, gr.serie, gr.correlativo, gr.fecha_emision, gr.tercero_id, t.nombre
 HAVING (count(l.id) FILTER (WHERE (pc.lote_id IS NULL)) > 0);


ALTER VIEW inventario.vw_entregas_rollos_pendientes OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_item_movimiento_categoria
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_item_movimiento_categoria AS
 SELECT (c.codigo)::text AS codigo,
        CASE c.codigo
            WHEN 'COMPRA'::public.item_movimiento_tipo_categoria_enum THEN 'Compras'::text
            WHEN 'VENTA'::public.item_movimiento_tipo_categoria_enum THEN 'Ventas'::text
            WHEN 'PRODUCCION'::public.item_movimiento_tipo_categoria_enum THEN 'Producción'::text
            WHEN 'PROCESO_EXTERNO'::public.item_movimiento_tipo_categoria_enum THEN 'Proceso externo'::text
            WHEN 'DEVOLUCION'::public.item_movimiento_tipo_categoria_enum THEN 'Devoluciones'::text
            WHEN 'AJUSTE'::public.item_movimiento_tipo_categoria_enum THEN 'Ajustes'::text
            WHEN 'TRANSFERENCIA'::public.item_movimiento_tipo_categoria_enum THEN 'Transferencias'::text
            ELSE NULL::text
        END AS nombre
   FROM unnest(enum_range(NULL::public.item_movimiento_tipo_categoria_enum)) c(codigo);


ALTER VIEW inventario.vw_item_movimiento_categoria OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_item_proveedor_entrega
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_item_proveedor_entrega AS
 SELECT DISTINCT i.id AS item_id,
    i.codigo AS item_codigo,
    i.nombre AS item_nombre,
    gr.tercero_id AS proveedor_id,
    t.nombre AS proveedor_nombre
   FROM ((((doc.entrega gr
     JOIN doc.entrega_tipo grt ON ((grt.id = gr.entrega_tipo_id)))
     JOIN doc.entrega_detalle grd ON ((grd.entrega_id = gr.id)))
     JOIN public.item i ON ((i.id = grd.item_id)))
     JOIN public.tercero t ON ((t.id = gr.tercero_id)))
  WHERE ((grt.flg_emitida = false) AND (t.flg_proveedor = true));


ALTER VIEW inventario.vw_item_proveedor_entrega OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_items_movimientos
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_items_movimientos AS
 SELECT im.id AS movimiento_id,
    im.fecha_hora,
    im.item_id,
    vi.item_codigo,
    vi.item_nombre,
    im.lote_id,
        CASE
            WHEN (l.id IS NOT NULL) THEN ((((EXTRACT(year FROM l.fyh_cre))::integer % 100) || '-'::text) || lpad((l.secuencia)::text, 5, '0'::text))
            ELSE NULL::text
        END AS lote_codigo,
    im.item_movimiento_tipo_id,
    imt.codigo AS tipo_codigo,
    imt.nombre AS tipo_nombre,
    imt.categoria,
    im.cantidad,
    (im.cantidad * ((
        CASE
            WHEN (im.destino_ubicacion_id IS NOT NULL) THEN 1
            ELSE 0
        END +
        CASE
            WHEN (im.origen_ubicacion_id IS NOT NULL) THEN '-1'::integer
            ELSE 0
        END))::numeric) AS cantidad_neta,
    im.origen_ubicacion_id,
    uo.nombre AS origen_nombre,
    im.destino_ubicacion_id,
    ud.nombre AS destino_nombre,
    im.documento_tipo,
    im.documento_id,
    im.observacion
   FROM (((((inventario.item_movimientos im
     LEFT JOIN inventario.item_movimiento_tipo imt ON ((imt.id = im.item_movimiento_tipo_id)))
     LEFT JOIN public.vw_items vi ON ((vi.item_id = im.item_id)))
     LEFT JOIN inventario.lote l ON ((l.id = im.lote_id)))
     LEFT JOIN inventario.ubicacion uo ON ((uo.id = im.origen_ubicacion_id)))
     LEFT JOIN inventario.ubicacion ud ON ((ud.id = im.destino_ubicacion_id)));


ALTER VIEW inventario.vw_items_movimientos OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_stock_lotes_ubicacion
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_stock_lotes_ubicacion AS
 SELECT l.id AS lote_id,
    l.item_id,
    ls.ubicacion_id,
    ls.cantidad_actual AS cantidad_disponible,
    l.fyh_cre AS fecha_hora_ingreso
   FROM (inventario.lote l
     JOIN inventario.lote_saldo ls ON ((ls.lote_id = l.id)))
  WHERE ((l.fyh_elm IS NULL) AND (ls.cantidad_actual > (0)::numeric));


ALTER VIEW inventario.vw_stock_lotes_ubicacion OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_lotes_disponibles
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_lotes_disponibles AS
 SELECT vi.item_id,
    vi.item_codigo,
    vi.item_nombre,
    vi.item_tipo_id,
    vi.item_tipo_codigo,
    sa.lote_id,
    ((((EXTRACT(year FROM l.fyh_cre))::integer % 100) || '-'::text) || lpad((l.secuencia)::text, 5, '0'::text)) AS lote_codigo,
    sa.ubicacion_id,
    sa.cantidad_disponible,
    vi.unidad_id,
    vi.unidad_codigo
   FROM ((inventario.vw_stock_lotes_ubicacion sa
     LEFT JOIN public.vw_items vi ON ((vi.item_id = sa.item_id)))
     LEFT JOIN inventario.lote l ON ((l.id = sa.lote_id)));


ALTER VIEW inventario.vw_lotes_disponibles OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_lotes_rollos_despachados
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_lotes_rollos_despachados AS
 WITH mov AS (
         SELECT im.lote_id,
            sum((im.cantidad * ((
                CASE
                    WHEN (im.destino_ubicacion_id IS NOT NULL) THEN 1
                    ELSE 0
                END +
                CASE
                    WHEN (im.origen_ubicacion_id IS NOT NULL) THEN '-1'::integer
                    ELSE 0
                END))::numeric)) AS saldo,
            bool_or(((im.origen_ubicacion_id IS NOT NULL) AND (imt.categoria <> ALL (ARRAY['PRODUCCION'::public.item_movimiento_tipo_categoria_enum, 'TRANSFERENCIA'::public.item_movimiento_tipo_categoria_enum])))) AS has_egreso
           FROM (inventario.item_movimientos im
             JOIN inventario.item_movimiento_tipo imt ON ((imt.id = im.item_movimiento_tipo_id)))
          GROUP BY im.lote_id
        )
 SELECT l.id AS lote_id,
    ((((EXTRACT(year FROM l.fyh_cre))::integer % 100) || '-'::text) || lpad((l.secuencia)::text, 5, '0'::text)) AS lote_codigo,
    l.item_id,
    i.codigo AS item_codigo,
    i.nombre AS item_nombre,
    un.codigo AS unidad,
    (l.estado_calidad)::text AS estado_calidad,
    l.cantidad AS peso,
    ird.articulo_id,
    art.nombre AS articulo_nombre,
    art.articulo_tipo_id,
    lrd.flg_tenido,
    ird.flg_rib,
    art.fibra,
    lrd.color_x_cliente_id,
    vc.color_id,
    vc.color,
    vc.tono,
    vc.cliente_id,
    vc.color_hex,
    vc.color_x_cliente_hex,
    lrd.tenido_id,
    lrd.ancho,
    lrd.malla,
    lrd.rendimiento,
    lrd.flg_antipilling,
    c.id AS propietario_id,
    c.nombre AS propietario,
    p.id AS partida_id,
    (((EXTRACT(year FROM p.fyh_cre))::text || '-'::text) || lpad((p.numero)::text, 4, '0'::text)) AS partida_codigo,
    lrd.entrega_id,
    e.serie AS entrega_serie,
    e.correlativo AS entrega_correlativo
   FROM (((((((((((((inventario.lote l
     JOIN mov m ON (((m.lote_id = l.id) AND (m.saldo <= (0)::numeric) AND m.has_egreso)))
     JOIN public.item i ON ((i.id = l.item_id)))
     JOIN public.item_tipo it ON (((it.id = i.item_tipo_id) AND (it.codigo = 'ROLLO'::text))))
     JOIN public.item_rollo_detalle ird ON ((ird.item_id = i.id)))
     JOIN public.articulo art ON ((art.id = ird.articulo_id)))
     JOIN public.unidad un ON ((un.id = i.unidad_id)))
     JOIN inventario.lote_rollo_detalle lrd ON (((lrd.lote_id = l.id) AND (lrd.flg_tenido = true))))
     LEFT JOIN public.tercero c ON ((c.id = l.propietario_id)))
     LEFT JOIN mes.partida_paso_ejecucion pe ON (((pe.id = l.documento_id) AND (l.documento_tipo = 'partida_paso_ejecucion'::text))))
     LEFT JOIN mes.partida_paso pp ON ((pp.id = pe.partida_paso_id)))
     LEFT JOIN mes.partida p ON ((p.id = pp.partida_id)))
     LEFT JOIN public.vw_colores vc ON ((vc.color_x_cliente_id = lrd.color_x_cliente_id)))
     LEFT JOIN doc.entrega e ON ((e.id = lrd.entrega_id)));


ALTER VIEW inventario.vw_lotes_rollos_despachados OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_lotes_rollos_stock
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_lotes_rollos_stock AS
 SELECT sa.lote_id,
    sa.item_id,
    i.codigo AS item_codigo,
    i.nombre AS item_nombre,
    sa.ubicacion_id,
    u.nombre AS ubicacion,
    a.nombre AS almacen,
    sa.cantidad_disponible,
    un.codigo AS unidad,
    (l.estado_calidad)::text AS estado_calidad,
    l.cantidad AS peso,
    ird.articulo_id,
    art.nombre AS articulo_nombre,
    art.articulo_tipo_id,
    ird.flg_rib,
    art.fibra,
    lrd.flg_tenido,
    lrd.flg_antipilling,
    lrd.color_x_cliente_id,
    vc.color_id,
    vc.color,
    vc.tono,
    vc.cliente_id,
    vc.color_hex,
    vc.color_x_cliente_hex,
    lrd.tenido_id,
    tn.tenido,
    lrd.ancho,
    lrd.malla,
    lrd.rendimiento,
    l.propietario_id,
    t.nombre AS propietario,
    lrd.entrega_id,
    gr.serie AS entrega_serie,
    gr.correlativo AS entrega_correlativo
   FROM (((((((((((((inventario.vw_stock_lotes_ubicacion sa
     JOIN inventario.lote l ON ((l.id = sa.lote_id)))
     JOIN public.item i ON ((i.id = sa.item_id)))
     JOIN public.item_tipo it ON (((it.id = i.item_tipo_id) AND (it.codigo = 'ROLLO'::text))))
     JOIN public.item_rollo_detalle ird ON ((ird.item_id = i.id)))
     JOIN public.articulo art ON ((art.id = ird.articulo_id)))
     JOIN public.unidad un ON ((un.id = i.unidad_id)))
     LEFT JOIN inventario.ubicacion u ON ((u.id = sa.ubicacion_id)))
     LEFT JOIN inventario.almacen a ON ((a.id = u.almacen_id)))
     LEFT JOIN inventario.lote_rollo_detalle lrd ON ((lrd.lote_id = sa.lote_id)))
     LEFT JOIN doc.entrega gr ON ((gr.id = lrd.entrega_id)))
     LEFT JOIN public.tercero t ON ((t.id = l.propietario_id)))
     LEFT JOIN public.vw_colores vc ON ((vc.color_x_cliente_id = lrd.color_x_cliente_id)))
     LEFT JOIN public.tenido tn ON ((tn.id = lrd.tenido_id)));


ALTER VIEW inventario.vw_lotes_rollos_stock OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_lotes_rollos_disponibles
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_lotes_rollos_disponibles AS
 SELECT s.lote_id,
    s.item_id,
    s.item_codigo,
    s.item_nombre,
    s.ubicacion_id,
    s.ubicacion,
    s.almacen,
    s.cantidad_disponible,
    s.unidad,
    s.estado_calidad,
    s.peso,
    s.articulo_id,
    s.articulo_nombre,
    s.articulo_tipo_id,
    s.flg_rib,
    s.fibra,
    s.flg_tenido,
    s.flg_antipilling,
    s.color_x_cliente_id,
    s.color_id,
    s.color,
    s.tono,
    s.cliente_id,
    s.color_hex,
    s.color_x_cliente_hex,
    s.tenido_id,
    s.tenido,
    s.ancho,
    s.malla,
    s.rendimiento,
    s.propietario_id,
    s.propietario,
    s.entrega_id,
    s.entrega_serie,
    s.entrega_correlativo
   FROM inventario.vw_lotes_rollos_stock s
  WHERE (NOT (EXISTS ( SELECT 1
           FROM (mes.partida_componente pc
             JOIN mes.partida p ON ((p.id = pc.partida_id)))
          WHERE ((pc.lote_id = s.lote_id) AND (p.estado_produccion <> ALL (ARRAY['CERRADA'::public.partida_estado_produccion_enum, 'CANCELADA'::public.partida_estado_produccion_enum])) AND (p.fyh_elm IS NULL)))));


ALTER VIEW inventario.vw_lotes_rollos_disponibles OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_precio_promedio_insumos
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_precio_promedio_insumos AS
 WITH fpd AS (
         SELECT fpd.item_id,
            sum((fpd.cantidad * fpd.precio_unitario)) AS valor_total,
            sum(fpd.cantidad) AS cantidad_total
           FROM doc.factura_proveedor_detalle fpd
          GROUP BY fpd.item_id
        ), cd AS (
         SELECT cd.item_id,
            sum((cd.cantidad * cd.precio_unitario)) AS valor_total,
            sum(cd.cantidad) AS cantidad_total
           FROM doc.compra_detalle cd
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM doc.factura_proveedor_detalle fpd
                  WHERE (fpd.item_id = cd.item_id))))
          GROUP BY cd.item_id
        ), combinado AS (
         SELECT fpd.item_id,
            fpd.valor_total,
            fpd.cantidad_total
           FROM fpd
        UNION ALL
         SELECT cd.item_id,
            cd.valor_total,
            cd.cantidad_total
           FROM cd
        )
 SELECT c.item_id,
    vi.item_codigo,
    vi.item_nombre,
    vi.unidad_codigo,
    round((sum(c.valor_total) / NULLIF(sum(c.cantidad_total), (0)::numeric)), 4) AS precio_promedio_usd,
    sum(c.cantidad_total) AS cantidad_comprada
   FROM (combinado c
     JOIN public.vw_items vi ON ((vi.item_id = c.item_id)))
  GROUP BY c.item_id, vi.item_codigo, vi.item_nombre, vi.unidad_codigo;


ALTER VIEW inventario.vw_precio_promedio_insumos OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_rollos_por_entrega
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_rollos_por_entrega AS
 SELECT gr.id AS entrega_id,
    gr.serie,
    gr.correlativo,
    ((gr.serie || '-'::text) || gr.correlativo) AS entrega_numero,
    gr.fecha_emision,
    gr.tercero_id,
    t.nombre AS tercero_nombre,
    grt.codigo AS entrega_tipo,
    count(lrd.lote_id) AS total_rollos,
    count(lrd.lote_id) FILTER (WHERE (lrd.flg_tenido = false)) AS rollos_crudos,
    count(lrd.lote_id) FILTER (WHERE (lrd.flg_tenido = true)) AS rollos_tenidos,
    sum(l.cantidad) AS peso_total_kg,
    count(sa.lote_id) AS rollos_en_stock,
    sum(sa.cantidad_disponible) AS peso_en_stock_kg
   FROM (((((doc.entrega gr
     JOIN doc.entrega_tipo grt ON ((grt.id = gr.entrega_tipo_id)))
     JOIN public.tercero t ON ((t.id = gr.tercero_id)))
     JOIN inventario.lote_rollo_detalle lrd ON ((lrd.entrega_id = gr.id)))
     JOIN inventario.lote l ON (((l.id = lrd.lote_id) AND (l.fyh_elm IS NULL))))
     LEFT JOIN inventario.vw_stock_lotes sa ON ((sa.lote_id = l.id)))
  GROUP BY gr.id, gr.serie, gr.correlativo, gr.fecha_emision, gr.tercero_id, t.nombre, grt.codigo;


ALTER VIEW inventario.vw_rollos_por_entrega OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_stock_insumos
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_stock_insumos AS
 SELECT si.item_id,
    i.codigo AS item_codigo,
    i.nombre AS item_nombre,
    sum(si.cantidad_actual) AS cantidad_total,
    un.codigo AS unidad_codigo,
    iid.insumo_tipo_id,
    intp.codigo AS insumo_tipo_codigo,
    intp.nombre AS insumo_tipo_nombre,
    iid.colorante_tipo_id,
    ct.codigo AS colorante_tipo_codigo,
    ct.nombre AS colorante_tipo_nombre,
    iv.precio_promedio,
    (round((sum(si.cantidad_actual) * COALESCE(iv.precio_promedio, (0)::numeric)), 4))::numeric(16,4) AS stock_valorado
   FROM (((((((inventario.item_saldo si
     JOIN public.item i ON ((i.id = si.item_id)))
     JOIN public.item_tipo it ON (((it.id = i.item_tipo_id) AND (it.codigo = 'INSUMO'::text))))
     JOIN public.unidad un ON ((un.id = i.unidad_id)))
     LEFT JOIN public.item_insumo_detalle iid ON ((iid.item_id = si.item_id)))
     LEFT JOIN public.insumo_tipo intp ON ((intp.id = iid.insumo_tipo_id)))
     LEFT JOIN public.colorante_tipo ct ON ((ct.id = iid.colorante_tipo_id)))
     LEFT JOIN inventario.item_valoracion iv ON ((iv.item_id = si.item_id)))
  WHERE (si.cantidad_actual <> (0)::numeric)
  GROUP BY si.item_id, i.codigo, i.nombre, un.codigo, iid.insumo_tipo_id, intp.codigo, intp.nombre, iid.colorante_tipo_id, ct.codigo, ct.nombre, iv.precio_promedio
 HAVING (sum(si.cantidad_actual) <> (0)::numeric);


ALTER VIEW inventario.vw_stock_insumos OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_stock_items
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_stock_items AS
 SELECT vi.item_id,
    vi.item_codigo,
    vi.item_nombre,
    vi.item_tipo_id,
    vi.item_tipo_codigo,
    sum(si.cantidad_actual) AS cantidad_total,
    vi.unidad_id,
    vi.unidad_codigo
   FROM (inventario.item_saldo si
     JOIN public.vw_items vi ON ((vi.item_id = si.item_id)))
  WHERE (si.cantidad_actual <> (0)::numeric)
  GROUP BY vi.item_id, vi.item_codigo, vi.item_nombre, vi.item_tipo_id, vi.item_tipo_codigo, vi.unidad_id, vi.unidad_codigo;


ALTER VIEW inventario.vw_stock_items OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_stock_items_ubicacion
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_stock_items_ubicacion AS
 SELECT vi.item_id,
    vi.item_codigo,
    vi.item_nombre,
    vi.item_tipo_id,
    vi.item_tipo_codigo,
    si.ubicacion_id,
    si.cantidad_actual AS cantidad_total,
    vi.unidad_id,
    vi.unidad_codigo
   FROM (inventario.item_saldo si
     JOIN public.vw_items vi ON ((vi.item_id = si.item_id)))
  WHERE (si.cantidad_actual <> (0)::numeric);


ALTER VIEW inventario.vw_stock_items_ubicacion OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_stock_items_valorado
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_stock_items_valorado AS
 SELECT vi.item_id,
    vi.item_codigo,
    vi.item_nombre,
    vi.item_tipo_id,
    vi.item_tipo_codigo,
    sum(si.cantidad_actual) AS cantidad_total,
    vi.unidad_id,
    vi.unidad_codigo,
    iv.precio_promedio,
    (round((sum(si.cantidad_actual) * COALESCE(iv.precio_promedio, (0)::numeric)), 4))::numeric(16,4) AS stock_valorado
   FROM ((inventario.item_saldo si
     JOIN public.vw_items vi ON ((vi.item_id = si.item_id)))
     LEFT JOIN inventario.item_valoracion iv ON ((iv.item_id = si.item_id)))
  WHERE (si.cantidad_actual <> (0)::numeric)
  GROUP BY vi.item_id, vi.item_codigo, vi.item_nombre, vi.item_tipo_id, vi.item_tipo_codigo, vi.unidad_id, vi.unidad_codigo, iv.precio_promedio, iv.stock_valorado;


ALTER VIEW inventario.vw_stock_items_valorado OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_stock_rollos_crudos
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_stock_rollos_crudos AS
 SELECT sa.item_id,
    i.codigo AS item_codigo,
    i.nombre AS item_nombre,
    u.codigo AS unidad_codigo,
    ird.articulo_id,
    art.nombre AS articulo_nombre,
    art.articulo_tipo_id,
    ird.flg_rib,
    art.fibra,
    l.propietario_id,
    c.nombre AS propietario,
    count(sa.lote_id) AS cantidad_rollos,
    sum(sa.cantidad_disponible) AS cantidad_total
   FROM ((((((((inventario.vw_stock_lotes sa
     JOIN inventario.lote l ON ((l.id = sa.lote_id)))
     JOIN public.item i ON ((i.id = sa.item_id)))
     JOIN public.item_tipo it ON (((it.id = i.item_tipo_id) AND (it.codigo = 'ROLLO'::text))))
     JOIN public.unidad u ON ((u.id = i.unidad_id)))
     JOIN public.item_rollo_detalle ird ON ((ird.item_id = i.id)))
     JOIN public.articulo art ON ((art.id = ird.articulo_id)))
     LEFT JOIN inventario.lote_rollo_detalle lrd ON ((lrd.lote_id = sa.lote_id)))
     LEFT JOIN public.tercero c ON ((c.id = l.propietario_id)))
  WHERE (lrd.flg_tenido IS NOT TRUE)
  GROUP BY sa.item_id, i.codigo, i.nombre, u.codigo, ird.articulo_id, art.nombre, art.articulo_tipo_id, ird.flg_rib, art.fibra, l.propietario_id, c.nombre
  ORDER BY art.nombre, i.nombre;


ALTER VIEW inventario.vw_stock_rollos_crudos OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_stock_rollos_tenidos
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_stock_rollos_tenidos AS
 SELECT sa.item_id,
    i.codigo AS item_codigo,
    i.nombre AS item_nombre,
    u.codigo AS unidad_codigo,
    ird.articulo_id,
    art.nombre AS articulo_nombre,
    art.articulo_tipo_id,
    ird.flg_rib,
    art.fibra,
    lrd.color_x_cliente_id,
    vc.color_id,
    vc.color,
    vc.tono,
    vc.color_hex,
    vc.color_x_cliente_hex,
    vc.tercero_id,
    lrd.tenido_id,
    tn.tenido,
    lrd.flg_antipilling,
    lrd.ancho,
    lrd.malla,
    lrd.rendimiento,
    l.estado_calidad,
    l.propietario_id,
    c.nombre AS propietario,
    count(sa.lote_id) AS cantidad_rollos,
    sum(sa.cantidad_disponible) AS cantidad_total
   FROM ((((((((((inventario.vw_stock_lotes sa
     JOIN inventario.lote l ON ((l.id = sa.lote_id)))
     JOIN public.item i ON ((i.id = sa.item_id)))
     JOIN public.item_tipo it ON (((it.id = i.item_tipo_id) AND (it.codigo = 'ROLLO'::text))))
     JOIN public.unidad u ON ((u.id = i.unidad_id)))
     JOIN public.item_rollo_detalle ird ON ((ird.item_id = i.id)))
     JOIN public.articulo art ON ((art.id = ird.articulo_id)))
     JOIN inventario.lote_rollo_detalle lrd ON (((lrd.lote_id = sa.lote_id) AND (lrd.flg_tenido = true))))
     LEFT JOIN public.vw_colores vc ON ((vc.color_x_cliente_id = lrd.color_x_cliente_id)))
     LEFT JOIN public.tenido tn ON ((tn.id = lrd.tenido_id)))
     LEFT JOIN public.tercero c ON ((c.id = l.propietario_id)))
  GROUP BY sa.item_id, i.codigo, i.nombre, u.codigo, ird.articulo_id, art.nombre, art.articulo_tipo_id, ird.flg_rib, art.fibra, lrd.color_x_cliente_id, vc.color_id, vc.color, vc.tono, vc.color_hex, vc.color_x_cliente_hex, vc.tercero_id, lrd.tenido_id, tn.tenido, lrd.flg_antipilling, lrd.ancho, lrd.malla, lrd.rendimiento, l.estado_calidad, l.propietario_id, c.nombre
  ORDER BY art.nombre, vc.color, i.nombre;


ALTER VIEW inventario.vw_stock_rollos_tenidos OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: inventario.vw_stock_x_proveedor
-- ---------------------------------------------------------------------
CREATE VIEW inventario.vw_stock_x_proveedor AS
 WITH lote_proveedor AS (
         SELECT l_1.id AS lote_id,
            c.tercero_id AS proveedor_id
           FROM (inventario.lote l_1
             JOIN doc.compra c ON ((c.id = l_1.documento_id)))
          WHERE (l_1.documento_tipo = 'compra'::text)
        UNION
         SELECT DISTINCT l_1.id,
            c.tercero_id
           FROM ((inventario.lote l_1
             JOIN doc.compra_entrega ce ON ((ce.entrega_id = l_1.documento_id)))
             JOIN doc.compra c ON ((c.id = ce.compra_id)))
          WHERE (l_1.documento_tipo = 'entrega'::text)
        )
 SELECT vi.item_id,
    vi.item_codigo,
    vi.item_nombre,
    vi.item_tipo_id,
    vi.item_tipo_codigo,
    vi.unidad_id,
    vi.unidad_codigo,
    t.id AS proveedor_id,
    t.nombre AS proveedor_nombre,
    sum(ls.cantidad_actual) AS cantidad_total,
    iv.precio_promedio,
    (round((sum(ls.cantidad_actual) * COALESCE(iv.precio_promedio, (0)::numeric)), 4))::numeric(16,4) AS stock_valorado
   FROM (((((inventario.lote_saldo ls
     JOIN inventario.lote l ON (((l.id = ls.lote_id) AND (l.fyh_elm IS NULL))))
     JOIN public.vw_items vi ON ((vi.item_id = l.item_id)))
     LEFT JOIN lote_proveedor lp ON ((lp.lote_id = l.id)))
     LEFT JOIN public.tercero t ON ((t.id = lp.proveedor_id)))
     LEFT JOIN inventario.item_valoracion iv ON ((iv.item_id = l.item_id)))
  WHERE (ls.cantidad_actual > (0)::numeric)
  GROUP BY vi.item_id, vi.item_codigo, vi.item_nombre, vi.item_tipo_id, vi.item_tipo_codigo, vi.unidad_id, vi.unidad_codigo, t.id, t.nombre, iv.precio_promedio;


ALTER VIEW inventario.vw_stock_x_proveedor OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: mes.vw_cola_estacion
-- ---------------------------------------------------------------------
CREATE VIEW mes.vw_cola_estacion AS
 SELECT pp.id AS paso_id,
    pp.secuencia,
    pp.partida_id,
    pp.operacion_id,
    o.codigo AS operacion_codigo,
    o.nombre AS operacion_nombre,
    o.requiere_receta,
    o.requiere_maquina,
    pp.estado,
    p.estado_produccion AS partida_estado_produccion,
    ((EXTRACT(year FROM p.fyh_cre) || '-'::text) || lpad((p.numero)::text, 4, '0'::text)) AS partida_codigo,
    p.tercero_id,
    c.nombre AS cliente,
    p.color_x_cliente_id,
    vc.color,
    vc.color_hex,
    p.partida_origen_id,
    pe.id AS ejecucion_id,
    pe.fyh_inicio,
    pe.maquina_id,
    (NOT (EXISTS ( SELECT 1
           FROM mes.partida_paso prev
          WHERE ((prev.partida_id = pp.partida_id) AND (prev.secuencia < pp.secuencia) AND (prev.estado <> ALL (ARRAY['COMPLETADO'::public.partida_paso_estado_enum, 'OMITIDO'::public.partida_paso_estado_enum])))))) AS listo,
    ( SELECT max(pe2.fyh_fin) AS max
           FROM (mes.partida_paso prev
             JOIN mes.partida_paso_ejecucion pe2 ON ((pe2.partida_paso_id = prev.id)))
          WHERE ((prev.partida_id = pp.partida_id) AND (prev.secuencia < pp.secuencia) AND (prev.estado = ANY (ARRAY['COMPLETADO'::public.partida_paso_estado_enum, 'OMITIDO'::public.partida_paso_estado_enum])))) AS fyh_listo
   FROM (((((mes.partida p
     JOIN mes.partida_paso pp ON ((pp.partida_id = p.id)))
     JOIN mes.operacion o ON ((o.id = pp.operacion_id)))
     LEFT JOIN public.tercero c ON ((c.id = p.tercero_id)))
     LEFT JOIN public.vw_colores vc ON ((vc.color_x_cliente_id = p.color_x_cliente_id)))
     LEFT JOIN LATERAL ( SELECT partida_paso_ejecucion.id,
            partida_paso_ejecucion.fyh_inicio,
            partida_paso_ejecucion.maquina_id
           FROM mes.partida_paso_ejecucion
          WHERE (partida_paso_ejecucion.partida_paso_id = pp.id)
          ORDER BY partida_paso_ejecucion.fyh_inicio DESC NULLS LAST
         LIMIT 1) pe ON (true))
  WHERE ((p.estado_produccion = ANY (ARRAY['PROGRAMADA'::public.partida_estado_produccion_enum, 'EN_PRODUCCION'::public.partida_estado_produccion_enum])) AND (pp.estado = ANY (ARRAY['PENDIENTE'::public.partida_paso_estado_enum, 'EN_PROCESO'::public.partida_paso_estado_enum])));


ALTER VIEW mes.vw_cola_estacion OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: mes.vw_empleados_activos
-- ---------------------------------------------------------------------
CREATE VIEW mes.vw_empleados_activos AS
 SELECT e.id,
    e.nombre,
    e.apellido,
    ((e.nombre || ' '::text) || e.apellido) AS nombre_completo,
    e.rol_id,
    er.nombre AS rol_nombre,
    e.turno_id
   FROM (mes.empleado e
     JOIN mes.empleado_rol er ON ((er.id = e.rol_id)))
  WHERE (e.activo = true);


ALTER VIEW mes.vw_empleados_activos OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: mes.vw_maquina_cola
-- ---------------------------------------------------------------------
CREATE VIEW mes.vw_maquina_cola AS
 WITH cola AS (
         SELECT prog.maquina_id,
            prog.fecha,
            prog.secuencia AS orden_cola,
            prog.id AS programacion_id,
            prog.nota,
            prog.actividad_tipo,
            prog.actividad_id,
            pp.partida_id,
            (((EXTRACT(year FROM p.fyh_cre))::text || '-'::text) || lpad((p.numero)::text, 4, '0'::text)) AS partida_codigo,
            p.tercero_id,
            c.nombre AS cliente,
            p.color_x_cliente_id,
            vc.color,
            vc.color_hex,
            o.codigo AS operacion_codigo,
            o.nombre AS operacion_nombre,
            pp.secuencia AS paso_secuencia,
            (pp.estado)::text AS estado_actividad,
            (pp.estado = 'EN_PROCESO'::public.partida_paso_estado_enum) AS flg_actual,
                CASE
                    WHEN (pp.estado = 'EN_PROCESO'::public.partida_paso_estado_enum) THEN pe.fyh_inicio
                    ELSE NULL::timestamp with time zone
                END AS desde
           FROM ((((((mes.programacion prog
             JOIN mes.partida_paso pp ON ((pp.id = prog.actividad_id)))
             JOIN mes.partida p ON ((p.id = pp.partida_id)))
             JOIN mes.operacion o ON ((o.id = pp.operacion_id)))
             LEFT JOIN public.tercero c ON ((c.id = p.tercero_id)))
             LEFT JOIN public.vw_colores vc ON ((vc.color_x_cliente_id = p.color_x_cliente_id)))
             LEFT JOIN LATERAL ( SELECT partida_paso_ejecucion.fyh_inicio
                   FROM mes.partida_paso_ejecucion
                  WHERE (partida_paso_ejecucion.partida_paso_id = pp.id)
                  ORDER BY partida_paso_ejecucion.fyh_inicio DESC NULLS LAST
                 LIMIT 1) pe ON (true))
          WHERE ((prog.actividad_tipo = 'partida_paso'::text) AND ((prog.fecha >= CURRENT_DATE) OR (pp.estado = ANY (ARRAY['PENDIENTE'::public.partida_paso_estado_enum, 'EN_PROCESO'::public.partida_paso_estado_enum]))))
        UNION ALL
         SELECT prog.maquina_id,
            prog.fecha,
            prog.secuencia,
            prog.id,
            prog.nota,
            prog.actividad_tipo,
            prog.actividad_id,
            NULL::bigint AS int8,
            NULL::text AS text,
            NULL::integer AS int4,
            NULL::text AS text,
            NULL::integer AS int4,
            NULL::text AS text,
            NULL::text AS text,
            'LAVADO_MAQUINA'::text,
            'Lavado de máquina'::text,
            NULL::smallint AS int2,
            (lm.estado)::text AS estado,
            (lm.estado = 'EN_PROCESO'::public.partida_paso_estado_enum),
                CASE
                    WHEN (lm.estado = 'EN_PROCESO'::public.partida_paso_estado_enum) THEN lm.fyh_inicio
                    ELSE NULL::timestamp with time zone
                END AS "case"
           FROM (mes.programacion prog
             JOIN mes.lavado_maquina lm ON ((lm.id = prog.actividad_id)))
          WHERE ((prog.actividad_tipo = 'LAVADO_MAQUINA'::text) AND ((prog.fecha >= CURRENT_DATE) OR (lm.estado = ANY (ARRAY['PENDIENTE'::public.partida_paso_estado_enum, 'EN_PROCESO'::public.partida_paso_estado_enum]))))
        )
 SELECT m.id AS maquina_id,
    m.codigo AS maquina_codigo,
    m.nombre AS maquina_nombre,
    m.estado_actual AS maquina_estado,
    mt.operacion_id AS maquina_operacion_id,
    cola.fecha,
    cola.orden_cola,
    cola.programacion_id,
    cola.nota,
    cola.actividad_tipo,
    cola.actividad_id,
    cola.partida_id,
    cola.partida_codigo,
    cola.tercero_id,
    cola.cliente,
    cola.color_x_cliente_id,
    cola.color,
    cola.color_hex,
    cola.operacion_codigo,
    cola.operacion_nombre,
    cola.paso_secuencia,
    cola.estado_actividad,
    cola.flg_actual,
    cola.desde,
    round((EXTRACT(epoch FROM (now() - cola.desde)) / (3600)::numeric), 1) AS horas_en_estado
   FROM ((cola
     JOIN mes.maquina m ON ((m.id = cola.maquina_id)))
     LEFT JOIN mes.maquina_tipo mt ON ((mt.id = m.maquina_tipo_id)));


ALTER VIEW mes.vw_maquina_cola OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: mes.vw_maquinas
-- ---------------------------------------------------------------------
CREATE VIEW mes.vw_maquinas AS
 SELECT m.id,
    m.codigo,
    m.nombre,
    m.maquina_tipo_id,
    mt.codigo AS maquina_tipo_codigo,
    mt.nombre AS maquina_tipo_nombre,
    mt.operacion_id,
    m.capacidad_min_kg,
    o.codigo AS operacion_codigo,
    m.relacion_bano
   FROM ((mes.maquina m
     LEFT JOIN mes.maquina_tipo mt ON ((mt.id = m.maquina_tipo_id)))
     LEFT JOIN mes.operacion o ON ((o.id = mt.operacion_id)));


ALTER VIEW mes.vw_maquinas OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: mes.vw_partida_familia_output
-- ---------------------------------------------------------------------
CREATE VIEW mes.vw_partida_familia_output AS
 SELECT COALESCE(p.partida_origen_id, p.id) AS root_id,
    p.id AS partida_id,
    (p.partida_origen_id IS NOT NULL) AS es_reproceso,
    l.id AS lote_id,
    l.item_id,
    l.estado_calidad,
    l.cantidad
   FROM (((inventario.lote l
     JOIN mes.partida_paso_ejecucion pe ON (((pe.id = l.documento_id) AND (l.documento_tipo = 'partida_paso_ejecucion'::text))))
     JOIN mes.partida_paso pp ON ((pp.id = pe.partida_paso_id)))
     JOIN mes.partida p ON ((p.id = pp.partida_id)))
  WHERE ((l.fyh_elm IS NULL) AND (( SELECT COALESCE(sum(
                CASE
                    WHEN (imt.codigo = 'PROD_CONSUMO'::text) THEN 1
                    WHEN (imt.codigo = 'PROD_CONSUMO_REV'::text) THEN '-1'::integer
                    ELSE 0
                END), (0)::bigint) AS "coalesce"
           FROM (inventario.item_movimientos im
             JOIN inventario.item_movimiento_tipo imt ON ((imt.id = im.item_movimiento_tipo_id)))
          WHERE (im.lote_id = l.id)) <= 0));


ALTER VIEW mes.vw_partida_familia_output OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: mes.vw_partida_comercial
-- ---------------------------------------------------------------------
CREATE VIEW mes.vw_partida_comercial AS
 WITH terminal AS (
         SELECT vw_partida_familia_output.root_id,
            vw_partida_familia_output.lote_id
           FROM mes.vw_partida_familia_output
          WHERE (vw_partida_familia_output.estado_calidad = 'APROBADO'::public.calidad_estado_enum)
        ), fulfillment AS (
         SELECT t.root_id,
            count(*) AS total_terminal,
            count(*) FILTER (WHERE ((EXISTS ( SELECT 1
                   FROM (inventario.item_movimientos im
                     JOIN inventario.item_movimiento_tipo imt ON ((imt.id = im.item_movimiento_tipo_id)))
                  WHERE ((im.lote_id = t.lote_id) AND (imt.codigo = ANY (ARRAY['SERV_EGR'::text, 'VENTA_EGR'::text]))))) AND (NOT (EXISTS ( SELECT 1
                   FROM (inventario.item_movimientos im2
                     JOIN inventario.item_movimiento_tipo imt2 ON ((imt2.id = im2.item_movimiento_tipo_id)))
                  WHERE ((im2.lote_id = t.lote_id) AND (imt2.codigo = ANY (ARRAY['SERV_DEV_ING'::text, 'DEV_CLI_ING'::text])))))))) AS dispatched_ahora
           FROM terminal t
          GROUP BY t.root_id
        )
 SELECT p.id AS partida_id,
    (((EXTRACT(year FROM p.fyh_cre))::text || '-'::text) || lpad((p.numero)::text, 4, '0'::text)) AS codigo,
    p.tercero_id,
    c.nombre AS cliente,
    p.estado_comercial AS estado_comercial_cache,
    COALESCE(f.total_terminal, (0)::bigint) AS total_terminal,
    COALESCE(f.dispatched_ahora, (0)::bigint) AS dispatched_ahora,
    GREATEST((0)::bigint, (COALESCE(f.total_terminal, (0)::bigint) - COALESCE(f.dispatched_ahora, (0)::bigint))) AS pendiente,
    v.venta_ids,
    v.factura_refs,
    v.total_kg_facturado,
    v.total_importe
   FROM (((mes.partida p
     JOIN public.tercero c ON ((c.id = p.tercero_id)))
     LEFT JOIN fulfillment f ON ((f.root_id = p.id)))
     LEFT JOIN LATERAL ( SELECT jsonb_agg(DISTINCT vd.venta_id) AS venta_ids,
            jsonb_agg(DISTINCT ((ve.factura_serie || '-'::text) || (ve.factura_numero)::text)) FILTER (WHERE (ve.factura_serie IS NOT NULL)) AS factura_refs,
            sum(vd.cantidad_kg) AS total_kg_facturado,
            sum(vd.importe) AS total_importe
           FROM (doc.venta_detalle vd
             JOIN doc.venta ve ON (((ve.id = vd.venta_id) AND (ve.estado <> 'ANULADA'::public.venta_estado_enum))))
          WHERE (vd.partida_id = p.id)) v ON (true))
  WHERE ((p.partida_origen_id IS NULL) AND (p.fyh_elm IS NULL));


ALTER VIEW mes.vw_partida_comercial OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: mes.vw_partida_familia
-- ---------------------------------------------------------------------
CREATE VIEW mes.vw_partida_familia AS
 WITH demanda AS (
         SELECT pd.partida_id AS root_id,
            sum(pd.cantidad) AS demanda_rollos
           FROM mes.partida_detalle pd
          GROUP BY pd.partida_id
        ), salida AS (
         SELECT vw_partida_familia_output.root_id,
            count(*) FILTER (WHERE (vw_partida_familia_output.estado_calidad = 'APROBADO'::public.calidad_estado_enum)) AS producido_bueno,
            count(*) FILTER (WHERE (vw_partida_familia_output.estado_calidad = 'PENDIENTE'::public.calidad_estado_enum)) AS producido_pendiente,
            count(*) FILTER (WHERE (vw_partida_familia_output.estado_calidad = 'REPROCESO'::public.calidad_estado_enum)) AS producido_reproceso,
            count(*) AS producido_terminal
           FROM mes.vw_partida_familia_output
          GROUP BY vw_partida_familia_output.root_id
        )
 SELECT r.id AS partida_id,
    (((EXTRACT(year FROM r.fyh_cre))::text || '-'::text) || lpad((r.numero)::text, 4, '0'::text)) AS codigo,
    r.tercero_id,
    c.nombre AS cliente,
    r.grupo_articulo_id,
    ga.nombre AS grupo_articulo,
    r.color_x_cliente_id,
    vc.color,
    vc.color_hex,
    r.estado_produccion,
    r.estado_comercial,
    r.estado_facturacion,
    r.prioridad_id,
    pr.prioridad,
    r.fecha_acordada,
    r.fyh_cre,
    COALESCE(d.demanda_rollos, (0)::numeric) AS demanda_rollos,
    COALESCE(s.producido_bueno, (0)::bigint) AS producido_bueno,
    COALESCE(s.producido_pendiente, (0)::bigint) AS producido_pendiente,
    COALESCE(s.producido_reproceso, (0)::bigint) AS producido_reproceso,
    COALESCE(s.producido_terminal, (0)::bigint) AS producido_terminal,
    GREATEST((0)::numeric, (COALESCE(d.demanda_rollos, (0)::numeric) - (COALESCE(s.producido_bueno, (0)::bigint))::numeric)) AS faltante,
    round((((COALESCE(s.producido_bueno, (0)::bigint))::numeric / NULLIF(COALESCE(d.demanda_rollos, (0)::numeric), (0)::numeric)) * (100)::numeric), 0) AS porcentaje_cumplimiento,
    (((COALESCE(s.producido_bueno, (0)::bigint))::numeric >= COALESCE(d.demanda_rollos, (0)::numeric)) AND (COALESCE(d.demanda_rollos, (0)::numeric) > (0)::numeric)) AS flg_cumplida,
    ( SELECT count(*) AS count
           FROM mes.partida rw
          WHERE (rw.partida_origen_id = r.id)) AS num_reprocesos,
    (EXISTS ( SELECT 1
           FROM mes.partida rw
          WHERE ((rw.partida_origen_id = r.id) AND (rw.estado_produccion <> ALL (ARRAY['TECO'::public.partida_estado_produccion_enum, 'CERRADA'::public.partida_estado_produccion_enum, 'CANCELADA'::public.partida_estado_produccion_enum]))))) AS tiene_rework_activo
   FROM ((((((mes.partida r
     LEFT JOIN demanda d ON ((d.root_id = r.id)))
     LEFT JOIN salida s ON ((s.root_id = r.id)))
     LEFT JOIN public.tercero c ON ((c.id = r.tercero_id)))
     LEFT JOIN public.grupo_articulo ga ON ((ga.id = r.grupo_articulo_id)))
     LEFT JOIN public.vw_colores vc ON ((vc.color_x_cliente_id = r.color_x_cliente_id)))
     LEFT JOIN public.prioridad pr ON ((pr.id = r.prioridad_id)))
  WHERE ((r.partida_origen_id IS NULL) AND (r.fyh_elm IS NULL));


ALTER VIEW mes.vw_partida_familia OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: mes.vw_partida_produccion_rollos
-- ---------------------------------------------------------------------
CREATE VIEW mes.vw_partida_produccion_rollos AS
 SELECT p.id AS partida_id,
    l.item_id,
    vi.item_codigo,
    vi.item_nombre,
    count(*) AS cantidad_rollos
   FROM ((((inventario.lote l
     JOIN public.vw_items vi ON (((vi.item_id = l.item_id) AND (vi.item_tipo_codigo = 'ROLLO'::text))))
     JOIN mes.partida_paso_ejecucion pe ON ((pe.id = l.documento_id)))
     JOIN mes.partida_paso pp ON ((pp.id = pe.partida_paso_id)))
     JOIN mes.partida p ON ((p.id = pp.partida_id)))
  WHERE (l.documento_tipo = 'partida_paso_ejecucion'::text)
  GROUP BY p.id, l.item_id, vi.item_codigo, vi.item_nombre;


ALTER VIEW mes.vw_partida_produccion_rollos OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: mes.vw_partida_resumen_tenido
-- ---------------------------------------------------------------------
CREATE VIEW mes.vw_partida_resumen_tenido AS
 SELECT pd.partida_id,
    a.id AS articulo_id,
    a.nombre AS articulo_nombre,
    a.articulo_tipo_id,
    at.nombre AS articulo_tipo_nombre,
    a.fibra,
    sum(pd.cantidad) AS total_rollos,
    sum(pd.cantidad) AS cantidad_total,
    sum(
        CASE
            WHEN (ird.flg_rib = false) THEN pd.cantidad
            ELSE (0)::numeric
        END) AS cantidad_regular,
    sum(
        CASE
            WHEN (ird.flg_rib = true) THEN pd.cantidad
            ELSE (0)::numeric
        END) AS cantidad_rib
   FROM (((mes.partida_detalle pd
     JOIN public.item_rollo_detalle ird ON ((ird.item_id = pd.item_id)))
     JOIN public.articulo a ON ((a.id = ird.articulo_id)))
     JOIN public.articulo_tipo at ON ((at.id = a.articulo_tipo_id)))
  GROUP BY pd.partida_id, a.id, a.nombre, a.articulo_tipo_id, at.nombre, a.fibra
  ORDER BY pd.partida_id, a.id;


ALTER VIEW mes.vw_partida_resumen_tenido OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: mes.vw_partidas
-- ---------------------------------------------------------------------
CREATE VIEW mes.vw_partidas AS
 SELECT p.id,
    p.numero,
    (((EXTRACT(year FROM p.fyh_cre))::text || '-'::text) || lpad((p.numero)::text, 4, '0'::text)) AS codigo,
    p.estado_produccion AS estado,
    p.estado_comercial,
    p.estado_facturacion,
    p.partida_origen_id,
    p.fyh_cre,
    p.fyh_programacion,
    p.fyh_inicio,
    p.fyh_fin,
    p.fecha_acordada,
    p.tercero_id,
    c.nombre AS cliente,
    p.color_x_cliente_id,
    vc.color_id,
    vc.color,
    vc.tono,
    vc.color_hex,
    p.tenido_id,
    t.tenido,
    p.grupo_articulo_id,
    ga.nombre AS grupo_articulo,
    p.fibra,
    p.flg_antipilling,
    p.flg_doble_bolsa,
    p.malla,
    p.rendimiento,
    p.ancho,
    p.prioridad_id,
    pr.prioridad,
    COALESCE(pasos_stats.total_pasos, (0)::bigint) AS total_pasos,
    COALESCE(pasos_stats.pasos_completados, (0)::bigint) AS pasos_completados,
    COALESCE(pasos_stats.pasos_en_proceso, (0)::bigint) AS pasos_en_proceso,
    COALESCE(pasos_stats.pasos_pendientes, (0)::bigint) AS pasos_pendientes,
        CASE
            WHEN (COALESCE(pasos_stats.total_pasos, (0)::bigint) > 0) THEN round((((COALESCE(pasos_stats.pasos_completados, (0)::bigint))::numeric / (pasos_stats.total_pasos)::numeric) * (100)::numeric), 0)
            ELSE (0)::numeric
        END AS progreso_porcentaje,
    COALESCE(materiales_stats.total_materiales, (0)::bigint) AS total_materiales,
    COALESCE(materiales_stats.cantidad_total_kg, (0)::numeric) AS cantidad_total_kg,
    COALESCE(produccion_stats.rollos_producidos, (0)::bigint) AS rollos_producidos,
    COALESCE(produccion_stats.kg_producidos, (0)::numeric) AS kg_producidos,
        CASE
            WHEN ((p.fyh_inicio IS NOT NULL) AND (p.fyh_fin IS NOT NULL)) THEN (EXTRACT(epoch FROM (p.fyh_fin - p.fyh_inicio)) / (3600)::numeric)
            WHEN (p.fyh_inicio IS NOT NULL) THEN (EXTRACT(epoch FROM (now() - p.fyh_inicio)) / (3600)::numeric)
            ELSE NULL::numeric
        END AS duracion_horas,
    p.usr_cre,
    ((prof.nombre || ' '::text) || prof.apellido) AS creado_por,
    p.usr_mod,
    p.fyh_mod,
    p.fyh_elm,
    p.observacion
   FROM (((((((((mes.partida p
     LEFT JOIN public.tercero c ON ((c.id = p.tercero_id)))
     LEFT JOIN public.vw_colores vc ON ((vc.color_x_cliente_id = p.color_x_cliente_id)))
     LEFT JOIN public.tenido t ON ((t.id = p.tenido_id)))
     LEFT JOIN public.grupo_articulo ga ON ((ga.id = p.grupo_articulo_id)))
     LEFT JOIN public.prioridad pr ON ((pr.id = p.prioridad_id)))
     LEFT JOIN public.usuario prof ON ((prof.id = p.usr_cre)))
     LEFT JOIN LATERAL ( SELECT count(*) AS total_pasos,
            count(*) FILTER (WHERE (EXISTS ( SELECT 1
                   FROM mes.partida_paso_ejecucion pe
                  WHERE ((pe.partida_paso_id = pp.id) AND (pe.estado = 'COMPLETADO'::public.paso_ejecucion_estado_enum))))) AS pasos_completados,
            count(*) FILTER (WHERE (EXISTS ( SELECT 1
                   FROM mes.partida_paso_ejecucion pe
                  WHERE ((pe.partida_paso_id = pp.id) AND (pe.estado = 'EN_PROCESO'::public.paso_ejecucion_estado_enum))))) AS pasos_en_proceso,
            count(*) FILTER (WHERE (NOT (EXISTS ( SELECT 1
                   FROM mes.partida_paso_ejecucion pe
                  WHERE (pe.partida_paso_id = pp.id))))) AS pasos_pendientes
           FROM mes.partida_paso pp
          WHERE (pp.partida_id = p.id)) pasos_stats ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS total_materiales,
            sum(l.cantidad) AS cantidad_total_kg
           FROM (mes.partida_componente opi
             LEFT JOIN inventario.lote l ON ((l.id = opi.lote_id)))
          WHERE (opi.partida_id = p.id)) materiales_stats ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS rollos_producidos,
            sum(l.cantidad) AS kg_producidos
           FROM ((inventario.lote l
             JOIN mes.partida_paso_ejecucion pe ON ((pe.id = l.documento_id)))
             JOIN mes.partida_paso pp ON ((pp.id = pe.partida_paso_id)))
          WHERE ((l.documento_tipo = 'partida_paso_ejecucion'::text) AND (pp.partida_id = p.id) AND (l.fyh_elm IS NULL))) produccion_stats ON (true));


ALTER VIEW mes.vw_partidas OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: mes.vw_pasos
-- ---------------------------------------------------------------------
CREATE VIEW mes.vw_pasos AS
 SELECT pp.id AS paso_id,
    pp.secuencia,
    pp.partida_id,
    p.numero AS partida_numero,
    ((EXTRACT(year FROM p.fyh_cre) || '-'::text) || lpad((p.numero)::text, 4, '0'::text)) AS partida_codigo,
    p.tercero_id,
    c.nombre AS cliente,
    p.color_x_cliente_id,
    vc.color,
    vc.color_hex,
    pp.operacion_id,
    o.codigo AS operacion_codigo,
    o.nombre AS operacion_nombre,
    o.requiere_receta,
    o.requiere_maquina,
    pp.receta_id,
    pp.ph_objetivo,
    pp.temperatura_objetivo,
    prog.relacion_bano AS relacion_bano_objetivo,
    pp.tiempo_estandar,
    m.id AS maquina_id,
    m.codigo AS maquina_codigo,
    m.nombre AS maquina_nombre,
    pe.id AS ejecucion_id,
    pe.empleado_id,
    pe.fyh_inicio,
    pe.fyh_fin,
    pe.ph_real,
    pe.temperatura_real,
    pe.relacion_bano_real,
    pe.cantidad_rollos,
    pe.peso_kg,
    pe.notas,
    pe.ancho_entrada,
    pe.ancho_salida,
    pe.velocidad,
    pe.entrada,
    pe.salida,
    pe.rendimiento,
    pe.pases,
    pe.malla_alimentacion,
    pt.ancho_marco,
    pt.vel_maquina,
    pt.vel_alimentacion,
    pt.densidad_entrada,
    pt.densidad_salida,
    pt.lm,
    pt.galga,
    prog.id AS programacion_id,
    prog.maquina_id AS maquina_programada_id,
    prog.fecha AS fecha_programada,
    prog.secuencia AS secuencia_programada,
        CASE
            WHEN ((pe.id IS NOT NULL) AND (pe.estado = 'COMPLETADO'::public.paso_ejecucion_estado_enum)) THEN 'COMPLETADO'::text
            WHEN ((pe.id IS NOT NULL) AND (pe.estado = 'EN_PROCESO'::public.paso_ejecucion_estado_enum)) THEN 'EN_PROCESO'::text
            WHEN ((pe.id IS NOT NULL) AND (pe.estado = 'OMITIDO'::public.paso_ejecucion_estado_enum)) THEN 'OMITIDO'::text
            ELSE 'PENDIENTE'::text
        END AS estado,
    p.estado_produccion AS partida_estado_produccion
   FROM ((((((((mes.partida_paso pp
     JOIN mes.partida p ON ((p.id = pp.partida_id)))
     JOIN mes.operacion o ON ((o.id = pp.operacion_id)))
     LEFT JOIN public.tercero c ON ((c.id = p.tercero_id)))
     LEFT JOIN public.vw_colores vc ON ((vc.color_x_cliente_id = p.color_x_cliente_id)))
     LEFT JOIN LATERAL ( SELECT partida_paso_ejecucion.id,
            partida_paso_ejecucion.estado,
            partida_paso_ejecucion.maquina_id,
            partida_paso_ejecucion.empleado_id,
            partida_paso_ejecucion.fyh_inicio,
            partida_paso_ejecucion.fyh_fin,
            partida_paso_ejecucion.ph_real,
            partida_paso_ejecucion.temperatura_real,
            partida_paso_ejecucion.relacion_bano_real,
            partida_paso_ejecucion.cantidad_rollos,
            partida_paso_ejecucion.peso_kg,
            partida_paso_ejecucion.notas,
            partida_paso_ejecucion.ancho_entrada,
            partida_paso_ejecucion.ancho_salida,
            partida_paso_ejecucion.velocidad,
            partida_paso_ejecucion.entrada,
            partida_paso_ejecucion.salida,
            partida_paso_ejecucion.rendimiento,
            partida_paso_ejecucion.pases,
            partida_paso_ejecucion.malla_alimentacion
           FROM mes.partida_paso_ejecucion
          WHERE (partida_paso_ejecucion.partida_paso_id = pp.id)
          ORDER BY partida_paso_ejecucion.fyh_inicio DESC NULLS LAST
         LIMIT 1) pe ON (true))
     LEFT JOIN LATERAL ( SELECT programacion.id,
            programacion.maquina_id,
            programacion.fecha,
            programacion.secuencia,
            programacion.relacion_bano
           FROM mes.programacion
          WHERE ((programacion.actividad_tipo = 'partida_paso'::text) AND (programacion.actividad_id = pp.id))
          ORDER BY programacion.fyh_cre DESC
         LIMIT 1) prog ON (true))
     LEFT JOIN mes.maquina m ON ((m.id = COALESCE(pe.maquina_id, prog.maquina_id))))
     LEFT JOIN mes.partida_paso_ejecucion_termofijado pt ON ((pt.ejecucion_id = pe.id)));


ALTER VIEW mes.vw_pasos OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: mes.vw_pesaje_pendiente
-- ---------------------------------------------------------------------
CREATE VIEW mes.vw_pesaje_pendiente AS
SELECT
    NULL::bigint AS partida_id,
    NULL::text AS partida_codigo,
    NULL::bigint AS partida_origen_id,
    NULL::integer AS tercero_id,
    NULL::text AS cliente,
    NULL::integer AS color_x_cliente_id,
    NULL::character varying(25) AS color,
    NULL::text AS color_hex,
    NULL::integer AS tenido_id,
    NULL::text AS tenido,
    NULL::integer AS grupo_articulo_id,
    NULL::text AS grupo_articulo,
    NULL::smallint AS fibra,
    NULL::text AS malla,
    NULL::text AS rendimiento,
    NULL::text AS ancho,
    NULL::date AS fecha_acordada,
    NULL::date AS fecha_programada,
    NULL::bigint AS entrega_id,
    NULL::text AS entrega_numero,
    NULL::integer AS item_id,
    NULL::text AS item_codigo,
    NULL::text AS item_nombre,
    NULL::boolean AS flg_rib,
    NULL::integer AS rollos;


ALTER VIEW mes.vw_pesaje_pendiente OWNER TO postgres;

-- ---------------------------------------------------------------------
-- VIEW: mes.vw_proyeccion_tenido
-- ---------------------------------------------------------------------
CREATE VIEW mes.vw_proyeccion_tenido AS
 WITH pasos AS (
         SELECT p.fecha,
            p.maquina_id,
            p.secuencia,
            'TENIDO'::text AS tipo_registro,
            p.actividad_id,
            co.color,
            te.tenido,
            val.valor,
            rt.flg_antipilling,
            w.kilos_raw,
                CASE
                    WHEN (w.kilos_raw < (5)::numeric) THEN (20)::numeric
                    ELSE w.kilos_raw
                END AS kilos,
                CASE
                    WHEN (pe.estado = 'EN_PROCESO'::public.paso_ejecucion_estado_enum) THEN GREATEST('00:00:00'::interval, (te_std.duracion - (now() - pe.fyh_inicio)))
                    ELSE te_std.duracion
                END AS duracion,
            pe.fyh_inicio
           FROM (((((((((((mes.programacion p
             JOIN mes.partida_paso pp ON ((pp.id = p.actividad_id)))
             JOIN mes.partida ptd ON ((ptd.id = pp.partida_id)))
             JOIN mes.operacion op ON ((op.id = pp.operacion_id)))
             CROSS JOIN LATERAL ( SELECT COALESCE(sum(l.cantidad), (0)::numeric) AS kilos_raw
                   FROM (mes.partida_componente opi
                     JOIN inventario.lote l ON ((l.id = opi.lote_id)))
                  WHERE (opi.partida_id = pp.partida_id)) w)
             LEFT JOIN mes.partida_paso_ejecucion pe ON (((pe.partida_paso_id = pp.id) AND (pe.estado = 'EN_PROCESO'::public.paso_ejecucion_estado_enum))))
             LEFT JOIN receta.tenido rt ON ((rt.id = pp.receta_id)))
             LEFT JOIN public.color_x_cliente cxc ON ((cxc.id = rt.color_x_cliente_id)))
             LEFT JOIN public.color co ON ((co.id = cxc.color_id)))
             LEFT JOIN public.tenido te ON ((te.id = rt.tenido_id)))
             LEFT JOIN public.valor val ON ((val.id = cxc.valor_id)))
             LEFT JOIN mes.tiempos_estandar_tenido te_std ON (((te_std.valor_id = cxc.valor_id) AND (te_std.tenido_id = rt.tenido_id) AND (te_std.flg_antipilling = rt.flg_antipilling) AND (te_std.flg_activo = true))))
          WHERE ((p.actividad_tipo = 'partida_paso'::text) AND (ptd.partida_origen_id IS NULL) AND (op.codigo <> 'TERMOFIJADO'::text) AND (NOT (EXISTS ( SELECT 1
                   FROM mes.partida_paso_ejecucion pe2
                  WHERE ((pe2.partida_paso_id = pp.id) AND (pe2.estado = 'COMPLETADO'::public.paso_ejecucion_estado_enum))))))
        ), lavados AS (
         SELECT p.fecha,
            p.maquina_id,
            p.secuencia,
            'LAVADO'::text AS tipo_registro,
            p.actividad_id,
            NULL::text AS color,
            NULL::text AS tenido,
            NULL::text AS valor,
            NULL::boolean AS flg_antipilling,
            NULL::numeric AS kilos_raw,
            NULL::numeric AS kilos,
                CASE
                    WHEN (lm.estado = 'EN_PROCESO'::public.partida_paso_estado_enum) THEN GREATEST('00:00:00'::interval, (tel.duracion - (now() - lm.fyh_inicio)))
                    ELSE tel.duracion
                END AS duracion,
            lm.fyh_inicio
           FROM (((mes.programacion p
             JOIN mes.lavado_maquina lm ON ((lm.id = p.actividad_id)))
             JOIN receta.lavado_maquina rlm ON ((rlm.id = lm.receta_id)))
             LEFT JOIN mes.tiempos_estandar_lavado tel ON (((tel.tipo_lavado_mq_id = rlm.tipo_lavado_mq_id) AND (tel.flg_activo = true))))
          WHERE ((p.actividad_tipo = 'LAVADO_MAQUINA'::text) AND (lm.estado = ANY (ARRAY['PENDIENTE'::public.partida_paso_estado_enum, 'EN_PROCESO'::public.partida_paso_estado_enum])))
        ), union_total AS (
         SELECT pasos.fecha,
            pasos.maquina_id,
            pasos.secuencia,
            pasos.tipo_registro,
            pasos.actividad_id,
            pasos.color,
            pasos.tenido,
            pasos.valor,
            pasos.flg_antipilling,
            pasos.kilos_raw,
            pasos.kilos,
            pasos.duracion,
            pasos.fyh_inicio
           FROM pasos
        UNION ALL
         SELECT lavados.fecha,
            lavados.maquina_id,
            lavados.secuencia,
            lavados.tipo_registro,
            lavados.actividad_id,
            lavados.color,
            lavados.tenido,
            lavados.valor,
            lavados.flg_antipilling,
            lavados.kilos_raw,
            lavados.kilos,
            lavados.duracion,
            lavados.fyh_inicio
           FROM lavados
        ), con_offsets AS (
         SELECT s.fecha,
            s.maquina_id,
            s.secuencia,
            s.tipo_registro,
            s.actividad_id,
            s.color,
            s.tenido,
            s.valor,
            s.flg_antipilling,
            s.kilos_raw,
            s.kilos,
            s.duracion,
            s.fyh_inicio,
            s.cumsum,
            s.break,
            ((s.cumsum - COALESCE(s.duracion, '00:00:00'::interval)) + s.break) AS offset_inicio,
            (s.cumsum + s.break) AS offset_fin
           FROM ( SELECT union_total.fecha,
                    union_total.maquina_id,
                    union_total.secuencia,
                    union_total.tipo_registro,
                    union_total.actividad_id,
                    union_total.color,
                    union_total.tenido,
                    union_total.valor,
                    union_total.flg_antipilling,
                    union_total.kilos_raw,
                    union_total.kilos,
                    union_total.duracion,
                    union_total.fyh_inicio,
                    sum(COALESCE(union_total.duracion, '00:00:00'::interval)) OVER (PARTITION BY union_total.maquina_id, union_total.fecha ORDER BY union_total.secuencia) AS cumsum,
                    (((row_number() OVER (PARTITION BY union_total.maquina_id, union_total.fecha ORDER BY union_total.secuencia) - 1))::double precision * '00:20:00'::interval) AS break
                   FROM union_total) s
        )
 SELECT con_offsets.fecha,
    con_offsets.maquina_id,
    con_offsets.secuencia,
    con_offsets.tipo_registro,
    con_offsets.actividad_id,
    con_offsets.color,
    con_offsets.tenido,
    con_offsets.valor,
    con_offsets.flg_antipilling,
    con_offsets.kilos_raw,
    con_offsets.kilos,
    con_offsets.duracion,
    con_offsets.fyh_inicio,
    con_offsets.cumsum,
    con_offsets.break,
    con_offsets.offset_inicio,
    con_offsets.offset_fin,
        CASE
            WHEN (con_offsets.tipo_registro = 'LAVADO'::text) THEN NULL::numeric
            WHEN (con_offsets.offset_inicio >= '12:00:00'::interval) THEN (0)::numeric
            WHEN (con_offsets.offset_fin <= '12:00:00'::interval) THEN con_offsets.kilos
            ELSE round(((EXTRACT(epoch FROM ('12:00:00'::interval - con_offsets.offset_inicio)) / NULLIF(EXTRACT(epoch FROM con_offsets.duracion), (0)::numeric)) * con_offsets.kilos), 2)
        END AS produccion_dia,
        CASE
            WHEN (con_offsets.tipo_registro = 'LAVADO'::text) THEN NULL::numeric
            WHEN (con_offsets.offset_inicio >= '24:00:00'::interval) THEN (0)::numeric
            WHEN (con_offsets.offset_fin <= '24:00:00'::interval) THEN con_offsets.kilos
            ELSE round(((EXTRACT(epoch FROM ('24:00:00'::interval - con_offsets.offset_inicio)) / NULLIF(EXTRACT(epoch FROM con_offsets.duracion), (0)::numeric)) * con_offsets.kilos), 2)
        END AS produccion_total
   FROM con_offsets
  ORDER BY con_offsets.fecha, con_offsets.maquina_id, con_offsets.secuencia;


ALTER VIEW mes.vw_proyeccion_tenido OWNER TO postgres;

