-- ---------------------------------------------------------------------
-- VIEW: mes.vw_wip
-- ---------------------------------------------------------------------
CREATE VIEW mes.vw_wip AS
 SELECT p.id AS partida_id,
    (((EXTRACT(year FROM p.fyh_cre))::text || '-'::text) || lpad((p.numero)::text, 4, '0'::text)) AS partida_codigo,
    p.estado_produccion,
    p.prioridad_id,
    pr.prioridad,
    p.tercero_id,
    c.nombre AS cliente,
    p.color_x_cliente_id,
    vc.color,
    vc.color_hex,
    p.fecha_acordada,
    ((p.fecha_acordada IS NOT NULL) AND (p.fecha_acordada < CURRENT_DATE)) AS flg_atraso,
    tot.total_pasos,
    tot.pasos_hechos,
        CASE
            WHEN (tot.total_pasos > 0) THEN round((((tot.pasos_hechos)::numeric / (tot.total_pasos)::numeric) * (100)::numeric), 0)
            ELSE (0)::numeric
        END AS progreso_porcentaje,
    cur.paso_id AS paso_actual_id,
    cur.secuencia AS secuencia_actual,
    cur.operacion_id,
    o.codigo AS operacion_codigo,
    o.nombre AS operacion_nombre,
    cur.ejecucion_id,
    cur.maquina_id,
    m.codigo AS maquina_codigo,
    m.nombre AS maquina_nombre,
        CASE
            WHEN (cur.paso_id IS NULL) THEN 'SIN_PASO'::text
            WHEN (cur.estado_paso = 'EN_PROCESO'::public.partida_paso_estado_enum) THEN 'EN_PROCESO'::text
            WHEN cur.listo THEN 'EN_COLA'::text
            ELSE 'BLOQUEADA'::text
        END AS situacion,
    cur.desde,
    round((EXTRACT(epoch FROM (now() - cur.desde)) / (3600)::numeric), 1) AS horas_en_estado,
    cur.tiempo_estandar
   FROM (((((((mes.partida p
     LEFT JOIN public.tercero c ON ((c.id = p.tercero_id)))
     LEFT JOIN public.vw_colores vc ON ((vc.color_x_cliente_id = p.color_x_cliente_id)))
     LEFT JOIN public.prioridad pr ON ((pr.id = p.prioridad_id)))
     LEFT JOIN LATERAL ( SELECT count(*) AS total_pasos,
            count(*) FILTER (WHERE (pp.estado = ANY (ARRAY['COMPLETADO'::public.partida_paso_estado_enum, 'OMITIDO'::public.partida_paso_estado_enum]))) AS pasos_hechos
           FROM mes.partida_paso pp
          WHERE (pp.partida_id = p.id)) tot ON (true))
     LEFT JOIN LATERAL ( SELECT pp.id AS paso_id,
            pp.secuencia,
            pp.operacion_id,
            pp.estado AS estado_paso,
            pp.tiempo_estandar,
            pe.id AS ejecucion_id,
            pe.maquina_id,
            (NOT (EXISTS ( SELECT 1
                   FROM mes.partida_paso prev
                  WHERE ((prev.partida_id = pp.partida_id) AND (prev.secuencia < pp.secuencia) AND (prev.estado <> ALL (ARRAY['COMPLETADO'::public.partida_paso_estado_enum, 'OMITIDO'::public.partida_paso_estado_enum])))))) AS listo,
                CASE
                    WHEN (pp.estado = 'EN_PROCESO'::public.partida_paso_estado_enum) THEN pe.fyh_inicio
                    ELSE COALESCE(( SELECT max(pe2.fyh_fin) AS max
                       FROM (mes.partida_paso prev
                         JOIN mes.partida_paso_ejecucion pe2 ON ((pe2.partida_paso_id = prev.id)))
                      WHERE ((prev.partida_id = pp.partida_id) AND (prev.secuencia < pp.secuencia) AND (prev.estado = ANY (ARRAY['COMPLETADO'::public.partida_paso_estado_enum, 'OMITIDO'::public.partida_paso_estado_enum])))), p.fyh_programacion, p.fyh_cre)
                END AS desde
           FROM (mes.partida_paso pp
             LEFT JOIN LATERAL ( SELECT partida_paso_ejecucion.id,
                    partida_paso_ejecucion.maquina_id,
                    partida_paso_ejecucion.fyh_inicio
                   FROM mes.partida_paso_ejecucion
                  WHERE (partida_paso_ejecucion.partida_paso_id = pp.id)
                  ORDER BY partida_paso_ejecucion.fyh_inicio DESC NULLS LAST
                 LIMIT 1) pe ON (true))
          WHERE ((pp.partida_id = p.id) AND (pp.estado = ANY (ARRAY['PENDIENTE'::public.partida_paso_estado_enum, 'EN_PROCESO'::public.partida_paso_estado_enum])))
          ORDER BY
                CASE
                    WHEN (pp.estado = 'EN_PROCESO'::public.partida_paso_estado_enum) THEN 0
                    ELSE 1
                END, pp.secuencia
         LIMIT 1) cur ON (true))
     LEFT JOIN mes.operacion o ON ((o.id = cur.operacion_id)))
     LEFT JOIN mes.maquina m ON ((m.id = cur.maquina_id)))
  WHERE (p.estado_produccion = ANY (ARRAY['PROGRAMADA'::public.partida_estado_produccion_enum, 'EN_PRODUCCION'::public.partida_estado_produccion_enum]));


ALTER VIEW mes.vw_wip OWNER TO postgres;

