 SELECT cc.id,
    col.color,
    cli.cliente AS tono
   FROM ((public.color_x_cliente cc
     LEFT JOIN public.color col ON ((col.id = cc.color_id)))
     LEFT JOIN public.cliente cli ON ((cli.id = cc.cliente_id)));


